    /**
     * May-2026 — single source of truth for "what counts as a FRESH
     * rider GPS reading" when picking the origin for Qurbani route
     * planning. Used by Auto Route, Dispatch (Start), the manager-
     * side Refresh ETA, and any other path that needs to decide
     * "rider GPS or warehouse?".
     *
     * 10 minutes balances two competing concerns:
     *   - LocationHeartbeat fires every ~5 min. A rider with the
     *     app open and GPS working will always have a reading
     *     within the last cycle, so they pass the gate.
     *   - A rider whose phone has been backgrounded / signal dropped
     *     for >10 min has likely moved enough that their last
     *     reading is no longer the right origin — fall back to
     *     the configured warehouse instead.
     *
     * The mid-run refresh-self path uses a tighter 5-min window
     * (see dispatchQurbaniRoute) because that path is supposed to
     * reflect the rider's current position right now, not "last
     * known".
     */
    public const QURBANI_FRESH_GPS_MINUTES = 10;

    /**
     * Parse coordinates from a Google Maps URL
     * Handles various URL formats:
     * - https://www.google.com/maps?q=33.6844,73.0479
     * - https://maps.google.com/?ll=33.6844,73.0479
     * - https://www.google.com/maps/place/.../@33.6844,73.0479,15z
     * - https://www.google.com/maps/@33.6844,73.0479,15z
     * 
     * @param string|null $url The Google Maps URL
     * @return array|null ['latitude' => float, 'longitude' => float] or null if parsing fails
     */
    public function parseCoordinatesFromGoogleMapsUrl(?string $url): ?array
    {
        if (empty($url)) {
            return null;
        }
        $url = trim((string) $url);

        // Helper — sanity-check that a captured (lat,lng) pair looks like a
        // real geographic coordinate before returning it. Google Maps URLs
        // are full of "1234,5678" style data tokens that can match a naive
        // /(\d+),(\d+)/ regex and yield nonsense coords (e.g. -91, 200).
        $accept = function ($lat, $lng) {
            $lat = (float) $lat; $lng = (float) $lng;
            if ($lat == 0.0 && $lng == 0.0) return null; // null-island guard
            if ($lat < -90.0 || $lat > 90.0) return null;
            if ($lng < -180.0 || $lng > 180.0) return null;
            return ['latitude' => $lat, 'longitude' => $lng];
        };

        // Pattern 1: ?q=lat,lng / ?ll=lat,lng / &destination=lat,lng /
        // ?daddr=lat,lng — covers query-string variants used by classic
        // Maps, Directions deep links, and iOS Maps shares.
        if (preg_match('/[?&](?:q|ll|destination|daddr|saddr)=(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/i', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // Pattern 2: @lat,lng in URL path (map centre marker — present on
        // most desktop /maps/ URLs and shared "place" links).
        if (preg_match('/@(-?\d+\.\d+),(-?\d+\.\d+)/', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // Pattern 3: /place/lat,lng/
        if (preg_match('/\/place\/(-?\d+\.\d+),(-?\d+\.\d+)/', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // Pattern 4 (May-2026) — Google's "data" URI uses !3d<lat>!4d<lng>
        // to encode the *exact* user-dropped pin (the @lat,lng before it
        // is just the map viewport centre, which can be off by 100m+ on
        // zoom changes). Long share URLs straight from the Android Maps
        // app look like:
        //   https://www.google.com/maps/place/Foo/@33.68,73.04,17z/
        //     data=!3m1!4b1!4m6!3m5!1s0x...:0x...!7e2!8m2!3d33.6844!4d73.0479
        // Picking the !3d/!4d pair preserves the true dropped pin and is
        // strictly more accurate than the @lat,lng fallback.
        if (preg_match('/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // Pattern 5 (May-2026) — Directions deep link destination:
        //   https://www.google.com/maps/dir/?api=1&destination=lat,lng
        //   https://www.google.com/maps/dir//lat,lng/
        if (preg_match('/\/dir\/(?:[^\/]*\/)?(-?\d+\.\d+),(-?\d+\.\d+)/', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // Pattern 6 (May-2026) — bare coords in path (e.g. some shortened
        // share-sheet variants of /maps?q):  /maps/<lat>,<lng>
        if (preg_match('/\/maps\/(-?\d+\.\d+),(-?\d+\.\d+)(?:[\/,?]|$)/', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // Pattern 7 (Jul-2026) — the target a maps.app.goo.gl short link redirects to when the
        // rider shares a dropped pin:  /maps/search/24.791417,+46.651916?entry=tts
        // The '+' (or '%2C'/space) is a URL-encoded space Google inserts between "lat, lng".
        if (preg_match('#/(?:search|dir)/(-?\d+\.\d+),(?:\+|%2C|\s|%20)*(-?\d+\.\d+)#i', $url, $m)) {
            if ($r = $accept($m[1], $m[2])) return $r;
        }

        // NOTE — `maps.app.goo.gl` / `goo.gl/maps` short links cannot be
        // parsed in-process because the coords are only revealed after an
        // HTTP redirect chain. Resolution should happen at the time the
        // URL is saved (LocationService::saveVerifiedLocation already
        // expands short links to a long URL before storing it). If a
        // short link slipped through, the caller will see null here and
        // surface the dispatch warning so a human can re-save the pin.

        return null;
    }

    /**
     * Lightweight diagnostic — distinguishes "URL totally unparseable"
     * from "URL is a known short-link format we couldn't expand" so the
     * dispatch warning banner can show a more actionable message
     * (e.g. "re-share the pin so we can parse it" vs "unknown format").
     * Pure function, no I/O.
     */
    private function classifyUnparseableMapUrl(?string $url): ?string
    {
        if (empty($url)) return null;
        $u = strtolower(trim((string) $url));
        if (str_contains($u, 'maps.app.goo.gl') || str_contains($u, 'goo.gl/maps')) {
            return 'short_link_not_expanded';
        }
        if (str_contains($u, 'plus.codes/') || preg_match('/[23456789CFGHJMPQRVWX]{4,}\+[23456789CFGHJMPQRVWX]{2,}/', strtoupper($url))) {
            return 'plus_code';
        }
        if (str_contains($u, 'apple.com/maps') || str_contains($u, 'maps.apple.com')) {
            return 'apple_maps_share';
        }
        return 'unknown_format';
    }

    /**
     * Resolve a customer's effective dispatch coordinates (Phase E,
     * May-2026 fix for the "Nth order has no ETA" bug).
     *
     * Priority order:
     *   1. Saved pin (c.latitude / c.longitude) — the canonical source.
     *   2. Parse c.verified_location_url — covers legacy customers and
     *      Phase-3 location-request replies where the URL was saved
     *      but the lat/lng pin columns were never backfilled. Before
     *      this fallback, those bundles shipped cust_lat=NULL, which
     *      silently excluded them from the Google Directions waypoint
     *      list — manifesting as "the 5th order sometimes has no ETA".
     *
     * Returns ['lat' => ?float, 'lng' => ?float, 'source' => 'pin'|'url'|null].
     */
    private function resolveCustomerDispatchCoords($customer): array
    {
        if (!$customer) {
            return ['lat' => null, 'lng' => null, 'source' => null, 'reason' => 'no_customer'];
        }
        if (!empty($customer->latitude) && !empty($customer->longitude)) {
            return [
                'lat'    => (float) $customer->latitude,
                'lng'    => (float) $customer->longitude,
                'source' => 'pin',
                'reason' => null,
            ];
        }
        if (!empty($customer->verified_location_url)) {
            $parsed = $this->parseCoordinatesFromGoogleMapsUrl($customer->verified_location_url);
            if ($parsed && isset($parsed['latitude'], $parsed['longitude'])) {
                return [
                    'lat'    => (float) $parsed['latitude'],
                    'lng'    => (float) $parsed['longitude'],
                    'source' => 'url',
                    'reason' => null,
                ];
            }
            // May-2026 — URL exists but our parser couldn't extract a
            // lat/lng pair. Surface a diagnostic reason so the mobile
            // warning banner can tell the rider exactly what went wrong
            // (e.g. a maps.app.goo.gl short link the original capture
            // never expanded) instead of the generic "missing coords".
            return [
                'lat'    => null,
                'lng'    => null,
                'source' => null,
                'reason' => $this->classifyUnparseableMapUrl($customer->verified_location_url) ?: 'url_unparseable',
            ];
        }
        return ['lat' => null, 'lng' => null, 'source' => null, 'reason' => 'no_pin_no_url'];
    }

    /**
     * Get dashboard summary for logged-in rider
     * Returns: order counts, ledger balance, pending requests, attendance status
     */
    public function dashboard(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Get order counts for this rider
            $excludedStatuses = ['delivered', 'completed', 'cancelled', 'refunded'];
            
            $orderCounts = DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $user->id)
                ->whereNotIn('order_status', $excludedStatuses)
                ->select([
                    DB::raw('COUNT(*) as total_orders'),
                    DB::raw('SUM(CASE WHEN order_status = "ready_for_delivery" THEN 1 ELSE 0 END) as ready_for_delivery'),
                    DB::raw('SUM(CASE WHEN order_status = "pending" THEN 1 ELSE 0 END) as pending'),
                    DB::raw('SUM(CASE WHEN order_status = "processing" THEN 1 ELSE 0 END) as processing')
                ])
                ->first();

            // Get ledger balance
            $ledgerBalance = DB::table('t_fin_employee_cash_txn')
                ->where('rider_user_id', $user->id)
                ->select([
                    DB::raw('SUM(CASE WHEN txn_type = "debit" THEN amount ELSE 0 END) as total_debit'),
                    DB::raw('SUM(CASE WHEN txn_type = "credit" THEN amount ELSE 0 END) as total_credit')
                ])
                ->first();

            $balance = ($ledgerBalance->total_debit ?? 0) - ($ledgerBalance->total_credit ?? 0);

            // Get pending requests count
            $pendingRequests = DB::table('t_fin_request')
                ->where('requested_by', $user->id)
                ->where('status', 'pending')
                ->count();

            // Get today's attendance
            $today = now()->format('Y-m-d');
            $attendance = DB::table('t_hr_attendance')
                ->where('user_id', $user->id)
                ->whereDate('attendance_date', $today)
                ->select('check_in_time', 'check_out_time', 'status')
                ->first();

            return response()->json([
                'success' => true,
                'data' => [
                    'user' => [
                        'id' => $user->id,
                        'fullname' => $user->fullname,
                        'email' => $user->email,
                    ],
                    'orders' => [
                        'total' => $orderCounts->total_orders ?? 0,
                        'ready_for_delivery' => $orderCounts->ready_for_delivery ?? 0,
                        'pending' => $orderCounts->pending ?? 0,
                        'processing' => $orderCounts->processing ?? 0,
                    ],
                    'ledger' => [
                        'balance' => $balance,
                        'balance_formatted' => 'Rs. ' . number_format(abs($balance), 2),
                        'balance_type' => $balance >= 0 ? 'debit' : 'credit',
                    ],
                    'requests' => [
                        'pending_count' => $pendingRequests,
                    ],
                    'attendance' => [
                        'today' => $today,
                        'checked_in' => $attendance ? ($attendance->check_in_time !== null) : false,
                        'checked_out' => $attendance ? ($attendance->check_out_time !== null) : false,
                        'check_in_time' => $attendance->check_in_time ?? null,
                        'check_out_time' => $attendance->check_out_time ?? null,
                        'status' => $attendance->status ?? 'absent',
                    ],
                ],
            ]);
        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to load dashboard: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Get detailed information for a specific order
     * Riders can only view their own assigned orders
     */
    public function getOrderDetails(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            // Fetch order with relationships
            $order = \App\Models\CRM\OrderModel::with([
                'customer',
                'lineItems',
                'discounts',
                'statusHistory' => function($q) {
                    $q->orderBy('changed_at', 'desc');
                }
            ])->find($id);

            if (!$order) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found',
                ], 404);
            }

            // Check if rider is assigned to this order
            if ($order->assigned_rider_user_id != $user->id) {
                return response()->json([
                    'success' => false,
                    'message' => 'You are not authorized to view this order',
                ], 403);
            }

            // Format line items
            $lineItems = $order->lineItems->map(function($item) {
                return [
                    'id' => $item->id,
                    'product_name' => $item->name ?? 'N/A',
                    'variant_name' => $item->sku ?? '',
                    'quantity' => $item->quantity,
                    'unit_price' => $item->unit_price,
                    'unit_price_formatted' => 'Rs. ' . number_format($item->unit_price, 0),
                    'total' => $item->line_total,
                    'total_formatted' => $item->is_free ? 'FREE' : 'Rs. ' . number_format($item->line_total, 0),
                    'preparation_status' => $item->preparation_status,
                    'is_free' => (bool) $item->is_free,
                    'qurbani_day' => $item->qurbani_day,
                    'qurbani_slot' => $item->qurbani_slot,
                    'qurbani_region' => $item->qurbani_region,
                    'qurbani_delivery_type' => $item->qurbani_delivery_type,
                    'qurbani_type' => $item->qurbani_type,
                    'qurbani_paya' => $item->qurbani_paya,
                    'instructions' => $item->instructions,
                ];
            });
            
            // Calculate preparation summary
            $totalItems = $lineItems->count();
            $preparingCount = $lineItems->where('preparation_status', 'preparing')->count();

            // Format status history
            $statusHistory = $order->statusHistory->map(function($history) {
                return [
                    'status_code' => $history->status_code,
                    'status_display' => ucwords(str_replace(['_', '-'], ' ', $history->status_code)),
                    'changed_at' => $history->changed_at,
                    'changed_by' => $history->changed_by,
                    'notes' => $history->notes,
                ];
            });

            $paymentMethod = strtolower($order->payment_method ?? 'cash');
            $isCash = in_array($paymentMethod, ['cash', 'cash_on_delivery', 'cod']);

            // Get delivery location if order is delivered
            $deliveryLocation = null;
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                $deliveryHistory = \DB::table('t_crm_order_status_history')
                    ->where('order_id', $order->id)
                    ->where('status_code', 'delivered')
                    ->where('is_current', 1)
                    ->select('delivery_latitude', 'delivery_longitude', 'changed_at')
                    ->first();
                
                if ($deliveryHistory && $deliveryHistory->delivery_latitude && $deliveryHistory->delivery_longitude) {
                    $deliveryLocation = [
                        'latitude' => (float)$deliveryHistory->delivery_latitude,
                        'longitude' => (float)$deliveryHistory->delivery_longitude,
                        'delivered_at' => $deliveryHistory->changed_at,
                        'google_maps_url' => "https://www.google.com/maps?q={$deliveryHistory->delivery_latitude},{$deliveryHistory->delivery_longitude}"
                    ];
                }
            }

            // Format discounts (for invoice calculation)
            $discounts = $order->discounts ? $order->discounts->map(function($discount) {
                return [
                    'discount_amount' => $discount->discount_amount,
                    'discount_type' => $discount->discount_type,
                    // Lets the mobile invoice separate the customer's own account
                    // balance from a real discount instead of printing it as one.
                    'coupon_code' => $discount->coupon_code,
                    'discount_title' => $discount->discount_title,
                ];
            })->toArray() : [];

            // Generate invoice URLs
            $invoiceImageUrl = route('orders.invoice.pdf', ['id' => $order->id, 'download_image' => 1]);
            $invoicePdfUrl = route('orders.invoice.pdf', ['id' => $order->id, 'force_pdf' => 1]);

            // ⭐ Payment proof (E3a — so the rider sees "payment received" before he
            // knocks) + WhatsApp-reachability + first-order flags (E2 — so the UI can
            // show a warning chip and know whether conversion will be blocked). Both
            // non-fatal: a lookup error must not break order details.
            $paymentProof = null;
            try {
                if (config('payment_signals.enabled')) {
                    $ppMap = app(\App\Services\Payments\Signals\PaymentProofStatusService::class)
                        ->forOrders([$order->id], suppressSettled: false);
                    $paymentProof = $ppMap[$order->id] ?? null;
                }
            } catch (\Throwable $ppErr) {
                $paymentProof = null;
            }

            $customerWaInvalid = false;
            $isFirstOrder = false;
            try {
                $cust = $order->customer;
                if ($cust && !$cust->isShop()) {
                    $isFirstOrder = \App\Models\CRM\OrderModel::where('customer_id', $order->customer_id)->count() <= 1;
                    $dialPhone = $cust->phone_normalized ?: ($cust->phone_original ?: $order->address_phone);
                    $customerWaInvalid = app(\App\Services\WhatsAppService::class)->isNumberUndeliverable($dialPhone);
                }
            } catch (\Throwable $waErr) {
                // non-fatal
            }

            return response()->json([
                'success' => true,
                'order' => [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'order_status' => $order->order_status,
                    // 🚚 Van custody (Sep-2026) — see vanBlockFor. The page had no
                    //    way to know a box was still on a van, so it offered the
                    //    delivery scanner at the meet-up (Arslan, Sep-3).
                    'van' => $this->vanBlockFor($order),
                    'status_display' => ucwords(str_replace(['_', '-'], ' ', $order->order_status)),
                    'order_date' => $order->order_date,
                    'delivery_date' => $order->delivery_date,
                    'payment_method' => $order->payment_method,
                    'payment_type' => $isCash ? 'cash' : 'online',
                    'payment_label' => $isCash ? 'Cash' : 'Online',
                    'payment_proof' => $paymentProof, // E3a: WhatsApp/bank proof status or null
                    'customer_wa_invalid' => $customerWaInvalid, // E2: number can't receive WhatsApp
                    'is_first_order' => $isFirstOrder, // E2: first order → rider online-conversion may be blocked
                    'customer' => [
                        'id' => $order->customer->id ?? null,
                        'name' => $order->customer ? trim($order->customer->first_name . ' ' . $order->customer->last_name) : 'N/A',
                        'phone' => $order->customer->phone_original ?? $order->customer->phone ?? '',
                        'email' => $order->customer->email ?? '',
                        'address' => $order->customer->address1 ?? '',
                        'address1' => $order->customer->address1 ?? '',
                        'address2' => $order->customer->address2 ?? '',
                        'city' => $order->customer->city ?? '',
                        'province' => $order->customer->province ?? '',
                        'postal_code' => $order->customer->postal_code ?? '',
                        'verified_location' => ($order->customer && ($order->customer->verified_location_url || ($order->customer->latitude && $order->customer->longitude))) ? [
                            'latitude' => $order->customer->latitude ? (float)$order->customer->latitude : null,
                            'longitude' => $order->customer->longitude ? (float)$order->customer->longitude : null,
                            'url' => $order->customer->verified_location_url ?? null,
                            'google_maps_url' => $order->customer->verified_location_url ?: ($order->customer->latitude && $order->customer->longitude ? "https://www.google.com/maps?q={$order->customer->latitude},{$order->customer->longitude}" : null),
                            'saved_by' => \App\Models\CRM\CustomerModel::verifierLabel($order->customer->verified_location_saved_by),
                            'saved_at' => $order->customer->verified_location_saved_at,
                            // Verified-pin lock: initial state for the rider UI
                            // (kept fresh afterwards by the live-flags poll).
                            'pin_locked' => $order->customer->isVerifiedPinLocked(),
                            'pin_unlock_until' => $order->customer->verifiedPinUnlockActive()
                                ? $order->customer->verified_pin_unlocked_until->toIso8601String() : null,
                            // Seeds the "Store notified" state before the first poll lands.
                            'pin_unlock_requested' => $order->customer->verifiedPinUnlockRequestActive(),
                        ] : null,
                    ],
                    'amounts' => [
                        'subtotal' => $order->subtotal_price,
                        'discount' => $order->discount_total,
                        'shipping' => $order->shipping_total,
                        'total' => $order->total_price,
                        'subtotal_formatted' => 'Rs. ' . number_format($order->subtotal_price, 0),
                        'discount_formatted' => 'Rs. ' . number_format($order->discount_total, 0),
                        'shipping_formatted' => 'Rs. ' . number_format($order->shipping_total, 0),
                        'total_formatted' => 'Rs. ' . number_format($order->total_price, 0),
                    ],
                    'shipping_total' => $order->shipping_total ?? 0,
                    'tip_amount' => $order->tip_amount ?? 0,
                    'total_price' => $order->total_price,
                    'discounts' => $discounts,
                    // ⭐ Order note - specific to this order
                    'notes' => $order->note,
                    'order_note' => $order->note,
                    'has_order_note' => !empty($order->note),
                    // ⭐ Customer notes - use primary customer notes if order linked to merged duplicate
                    'customer_notes' => $order->customer ? (
                        $order->customer->merged_into_customer_id
                            ? (\App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id)?->notes ?? null)
                            : ($order->customer->notes ?? null)
                    ) : null,
                    'has_customer_notes' => $order->customer && !empty(
                        $order->customer->merged_into_customer_id
                            ? (\App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id)?->notes ?? null)
                            : ($order->customer->notes ?? null)
                    ),
                    'expected_packets' => $order->expected_packets, // Number of packets expected (from manager)
                    'actual_packets' => $order->actual_packets,     // Number of packets delivered (from rider)
                    // Enh-2: dispatch hand-over scan audit (who marked this order ready to leave, when).
                    // Safe before the SQL migration runs: missing columns read as null on the Eloquent model.
                    'dispatch_scanned_at' => $order->dispatch_scanned_at,
                    'dispatch_scanned_by_name' => $order->dispatch_scanned_by
                        ? (\DB::table('t_sys_user')->where('id', $order->dispatch_scanned_by)->value('fullname') ?: null)
                        : null,
                    // Delivery-scan audit (proof the rider scanned at delivery + when). Same safe-null rule.
                    'delivery_scanned_at' => $order->delivery_scanned_at,
                    'delivery_scanned_by_name' => $order->delivery_scanned_by
                        ? (\DB::table('t_sys_user')->where('id', $order->delivery_scanned_by)->value('fullname') ?: null)
                        : null,
                    'delivery_location' => $deliveryLocation,       // GPS coordinates of delivery (if delivered)
                    'online_message_sent_at' => $order->online_message_sent_at,  // WhatsApp message sent timestamp
                    'online_message_sent_by' => $order->online_message_sent_by,  // Who sent the message
                    'invoice' => [
                        'image_url' => $invoiceImageUrl,  // URL to download invoice as PNG image
                        'pdf_url' => $invoicePdfUrl,      // URL to download invoice as PDF
                    ],
                    'line_items' => $lineItems,
                    'preparation_summary' => [
                        'preparing_count' => $preparingCount,
                        'total_items' => $totalItems,
                    ],
                    'status_history' => $statusHistory,
                    'qurbani_day' => $order->qurbani_day,
                    'qurbani_slot' => $order->qurbani_slot,
                    'qurbani_region' => $order->qurbani_region,
                    'qurbani_delivery_type' => $order->qurbani_delivery_type,
                    'is_qurbani' => !empty($order->qurbani_day) || !empty($order->qurbani_slot) || !empty($order->qurbani_region) || !empty($order->qurbani_delivery_type) || $order->hasQurbaniItems() || $order->lineItems->contains(function($li) { return !empty($li->qurbani_day) || !empty($li->qurbani_slot) || !empty($li->qurbani_region) || !empty($li->qurbani_delivery_type); }),
                    'total_paid' => (float)($order->total_paid ?? 0),
                    'payment_status' => $order->payment_status ?? 'unpaid',
                    'balance_remaining' => max(0, (float)$order->total_price - (float)($order->total_paid ?? 0)),
                    // Fully computed PAID stamp — shared source of truth for
                    // the mobile InvoiceTemplate. Uses the exact same rules
                    // as the server-side blade partial (getPaidStampData),
                    // so mobile doesn't need to duplicate the cash/online
                    // bank fallback logic.
                    'paid_stamp' => $order->getPaidStampData(),
                    'qurbani_rider_delivered_enabled' => \App\Models\FIN\ConfigModel::get('qurbani_rider_delivered_enabled', '0') === '1',
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get order details', [
                'order_id' => $id,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load order details: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Resolve a shortened Google Maps URL to get the final URL with coordinates
     * Follows redirects for goo.gl, maps.app.goo.gl, etc.
     * 
     * @param string $url The potentially shortened URL
     * @return string The resolved URL (or original if resolution fails)
     */
    public function resolveGoogleMapsUrl(string $url): string
    {
        // Check if this is a shortened URL that needs resolution
        $shortenedDomains = ['goo.gl', 'maps.app.goo.gl', 'g.co', 'maps.google.com/goo.gl'];
        $needsResolution = false;
        
        foreach ($shortenedDomains as $domain) {
            if (stripos($url, $domain) !== false) {
                $needsResolution = true;
                break;
            }
        }
        
        if (!$needsResolution) {
            return $url;
        }
        
        try {
            // Use cURL to follow redirects and get final URL
            $ch = curl_init($url);
            curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_HEADER, false);
            curl_setopt($ch, CURLOPT_TIMEOUT, 10);
            curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
            curl_setopt($ch, CURLOPT_USERAGENT, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36');
            
            curl_exec($ch);
            $finalUrl = curl_getinfo($ch, CURLINFO_EFFECTIVE_URL);
            $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            curl_close($ch);
            
            if ($httpCode >= 200 && $httpCode < 400 && !empty($finalUrl)) {
                \Log::info('Resolved shortened Google Maps URL', [
                    'original' => $url,
                    'resolved' => $finalUrl,
                ]);
                return $finalUrl;
            }
        } catch (\Exception $e) {
            \Log::warning('Failed to resolve shortened URL', [
                'url' => $url,
                'error' => $e->getMessage(),
            ]);
        }
        
        return $url;
    }

    /**
     * The verified-pin lock binds RIDERS only. Store/web users edit freely — they
     * are the ones who grant unlocks. A rider is any mobile user WITHOUT
     * access_store_mode. No identity → treat as bound (safest).
     */
    private function riderPinBindApplies($user): bool
    {
        if (!$user) {
            return true;
        }
        return !$user->hasMobilePermission('access_store_mode');
    }

    /**
     * Set verified location for a customer
     * Accepts either coordinates OR Google Maps URL
     * For shortened URLs (goo.gl, maps.app.goo.gl), automatically resolves and extracts coordinates
     */
    public function setCustomerVerifiedLocation(Request $request, $customerId)
    {
        try {
            $validated = $request->validate([
                'latitude' => 'nullable|numeric|between:-90,90',
                'longitude' => 'nullable|numeric|between:-180,180',
                'url' => 'nullable|string|max:500',
                // Aug-2026 — where in the app this save was made from, so the pin
                // history reads "saved from the customer's chat pin" instead of a
                // flat "store app". Descriptive only; never changes what is saved
                // and never affects the pin lock.
                'context' => 'nullable|string|max:30',
            ]);

            // Must provide either coordinates OR URL
            if (empty($validated['latitude']) && empty($validated['longitude']) && empty($validated['url'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Please provide either coordinates or a Google Maps URL'
                ], 400);
            }

            $customer = \App\Models\CRM\CustomerModel::find($customerId);

            if (!$customer) {
                return response()->json([
                    'success' => false,
                    'message' => 'Customer not found',
                ], 404);
            }

            // Verified-pin lock: a rider may not overwrite an existing pin unless
            // a store/web user has granted a live unlock window. Store/web users
            // are never bound (they ARE the unlockers); a first-ever pin is never
            // locked. See DISPATCH-F1-F2-F3-COORDINATION-JUL2026.md.
            $isBoundRider = $this->riderPinBindApplies(Auth::user());
            if ($isBoundRider && $customer->isVerifiedPinLocked()) {
                // The refusal itself raises the request, so the store sees a
                // banner without the rider phoning anyone — and it works even on
                // an APK too old to know about this feature.
                $requested = \App\Services\Location\PinUnlockRequestService::raise(
                    $customer,
                    Auth::id(),
                    $request->input('order_id')
                );

                return response()->json([
                    'success' => false,
                    'message' => $requested
                        ? "This customer's location is locked. The store has been asked to unlock it — you'll be able to save as soon as they do."
                        : "This customer's location is locked. Ask the store to unlock it before changing the pin.",
                    'pin_locked' => true,
                    'unlock_requested' => $requested,
                ], 423);
            }

            // Prepare update data. A RIDER's save CONSUMES any unlock grant, so
            // the pin re-locks immediately and a granted-but-unused window never
            // lingers past the one edit it was for. A STORE/WEB save instead
            // leaves the 24h grace window open, so the rider who reaches the
            // door can correct a temporary pin without phoning for an unlock.
            $updateData = array_merge([
                'updated_by' => Auth::id(),
                'verified_location_saved_by' => Auth::id(),
                'verified_location_saved_at' => now(),
            ], $isBoundRider
                ? \App\Models\CRM\CustomerModel::pinGrantConsumed()
                : \App\Models\CRM\CustomerModel::pinGrantGrace(
                    $customer->verified_pin_unlocked_until,
                    $customer->verified_pin_unlocked_by,
                    Auth::id()
                ));
            
            // Track where the pin's coordinates came from, so the response can
            // warn when they're approximate (geocoded) or missing entirely.
            $coordsSource = null; // 'url' | 'geocoded' | 'none'

            if (!empty($validated['url'])) {
                // URL provided - resolve if shortened and extract coordinates
                $originalUrl = $validated['url'];
                $resolvedUrl = $this->resolveGoogleMapsUrl($originalUrl);

                // May-2026 fix — previously this stored $originalUrl
                // even when the URL was a maps.app.goo.gl short link
                // that resolveGoogleMapsUrl had already expanded. The
                // bundle loader's per-request parser
                // (parseCoordinatesFromGoogleMapsUrl) cannot follow
                // redirects in-process, so those rows shipped with
                // verified_location_url set + lat/lng NULL —
                // manifesting as the rider's "Verified Pin" badge
                // showing AT THE SAME TIME as the missing-coords
                // warning (Waseem Aslam case).
                //
                // Storing the resolved long URL when we have one
                // keeps the badge meaningful AND lets every
                // downstream parser succeed without a network round
                // trip. We fall back to the original URL only when
                // resolution didn't change anything (already long).
                // Length-safe URL: a resolved Google "ftid" share link can blow
                // past the column ("Data too long for verified_location_url" hit
                // prod, Jul-19). Keep the resolved URL when it fits; otherwise
                // store the short original — it re-resolves and stays openable.
                $urlToStore = (!empty($resolvedUrl) && mb_strlen($resolvedUrl) <= 480)
                    ? $resolvedUrl : $originalUrl;
                $updateData['verified_location_url'] = $urlToStore;

                // Try to parse coordinates from the resolved URL
                $parsedCoords = $this->parseCoordinatesFromGoogleMapsUrl($resolvedUrl);

                if ($parsedCoords) {
                    // Successfully extracted coordinates - save them too!
                    $updateData['latitude'] = $parsedCoords['latitude'];
                    $updateData['longitude'] = $parsedCoords['longitude'];
                    $coordsSource = 'url';

                    \Log::info('Setting verified location from URL with extracted coordinates', [
                        'customer_id' => $customerId,
                        'original_url' => $originalUrl,
                        'resolved_url' => $resolvedUrl,
                        'stored_url'   => $urlToStore,
                        'latitude'  => $parsedCoords['latitude'],
                        'longitude' => $parsedCoords['longitude'],
                        'saved_by'  => Auth::user()->fullname,
                    ]);
                } else {
                    // Geocode-on-save fallback: the URL had no coordinates (an
                    // address / ftid share link). Geocode the address text so the
                    // pin is never saved coord-less — a coord-less "verified"
                    // customer is invisible to every distance report AND to the
                    // pin lock (Ahmed Mujtaba / SH-21269, Jul-19).
                    $geo = \App\Services\GeocodingService::geocodeFromMapsUrl($resolvedUrl)
                        ?: \App\Services\GeocodingService::geocodeFromMapsUrl($originalUrl);
                    if ($geo) {
                        $updateData['latitude'] = $geo['latitude'];
                        $updateData['longitude'] = $geo['longitude'];
                        $coordsSource = 'geocoded';
                        \Log::info('Verified location URL had no coords — geocoded the address instead (approximate)', [
                            'customer_id'  => $customerId,
                            'resolved_url' => $resolvedUrl,
                            'latitude'     => $geo['latitude'],
                            'longitude'    => $geo['longitude'],
                            'saved_by'     => Auth::user()->fullname,
                        ]);
                    } else {
                        $coordsSource = 'none';
                        \Log::warning('Setting verified location URL but COORDS NOT EXTRACTED and geocode failed — customer has NO pin coords', [
                            'customer_id' => $customerId,
                            'url'         => $originalUrl,
                            'resolved_url'=> $resolvedUrl,
                            'stored_url'  => $urlToStore,
                            'saved_by'    => Auth::user()->fullname,
                        ]);
                    }
                }
            }
            
            if (!empty($validated['latitude']) && !empty($validated['longitude'])) {
                // Coordinates provided directly - store them (overrides URL-extracted coords)
                $updateData['latitude'] = $validated['latitude'];
                $updateData['longitude'] = $validated['longitude'];
                $coordsSource = 'url'; // an explicit dropped pin is precise

                // If no URL was provided in this request, clear the old URL
                // This ensures "View Location" shows the new pin location, not the old URL
                if (empty($validated['url'])) {
                    $updateData['verified_location_url'] = null;
                }

                \Log::info('Setting verified location coordinates for customer', [
                    'customer_id' => $customerId,
                    'latitude' => $validated['latitude'],
                    'longitude' => $validated['longitude'],
                    'cleared_old_url' => empty($validated['url']),
                    'saved_by' => Auth::user()->fullname,
                ]);
            }

            // Capture the pre-write pin so the change is auditable — a
            // mis-dropped pin is exactly what once turned a 15-min drive into
            // an hour-long ETA, and today the old value is silently overwritten.
            $oldPinLat = $customer->latitude;
            $oldPinLng = $customer->longitude;

            // Update customer
            $customer->update($updateData);

            \App\Services\AuditLogger::logCustomerPinChange(
                $customer->id,
                trim(($customer->first_name ?? '') . ' ' . ($customer->last_name ?? '')),
                $oldPinLat, $oldPinLng,
                $customer->latitude, $customer->longitude,
                // Name WHICH mobile hand did this. Both surfaces are 'mobile' to
                // detectSource(), but "the rider standing at the door", "the store
                // correcting it from the office" and "someone took the pin the
                // customer sent in chat" are different claims about how
                // trustworthy the pin is.
                match ((string) ($validated['context'] ?? '')) {
                    'chat_pin'  => "Saved from the customer's pin in the chat",
                    'chat_link' => "Saved from the customer's map link in the chat",
                    default     => $isBoundRider
                        ? 'Verified pin dropped by the rider at the door'
                        : 'Verified pin dropped in the store app',
                }
            );

            // The pin moved, so the delivery region must follow it. Without this
            // the region stays whatever it was first guessed at (often a Google
            // city-centre geocode) for the life of the customer, and region-based
            // rider auto-assign keeps routing the order to the wrong rider.
            \App\Services\RegionDetectionService::refreshAfterPinSave($customer->id);

            // Warn when the pin's coordinates are approximate (geocoded from the
            // address) or missing (link had none and geocode failed) — so staff
            // know to drop an exact pin instead of trusting a coord-less save.
            $approximate   = $coordsSource === 'geocoded';
            $coordsMissing = $coordsSource === 'none';
            $message = $coordsMissing
                ? "Saved the link, but we couldn't read an exact location from it. Please drop the pin on the map so riders and reports have precise coordinates."
                : ($approximate
                    ? 'Saved — but from the address (approximate), because the link had no exact pin. For precise delivery, drop the pin on the map.'
                    : 'Verified location saved successfully');

            return response()->json([
                'success'        => true,
                'message'        => $message,
                'coords_source'  => $coordsSource,
                'approximate'    => $approximate,
                'coords_missing' => $coordsMissing,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Invalid location data',
                'errors' => $e->errors(),
            ], 422);
        } catch (\Exception $e) {
            \Log::error('Failed to set customer verified location', [
                'customer_id' => $customerId,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to save location: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * ⭐ Get ETA and distance from rider to destination
     * Uses Google Maps Directions API with fallback to OpenRouteService
     * Includes smart usage tracking to stay within free tier limits
     * 
     * @param Request $request - origin_lat, origin_lng, dest_lat, dest_lng
     * @return JSON with distance_km, duration_minutes, duration_text, source
     */
    public function getEtaToDestination(Request $request)
    {
        try {
            $validated = $request->validate([
                'origin_lat' => 'required|numeric|between:-90,90',
                'origin_lng' => 'required|numeric|between:-180,180',
                'dest_lat' => 'required|numeric|between:-90,90',
                'dest_lng' => 'required|numeric|between:-180,180',
            ]);
            
            $originLat = $validated['origin_lat'];
            $originLng = $validated['origin_lng'];
            $destLat = $validated['dest_lat'];
            $destLng = $validated['dest_lng'];
            
            // Check cache first (5-minute cache based on rounded coordinates)
            $cacheKey = sprintf(
                'eta_%s_%s_%s_%s',
                round($originLat, 3), round($originLng, 3),
                round($destLat, 3), round($destLng, 3)
            );
            
            $cached = \Cache::get($cacheKey);
            if ($cached) {
                return response()->json([
                    'success' => true,
                    'cached' => true,
                    ...$cached
                ]);
            }
            
            // Try Google Maps first (if within monthly limit)
            $result = $this->getEtaFromGoogleMaps($originLat, $originLng, $destLat, $destLng);
            
            // If Google failed or limit reached, try OpenRouteService
            if (!$result) {
                $result = $this->getEtaFromOpenRouteService($originLat, $originLng, $destLat, $destLng);
            }
            
            // If both failed, calculate straight-line estimate
            if (!$result) {
                $straightLineKm = $this->haversineDistance($originLat, $originLng, $destLat, $destLng) / 1000;
                // Rough estimate: 30 km/h average speed in city
                $estimatedMinutes = round(($straightLineKm / 30) * 60);
                
                $result = [
                    'distance_km' => round($straightLineKm, 1),
                    'distance_text' => round($straightLineKm, 1) . ' km',
                    'duration_minutes' => $estimatedMinutes,
                    'duration_text' => $estimatedMinutes . ' min',
                    'source' => 'estimate',
                    'traffic' => null,
                ];
            }
            
            // Cache result for 5 minutes
            \Cache::put($cacheKey, $result, now()->addMinutes(5));
            
            return response()->json([
                'success' => true,
                'cached' => false,
                ...$result
            ]);
            
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Invalid coordinates',
                'errors' => $e->errors(),
            ], 422);
        } catch (\Exception $e) {
            \Log::error('ETA calculation failed', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            return response()->json([
                'success' => false,
                'message' => 'Failed to calculate ETA',
            ], 500);
        }
    }
    
    /**
     * Get current API usage stats for monitoring
     */
    public function getApiUsageStats()
    {
        $monthKey = date('Y-m');
        
        $stats = \DB::table('t_sys_api_usage')
            ->where('month_key', $monthKey)
            ->get()
            ->keyBy('api_name');
        
        $googleUsage = $stats->get('google_directions');
        $openRouteUsage = $stats->get('openroute_directions');
        
        return response()->json([
            'success' => true,
            'month' => $monthKey,
            'google_directions' => [
                'calls' => $googleUsage->call_count ?? 0,
                'limit' => 10000,
                'remaining' => 10000 - ($googleUsage->call_count ?? 0),
                'at_limit' => ($googleUsage->call_count ?? 0) >= 10000,
            ],
            'openroute_directions' => [
                'calls' => $openRouteUsage->call_count ?? 0,
                'daily_limit' => 2000,
            ],
        ]);
    }
    
    /**
     * Get ETA from Google Maps Directions API
     * Tracks usage and returns null if monthly limit reached
     */
    private function getEtaFromGoogleMaps($originLat, $originLng, $destLat, $destLng): ?array
    {
        // Check monthly usage limit
        $monthKey = date('Y-m');
        $usage = \DB::table('t_sys_api_usage')
            ->where('api_name', 'google_directions')
            ->where('month_key', $monthKey)
            ->first();
        
        $currentCount = $usage->call_count ?? 0;
        if ($currentCount >= 10000) {
            \Log::warning('Google Maps API monthly limit reached', [
                'month' => $monthKey,
                'count' => $currentCount,
            ]);
            return null;
        }
        
        $apiKey = config('services.google_maps.directions_key');
        if (empty($apiKey)) {
            \Log::warning('Google Maps API key not configured');
            return null;
        }
        
        try {
            $client = new \GuzzleHttp\Client(['timeout' => 10]);
            
            $response = $client->get('https://maps.googleapis.com/maps/api/directions/json', [
                'query' => [
                    'origin' => "{$originLat},{$originLng}",
                    'destination' => "{$destLat},{$destLng}",
                    'mode' => 'driving',
                    'departure_time' => 'now', // For traffic data
                    'key' => $apiKey,
                ]
            ]);
            
            $data = json_decode($response->getBody()->getContents(), true);
            
            // Increment usage counter
            $this->incrementApiUsage('google_directions');
            
            if ($data['status'] !== 'OK' || empty($data['routes'])) {
                \Log::warning('Google Maps API error', ['status' => $data['status']]);
                return null;
            }
            
            $route = $data['routes'][0]['legs'][0];
            
            // Use duration_in_traffic if available, else regular duration
            $durationSeconds = $route['duration_in_traffic']['value'] ?? $route['duration']['value'];
            $durationText = $route['duration_in_traffic']['text'] ?? $route['duration']['text'];
            $distanceMeters = $route['distance']['value'];
            
            // Determine traffic status (guard against division by zero when duration is 0)
            $traffic = null;
            if (isset($route['duration_in_traffic']) && isset($route['duration'])) {
                $normalDuration = $route['duration']['value'] ?? 0;
                if ($normalDuration > 0) {
                    $ratio = $route['duration_in_traffic']['value'] / $normalDuration;
                    if ($ratio > 1.5) $traffic = 'heavy';
                    elseif ($ratio > 1.2) $traffic = 'moderate';
                    else $traffic = 'light';
                } else {
                    // Duration is 0 (origin ≈ destination), default to light traffic
                    $traffic = 'light';
                }
            }
            
            return [
                'distance_km' => round($distanceMeters / 1000, 1),
                'distance_text' => $route['distance']['text'],
                'duration_minutes' => round($durationSeconds / 60),
                'duration_text' => $durationText,
                'source' => 'google',
                'traffic' => $traffic,
            ];
            
        } catch (\Exception $e) {
            \Log::error('Google Maps API call failed', [
                'error' => $e->getMessage(),
            ]);
            return null;
        }
    }
    
    /**
     * Get ETA from OpenRouteService (fallback)
     */
    private function getEtaFromOpenRouteService($originLat, $originLng, $destLat, $destLng): ?array
    {
        $apiKey = env('OPENROUTESERVICE_API_KEY', '5b3ce3597851110001cf62487c37b3c0b8d74b9fb9f7d9f3c3d7f8e9');
        
        try {
            $client = new \GuzzleHttp\Client(['timeout' => 10]);
            
            $response = $client->post('https://api.openrouteservice.org/v2/directions/driving-car', [
                'headers' => [
                    'Authorization' => $apiKey,
                    'Content-Type' => 'application/json',
                ],
                'json' => [
                    'coordinates' => [
                        [$originLng, $originLat], // GeoJSON: [lng, lat]
                        [$destLng, $destLat],
                    ],
                    'instructions' => false,
                    'geometry' => false,
                ]
            ]);
            
            $data = json_decode($response->getBody()->getContents(), true);
            
            // Increment usage counter
            $this->incrementApiUsage('openroute_directions');
            
            if (empty($data['routes'])) {
                return null;
            }
            
            $summary = $data['routes'][0]['summary'];
            $distanceKm = round($summary['distance'] / 1000, 1);
            $durationMinutes = round($summary['duration'] / 60);
            
            return [
                'distance_km' => $distanceKm,
                'distance_text' => $distanceKm . ' km',
                'duration_minutes' => $durationMinutes,
                'duration_text' => $durationMinutes . ' min',
                'source' => 'openroute',
                'traffic' => null, // OpenRouteService doesn't provide traffic data
            ];
            
        } catch (\Exception $e) {
            \Log::error('OpenRouteService API call failed', [
                'error' => $e->getMessage(),
            ]);
            return null;
        }
    }
    
    /**
     * Increment API usage counter
     */
    private function incrementApiUsage(string $apiName): void
    {
        $monthKey = date('Y-m');
        
        \DB::table('t_sys_api_usage')
            ->updateOrInsert(
                ['api_name' => $apiName, 'month_key' => $monthKey],
                [
                    'call_count' => \DB::raw('call_count + 1'),
                    'last_called_at' => now(),
                    'updated_at' => now(),
                ]
            );
    }
    
    /**
     * Authorize route / dispatch actions on a rider's orders.
     *
     * Two callers are allowed:
     *   1. Store managers with the 'view_open_orders' mobile permission
     *      (acting on ANY rider under a pinned-rider view), or
     *   2. A rider acting on their OWN orders ($user->id === $riderId) —
     *      this is what powers Rider-Mode dispatch.
     *
     * @return bool
     */
    private function canManageRiderRoute($user, $riderId): bool
    {
        if (!$user) {
            return false;
        }
        if ((int) $user->id === (int) $riderId) {
            return true; // rider acting on own route
        }
        return $user->hasMobilePermission('view_open_orders');
    }

    /**
     * ⭐ Calculate and save delivery ETAs for a rider's out_for_delivery orders
     * Called when user presses "Get Times" button in pinned rider view
     * 
     * Uses Google Maps Directions API with waypoints (1 API call for all orders)
     * Adds 10 minutes stop time at each destination
     * Saves estimated_delivery_at for each order (fixed, won't change)
     * 
     * @param int $riderId - The rider to calculate ETAs for
     */
    public function calculateDeliveryEtas(Request $request, $riderId)
    {
        try {
            $user = Auth::user();

            // Entry log so every dispatch attempt is visible. This endpoint was
            // previously silent on its early "controlled" returns, which made
            // "failed to dispatch" reports impossible to trace in the logs.
            \Log::info('Dispatch: delivery-ETA calculation requested', [
                'rider_id'       => $riderId,
                'requested_by'   => $user->id ?? null,
                'scope'          => $request->input('scope', 'all'),
                'sequence_count' => is_array($request->input('order_sequence')) ? count($request->input('order_sequence')) : 0,
            ]);

            // Check permission — store managers (view_open_orders) OR the rider acting on own route
            if (!$this->canManageRiderRoute($user, $riderId)) {
                \Log::warning('Dispatch denied: permission', ['rider_id' => $riderId, 'user_id' => $user->id ?? null]);
                return response()->json([
                    'success' => false,
                    'message' => 'Permission denied'
                ], 403);
            }
            
            // Get rider info
            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->where('is_active', 1)
                ->select('id', 'fullname')
                ->first();

            if (!$rider) {
                \Log::warning('Dispatch failed: rider not found or inactive', ['rider_id' => $riderId]);
                return response()->json([
                    'success' => false,
                    'message' => 'Rider not found'
                ], 404);
            }

            /**
             * 🔧⭐⭐ HE IS STILL AT THE WORKSHOP — THE ONE PLACE THE FLEET ACTUALLY STOPS
             *    (owner ruling, 11-Sep-2026).
             *
             * ⭐ THE WHOLE POINT OF MOVING THE GUARD HERE. Assigning and marking an order
             *   "out for delivery" are desk actions — nothing leaves the building. Pressing
             *   DISPATCH is the claim that these parcels are now on the road with a time
             *   against each customer's name, and a man standing at Ali Motors cannot make
             *   that true. Stopping at the assign door (as this feature used to) blocked the
             *   paperwork and let the lie through; stopping here does the reverse.
             *
             * ⭐ ASK, don't refuse: `confirm` overrides it, because a real emergency happens
             *   and the dispatcher is the one who knows. Unlike the old assign guard, this
             *   override is REACHABLE — both phone callers already surface `message`, and the
             *   new APK sends `confirm` from the "Dispatch anyway" button.
             * ⚠ Fails OPEN: a lookup wobble must never strand a genuine dispatch.
             */
            try {
                $wsTrip = app(\App\Services\Riders\WorkshopVisitService::class)->tripFor((int) $riderId);
                if ($wsTrip && !empty($wsTrip['is_active'])) {
                    if (!$request->boolean('confirm')) {
                        \Log::warning('Dispatch held: rider is on a workshop trip', [
                            'rider_id' => $riderId,
                            'state'    => $wsTrip['state']    ?? null,
                            'visit_id' => $wsTrip['visit_id'] ?? null,
                        ]);
                        return response()->json([
                            'success'            => false,
                            'needs_confirmation' => true,
                            'workshop_trip'      => $wsTrip,
                            'message'            => ($wsTrip['label'] ?? 'He is at the workshop')
                                . '. Dispatch anyway?',
                        ], 409);
                    }
                    // Overridden deliberately — recorded, because the ETAs it writes will
                    // look wrong to whoever reads them later and this says why.
                    \Log::warning('Dispatch OVERRIDDEN during a workshop trip', [
                        'rider_id'     => $riderId,
                        'requested_by' => $user->id ?? null,
                        'visit_id'     => $wsTrip['visit_id'] ?? null,
                    ]);
                }
            } catch (\Throwable $e) {
                \Log::warning('workshop dispatch guard skipped', ['error' => $e->getMessage()]);
            }

            // Choose the dispatch origin with a guardrail against phantom GPS
            // fixes. A stale / low-accuracy reading that lands kilometres away
            // used to be accepted blindly and blew ETAs up to an hour for a
            // 15-minute drive (Jul 2026: a rider's fix reported 16 km NW of the
            // store). selectDispatchOrigin() filters those out and, on a FIRST
            // dispatch (rider loading at the store), refuses an implausibly-far
            // fix in favour of the store location. On a mid-run re-dispatch it
            // always trusts the live rider GPS so re-timing a live route still
            // works from the rider's real position.
            $origin = $this->selectDispatchOrigin($riderId);

            /**
             * 🧭 THE STORE CHOSE WHERE TO TIME FROM (Sep-2026, the dispatch sheet).
             *    `origin=rider|office` overrides the automatic pick; absent/'auto' =
             *    exactly today's behaviour (riders, old APKs, the van send-out path).
             *    'rider' uses his live ping only if it is ≤10 min old and possible —
             *    otherwise the office, and the warning says why.
             */
            // C9 (Sep-29): the choice is the STORE's. A rider pressing dispatch for his own
            // route always gets the automatic pick, whatever a client sends.
            $originChoice = ((int) ($user->id ?? 0) === (int) $riderId) ? null : $request->input('origin');
            $riderPos = $this->riderPositionNow((int) $riderId);
            $riderChosenOnRoad = false;
            if ($originChoice === 'office' && $riderPos['office']) {
                $o = $riderPos['office'];
                $origin = array_merge($origin, [
                    'location'   => (object) ['latitude' => $o->latitude, 'longitude' => $o->longitude, 'captured_at' => null],
                    'used_store' => true,
                    'source'     => 'office_chosen',
                    'note'       => 'Store chose to time the route from the office.',
                    'phantom'    => false,
                ]);
            } elseif ($originChoice === 'rider') {
                if ($riderPos['fix'] && in_array($riderPos['freshness'], ['fresh', 'aging'], true)) {
                    $origin = array_merge($origin, [
                        'location'   => $riderPos['fix'],
                        'used_store' => false,
                        'source'     => 'rider_chosen',
                        'note'       => 'Store chose to time the route from the rider\'s live location (ping '
                                        . $this->pingAgeText($riderPos['age_s']) . ').',
                        'fix'        => $riderPos['fix'],
                        'distance_from_store_m' => $riderPos['distance_m'],
                        'phantom'    => false,
                    ]);
                    $riderChosenOnRoad = !$riderPos['at_office'];
                } elseif ($riderPos['office']) {
                    // Asked for his location, but it is too old / impossible now.
                    $o = $riderPos['office'];
                    $origin = array_merge($origin, [
                        'location'   => (object) ['latitude' => $o->latitude, 'longitude' => $o->longitude, 'captured_at' => null],
                        'used_store' => true,
                        'source'     => 'office_rider_unavailable',
                        'note'       => 'Rider location was chosen but no usable ping — used the office.',
                        'phantom'    => $riderPos['implausible'],
                    ]);
                }
            }

            if (!$origin['location']) {
                // The ONLY remaining hard stop on this endpoint, and it is a
                // configuration fault rather than anything the rider did: there is
                // no usable GPS AND no office to fall back to, so there is no point
                // on earth to measure from. Says so plainly instead of blaming GPS.
                \Log::warning('Dispatch failed: no usable rider GPS and no office location configured', [
                    'rider_id' => $riderId,
                    'source'   => $origin['source'],
                    'phantom'  => !empty($origin['phantom']),
                ]);
                return response()->json([
                    'success' => false,
                    'message' => "⚠️ {$rider->fullname} ki location nahi mil rahi, aur office ki location bhi set nahi hai — "
                               . "is liye time nahi lagaya ja sakta. Admin se kahein ke office location set kare.",
                ], 400);
            }

            $riderLocation    = $origin['location'];
            $usedShopLocation = $origin['used_store'];

            \Log::info('Dispatch origin selected', [
                'rider_id'              => $riderId,
                'source'                => $origin['source'],
                'is_mid_run'            => $origin['is_mid_run'],
                'used_store'            => $origin['used_store'],
                'distance_from_store_m' => $origin['distance_from_store_m'],
                'gps_fix'               => $origin['fix'] ? [
                    'lat'         => (float) $origin['fix']->latitude,
                    'lng'         => (float) $origin['fix']->longitude,
                    'accuracy_m'  => $origin['fix']->accuracy ?? null,
                    'captured_at' => $origin['fix']->captured_at ?? null,
                ] : null,
                'origin_used'           => [
                    'lat' => (float) $riderLocation->latitude,
                    'lng' => (float) $riderLocation->longitude,
                ],
                'note'                  => $origin['note'],
            ]);
            
            // ⭐ Check if frontend passed explicit order sequence (fixes debounce timing issue)
            $orderSequence = $request->input('order_sequence', []);

            // ⭐ Dispatch scope: 'undispatched' = only orders not yet dispatched
            //    (the "Next Dispatch" wave) — keeps an already-dispatched batch's
            //    times frozen. Default 'all' dispatches every OFD order.
            $scope = $request->input('scope', 'all');

            /**
             * ⭐ RESTRICT THE WAVE TO WHAT WAS ACTUALLY PICKED (Sep-2026, van picker).
             *
             * `scope=undispatched` is rider-wide: it times EVERY out-for-delivery order of his
             * that has no ETA yet. That is right for the ordinary Dispatch button, but the van
             * wave picker is a deliberate selection — so a stop that happened to be sitting
             * OFD-without-a-time (a store hand-flip, or a failed earlier dispatch) was silently
             * appended to the route and PROMISED to a customer without anyone choosing it.
             *
             * ⚠ Absent = unchanged behaviour for every existing caller; only the van's
             *   dispatch-selected path sends it.
             */
            $onlyOrderIds = array_values(array_filter(array_map(
                'intval', (array) $request->input('only_order_ids', [])
            )));

            // ⭐ Start grace offset (minutes): pushes the whole route's start
            //    time forward before the first leg so the rider has time to
            //    reach his motorbike (e.g. dispatch at 10:00 → first ETA from
            //    10:05). A client-sent value is always honoured (Rider Mode's
            //    old APK sends 5); its ABSENCE means "server decides", and the
            //    default is finalised below once we know isRedispatch — NOT here
            //    off is_mid_run. See the block after the isRedispatch snapshot.
            $clientOffset = $request->input('start_offset_minutes'); // null when absent

            // Get all out_for_delivery orders for this rider
            $ordersQuery = \DB::table('t_crm_prod_order as o')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->where('o.assigned_rider_user_id', $riderId)
                ->where('o.order_status', 'out_for_delivery')
                ->when($scope === 'undispatched', function ($q) {
                    $q->whereNull('o.eta_calculated_at');
                })
                // See $onlyOrderIds above — the van picker's explicit selection.
                ->when(!empty($onlyOrderIds), function ($q) use ($onlyOrderIds) {
                    $q->whereIn('o.id', $onlyOrderIds);
                })
                ->select([
                    'o.id',
                    'o.order_number',
                    'o.delivery_priority',
                    'o.estimated_delivery_at', // Check if already has ETA
                    'c.latitude',
                    'c.longitude',
                    'c.geocoded_latitude',
                    'c.geocoded_longitude',
                    // How good the machine-geocoded pin is, so a rooftop match can
                    // be timed normally while an area-level one is labelled a
                    // guess. Requires add_location_confidence_jul2026.sql — the
                    // SQL must be run BEFORE this file is uploaded.
                    'c.geocode_precision',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                ]);
            
            // Deterministic base order for BOTH paths below. The sequence path
            // used a bare ->get() (no ORDER BY), so anything the client's map
            // didn't pin down — a stop it omitted, or two stops it gave the same
            // number — was left in raw storage order rather than the stored
            // route. Every stop the map DOES pin is unaffected by this.
            $ordersQuery->orderByRaw('COALESCE(o.delivery_priority, 999) ASC, o.id ASC');

            // ⭐ If frontend passed order sequence, use that order
            if (!empty($orderSequence)) {
                // Create a map of order_id => priority
                $priorityMap = [];
                foreach ($orderSequence as $item) {
                    // Skip a null/absent priority instead of mapping it: older
                    // app builds sent the raw delivery_priority, which is null
                    // for a stop nobody has sequenced yet, and every null then
                    // collapsed to the same sort key.
                    if (isset($item['order_id'], $item['priority'])) {
                        $priorityMap[$item['order_id']] = $item['priority'];
                    }
                }

                // sortBy is stable, so unmapped stops (PHP_INT_MAX = "not in the
                // client's plan, put it last") and ties keep the base order.
                $orders = $ordersQuery->get()->sortBy(function ($order) use ($priorityMap) {
                    return $priorityMap[$order->id] ?? PHP_INT_MAX;
                })->values();
            } else {
                // Use DB priority order (fallback)
                $orders = $ordersQuery->get();
            }
            
            if ($orders->isEmpty()) {
                \Log::warning('Dispatch failed: no out_for_delivery orders for rider', ['rider_id' => $riderId, 'scope' => $scope]);
                return response()->json([
                    'success' => false,
                    'message' => 'No out_for_delivery orders found for this rider'
                ], 400);
            }
            
            // ⭐ Resolve every stop's location AND how much it can be trusted, in
            //    sequence. One brain does this (CustomerLocationResolver) so the
            //    times, the labels the team reads, and anything added later can
            //    never disagree about where a customer is.
            //
            //    EVERY stop in scope stays in the plan. A stop with no usable pin
            //    used to be dropped here — it got no time, so an un-timed stop sat
            //    ahead of timed ones and the board reported "a new order was placed
            //    ahead of stops that already have times" about an order nobody had
            //    added, while a Re-dispatch could never clear it (Jul-25: SH-21417,
            //    4 stops sent, 3 timed). Worse, the stops BEHIND it were costed as
            //    if it did not exist — that route came out 67 min for 3 stops
            //    against 87 for the same 4, so three customers were promised times
            //    ~20 min early. Now it keeps its position and is costed with a flat
            //    estimated leg instead, which is honest and self-correcting: the
            //    moment someone pins the customer, the next dispatch is exact.
            $noPinLegMinutes = max(1, min(120, (int) $this->attnConfig('DISPATCH_NO_PIN_LEG_MINUTES', 15)));

            $plan = [];               // every stop, in dispatch order
            $waypoints = [];          // only the stops Google can actually route
            $unverifiedOrders = [];   // routed, but not from a human pin (unchanged meaning)
            $noLocationOrders = [];   // no usable pin — timed from the estimated leg
            $locationNotes = [];      // per-stop explanation for the app

            // ⭐ The same phantom ceiling as the rider's origin, applied to the
            //    CUSTOMER pins — because the same fault produces both, and one
            //    impossible pin is enough to make Google answer ZERO_RESULTS for
            //    the ENTIRE route, so all six stops lose their real times over one
            //    bad row. Judged against the primary office only; if none is
            //    configured there is nothing to measure against and the check is
            //    skipped, which leaves behaviour exactly as it was.
            $phantomPinM  = $this->phantomOriginMetres();
            $pinBase      = \App\Services\LocationService::getPrimaryBaseLocation();
            $pinBaseOk    = $pinBase && $pinBase->latitude && $pinBase->longitude;
            $badPinOrders = [];

            // Start with rider's current location
            $waypoints[] = [
                'lat' => (float)$riderLocation->latitude,
                'lng' => (float)$riderLocation->longitude,
            ];

            foreach ($orders as $order) {
                $loc = \App\Services\Location\CustomerLocationResolver::resolve($order);

                // A pin further from the office than any delivery could possibly
                // be is a data fault, not a destination. Demote it to "no pin":
                // the stop KEEPS its place in the sequence and is charged the flat
                // estimated leg, exactly like a customer nobody has pinned yet.
                // That path is already built, already honest, and already tells
                // the rider to navigate by the written address.
                if ($loc['routable'] && $pinBaseOk) {
                    $pinDistance = \App\Services\LocationService::calculateDistance(
                        $loc['latitude'], $loc['longitude'], $pinBase->latitude, $pinBase->longitude
                    );
                    if ($pinDistance > $phantomPinM) {
                        $pinKm = (int) round($pinDistance / 1000);
                        \Log::warning('Dispatch: customer pin implausibly far — treated as unpinned', [
                            'rider_id'     => $riderId,
                            'order_number' => $order->order_number,
                            'tier'         => $loc['tier'],
                            'pin'          => ['lat' => (float) $loc['latitude'], 'lng' => (float) $loc['longitude']],
                            'km_from_office' => $pinKm,
                        ]);
                        $badPinOrders[] = $order->order_number;
                        $loc = [
                            'tier'        => \App\Services\Location\CustomerLocationResolver::TIER_NONE,
                            'latitude'    => null,
                            'longitude'   => null,
                            'routable'    => false,
                            'approximate' => true,
                            'label'       => "Saved location looks wrong (~{$pinKm} km from the office) — treated as no pin",
                            'short'       => 'Pin looks wrong',
                            // Marker so the note below can say WHY this stop lost
                            // its pin. The tier stays TIER_NONE on purpose: every
                            // client already knows how to render that.
                            'bad_pin'     => true,
                            'bad_pin_km'  => $pinKm,
                        ];
                    }
                }

                $plan[] = ['order' => $order, 'loc' => $loc];

                if ($loc['routable']) {
                    $waypoints[] = [
                        'lat' => (float) $loc['latitude'],
                        'lng' => (float) $loc['longitude'],
                    ];
                    // Same list, same meaning as before: has coordinates, but they
                    // are not a verified pin. Old app builds still read this key.
                    if ($loc['tier'] !== \App\Services\Location\CustomerLocationResolver::TIER_VERIFIED) {
                        $unverifiedOrders[] = $order->order_number;
                    }
                } else {
                    $noLocationOrders[] = $order->order_number;
                }

                if ($loc['tier'] !== \App\Services\Location\CustomerLocationResolver::TIER_VERIFIED) {
                    $locationNotes[] = [
                        'order_id'     => (int) $order->id,
                        'order_number' => $order->order_number,
                        'customer_name'=> trim((string) $order->customer_name),
                        'tier'         => $loc['tier'],
                        'label'        => $loc['label'],
                        'short'        => $loc['short'],
                        'approximate'  => $loc['approximate'],
                        'routable'     => $loc['routable'],
                        // English sentence AND a stable key. The app renders Roman Urdu
                        // from the key and falls back to `note` for anything it doesn't
                        // recognise, so a missing translation can never blank a warning.
                        // A rejected pin gets its own key/sentence: "no pin" and "the
                        // pin we have is wrong" call for different action from the team.
                        'note'         => !empty($loc['bad_pin'])
                            ? "{$order->order_number}: the saved location is about {$loc['bad_pin_km']} km from the office, "
                              . "which cannot be right — it was ignored and about {$noPinLegMinutes} minutes allowed for this stop. "
                              . 'Please correct the pin.'
                            : \App\Services\Location\CustomerLocationResolver::dispatchNote($loc['tier'], $noPinLegMinutes),
                        'key'          => !empty($loc['bad_pin'])
                            ? 'note_bad_pin'
                            : \App\Services\Location\CustomerLocationResolver::noteKey($loc['tier']),
                        'params'       => [
                            'order' => $order->order_number,
                            'mins'  => $noPinLegMinutes,
                            'km'    => $loc['bad_pin_km'] ?? null,
                        ],
                    ];
                }
            }

            // ⭐ Optional hard gate, OFF by default (DISPATCH_REQUIRE_PIN=0).
            //    Enforced server-side so flipping the config works immediately, on
            //    old app builds too. Default is to let the dispatch through:
            //    refusing it does not stop the delivery, only the timing of it —
            //    the rider leaves regardless, every stop loses its ETA, the
            //    customer app gets nothing, and he is then flagged for "leaving
            //    without dispatching". One rough time beats none at all.
            if (!empty($noLocationOrders)
                && (string) $this->attnConfig('DISPATCH_REQUIRE_PIN', '0') === '1') {
                \Log::warning('Dispatch refused: stops without a location pin (DISPATCH_REQUIRE_PIN=1)', [
                    'rider_id' => $riderId, 'orders' => $noLocationOrders,
                ]);
                return response()->json([
                    'success' => false,
                    'message' => count($noLocationOrders) === 1
                        ? "{$noLocationOrders[0]} has no location pin. Please add the pin, then dispatch."
                        : 'These orders have no location pin: ' . implode(', ', $noLocationOrders)
                          . '. Please add the pins, then dispatch.',
                    'no_location_orders' => $noLocationOrders,
                    'pin_required' => true,
                ], 422);
            }

            // Google is only called when there is at least one routable stop. A van
            // where NOTHING can be routed still gets timed (every leg estimated)
            // rather than being refused — same principle as above.
            $etaResult = ['legs' => []];
            // Set when the times below are straight-line guesses rather than
            // Google's road times. Read again further down, where it seeds the
            // "≈" honesty flag so a guess can never render as a firm promise.
            $routeIsEstimated = false;
            $googleFailure    = null;
            // Where the leg times came from. Tracked explicitly rather than
            // inferred: when NO stop is routable, Google is never called at all,
            // and reporting "google_maps" for times it never produced would make
            // this field lie in exactly the situation someone is reading it.
            $etaSource        = 'no_routable_stops';

            if (count($waypoints) > 1) {
                $etaResult = $this->getMultiStopEtaFromGoogle($waypoints, $googleFailure);
                $etaSource = 'google_maps';

                if (!$etaResult) {
                    // ⭐ NEVER REFUSE THE DISPATCH OVER THIS (Sep-2026). Aug-31 a
                    //    mislocated WiFi router put a rider's phone in Beijing;
                    //    Google correctly answered ZERO_RESULTS for "drive from
                    //    Beijing to Islamabad" and this branch returned a 500, so
                    //    the rider tapped Dispatch ten times, got "API error or
                    //    limit reached" each time, and left with six stops carrying
                    //    NO times at all — while the route-preview path handled the
                    //    very same failure gracefully in the same minute.
                    //
                    //    The origin and pin guards above should now prevent the
                    //    impossible-coordinate case from ever reaching Google, so
                    //    this is the backstop for everything else: an outage, a
                    //    timeout, a genuinely unroutable pin. Same principle as the
                    //    no-pin rule — one rough time beats none at all.
                    $etaResult        = $this->estimateLegsByStraightLine($waypoints);
                    $routeIsEstimated = true;
                    $etaSource        = 'straight_line_estimate';
                    \Log::warning('Dispatch: Google multi-stop ETA unavailable — using straight-line estimates', [
                        'rider_id' => $riderId,
                        'stops'    => count($waypoints) - 1,
                        'reason'   => $googleFailure,   // the REAL cause, not a guess
                    ]);
                }
            } else {
                \Log::warning('Dispatch: no stop has a usable location — timing every leg from the estimate', [
                    'rider_id' => $riderId,
                    'orders' => $noLocationOrders,
                    'estimated_leg_minutes' => $noPinLegMinutes,
                ]);
            }
            
            // ⭐ Accountability: how far into his day was he when he pressed?
            //    Captured BEFORE the writes below. delivered_before (not the
            //    is_mid_run flag) is what separates "re-timed before leaving the
            //    office" — harmless, his times are still honest — from "re-timed
            //    after dropping 4 stops", which moves the goalposts.
            $deliveredBefore = $this->deliveredTodayCount((int) $riderId);
            $etaLogStops = [];

            // Snapshot the times these stops carried BEFORE we overwrite them.
            // Two jobs: it tells a genuine RE-TIME (stops that already had a
            // promised time) apart from simply dispatching a fresh wave — a rider
            // who finished wave 1 and dispatches wave 2 has delivered_before > 0
            // but is re-timing nothing — and it measures how far the times moved.
            $previousEtas = [];
            foreach ($plan as $entry) {
                if (!empty($entry['order']->estimated_delivery_at)) {
                    $previousEtas[(int) $entry['order']->id] = $entry['order']->estimated_delivery_at;
                }
            }
            $isRedispatch = !empty($previousEtas);

            // ⭐ Finalise the start grace now that isRedispatch is known.
            //    Keyed on isRedispatch, NOT is_mid_run — this is the F2 fix.
            //    riderIsMidRun stays true for 90 min after the last delivery, so
            //    a rider who finished wave 1 and is dispatching a FRESH wave 2
            //    from the office is "mid-run" yet genuinely remounting and needs
            //    the head start. What actually removes the need for grace is
            //    re-timing stops that ALREADY carry an ETA (he's on the road):
            //      • isRedispatch = false → fresh stops (first wave OR a next
            //        wave, OR a cancel→re-dispatch which cleared the ETAs) → +5.
            //      • isRedispatch = true  → re-time of already-promised stops → 0.
            //    A client-sent value still wins, so old APKs keep today's exact
            //    behaviour until the rider app stops sending it (C3, next APK).
            if ($clientOffset !== null) {
                $startOffsetMinutes = max(0, min(30, (int) $clientOffset));
            } else {
                $startOffsetMinutes = $isRedispatch ? 0 : 5;

                // ⭐ THE VAN DRIVER GETS NO HEAD START (owner ruling Aug-2026:
                //    "no 5 min headstart needed here"). The grace buys time to
                //    walk out and reach a motorbike; when he dispatches his
                //    second wave he is already sitting in a running van at the
                //    meet-up point, so the padding only makes every promise to
                //    the customer 5 minutes pessimistic. Driving side ONLY — a
                //    rider who has just collected off the van keeps his grace.
                if ($this->riderIsDrivingVanNow((int) $riderId)) {
                    $startOffsetMinutes = 0;
                }
                // The store chose "his location" while he is out on the road: he is
                // already moving, there is no walk to the bike to pad for (Sep-2026).
                // Automatic picks keep today's grace rule untouched.
                if ($riderChosenOnRoad) {
                    $startOffsetMinutes = 0;
                }
            }

            // ⭐ Calculate cumulative ETA for each order
            $stopTimeMinutes = 10; // Time spent at each stop
            $now = now();
            $calculatedAt = $now->copy();
            // Seed with the start grace so every ETA is shifted by the offset
            // (e.g. 5 min in Rider Mode). The 10-min gap between stops below is
            // unaffected — it's still added after each stop.
            $cumulativeMinutes = $startOffsetMinutes;
            $updatedOrders = [];
            // Google returned one leg per ROUTABLE stop, but we walk every stop in
            // the plan — so the leg pointer advances only when a stop was actually
            // sent to Google. Without this the legs would shift onto the wrong
            // stops as soon as one had no pin.
            $legIndex = 0;
            // ⭐ Once ANY leg has been estimated, every LATER stop's cumulative time
            //    contains that guess — and Google's leg that skips over the pinless
            //    stop is missing the detour too. So the "≈" honesty flag propagates
            //    downstream instead of marking only the pinless stop itself: the
            //    times behind it are exactly as approximate as its own.
            //
            //    Seeded from $routeIsEstimated: when Google could not answer at all,
            //    EVERY leg is a straight-line guess, so every stop must carry the
            //    "≈" from the very first one — not just the stops behind a pinless
            //    neighbour.
            $estimatedLegSeen = $routeIsEstimated;

            foreach ($plan as $index => $entry) {
                $order = $entry['order'];
                $loc   = $entry['loc'];

                if ($loc['routable']) {
                    // Get travel time to this order from previous point
                    $legDuration = $etaResult['legs'][$legIndex] ?? 0; // Duration in minutes
                    $legIndex++;
                } else {
                    // No pin to route to. Charge a flat estimate so the stop still
                    // occupies real time in the route and every stop behind it is
                    // pushed back accordingly.
                    //
                    // Known approximation: when this stop sits BETWEEN two routable
                    // ones, Google's leg between those two does not include the
                    // detour, so the estimate stands in for it. It errs toward
                    // allowing more time, which is the safe direction for a promise.
                    $legDuration = $noPinLegMinutes;
                    $estimatedLegSeen = true;
                }

                $cumulativeMinutes += $legDuration;
                
                // Calculate estimated arrival time
                $estimatedAt = $now->copy()->addMinutes(round($cumulativeMinutes));
                
                // Update order with estimated time only (DO NOT change delivery_priority - that's set by the team)
                \DB::table('t_crm_prod_order')
                    ->where('id', $order->id)
                    ->update([
                        'estimated_delivery_at' => $estimatedAt,
                        'eta_calculated_at' => $calculatedAt,
                        'eta_calculated_by' => $user->id, // attribution: who dispatched (rider or store)
                    ]);

                // 🛎 CUSTOMER APP — THIS is the moment the order becomes "out for
                // delivery" for the CUSTOMER. Ops sets that status early (while the
                // order is still being loaded), so the webhook emitter has been
                // masking it as `processing`; now there is a real rider, a real route
                // and a real ETA, so the true status is released — carrying the
                // delivery window. No-op unless the Status Hub flags the status as
                // held and this is an SH- order.
                //
                // Only on a stop's FIRST dispatch: $previousEtas (snapshotted before
                // the writes above) is exactly the "this stop was already promised a
                // time" test, so a re-time never re-announces a status the customer
                // already has. Emitted BEFORE the ETA event below so the outbox —
                // drained in id order — delivers status-then-ETA. Non-fatal; never
                // affects ETA calculation.
                if (!isset($previousEtas[(int) $order->id])) {
                    try {
                        app(\App\Services\CustomerAppWebhookEmitter::class)
                            ->emitDispatchStatus((int) $order->id, $order->order_number, 'out_for_delivery', $estimatedAt);
                    } catch (\Throwable $e) {
                        \Log::error('CustomerApp emitDispatchStatus hook failed (non-fatal)', [
                            'order_id' => $order->id,
                            'error'    => $e->getMessage(),
                        ]);
                    }
                }

                // Phase 2 (customer app) — push the refreshed ETA + delivery
                // window. No-op unless config emit_eta_updates is ON and this
                // is an SH- order. Self-contained + non-fatal; never affects
                // ETA calculation.
                try {
                    app(\App\Services\CustomerAppWebhookEmitter::class)
                        ->emitEtaUpdate($order->id, $order->order_number, 'out_for_delivery', $estimatedAt);
                } catch (\Throwable $e) {
                    \Log::error('CustomerApp emitEtaUpdate hook failed (non-fatal)', [
                        'order_id' => $order->id,
                        'error'    => $e->getMessage(),
                    ]);
                }

                $etaLogStops[] = [
                    'order_id'              => (int) $order->id,
                    'estimated_delivery_at' => $estimatedAt->format('Y-m-d H:i:s'),
                    'position'              => $index + 1,
                ];

                $updatedOrders[] = [
                    'order_id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_name' => trim($order->customer_name),
                    'sequence' => $index + 1,
                    'delivery_priority' => $index + 1, // ⭐ Show the assigned priority
                    'travel_minutes' => round($legDuration),
                    'estimated_at' => $estimatedAt->format('h:i A'),
                    'estimated_at_raw' => $estimatedAt->toIso8601String(),
                    // ⭐ How trustworthy this particular time is, so the app can show
                    //    "≈" instead of quoting a guess as a promise. TRUE for the
                    //    stop's own approximate pin AND for every stop downstream of
                    //    an estimated leg — its cumulative time carries the guess.
                    'location_tier' => $loc['tier'],
                    'location_label' => $loc['label'],
                    'time_is_estimate' => $loc['approximate'] || $estimatedLegSeen,
                    'leg_was_estimated' => !$loc['routable'],
                ];
                
                // Add stop time for next order calculation
                $cumulativeMinutes += $stopTimeMinutes;
            }
            
            // ⭐ Remember what was promised, and by whom. estimated_delivery_at is
            //    overwritten by every dispatch, so without this log the ORIGINAL
            //    commitment is unrecoverable and lateness can be re-dispatched
            //    away. Fail-safe: no table → silent no-op (PHP deploys before SQL).
            \App\Services\Riders\EtaPromiseService::logDispatch(
                (int) $riderId,
                $calculatedAt->format('Y-m-d H:i:s'),
                $etaLogStops,
                $user->id ?? null,
                (bool) $origin['is_mid_run'],
                $deliveredBefore,
                (string) $scope,
                [
                    'origin_source'    => $origin['source'],
                    // HIS position at the press, whatever origin was used — read by the
                    // "cleared while he was out" excuse and the "he was X km out" wording.
                    'rider_distance_m' => $riderPos['fix'] && $riderPos['freshness'] !== 'stale' ? $riderPos['distance_m'] : null,
                    'rider_gps_age_s'  => $riderPos['age_s'],
                ]
            );

            // 📲 The store timed HIS route — tell him, in Roman Urdu, so he looks at
            //    the new times instead of riding on the old ones (owner, Sep-28).
            //    Never for his own press. Non-fatal.
            if ((int) ($user->id ?? 0) !== (int) $riderId && !empty($updatedOrders)) {
                try {
                    $recentStoreCancel = false;
                    if (!$isRedispatch && \Schema::hasTable('t_ops_eta_log')) {
                        $recentStoreCancel = \DB::table('t_ops_eta_log')
                            ->where('rider_id', $riderId)->where('event', 'cancel')->where('is_rider_self', 0)
                            ->whereIn('order_id', array_map(fn ($s) => (int) $s['order_id'], $etaLogStops))
                            ->where('created_at', '>=', now()->subMinutes(10)->format('Y-m-d H:i:s'))
                            ->exists();
                    }
                    app(\App\Services\FirebaseService::class)->notifyRiderRouteTimed(
                        (int) $riderId,
                        (string) ($user->fullname ?? 'Office'),
                        count($updatedOrders),
                        $isRedispatch || $recentStoreCancel,
                        (bool) $usedShopLocation
                    );
                } catch (\Throwable $e) {
                    \Log::warning('Rider route-timed push failed (non-fatal)', ['rider_id' => $riderId, 'error' => $e->getMessage()]);
                }
            }

            // ⭐ Tell the store, now, when a rider re-times his OWN route after he
            //    has already dropped stops — the press that quietly moves times
            //    customers were promised. Not fired when a store user pressed it
            //    (they know), nor before he has delivered anything (re-timing at
            //    the office changes nobody's expectations). Non-fatal.
            $isRiderSelf = ((int) ($user->id ?? 0) === (int) $riderId);
            if ($isRiderSelf && $deliveredBefore > 0 && $isRedispatch) {
                try {
                    app(\App\Services\FirebaseService::class)->notifyMidRunRouteChange(
                        (int) $riderId,
                        $rider->fullname ?? 'Rider',
                        $deliveredBefore,
                        count($updatedOrders),
                        $this->averageEtaShiftMinutes($etaLogStops, $previousEtas)
                    );
                } catch (\Throwable $e) {
                    \Log::warning('Mid-run route-change alert failed (non-fatal)', [
                        'rider_id' => $riderId, 'error' => $e->getMessage(),
                    ]);
                }
            }

            // orders_count now equals the number of stops SENT (it silently meant
            // "stops we could locate" before — that gap between sequence_count and
            // orders_count is what gave the Jul-25 incident away). estimated_legs
            // makes the remaining uncertainty visible in the log itself.
            \Log::info('📊 Delivery ETAs calculated', [
                'rider_id' => $riderId,
                'orders_count' => count($updatedOrders),
                'total_duration_minutes' => round($cumulativeMinutes),
                'start_offset_minutes' => $startOffsetMinutes,
                'delivered_before' => $deliveredBefore,
                'is_mid_run' => $origin['is_mid_run'],
                'estimated_legs' => count($noLocationOrders),
                'approx_stops' => count($locationNotes),
            ]);
            
            $response = [
                'success' => true,
                'message' => 'ETAs calculated for ' . count($updatedOrders) . ' orders',
                'rider' => [
                    'id' => $rider->id,
                    'name' => $rider->fullname,
                    'current_location' => [
                        'latitude' => (float)$riderLocation->latitude,
                        'longitude' => (float)$riderLocation->longitude,
                        'captured_at' => $riderLocation->captured_at ?? null,
                    ],
                ],
                'calculated_at' => $calculatedAt->toIso8601String(),
                'stop_time_minutes' => $stopTimeMinutes,
                'start_offset_minutes' => $startOffsetMinutes,
                'orders' => $updatedOrders,
                'unverified_orders' => $unverifiedOrders,
                // Kept for older app builds, but the meaning has softened: these
                // stops were still dispatched and still carry a time — they were
                // simply costed from the estimate rather than dropped.
                'no_location_orders' => $noLocationOrders,
                // ⭐ New clients: one entry per stop that is not a verified pin,
                //    already written in plain English for display.
                'location_notes' => $locationNotes,
                'no_pin_leg_minutes' => $noPinLegMinutes,
                // Where these times came from: Google's road times, the
                // straight-line stand-in used when Google could not answer, or
                // no Google call at all because nothing was routable.
                // Diagnostic — nothing renders it yet, and it costs one string.
                'eta_source' => $etaSource,
                // Stops whose saved pin was rejected as impossible (see above).
                'bad_pin_orders' => $badPinOrders,
                // Where these times were measured FROM, in one line for the
                // success alert (Sep-2026): "Timed from Asim's location (ping 20 s ago)".
                'origin_used' => [
                    'kind'  => $usedShopLocation ? 'office' : 'rider',
                    'source'=> $origin['source'],
                    'label' => $usedShopLocation
                        ? 'Timed from the office'
                        : 'Timed from ' . $rider->fullname . "'s location"
                          . ($riderPos['fix'] && $riderPos['age_s'] !== null ? ' (ping ' . $this->pingAgeText($riderPos['age_s']) . ')' : ''),
                ],
            ];

            // Everything the team needs to know about HOW these times were worked
            // out, in one place. Both parts go out under `gps_warning` because
            // that is the key every APK already in riders' hands displays — a
            // new key would show nothing until the whole fleet had updated.
            $dispatchWarnings = [];

            if ($origin['source'] === 'office_chosen') {
                // chosen deliberately in the sheet — nothing to warn about
            } elseif ($origin['source'] === 'office_rider_unavailable' && empty($origin['phantom'])) {
                $dispatchWarnings[] = "⚠️ {$rider->fullname} ki location purani thi (" . $this->pingAgeText($riderPos['age_s'])
                    . "), is liye delivery times office se lagaye gaye hain. Unse kahein ke app kholein, phir dobara Dispatch karein.";
            } elseif ($usedShopLocation) {
                $dispatchWarnings[] = $this->dispatchOriginWarning($origin, $rider->fullname, 'Delivery times');
            }

            if ($routeIsEstimated) {
                $dispatchWarnings[] = "⚠️ Google se route nahi ban saka, is liye times seedhi doori se lagaye gaye hain "
                                    . "— ye sirf andaza hain. Thori der baad dobara Dispatch karein to theek time lag jayenge.";
            }

            if (!empty($badPinOrders)) {
                $dispatchWarnings[] = "⚠️ In orders ki saved location bilkul galat thi, is liye unhein bina pin ke ginna para: "
                                    . implode(', ', $badPinOrders) . ". Inki pin theek karwayein.";
            }

            if (!empty($dispatchWarnings)) {
                $response['gps_warning'] = implode("\n\n", $dispatchWarnings);
            }

            return response()->json($response);
            
        } catch (\Exception $e) {
            \Log::error('Failed to calculate delivery ETAs', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to calculate ETAs: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Is this rider already out on the road (as opposed to loading up at the
     * store for a first dispatch)? Used to decide whether the store-proximity
     * guardrail in selectDispatchOrigin() should apply.
     *
     * Two independent signals, either is enough:
     *   1. A previous dispatch wave is still live — some order assigned to the
     *      rider is out_for_delivery AND already has an ETA. This covers the
     *      manager "reorder → Re-dispatch" case (mobile Re-dispatch re-times
     *      without clearing eta_calculated_at) and the "Next Dispatch" wave.
     *   2. The rider delivered something in the last 90 minutes — he's clearly
     *      moving even if a cancel-dispatch wiped the ETAs first.
     *
     * When in doubt this errs toward "mid-run" (trust the rider's GPS), which
     * is the safe direction: it never snaps a genuinely-travelling rider back
     * to the store.
     */
    private function riderIsMidRun(int $riderId): bool
    {
        $hasLiveEta = \DB::table('t_crm_prod_order')
            ->where('assigned_rider_user_id', $riderId)
            ->where('order_status', 'out_for_delivery')
            ->whereNotNull('eta_calculated_at')
            ->exists();
        if ($hasLiveEta) {
            return true;
        }

        // Second signal: he DELIVERED something in the last 90 minutes, so he's
        // still out on the road even though no OFD order carries an ETA now.
        //
        // The delivery time comes from the status history, NOT the order's
        // updated_at: updated_at moves on ANY edit, so an operator correcting an
        // old delivered order (a weight, a payment, a note) made that order's
        // rider look mid-run for the next 90 minutes. A "mid-run" rider is timed
        // from raw live GPS with no 5-min grace and no office anchoring — the
        // exact guardrails a rider genuinely starting his day from the office
        // needs. Same join the canonical detectLeftWithoutDispatch uses, and
        // covered by idx_order_history (order_id, changed_at).
        $recentDrop = \DB::table('t_crm_prod_order as o')
            ->join('t_crm_order_status_history as osh', function ($j) {
                $j->on('o.id', '=', 'osh.order_id')
                  ->where('osh.status_code', '=', 'delivered');
            })
            ->where('o.assigned_rider_user_id', $riderId)
            ->where('o.order_status', 'delivered')
            ->where('osh.changed_at', '>=', now()->subMinutes(90))
            ->exists();
        if ($recentDrop) {
            return true;
        }

        /**
         * Third signal (Sep-2026): WHERE HE IS decides, not whether a cancel
         * happened. The orders he holds now WERE dispatched today (the log still
         * says so after a cancel wiped the order rows) AND a fresh (≤5 min),
         * possible fix puts him away from the office → he is out on the road.
         * This is Asim's Sep-27 case: a store cancel wiped signal 1, his last drop
         * was >90 min earlier, and a rider 13.4 km out was timed from the office.
         *
         * ⚠ Deliberately NOT "he delivered today": a rider at his pickup point with
         *   never-dispatched orders must keep the first-dispatch consensus + 5 km
         *   office anchoring — that is the guard against the Jul-2026 phantom fix
         *   (a phone at the store claiming 16 km NW). Only a route that was actually
         *   pressed out qualifies. At the office (≤300 m) this stays false — a rider
         *   back to collect new orders still gets a fresh first-dispatch wave.
         */
        if (\App\Services\Riders\EtaPromiseService::currentOrdersWereDispatchedToday($riderId)) {
            $pos = $this->riderPositionNow($riderId);
            if ($pos['freshness'] === 'fresh' && !$pos['at_office'] && $pos['distance_m'] !== null) {
                return true;
            }
        }
        return false;
    }

    /**
     * Average minutes the stops' times moved in this dispatch (+ = later).
     * Null when nothing had a previous time to compare against.
     */
    private function averageEtaShiftMinutes(array $newStops, array $previousEtas): ?int
    {
        $diffs = [];
        foreach ($newStops as $s) {
            $old = $previousEtas[(int) $s['order_id']] ?? null;
            if ($old) {
                $diffs[] = (strtotime($s['estimated_delivery_at']) - strtotime($old)) / 60;
            }
        }
        if (empty($diffs)) {
            return null;
        }
        return (int) round(array_sum($diffs) / count($diffs));
    }

    /**
     * How many orders this rider has actually DELIVERED today.
     *
     * Used to stamp the ETA log: a re-dispatch pressed after real stops have
     * been dropped is the one that moves the goalposts. Reads the delivery time
     * from the status history (never updated_at — that moves on any edit) and
     * counts distinct orders (an order can carry more than one delivered row if
     * it was pulled back and re-delivered).
     */
    private function deliveredTodayCount(int $riderId): int
    {
        try {
            return (int) \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as osh', function ($j) {
                    $j->on('o.id', '=', 'osh.order_id')
                      ->where('osh.status_code', '=', 'delivered');
                })
                ->where('o.assigned_rider_user_id', $riderId)
                ->whereIn('o.order_status', ['delivered', 'completed'])
                ->whereDate('osh.changed_at', now()->toDateString())
                ->distinct()
                ->count('o.id');
        } catch (\Throwable $e) {
            return 0; // never block a dispatch over a stat
        }
    }

    /**
     * Pick the origin point for a dispatch ETA calculation, defending against
     * phantom GPS fixes (cached / low-accuracy readings that land kilometres
     * from the rider and inflate ETAs to an hour for a 15-minute drive).
     *
     * The core trick is to anchor on the rider's OWN recent GPS consensus: we
     * take the median of his credible recent fixes (robust to a transient burst
     * of phantom readings, even ones that report good accuracy) and use the
     * newest fix that agrees with that consensus.
     *
     * The fallback / backstop reference is the primary OFFICE — every rider
     * dispatches deliveries from there. (A rider's *assigned* location is only
     * his attendance / supply-pickup point and can be kilometres away, so it is
     * deliberately NOT used here.)
     *
     * Rules:
     *  - MID-RUN / RE-DISPATCH (see riderIsMidRun): always trust the rider's
     *    live GPS (newest accuracy-filtered fix). Never second-guess it, so
     *    re-timing a live route from the rider's real position keeps working.
     *  - FIRST DISPATCH: use the consensus-anchored fix. Only when even that
     *    anchored position is EGREGIOUSLY far from the office (a persistent
     *    phantom — the phone stuck on one wrong spot) do we fall back to the
     *    office location.
     *  - No usable GPS at all: fall back to the office location (unchanged
     *    behaviour) with a warning; error only if no office is configured.
     *
     * @return array{location: ?object, used_store: bool, source: string,
     *               note: string, fix: ?object, distance_from_store_m: ?int,
     *               is_mid_run: bool}
     */
    /**
     * Is this rider dispatching from a van meet point rather than the office?
     *
     * Answers the question for BOTH sides of a handover:
     *   • the RECEIVING rider — he has an order he collected off the van within
     *     the window (`handover_at`), so he is standing wherever the van was;
     *   • the VAN DRIVER — he has departed on a trip that has not ended. He never
     *     scans a handover, so nothing else would place him on the road.
     *
     * Cheap and fail-safe: two indexed reads, and any error (or a server where
     * batch 14 has not run) returns false = today's behaviour exactly.
     */
    private function riderIsAtVanMeetPoint(int $riderId): bool
    {
        static $memo = [];
        if (array_key_exists($riderId, $memo)) return $memo[$riderId];

        $windowMinutes = 45;
        try {
            if (!\Schema::hasColumn('t_crm_prod_order', 'handover_at')) {
                return $memo[$riderId] = false;
            }

            // Receiving side: collected something off the van very recently.
            $justCollected = \DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $riderId)
                ->where('order_status', 'out_for_delivery')
                ->whereNotNull('handover_at')
                ->where('handover_at', '>=', now()->subMinutes($windowMinutes))
                ->exists();
            if ($justCollected) return $memo[$riderId] = true;

            // Driving side: out on a trip that has not been closed.
            // ⚠ TIME-BOUNDED: a trip the driver forgot to close must not make him
            //   count as "on the road" forever — that would permanently bypass the
            //   phantom-GPS office anchoring on every future first dispatch. 14h
            //   covers any real shift including a past-midnight run.
            if (!\Schema::hasTable('t_ops_van_trip')) {
                return $memo[$riderId] = false;
            }
            $onTheRoad = \DB::table('t_ops_van_trip')
                ->where('van_user_id', $riderId)
                ->whereNull('ended_at')
                ->whereNotNull('departed_at')
                ->where('departed_at', '>=', now()->subHours(14))
                ->exists();

            return $memo[$riderId] = $onTheRoad;
        } catch (\Throwable $e) {
            return $memo[$riderId] = false;
        }
    }

    /**
     * Is this user OUT ON THE ROAD IN THE VAN right now (the driving side only)?
     *
     * Deliberately narrower than `riderIsAtVanMeetPoint`, which also answers true
     * for a rider who has just collected off the van. Used for the start-grace
     * rule: the +5 minutes exists so a rider can walk out and reach his
     * motorbike, and a driver already sitting in a running van has no walk to
     * make (owner ruling: "no 5 min headstart needed here" for the van driver's
     * second wave). The receiving rider's grace is deliberately left alone —
     * that was never ruled on, and shaving 5 minutes off his promises would make
     * him read late to customers.
     *
     * Same 14h bound and fail-safe-false as riderIsAtVanMeetPoint.
     */
    private function riderIsDrivingVanNow(int $riderId): bool
    {
        static $memo = [];
        if (array_key_exists($riderId, $memo)) return $memo[$riderId];
        try {
            if (!\Schema::hasTable('t_ops_van_trip')) return $memo[$riderId] = false;
            return $memo[$riderId] = \DB::table('t_ops_van_trip')
                ->where('van_user_id', $riderId)
                ->whereNull('ended_at')
                ->whereNotNull('departed_at')
                ->where('departed_at', '>=', now()->subHours(14))
                ->exists();
        } catch (\Throwable $e) {
            return $memo[$riderId] = false;
        }
    }

    /** Ping freshness bands for the store's "time from" choice (owner, Sep-28). */
    const RIDER_FIX_FRESH_S = 300;   // ≤5 min: his location is the default
    const RIDER_FIX_AMBER_S = 600;   // ≤10 min: still selectable, marked "may be off"

    /**
     * First-dispatch persistent-phantom backstop: a fix further than this from the office
     * is not trusted as the start of a FIRST dispatch. ONE number for the automatic pick
     * (selectDispatchOrigin) and the sheet's phantom guard (dispatchPreview, Sep-29).
     */
    const FIRST_DISPATCH_FAR_M = 5000.0;

    /**
     * Where is the rider RIGHT NOW, and how much can we trust it? (Sep-2026)
     *
     * The ONE reading behind the store's "time from his location / the office"
     * sheet, the explicit `origin=rider` dispatch, the location-based mid-run
     * signal and the position stamped on the ETA log — so all four always agree.
     *
     * Newest fix of the last 30 min that is physically possible (inside the
     * Pakistan box AND within the phantom ceiling of the office), preferring one
     * with ≤150 m accuracy. Returns freshness:
     *   'fresh' ≤5 min · 'aging' ≤10 min · 'stale' older · 'none' no usable fix
     */
    private function riderPositionNow(int $riderId): array
    {
        $out = ['fix' => null, 'age_s' => null, 'accuracy_m' => null, 'distance_m' => null,
                'freshness' => 'none', 'at_office' => false, 'implausible' => false, 'office' => null];
        try {
            $office = \App\Services\LocationService::getPrimaryBaseLocation();
            if ($office && $office->latitude && $office->longitude) {
                $out['office'] = $office;
            }
            $fixes = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->where('captured_at', '>=', now()->subMinutes(30))
                ->whereNotNull('latitude')->whereNotNull('longitude')
                ->orderBy('captured_at', 'desc')
                ->limit(60)
                ->get(['latitude', 'longitude', 'accuracy', 'captured_at']);

            $phantomM = $this->phantomOriginMetres();
            $dist = function ($f) use ($office) {
                return ($office && $office->latitude && $office->longitude)
                    ? (int) round(\App\Services\LocationService::calculateDistance(
                        $f->latitude, $f->longitude, $office->latitude, $office->longitude))
                    : null;
            };
            $possible = $fixes->filter(function ($f) use ($dist, $phantomM) {
                if (!\App\Services\LocationService::isPlausibleFix($f->latitude, $f->longitude)) return false;
                $d = $dist($f);
                return $d === null || $d <= $phantomM;
            })->values();
            if ($fixes->isNotEmpty() && $possible->isEmpty()) {
                $out['implausible'] = true;   // the phone is reporting somewhere impossible
            }
            $fix = $possible->first(fn ($f) => $f->accuracy === null || (float) $f->accuracy <= 150.0)
                ?: $possible->first();
            if (!$fix) {
                return $out;
            }
            /**
             * ⚠ Age = time since this fix ARRIVED, deliberately. The phone's own `fix_age_s` is
             *   NOT added (tried and withdrawn, 29-Sep review): the native tracker only takes a
             *   new fix after 10 m of movement and re-sends the last one on its 5-min timer, so an
             *   "old" fix mostly means "he has not moved" — his position is still right. Adding
             *   that age turned standing riders stale (sheet, mid-run signal, cancel stamp).
             */
            $age = max(0, now()->timestamp - strtotime((string) $fix->captured_at));
            $out['fix'] = $fix;
            $out['age_s'] = $age;
            $out['accuracy_m'] = $fix->accuracy !== null ? (int) round((float) $fix->accuracy) : null;
            $out['distance_m'] = $dist($fix);
            $out['freshness'] = $age <= self::RIDER_FIX_FRESH_S ? 'fresh'
                : ($age <= self::RIDER_FIX_AMBER_S ? 'aging' : 'stale');
            $out['at_office'] = $out['freshness'] !== 'stale' && $out['distance_m'] !== null
                && $out['distance_m'] <= \App\Services\Riders\EtaPromiseService::OUT_OF_OFFICE_M;
        } catch (\Throwable $e) {
            \Log::warning('riderPositionNow failed (non-fatal)', ['rider_id' => $riderId, 'error' => $e->getMessage()]);
        }
        return $out;
    }

    /** "20 s ago" / "4 min ago" — the store sheet and dispatch notes. */
    private function pingAgeText(?int $s): string
    {
        if ($s === null) return 'no ping';
        if ($s < 60) return $s . ' s ago';
        if ($s < 3600) return intdiv($s, 60) . ' min ago';
        return intdiv($s, 3600) . ' h ago';
    }

    /**
     * "his GPS from 8 min ago (mid-run)" / "the office (no GPS in the last 30 min)" —
     * what the automatic pick (selectDispatchOrigin) would time the route from, for the
     * sheet's "Let the system decide" choice (Sep-29). Display only.
     */
    private function autoOriginLabel(array $auto, int $riderId): string
    {
        $fix = $auto['fix'] ?? null;
        $km = isset($auto['distance_from_store_m']) && $auto['distance_from_store_m'] !== null
            ? number_format($auto['distance_from_store_m'] / 1000, 1) . ' km' : null;
        if (!empty($auto['location']) && empty($auto['used_store']) && $fix) {
            $age = max(0, now()->timestamp - strtotime((string) $fix->captured_at));
            return 'his GPS from ' . $this->pingAgeText($age)
                 . (!empty($auto['is_mid_run']) ? ' (mid-run)' : ' (first dispatch of these orders)');
        }
        if (empty($auto['location'])) {
            return 'nowhere — no GPS and no office location set';
        }
        switch ($auto['source'] ?? '') {
            case 'store_far_gps':
                return 'the office (not on a delivery run; his GPS reads ' . ($km ?? 'far') . ' away)';
            case 'store_phantom_gps_midrun':
                return 'the office (his phone is reporting an impossible location)';
            case 'store_no_gps':
            case 'store_no_gps_midrun':
                return 'the office (no GPS from his phone in the last 30 min)';
        }
        return 'the office';
    }

    /**
     * Is this account a rider the store dispatches for (C9, Sep-29)? Active login AND
     * either an active rider profile (the "Delivery Rider" tick — the assign list's own
     * rule) or out-for-delivery orders on his name right now (a man being dispatched is
     * by definition a rider, even an unticked stand-in).
     */
    private function isDispatchableRider(int $userId): bool
    {
        try {
            $active = \DB::table('t_sys_user')->where('id', $userId)->where('is_active', 1)->exists();
            if (!$active) return false;
            if (\DB::table('t_ops_rider_profile')->where('user_id', $userId)->where('active', 1)->exists()) {
                return true;
            }
            return \DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $userId)
                ->where('order_status', 'out_for_delivery')
                ->exists();
        } catch (\Throwable $e) {
            return false;
        }
    }

    /**
     * 🧭 What the store sees BEFORE pressing Dispatch for a rider (Sep-2026).
     *
     * GET /rider/{riderId}/dispatch-preview — read-only, writes nothing.
     * Answers: where is he, how old is that ping, is he at the office, and which
     * origin should the sheet pre-select? The sheet only ASKS when he is away
     * from the office; at the office both answers are the same place.
     */
    public function dispatchPreview(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            if (!$this->canManageRiderRoute($user, $riderId)) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }
            $rider = \DB::table('t_sys_user')->where('id', $riderId)->select('id', 'fullname')->first();
            if (!$rider) {
                return response()->json(['success' => false, 'message' => 'Rider not found'], 404);
            }
            // C9 (Sep-29): riders only — this endpoint reads a live GPS position, so it
            // must not answer for any staff account id. The new sheet treats a refusal
            // like any failed preview: the server's automatic pick, as before.
            if (!$this->isDispatchableRider((int) $riderId)) {
                return response()->json(['success' => false, 'message' => 'Not a rider'], 404);
            }
            $pos = $this->riderPositionNow((int) $riderId);
            $fresh = $pos['freshness'];

            // What the server would pick with NO origin sent ("Let the system decide").
            // selectDispatchOrigin is read-only (DB reads only), so asking costs nothing.
            $auto = $this->selectDispatchOrigin((int) $riderId);

            // rider option: enabled (fresh) · amber (5–10 min) · disabled (older / none)
            $riderOption = $fresh === 'fresh' ? 'enabled' : ($fresh === 'aging' ? 'amber' : 'disabled');
            $disabledReason = null;
            $amberReason = $riderOption === 'amber' ? 'Ping is a few minutes old — times may be a little off.' : null;
            if ($riderOption === 'disabled') {
                $disabledReason = $pos['implausible']
                    ? "His phone is reporting an impossible location (GPS fault) — times will be from the office."
                    : ($pos['fix'] ? 'Last ping ' . $this->pingAgeText($pos['age_s']) . ' — he has likely moved. Ask him to open the app, then press again.'
                                   : 'No GPS from his phone in the last 30 min. Ask him to open the app, then press again.');
            }

            /**
             * B2 — the phantom-GPS guard on a FIRST dispatch (Sep-29). Same test the automatic
             * pick uses: not mid-run, not at a van meet point, and his fix is beyond the 5 km
             * first-dispatch backstop — the Jul-2026 "phone at the store says 16 km NW" shape.
             * Never pre-selected, never 'enabled'; still one tap away (staff may know better).
             */
            $phantomSuspect = false;
            if ($riderOption !== 'disabled' && empty($auto['is_mid_run'])
                && $pos['distance_m'] !== null && $pos['distance_m'] > self::FIRST_DISPATCH_FAR_M) {
                $phantomSuspect = true;
                $riderOption = 'amber';
                $amberReason = 'Not on a delivery run and his phone says '
                    . number_format($pos['distance_m'] / 1000, 1) . ' km away — often a wrong GPS fix. Check with him before choosing.';
            }

            return response()->json([
                'success'  => true,
                'rider'    => ['id' => (int) $rider->id, 'name' => $rider->fullname],
                'position' => $pos['fix'] ? [
                    'latitude'     => (float) $pos['fix']->latitude,
                    'longitude'    => (float) $pos['fix']->longitude,
                    'accuracy_m'   => $pos['accuracy_m'],
                    'captured_at'  => $pos['fix']->captured_at,
                    'age_s'        => $pos['age_s'],
                    'age_text'     => $this->pingAgeText($pos['age_s']),
                    'distance_m'   => $pos['distance_m'],
                    'distance_text'=> $pos['distance_m'] === null ? null
                        : ($pos['distance_m'] >= 1000 ? number_format($pos['distance_m'] / 1000, 1) . ' km' : $pos['distance_m'] . ' m'),
                ] : null,
                'freshness'       => $fresh,
                'at_office'       => $pos['at_office'],
                // ask only when he is NOT at the office — otherwise both are the same place
                'ask'             => !$pos['at_office'],
                'rider_option'    => $riderOption,
                'rider_disabled_reason' => $disabledReason,
                // Why "his location" is amber (old ping, or the B2 phantom guard).
                'rider_amber_reason'    => $amberReason,
                'rider_phantom_suspect' => $phantomSuspect,
                // Pre-selected only when the ping is FRESH (owner: "rider location only if
                // it's fresh"); an amber ping stays one tap away.
                'default_origin'  => ($riderOption === 'enabled' && !$pos['at_office']) ? 'rider' : 'office',
                // B1 (owner D2, Sep-29): the sheet's default — his location only when fresh AND
                // trustworthy, otherwise "Let the system decide" (no origin sent = automatic).
                'default_choice'  => ($riderOption === 'enabled' && !$pos['at_office']) ? 'rider' : 'auto',
                'auto_origin'     => [
                    'source'     => $auto['source'],
                    'kind'       => (!empty($auto['location']) && empty($auto['used_store'])) ? 'rider' : 'office',
                    'is_mid_run' => (bool) $auto['is_mid_run'],
                    'label'      => $this->autoOriginLabel($auto, (int) $riderId),
                ],
                'office'          => $pos['office'] ? ['latitude' => (float) $pos['office']->latitude,
                                                       'longitude' => (float) $pos['office']->longitude] : null,
            ]);
        } catch (\Throwable $e) {
            \Log::error('dispatchPreview failed', ['rider_id' => $riderId, 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Could not read his location'], 500);
        }
    }

    private function selectDispatchOrigin(int $riderId): array
    {
        // Tunables — kept inline so this stays a single-file, cache-free deploy.
        $windowMinutes  = 30;       // how far back to look for a GPS fix
        $accuracyMaxM   = 150.0;    // fixes worse than this are "low confidence"
        $clusterRadiusM = 1500.0;   // a fix within this of the consensus is trusted
        $farBackstopM   = self::FIRST_DISPATCH_FAR_M;   // even anchored, beyond this ⇒ persistent phantom
        // ⭐ PHANTOM CEILING (Sep-2026). Beyond this a fix is not "far", it is
        //    IMPOSSIBLE, and it may not be used as an origin on ANY branch.
        //    See phantomOriginMetres() for why the number is what it is.
        $phantomM       = $this->phantomOriginMetres();

        // ⭐ Aug-2026 — a rider dispatching AT A VAN MEET POINT is out on the road,
        //   even on his first dispatch of the day. Without this, the first-dispatch
        //   branch below sees a position >5 km from the office, calls it a phantom
        //   fix, and snaps the origin BACK to the office — so every ETA in that
        //   wave is computed from a place he is nowhere near.
        //
        //   Two ways to be at a meet point, and BOTH are needed:
        //     • the receiving rider — he just scanned orders off the van;
        //     • the VAN DRIVER himself — who never scans a handover (the riders
        //       do), so the scan-based test alone would miss him entirely. He is
        //       covered by his own live van leg.
        $isMidRun = $this->riderIsMidRun($riderId)
                 || $this->riderIsAtVanMeetPoint($riderId);

        // Deliveries ALWAYS start from the primary office — that's the real
        // dispatch origin for every rider. The rider's *assigned* location is
        // only his attendance / supply-pickup point (e.g. LaCarne) and can be
        // kilometres away, so it must NOT be the dispatch reference. Fall back
        // to the assigned location only if no primary office is configured.
        $store = \App\Services\LocationService::getPrimaryBaseLocation()
            ?? \App\Services\LocationService::getUserAssignedLocation($riderId);
        $storeOk = $store && $store->latitude && $store->longitude;

        // Recent trail (newest first). One cheap indexed read; capped for safety.
        $fixes = \DB::table('t_ops_rider_location')
            ->where('user_id', $riderId)
            ->where('captured_at', '>=', now()->subMinutes($windowMinutes))
            ->whereNotNull('latitude')->whereNotNull('longitude')
            ->orderBy('captured_at', 'desc')
            ->limit(100)
            ->get(['latitude', 'longitude', 'accuracy', 'captured_at']);

        // Accuracy-filtered subset. NULL accuracy is allowed through (many
        // native fixes omit it); the consensus/backstop below still guards it.
        $credible = $fixes->filter(function ($f) use ($accuracyMaxM) {
            return $f->accuracy === null || (float) $f->accuracy <= $accuracyMaxM;
        })->values();

        $distFromStore = function ($fix) use ($store, $storeOk) {
            if (!$fix || !$storeOk) {
                return null;
            }
            return (int) round(\App\Services\LocationService::calculateDistance(
                $fix->latitude, $fix->longitude, $store->latitude, $store->longitude
            ));
        };

        $storeLocation = function () use ($store, $storeOk) {
            return $storeOk
                ? (object) ['latitude' => $store->latitude, 'longitude' => $store->longitude, 'captured_at' => null]
                : null;
        };

        // A fix we are willing to stand on. A NULL distance means no office is
        // configured, so there is nothing to judge against — allow it, which
        // keeps behaviour identical on a server without a primary location.
        $plausible = function ($fix) use ($distFromStore, $phantomM) {
            $d = $distFromStore($fix);
            return $d === null || $d <= $phantomM;
        };

        // --- MID-RUN: trust the rider's live GPS, prefer the confident fix. ---
        if ($isMidRun) {
            // ⭐ PLAUSIBILITY IS APPLIED BEFORE THE ACCURACY PREFERENCE, and the
            //    order matters more than it looks. A WiFi-mislocated fix reports
            //    EXCELLENT accuracy — Aug-31 the phone claimed 6.7 m while sitting
            //    3,878 km away — so choosing by accuracy first actively selects
            //    the most confident lie. Neither existing filter could catch it:
            //    60 of 225 phantom fixes passed the 150 m accuracy test, and the
            //    consensus check passed too because EVERY fix in the window was
            //    the same wrong place, so they agreed with each other.
            $sane    = $credible->filter($plausible)->values();
            $saneRaw = $fixes->filter($plausible)->values();
            $fix     = $sane->first() ?: $saneRaw->first();

            if ($fix) {
                return [
                    'location'              => $fix,
                    'used_store'            => false,
                    'source'                => $sane->isNotEmpty() ? 'rider_gps_midrun' : 'rider_gps_midrun_lowacc',
                    'note'                  => 'Mid-run re-dispatch — used live rider GPS.',
                    'fix'                   => $fix,
                    'distance_from_store_m' => $distFromStore($fix),
                    'is_mid_run'            => true,
                    'phantom'               => false,
                ];
            }

            // Nothing usable. "The phone gave us nothing" and "everything the
            // phone gave us is impossible" are DIFFERENT faults needing different
            // advice from the rider, so they are reported apart rather than both
            // becoming a generic "GPS not active".
            $phantomFix = $credible->first() ?: $fixes->first();
            if ($phantomFix) {
                return [
                    'location'              => $storeLocation(),
                    'used_store'            => $storeOk,
                    'source'                => 'store_phantom_gps_midrun',
                    'note'                  => 'Mid-run but every recent fix was implausibly far — used office location.',
                    'fix'                   => $phantomFix,
                    'distance_from_store_m' => $distFromStore($phantomFix),
                    'is_mid_run'            => true,
                    'phantom'               => true,
                ];
            }

            return [
                'location'              => $storeLocation(),
                'used_store'            => $storeOk,
                'source'                => 'store_no_gps_midrun',
                'note'                  => 'Mid-run but no recent GPS — fell back to office location.',
                'fix'                   => null,
                'distance_from_store_m' => null,
                'is_mid_run'            => true,
                'phantom'               => false,
            ];
        }

        // --- FIRST DISPATCH: anchor on the rider's own recent consensus. ------
        $fix = null;
        if ($credible->isNotEmpty()) {
            // Robust centre of the recent trail. Median tolerates up to ~half
            // the fixes being phantom outliers without moving off the real spot.
            $medLat = $this->medianOf($credible->pluck('latitude')->map('floatval')->all());
            $medLng = $this->medianOf($credible->pluck('longitude')->map('floatval')->all());

            // Newest credible fix that agrees with the consensus = the rider's
            // real current position (skips a fresh phantom that jumped away).
            foreach ($credible as $f) {
                $d = \App\Services\LocationService::calculateDistance($f->latitude, $f->longitude, $medLat, $medLng);
                if ($d <= $clusterRadiusM) {
                    $fix = $f;
                    break;
                }
            }
            $fix = $fix ?: $credible->first();
        } else {
            $fix = $fixes->first(); // nothing credible — raw fix, guarded below
        }

        $dist = $distFromStore($fix);

        // Persistent-phantom backstop: even the consensus sits absurdly far from
        // the store (phone stuck on a wrong spot). No legitimate dispatch point
        // is 10 km from the store, so use the store instead.
        if ($fix && $storeOk && $dist !== null && $dist > $farBackstopM) {
            return [
                'location'              => $storeLocation(),
                'used_store'            => true,
                'source'                => 'store_far_gps',
                'note'                  => "First-dispatch GPS was {$dist} m from the office — used office location instead.",
                'fix'                   => $fix,
                'distance_from_store_m' => $dist,
                'is_mid_run'            => false,
                // Same rejection, but "16 km away" and "3,878 km away" need
                // different advice: one is a drifting fix, the other is a phone
                // being told the wrong country by a mislocated WiFi router.
                'phantom'               => $dist > $phantomM,
            ];
        }

        if ($fix) {
            return [
                'location'              => $fix,
                'used_store'            => false,
                'source'                => 'rider_gps_anchored',
                'note'                  => 'First dispatch — used rider GPS (recent consensus position).',
                'fix'                   => $fix,
                'distance_from_store_m' => $dist,
                'is_mid_run'            => false,
                'phantom'               => false,
            ];
        }

        // No usable GPS at all → store fallback (unchanged behaviour).
        return [
            'location'              => $storeLocation(),
            'used_store'            => $storeOk,
            'source'                => 'store_no_gps',
            'note'                  => 'No recent rider GPS — used office location.',
            'fix'                   => null,
            'distance_from_store_m' => null,
            'is_mid_run'            => false,
            'phantom'               => false,
        ];
    }

    /**
     * How far from the office a coordinate may be before we call it impossible
     * rather than merely far. Used for BOTH the rider's origin and the customer
     * pins, because the same fault produces both.
     *
     * WHY 80 km. Measured against 51,056 real fixes (12 Aug – 1 Sep 2026):
     *   • furthest a rider has ever legitimately been:  35.6 km  (a genuine far
     *     run on 15 Aug, three riders, and the van meet points sit inside this)
     *   • closest a phantom fix has ever been:         172.2 km
     *   • fixes recorded between 60 km and 172 km:            0
     * 80 km sits in that empty band — 2.2× the furthest real position, and less
     * than half the nearest phantom. It exists to catch "the phone thinks it is
     * in Beijing", NOT to second-guess a long delivery.
     *
     * DELIBERATELY NOT the first-dispatch 5 km backstop: a rider mid-run — or one
     * standing at a van meet point — is legitimately tens of kilometres out, so
     * reusing 5 km here would reject real positions all day.
     */
    private function phantomOriginMetres(): float
    {
        $m = (float) $this->attnConfig('DISPATCH_PHANTOM_ORIGIN_M', 80000);
        // A zero / negative / unparseable override must not silently disable the
        // guard — that would restore exactly the bug this exists to prevent.
        return $m > 0 ? $m : 80000.0;
    }

    /**
     * The dispatch origin explained to the team, in Roman Urdu, in the ONE case
     * they can act on: we did not use the rider's own position.
     *
     * Three different faults, three different messages — this distinction is the
     * whole point. Telling a rider "GPS not active" when his GPS is on and
     * reporting 6.7 m accuracy sends him to check a setting that is already
     * correct, while the thing that actually fixes it (turn the WiFi off) is
     * something he would never guess.
     */
    private function dispatchOriginWarning(array $origin, string $riderName, string $what = 'Delivery times'): string
    {
        // 1. PHANTOM — GPS is on and confident, and somewhere impossible.
        if (!empty($origin['phantom'])) {
            $km  = number_format(((int) $origin['distance_from_store_m']) / 1000);
            $fix = $origin['fix'] ?? null;

            // "Pakistan se bahar" lands where a bare number does not. A distance
            // reads like an app error the rider can't act on; being told his
            // phone thinks he is out of the country tells him instantly that the
            // PHONE is wrong, which is the whole point of the message.
            $outside = $fix && $this->isOutsidePakistan(
                isset($fix->latitude)  ? (float) $fix->latitude  : null,
                isset($fix->longitude) ? (float) $fix->longitude : null
            );
            $where = $outside
                ? "phone keh raha hai ke aap Pakistan se BAHAR hain (takreeban {$km} km door)"
                : "phone aap ko office se takreeban {$km} km door dikha raha hai";

            return "⚠️ {$riderName} ke phone ki location galat aa rahi hai — {$where}. "
                 . "{$what} office se lagaye gaye hain — ye sirf andaza hain.\n"
                 . "Theek karne ka tareeqa: WiFi band karein, mobile data aur Location on rakhein, "
                 . "phir app dobara kholein aur dobara Dispatch karein.";
        }

        // 2. DRIFTING — plausible place, just too far from the office to be the
        //    start of a first dispatch. Opening the app usually refreshes it.
        //    lcfirst: $what starts a sentence in case 1 but sits mid-sentence here.
        if ($origin['source'] === 'store_far_gps' && $origin['distance_from_store_m']) {
            $km = number_format($origin['distance_from_store_m'] / 1000, 1);
            return "⚠️ {$riderName} ki GPS reading office se takreeban {$km} km door thi, "
                 . "is liye " . lcfirst($what) . " office se lagaye gaye hain. "
                 . "Unse kahein ke app khol kar GPS refresh karein.";
        }

        // 3. GENUINELY ABSENT — no fix at all in the window.
        return "⚠️ {$riderName} ka GPS on nahi hai — " . lcfirst($what) . " office se lagaye gaye hain "
             . "(sirf andaza). Location on kar ke app kholein, phir dobara Dispatch karein.";
    }

    /**
     * Is this coordinate outside Pakistan?
     *
     * Used ONLY to word a warning more vividly — never to make a routing or
     * money decision — so the box is deliberately GENEROUS. Telling a rider he
     * is "outside Pakistan" when he is not would destroy the credibility of the
     * whole message, and a false negative costs nothing: the warning simply
     * falls back to reporting the distance, which is still true.
     *
     * Pakistan spans roughly lat 23.6–37.1, lng 60.9–77.8. The margin below puts
     * Gwadar (25.1, 62.3), Karachi (24.9, 67.1) and Gilgit (35.9, 74.3) safely
     * inside, while Beijing (39.9, 116.4) and Ottawa (45.4, -75.7) — the two
     * places phones have actually claimed — are far outside.
     */
    private function isOutsidePakistan(?float $lat, ?float $lng): bool
    {
        if ($lat === null || $lng === null) {
            return false;
        }
        return $lat < 23.0 || $lat > 37.5 || $lng < 60.5 || $lng > 78.5;
    }

    /**
     * Straight-line stand-in for Google's leg times.
     *
     * Used ONLY when Google cannot answer. It is a poor estimate and it is
     * labelled as one everywhere it surfaces — but a rough time beats the old
     * behaviour, which was to refuse the dispatch outright and leave every stop
     * with no time at all while the rider left anyway (Aug-31).
     *
     * The per-leg cap is load-bearing: without it one bad coordinate that slipped
     * through would text a customer an ETA measured in days.
     */
    private function estimateLegsByStraightLine(array $waypoints): array
    {
        $kmh = max(5, min(80, (int) $this->attnConfig('DISPATCH_FALLBACK_SPEED_KMH', 25)));
        $legs = [];
        $total = 0;

        for ($i = 0, $n = count($waypoints) - 1; $i < $n; $i++) {
            $metres = $this->haversineDistance(
                (float) $waypoints[$i]['lat'],     (float) $waypoints[$i]['lng'],
                (float) $waypoints[$i + 1]['lat'], (float) $waypoints[$i + 1]['lng']
            );
            // ×1.3: roads are never straight. Errs toward allowing more time,
            // which is the safe direction for a promise to a customer.
            $minutes = (int) max(1, min(180, round((($metres / 1000) * 1.3) / $kmh * 60)));
            $legs[]  = $minutes;
            $total  += $minutes;
        }

        return [
            'total_duration' => $total,
            'legs'           => $legs,
            'source'         => 'straight_line_estimate',
        ];
    }

    /**
     * Median of a numeric list (returns the lower-middle for even counts).
     * Small local helper for selectDispatchOrigin's consensus anchor.
     */
    private function medianOf(array $values): float
    {
        $values = array_values(array_filter($values, 'is_numeric'));
        sort($values);
        $n = count($values);
        if ($n === 0) {
            return 0.0;
        }
        return (float) $values[intdiv($n - 1, 2)];
    }

    /**
     * ⭐ Cancel dispatch for a rider's out_for_delivery orders.
     *
     * Clears the dispatch state (estimated_delivery_at, eta_calculated_at,
     * eta_calculated_by) so any "frozen" dispatched batch and the "Next
     * Dispatch" wave merge back into a single, undispatched set. Pressing
     * Dispatch afterwards re-times + re-routes everything together.
     *
     * Does NOT touch delivery_priority (the sequence) or order_status.
     * Authorized for store managers (view_open_orders) OR the rider themselves.
     *
     * @param int $riderId
     */
    public function cancelDispatch(Request $request, $riderId)
    {
        try {
            $user = Auth::user();

            if (!$this->canManageRiderRoute($user, $riderId)) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            // Capture WHICH orders are being cleared before we clear them — the
            // accountability log needs the ids, and after the update they're
            // indistinguishable from orders that were never dispatched.
            $clearedIds = \DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $riderId)
                ->where('order_status', 'out_for_delivery')
                ->whereNotNull('eta_calculated_at')
                ->pluck('id')
                ->all();

            $affected = \DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $riderId)
                ->where('order_status', 'out_for_delivery')
                ->whereNotNull('eta_calculated_at')
                ->update([
                    'estimated_delivery_at' => null,
                    'eta_calculated_at' => null,
                    'eta_calculated_by' => null,
                ]);

            // A STORE cancel withdraws the old promise, so the next dispatch sets
            // a new one. A RIDER cancelling his own dispatch must NOT do that —
            // otherwise cancel-then-redispatch would launder his lateness. Both
            // are logged (with is_rider_self) so the difference is provable.
            // Where he was when the times were cleared: a store cancel while he is
            // out on the road is the store's re-plan, and must not later read as
            // "left without dispatch" (Sep-2026).
            $pos = $this->riderPositionNow((int) $riderId);
            \App\Services\Riders\EtaPromiseService::logCancel(
                (int) $riderId,
                $clearedIds,
                $user->id ?? null,
                [
                    'rider_distance_m' => $pos['fix'] && $pos['freshness'] !== 'stale' ? $pos['distance_m'] : null,
                    'rider_gps_age_s'  => $pos['age_s'],
                ]
            );

            \Log::info('Dispatch cancelled (ETAs cleared)', [
                'user_id' => $user->id,
                'rider_id' => $riderId,
                'orders_cleared' => $affected,
            ]);

            return response()->json([
                'success' => true,
                'message' => "Dispatch cancelled for {$affected} orders",
                'cleared_count' => $affected,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to cancel dispatch', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json([
                'success' => false,
                'message' => 'Failed to cancel dispatch: ' . $e->getMessage(),
            ], 500);
        }
    }
    
    /**
     * ⭐ Get multi-stop ETA from Google Maps Directions API
     * Returns leg durations for waypoints route
     * 
     * @param array $waypoints - Array of ['lat' => x, 'lng' => y]
     * @param string|null $failure OUT — why this returned null, in the caller's
     *        words rather than a guess. Every null return sets it. Aug-31 cost
     *        an evening to a log line that blamed "API error or monthly cap"
     *        for a ZERO_RESULTS, sending the owner to check Google billing that
     *        was never the problem: the cap was at 3,720 of 10,000.
     * @return array|null - ['total_duration' => minutes, 'legs' => [min, min, ...]]
     */
    private function getMultiStopEtaFromGoogle(array $waypoints, ?string &$failure = null): ?array
    {
        $failure = null;

        if (count($waypoints) < 2) {
            $failure = 'fewer_than_two_waypoints';
            return null;
        }

        // Check monthly usage limit
        $monthKey = date('Y-m');
        $usage = \DB::table('t_sys_api_usage')
            ->where('api_name', 'google_directions')
            ->where('month_key', $monthKey)
            ->first();

        $currentCount = $usage->call_count ?? 0;
        if ($currentCount >= 10000) {
            \Log::warning('Google Maps API monthly limit reached for multi-stop ETA', [
                'call_count' => $currentCount, 'month_key' => $monthKey,
            ]);
            $failure = 'monthly_cap_reached';
            return null;
        }

        $apiKey = config('services.google_maps.directions_key');
        if (empty($apiKey)) {
            \Log::warning('Google Maps API key not configured');
            $failure = 'no_api_key';
            return null;
        }

        try {
            // Build origin (first point)
            $origin = $waypoints[0]['lat'] . ',' . $waypoints[0]['lng'];
            
            // Build destination (last point)
            $lastIdx = count($waypoints) - 1;
            $destination = $waypoints[$lastIdx]['lat'] . ',' . $waypoints[$lastIdx]['lng'];
            
            // Build waypoints (intermediate points) - Google limits to 25 waypoints
            $intermediateWaypoints = [];
            for ($i = 1; $i < $lastIdx && $i <= 25; $i++) {
                $intermediateWaypoints[] = $waypoints[$i]['lat'] . ',' . $waypoints[$i]['lng'];
            }
            
            $client = new \GuzzleHttp\Client(['timeout' => 15]);
            
            $queryParams = [
                'origin' => $origin,
                'destination' => $destination,
                'mode' => 'driving',
                'departure_time' => 'now', // For traffic data
                'key' => $apiKey,
            ];
            
            if (!empty($intermediateWaypoints)) {
                $queryParams['waypoints'] = implode('|', $intermediateWaypoints);
            }
            
            $response = $client->get('https://maps.googleapis.com/maps/api/directions/json', [
                'query' => $queryParams
            ]);
            
            $data = json_decode($response->getBody()->getContents(), true);
            
            // Increment usage counter
            $this->incrementApiUsage('google_directions');
            
            if (($data['status'] ?? null) !== 'OK' || empty($data['routes'])) {
                $status = $data['status'] ?? 'unknown';
                \Log::warning('Google Maps multi-stop API error', [
                    'status'  => $status,
                    // Google explains ZERO_RESULTS / NOT_FOUND here when it can.
                    'message' => $data['error_message'] ?? null,
                    'stops'   => count($waypoints) - 1,
                ]);
                $failure = $status;
                return null;
            }
            
            $route = $data['routes'][0];
            $legs = [];
            $totalDuration = 0;
            
            foreach ($route['legs'] as $leg) {
                // Use duration_in_traffic if available
                $durationSeconds = $leg['duration_in_traffic']['value'] ?? $leg['duration']['value'];
                $durationMinutes = round($durationSeconds / 60);
                $legs[] = $durationMinutes;
                $totalDuration += $durationMinutes;
            }
            
            \Log::info('📍 Multi-stop ETA from Google', [
                'waypoints' => count($waypoints),
                'legs' => $legs,
                'total_minutes' => $totalDuration,
            ]);
            
            return [
                'total_duration' => $totalDuration,
                'legs' => $legs,
                'source' => 'google_maps',
            ];
            
        } catch (\Exception $e) {
            \Log::error('Google Maps multi-stop API call failed', [
                'error' => $e->getMessage(),
            ]);
            $failure = 'request_failed';
            return null;
        }
    }

    /**
     * Optimize delivery route using Google Directions API (optimize:true).
     * Returns suggested order sequence + per-leg ETAs without saving to DB (preview only).
     */
    public function optimizeRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();

            // Store managers (view_open_orders) OR the rider acting on own route
            if (!$this->canManageRiderRoute($user, $riderId)) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $rider = \DB::table('t_sys_user')->where('id', $riderId)->where('is_active', 1)->select('id', 'fullname')->first();
            if (!$rider) {
                return response()->json(['success' => false, 'message' => 'Rider not found'], 404);
            }

            // Same phantom-GPS guardrail as the "Get Times" dispatch path
            // (selectDispatchOrigin) so this route-optimisation PREVIEW can't
            // show a phantom-inflated route while the real dispatch is fine.
            $origin = $this->selectDispatchOrigin($riderId);
            if (!$origin['location']) {
                return response()->json([
                    'success' => false,
                    'message' => "⚠️ {$rider->fullname} ki location nahi mil rahi, aur office ki location bhi set nahi hai — "
                               . "is liye route nahi banaya ja sakta. Admin se kahein ke office location set kare.",
                ], 400);
            }
            $riderLocation    = $origin['location'];
            $usedShopLocation = $origin['used_store'];

            // 🚚 ON-VAN ORDERS ARE ROUTE-PLANNABLE TOO (Aug-2026). The whole point
            //    of sequencing while the boxes ride the van is that
            //    `delivery_priority` SURVIVES the handover — the rider collects a
            //    route that is already planned and only has to press Dispatch.
            //    The save half of that (updateDeliveryPriorities) has accepted
            //    `on_van` since Aug-4; this SUGGESTION half still refused, so
            //    "Auto Route" answered "no orders" about a list the store was
            //    looking at. Everything downstream is status-agnostic, and the
            //    apply step goes through the same whitelist.
            /**
             * ⭐ `processing` JOINS THE ROUTE (Sep-2026, owner ruling).
             *
             * The three sequencing halves had drifted apart: the SAVE half
             * (updateDeliveryPriorities) has whitelisted `processing` since Aug-2026 and the
             * store board counts it as sequenceable, but this SUGGESTION half did not — so the
             * 📋 Delivery Order button appeared for a rider whose orders were all still being
             * prepared, and Auto Route then answered "no orders to optimize" about the exact
             * list on screen. Manual reorder worked on the same rows the whole time.
             *
             * Pre-planning the route while the boxes are still being packed is the point of
             * the pre-plan feature; everything downstream is status-agnostic.
             */
            $orders = \DB::table('t_crm_prod_order as o')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->where('o.assigned_rider_user_id', $riderId)
                ->whereIn('o.order_status', ['out_for_delivery', 'on_van', 'processing'])
                ->select([
                    'o.id', 'o.order_number', 'o.delivery_priority', 'o.order_status',
                    'c.latitude', 'c.longitude', 'c.geocoded_latitude', 'c.geocoded_longitude',
                    'c.geocode_precision',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    \DB::raw('CONCAT(COALESCE(c.address1, ""), ", ", COALESCE(c.city, "")) as address_short'),
                ])
                ->orderByRaw('COALESCE(o.delivery_priority, 999) ASC, o.id ASC')
                ->get();

            if ($orders->isEmpty()) {
                return response()->json(['success' => false, 'message' => 'No orders to route — nothing is being prepared, on the van, or out for delivery for this rider'], 400);
            }

            $waypoints = [['lat' => (float)$riderLocation->latitude, 'lng' => (float)$riderLocation->longitude]];
            $ordersWithLocation = [];
            $unverifiedOrders = [];
            $noLocationOrders = [];
            $locationNotes = [];

            // Auto Route can only ORDER stops it can place on a map. Unlike dispatch
            // — which must never refuse, because the rider leaves regardless — a stop
            // with no location genuinely cannot be sequenced, so it is reported and
            // the client blocks (this is a suggestion tool; nothing operational stops).
            foreach ($orders as $order) {
                $loc = \App\Services\Location\CustomerLocationResolver::resolve($order);
                if ($loc['routable']) {
                    $waypoints[] = ['lat' => (float) $loc['latitude'], 'lng' => (float) $loc['longitude']];
                    $ordersWithLocation[] = $order;
                    if ($loc['tier'] !== \App\Services\Location\CustomerLocationResolver::TIER_VERIFIED) {
                        $unverifiedOrders[] = $order->order_number;
                    }
                } else {
                    $noLocationOrders[] = $order->order_number;
                }
                if ($loc['tier'] !== \App\Services\Location\CustomerLocationResolver::TIER_VERIFIED) {
                    $locationNotes[] = [
                        'order_id'      => (int) $order->id,
                        'order_number'  => $order->order_number,
                        'customer_name' => trim((string) $order->customer_name),
                        'tier'          => $loc['tier'],
                        'label'         => $loc['label'],
                        'short'         => $loc['short'],
                        'approximate'   => $loc['approximate'],
                        'routable'      => $loc['routable'],
                        'key'           => \App\Services\Location\CustomerLocationResolver::chipKey($loc['tier']),
                    ];
                }
            }

            if (count($ordersWithLocation) === 0) {
                return response()->json([
                    'success' => false,
                    'message' => 'None of these orders has a location pin, so a route cannot be worked out. Please add the pins first.',
                    'no_location_orders' => $noLocationOrders,
                    'location_notes' => $locationNotes,
                ], 400);
            }

            $result = $this->getOptimizedRouteFromGoogle($waypoints);

            if (!$result) {
                return response()->json(['success' => false, 'message' => 'Failed to optimize route (API error or limit reached)'], 500);
            }

            $stopTimeMinutes = 10;
            $now = now();
            $cumulativeMinutes = 0;
            $optimizedSequence = [];
            $waypointOrder = $result['waypoint_order'];

            foreach ($waypointOrder as $priority => $originalIndex) {
                $order = $ordersWithLocation[$originalIndex];
                $legDuration = $result['legs'][$priority] ?? 0;
                $cumulativeMinutes += $legDuration;
                $estimatedAt = $now->copy()->addMinutes(round($cumulativeMinutes));

                $optimizedSequence[] = [
                    'order_id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_name' => trim($order->customer_name),
                    'address_short' => trim($order->address_short),
                    // Lets a preview row say WHERE the box is (on the van / being packed /
                    // already on his run) — the route sheet mixes all three by design.
                    'status' => $order->order_status ?? null,
                    'priority' => $priority + 1,
                    'travel_minutes' => round($legDuration),
                    'cumulative_minutes' => round($cumulativeMinutes),
                    'estimated_at' => $estimatedAt->format('h:i A'),
                ];

                $cumulativeMinutes += $stopTimeMinutes;
            }

            // Flag orders with unusually long travel times (likely wrong GPS)
            $farOrders = [];
            foreach ($optimizedSequence as $item) {
                if ($item['travel_minutes'] > 60) {
                    $farOrders[] = "{$item['order_number']} ({$item['customer_name']}) — {$item['travel_minutes']} min away";
                }
            }

            $response = [
                'success' => true,
                'optimized_sequence' => $optimizedSequence,
                'total_time_minutes' => round($cumulativeMinutes - $stopTimeMinutes),
                'total_distance_km' => $result['total_distance_km'] ?? null,
                'orders_count' => count($optimizedSequence),
                'unverified_orders' => $unverifiedOrders,
                // Stops that could NOT be placed in the suggested order. The client
                // blocks on these so the team pins them before routing, rather than
                // silently receiving a sequence that is missing stops.
                'no_location_orders' => $noLocationOrders,
                'location_notes' => $locationNotes,
            ];

            if ($usedShopLocation) {
                // Same three-way explanation as dispatch, so the preview and the
                // real thing can never tell the team two different stories about
                // the same phone.
                $response['gps_warning'] = $this->dispatchOriginWarning($origin, $rider->fullname, 'Route aur times');
            }

            if (!empty($farOrders)) {
                $response['far_orders_warning'] = $farOrders;
            }

            return response()->json($response);

        } catch (\Exception $e) {
            \Log::error('Failed to optimize route', ['rider_id' => $riderId, 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to optimize route: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Nearest-neighbor route optimization using Google Directions.
     * 
     * Strategy: Starting from rider/shop, always go to the nearest unvisited
     * customer next. Uses Google Directions for real road travel times per leg.
     * Simple, predictable, and optimal for typical city delivery routes.
     * 
     * Falls back to haversine straight-line if Google API fails.
     */
    private function getOptimizedRouteFromGoogle(array $waypoints): ?array
    {
        if (count($waypoints) < 3) {
            $directResult = $this->getMultiStopEtaFromGoogle($waypoints);
            if (!$directResult) return null;
            return [
                'waypoint_order' => [0],
                'legs' => $directResult['legs'],
                'total_duration' => $directResult['total_duration'],
                'total_distance_km' => null,
            ];
        }

        $apiKey = config('services.google_maps.directions_key');
        if (empty($apiKey)) return null;

        $monthKey = date('Y-m');
        $usage = \DB::table('t_sys_api_usage')
            ->where('api_name', 'google_directions')
            ->where('month_key', $monthKey)
            ->first();

        if (($usage->call_count ?? 0) >= 10000) {
            \Log::warning('Google Maps API monthly limit reached for route optimization');
            return null;
        }

        try {
            // Build the nearest-neighbor sequence using haversine first (fast)
            $orderCount = count($waypoints) - 1; // exclude rider at index 0
            $visited = [];
            $sequence = []; // indices into $waypoints (1-based, orders only)
            $currentLat = $waypoints[0]['lat'];
            $currentLng = $waypoints[0]['lng'];

            for ($step = 0; $step < $orderCount; $step++) {
                $nearestIdx = null;
                $nearestDist = PHP_FLOAT_MAX;

                for ($i = 1; $i < count($waypoints); $i++) {
                    if (in_array($i, $visited)) continue;
                    $dist = $this->haversineDistance($currentLat, $currentLng, $waypoints[$i]['lat'], $waypoints[$i]['lng']);
                    if ($dist < $nearestDist) {
                        $nearestDist = $dist;
                        $nearestIdx = $i;
                    }
                }

                if ($nearestIdx === null) break;
                $visited[] = $nearestIdx;
                $sequence[] = $nearestIdx;
                $currentLat = $waypoints[$nearestIdx]['lat'];
                $currentLng = $waypoints[$nearestIdx]['lng'];
            }

            // Build the ordered route: rider → sequence of orders
            $orderedWaypoints = [$waypoints[0]];
            foreach ($sequence as $idx) {
                $orderedWaypoints[] = $waypoints[$idx];
            }

            // Get actual road travel times from Google Directions for this sequence
            $origin = $orderedWaypoints[0]['lat'] . ',' . $orderedWaypoints[0]['lng'];
            $lastIdx = count($orderedWaypoints) - 1;
            $destination = $orderedWaypoints[$lastIdx]['lat'] . ',' . $orderedWaypoints[$lastIdx]['lng'];

            $intermediateCoords = [];
            for ($i = 1; $i < $lastIdx; $i++) {
                $intermediateCoords[] = $orderedWaypoints[$i]['lat'] . ',' . $orderedWaypoints[$i]['lng'];
            }

            $client = new \GuzzleHttp\Client(['timeout' => 15]);
            $queryParams = [
                'origin' => $origin,
                'destination' => $destination,
                'mode' => 'driving',
                'departure_time' => 'now',
                'key' => $apiKey,
            ];

            if (!empty($intermediateCoords)) {
                // No optimize:true — we already determined the order via nearest-neighbor
                $queryParams['waypoints'] = implode('|', $intermediateCoords);
            }

            $response = $client->get('https://maps.googleapis.com/maps/api/directions/json', ['query' => $queryParams]);
            $data = json_decode($response->getBody()->getContents(), true);
            $this->incrementApiUsage('google_directions');

            $legs = [];
            $totalDuration = 0;
            $totalDistanceMeters = 0;

            if ($data['status'] === 'OK' && !empty($data['routes'])) {
                $route = $data['routes'][0];
                foreach ($route['legs'] as $leg) {
                    $durationSeconds = $leg['duration_in_traffic']['value'] ?? $leg['duration']['value'];
                    $durationMinutes = round($durationSeconds / 60);
                    $legs[] = $durationMinutes;
                    $totalDuration += $durationMinutes;
                    $totalDistanceMeters += $leg['distance']['value'] ?? 0;
                }
            } else {
                // Fallback: estimate using haversine at ~30 km/h
                \Log::warning('Google Directions failed for ordered route, using haversine fallback', ['status' => $data['status'] ?? 'unknown']);
                for ($i = 0; $i < count($orderedWaypoints) - 1; $i++) {
                    $distMeters = $this->haversineDistance(
                        $orderedWaypoints[$i]['lat'], $orderedWaypoints[$i]['lng'],
                        $orderedWaypoints[$i+1]['lat'], $orderedWaypoints[$i+1]['lng']
                    );
                    $minutes = round(($distMeters / 1000 / 30) * 60);
                    $legs[] = max(1, $minutes);
                    $totalDuration += $legs[count($legs) - 1];
                    $totalDistanceMeters += $distMeters;
                }
            }

            // Map sequence back to 0-based order indices
            $waypointOrder = array_map(fn($idx) => $idx - 1, $sequence);

            \Log::info('Optimized route (nearest-neighbor)', [
                'waypoint_order' => $waypointOrder,
                'legs' => $legs,
                'total_minutes' => $totalDuration,
                'total_distance_km' => round($totalDistanceMeters / 1000, 1),
            ]);

            return [
                'waypoint_order' => $waypointOrder,
                'legs' => $legs,
                'total_duration' => $totalDuration,
                'total_distance_km' => round($totalDistanceMeters / 1000, 1),
            ];

        } catch (\Exception $e) {
            \Log::error('Route optimization failed', ['error' => $e->getMessage()]);
            return null;
        }
    }


    /**
     * PREVIEW a pin from the written address — geocode it, save NOTHING.
     *
     * WHY A PREVIEW STEP EXISTS (Jul-28-2026)
     * The old button geocoded the address and wrote the VERIFIED coordinates in
     * one blind step. Those columns are the team's truth: the pin lock, the 150 m
     * checkout rule, delivery-region assignment and the customer app all read
     * them. Writing them from an unseen machine answer meant a sector-level guess
     * could be promoted into truth with nobody ever looking at it.
     *
     * Now the human sees the candidate on a map first and confirms it (or drags
     * it), so pressing the button is an actual verification rather than an act of
     * faith. The confirm then travels the ordinary
     * setCustomerVerifiedLocation() path with real coordinates.
     *
     * Two rules this endpoint keeps:
     *   - It writes NOTHING to the customer. A failed lookup can no longer leave
     *     the half-record it used to (URL saved, lat/lng NULL).
     *   - It enforces the SAME pin lock as the save. Showing a rider a pin he is
     *     not allowed to save would just be a confusing dead end.
     */
    public function previewLocationFromAddress(Request $request, $orderId)
    {
        try {
            $validated = $request->validate([
                'customer_id' => 'required|integer',
                'address'     => 'required|string',
                'source'      => 'nullable|string|in:shopify',
            ]);

            $customer = \App\Models\CRM\CustomerModel::find($validated['customer_id']);

            if (!$customer) {
                return response()->json([
                    'success' => false,
                    'message' => 'Customer not found',
                ], 404);
            }

            if ($this->riderPinBindApplies(Auth::user()) && $customer->isVerifiedPinLocked()) {
                return response()->json([
                    'success' => false,
                    'message' => "This customer's location is locked. Ask the store to unlock it before changing the pin.",
                    'pin_locked' => true,
                ], 423);
            }

            $original = trim($validated['address']);
            $cleaned  = \App\Services\GeocodingService::cleanAddressForGeocoding($original);

            // The Shopify store screen passes ids from t_crm_shopify_order, which
            // overlap t_crm_prod_order ids (golden rule: same number, unrelated
            // orders). A staging id must never be recorded where a reader would
            // join it against prod orders — so it goes to NULL and the trigger
            // name carries the context instead.
            $fromShopify = ($validated['source'] ?? null) === 'shopify';

            $geo = \App\Services\GeocodingService::geocodeAddress($original, $customer->city, [
                'customer_id' => $customer->id,
                'order_id'    => (!$fromShopify && is_numeric($orderId)) ? (int) $orderId : null,
                'trigger'     => $fromShopify ? 'store_preview_shopify' : 'store_preview',
                'user_id'     => Auth::id(),
            ]);

            $precision = $geo['precision'] ?? null;

            \Log::info('Geocode preview from address', [
                'order_id'    => $orderId,
                'customer_id' => $customer->id,
                'original'    => $original,
                'cleaned'     => $cleaned,
                'was_cleaned' => $cleaned !== $original,
                'found'       => (bool) $geo,
                'precision'   => $precision,
                'by'          => Auth::user()->fullname ?? null,
            ]);

            if (!$geo) {
                return response()->json([
                    'success'          => true,
                    'found'            => false,
                    'original_address' => $original,
                    'cleaned_address'  => $cleaned,
                    'was_cleaned'      => $cleaned !== $original,
                    'message'          => "Google could not place this address precisely enough to trust. "
                                        . 'Please drop the pin on the map, or ask the customer for their location.',
                ]);
            }

            // Plain-English wording for the confirm screen. It describes what
            // Google actually matched, so the person confirming knows whether they
            // are accepting a rooftop or a best guess at the street.
            $note = match ($precision) {
                \App\Services\Location\CustomerLocationResolver::PRECISION_EXACT =>
                    'Google matched the building. Check the pin looks right, then confirm.',
                \App\Services\Location\CustomerLocationResolver::PRECISION_STREET =>
                    'Google matched the street but not the exact house. Move the pin onto the right house if you know it.',
                default =>
                    'Google could only match the area. Move the pin onto the right spot before confirming.',
            };

            return response()->json([
                'success'          => true,
                'found'            => true,
                'latitude'         => $geo['latitude'],
                'longitude'        => $geo['longitude'],
                'precision'        => $precision,
                'matched_address'  => $geo['matched_address'] ?? null,
                'original_address' => $original,
                'cleaned_address'  => $cleaned,
                'was_cleaned'      => $cleaned !== $original,
                'message'          => $note,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Invalid data',
                'errors'  => $e->errors(),
            ], 422);
        } catch (\Exception $e) {
            \Log::error('Geocode preview failed', [
                'order_id' => $orderId,
                'error'    => $e->getMessage(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Could not look up this address right now. Please drop the pin on the map.',
            ], 500);
        }
    }

    /**
     * Quick verify location from address (for Store Mode)
     * Geocodes the address and saves it as verified location
     *
     * LEGACY as of Jul-28-2026 — superseded by previewLocationFromAddress() plus
     * an ordinary confirmed save. Kept working because phones on the old APK
     * still call it until every store device is updated.
     */
    public function setVerifiedLocationFromAddress(Request $request, $orderId)
    {
        try {
            $validated = $request->validate([
                'customer_id' => 'required|integer',
                'address' => 'required|string',
            ]);

            $customer = \App\Models\CRM\CustomerModel::find($validated['customer_id']);

            if (!$customer) {
                return response()->json([
                    'success' => false,
                    'message' => 'Customer not found',
                ], 404);
            }

            // Verified-pin lock (same rule as setCustomerVerifiedLocation): a
            // rider may not override an existing verified pin without a store/web
            // unlock grant. First-ever pin is never locked.
            $isBoundRider = $this->riderPinBindApplies(Auth::user());
            if ($isBoundRider && $customer->isVerifiedPinLocked()) {
                // Same as the sibling method: refusing a rider also asks the
                // store, so he never has to make the phone call. This path knows
                // the order, so the banner can name it.
                $requested = \App\Services\Location\PinUnlockRequestService::raise(
                    $customer,
                    Auth::id(),
                    $orderId
                );

                return response()->json([
                    'success' => false,
                    'message' => $requested
                        ? "This customer's location is locked. The store has been asked to unlock it — you'll be able to save as soon as they do."
                        : "This customer's location is locked. Ask the store to unlock it before changing the pin.",
                    'pin_locked' => true,
                    'unlock_requested' => $requested,
                ], 423);
            }

            // Create Google Maps search URL from address
            $googleMapsUrl = 'https://www.google.com/maps/search/?api=1&query=' . urlencode($validated['address']);

            // Prepare update data (grant handling — see the sibling method). This
            // button is THE temporary-pin case: the store places an approximate,
            // address-derived pin so dispatch can time the stop, and the rider is
            // expected to replace it with the real one on arrival. So a store save
            // here deliberately leaves the 24h grace window open.
            $updateData = array_merge([
                'updated_by' => Auth::id(),
                'verified_location_saved_by' => Auth::id(),
                'verified_location_saved_at' => now(),
                'verified_location_url' => $googleMapsUrl,
            ], $isBoundRider
                ? \App\Models\CRM\CustomerModel::pinGrantConsumed()
                : \App\Models\CRM\CustomerModel::pinGrantGrace(
                    $customer->verified_pin_unlocked_until,
                    $customer->verified_pin_unlocked_by,
                    Auth::id()
                ));

            // NOTE: whether any of the above is actually written is decided below.
            // Until Jul-28-2026 this update ran unconditionally, so a failed
            // geocode still stamped verified_location_url + saved_by/saved_at with
            // lat/lng left NULL. That half-record reads as "someone verified this
            // customer" to three different consumers — the rider bundle
            // (verified_location_url || lat&&lng), the customer app's
            // buildPin() is_verified flag, and resolveCustomerDispatchCoords()
            // which then reports url_unparseable instead of the honest
            // no_pin_no_url. Taimur Nizami / customer 6469 was left in exactly
            // that state this morning. Nothing is written now unless we have
            // coordinates.

            // This method's whole point is "from the address" — so GEOCODE it and
            // store real coords. Previously it saved a search URL only, leaving
            // lat/lng NULL (invisible to reports + the pin lock).
            //
            // Writing the VERIFIED columns from a geocode is deliberate here and is
            // not a machine deciding on its own: a human pressed "set pin from
            // address", which is them asserting that address is where to go. What
            // WAS missing is how good the match is — on Jul-25 this button was
            // pressed for SH-21417 and logged `geocoded: false` (the old engine
            // could not find the building), so the stop stayed location-less and
            // the manager had no way to know the press had achieved nothing.
            $geo = \App\Services\GeocodingService::geocodeAddress($validated['address'], $customer->city, [
                'customer_id' => $customer->id,
                'order_id'    => is_numeric($orderId) ? (int) $orderId : null,
                'trigger'     => 'store_button',
                'user_id'     => Auth::id(),
            ]);
            $precision = $geo['precision'] ?? null;

            if (!$geo) {
                // Nothing usable — so write nothing at all and say so plainly.
                // Leaving the customer untouched keeps "no pin" honest, which is
                // what makes the missing-location warning trustworthy.
                \Log::warning('Quick verify from address found no usable location — nothing saved', [
                    'order_id'    => $orderId,
                    'customer_id' => $validated['customer_id'],
                    'address'     => $validated['address'],
                    'saved_by'    => Auth::user()->fullname,
                ]);

                return response()->json([
                    'success'        => false,
                    'coords_source'  => 'none',
                    'coords_missing' => true,
                    'precision'      => null,
                    'message'        => "Google could not place this address precisely enough to trust, "
                                      . 'so nothing was saved. Please drop the pin on the map instead.',
                ]);
            }

            $updateData['latitude']  = $geo['latitude'];
            $updateData['longitude'] = $geo['longitude'];

            // Capture the pre-write pin so the change is auditable (same as the
            // two dropped-pin endpoints). This path was the last pin writer with
            // no audit row, which made an address-derived pin indistinguishable
            // from a precise one after the fact — the exact distinction staff
            // need when a delivery lands on the wrong street.
            $oldPinLat = $customer->latitude;
            $oldPinLng = $customer->longitude;

            // Update customer
            $customer->update($updateData);

            \App\Services\AuditLogger::logCustomerPinChange(
                $customer->id,
                trim(($customer->first_name ?? '') . ' ' . ($customer->last_name ?? '')),
                $oldPinLat, $oldPinLng,
                $customer->latitude, $customer->longitude,
                'Pin from address — geocoded by Google, approximate'
                    . ($precision ? ' (' . $precision . ' match)' : '')
            );

            // Pin changed → re-derive the region from it (see refreshAfterPinSave).
            \App\Services\RegionDetectionService::refreshAfterPinSave($customer->id);

            \Log::info('Quick verified location from address', [
                'order_id' => $orderId,
                'customer_id' => $validated['customer_id'],
                'address' => $validated['address'],
                'url' => $googleMapsUrl,
                'geocoded' => true,
                'precision' => $precision,
                'saved_by' => Auth::user()->fullname,
            ]);

            // Tell the truth about what was saved, in plain English, so the person
            // who pressed it knows whether to stop or still chase a precise pin.
            // (The "couldn't pinpoint it" case returned earlier without saving.)
            if ($precision === \App\Services\Location\CustomerLocationResolver::PRECISION_EXACT) {
                $message = 'Location saved from the address — matched to the building. '
                         . 'Delivery times will now be calculated properly.';
            } elseif ($precision === \App\Services\Location\CustomerLocationResolver::PRECISION_STREET) {
                $message = 'Location saved from the address — matched to the street, '
                         . 'but not the exact house. Good enough to route; drop the pin on arrival.';
            } else {
                $message = 'Location saved from the address, but only the area could be matched. '
                         . 'Times will be approximate — please drop the pin on the map when you can.';
            }

            return response()->json([
                'success' => true,
                'message' => $message,
                'verified_location_url' => $googleMapsUrl,
                'coords_source'  => 'geocoded',
                // Unchanged key/meaning for existing clients: an address-derived pin
                // is never as good as a dropped one. `precision` is the new detail.
                'approximate'    => true,
                'precision'      => $precision,
                'coords_missing' => false,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Invalid data',
                'errors' => $e->errors(),
            ], 422);
        } catch (\Exception $e) {
            \Log::error('Failed to quick verify location from address', [
                'order_id' => $orderId,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to save location: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Grant a time-boxed unlock so a rider can change a LOCKED verified pin.
     *
     * Store/web only — a bound rider cannot unlock for himself (that would
     * defeat the lock). The window (CustomerModel::VERIFIED_PIN_UNLOCK_MINUTES)
     * is the backstop for "unlocked but the rider never saved": it just expires,
     * and any rider save inside it consumes the grant immediately.
     */
    public function unlockCustomerVerifiedPin(Request $request, $customerId)
    {
        try {
            $user = Auth::user();
            if ($this->riderPinBindApplies($user)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Only store staff can unlock a verified location.',
                ], 403);
            }

            $customer = \App\Models\CRM\CustomerModel::find($customerId);
            if (!$customer) {
                return response()->json(['success' => false, 'message' => 'Customer not found'], 404);
            }

            $until = now()->addMinutes(\App\Models\CRM\CustomerModel::VERIFIED_PIN_UNLOCK_MINUTES);
            // Granting the unlock ANSWERS any standing rider request, so it is
            // cleared here — that is what takes the banner off the store and web
            // screens the moment the job is done.
            $customer->update(array_merge([
                'verified_pin_unlocked_until' => $until,
                'verified_pin_unlocked_by'    => $user->id,
            ], \App\Models\CRM\CustomerModel::pinUnlockRequestCleared()));

            \Log::info('Verified pin unlocked for rider edit', [
                'customer_id' => $customer->id,
                'unlocked_by' => $user->fullname ?? $user->id,
                'until'       => $until->toDateTimeString(),
            ]);

            return response()->json([
                'success'        => true,
                'message'        => 'Location unlocked. The rider can update the pin now.',
                'unlocked_until' => $until->toIso8601String(),
            ]);
        } catch (\Throwable $e) {
            \Log::error('Failed to unlock verified pin', [
                'customer_id' => $customerId,
                'error'       => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed to unlock location'], 500);
        }
    }

    /**
     * A rider ASKS for a locked pin to be unlocked (the button on his order
     * screen). The 423 refusal raises the same request, but only if he first
     * does the pointless work of dropping a pin that will be rejected — this is
     * the direct route: he sees "Locked", taps once, the store is asked.
     */
    public function requestCustomerPinUnlock(Request $request, $customerId)
    {
        try {
            $customer = \App\Models\CRM\CustomerModel::find($customerId);
            if (!$customer) {
                return response()->json(['success' => false, 'message' => 'Customer not found'], 404);
            }

            // Nothing to ask for if it is already open — tell the client so it
            // can just refresh rather than leaving a request nobody needs.
            if (!$customer->isVerifiedPinLocked()) {
                return response()->json([
                    'success'         => true,
                    'already_unlocked' => true,
                    'message'         => 'This location is already unlocked — you can update the pin now.',
                ]);
            }

            $raised = \App\Services\Location\PinUnlockRequestService::raise(
                $customer,
                Auth::id(),
                $request->input('order_id')
            );

            return response()->json([
                'success' => $raised,
                'message' => $raised
                    ? 'The store has been asked to unlock this location.'
                    : 'Could not send the request — please try again.',
                'unlock_requested' => $raised,
            ], $raised ? 200 : 500);
        } catch (\Throwable $e) {
            \Log::error('Failed to raise a pin unlock request', [
                'customer_id' => $customerId,
                'error'       => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Could not send the request'], 500);
        }
    }

    /**
     * Dismiss a rider's pin-unlock request from store mode WITHOUT unlocking —
     * the store banner's ✕. Same store-only bind as the unlock itself: a rider
     * must not be able to clear his own request (nor anyone else's).
     */
    public function dismissCustomerPinUnlockRequest(Request $request, $customerId)
    {
        try {
            $user = Auth::user();
            if ($this->riderPinBindApplies($user)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Only store staff can dismiss an unlock request.',
                ], 403);
            }

            $customer = \App\Models\CRM\CustomerModel::find($customerId);
            if (!$customer) {
                return response()->json(['success' => false, 'message' => 'Customer not found'], 404);
            }

            \App\Services\Location\PinUnlockRequestService::dismiss($customer);

            \Log::info('Verified-pin unlock request dismissed (store mode)', [
                'customer_id' => $customer->id,
                'by'          => $user->fullname ?? $user->id,
            ]);

            return response()->json(['success' => true, 'message' => 'Request dismissed.']);
        } catch (\Throwable $e) {
            \Log::error('Failed to dismiss pin unlock request (store mode)', [
                'customer_id' => $customerId,
                'error'       => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed to dismiss request'], 500);
        }
    }

    /**
     * Lightweight per-order live flags the rider app polls WHILE an order is
     * open, so a change made elsewhere (store unlocks the pin, and later: scan
     * rules, dispatch lock) reaches the rider WITHOUT reopening the order.
     * Deliberately generic — new flags attach here. See
     * DISPATCH-F1-F2-F3-COORDINATION-JUL2026.md (shared refresh mechanism).
     */
    public function getOrderLiveFlags(Request $request, $orderId)
    {
        try {
            // Van custody columns ride along for `vanBlockFor` (Sep-2026); each is
            // read through `??` there, so a server without batch 14 still answers.
            $vanCols = [];
            foreach (['order_status', 'assigned_rider_user_id', 'van_user_id', 'van_loaded_at', 'handover_at'] as $c) {
                if (\Schema::hasColumn('t_crm_prod_order', $c)) $vanCols[] = $c;
            }
            $order = \DB::table('t_crm_prod_order')
                ->where('id', $orderId)
                ->select(array_merge(['id', 'customer_id', 'expected_packets'], $vanCols))
                ->first();
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }

            $customer = $order->customer_id
                ? \App\Models\CRM\CustomerModel::find($order->customer_id)
                : null;

            $pinLocked   = $customer ? $customer->isVerifiedPinLocked() : false;
            $unlockUntil = ($customer && $customer->verifiedPinUnlockActive())
                ? $customer->verified_pin_unlocked_until->toIso8601String()
                : null;
            // Whether HIS ask is already standing, so the button reads "Store
            // notified" instead of inviting him to ask again — and still does
            // after he backs out and reopens the order.
            $unlockRequested = $customer ? $customer->verifiedPinUnlockRequestActive() : false;

            // Delivery-scan rules ride along (same shape as /delivery-scan-config)
            // so a bypass/require change made mid-delivery reaches the rider
            // WITHOUT reopening the order — the owner-requested refresh fix.
            $cfg = \DB::table('t_sys_config')->where('id', 1)->first();

            // Payment proof rides along too (Aug-2026): a customer who transfers
            // the money WHILE the rider is at the door must show up on his screen
            // without him reopening the order. suppressSettled:false — this is a
            // record surface, so an already-approved payment still reads as
            // received. Non-fatal: the flags this poll exists for must survive a
            // proof-lookup failure.
            $paymentProof = null;
            try {
                if (config('payment_signals.enabled')) {
                    $paymentProof = app(\App\Services\Payments\Signals\PaymentProofStatusService::class)
                        ->forOrder((int) $order->id, suppressSettled: false);
                }
            } catch (\Throwable $ppErr) {
                $paymentProof = null;
            }

            return response()->json([
                'success' => true,
                'flags'   => [
                    'verified_pin_locked'          => $pinLocked,
                    'verified_pin_unlock_until'    => $unlockUntil,
                    'verified_pin_unlock_requested' => $unlockRequested,
                    'require_delivery_scan'      => $cfg ? (int) ($cfg->require_delivery_scan ?? 0) : 0,
                    'allow_delivery_scan_bypass' => $cfg ? (int) ($cfg->allow_delivery_scan_bypass ?? 0) : 0,
                    // ⭐ The packet target rides along too (Aug-2026). The scan modal used to take it
                    //    from whatever the order payload held when the screen loaded, so a count the
                    //    store corrected AFTER that never reached the rider — half of how NF-19218
                    //    was delivered 1-of-2. This poll is the fresh source of truth.
                    'expected_packets'           => (int) ($order->expected_packets ?: 0),
                    'payment_proof'              => $paymentProof,
                    // 🚚 Whose hands the box is in (Sep-2026) — so the order page
                    //    swaps "Mark Delivered" for the handover scan while the box
                    //    is still on somebody's van, and swaps back within this
                    //    poll once it is collected. Null = no van info (old server
                    //    or van features off) = today's behaviour.
                    'van'                        => $this->vanBlockFor($order),
                ],
            ]);
        } catch (\Throwable $e) {
            \Log::error('getOrderLiveFlags failed', [
                'order_id' => $orderId,
                'error'    => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed to load flags'], 500);
        }
    }

    /**
     * Mark an order as delivered
     * Riders can only mark their own assigned orders as delivered
     */
    public function markOrderDelivered(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            // Fetch order WITH customer relationship eagerly loaded for ledger posting
            $order = \App\Models\CRM\OrderModel::with('customer')->find($id);

            if (!$order) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found',
                ], 404);
            }

            // Check if rider is assigned to this order
            if ($order->assigned_rider_user_id != $user->id) {
                return response()->json([
                    'success' => false,
                    'message' => 'You are not authorized to update this order',
                ], 403);
            }

            // Check if order is already delivered
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'This order is already marked as delivered',
                ], 400);
            }

            // 🚚 Still ON THE VAN (Aug-2026): it cannot be delivered before it is
            // collected. This endpoint historically never checked the current
            // status, so without this a rider could "deliver" a box that is
            // physically riding in the van. The handover scan is the door.
            $vanBlock = \App\Services\Riders\VanService::manualChangeBlock($order, 'delivered');
            if ($vanBlock !== null) {
                return response()->json(['success' => false, 'message' => $vanBlock], 422);
            }

            // Get notes, GPS coordinates, and packet count from request (optional)
            $notes = $request->input('notes', 'Marked as delivered by rider via mobile app');
            $latitude = $request->input('latitude');
            $longitude = $request->input('longitude');
            /**
             * ⭐⭐ THE PHANTOM GATE (16-Sep-2026). Two of Rajab's deliveries were stamped in Beijing
             *    from a stale, mislocated fix. That point is later measured twice ("delivered N m
             *    from pin", the checkout rule) and OFFERED as the customer's pin — so a fix outside
             *    Pakistan is dropped here and the delivery is recorded with no coordinates, exactly
             *    as when the phone had none. The delivery itself is never blocked over it.
             */
            if ($latitude !== null && $longitude !== null && !LocationService::isPlausibleFix($latitude, $longitude)) {
                \Log::warning('📍 DELIVERY: fix outside Pakistan (phantom) — coordinates dropped', [
                    'order_id' => $id, 'user_id' => $user->id ?? null,
                    'latitude' => $latitude, 'longitude' => $longitude, 'accuracy' => $request->input('accuracy'),
                ]);
                $this->recordLocationFailureRow((int) ($user->id ?? 0), 'phantom_fix', 'delivery',
                    sprintf('phantom %s,%s acc=%s order=%s', $latitude, $longitude, $request->input('accuracy', '?'), $id),
                    $latitude, $longitude);
                $latitude = null; $longitude = null;
            }
            $actualPackets = $request->input('actual_packets'); // Optional packet count from rider

            // ── Phase 3: package-scan gate. DEFAULT OFF — only enforces when the owner has
            //    turned on require_delivery_scan in the web operations settings. When OFF (or the
            //    config columns don't exist yet), this whole block is inert and delivery behaves
            //    exactly as before. `??` on a missing column is warning-free and reads as 0.
            $scanCfg = \DB::table('t_sys_config')->where('id', 1)->first();
            $requireScan = $scanCfg ? ((int) ($scanCfg->require_delivery_scan ?? 0) === 1) : false;
            $allowBypass = $scanCfg ? ((int) ($scanCfg->allow_delivery_scan_bypass ?? 0) === 1) : false;

            if ($requireScan) {
                $scanCode = trim((string) $request->input('scan_code', ''));
                $bypassReason = trim((string) $request->input('bypass_reason', ''));
                // A scan is valid when the order-number part of the QR (before '|') matches THIS order.
                $scanOrderNumber = $scanCode !== '' ? trim(explode('|', $scanCode)[0]) : '';
                $scanMatches = $scanOrderNumber !== '' && $scanOrderNumber === (string) $order->order_number;

                // ⭐ A SCAN TAKEN BEFORE THE HANDOVER IS NOT A DOOR SCAN (Sep-2026).
                //    The phone keeps a completed scan for 24h so a screen rebuild
                //    never forces a re-scan — and on Sep-3 that let a scan taken
                //    AT THE VAN close the delivery two hours later. The app now
                //    sends when the scan was captured; if that predates the
                //    handover the rider is asked to scan again at the door —
                //    the same `scan_required` the app already knows how to
                //    handle (clears the saved scan, reopens the scanner).
                //    Old builds send nothing → rule inert. A rider with NO
                //    handover at all never reaches here (the van guard above).
                $scannedAtMs = $request->input('scanned_at');
                if ($scanMatches && is_numeric($scannedAtMs) && !empty($order->handover_at)) {
                    try {
                        $scannedAt  = \Carbon\Carbon::createFromTimestampMs((int) $scannedAtMs, config('app.timezone'));
                        $handoverAt = \Carbon\Carbon::parse($order->handover_at, config('app.timezone'));
                        if ($scannedAt->lt($handoverAt)) {
                            \Log::warning('Delivery used a pre-handover scan — asked to re-scan', [
                                'order' => $order->id, 'number' => $order->order_number,
                                'rider' => $user->id, 'scanned_at' => $scannedAt->toDateTimeString(),
                                'handover_at' => $handoverAt->toDateTimeString(),
                            ]);
                            return response()->json([
                                'success' => false,
                                'code' => 'scan_required',
                                'require_scan' => true,
                                'allow_bypass' => $allowBypass,
                                'message' => 'Ye scan van par hua tha — customer ke paas packet dobara scan karein.',
                            ], 422);
                        }
                    } catch (\Throwable $e) {
                        // an unparseable timestamp must never block a delivery
                    }
                }

                if ($scanMatches) {
                    $notes .= ' (scan verified)';
                } elseif ($bypassReason !== '' && $allowBypass) {
                    $order->delivery_scan_bypass_reason = mb_substr($bypassReason, 0, 250);
                    $order->save();
                    $notes .= ' (scan bypassed: ' . mb_substr($bypassReason, 0, 100) . ')';
                } else {
                    return response()->json([
                        'success' => false,
                        'code' => 'scan_required',
                        'require_scan' => true,
                        'allow_bypass' => $allowBypass,
                        'message' => $scanCode !== ''
                            ? 'This package does not match this order — please scan the correct package.'
                            : 'Please scan the package QR before marking delivered.',
                    ], 422);
                }
            }

            // ── Aug-2026 packet-count enforcement (order NF-19218). The gate above only proves the
            //    rider scanned A label belonging to THIS order — it never counted them, so an order
            //    the store packed as 2 could be closed with a single scan, and was. When the store
            //    has set a count and scanning is required, that count is the target and the SERVER
            //    is the judge: the phone's own idea of the target was exactly what went wrong (a
            //    stale "1/1" label talked the scanner down from 2 to 1).
            //
            //    Authority order: the distinct packet indices the phone actually scanned
            //    (scanned_indices — new in the Aug-2026 build) beat the free-typed actual_packets,
            //    which is all an older build sends. Older builds are still enforced, just on the
            //    weaker number — which is why this check lives here and not only in the app.
            $scanHelp = new \App\Services\Riders\ScanHelpService();
            $expectedPackets = (int) ($order->expected_packets ?: 0);
            $rawIndices = $request->input('scanned_indices');
            $scannedIndices = is_array($rawIndices)
                ? array_values(array_unique(array_filter(
                    array_map('intval', array_filter($rawIndices, 'is_numeric')),
                    fn ($i) => $i > 0
                )))
                : null;
            $countedPackets = $scannedIndices !== null
                ? count($scannedIndices)
                : (is_numeric($actualPackets) ? (int) $actualPackets : null);
            $shortDeliveryApproved = false;

            // No count at all while one is expected. Every shipped client sends one in this
            // situation, so this is unreachable in practice — but it is the shape a tampered or
            // very old client would take, and it would slip past the check below, so make it
            // visible instead of silent. Not blocked: a client that can omit the field can equally
            // send the expected number, so a block buys nothing and could strand a real rider.
            if ($requireScan && $expectedPackets > 0 && $countedPackets === null) {
                \Log::warning('Delivery had no packet count to check', [
                    'order_id'         => $order->id,
                    'order_number'     => $order->order_number,
                    'rider_id'         => $user->id,
                    'expected_packets' => $expectedPackets,
                ]);
            }

            if ($requireScan && $expectedPackets > 0 && $countedPackets !== null && $countedPackets < $expectedPackets) {
                $approval = $scanHelp->approvalFor($order, (int) $user->id);

                if ($approval === null) {
                    $requestPending = (string) ($order->scan_bypass_status ?? '') === \App\Services\Riders\ScanHelpService::STATUS_PENDING
                        && (int) ($order->scan_bypass_requested_by ?: 0) === (int) $user->id;
                    \Log::warning('Delivery blocked — packet shortfall', [
                        'order_id'         => $order->id,
                        'order_number'     => $order->order_number,
                        'rider_id'         => $user->id,
                        'expected_packets' => $expectedPackets,
                        'counted_packets'  => $countedPackets,
                        'from_indices'     => $scannedIndices !== null,
                        'request_pending'  => $requestPending,
                    ]);
                    return response()->json([
                        'success'          => false,
                        'code'             => 'packet_shortfall',
                        'expected_packets' => $expectedPackets,
                        'counted_packets'  => $countedPackets,
                        'request_pending'  => $requestPending,
                        'message'          => 'The store packed ' . $expectedPackets . ' packets for this order but only '
                            . $countedPackets . ' ' . ($countedPackets === 1 ? 'was' : 'were')
                            . ' scanned. Scan the rest, or ask a manager to approve a short delivery.',
                    ], 422);
                }

                // Approved short delivery. The approval is burned only AFTER the status change
                // actually succeeds (further down) — burning it here would leave the rider needing a
                // brand-new approval if the delivery itself then failed. Single-use either way.
                // The note is the durable record: it outlives the request row, which a later packet
                // change or a fresh request will clear.
                $shortDeliveryApproved = true;
                $notes .= ' (short delivery approved: ' . $countedPackets . ' of ' . $expectedPackets
                    . ($approval['reason'] !== '' ? ' — ' . mb_substr($approval['reason'], 0, 80) : '') . ')';
                \Log::info('Short delivery allowed by approved scan-help', [
                    'order_id'         => $order->id,
                    'order_number'     => $order->order_number,
                    'rider_id'         => $user->id,
                    'expected_packets' => $expectedPackets,
                    'counted_packets'  => $countedPackets,
                    'approved_by'      => $approval['decided_by'],
                ]);
            } elseif ($countedPackets !== null && $expectedPackets > 0 && $countedPackets >= $expectedPackets) {
                // He found the missing box and scanned everything after all — retire the request so
                // the managers' banner stops asking them to decide something that no longer matters.
                $scanHelp->clear($order, 'rider scanned every packet in the end');
            }

            // Log received GPS data for debugging
            \Log::info('Received GPS data from mobile app', [
                'order_id' => $order->id,
                'latitude' => $latitude,
                'longitude' => $longitude,
                'latitude_type' => gettype($latitude),
                'longitude_type' => gettype($longitude),
                'latitude_is_null' => is_null($latitude),
                'longitude_is_null' => is_null($longitude),
                'full_request' => $request->all()
            ]);

            // Add GPS coordinates to notes if provided
            if ($latitude && $longitude) {
                $notes .= " (GPS: {$latitude}, {$longitude})";
            }

            // Record the packet count. `$countedPackets` is the number the enforcement above
            // actually judged (the distinct scan indices when the phone sent them, else the typed
            // field), so record THAT — an audit trail that disagrees with the rule which let the
            // delivery through is worse than none.
            if ($countedPackets !== null) {
                $order->actual_packets = $countedPackets;
                $order->save();

                // Persist WHICH packets were scanned. Before this only the scan TIME survived
                // (delivery_scanned_at), so a short rider scan left nothing to reconstruct while the
                // store side kept dispatch_scanned_packets. Written in its OWN statement: if the
                // column has not been migrated yet this fails alone and the delivery recorded above
                // is untouched (same pattern as dispatch_scan_banner_enabled).
                if ($scannedIndices !== null) {
                    try {
                        sort($scannedIndices);
                        \DB::table('t_crm_prod_order')->where('id', $order->id)
                            ->update(['delivery_scanned_packets' => json_encode($scannedIndices)]);
                    } catch (\Throwable $e) {
                        // column absent — the count above is still on record
                    }
                }

                \Log::info('Rider entered packet count', [
                    'order_id' => $order->id,
                    'expected_packets' => $order->expected_packets,
                    'actual_packets' => $countedPackets,
                    'scanned_indices' => $scannedIndices,
                    'typed_packets' => is_numeric($actualPackets) ? (int) $actualPackets : null,
                    'match' => (int) ($order->expected_packets ?: 0) === (int) $countedPackets
                ]);
            }

            // Use the existing changeStatus method
            $result = $order->changeStatus('delivered', $notes, $user->id);

            // The delivery is on record — now burn the one-time short-delivery approval so it can
            // never serve a second attempt. Deliberately after the status change, not before.
            if ($result && $shortDeliveryApproved) {
                $scanHelp->consume($order);
            }

            // Update the status history record with GPS coordinates if provided
            if ($result && $latitude && $longitude) {
                $histUpdate = [
                    'delivery_latitude' => $latitude,
                    'delivery_longitude' => $longitude
                ];
                // ⭐ How good was this fix? This point is later measured TWICE — the
                // "delivered N m from pin" flag, and the checkout rule's "within 150 m of your
                // last delivery" — so a vague fix can penalise a rider at both ends without
                // anyone knowing it was vague. Stored when the app sends it (new APK);
                // Schema-guarded + NULL from older builds, so nothing changes until then.
                $accuracy = $request->input('accuracy');
                $fixAge   = $request->input('fix_age_s');
                if (\Illuminate\Support\Facades\Schema::hasColumn('t_crm_order_status_history', 'delivery_accuracy_m')) {
                    $histUpdate['delivery_accuracy_m'] = is_numeric($accuracy) ? (float) $accuracy : null;
                    $histUpdate['delivery_fix_age_s']  = is_numeric($fixAge) ? (int) $fixAge : null;
                }
                \DB::table('t_crm_order_status_history')
                    ->where('order_id', $order->id)
                    ->where('status_code', 'delivered')
                    ->where('is_current', 1)
                    ->update($histUpdate);

                \Log::info('GPS location stored', [
                    'order_id' => $order->id,
                    'latitude' => $latitude,
                    'longitude' => $longitude,
                    'accuracy_m' => is_numeric($accuracy) ? (float) $accuracy : null,
                    'fix_age_s' => is_numeric($fixAge) ? (int) $fixAge : null,
                ]);
            }

            // ⭐ This customer has no verified pin, and the rider is standing at her
            //    door right now with a GPS fix — the one moment the exact location
            //    is free to capture. Offer it back so the app can ask "save this as
            //    her location?" instead of the address staying un-pinned for months
            //    (SH-21417 was navigated to by address, dropped from a dispatch, and
            //    only pinned by the rider on arrival — after the damage).
            //
            //    We hand back the DELIVERY coordinates, not "wherever the phone is
            //    when you tap": by then he may have ridden off. Nothing is written
            //    here — promoting a machine reading into the verified columns stays
            //    a human decision, made through setCustomerVerifiedLocation.
            $suggestPinSave = null;
            try {
                if ($result && $latitude && $longitude && $order->customer_id) {
                    $cust = \DB::table('t_crm_prod_customer')
                        ->where('id', $order->customer_id)
                        ->select('id', 'first_name', 'last_name', 'latitude', 'longitude')
                        ->first();
                    if ($cust && !($cust->latitude && $cust->longitude)) {
                        $suggestPinSave = [
                            'customer_id'   => (int) $cust->id,
                            'customer_name' => trim(($cust->first_name ?? '') . ' ' . ($cust->last_name ?? '')),
                            'latitude'      => (float) $latitude,
                            'longitude'     => (float) $longitude,
                            'prompt'        => 'Save this spot as the delivery location? Next time the route and delivery time will be exact.',
                        ];
                    }
                }
            } catch (\Throwable $e) {
                // Never let a suggestion break a delivery confirmation.
                \Log::warning('suggest_pin_save check failed (non-fatal)', [
                    'order_id' => $order->id, 'error' => $e->getMessage(),
                ]);
            }

            if ($result) {
                \Log::info('Order marked as delivered by rider', [
                    'order_id' => $order->id,
                    'order_number' => $order->order_number,
                    'rider_id' => $user->id,
                    'rider_name' => $user->fullname,
                ]);

                return response()->json([
                    'success' => true,
                    'message' => 'Order marked as delivered successfully',
                    'order' => [
                        'id' => $order->id,
                        'order_number' => $order->order_number,
                        'order_status' => $order->order_status,
                    ],
                    // null unless this customer still has no verified pin (see above).
                    'suggest_pin_save' => $suggestPinSave,
                ]);
            } else {
                return response()->json([
                    'success' => false,
                    'message' => 'Failed to update order status',
                ], 500);
            }
        } catch (\Exception $e) {
            \Log::error('Failed to mark order as delivered', [
                'order_id' => $id,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to mark order as delivered: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Phase 3: verify a scanned package QR against the rider's assigned order.
     * QR format = "ORDERNUMBER|index/total" (e.g. "SH-10457|1/2"). Read-only, never throws.
     */
    public function verifyDeliveryScan(Request $request)
    {
        try {
            $user = Auth::user();
            $code = trim((string) $request->input('code', ''));
            if ($code === '') {
                return response()->json(['success' => true, 'found' => false, 'message' => 'Nothing scanned']);
            }

            $parts = explode('|', $code);
            $orderNumber = trim($parts[0] ?? '');
            $packetIndex = null;
            $packetTotal = null;
            if (isset($parts[1]) && strpos($parts[1], '/') !== false) {
                $pp = explode('/', $parts[1]);
                $packetIndex = is_numeric(trim($pp[0] ?? '')) ? (int) trim($pp[0]) : null;
                $packetTotal = is_numeric(trim($pp[1] ?? '')) ? (int) trim($pp[1]) : null;
            }

            if ($orderNumber === '') {
                return response()->json(['success' => true, 'found' => false, 'message' => 'QR not recognised']);
            }

            $order = \App\Models\CRM\OrderModel::with('customer')->where('order_number', $orderNumber)->first();
            if (!$order) {
                return response()->json(['success' => true, 'found' => false, 'message' => 'No order found for this QR']);
            }

            $assignedToMe = ((int) $order->assigned_rider_user_id === (int) $user->id);
            $alreadyDelivered = in_array($order->order_status, ['delivered', 'completed'], true);

            return response()->json([
                'success' => true,
                'found' => true,
                'assigned_to_me' => $assignedToMe,
                'already_delivered' => $alreadyDelivered,
                'order' => [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_name' => optional($order->customer)->name ?? ($order->address_name ?? null),
                    'order_status' => $order->order_status,
                ],
                'packet' => ['index' => $packetIndex, 'total' => $packetTotal],
                'message' => $assignedToMe
                    ? ($alreadyDelivered ? 'This order is already delivered' : 'Package matches this order')
                    : 'This package belongs to another rider',
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'found' => false, 'message' => 'Could not verify the scan']);
        }
    }

    /**
     * Phase 3: delivery-scan config flags for the app (require + allow bypass). Defaults 0/0
     * (scanning optional) when unset or the columns don't exist yet. Never throws.
     */
    public function getDeliveryScanConfig()
    {
        try {
            $cfg = \DB::table('t_sys_config')->where('id', 1)->first();
            return response()->json([
                'success' => true,
                'require_delivery_scan' => $cfg ? (int) ($cfg->require_delivery_scan ?? 0) : 0,
                'allow_delivery_scan_bypass' => $cfg ? (int) ($cfg->allow_delivery_scan_bypass ?? 0) : 0,
                // Enh-1: store-side dispatch hand-over banner toggle (default off).
                'dispatch_scan_banner_enabled' => $cfg ? (int) ($cfg->dispatch_scan_banner_enabled ?? 0) : 0,
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => true, 'require_delivery_scan' => 0, 'allow_delivery_scan_bypass' => 0, 'dispatch_scan_banner_enabled' => 0]);
        }
    }

    /**
     * Best-effort audit stamp that the rider completed the delivery package scan (proof + time).
     * The phone pings this right after a successful scan; the on-device cache is what actually
     * prevents re-scans, so this NEVER blocks the delivery flow. Records the FIRST scan time only
     * (re-scans don't move it). Safe before the SQL migration runs — a missing column is caught.
     * POST /api/rider/orders/{id}/delivery-scan-mark
     */
    /**
     * 🚚 The `van` block the order page and its live-flags poll both carry
     *    (Sep-2026). ONE derivation (`VanService::custodyState`) shared with the
     *    status guard, so "the page hides Mark Delivered" and "the server
     *    refuses Mark Delivered" can never drift apart.
     *
     *    Null when van features are not installed — the app reads null as
     *    "no van info" and behaves exactly as before. Never throws: a van
     *    lookup must not cost the rider his order page.
     */
    private function vanBlockFor($order): ?array
    {
        try {
            $vs = new \App\Services\Riders\VanService();
            if (!$vs->available()) return null;
            $c = \App\Services\Riders\VanService::custodyState($order);
            $driverId = !empty($order->van_user_id) ? (int) $order->van_user_id : null;

            $driverName = null;
            $stop = null;
            if ($c['needs_handover'] && $driverId) {
                $driverName = \DB::table('t_sys_user')->where('id', $driverId)->value('fullname');
                try {
                    $stop = app(\App\Services\Riders\VanStopService::class)->currentStopPayload($driverId);
                } catch (\Throwable $e) {
                    $stop = null;
                }
            }

            return [
                'on_van'         => $c['on_van'],
                'needs_handover' => $c['needs_handover'],
                'drivers_own'    => $c['drivers_own'] && $c['on_van'],
                'driver_id'      => $driverId,
                'driver_name'    => $driverName,
                'loaded_at'      => $order->van_loaded_at ?? null,
                'handover_at'    => $order->handover_at ?? null,
                'stop'           => $stop ? [
                    'id'         => $stop['id'],
                    'label'      => $stop['label'],
                    'latitude'   => $stop['latitude'],
                    'longitude'  => $stop['longitude'],
                    'reached_at' => $stop['reached_at'],
                ] : null,
            ];
        } catch (\Throwable $e) {
            return null;
        }
    }

    public function deliveryScanMark(Request $request, $id)
    {
        try {
            $user = Auth::user();
            $order = \DB::table('t_crm_prod_order')
                ->where('id', $id)
                ->select('id', 'order_number', 'order_status', 'assigned_rider_user_id', 'delivery_scanned_at',
                         'van_user_id', 'van_loaded_at', 'handover_at')
                ->first();
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }
            if ((int) $order->assigned_rider_user_id !== (int) $user->id) {
                return response()->json(['success' => false, 'message' => 'Not authorized for this order'], 403);
            }
            // 🚚 NOT A DOOR SCAN IF THE BOX IS STILL ON THE VAN (Sep-2026). This
            //    ping used to stamp `delivery_scanned_at` for an order the rider
            //    had only just met at the van — the stamp then looked like proof
            //    the box reached the customer. Same rule as Mark Delivered itself;
            //    refused AND logged so the next one is one grep away. The app
            //    fires this best-effort, so an older build simply sees nothing.
            $vanBlock = \App\Services\Riders\VanService::manualChangeBlock($order, 'delivered');
            if ($vanBlock !== null) {
                \Log::info('Delivery scan attempted on an on-van order', [
                    'order' => $order->id, 'number' => $order->order_number ?? null,
                    'rider' => $user->id, 'van' => $order->van_user_id ?? null,
                ]);
                return response()->json(['success' => false, 'code' => 'on_van', 'message' => $vanBlock], 422);
            }
            // Stamp only the first scan — keeps the earliest proof; later re-scans don't overwrite.
            if (empty($order->delivery_scanned_at)) {
                \DB::table('t_crm_prod_order')->where('id', $id)->update([
                    'delivery_scanned_at' => now(),
                    'delivery_scanned_by' => $user->id,
                ]);
            }
            return response()->json(['success' => true]);
        } catch (\Exception $e) {
            // Best-effort only — never surface an error into the delivery flow.
            return response()->json(['success' => false], 200);
        }
    }

    /**
     * ── Scan help (Aug-2026). A rider who cannot scan every packet asks a manager instead of
     *    self-serving a bypass. Four endpoints: he requests, he polls, managers list, managers
     *    decide. All authority lives in ScanHelpService so store mode and the web banner cannot
     *    drift apart. See add_scan_help_bypass_aug17_2026.sql.
     *
     * POST /api/rider/orders/{id}/scan-help   { reason, packets_in_hand }
     */
    public function scanHelpRequest(Request $request, $id)
    {
        try {
            $user = Auth::user();
            $order = \App\Models\CRM\OrderModel::find($id);
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }
            // Only the assigned rider may ask — the approval is later bound to this same id.
            if ((int) $order->assigned_rider_user_id !== (int) $user->id) {
                return response()->json(['success' => false, 'message' => 'Not authorized for this order'], 403);
            }
            if (in_array($order->order_status, ['delivered', 'completed', 'cancelled', 'refunded'])) {
                return response()->json(['success' => false, 'message' => 'This order is already closed.'], 422);
            }

            $inHand = $request->input('packets_in_hand');
            $res = (new \App\Services\Riders\ScanHelpService())->request(
                $order,
                (int) $user->id,
                (string) $request->input('reason', ''),
                is_numeric($inHand) ? (int) $inHand : null
            );

            return response()->json([
                'success' => $res['ok'],
                'status'  => $res['status'] ?? null,
                'message' => $res['message'] ?? null,
            ], $res['ok'] ? 200 : 422);
        } catch (\Exception $e) {
            \Log::error('scanHelpRequest failed', ['order_id' => $id, 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Could not send the request'], 500);
        }
    }

    /**
     * What the rider's phone polls while it waits for a decision.
     * GET /api/rider/orders/{id}/scan-help
     */
    public function scanHelpStatus(Request $request, $id)
    {
        try {
            $user = Auth::user();
            $order = \App\Models\CRM\OrderModel::find($id);
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }
            if ((int) $order->assigned_rider_user_id !== (int) $user->id) {
                return response()->json(['success' => false, 'message' => 'Not authorized for this order'], 403);
            }
            $state = (new \App\Services\Riders\ScanHelpService())->statusFor($order, (int) $user->id);
            return response()->json(array_merge(['success' => true], $state));
        } catch (\Exception $e) {
            // Polling must never surface an error — the rider keeps waiting and can retry.
            return response()->json(['success' => true, 'status' => 'none']);
        }
    }

    /**
     * Pending requests for the store-mode banner.
     * GET /api/rider/scan-help/pending
     *
     * `can_approve` is returned LIVE rather than relying on the app's permission snapshot, which is
     * only refreshed at app start / login — a freshly granted approve_scan_bypass would otherwise
     * stay invisible until every manager re-logged in.
     */
    public function scanHelpPending(Request $request)
    {
        try {
            $svc = new \App\Services\Riders\ScanHelpService();
            $user = Auth::user();
            $canApprove = $svc->canApprove($user);
            return response()->json([
                'success'     => true,
                'can_approve' => $canApprove,
                // Nothing to show someone who cannot act on it.
                'requests'    => $canApprove ? $svc->pending() : [],
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => true, 'can_approve' => false, 'requests' => []]);
        }
    }

    /**
     * Manager approves or denies from store mode.
     * POST /api/rider/scan-help/decide  { order_id, decision: approved|denied }
     */
    public function scanHelpDecide(Request $request)
    {
        try {
            $orderId = (int) $request->input('order_id');
            $res = (new \App\Services\Riders\ScanHelpService())->decide(
                $orderId,
                (string) $request->input('decision', ''),
                Auth::user()
            );
            return response()->json([
                'success' => $res['ok'],
                'status'  => $res['status'] ?? null,
                'code'    => $res['code'] ?? null,
                'message' => $res['message'] ?? null,
            ], $res['ok'] ? 200 : (($res['code'] ?? '') === 'forbidden' ? 403 : 422));
        } catch (\Exception $e) {
            \Log::error('scanHelpDecide failed', ['error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Could not save the decision'], 500);
        }
    }

    /**
     * Receipt printout field config for the app (which fields to print). Empty object when
     * unset (the app then prints everything, i.e. today's layout). Never throws.
     */
    public function getReceiptConfig()
    {
        try {
            $raw = \DB::table('t_sys_config')->where('id', 1)->value('receipt_print_config');
            $decoded = $raw ? json_decode($raw, true) : null;
            return response()->json(['success' => true, 'config' => is_array($decoded) ? $decoded : (object) []]);
        } catch (\Exception $e) {
            return response()->json(['success' => true, 'config' => (object) []]);
        }
    }

    /**
     * Dispatch package-scan (store hand-over). The manager scans a package QR
     * ("ORDERNUMBER|index/total") at dispatch. Records the packet index; when ALL
     * packets are scanned the order is stamped "ready to leave" (dispatch_scanned_at).
     * Per-packet + persistent. Verifies the scanned QR belongs to THIS order. Never throws.
     */
    public function dispatchScan(Request $request, $id)
    {
        try {
            $user = Auth::user();
            $order = \App\Models\CRM\OrderModel::find($id);
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }

            $code = trim((string) $request->input('scan_code', ''));
            $parts = explode('|', $code);
            $codeOrderNo = trim($parts[0] ?? '');
            $idx = null;
            $totalFromCode = null;
            if (isset($parts[1]) && strpos($parts[1], '/') !== false) {
                $pp = explode('/', $parts[1]);
                $idx = is_numeric(trim($pp[0] ?? '')) ? (int) trim($pp[0]) : null;
                $totalFromCode = is_numeric(trim($pp[1] ?? '')) ? (int) trim($pp[1]) : null;
            }

            if ($codeOrderNo === '' || $codeOrderNo !== (string) $order->order_number) {
                return response()->json([
                    'success' => false,
                    'code' => 'wrong_order',
                    'scanned_order' => $codeOrderNo,
                    'message' => $codeOrderNo !== '' ? 'This package is for order ' . $codeOrderNo : 'QR not recognised',
                ], 422);
            }

            // Target = the order's packet count (fallback to the QR's total, then 1).
            $target = (int) ($order->expected_packets ?: $totalFromCode ?: 1);
            if ($target < 1) $target = 1;
            $idx = $idx ?: 1;

            $scanned = [];
            if (!empty($order->dispatch_scanned_packets)) {
                $decoded = json_decode($order->dispatch_scanned_packets, true);
                if (is_array($decoded)) $scanned = array_values(array_unique(array_map('intval', $decoded)));
            }
            $already = in_array($idx, $scanned, true);
            if (!$already) $scanned[] = $idx;
            sort($scanned);

            $order->dispatch_scanned_packets = json_encode(array_values($scanned));
            $complete = count($scanned) >= $target;
            if ($complete && empty($order->dispatch_scanned_at)) {
                $order->dispatch_scanned_at = now();
                $order->dispatch_scanned_by = $user->id;
            }
            $order->save();

            return response()->json([
                'success' => true,
                'already_scanned' => $already,
                'scanned_count' => count($scanned),
                'target' => $target,
                'complete' => $complete,
                'dispatch_scanned_at' => $order->dispatch_scanned_at,
                'message' => $complete
                    ? 'All packets scanned — ready to leave'
                    : ($already ? ('Packet ' . $idx . ' already scanned (' . count($scanned) . ' of ' . $target . ')')
                                : ('Packet ' . $idx . ' scanned (' . count($scanned) . ' of ' . $target . ')')),
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => 'Could not record the scan'], 200);
        }
    }

    /**
     * Clear an order's dispatch scan (undo a mistaken scan / re-do from scratch).
     */
    public function dispatchScanClear(Request $request, $id)
    {
        try {
            $order = \App\Models\CRM\OrderModel::find($id);
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }
            $order->dispatch_scanned_packets = null;
            $order->dispatch_scanned_at = null;
            $order->dispatch_scanned_by = null;
            $order->save();
            return response()->json(['success' => true, 'message' => 'Dispatch scan cleared']);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => 'Could not clear the scan'], 200);
        }
    }

    /**
     * Change payment method for an order (rider can switch between cash/online)
     * For non-delivered orders only
     */
    public function changePaymentMethod(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            $request->validate([
                'payment_type' => 'required|in:cash,online',
            ]);
            
            $order = OrderModel::where('id', $id)
                ->where('assigned_rider_user_id', $user->id) // Fixed: correct column name
                ->first();
            
            if (!$order) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found or not assigned to you',
                ], 404);
            }
            
            // Check if order is already delivered - riders can only change before delivery
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cannot change payment method for delivered orders',
                ], 400);
            }
            
            $newPaymentType = $request->payment_type;
            $oldPaymentMethod = $order->payment_method;
            
            // Determine old payment type - treat NULL/empty as 'cash' (default)
            // This handles orders created from mobile without explicit payment method
            $normalizedOldMethod = strtolower(trim($oldPaymentMethod ?? ''));
            $oldPaymentType = (empty($normalizedOldMethod) || in_array($normalizedOldMethod, ['cash', 'cash_on_delivery', 'cod'])) 
                ? 'cash' 
                : 'online';
            
            if ($oldPaymentType === $newPaymentType) {
                return response()->json([
                    'success' => false,
                    'message' => 'Payment method is already set to ' . $newPaymentType,
                ], 400);
            }

            // ⭐ WhatsApp-reachability guard (RIDER mode only). Don't let a rider
            // convert a REGULAR customer's FIRST order to online when we already
            // know the customer's WhatsApp can't receive messages — the bank-details
            // payment message would just bounce. Managers (web) and store mode can
            // still convert; this guard lives ONLY in this rider endpoint. Checks the
            // SAME number the pay-change message would dial. Positive-evidence only
            // and fail-open (isNumberUndeliverable), so it never wrongly blocks.
            if ($newPaymentType === 'online') {
                $order->loadMissing('customer');
                $customer = $order->customer;
                if ($customer && !$customer->isShop()) {
                    $orderCount = OrderModel::where('customer_id', $order->customer_id)->count();
                    if ($orderCount <= 1) { // first order for this customer
                        $dialPhone = $customer->phone_normalized
                            ?: ($customer->phone_original ?: $order->address_phone);
                        if (app(\App\Services\WhatsAppService::class)->isNumberUndeliverable($dialPhone)) {
                            \Log::info('Rider online-conversion blocked — customer WhatsApp undeliverable', [
                                'order_id' => $order->id,
                                'order_number' => $order->order_number,
                                'rider_id' => $user->id,
                                'customer_id' => $order->customer_id,
                            ]);
                            return response()->json([
                                'success' => false,
                                'wa_invalid' => true,
                                'message' => "This customer's WhatsApp number can't receive messages, so the online payment details won't be delivered. Online conversion is blocked for first-time customers — please collect cash, or ask a manager to convert.",
                            ], 422);
                        }
                    }
                }
            }

            // Map the payment type to actual payment method value
            $newPaymentMethod = $newPaymentType === 'cash' ? 'cash_on_delivery' : 'online_payment';
            
            // Update payment method
            $order->payment_method = $newPaymentMethod;
            $order->save();
            
            \Log::info('Payment method changed by rider (before delivery)', [
                'order_id' => $order->id,
                'order_number' => $order->order_number,
                'rider_id' => $user->id,
                'rider_name' => $user->fullname,
                'old_method' => $oldPaymentMethod,
                'new_method' => $newPaymentMethod,
                'order_status' => $order->order_status
            ]);

            // ⭐ Payment-proof awareness (E3b): when converting TO online, tell the
            // rider if a WhatsApp/bank payment proof was already received for this
            // order. The pay-change automation already SKIPS the bank-details
            // message in that case (PaymentChangeInvoiceHandler::eligibility), so
            // this flag only sets the rider's expectation ("no message will be
            // sent"). Non-fatal.
            $paymentProofReceived = false;
            try {
                if ($newPaymentType === 'online' && config('payment_signals.enabled')) {
                    // suppressSettled:false — an ALREADY-APPROVED online payment must
                    // also read as "received" here, mirroring the automation handler
                    // (which skips both proof-received AND settled invoices).
                    $st = app(\App\Services\Payments\Signals\PaymentProofStatusService::class)
                        ->forOrder($order->id, suppressSettled: false)['status'] ?? \App\Services\Payments\Signals\PaymentProofStatusService::NONE;
                    $paymentProofReceived = ($st !== \App\Services\Payments\Signals\PaymentProofStatusService::NONE);
                }
            } catch (\Throwable $ppErr) {
                \Log::debug('Proof lookup on payment change skipped (non-fatal)', ['error' => $ppErr->getMessage()]);
            }

            $baseMsg = 'Payment method changed to ' . ($newPaymentType === 'cash' ? 'Cash' : 'Online/Bank');
            return response()->json([
                'success' => true,
                'message' => $paymentProofReceived
                    ? $baseMsg . '. Payment was already received for this order — no payment message will be sent to the customer.'
                    : $baseMsg,
                'payment_proof_received' => $paymentProofReceived,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to change payment method', [
                'order_id' => $id,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to change payment method: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Mark that the WhatsApp payment reminder message was sent for an online order
     * This only sets a flag - does NOT affect delivery status, ledger, or settlement flow
     */
    public function markOnlineMessageSent(Request $request, $id)
    {
        try {
            $user = Auth::user();

            $request->validate([
                // Sep-2026: the orders a MULTI-invoice reminder covered. Absent
                // for the ordinary one-invoice send, which behaves exactly as
                // before — including for the APK already on riders' phones.
                'order_ids'   => 'nullable|array|max:50',
                'order_ids.*' => 'integer',
            ]);

            $ids = $request->input('order_ids') ?: [$id];

            $result = app(\App\Services\Payments\OnlineFollowUpService::class)
                ->stampReminded($ids, $user->id);

            if (empty($result['stamped'])) {
                $reason = reset($result['skipped']) ?: 'Order not found';

                return response()->json([
                    'success' => false,
                    'message' => $reason,
                ], $reason === 'Order not found' ? 404 : 400);
            }

            return response()->json([
                'success' => true,
                'message' => 'Message status updated',
                'online_message_sent_at' => now()->toIso8601String(),
                'stamped' => $result['stamped'],
                'skipped' => $result['skipped'],
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to mark online message sent', [
                'order_id' => $id,
                'error' => $e->getMessage(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to update message status: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Get ledger balance and recent transactions for logged-in rider
     */
    public function getLedger(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Get rider's account (employee_cash category)
            $account = \App\Models\FIN\AccountModel::where('user_id', $user->id)
                ->where('account_category', \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH)
                ->first();

            if (!$account) {
                // Return empty ledger if no account exists yet
                return response()->json([
                    'success' => true,
                    'account_id' => null,
                    'balance' => 0,
                    'balance_formatted' => 'Rs. 0',
                    'balance_type' => 'No account yet',
                    'outstanding_invoices' => [
                        'count' => 0,
                        'total' => 0,
                        'total_formatted' => 'Rs. 0',
                    ],
                    'recent_transactions' => [],
                ]);
            }

            // Use CALCULATED balance for employee_cash accounts
            // This excludes salary/personal transactions - only tracks company cash held
            $balance = $account->getCalculatedBalance();

            // Get recent transactions that affect balance (last 30 days)
            // For employee_cash: excludes salary_payment, salary_advance, etc.
            $recentTransactions = $account->getBalanceAffectingTransactions(30)
                ->map(function($txn) use ($account) {
                    return [
                        'id' => $txn->id,
                        'date' => $txn->transaction_date->format('Y-m-d'),
                        'type' => $txn->transaction_type,
                        'description' => $txn->description,
                        'amount' => $txn->amount,
                        'amount_formatted' => 'Rs. ' . number_format($txn->amount, 0),
                        'is_debit' => $txn->from_account_id == $account->id,
                        'is_credit' => $txn->to_account_id == $account->id,
                    ];
                });

            // Get outstanding invoices count and total
            // IMPORTANT: Include both 'open' and 'partial' statuses, exclude REVERSED transactions
            $outstandingInvoices = \App\Models\FIN\LedgerModel::where('to_account_id', $account->id)
                ->where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_INVOICE)
                ->whereIn('settlement_status', ['open', 'partial'])
                ->where('approval_status', '!=', \App\Models\FIN\LedgerModel::STATUS_REVERSED)
                ->get();

            $totalOutstanding = $outstandingInvoices->sum(function($invoice) {
                return $invoice->amount - ($invoice->settled_amount ?? 0);
            });

            // ⭐ Get loan, advance, and petty cash balances for display in rider mode
            $loanBalance = 0;
            $advanceBalance = 0;
            $pettyCash = $account->petty_cash ?? 0;
            
            if ($account->user_id) {
                // Get total outstanding loan balance
                $loanBalance = \App\Models\HR\EmployeeLoanModel::where('user_id', $account->user_id)
                    ->where('loan_status', 'active')
                    ->sum('outstanding_balance');
                
                // Get total pending salary advances (from approved but not settled requests)
                $advanceBalance = \App\Models\Request\RequestModel::where('requester_user_id', $account->user_id)
                    ->whereHas('category', function($q) {
                        $q->where('category_code', 'salary_advance');
                    })
                    ->where('status', 'approved')
                    ->where(function($q) {
                        $q->whereNull('settlement_status')
                          ->orWhere('settlement_status', '!=', 'settled');
                    })
                    ->sum('amount');
            }

            return response()->json([
                'success' => true,
                'account_id' => $account->id,
                'balance' => $balance,
                'balance_formatted' => 'Rs. ' . number_format(abs($balance), 2),
                'balance_type' => $balance >= 0 ? 'You are owed' : 'You owe',
                'outstanding_invoices' => [
                    'count' => $outstandingInvoices->count(),
                    'total' => $totalOutstanding,
                    'total_formatted' => 'Rs. ' . number_format($totalOutstanding, 0),
                ],
                'loan_balance' => round($loanBalance, 0),
                'loan_balance_formatted' => 'Rs. ' . number_format($loanBalance, 0),
                'advance_balance' => round($advanceBalance, 0),
                'advance_balance_formatted' => 'Rs. ' . number_format($advanceBalance, 0),
                'petty_cash' => round($pettyCash, 0),
                'petty_cash_formatted' => 'Rs. ' . number_format($pettyCash, 0),
                'recent_transactions' => $recentTransactions,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get rider ledger', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load ledger: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Get expense categories (for short cash settlements)
     */
    public function getExpenseCategories(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check if user has admin role (super_admin or admin type)
            $isAdmin = $user->roles()
                ->whereIn('type', ['super_admin', 'admin'])
                ->exists();
            
            if ($isAdmin) {
                // Admin users: Get all categories from existing expenses
            $categories = \App\Models\Request\RequestModel::whereHas('category', function($q) {
                    $q->whereIn('category_code', ['expense', 'salary_advance']);
                })
                ->whereNotNull('expense_category')
                ->where('expense_category', '!=', '')
                ->distinct()
                ->pluck('expense_category')
                ->sort()
                ->values()
                ->toArray();

            // Add PENDING as a special option at the top for partial payments
            array_unshift($categories, 'PENDING');
            } else {
                // Non-admin users: Limited categories only
                $categories = ['Petrol', 'Maintenance', 'PENDING'];
            }

            return response()->json([
                'success' => true,
                'categories' => $categories,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get expense categories', [
                'error' => $e->getMessage(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load categories: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Get expense categories from config table (for expense request form dropdown)
     * Same data source as the web expense form
     * ⭐ Supports business_unit_id filter for Khaas mode
     */
    /**
     * Qurbani Expense screen summary (mobile).
     *
     * Powers the four KPI cards on the new mobile QurbaniExpensesScreen:
     *   - Revenue (delivered Qurbani orders this year, by canonical
     *     OR-rule that matches /qurbani/invoices)
     *   - Vendor Purchases (ledger rows linked to a Qurbani request
     *     or order, transaction_type = vendor_purchase, approved)
     *   - Available years (years that have at least one qurbani
     *     order or request — feeds the year picker)
     *
     * Auth: any user with `view_expenses` mobile permission. The
     * regular Qurbani-mode permission gates the screen visibility on
     * the client side; this endpoint only validates the underlying
     * expense permission.
     *
     * Why a separate endpoint instead of bolting onto /expenses?
     * Keeps the existing endpoint focused on listing rows. Revenue +
     * vendor purchases are a different shape (single scalar each)
     * and are only ever needed when on the Qurbani tab.
     */
    public function getQurbaniExpenseSummary(Request $request)
    {
        try {
            $user = \Illuminate\Support\Facades\Auth::user();
            if (!$user || !$user->hasMobilePermission('view_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view expenses',
                ], 403);
            }

            $year = (int) $request->input('year', date('Y'));
            if ($year < 2024 || $year > 2099) { $year = (int) date('Y'); }
            $dateFrom = $year . '-01-01';
            $dateTo   = $year . '-12-31';

            // Booked revenue — every non-cancelled qurbani order
            // created this year. May-2026 — replaces the old
            // "delivered revenue" definition so the operator sees
            // what the season is *committed* to bring in, with a
            // Paid / Pending split coming from order.total_paid.
            $bookedQuery = \DB::table('t_crm_prod_order as o')
                ->whereRaw('YEAR(o.created_at) = ?', [$year])
                ->whereRaw("LOWER(COALESCE(o.order_status, '')) <> 'cancelled'")
                ->where(function ($q) {
                    $q->whereNull('o.external_source')
                      ->orWhere('o.external_source', '!=', 'shopify');
                });
            \App\Services\QurbaniFinanceFilter::applyToOrderQuery($bookedQuery, 'o', \App\Services\QurbaniFinanceFilter::MODE_INCLUDE);
            $bookedTotals = $bookedQuery
                ->selectRaw('COALESCE(SUM(o.total_price), 0) as booked, COALESCE(SUM(o.total_paid), 0) as paid')
                ->first();
            $booked = (float) ($bookedTotals->booked ?? 0);
            $paid   = (float) ($bookedTotals->paid ?? 0);
            $pending = max(0.0, $booked - $paid);

            // Vendor purchases — ledger leg.
            $vendorQuery = \DB::table('t_fin_ledger as l')
                ->where('l.transaction_type', 'vendor_purchase')
                ->where('l.approval_status', 'approved')
                ->whereRaw('DATE(l.transaction_date) >= ?', [$dateFrom])
                ->whereRaw('DATE(l.transaction_date) <= ?', [$dateTo]);
            \App\Services\QurbaniFinanceFilter::applyToLedgerQuery($vendorQuery, 'l', \App\Services\QurbaniFinanceFilter::MODE_INCLUDE);
            $vendorPurchases = (float) $vendorQuery->sum('l.amount');

            // Year picker source — orders and requests.
            $orderYears = \DB::table('t_crm_prod_order as o')
                ->where(function ($q) {
                    $q->whereNull('o.external_source')
                      ->orWhere('o.external_source', '!=', 'shopify');
                })
                ->whereRaw("LOWER(COALESCE(o.order_status, '')) <> 'cancelled'");
            \App\Services\QurbaniFinanceFilter::applyToOrderQuery($orderYears, 'o', \App\Services\QurbaniFinanceFilter::MODE_INCLUDE);
            $orderYears = $orderYears
                ->selectRaw('DISTINCT YEAR(o.created_at) as y')
                ->pluck('y')
                ->all();
            $reqYears = \DB::table('t_req_master as r')
                ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                ->where('c.category_code', 'qurbani')
                ->whereNotNull('r.ledger_transaction_id')
                ->selectRaw('DISTINCT YEAR(COALESCE(r.expense_date, r.created_at)) as y')
                ->pluck('y')
                ->all();
            $availableYears = collect(array_merge([(int) date('Y')], $orderYears, $reqYears))
                ->filter(fn ($y) => is_numeric($y) && $y >= 2024 && $y <= 2099)
                ->map(fn ($y) => (int) $y)
                ->unique()
                ->sortDesc()
                ->values()
                ->all();

            return response()->json([
                'success' => true,
                'year' => $year,
                // Legacy field kept as alias to avoid breaking any
                // already-deployed mobile build that still reads
                // `revenue` — now mirrors `booked`.
                'revenue' => $booked,
                'booked' => $booked,
                'paid' => $paid,
                'pending' => $pending,
                'vendor_purchases' => $vendorPurchases,
                'available_years' => $availableYears,
            ]);
        } catch (\Throwable $e) {
            \Log::error('getQurbaniExpenseSummary failed: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to load Qurbani summary',
            ], 500);
        }
    }

    public function getExpenseCategoriesFromConfig(Request $request)
    {
        try {
            $businessUnitId = $request->input('business_unit_id');
            $requestCategoryCode = $request->input('request_category_code');
            
            $query = \App\Models\FIN\ConfigModel::where('config_key', 'LIKE', 'EXPENSE_CATEGORY_%')
                ->where('config_key', '!=', 'EXPENSE_CATEGORY_STAFF_SALARIES'); // salaries go through Payroll now

            if ($businessUnitId) {
                if ($businessUnitId == 1) {
                    $query->where(function($q) {
                        $q->where('business_unit_id', 1)
                          ->orWhereNull('business_unit_id');
                    });
                } else {
                    $query->where('business_unit_id', $businessUnitId);
                }
            }

            if ($requestCategoryCode) {
                $isOriginalType = in_array($requestCategoryCode, ['expense', 'khaas_expense']);
                if ($isOriginalType) {
                    $query->where(function ($q) use ($requestCategoryCode) {
                        $q->whereNull('request_category_code')
                          ->orWhere('request_category_code', $requestCategoryCode);
                    });
                } else {
                    $query->where('request_category_code', $requestCategoryCode);
                }
            }
            
            $categories = $query->orderBy('config_value')
                ->pluck('config_value')
                ->toArray();

            // Jun-2026 — quick-select "bubbles": the admin-chosen ordered subset
            // shown as chips above the Expense Type dropdown. Stored per
            // (business unit + request category). Falls back to the first few
            // until an admin customises it. (The full list is still `categories`.)
            $bubbleKey = $this->expenseBubbleConfigKey($businessUnitId, $requestCategoryCode);
            $saved = json_decode((string) \App\Models\FIN\ConfigModel::get($bubbleKey, ''), true);
            $saved = is_array($saved) ? $saved : [];
            // Keep only names that still exist, preserving the saved order.
            $bubbles = array_values(array_intersect($saved, $categories));
            if (empty($bubbles)) {
                $bubbles = array_slice($categories, 0, 7); // sensible default count
            }

            return response()->json([
                'success' => true,
                'categories' => $categories,
                'bubbles' => $bubbles,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get expense categories from config', [
                'error' => $e->getMessage(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load categories: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Build the scoped config_key that stores the expense-type "bubbles" (the
     * admin-chosen quick-select chips) for a given business unit + request
     * category. GET and POST must normalise identically so the key matches.
     */
    private function expenseBubbleConfigKey($businessUnitId, $requestCategoryCode): string
    {
        $bu  = $businessUnitId ? (int) $businessUnitId : 1;
        $rcc = strtoupper(preg_replace('/[^A-Za-z0-9]+/', '_', (string) ($requestCategoryCode ?: 'expense')));
        return "EXPENSE_BUBBLES__{$rcc}__{$bu}";
    }

    /**
     * The expense-type names available for a (business unit + request category)
     * scope — same filter as getExpenseCategoriesFromConfig, used to VALIDATE a
     * saved bubble list (so we never store a name that isn't a real category).
     */
    private function expenseCategoryNamesForScope($businessUnitId, $requestCategoryCode): array
    {
        $query = \App\Models\FIN\ConfigModel::where('config_key', 'LIKE', 'EXPENSE_CATEGORY_%');

        if ($businessUnitId) {
            if ($businessUnitId == 1) {
                $query->where(function ($q) {
                    $q->where('business_unit_id', 1)->orWhereNull('business_unit_id');
                });
            } else {
                $query->where('business_unit_id', $businessUnitId);
            }
        }

        if ($requestCategoryCode) {
            $isOriginalType = in_array($requestCategoryCode, ['expense', 'khaas_expense']);
            if ($isOriginalType) {
                $query->where(function ($q) use ($requestCategoryCode) {
                    $q->whereNull('request_category_code')
                      ->orWhere('request_category_code', $requestCategoryCode);
                });
            } else {
                $query->where('request_category_code', $requestCategoryCode);
            }
        }

        return $query->orderBy('config_value')->pluck('config_value')->toArray();
    }

    /**
     * POST /rider/expenses/bubbles — admin-only.
     *
     * Save which expense types (and in what order) show as quick-select bubbles
     * above the Expense Type dropdown, for a given business unit + request
     * category. Gated by the `configure_expense_bubbles` mobile permission.
     * Writes ONLY a t_fin_config row (no money/schema impact).
     */
    public function saveExpenseBubbles(Request $request)
    {
        $user = Auth::user();
        if (!$user || !method_exists($user, 'hasMobilePermission')
            || !$user->hasMobilePermission('configure_expense_bubbles')) {
            return response()->json([
                'success' => false,
                'message' => 'You do not have permission to configure expense bubbles.',
            ], 403);
        }

        $businessUnitId      = $request->input('business_unit_id');
        $requestCategoryCode = $request->input('request_category_code');
        $bubbles             = $request->input('bubbles', []);
        if (!is_array($bubbles)) {
            $bubbles = [];
        }

        // Keep only real category names for this scope, preserve submitted order,
        // drop blanks/dupes.
        $valid = $this->expenseCategoryNamesForScope($businessUnitId, $requestCategoryCode);
        $clean = [];
        foreach ($bubbles as $name) {
            $name = is_string($name) ? trim($name) : '';
            if ($name !== '' && in_array($name, $valid, true) && !in_array($name, $clean, true)) {
                $clean[] = $name;
            }
        }

        $key = $this->expenseBubbleConfigKey($businessUnitId, $requestCategoryCode);
        \App\Models\FIN\ConfigModel::set(
            $key,
            json_encode(array_values($clean)),
            'Expense quick-select bubbles (' . ($requestCategoryCode ?: 'expense') . ' / BU ' . ($businessUnitId ?: 1) . ')'
        );

        return response()->json([
            'success' => true,
            'bubbles' => array_values($clean),
        ]);
    }

    /**
     * Get outstanding invoices for settlement (reuses existing controller logic)
     */
    public function getOutstandingInvoices(Request $request)
    {
        try {
            $user = Auth::user();
            
            // CRITICAL FIX: Allow fetching invoices for another user (for NF Ledger settle functionality)
            // If user_id is provided in request, use that (requires permission check)
            // Otherwise, use the logged-in user's ID (rider mode)
            $targetUserId = $request->input('user_id', $user->id);
            
            // Security check: Only allow fetching other users' invoices if user has store mode permission
            if ($targetUserId != $user->id) {
                if (!$user->hasMobilePermission('view_nf_ledger')) {
                    return response()->json([
                        'success' => false,
                        'message' => 'You do not have permission to view other users\' invoices',
                    ], 403);
                }
            }
            
            // Get account for the target user
            $account = \App\Models\FIN\AccountModel::where('user_id', $targetUserId)
                ->where('account_category', \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH)
                ->first();

            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Account not found for this user',
                ], 404);
            }

            // Reuse existing method from EmployeeCashController
            $controller = new \App\Http\Controllers\FIN\EmployeeCashController();
            return $controller->getOutstandingInvoices($account->id);
        } catch (\Exception $e) {
            \Log::error('Failed to get outstanding invoices', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load invoices: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Settle invoices (full or partial payment)
     */
    public function settleInvoices(Request $request)
    {
        try {
            $user = Auth::user();
            
            // CRITICAL FIX: Allow settling for another user (for NF Ledger settle functionality)
            // If user_id is provided in request, use that (requires permission check)
            // Otherwise, use the logged-in user's ID (rider mode)
            $targetUserId = $request->input('user_id', $user->id);
            
            // Security check: Only allow settling other users' accounts if user has store mode permission
            if ($targetUserId != $user->id) {
                if (!$user->hasMobilePermission('view_nf_ledger')) {
                    return response()->json([
                        'success' => false,
                        'message' => 'You do not have permission to settle other users\' accounts',
                    ], 403);
                }
            }
            
            // Get account for the target user
            $account = \App\Models\FIN\AccountModel::where('user_id', $targetUserId)
                ->where('account_category', \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH)
                ->first();

            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Account not found for this user',
                ], 404);
            }

            // Validate request
            $request->validate([
                'amount' => 'required|numeric|min:0.01',
                'transaction_date' => 'required|date',
                'invoice_ids' => 'required|array|min:1',
                'invoice_ids.*' => 'exists:t_fin_ledger,id'
            ]);

            \DB::beginTransaction();

            // Verify selected invoices (include both open/partial invoices and qurbani order_payment entries)
            $selectedInvoices = \App\Models\FIN\LedgerModel::whereIn('id', $request->invoice_ids)
                ->where('to_account_id', $account->id)
                ->whereIn('transaction_type', [\App\Models\FIN\LedgerModel::TYPE_INVOICE, \App\Models\FIN\LedgerModel::TYPE_ORDER_PAYMENT])
                ->whereIn('settlement_status', ['open', 'partial'])
                ->orderBy('transaction_date', 'asc')
                ->get();

            if ($selectedInvoices->count() !== count($request->invoice_ids)) {
                throw new \Exception("Some selected invoices are invalid or already settled");
            }

            // Guard: prevent the same invoice landing in two pending settlements.
            // Reject any invoice that is already fully covered by another pending deposit
            // (root cause of the double-settlement bug). Partial-payment flow is unaffected.
            $alreadyPending = (new \App\Http\Controllers\FIN\EmployeeCashController())
                ->getInvoicesAlreadyPending($account->id, $request->invoice_ids);
            if (!empty($alreadyPending)) {
                $conflictNumbers = $selectedInvoices->whereIn('id', $alreadyPending)
                    ->map(fn($inv) => $inv->order ? $inv->order->order_number : "Invoice #{$inv->id}")
                    ->join(', ');
                throw new \Exception("These invoice(s) already have a pending settlement awaiting approval: {$conflictNumbers}. Please refresh and try again.");
            }

            // Determine destination based on whether these are qurbani order payments
            $hasQurbaniPayments = $selectedInvoices->contains(function ($inv) {
                if ($inv->transaction_type !== \App\Models\FIN\LedgerModel::TYPE_ORDER_PAYMENT) return false;
                if (!$inv->order_id) return false;
                $order = \App\Models\CRM\OrderModel::find($inv->order_id);
                return $order && (str_starts_with($order->order_number ?? '', 'QUR') || !empty($order->qurbani_day));
            });
            $hasRegularInvoices = $selectedInvoices->contains(fn($inv) => $inv->transaction_type === \App\Models\FIN\LedgerModel::TYPE_INVOICE);

            if ($hasQurbaniPayments && $hasRegularInvoices) {
                throw new \Exception("Cannot settle qurbani payments and regular invoices together. Please settle them separately.");
            }

            $destinationAccount = $hasQurbaniPayments
                ? \App\Models\FIN\ConfigModel::getQurbaniCashAccount()
                : \App\Models\FIN\ConfigModel::getNFCashAccount();
            if (!$destinationAccount) {
                throw new \Exception("Destination account not found");
            }

            $totalOutstanding = round($selectedInvoices->sum(function($invoice) {
                return $invoice->amount - ($invoice->settled_amount ?? 0);
            }), 2);

            // Build description
            $invoiceNumbers = $selectedInvoices->map(function($invoice) {
                return $invoice->order ? $invoice->order->order_number : "Invoice #" . $invoice->id;
            })->take(3)->join(', ');
            
            if ($selectedInvoices->count() > 3) {
                $invoiceNumbers .= " + " . ($selectedInvoices->count() - 3) . " more";
            }

            $description = $request->description 
                ? "Settlement: {$invoiceNumbers} - {$request->description}"
                : "Settlement for invoices: {$invoiceNumbers}";

            // Create deposit transaction (pending approval)
            $depositLedger = \App\Models\FIN\LedgerModel::create([
                'transaction_date' => $request->transaction_date,
                'transaction_type' => \App\Models\FIN\LedgerModel::TYPE_EMPLOYEE_DEPOSIT,
                'description' => $description,
                'from_account_id' => $account->id,
                'to_account_id' => $destinationAccount->id,
                'amount' => $request->amount,
                'mode' => \App\Models\FIN\LedgerModel::MODE_CASH,
                'approval_status' => \App\Models\FIN\LedgerModel::STATUS_PENDING,
                'approval_date' => null,
                'approved_by' => null,
                'created_by' => $user->id,
                'comments' => "Settlement deposit for {$selectedInvoices->count()} invoice(s). Total outstanding: Rs. " . number_format($totalOutstanding, 2),
                'settlement_metadata' => [
                    'invoice_ids' => $request->invoice_ids,
                    'deposit_amount' => round((float) $request->amount, 2),
                    'total_outstanding' => $totalOutstanding
                ]
            ]);

            \DB::commit();

            $message = 'Settlement deposit recorded and pending approval!';
            if ($request->amount < $totalOutstanding) {
                $shortfall = $totalOutstanding - $request->amount;
                $message .= " Note: Short by Rs. " . number_format($shortfall, 2);
            }

            return response()->json([
                'success' => true,
                'message' => $message,
                'deposit_id' => $depositLedger->id,
            ]);

        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Failed to settle invoices', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to settle invoices: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Settle with short cash (partial payment + expense request)
     */
    public function settleShortCash(Request $request)
    {
        try {
            $user = Auth::user();
            
            // CRITICAL FIX: Allow settling for another user (for NF Ledger settle functionality)
            // If user_id is provided in request, use that (requires permission check)
            // Otherwise, use the logged-in user's ID (rider mode)
            $targetUserId = $request->input('user_id', $user->id);
            
            // Security check: Only allow settling other users' accounts if user has store mode permission
            if ($targetUserId != $user->id) {
                if (!$user->hasMobilePermission('view_nf_ledger')) {
                    return response()->json([
                        'success' => false,
                        'message' => 'You do not have permission to settle other users\' accounts',
                    ], 403);
                }
            }
            
            // Get account for the target user
            $account = \App\Models\FIN\AccountModel::where('user_id', $targetUserId)
                ->where('account_category', \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH)
                ->first();

            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Account not found for this user',
                ], 404);
            }

            // Validate request
            $request->validate([
                'amount' => 'required|numeric|min:0.01',
                'transaction_date' => 'required|date',
                'invoice_ids' => 'required|array|min:1',
                'invoice_ids.*' => 'exists:t_fin_ledger,id',
                'expense_category' => 'required|string|max:100'
            ]);

            \DB::beginTransaction();

            // Verify selected invoices (include both open/partial invoices and qurbani order_payment entries)
            $selectedInvoices = \App\Models\FIN\LedgerModel::whereIn('id', $request->invoice_ids)
                ->where('to_account_id', $account->id)
                ->whereIn('transaction_type', [\App\Models\FIN\LedgerModel::TYPE_INVOICE, \App\Models\FIN\LedgerModel::TYPE_ORDER_PAYMENT])
                ->whereIn('settlement_status', ['open', 'partial'])
                ->orderBy('transaction_date', 'asc')
                ->get();

            if ($selectedInvoices->count() !== count($request->invoice_ids)) {
                throw new \Exception("Some selected invoices are invalid or already settled");
            }

            // Guard: prevent the same invoice landing in two pending settlements.
            // Reject any invoice that is already fully covered by another pending deposit
            // (root cause of the double-settlement bug). Partial-payment flow is unaffected.
            $alreadyPending = (new \App\Http\Controllers\FIN\EmployeeCashController())
                ->getInvoicesAlreadyPending($account->id, $request->invoice_ids);
            if (!empty($alreadyPending)) {
                $conflictNumbers = $selectedInvoices->whereIn('id', $alreadyPending)
                    ->map(fn($inv) => $inv->order ? $inv->order->order_number : "Invoice #{$inv->id}")
                    ->join(', ');
                throw new \Exception("These invoice(s) already have a pending settlement awaiting approval: {$conflictNumbers}. Please refresh and try again.");
            }

            // Determine destination based on qurbani vs regular
            $hasQurbaniPayments = $selectedInvoices->contains(function ($inv) {
                if ($inv->transaction_type !== \App\Models\FIN\LedgerModel::TYPE_ORDER_PAYMENT) return false;
                if (!$inv->order_id) return false;
                $order = \App\Models\CRM\OrderModel::find($inv->order_id);
                return $order && (str_starts_with($order->order_number ?? '', 'QUR') || !empty($order->qurbani_day));
            });
            $hasRegularInvoices = $selectedInvoices->contains(fn($inv) => $inv->transaction_type === \App\Models\FIN\LedgerModel::TYPE_INVOICE);

            if ($hasQurbaniPayments && $hasRegularInvoices) {
                throw new \Exception("Cannot settle qurbani payments and regular invoices together. Please settle them separately.");
            }

            $destinationAccount = $hasQurbaniPayments
                ? \App\Models\FIN\ConfigModel::getQurbaniCashAccount()
                : \App\Models\FIN\ConfigModel::getNFCashAccount();
            if (!$destinationAccount) {
                throw new \Exception("Destination account not found");
            }

            // Calculate expected amount and shortage (remaining balance for partial invoices) — 2dp
            $totalOutstanding = round($selectedInvoices->sum(function($invoice) {
                return $invoice->amount - ($invoice->settled_amount ?? 0);
            }), 2);

            $depositAmount = round((float) $request->amount, 2);
            $shortCashAmount = round($totalOutstanding - $depositAmount, 2);

            // Use tolerance for floating-point comparison (0.01 Rs tolerance)
            // This handles edge cases from old transactions or rounding issues
            $TOLERANCE = 0.01;
            
            if ($shortCashAmount < -$TOLERANCE) {
                throw new \Exception("Deposit amount cannot exceed total outstanding");
            }
            
            // If shortage is within tolerance (e.g., 0.001 Rs), treat as exact match
            if (abs($shortCashAmount) < $TOLERANCE) {
                $shortCashAmount = 0;
            }

            // Check if this is a PENDING (partial payment) or actual expense
            $expenseRequest = null;
            $isPartialPayment = false;
            
            if (strtoupper($request->expense_category) === 'PENDING') {
                // Partial payment - no expense request, just settle what was deposited
                $isPartialPayment = true;
                \Log::info("Mobile: Partial payment settlement - keeping invoices open", [
                    'user_id' => $user->id,
                    'deposit_amount' => $depositAmount,
                    'remaining_amount' => $shortCashAmount,
                    'total_outstanding' => $totalOutstanding
                ]);
            } else {
                // Create expense request for shortage
                $category = \App\Models\Request\RequestCategoryModel::where('category_code', 'expense')->first();
                if (!$category) {
                    throw new \Exception("Expense category not found in system");
                }

                $expenseRequest = \App\Models\Request\RequestModel::create([
                    'request_number' => \App\Models\Request\RequestModel::generateRequestNumber(),
                    'category_id' => $category->id,
                    'requester_user_id' => $account->user_id,
                    'title' => "Short Cash - {$request->expense_category}",
                    'amount' => $shortCashAmount,
                    'expense_category' => $request->expense_category,
                    'expense_date' => now()->toDateString(), // ⭐ Always set expense_date
                    'description' => "Short cash from invoice settlement - " . $request->expense_category . ($request->description ? " - {$request->description}" : ""),
                    'payment_source_account_id' => $account->id,
                    'status' => \App\Models\Request\RequestModel::STATUS_PENDING,
                    'settlement_status' => 'pending',
                    'requires_level_1' => $category->requiresLevel1(),
                    'requires_level_2' => $category->requiresLevel2(),
                    'level_1_status' => $category->requiresLevel1() ? \App\Models\Request\RequestModel::APPROVAL_STATUS_PENDING : null,
                    'level_2_status' => $category->requiresLevel2() ? \App\Models\Request\RequestModel::APPROVAL_STATUS_PENDING : null,
                    'submitted_at' => now(),
                    'created_by' => $user->id,
                ]);
            }

            // Build description
            $invoiceNumbers = $selectedInvoices->map(function($invoice) {
                return $invoice->order ? $invoice->order->order_number : "Invoice #" . $invoice->id;
            })->take(3)->join(', ');
            
            if ($selectedInvoices->count() > 3) {
                $invoiceNumbers .= " + " . ($selectedInvoices->count() - 3) . " more";
            }

            // Build description and metadata based on settlement type
            if ($isPartialPayment) {
                $description = "Partial Payment: {$invoiceNumbers} - Paid Rs. " . number_format($depositAmount, 2) . ", Remaining Rs. " . number_format($shortCashAmount, 2);
                $comments = "Partial payment. Paid: Rs. " . number_format($depositAmount, 2) . ", Remaining: Rs. " . number_format($shortCashAmount, 2) . " (will remain open)";
                $settlementMetadata = [
                    'invoice_ids' => $request->invoice_ids,
                    'deposit_amount' => $depositAmount,
                    'total_outstanding' => $totalOutstanding,
                    'is_partial_payment' => true,
                    'is_short_cash_settlement' => false,
                    'short_cash_amount' => $shortCashAmount,
                    'expense_category' => 'PENDING'
                ];
            } else {
                $description = "Short Cash Settlement: {$invoiceNumbers} (Shortage: {$request->expense_category})";
                $comments = "Short cash settlement. Deposit: Rs. " . number_format($depositAmount, 2) . ", Shortage (Expense #{$expenseRequest->request_number}): Rs. " . number_format($shortCashAmount, 2);
                $settlementMetadata = [
                    'invoice_ids' => $request->invoice_ids,
                    'deposit_amount' => $depositAmount,
                    'total_outstanding' => $totalOutstanding,
                    'is_short_cash_settlement' => true,
                    'is_partial_payment' => false,
                    'short_cash_amount' => $shortCashAmount,
                    'expense_request_id' => $expenseRequest->id,
                    'expense_category' => $request->expense_category
                ];
            }

            // Create deposit transaction
            $depositLedger = \App\Models\FIN\LedgerModel::create([
                'transaction_date' => $request->transaction_date,
                'transaction_type' => \App\Models\FIN\LedgerModel::TYPE_EMPLOYEE_DEPOSIT,
                'description' => $description,
                'from_account_id' => $account->id,
                'to_account_id' => $destinationAccount->id,
                'amount' => $depositAmount,
                'mode' => \App\Models\FIN\LedgerModel::MODE_CASH,
                'approval_status' => \App\Models\FIN\LedgerModel::STATUS_PENDING,
                'created_by' => $user->id,
                'comments' => $comments,
                'settlement_metadata' => $settlementMetadata
            ]);

            \DB::commit();

            // Build response message
            if ($isPartialPayment) {
                $message = "Partial payment recorded! Paid: Rs. " . number_format($depositAmount, 2) . ". Remaining Rs. " . number_format($shortCashAmount, 2) . " will stay open for future settlement.";
                $responseData = [
                    'success' => true,
                    'message' => $message,
                    'deposit_id' => $depositLedger->id,
                    'is_partial_payment' => true
                ];
            } else {
                $message = "Short cash settlement recorded! Deposit: Rs. " . number_format($depositAmount, 2) . ". Expense request #{$expenseRequest->request_number} created for shortage of Rs. " . number_format($shortCashAmount, 2);
                $responseData = [
                    'success' => true,
                    'message' => $message,
                    'deposit_id' => $depositLedger->id,
                    'expense_request_id' => $expenseRequest->id
                ];
            }

            return response()->json($responseData);

        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Failed to settle short cash', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to settle with short cash: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Get today's attendance for logged-in rider
     */
    public function getTodayAttendance(Request $request)
    {
        try {
            $user = Auth::user();
            $today = now()->format('Y-m-d');

            $attendance = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)
                ->whereDate('attendance_date', $today)
                ->first();

            // ⭐ Past-midnight shift (owner-approved Jul-28): at 00:05 "today" has no row, so the
            //    app showed "Check In" to a rider still mid-shift — the wrong button at the worst
            //    moment (tapping IN would orphan yesterday's open shift AND block the server's
            //    midnight checkout fallback). Before 06:00, yesterday's OPEN shift IS his day:
            //    serve that row, so the app shows checked-in state + the OUT button. Same bound
            //    The bound and the open-row condition now live in AttendanceDay, so this can no
            //    longer drift away from the other doors (it did — see uploadMeterPicture, 1 Sep).
            //    After he checks out (or past 06:00) this no-ops and the new day starts clean.
            $crossMidnight = false;
            if (!$attendance || !$attendance->login_time) {
                $openYesterday = (new \App\Services\Riders\AttendanceDay())->openPastMidnightRow($user->id);
                if ($openYesterday) {
                    $attendance = $openYesterday;
                    $crossMidnight = true;
                }
            }

            // Get user's assigned office location
            $assignedLocation = \DB::table('t_ops_user_location_assignment as ula')
                ->join('t_ops_company_locations as loc', 'loc.id', '=', 'ula.location_id')
                ->where('ula.user_id', $user->id)
                ->where('ula.is_active', 1)
                ->where('loc.is_active', 1)
                ->select('loc.location_name', 'loc.latitude', 'loc.longitude', 'loc.radius_meters')
                ->first();

            // If no assigned location, get primary location
            if (!$assignedLocation) {
                $assignedLocation = \DB::table('t_ops_company_locations')
                    ->where('is_primary', 1)
                    ->where('is_active', 1)
                    ->select('location_name', 'latitude', 'longitude', 'radius_meters')
                    ->first();
            }

            // Rider's current shift + any change awaiting their acknowledgment (additive fields).
            $shiftSvc = new \App\Services\ShiftResolutionService();
            $todayShift = $shiftSvc->getUserShift(Auth::id(), now()->format('Y-m-d'));

            // "Your Office" banner should show where the SHIFT expects them today
            // (assignment location → default → primary) — same location check-in verifies.
            if (!empty($todayShift['location_id'])) {
                $shiftLoc = \DB::table('t_ops_company_locations')
                    ->where('id', $todayShift['location_id'])->where('is_active', 1)
                    ->select('location_name', 'latitude', 'longitude', 'radius_meters')->first();
                if ($shiftLoc) {
                    $assignedLocation = $shiftLoc;
                }
            }
            $pendingAck = \App\Models\Ops\UserShiftAssignmentModel::with('shiftTemplate')
                ->where('user_id', Auth::id())
                ->whereNotNull('notified_at')->whereNull('acknowledged_at')
                // Don't nag for a temporary change that's already fully in the past.
                ->where(function ($q) {
                    $q->whereNull('effective_to')->orWhereDate('effective_to', '>=', now()->format('Y-m-d'));
                })
                // Most-recently-notified first (a same-day correction updates an older row in place).
                ->orderByDesc('notified_at')->orderByDesc('id')->first();
            $pendingAckData = null;
            if ($pendingAck && $pendingAck->shiftTemplate) {
                $pendingAckData = [
                    'assignment_id' => $pendingAck->id,
                    'shift_name' => $pendingAck->shiftTemplate->shift_name,
                    'start' => substr($pendingAck->shiftTemplate->shift_start, 0, 5),
                    'end' => $pendingAck->shiftTemplate->shift_end ? substr($pendingAck->shiftTemplate->shift_end, 0, 5) : null,
                    'effective_from' => $pendingAck->effective_from ? $pendingAck->effective_from->format('Y-m-d') : null,
                    'effective_to' => $pendingAck->effective_to ? $pendingAck->effective_to->format('Y-m-d') : null,
                ];
            }

            // Today's leave (if any) — lets the app show "leave applied / approved"
            // on the Today card instead of "Not checked in / Apply for leave".
            $todayLeave = null;
            try {
                $leaveCatId = \DB::table('t_req_category')->where('category_code', 'leave')->value('id');
                if ($leaveCatId) {
                    $lv = \DB::table('t_req_master')
                        ->where('category_id', $leaveCatId)
                        ->where('requester_user_id', $user->id)
                        ->whereIn('status', ['approved', 'pending', 'pending_l1', 'pending_l2', 'submitted'])
                        ->whereRaw('? BETWEEN leave_start_date AND leave_end_date', [$today])
                        ->orderByDesc('id')
                        ->first();
                    if ($lv) {
                        $todayLeave = [
                            'id' => $lv->id,
                            'status' => $lv->status,        // approved | pending | ...
                            'type' => $lv->leave_type,      // planned | emergency
                            'start' => substr((string) $lv->leave_start_date, 0, 10),
                            'end' => substr((string) $lv->leave_end_date, 0, 10),
                        ];
                    }
                }
            } catch (\Throwable $e) { /* card just shows the normal state */ }

            // U4 — going-home journey state for company-bike riders (drives the app's Ride-Home /
            // locked / record-meter card + the global banner). Additive + guarded; null otherwise.
            // home_flow (bool) tells the app BEFORE checkout that this rider records his meter at
            // HOME, so the end-meter prompt at checkout is skipped.
            [$homeJourneyToday, $homeFlow] = $this->buildHomeJourneyPayload($user->id, $attendance);

            // U5 — MORNING start journey (offer / riding / overdue) for the "Start your day"
            // card. Additive + guarded; null for non-bike riders, once checked in, on off-days,
            // and on leave days (no card nagging someone who isn't riding in today).
            $workJourneyToday = $this->buildWorkJourneyPayload($user->id, $attendance, $todayLeave);

            // R1 — may this rider check in at any office? (banner text; guarded)
            $anyOfficeAllowed = false;
            try {
                if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_rider_profile', 'checkin_any_office')) {
                    $anyOfficeAllowed = (int) \DB::table('t_ops_rider_profile')->where('user_id', $user->id)->value('checkin_any_office') === 1;
                }
            } catch (\Throwable $e) { /* default false */ }

            // Is the meter reading compulsory for this user? (Phase D: the bike registry
            // decides — see meterRequiredForUser(). Falls back to the riders-page tag.)
            // null = column not deployed yet → the app keeps its legacy optional behaviour.
            $meterRequired = $this->meterRequiredForUser($user->id, $today);

            // ⭐ WHICH MACHINE HE IS ABOUT TO CLOSE THE DAY ON, and — when he arrived on his own
            //   bike and is still holding a company machine — the choice he should be offered
            //   before he does. Both additive and null-safe; see checkoutMachineContext().
            [$closingMachine, $checkoutChoice] =
                $this->checkoutMachineContext((int) $user->id, $attendance, (bool) $homeFlow, $meterRequired);

            return response()->json([
                'success' => true,
                'attendance' => $attendance ? [
                    'id' => $attendance->id,
                    'attendance_date' => $attendance->attendance_date,
                    'login_time' => $attendance->login_time,
                    'logout_time' => $attendance->logout_time,
                    'notes' => $attendance->notes,
                    'is_checked_in' => $attendance->login_time !== null,
                    'is_checked_out' => $attendance->logout_time !== null,
                    'checkin_latitude' => $attendance->checkin_latitude ?? null,
                    'checkin_longitude' => $attendance->checkin_longitude ?? null,
                    'checkin_distance_from_base' => $attendance->checkin_distance_from_base ?? null,
                    'is_remote_checkin' => $attendance->is_remote_checkin ?? 0,
                    'meter_start' => $attendance->meter_start ? (int) $attendance->meter_start : null,
                    'meter_end' => $attendance->meter_end ? (int) $attendance->meter_end : null,
                    'meter_start_source' => $attendance->meter_start_source ?? null, // U5: home | checkin | manager
                    // Photo URLs so the app can show a "saved" tile with the thumbnail
                    // instead of the bare upload button (additive; old APKs ignore).
                    'picture_start' => !empty($attendance->picture_start) ? $this->getMeterPictureUrl($attendance->picture_start) : null,
                    'picture_end' => !empty($attendance->picture_end) ? $this->getMeterPictureUrl($attendance->picture_end) : null,
                    // ⭐ TRUE when this is yesterday's still-open shift served past midnight
                    //    (before 06:00). Additive — current APKs ignore it and simply render
                    //    the checked-in state, which is exactly the point.
                    'cross_midnight' => $crossMidnight,
                ] : null,
                'assigned_location' => $assignedLocation ? [
                    'name' => $assignedLocation->location_name,
                    'latitude' => $assignedLocation->latitude,
                    'longitude' => $assignedLocation->longitude,
                    'radius_meters' => $assignedLocation->radius_meters,
                    // ⭐ Sep-2026: the radius the SERVER actually judges against (location radius
                    //   capped by OFFICE_AT_RADIUS_M) + the "coarse fix" line, so the app's map
                    //   circle and its verdict can never disagree with the 422 that follows. Before
                    //   this the app used the RAW radius — "On-site" at 1.5 km from the main office
                    //   (2000 m) and then a server rejection at 300. Additive; old APKs ignore both.
                    'effective_radius_m' => (int) round(LocationService::effectiveOfficeRadius((float) $assignedLocation->radius_meters)),
                    'coarse_fix_m' => (int) $this->attnConfig('COARSE_FIX_M', 150),
                    // R1 — this rider may check in at ANY office (banner shows it; server authoritative).
                    'any_office' => $anyOfficeAllowed,
                ] : null,
                // NEW (additive): rider's own shift + pending acknowledgment
                'shift' => [
                    'shift_name' => $todayShift['shift_name'],
                    'start' => $todayShift['shift_start'],
                    'end' => $todayShift['shift_end'], // null for start-only shifts
                    'location_name' => $todayShift['location_name'] ?? null,
                ],
                // Manager's "must be at your location to check in" rule (default off).
                // The app uses this to require a real GPS fix before check-in.
                'require_location' => $this->attendanceRequiresLocation(),
                // Manager's "must check out at office or last delivery" rule (default off).
                'checkout_rule' => $this->checkoutRuleEnabled(),
                'pending_shift_ack' => $pendingAckData,
                'today_leave' => $todayLeave,
                'home_journey' => $homeJourneyToday, // U4: null unless a bike home journey is active
                'home_flow' => $homeFlow, // U4: this rider records his meter at HOME (skip end-meter at checkout)
                'work_journey' => $workJourneyToday, // U5: morning start card (offer/riding/overdue), null otherwise
                'meter_required' => $meterRequired, // 1 = compulsory, 0 = exempt, null = legacy (optional)
                // ⭐ The machine his closing reading will be OF — so the checkout dialogs can name
                //   it instead of asking for "the meter". Null when the registry cannot say.
                'closing_machine' => $closingMachine,
                // ⭐ "You came on your own bike but you are holding the van" — null on every
                //   ordinary day. See checkoutMachineContext() for the six conditions.
                'checkout_choice' => $checkoutChoice,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get today attendance', [
                'error' => $e->getMessage(),
            ]);
            
            return response()->json(['success' => false, 'message' => 'Failed to load attendance: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Check in for today
     * Optionally accepts meter picture and GPS location
     */
    /**
     * ⭐⭐ "WHICH MACHINE AM I CHECKING OUT ON?" — and the one question worth asking first.
     *
     * ⚠⚠ THE DAY THIS EXISTS FOR (Rajab, 11-Sep-2026). He rode his own bike to work, took the
     *    van at 13:32, delivered on it all afternoon, and pressed OUT at 18:54 while still
     *    holding it. The server behaved correctly — rule 2 of the checkout meter ladder asked
     *    for the VAN's closing reading and stamped 75,484 to the van. He handed the van back at
     *    18:56, and at 18:59 typed his own bike's 7,610 into the still-open START tile. One
     *    attendance row, two odometers, and a "distance" of 67,874 km.
     *
     *    Nothing was wrong except the ORDER. What should have happened is: hand the van back
     *    first (recording its close), then check out on his own bike. So the app now asks.
     *
     * ⚠⚠ IT MUST NEVER BLOCK. A rider who takes the van HOME and leaves his bike at the office
     *    is a perfectly normal day, and the manager who approves hand-backs may be busy. This
     *    returns information; `checkOut()` is untouched and still lets him close on the van.
     *
     * Returns [closing_machine, checkout_choice]:
     *   · closing_machine — EVERY rider, every day: the machine his closing reading is of, plus
     *     his start reading, so the dialogs can say "🏍 your own bike · start 7,610" instead of
     *     "the meter". Null only when the registry has no answer.
     *   · checkout_choice — ONLY on a Rajab-shaped day. Six conditions, ALL required:
     *       1. on duty (checked in, not checked out)          — nothing to offer otherwise
     *       2. holds a COMPANY machine right now
     *       3. he STARTED this day on his own bike            — stamp, or an assignment of it
     *                                                           released today that began earlier
     *       4. that own bike is free (nobody else holds it)   — `ownVehicleFor` enforces this
     *       5. NOT a home-flow rider (no home pin)            — U4 collects his close at home
     *       6. meter_required === 1                           — management riders are never asked
     *
     * ⚠ `currentVehicleFor` — the SAME resolver `meterStampFields()` uses to stamp the reading.
     *   Asking a different question here would let the app name one machine while the server
     *   recorded another, which is the exact class of bug this whole change is about.
     *
     * ⚠ Never throws: any failure returns [null, null] and the app behaves exactly as it did
     *   before this existed.
     */
    private function checkoutMachineContext(int $userId, $attendance, bool $homeFlow, ?int $meterRequired): array
    {
        try {
            // 1. on duty
            if (!$attendance || empty($attendance->login_time) || !empty($attendance->logout_time)) {
                return [null, null];
            }

            $res = new \App\Services\Riders\VehicleResolver();
            $vid = $res->currentVehicleFor($userId);
            if (!$vid) return [null, null];              // holds nothing → nothing to name
            $v = $res->vehicle($vid);
            if (!$v) return [null, null];

            $isCompany = (int) ($v->is_company ?? 1) === 1;

            // ⭐ The start reading's TIME: prefer the stamped recording moment, else check-in.
            //   Both are wall-clock on this server (DATETIME / TIME), so neither is affected by
            //   the TIMESTAMP timezone conversion that trips up created_at columns.
            $startAt = !empty($attendance->meter_start_recorded_at)
                ? substr((string) $attendance->meter_start_recorded_at, 11, 5)
                : (!empty($attendance->login_time) ? substr((string) $attendance->login_time, 0, 5) : null);

            $closing = [
                'id'           => (int) $vid,
                'label'        => \App\Services\Riders\MeterPairHelper::labelOf($v),
                'vtype'        => ((string) ($v->vtype ?? '')) === 'van' ? 'van' : 'bike',
                'is_company'   => $isCompany,
                'start_meter'  => !empty($attendance->meter_start) ? (int) $attendance->meter_start : null,
                'start_time'   => $startAt,
                /**
                 * ⭐ WHICH MACHINE THE MORNING READING IS OF — so the phone can tell whether
                 *   `end - start` is a distance at all.
                 *
                 * ⚠⚠ THE APP'S TWO TYPO GUARDS BOTH SUBTRACT THESE ENDS ("end is less than
                 *    start", "high distance"). On a two-machine day that is not a typo check,
                 *    it is nonsense: closing the VAN at 75,500 against the bike's 7,620 warned
                 *    "the distance for today would be 67,880 km" — caught on the real phone,
                 *    on the very flow where closing on the van is the rider's deliberate
                 *    choice. The mirror case (start on the van, close on his own bike) accuses
                 *    him of an end lower than the start. The phone skips both when this differs
                 *    from `id`.
                 * ⚠ NULL on an unstamped row (older data, or no start reading yet), which the
                 *   phone treats as "comparable" — exactly today's behaviour.
                 */
                'start_vehicle_id' => (\App\Services\Riders\VehicleService::stampsAvailable()
                    && !empty($attendance->meter_start)
                    && !empty($attendance->meter_start_vehicle_id))
                        ? (int) $attendance->meter_start_vehicle_id : null,
            ];

            // 2 / 5 / 6 — cheap disqualifiers first.
            if (!$isCompany)                 return [$closing, null];   // already on his own bike
            if ($homeFlow)                   return [$closing, null];   // U4 owns his close
            if ((int) $meterRequired !== 1)  return [$closing, null];   // never asked for a meter

            // 4 — his own bike, and only if nobody is holding it (ownVehicleFor's own rule).
            $svc = new \App\Services\Riders\VehicleService();
            $own = $svc->ownVehicleFor($userId);
            if (!$own || (int) $own['id'] === (int) $vid) return [$closing, null];
            $ownVeh = $res->vehicle((int) $own['id']);
            if (!$ownVeh) return [$closing, null];

            // 3 — did this DAY begin on that bike?
            $shiftDate = substr((string) $attendance->attendance_date, 0, 10);
            $startedOnOwn = false;

            if (\App\Services\Riders\VehicleService::stampsAvailable()
                && !empty($attendance->meter_start_vehicle_id)
                && (int) $attendance->meter_start_vehicle_id === (int) $own['id']) {
                $startedOnOwn = true;                    // he recorded the morning on it
            }

            if (!$startedOnOwn) {
                /**
                 * ⚠⚠ DELIBERATELY NOT "is his own bike his default" — the assignment table is
                 *    asked instead, for a row on that bike which was RELEASED today having
                 *    begun BEFORE today. That is precisely "he arrived on it and gave it up
                 *    during this shift", which is the case worth asking about. A bike released
                 *    yesterday evening (he took the van home) does not match, and must not:
                 *    that is the flow the owner explicitly does not want interrupted.
                 */
                $startedOnOwn = \DB::table(\App\Services\Riders\VehicleService::T_ASSIGN)
                    ->where('user_id', $userId)
                    ->where('vehicle_id', (int) $own['id'])
                    ->whereDate('released_on', $shiftDate)
                    ->whereDate('assigned_on', '<', $shiftDate)
                    ->exists();
            }

            if (!$startedOnOwn) return [$closing, null];

            // Since when has he held the company machine? Read from the handover request's
            // `decided_at` (a DATETIME — exact) when a request produced this assignment; null
            // otherwise. Never from the assignment's TIMESTAMP created_at, which renders
            // shifted on any box whose MySQL session timezone differs from the app's.
            $heldSince = null;
            try {
                $openAssign = \DB::table(\App\Services\Riders\VehicleService::T_ASSIGN)
                    ->where('user_id', $userId)->where('vehicle_id', (int) $vid)
                    ->whereNull('released_on')->orderByDesc('id')->first(['id']);
                if ($openAssign) {
                    $dec = \DB::table('t_ops_vehicle_handover_request')
                        ->where('applied_assignment_id', (int) $openAssign->id)
                        ->whereNotNull('decided_at')->orderByDesc('id')->value('decided_at');
                    if ($dec && substr((string) $dec, 0, 10) === $shiftDate) {
                        $heldSince = substr((string) $dec, 11, 5);
                    }
                }
            } catch (\Throwable $e) { $heldSince = null; }

            // Has he ALREADY asked for the swap? Then the app must say "waiting for approval"
            // rather than offering to raise a second request the server would refuse
            // (one open request per rider). Counts BOTH shapes of the same intent: a RETURN
            // of the machine he holds, and a TAKE of his own bike back (which is what Rajab
            // actually sent on 11-Sep).
            $pending = null;
            try {
                $openReq = (new \App\Services\Riders\VehicleHandoverRequestService())->openFor($userId);
                if ($openReq) {
                    $isReturnOfHeld = ($openReq['direction'] ?? '') === 'return'
                        && (int) ($openReq['vehicle_id'] ?? 0) === (int) $vid;
                    $isTakeOfOwn    = ($openReq['direction'] ?? '') === 'take'
                        && (int) ($openReq['vehicle_id'] ?? 0) === (int) $own['id'];
                    if ($isReturnOfHeld || $isTakeOfOwn) {
                        $pending = [
                            'id'           => (int) $openReq['id'],
                            'direction'    => (string) $openReq['direction'],
                            'meter'        => $openReq['meter_claimed'] ?? null,
                            'requested_at' => !empty($openReq['requested_at'])
                                ? substr((string) $openReq['requested_at'], 11, 5) : null,
                        ];
                    }
                }
            } catch (\Throwable $e) { $pending = null; }

            return [$closing, [
                'held' => [
                    'id'         => (int) $vid,
                    'label'      => $closing['label'],
                    'vtype'      => $closing['vtype'],
                    'is_company' => true,
                    'since'      => $heldSince,
                ],
                'own' => [
                    'id'    => (int) $own['id'],
                    'label' => \App\Services\Riders\MeterPairHelper::labelOf($ownVeh),
                    'vtype' => ((string) ($ownVeh->vtype ?? '')) === 'van' ? 'van' : 'bike',
                ],
                'pending_return' => $pending,
            ]];
        } catch (\Throwable $e) {
            \Log::warning('checkoutMachineContext failed (non-fatal)', [
                'user_id' => $userId, 'error' => $e->getMessage(),
            ]);
            return [null, null];
        }
    }

    /**
     * ⭐⭐ PHASE D — IS THE METER COMPULSORY FOR THIS RIDER TODAY?
     *
     * THE SINGLE SOURCE for all three surfaces that ask: the `meter_required` flag
     * in the today-attendance payload (which drives the app's whole "Meter & Check
     * In / Out" chain), the check-in gate and the checkout gate.
     *
     * ⚠⚠ THEY MUST NEVER DISAGREE. If the flag said "optional" while the gate said
     *    "required", the app would not offer the meter screen and the server would
     *    refuse the check-in — a rider stranded at the office with no button that
     *    helps him. That is why this is one method and not three copies.
     *
     * Order:
     *   1. the bike registry (owner ruling R2: no machine = no meter). Silent
     *      unless VEHICLE_RULES is on AND he is a rider AND the tables exist.
     *   2. the old Rider Management checkbox — unchanged for everyone the
     *      registry has no opinion about.
     *
     * Returns 1 / 0, or null when the legacy column isn't deployed (the app then
     * keeps its pre-Jul-28 optional behaviour).
     *
     * FAIL-SAFE: any error falls through to the checkbox, never to "required".
     */
    private function meterRequiredForUser(int $userId, ?string $date = null): ?int
    {
        try {
            $byRegistry = (new \App\Services\Riders\VehicleResolver())
                ->meterRequiredNow($userId, $date);
            if ($byRegistry !== null) {
                return $byRegistry ? 1 : 0;
            }
        } catch (\Throwable $e) {
            \Log::warning('meterRequiredForUser: registry check failed, using the profile flag', [
                'user_id' => $userId, 'error' => $e->getMessage(),
            ]);
        }

        try {
            if (!\Illuminate\Support\Facades\Schema::hasColumn('t_ops_rider_profile', 'meter_required')) {
                return null;                 // column not deployed → legacy optional
            }
            $mr = \DB::table('t_ops_rider_profile')->where('user_id', $userId)->value('meter_required');
            return $mr === null ? 0 : (int) $mr;   // no profile row → not required
        } catch (\Throwable $e) {
            return null;
        }
    }

    /**
     * Is the manager's "riders must be at their location to check in" rule ON?
     * Stored as t_fin_config ATTENDANCE_REQUIRE_LOCATION ('1' = on). Defaults to
     * OFF when the row is absent or unreadable — a config hiccup must NEVER block
     * check-in.
     */
    private function attendanceRequiresLocation(): bool
    {
        try {
            $v = \DB::table('t_fin_config')
                ->where('config_key', 'ATTENDANCE_REQUIRE_LOCATION')
                ->value('config_value');
            return $v !== null && (string) $v === '1';
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Read a t_fin_config value with a default (never throws). */
    /**
     * The most recent odometer reading we hold for this rider's bike — the
     * highest of his attendance meters and any earlier fill reading.
     *
     * Used to sanity-check a new meter_at_fill. Deliberately tolerant: readings
     * below 1000 are dropped-digit typos and must not become the baseline, or
     * one bad entry would reject every honest reading after it.
     * Returns null when we have nothing to compare against.
     */
    private function lastKnownOdometer(int $userId): ?int
    {
        try {
            $att = DB::table('t_ops_attendance')
                ->where('user_id', $userId)
                ->where('attendance_date', '>=', \Carbon\Carbon::today()->subDays(45)->format('Y-m-d'))
                ->selectRaw('MAX(GREATEST(COALESCE(meter_end,0), COALESCE(meter_home,0), COALESCE(meter_start,0))) AS m')
                ->value('m');

            $fill = DB::table('t_req_master')
                ->where('requester_user_id', $userId)
                ->whereNotNull('meter_at_fill')
                ->where('created_at', '>=', \Carbon\Carbon::today()->subDays(45))
                ->max('meter_at_fill');

            $best = max((int) $att, (int) $fill);
            return $best > 1000 ? $best : null;
        } catch (\Throwable $e) {
            return null;   // never block a request because the check itself failed
        }
    }

    /**
     * ⭐ Sep-30 — the rider's "Company bike this month" block, from MachineAttribution: shift km
     * and off-duty km on COMPANY machines only, plus his night list. Returns:
     *   array — the block (keys the installed APK already reads + `nights`)
     *   null  — he had no company machine this month: no block
     *   false — the engine cannot speak for him: caller keeps the old rider-keyed sum
     */
    private function engineBikeUsage(int $userId, string $month)
    {
        try {
            $cfg = DB::table('t_fin_config')->where('config_key', 'MACHINE_ATTRIBUTION')->value('config_value');
            if ($cfg !== null && $cfg !== '' && strtoupper((string) $cfg) !== 'Y') return false;

            $cm = (new \App\Services\Riders\MachineAttribution())->companyMonth($userId, $month);
            if ($cm === null) return false;
            if (!$cm['had_company']) return null;

            $work = (int) $cm['work_km'];
            $off  = (int) $cm['offduty_km'];
            return [
                'days'        => (int) $cm['days'],
                'work_km'     => $work,
                'offduty_km'  => $off,
                'total_km'    => $work + $off,
                'offduty_pct' => ($work + $off) > 0 ? (int) round($off * 100 / ($work + $off)) : 0,
                // additive — one line per night: date, plate, from → to, km, where read
                'nights'      => $cm['nights'],
                'source'      => 'engine',
            ];
        } catch (\Throwable $e) {
            Log::warning('engineBikeUsage failed', ['user' => $userId, 'error' => $e->getMessage()]);
            return false;
        }
    }

    /**
     * A company-bike rider's own month: shift km vs off-duty km.
     * ⚠ Sep-30: now only the FALLBACK for a rider the engine cannot speak for.
     *
     * Uses the SAME plausibility bounds as the Fleet tab (readings under 1000 are
     * dropped-digit typos; a day over 500 km or an overnight gap over 500 km is a
     * meter change, not a ride) so the rider and management can never be looking
     * at two different numbers.
     */
    private function monthBikeUsage(int $userId, string $startDate, string $endDate): array
    {
        $rows = DB::table('t_ops_attendance')
            ->select('attendance_date', 'meter_start', 'meter_end')
            ->where('user_id', $userId)
            ->whereBetween('attendance_date', [$startDate, $endDate])
            ->orderBy('attendance_date')
            ->get();

        $work = 0; $offDuty = 0; $days = 0; $prevEnd = null;
        foreach ($rows as $r) {
            $s = $r->meter_start !== null ? (int) $r->meter_start : null;
            $e = $r->meter_end !== null ? (int) $r->meter_end : null;
            $sane = $s !== null && $e !== null && $s > 1000 && $e >= $s && ($e - $s) <= 500;
            if (!$sane) continue;

            $days++;
            $work += $e - $s;
            if ($prevEnd !== null && $s >= $prevEnd && ($s - $prevEnd) <= 500) {
                $offDuty += $s - $prevEnd;
            }
            $prevEnd = $e;
        }

        return [
            'days'        => $days,
            'work_km'     => $work,
            'offduty_km'  => $offDuty,
            'total_km'    => $work + $offDuty,
            'offduty_pct' => ($work + $offDuty) > 0 ? (int) round($offDuty * 100 / ($work + $offDuty)) : 0,
        ];
    }

    /**
     * The odometer range a reading dated $date must sit inside.
     *
     *   floor — the highest reading recorded on any day BEFORE $date. An odometer
     *           never runs backwards, so a reading below this is wrong.
     *   ceil  — the lowest reading recorded on any day AFTER $date. A reading
     *           above this would mean the bike un-drove those kilometres.
     *
     * Same-day readings are deliberately excluded from BOTH bounds: a service or
     * fill at 11am sits below that evening's closing meter, and bracketing by the
     * neighbouring days is what lets an honest backdated entry through while still
     * catching a dropped or extra digit. Either bound may be null (nothing on that
     * side yet), and any failure returns nulls — a broken check must never block a
     * rider from filing.
     */
    /**
     * SQL predicate for an attendance row whose meter readings can be trusted.
     * Mirrors FleetFuelService's isSaneDay()/MIN_METER bounds — keep them in step.
     */
    private function saneMeterRowSql(): string
    {
        return 'meter_start > 1000
                AND (meter_end IS NULL OR (meter_end >= meter_start AND meter_end - meter_start <= 500))
                AND (meter_home IS NULL OR (meter_home >= meter_start AND meter_home - meter_start <= 700))';
    }

    private function odometerWindowFor(int $userId, string $date): array
    {
        try {
            // ⚠ Only PLAUSIBLE rows. The data contains typo'd meters (one row has
            // 26,261 → 56,403 in a single day). Taking a raw MAX lets one such row
            // become the floor forever, and the rider can then never file a correct
            // reading again. Same bounds the Bikes screen uses: opening above 1,000,
            // a day's run 0–500 km, the ride home no more than 700.
            $attBefore = DB::table('t_ops_attendance')
                ->where('user_id', $userId)
                ->where('attendance_date', '<', $date)
                ->whereRaw($this->saneMeterRowSql())
                ->selectRaw('MAX(GREATEST(COALESCE(meter_end,0), COALESCE(meter_home,0), COALESCE(meter_start,0))) AS m')
                ->value('m');

            $fillBefore = DB::table('t_req_master')
                ->where('requester_user_id', $userId)
                ->whereNotNull('meter_at_fill')
                ->whereNotIn('status', ['cancelled', 'rejected'])
                ->whereRaw('COALESCE(expense_date, DATE(created_at)) < ?', [$date])
                ->max('meter_at_fill');

            $floor = max((int) $attBefore, (int) $fillBefore);
            $floor = $floor > 1000 ? $floor : null;

            // Earliest reading known on a later day (a day's opening meter first).
            // Sub-1000 values are dropped-digit junk (there are such rows in the
            // data). They are excluded INSIDE the query — taking MIN() first would
            // let one junk row become the ceiling and silently disable the check.
            $attAfter = DB::table('t_ops_attendance')
                ->where('user_id', $userId)
                ->where('attendance_date', '>', $date)
                ->whereRaw($this->saneMeterRowSql())
                ->selectRaw('MIN(COALESCE(NULLIF(meter_start,0), NULLIF(meter_end,0), NULLIF(meter_home,0))) AS m')
                ->value('m');

            $fillAfter = DB::table('t_req_master')
                ->where('requester_user_id', $userId)
                ->whereNotNull('meter_at_fill')
                ->where('meter_at_fill', '>', 1000)
                ->whereNotIn('status', ['cancelled', 'rejected'])
                ->whereRaw('COALESCE(expense_date, DATE(created_at)) > ?', [$date])
                ->min('meter_at_fill');

            $candidates = array_filter([
                (int) $attAfter > 1000 ? (int) $attAfter : null,
                (int) $fillAfter > 1000 ? (int) $fillAfter : null,
            ], fn ($v) => $v !== null);
            $ceil = $candidates ? min($candidates) : null;

            return ['floor' => $floor, 'ceil' => $ceil];
        } catch (\Throwable $e) {
            return ['floor' => null, 'ceil' => null];
        }
    }

    /**
     * Is this rider on a company-owned bike (company pays the actual fuel)?
     *
     * ⭐ PHASE C: delegates to FuelClaimRules, which asks the vehicle REGISTRY for
     *    the given date and falls back to the profile checkbox when no vehicle
     *    answers (or while VEHICLE_RULES is off). This used to be a second,
     *    independent read of the same column — exactly the kind of copy that
     *    lets two screens disagree about one rider.
     */
    private function ridesCompanyBike(int $userId, ?string $date = null): bool
    {
        try {
            return (new \App\Services\Riders\FuelClaimRules())->ridesCompanyBike($userId, $date);
        } catch (\Throwable $e) {
            return false;
        }
    }

    /** Set by processCheckinLocation when the only fix it was given lay outside Pakistan. */
    private ?array $lastCheckinPhantom = null;

    /**
     * ⭐ Strip a phantom fix out of a request in place. Used at the doors that read
     *   `latitude`/`longitude` in several sub-steps (check-out: the checkout rule, the
     *   home-journey arming, the stored checkout position) — one strip at the top beats three
     *   gates that can drift. Returns true when something was stripped.
     */
    private function dropPhantomFromRequest(Request $request, int $userId, string $where): bool
    {
        $lat = $request->input('latitude'); $lng = $request->input('longitude');
        if ($lat === null || $lng === null || LocationService::isPlausibleFix($lat, $lng)) return false;
        \Log::warning('📍 ' . strtoupper($where) . ': fix outside Pakistan (phantom) — dropped', ['user_id' => $userId, 'lat' => $lat, 'lng' => $lng]);
        $this->recordLocationFailureRow($userId, 'phantom_fix', substr($where, 0, 30), sprintf('phantom %s,%s acc=%s', $lat, $lng, $request->input('accuracy', '?')), $lat, $lng);
        $request->merge(['latitude' => null, 'longitude' => null, 'accuracy' => null]);
        return true;
    }

    /**
     * One failure row, best effort — diagnosis only, never a reason to fail the caller.
     * The same table the app's own failure endpoint writes, so every "phone said Beijing"
     * episode is readable from one place afterwards.
     */
    private function recordLocationFailureRow(int $userId, string $reason, string $source, string $detail, $lat, $lng): void
    {
        try {
            \DB::table('t_ops_location_failures')->insert([
                'user_id' => $userId, 'failure_reason' => substr($reason, 0, 50),
                'failure_source' => substr($source, 0, 30), 'error_message' => substr($detail, 0, 255),
                'device_online' => 1, 'last_known_lat' => is_numeric($lat) ? $lat : null,
                'last_known_lng' => is_numeric($lng) ? $lng : null, 'app_state' => 'active',
                'captured_at' => now(),
            ]);
        } catch (\Throwable $e) {
            \Log::debug('location failure row not written', ['error' => $e->getMessage()]);
        }
    }

    private function attnConfig(string $key, $default)
    {
        try {
            $v = \DB::table('t_fin_config')->where('config_key', $key)->value('config_value');
            return ($v === null || $v === '') ? $default : $v;
        } catch (\Throwable $e) {
            return $default;
        }
    }

    /** Is the mandatory-checkout rule turned on? (Phase H) */
    private function checkoutRuleEnabled(): bool
    {
        return (string) $this->attnConfig('CHECKOUT_RULE_ENABLED', '0') === '1';
    }

    /**
     * Phase H gate: when the checkout rule is ON, a rider may only check out at the office,
     * or at his MOST RECENT delivery within the configured window + radius. Returns
     * ['ok'=>true] to allow, else ['ok'=>false,'reason'=>..,'message'=>..]. Server-authoritative.
     *
     * $accuracy = the fix's own accuracy in metres (NULL from older APKs). It is RECORDED on
     * every blocked attempt so a manager can see whether the rider was judged on a sharp fix
     * or a vague one before deciding to unlock. It only moves the pass/fail line if
     * CHECKOUT_ACCURACY_SLACK_M is raised above its default of 0 — this gate guards hours and
     * anti-abuse, so its behaviour is unchanged until someone deliberately turns that on.
     */
    private function checkoutRuleResult(int $userId, $lat, $lng, $accuracy = null, ?string $shiftDate = null): array
    {
        if (!$this->checkoutRuleEnabled()) {
            return ['ok' => true];
        }
        // No usable GPS → block with a distinct message (H-Q2). Nothing to measure — the
        // detail just records that he tried with location off.
        if (is_null($lat) || is_null($lng) || !LocationService::isValidCoordinates($lat, $lng)) {
            return ['ok' => false, 'reason' => 'no_gps',
                'message' => 'Your location is off — turn it on to check out, or call your manager to unlock checkout.',
                'detail' => [
                    'subreason' => 'no_gps',
                    'attempt_lat' => null, 'attempt_lng' => null,
                    'ref_type' => null, 'ref_lat' => null, 'ref_lng' => null, 'ref_label' => null,
                    'distance_m' => null, 'limit_m' => null, 'age_min' => null,
                    'accuracy_m' => null, 'is_coarse' => false,
                ]];
        }
        $lat = (float) $lat; $lng = (float) $lng;

        $windowMins = (int) $this->attnConfig('CHECKOUT_DELIVERY_WINDOW_MINS', 15);
        $radiusM    = (float) $this->attnConfig('CHECKOUT_DELIVERY_RADIUS_M', 150);

        // Fix quality. $accM is recorded on the attempt either way; $slack only widens the
        // radius when CHECKOUT_ACCURACY_SLACK_M is deliberately raised (default 0 = no change).
        $accM = ($accuracy !== null && is_numeric($accuracy)) ? (float) $accuracy : null;
        $coarseM = (float) $this->attnConfig('COARSE_FIX_M', 150);
        $isCoarseFix = $accM !== null && $accM > $coarseM;
        $slack = $accM !== null ? min($accM, (float) $this->attnConfig('CHECKOUT_ACCURACY_SLACK_M', 0)) : 0.0;

        // 1) Office (primary company location) within its radius.
        $office = \DB::table('t_ops_company_locations')->where('is_primary', 1)->where('is_active', 1)
            ->select('latitude', 'longitude', 'radius_meters')->first();
        $dOffice = null; $officeRadius = null;
        if ($office && $office->latitude !== null && $office->longitude !== null) {
            $officeRadius = (float) ($office->radius_meters ?: 300);
            $dOffice = $this->haversineDistance($lat, $lng, (float) $office->latitude, (float) $office->longitude);
            if (($dOffice - $slack) <= $officeRadius) {
                return ['ok' => true, 'basis' => 'office'];
            }
        }

        // 2) His MOST RECENT delivered order THIS SHIFT, within window + radius (H-Q3).
        //    Anchored to the shift's own date (normally today; yesterday when the
        //    checkout rolled past midnight) so a 23:58 delivery still counts as the
        //    reference for a 00:05 OUT instead of vanishing at midnight and leaving
        //    only the office. Same-day shifts: >= today 00:00 == the old whereDate.
        $sinceTs = ($shiftDate ?: now()->toDateString()) . ' 00:00:00';
        // The drop's own recorded accuracy travels with it (column exists after the GPS-accuracy
        // hardening SQL; NULL before it and on rows stamped by older APKs).
        $dropAccCol = \Illuminate\Support\Facades\Schema::hasColumn('t_crm_order_status_history', 'delivery_accuracy_m')
            ? 'h.delivery_accuracy_m'
            : \DB::raw('NULL as delivery_accuracy_m');
        $last = \DB::table('t_crm_order_status_history as h')
            ->join('t_crm_prod_order as o', 'o.id', '=', 'h.order_id')
            ->where('h.status_code', 'delivered')
            ->where('o.assigned_rider_user_id', $userId)
            ->whereNotNull('h.delivery_latitude')->whereNotNull('h.delivery_longitude')
            ->where('h.changed_at', '>=', $sinceTs)
            ->orderByDesc('h.changed_at')
            ->select('h.delivery_latitude', 'h.delivery_longitude', 'h.changed_at', 'o.order_number', $dropAccCol)
            ->first();
        $dDrop = null; $ageMin = null; $dropSlack = 0.0; $dropAcc = null;
        if ($last) {
            $ageMin = \Carbon\Carbon::parse($last->changed_at)->diffInMinutes(now(), false);
            $dDrop = $this->haversineDistance($lat, $lng, (float) $last->delivery_latitude, (float) $last->delivery_longitude);
            // ⭐ Sep-5 2026 — the REFERENCE point's own error bar. The drop this checkout is
            //   measured against was itself a GPS stamp; when THAT stamp was vague (Kanan's NF-19423
            //   on Aug-31 was recorded 700 m off by a canned cell fix), an honest rider standing at
            //   the customer's door reads as "too far" and has to phone a manager. Let the drop's
            //   recorded accuracy widen the circle — capped at COARSE_FIX_M, so the 150 m limit can
            //   never grow past 300 m, and only when the stamp itself says it was that vague.
            //   This is about the reference, not the rider: his CURRENT fix still gets no slack
            //   (CHECKOUT_ACCURACY_SLACK_M stays 0 — the anti-abuse choice is untouched), the
            //   15-min window still applies, and the office test is unchanged. NULL accuracy
            //   (older APKs / pre-hardening rows) ⇒ 0 ⇒ exactly the previous rule.
            $dropAcc = ($last->delivery_accuracy_m !== null && is_numeric($last->delivery_accuracy_m))
                ? (float) $last->delivery_accuracy_m : null;
            $dropSlack = $dropAcc !== null ? min($dropAcc, $coarseM) : 0.0;
            if ($ageMin >= 0 && $ageMin <= $windowMins && ($dDrop - $slack - $dropSlack) <= $radiusM) {
                return ['ok' => true, 'basis' => 'delivery'];
            }
        }

        // ---- Blocked. Build the diagnostic detail the manager sees (live alert + bypass modal).
        // Reference against the delivery he was *supposed* to be near; fall back to the office
        // when he had no delivery today. distance/limit + which limit broke (subreason).
        if ($last) {
            // Distance dominates the message ("he isn't there any more"); else it's the time window.
            // limit_m is the EFFECTIVE limit (radius + the drop's own slack): the app's retry card
            // turns the OUT button green when live distance <= limit_m, so it must match the gate.
            $effLimit = $radiusM + $dropSlack;
            $sub = ($dDrop !== null && $dDrop > $effLimit) ? 'too_far'
                 : (($ageMin !== null && $ageMin > $windowMins) ? 'too_late' : 'wrong_place');
            $detail = [
                'subreason'   => $sub,
                'attempt_lat' => $lat, 'attempt_lng' => $lng,
                'ref_type'    => 'delivery',
                'ref_lat'     => (float) $last->delivery_latitude,
                'ref_lng'     => (float) $last->delivery_longitude,
                'ref_label'   => ($last->order_number !== null && $last->order_number !== '')
                                    ? (string) $last->order_number : null,
                'distance_m'  => $dDrop !== null ? (int) round($dDrop) : null,
                'limit_m'     => (int) round($effLimit),
                'age_min'     => $ageMin !== null ? (int) $ageMin : null,
                'accuracy_m'  => $accM,
                'is_coarse'   => $isCoarseFix,
                // The reference drop's own quality — so the manager's bypass modal can tell
                // "he moved" from "the delivery was stamped vaguely" before unlocking.
                'ref_accuracy_m' => $dropAcc,
                'ref_coarse'     => $dropAcc !== null && $dropAcc > $coarseM,
            ];
        } else {
            $detail = [
                'subreason'   => 'wrong_place',
                'attempt_lat' => $lat, 'attempt_lng' => $lng,
                'ref_type'    => 'office',
                'ref_lat'     => ($office && $office->latitude !== null) ? (float) $office->latitude : null,
                'ref_lng'     => ($office && $office->longitude !== null) ? (float) $office->longitude : null,
                'ref_label'   => 'Office',
                'distance_m'  => $dOffice !== null ? (int) round($dOffice) : null,
                'limit_m'     => $officeRadius !== null ? (int) $officeRadius : null,
                'age_min'     => null,
                'accuracy_m'  => $accM,
                'is_coarse'   => $isCoarseFix,
            ];
        }

        return ['ok' => false, 'reason' => 'wrong_place',
            'message' => 'Check out at the office, or within ' . $windowMins . ' min at your last delivery — or call your manager to unlock checkout.',
            'detail' => $detail];
    }

    /**
     * Persist the LATEST blocked checkout attempt onto the day's attendance row (latest-wins,
     * plus a counter of how many times he tried today). Read by the shared attendance payload
     * → the live "stuck at checkout" alert + the bypass modal context. Silently no-ops if the
     * capture columns aren't applied yet (SQL not run) so it can never fail a checkout.
     * $detail is the 'detail' array from checkoutRuleResult() (may be null defensively).
     */
    private function recordCheckoutAttempt(int $attendanceId, ?array $detail, ?int $userId = null): void
    {
        if (!\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'checkout_attempt_at')) {
            return; // capture SQL not applied — skip quietly
        }
        $d = $detail ?: [];
        $update = [
            'checkout_attempt_at'         => now(),
            'checkout_attempt_lat'        => $d['attempt_lat']  ?? null,
            'checkout_attempt_lng'        => $d['attempt_lng']  ?? null,
            'checkout_attempt_reason'     => $d['subreason']    ?? 'wrong_place',
            'checkout_attempt_distance_m' => $d['distance_m']   ?? null,
            'checkout_attempt_limit_m'    => $d['limit_m']      ?? null,
            'checkout_attempt_age_min'    => $d['age_min']      ?? null,
            'checkout_attempt_drop_lat'   => $d['ref_lat']      ?? null,
            'checkout_attempt_drop_lng'   => $d['ref_lng']      ?? null,
            'checkout_attempt_drop_label' => $d['ref_label']    ?? null,
            'checkout_attempt_count'      => \DB::raw('COALESCE(checkout_attempt_count, 0) + 1'),
            'updated_at'                  => now(),
        ];
        if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'checkout_attempt_accuracy_m')) {
            $update['checkout_attempt_accuracy_m'] = $d['accuracy_m'] ?? null;
        }
        \DB::table('t_ops_attendance')->where('id', $attendanceId)->update($update);

        // ⭐ Append EVERY attempt. The row above is latest-wins, which inverted how Asim's
        // Jul-26 looked: his first press was 248 m from the drop, his last (an hour later)
        // was 7.5 km — and only the last survived. The log keeps the whole sequence, so
        // "he tried while he was still there, then gave up and rode off" stays readable.
        // Separate try: a log failure must never cost us the latest-attempt capture above.
        try {
            if (\Illuminate\Support\Facades\Schema::hasTable('t_ops_checkout_attempt_log')) {
                \DB::table('t_ops_checkout_attempt_log')->insert([
                    'attendance_id' => $attendanceId,
                    'user_id'       => $userId ?? 0,
                    'attempted_at'  => now(),
                    'latitude'      => $d['attempt_lat'] ?? null,
                    'longitude'     => $d['attempt_lng'] ?? null,
                    'accuracy_m'    => $d['accuracy_m']  ?? null,
                    'reason'        => $d['subreason']   ?? 'wrong_place',
                    'distance_m'    => $d['distance_m']  ?? null,
                    'limit_m'       => $d['limit_m']     ?? null,
                    'age_min'       => $d['age_min']     ?? null,
                    'ref_lat'       => $d['ref_lat']     ?? null,
                    'ref_lng'       => $d['ref_lng']     ?? null,
                    'ref_label'     => $d['ref_label']   ?? null,
                    'created_at'    => now(),
                ]);
            }
        } catch (\Throwable $logErr) {
            \Log::warning('checkout attempt log insert failed (non-fatal)', [
                'attendance_id' => $attendanceId, 'error' => $logErr->getMessage(),
            ]);
        }
    }

    public function checkIn(Request $request)
    {
        try {
            $user = Auth::user();
            $today = now()->format('Y-m-d');
            $currentTime = now()->format('H:i:s');

            // Validate optional meter picture and location data
            $request->validate([
                'meter_picture' => 'nullable|image|max:5120', // 5MB max
                'latitude' => 'nullable|numeric|between:-90,90',
                'longitude' => 'nullable|numeric|between:-180,180',
                'accuracy' => 'nullable|numeric',
            ]);

            // Check if already checked in today
            $existing = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)
                ->whereDate('attendance_date', $today)
                ->first();

            if ($existing && $existing->login_time) {
                return response()->json(['success' => false, 'message' => 'Already checked in today'], 400);
            }

            // ⭐ Past-midnight guard (owner-approved Jul-28): before 06:00, a rider whose
            //    YESTERDAY shift is still open must check OUT of it, not open a fresh day —
            //    an accidental IN here would orphan the open shift AND create a today-row
            //    that blocks the midnight checkout fallback. Same 06:00 bound as checkOut
            //    and getTodayAttendance; a genuine new day always starts after 06:00.
            //    The manager's web "Mark Attendance" is a separate path and unaffected.
            if ((new \App\Services\Riders\AttendanceDay())->openPastMidnightRow($user->id)) {
                return response()->json([
                    'success' => false,
                    'message' => "You're still checked in from yesterday — check out first, or ask your manager to close that shift.",
                ], 400);
            }

            // Process location data for check-in
            $locationData = $this->processCheckinLocation($request, $user->id);

            // Mandatory-location gate (manager-toggled, default OFF): a rider may check
            // in ONLY when GPS confirms they're within their shift location's radius.
            // Blocks a remote check-in AND a check-in with no usable location (can't
            // confirm → deny). The manager's WEB "Mark Attendance" is exempt (separate
            // path, no GPS) and is the intended override for genuine GPS failures.
            if ($this->attendanceRequiresLocation()) {
                if (!$locationData) {
                    // ⭐ 16-Sep: a phone claiming to be abroad is told WHAT is wrong, in the rider's
                    //   words, rather than "turn on GPS" — his GPS is on and lying.
                    if ($this->lastCheckinPhantom) {
                        return response()->json([
                            'success' => false,
                            'require_location' => true,
                            'code' => 'phantom_fix',
                            'message' => LocationService::phantomFixMessage(),
                        ], 422);
                    }
                    return response()->json([
                        'success' => false,
                        'require_location' => true,
                        'message' => 'Location is required to check in. Turn on GPS/location and try again from your work location.',
                    ], 422);
                }
                if (!empty($locationData['is_remote'])) {
                    $where = $locationData['base_name'] ?? 'your assigned location';
                    $dist = isset($locationData['distance'])
                        ? LocationService::formatDistance((int) $locationData['distance'])
                        : null;
                    // ⭐ Sep-5 2026 (Waseem/Kanan at Orchard Lacarne): a COARSE fix is not a
                    //   verdict. The phone handed over a canned ±700 m cell centroid 1.1 km away and
                    //   this branch told the rider he was "1.1km from Orchard Lacarne" — an accusation
                    //   the fix could not support. Same block, honest words: the GPS was vague, go
                    //   get a sharp one. `fix_coarse` lets the app show its own retry state; old
                    //   APKs render `message`, so they get the honest text for free.
                    if (!empty($locationData['is_coarse'])) {
                        $acc = isset($locationData['accuracy_m']) ? (int) round($locationData['accuracy_m']) : null;
                        return response()->json([
                            'success' => false,
                            'require_location' => true,
                            'fix_coarse' => true,
                            'accuracy_m' => $acc,
                            'message' => 'GPS signal kamzor hai' . ($acc ? " (±{$acc} m)" : '')
                                . " — is se pata nahi chal sakta aap {$where} par hain ya nahi. "
                                . 'Khule mein aayein, WiFi band karein aur dobara koshish karein.',
                        ], 422);
                    }
                    return response()->json([
                        'success' => false,
                        'require_location' => true,
                        'message' => ($dist ? "You're $dist from $where. " : '')
                            . "You can only check in at $where.",
                    ], 422);
                }
            }

            // ⭐ Meter-required gate (owner ruling Jul-28: "required cannot skip meter").
            //    A rider tagged meter_required=1 cannot check in without a START reading on the
            //    row — the app's "Meter & Check In" chain records it first, so this is the
            //    server backstop for anything that isn't the chain. Store staff / managers have
            //    no rider profile (or the tag off, e.g. Shabib's exemption) and are untouched.
            //    The manager check-in unlock is the valve, same as the ETA lock below.
            //    FAIL-OPEN on errors — a DB hiccup must never strand a rider at the office.
            try {
                // ⭐ PHASE D: asked through meterRequiredForUser() so the gate and the
                //   app's meter_required flag are always the SAME answer — a rider is
                //   never refused for a reading his app didn't offer to take.
                $mrFlag = $this->meterRequiredForUser($user->id, $today);
                {
                    if ((int) $mrFlag === 1
                        && (!$existing || $existing->meter_start === null || $existing->meter_start === '')) {
                        $mrUnlock = false;
                        if ($existing && \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'checkin_unlock_until')) {
                            $mrUnlock = (new \App\Services\Riders\WorkJourneyService())->checkinUnlockActive($existing);
                        }
                        if (!$mrUnlock) {
                            return response()->json([
                                'success' => false,
                                'meter_required' => true,
                                'message' => 'Record your start meter first — use "Meter & Check In".',
                            ], 422);
                        }
                    }
                }
            } catch (\Throwable $mrErr) {
                \Log::warning('checkin meter gate failed open (non-fatal)', ['user_id' => $user->id, 'error' => $mrErr->getMessage()]);
            }

            // ⭐ U5 Phase-2 check-in LOCK (config CHECKIN_ETA_LOCK, ships OFF): a company-bike
            // rider past his ride-to-work deadline — or who skipped the home start entirely —
            // must get a manager unlock (checkin_unlock_*) before he can check in. While the
            // config is 0 this whole block is inert. FAIL-OPEN: any error here must never
            // stop a check-in.
            try {
                if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'checkin_unlock_until')) {
                    $wjLock = new \App\Services\Riders\WorkJourneyService();
                    if ($wjLock->lockEnabled() && $wjLock->riderHomePin($user->id)) {
                        $hasHomeStart = $existing && (string) ($existing->meter_start_source ?? '') === 'home';
                        $verdict = $wjLock->checkinLockVerdict($existing ?: (object) [], $hasHomeStart);
                        if ($verdict['locked']) {
                            return response()->json([
                                'success' => false,
                                'checkin_locked' => true,
                                'reason' => $verdict['why'], // late | no_home_start
                                'message' => $verdict['why'] === 'late'
                                    ? 'You arrived after your ride-to-work deadline — call your manager to unlock check-in.'
                                    : 'No start meter from home today — call your manager to unlock check-in.',
                            ], 423);
                        }
                    }
                }
            } catch (\Throwable $lockErr) {
                \Log::warning('checkin lock gate failed open (non-fatal)', ['user_id' => $user->id, 'error' => $lockErr->getMessage()]);
            }

            // Store meter picture if provided
            $picturePath = null;
            if ($request->hasFile('meter_picture')) {
                $picturePath = $this->storeMeterPicture($request->file('meter_picture'), $user->id, 'checkin');
            }

            if ($existing) {
                // Update existing record
                $updateData = [
                    'login_time' => $currentTime,
                    'updated_at' => now(),
                ];
                if ($picturePath) {
                    $updateData['picture_start'] = $picturePath;
                }
                // Add location data
                if ($locationData) {
                    $updateData = array_merge($updateData, $locationData['db_fields']);
                }
                
                \DB::table('t_ops_attendance')
                    ->where('id', $existing->id)
                    ->update($updateData);
            } else {
                // Create new record
                $insertData = [
                    'user_id' => $user->id,
                    'attendance_date' => $today,
                    'login_time' => $currentTime,
                    'created_at' => now(),
                    'updated_at' => now(),
                ];
                if ($picturePath) {
                    $insertData['picture_start'] = $picturePath;
                }
                
                // Add location data
                if ($locationData) {
                    $insertData = array_merge($insertData, $locationData['db_fields']);
                }
                
                \DB::table('t_ops_attendance')->insert($insertData);
            }

            // ⭐ Freeze today's expected shift + late minutes onto the row so a later
            // shift change can never rewrite this day. NON-FATAL: must never block
            // or fail check-in.
            try {
                (new \App\Services\ShiftResolutionService())->stampAttendanceSnapshot($user->id, $today);
            } catch (\Exception $snapErr) {
                \Log::warning('Attendance shift snapshot failed on check-in (non-fatal)', [
                    'user_id' => $user->id,
                    'date' => $today,
                    'error' => $snapErr->getMessage(),
                ]);
            }

            // 💡 A late check-in is something a manager may want to waive, so tell them.
            // ⚠ AFTER the snapshot above (that is what freezes the late minutes) and off the
            // response via terminating(), so the rider never waits for it. Debounced to one
            // push an hour inside the service; there is no scheduler on prod, which is why
            // the rider's own action is what raises it.
            app()->terminating(function () {
                try { app(\App\Services\HR\DayReviewService::class)->pushDueOnce(); }
                catch (\Throwable $e) { /* best effort */ }
            });

            // Prepare response message with location info
            $message = 'Checked in successfully at ' . date('h:i A', strtotime($currentTime));
            $responseData = [
                'success' => true,
                'message' => $message,
                'login_time' => $currentTime,
                'picture_url' => $picturePath ? $this->getMeterPictureUrl($picturePath) : null,
                'location_captured' => $locationData ? true : false,
            ];
            // ⭐ 16-Sep: checked in WITHOUT coordinates because the phone claimed to be abroad
            //   (mandatory-location OFF). Say so — the current APK already renders gps_warning.
            if (!$locationData && $this->lastCheckinPhantom) {
                $responseData['gps_warning'] = LocationService::phantomFixMessage();
                $responseData['code'] = 'phantom_fix';
            }

            if ($locationData) {
                $responseData['is_remote'] = $locationData['is_remote'];
                $responseData['distance'] = $locationData['distance'];

                if ($locationData['is_remote']) {
                    $distanceFormatted = LocationService::formatDistance($locationData['distance']);
                    $responseData['message'] = $message . " ⚠️ Remote: {$distanceFormatted} from office";
                }
            }

            // ⭐ U5 — ride-to-work verdict for the app (additive; old APKs ignore). Judged
            // against the deadline armed at the home start; informational in Phase 1.
            try {
                if ($existing && !empty($existing->work_expected_by)) {
                    $expTs = strtotime((string) $existing->work_expected_by);
                    $late = max(0, (int) round((time() - $expTs) / 60));
                    $responseData['work_verdict'] = [
                        'on_time' => $late === 0,
                        'minutes_late' => $late,
                        'expected_by' => substr((string) $existing->work_expected_by, 11, 5),
                    ];
                    if ($late > 0) {
                        $responseData['message'] .= " ⏱ {$late} min after your ride-in deadline (" . substr((string) $existing->work_expected_by, 11, 5) . ')';
                    }
                }
            } catch (\Throwable $e) { /* verdict is optional */ }

            return response()->json($responseData);
        } catch (\Illuminate\Database\QueryException $qe) {
            // [3B] With the UNIQUE key on (user_id, attendance_date), a racing SECOND check-in
            // insert fails here (MySQL errno 1062) instead of creating a duplicate row — the first
            // insert already won, so treat it as "already checked in". The mobile refetches and
            // shows the real state. Any other DB error falls through to a generic failure.
            if ((int) ($qe->errorInfo[1] ?? 0) === 1062) {
                return response()->json(['success' => false, 'message' => 'Already checked in today'], 400);
            }
            \Log::error('Failed to check in (db)', ['error' => $qe->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to check in'], 500);
        } catch (\Exception $e) {
            \Log::error('Failed to check in', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);

            return response()->json(['success' => false, 'message' => 'Failed to check in: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Process check-in location data and calculate distance from base
     * 
     * @param Request $request
     * @param int $userId
     * @return array|null Location data or null if not provided
     */
    private function processCheckinLocation(Request $request, int $userId)
    {
        $latitude = $request->input('latitude');
        $longitude = $request->input('longitude');
        $accuracy = $request->input('accuracy');
        $source = $request->input('source'); // fresh_gps, recent_gps, network_cached
        $method = $request->input('method'); // 1, 2, or 3

        if (is_null($latitude) || is_null($longitude)) {
            \Log::warning('📍 ATTENDANCE CHECK-IN: No location provided', [
                'user_id' => $userId,
                'date' => now()->toDateString()
            ]);
            return null;
        }

        // Validate coordinates
        if (!LocationService::isValidCoordinates($latitude, $longitude)) {
            \Log::error('📍 ATTENDANCE CHECK-IN: Invalid GPS coordinates', [
                'user_id' => $userId,
                'latitude' => $latitude,
                'longitude' => $longitude
            ]);
            return null;
        }

        // Calculate distance from base. Priority: the location of the rider's SHIFT
        // for today (getUserShift resolves assignment → user default → primary), so a
        // rider working at LaCarne today is checked against LaCarne, not the office.
        // Falls back inside calculateDistanceFromBase if that location is unavailable.
        $shiftLocationId = null;
        try {
            $shiftLocationId = (new \App\Services\ShiftResolutionService())
                ->getUserShift($userId, now()->format('Y-m-d'))['location_id'] ?? null;
        } catch (\Throwable $e) { /* fall back to the user's assigned location below */ }

        // ⭐ Sep-2026 — the fix's OWN error bar, the way every other location door already
        //   reads it (checkout gate, home-meter stamp, home fence: COARSE_FIX_M, default 150 m).
        //   slack   = min(accuracy, COARSE_FIX_M) — up to 150 m of the distance may be the fix's
        //             fault before we call him remote (a wildly bad fix can never buy a pass).
        //   coarse  = accuracy > COARSE_FIX_M — the fix cannot resolve a 300 m question at all;
        //             the caller reports "GPS was vague" instead of "he was elsewhere".
        //   No accuracy sent (older APKs) ⇒ slack 0, coarse false ⇒ exactly the previous rule.
        $accM     = ($accuracy !== null && is_numeric($accuracy) && (float) $accuracy > 0) ? (float) $accuracy : null;
        $coarseM  = (float) $this->attnConfig('COARSE_FIX_M', 150);
        $isCoarse = $accM !== null && $accM > $coarseM;
        $slackM   = $accM !== null ? min($accM, $coarseM) : 0.0;

        /**
         * 📶 OFFICE PRESENCE BY WI-FI (16-Sep-2026). If the phone is connected to an office's own
         *    access point it is inside that office, whatever the coordinates say. Resolved once
         *    here; used below wherever the fix alone cannot answer. Dormant until the BSSIDs are
         *    configured (see LocationService::officeForWifi).
         */
        $wifiOffice = LocationService::officeForWifi($request->input('wifi_bssid'));

        /**
         * ⭐⭐ THE PHANTOM GATE (16-Sep-2026). Farooq's check-in was recorded from Tiananmen Square
         *    at 32 m "accuracy" and stored as a REMOTE check-in 3,878 km away — a payroll fact
         *    manufactured by a mislocated Wi-Fi router. A fix outside Pakistan is not a bad fix,
         *    it is no fix: it never reaches the distance rule and never lands in his row.
         *    If the office Wi-Fi vouches for him, the check-in proceeds on the office's own
         *    coordinates; otherwise the caller decides (mandatory-location ON ⇒ refused with the
         *    Roman-Urdu sentence; OFF ⇒ recorded without coordinates, as any no-fix check-in is).
         */
        $this->lastCheckinPhantom = null;
        if (!LocationService::isPlausibleFix($latitude, $longitude)) {
            $detail = sprintf('phantom %s,%s acc=%s src=%s at=checkin wifi=%s',
                $latitude, $longitude, $accuracy ?? '?', $source ?? '?', $wifiOffice->location_name ?? 'none');
            \Log::warning('📍 ATTENDANCE CHECK-IN: fix outside Pakistan (phantom) — not used', ['user_id' => $userId, 'detail' => $detail]);
            $this->recordLocationFailureRow($userId, 'phantom_fix', 'checkin_gate', $detail, $latitude, $longitude);
            if (!$wifiOffice) {
                $this->lastCheckinPhantom = ['latitude' => $latitude, 'longitude' => $longitude, 'accuracy' => $accuracy];
                return null;
            }
            $latitude  = (float) $wifiOffice->latitude;
            $longitude = (float) $wifiOffice->longitude;
            $accuracy  = null; $accM = null; $isCoarse = false; $slackM = 0.0;
            $source    = 'office_wifi'; $method = 5;
        }

        $distanceInfo = LocationService::calculateDistanceFromBase($latitude, $longitude, $userId, $shiftLocationId, $slackM);

        /**
         * 📶 The Wi-Fi also settles a fix that is merely VAGUE or reads remote: connected to the
         *    office router beats a ±700 m cell centroid 1.1 km away (the Sep-5 Orchard Lacarne
         *    lockout, in exactly these words). A SHARP fix that agrees he is elsewhere is left
         *    alone — the router's reach is tens of metres, a sharp fix hundreds away wins.
         */
        $sharpM  = (float) $this->attnConfig('SHARP_FIX_M', 50);
        $isSharp = $accM !== null && $accM <= $sharpM;
        if ($wifiOffice && ($isCoarse || (!empty($distanceInfo['is_remote']) && !$isSharp))) {
            $distanceInfo['is_remote'] = false;
            $distanceInfo['distance_meters'] = 0;
            $distanceInfo['base_location'] = $wifiOffice;
            $distanceInfo['matched_office_wifi'] = true;
            $isCoarse = false;
            $source = 'office_wifi'; $method = 5;
        }

        // R1 — "check in at ANY office" riders: if the resolved (shift/assigned) location reads
        // remote, accept when he's at ANY active company office instead. Widens WHERE, not
        // WHETHER — he must still be AT an office. Guarded so the column being absent is a no-op.
        if (!empty($distanceInfo['is_remote'])) {
            try {
                if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_rider_profile', 'checkin_any_office')
                    && (int) \DB::table('t_ops_rider_profile')->where('user_id', $userId)->value('checkin_any_office') === 1) {
                    $anyOffice = LocationService::nearestOfficeWithin($latitude, $longitude);
                    if ($anyOffice) {
                        $distanceInfo['is_remote'] = false;
                        $distanceInfo['distance_meters'] = $anyOffice->distance_meters;
                        $distanceInfo['base_location'] = $anyOffice;
                        $distanceInfo['matched_any_office'] = true;
                    }
                }
            } catch (\Throwable $e) { /* any-office check is best-effort; fall back to the normal result */ }
        }

        // ⭐ Detailed logging for attendance location tracking
        // ⚠ `method`/`source` are what the APP BELIEVED, not what happened: the fused provider
        //   answers a "fresh high-accuracy" request with a network fix when GPS hasn't locked, and
        //   the app used to label that method 1. Only `accuracy_meters` is real — `fix_quality`
        //   is derived from it and is the field to trust. (Method 4 = the app's network fallback;
        //   it had no label here, so it logged as "Unknown".)
        $methodLabels = [
            1 => 'Fresh GPS (Method 1)',
            2 => 'Recent GPS Cache (Method 2)',
            3 => 'Cached GPS (Method 3)',
            4 => 'Network/Cell (Method 4 - ⚠️ coarse)',
            5 => 'Office Wi-Fi presence (Method 5)',
        ];
        $methodLabel = $methodLabels[$method] ?? "Unknown (Method {$method})";

        \Log::info('📍 ATTENDANCE CHECK-IN: Location captured', [
            'user_id' => $userId,
            'user_name' => \DB::table('t_sys_user')->where('id', $userId)->value('fullname'),
            'date' => now()->toDateString(),
            'time' => now()->format('H:i:s'),
            'location_method' => $methodLabel,
            'source' => $source ?? 'unknown',
            'accuracy_meters' => $accuracy,
            'fix_quality' => $accM === null ? 'unknown' : ($isCoarse ? "COARSE (>{$coarseM}m — not a verdict)" : 'sharp'),
            'slack_m' => (int) round($slackM),
            'latitude' => $latitude,
            'longitude' => $longitude,
            'distance_from_office' => $distanceInfo['distance_meters'] ? round($distanceInfo['distance_meters']) . 'm' : 'N/A',
            'effective_radius_m' => $distanceInfo['effective_radius_m'] ?? null,
            'is_remote' => $distanceInfo['is_remote'] ? 'YES' : 'NO',
            'office_location' => $distanceInfo['base_location']->location_name ?? 'N/A',
        ]);

        // Warn on a COARSE fix (judged by accuracy — the old `method == 3` test was aimed at the
        // cached-GPS attempt, so it never fired for the network fallback it was written for).
        if ($isCoarse) {
            \Log::warning('📍 ATTENDANCE: Coarse (network-grade) fix at check-in — cannot place the rider', [
                'user_id' => $userId,
                'accuracy' => $accuracy,
                'distance_m' => $distanceInfo['distance_meters'],
                'recommendation' => 'Rider should step outside / disable WiFi and retry for a GPS lock',
            ]);
        }

        if ($distanceInfo['error']) {
            \Log::error('📍 ATTENDANCE CHECK-IN: Distance calculation failed', [
                'user_id' => $userId,
                'error' => $distanceInfo['error']
            ]);
        }

        return [
            'db_fields' => [
                'checkin_latitude' => $latitude,
                'checkin_longitude' => $longitude,
                'checkin_accuracy' => $accuracy,
                'checkin_distance_from_base' => $distanceInfo['distance_meters'],
                'checkin_location_captured_at' => now(),
                'is_remote_checkin' => $distanceInfo['is_remote'] ? 1 : 0,
            ],
            'is_remote' => $distanceInfo['is_remote'],
            'distance' => $distanceInfo['distance_meters'],
            // Fix quality for the mandatory-location block: a coarse fix gets the honest
            // "GPS was vague" refusal instead of "you're X from Y".
            'is_coarse' => $isCoarse,
            'accuracy_m' => $accM,
            'effective_radius_m' => $distanceInfo['effective_radius_m'] ?? null,
            // Name of the base we measured against (for the mandatory-location block
            // message); null when no base is configured for this rider.
            'base_name' => $distanceInfo['base_location']->location_name ?? null,
            'has_base' => !empty($distanceInfo['base_location']),
        ];
    }

    /**
     * Store meter picture to storage
     */
    private function storeMeterPicture($file, $userId, $type): string
    {
        $date = now();
        $year = $date->format('Y');
        $month = $date->format('m');
        $filename = "user_{$userId}_{$date->format('Ymd_His')}_{$type}.jpg";
        
        $path = "attendance/meters/{$year}/{$month}/{$filename}";
        
        \Storage::disk('public')->put($path, file_get_contents($file));
        
        return $path;
    }

    /**
     * Get petrol rate groups with assigned users
     */
    public function getPetrolRate(Request $request)
    {
        try {
            $groups = DB::table('t_fin_petrol_rate_group')
                ->where('is_active', 1)
                ->orderBy('name')
                ->get();

            // Build groups with user details
            $rateGroups = [];
            foreach ($groups as $group) {
                $users = [];
                if (!empty($group->user_ids)) {
                    $ids = array_map('trim', explode(',', $group->user_ids));
                    $ids = array_filter($ids);
                    $users = DB::table('t_sys_user')
                        ->whereIn('id', $ids)
                        ->select('id', 'fullname')
                        ->get()
                        ->map(fn($u) => ['id' => $u->id, 'name' => $u->fullname])
                        ->values()
                        ->toArray();
                }
                $rateGroups[] = [
                    'id' => $group->id,
                    'name' => $group->name,
                    'rate' => (float) $group->rate,
                    'user_ids' => $group->user_ids ?: '',
                    'users' => $users,
                ];
            }

            // Get all visible active users for the picker
            $allRiders = DB::table('t_sys_user as u')
                ->leftJoin('t_ops_attendance_visibility as av', 'av.user_id', '=', 'u.id')
                ->where('u.is_active', 1)
                ->where(function($q) {
                    $q->whereNull('av.is_visible')
                      ->orWhere('av.is_visible', 1);
                })
                ->select('u.id', 'u.fullname')
                ->orderBy('u.fullname')
                ->get()
                ->map(fn($u) => ['id' => $u->id, 'name' => $u->fullname])
                ->values();

            // Legacy: return first group's rate for backward compat
            $primaryRate = count($rateGroups) > 0 ? $rateGroups[0]['rate'] : 10;
            $allUserIds = collect($rateGroups)->pluck('user_ids')->filter()->implode(',');

            return response()->json([
                'success' => true,
                'petrol_rate' => $primaryRate,
                'allowed_user_ids' => $allUserIds,
                'rate_groups' => $rateGroups,
                'all_riders' => $allRiders,
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Save petrol rate groups - admin only
     */
    public function setPetrolRate(Request $request)
    {
        try {
            $user = Auth::user();
            
            if (!$user->hasMobilePermission('view_store_attendance')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $validated = $request->validate([
                'groups' => 'required|array|min:1',
                'groups.*.id' => 'nullable|integer',
                'groups.*.name' => 'required|string|max:100',
                'groups.*.rate' => 'required|numeric|min:0.01|max:999',
                'groups.*.user_ids' => 'nullable|string',
            ]);

            // Validate no user appears in multiple groups
            $allAssignedIds = [];
            foreach ($validated['groups'] as $group) {
                if (!empty($group['user_ids'])) {
                    $ids = array_map('trim', explode(',', $group['user_ids']));
                    $ids = array_filter($ids);
                    foreach ($ids as $id) {
                        if (in_array($id, $allAssignedIds)) {
                            $userName = DB::table('t_sys_user')->where('id', $id)->value('fullname') ?: "User #$id";
                            return response()->json([
                                'success' => false,
                                'message' => "$userName is assigned to multiple rate groups. Each user can only be in one group."
                            ], 422);
                        }
                        $allAssignedIds[] = $id;
                    }
                }
            }

            DB::beginTransaction();

            // Get existing group IDs
            $existingIds = DB::table('t_fin_petrol_rate_group')->where('is_active', 1)->pluck('id')->toArray();
            $incomingIds = array_filter(array_column($validated['groups'], 'id'));

            // Soft-delete groups that are no longer in the list
            $toDelete = array_diff($existingIds, $incomingIds);
            if (!empty($toDelete)) {
                DB::table('t_fin_petrol_rate_group')
                    ->whereIn('id', $toDelete)
                    ->update(['is_active' => 0, 'updated_at' => now()]);
            }

            // Upsert groups
            foreach ($validated['groups'] as $groupData) {
                if (!empty($groupData['id'])) {
                    DB::table('t_fin_petrol_rate_group')
                        ->where('id', $groupData['id'])
                        ->update([
                            'name' => $groupData['name'],
                            'rate' => $groupData['rate'],
                            'user_ids' => $groupData['user_ids'] ?? null,
                            'is_active' => 1,
                            'updated_at' => now(),
                        ]);
                } else {
                    DB::table('t_fin_petrol_rate_group')->insert([
                        'name' => $groupData['name'],
                        'rate' => $groupData['rate'],
                        'user_ids' => $groupData['user_ids'] ?? null,
                        'is_active' => 1,
                        'created_at' => now(),
                        'updated_at' => now(),
                    ]);
                }
            }

            // Keep legacy config keys in sync with first group for any code that still reads them
            $firstGroup = $validated['groups'][0] ?? null;
            if ($firstGroup) {
                \App\Models\FIN\ConfigModel::set('PETROL_RATE_PER_KM', (string) $firstGroup['rate'], 'Petrol rate (synced from rate groups)');
                \App\Models\FIN\ConfigModel::set('PETROL_AUTO_CALC_USER_IDS', implode(',', $allAssignedIds), 'Petrol user IDs (synced from rate groups)');
            }

            DB::commit();

            \Log::info('Petrol rate groups updated', [
                'groups_count' => count($validated['groups']),
                'updated_by' => $user->id,
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Petrol rate groups saved successfully',
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Get meter picture URL (works for both local dev and production)
     */
    private function getMeterPictureUrl($picturePath): string
    {
        // Always route through our storage proxy (works in prod + local)
        // Build absolute URL using the current request host to support mobile devices
        $base = request()->getSchemeAndHttpHost();
        $url = rtrim($base, '/') . '/public-storage/' . ltrim($picturePath, '/');
        
        \Log::info('getMeterPictureUrl', [
            'input' => $picturePath,
            'base' => $base,
            'output' => $url,
        ]);
        
        return $url;
    }

    /**
     * ⭐ Calculate GPS distance from an array of location readings
     * Uses Haversine formula with noise filtering
     * 
     * @param array $readings Array of objects with latitude, longitude, accuracy, captured_at
     * @return array ['distance' => km, 'readings_count' => int]
     */
    private function calculateGpsDistanceFromReadings(array $readings): array
    {
        $totalDistance = 0;
        $validReadingsCount = count($readings);
        
        if ($validReadingsCount < 2) {
            return ['distance' => null, 'readings_count' => $validReadingsCount];
        }
        
        $minMovementMeters = 20; // Filter out GPS drift (< 20m considered stationary)
        $segmentsUsed = 0;
        
        for ($i = 1; $i < $validReadingsCount; $i++) {
            $prev = $readings[$i - 1];
            $curr = $readings[$i];
            
            // Calculate distance between consecutive points using Haversine
            $distanceMeters = $this->haversineDistance(
                (float) $prev->latitude,
                (float) $prev->longitude,
                (float) $curr->latitude,
                (float) $curr->longitude
            );
            
            // Filter out GPS noise - only count if movement > 20m
            // This handles stationary GPS drift
            if ($distanceMeters >= $minMovementMeters) {
                $totalDistance += $distanceMeters;
                $segmentsUsed++;
            }
        }
        
        // Convert to kilometers, round to 1 decimal
        $distanceKm = round($totalDistance / 1000, 1);
        
        return [
            'distance' => $distanceKm > 0 ? $distanceKm : null,
            'readings_count' => $validReadingsCount,
        ];
    }

    /**
     * ⭐ Haversine formula to calculate distance between two lat/lng points
     * 
     * @param float $lat1 Latitude of point 1
     * @param float $lng1 Longitude of point 1
     * @param float $lat2 Latitude of point 2
     * @param float $lng2 Longitude of point 2
     * @return float Distance in meters
     */
    private function haversineDistance(float $lat1, float $lng1, float $lat2, float $lng2): float
    {
        $earthRadiusMeters = 6371000; // Earth's radius in meters
        
        $lat1Rad = deg2rad($lat1);
        $lat2Rad = deg2rad($lat2);
        $deltaLat = deg2rad($lat2 - $lat1);
        $deltaLng = deg2rad($lng2 - $lng1);
        
        $a = sin($deltaLat / 2) * sin($deltaLat / 2) +
             cos($lat1Rad) * cos($lat2Rad) *
             sin($deltaLng / 2) * sin($deltaLng / 2);
        
        $c = 2 * atan2(sqrt($a), sqrt(1 - $a));
        
        return $earthRadiusMeters * $c;
    }

    /**
     * ⭐ Calculate gap information for GPS readings
     * Identifies periods where GPS data is missing and whether rider was stationary
     * 
     * @param array $readings GPS readings array
     * @param string $loginTime HH:MM:SS
     * @param string|null $logoutTime HH:MM:SS or null if still working
     * @return array Gap summary info
     */
    private function calculateGapInfo(array $readings, string $loginTime, ?string $logoutTime): array
    {
        $minGapThreshold = 10; // Minutes - gaps less than this are normal
        $totalGapMinutes = 0;
        $stationaryGapMinutes = 0;
        $gapsCount = 0;
        $movingGapsCount = 0;
        
        if (count($readings) < 2) {
            return [
                'total_gap_minutes' => 0,
                'stationary_gap_minutes' => 0,
                'effective_gap_minutes' => 0,
                'gaps_count' => 0,
                'moving_gaps_count' => 0,
                'coverage_percent' => 0,
                'effective_coverage_percent' => 0,
            ];
        }
        
        // Calculate expected working minutes
        $loginTimestamp = strtotime($loginTime);
        $logoutTimestamp = $logoutTime ? strtotime($logoutTime) : time();
        $workingMinutes = ($logoutTimestamp - $loginTimestamp) / 60;
        
        // Check gap between login and first reading
        $firstReading = $readings[0];
        $firstReadingTime = strtotime(is_object($firstReading) ? $firstReading->captured_at : $firstReading['captured_at']);
        $gapFromLogin = ($firstReadingTime - $loginTimestamp) / 60;
        if ($gapFromLogin > $minGapThreshold) {
            $totalGapMinutes += $gapFromLogin;
            $gapsCount++;
            $movingGapsCount++; // Unknown if stationary at start
        }
        
        // Check gaps between consecutive readings
        for ($i = 1; $i < count($readings); $i++) {
            $prev = $readings[$i - 1];
            $curr = $readings[$i];
            
            $prevTime = strtotime(is_object($prev) ? $prev->captured_at : $prev['captured_at']);
            $currTime = strtotime(is_object($curr) ? $curr->captured_at : $curr['captured_at']);
            $gapMinutes = ($currTime - $prevTime) / 60;
            
            if ($gapMinutes > $minGapThreshold) {
                $gapsCount++;
                $totalGapMinutes += $gapMinutes;
                
                // Check if stationary during gap (< 50m movement)
                $distanceMeters = $this->haversineDistance(
                    (float) (is_object($prev) ? $prev->latitude : $prev['latitude']),
                    (float) (is_object($prev) ? $prev->longitude : $prev['longitude']),
                    (float) (is_object($curr) ? $curr->latitude : $curr['latitude']),
                    (float) (is_object($curr) ? $curr->longitude : $curr['longitude'])
                );
                
                if ($distanceMeters < 50) {
                    // Stationary gap - rider didn't move, so no distance lost
                    $stationaryGapMinutes += $gapMinutes;
                } else {
                    // Moving gap - rider moved but we don't have data
                    $movingGapsCount++;
                }
            }
        }
        
        // Check gap between last reading and logout
        if ($logoutTime) {
            $lastReading = $readings[count($readings) - 1];
            $lastReadingTime = strtotime(is_object($lastReading) ? $lastReading->captured_at : $lastReading['captured_at']);
            $gapToLogout = ($logoutTimestamp - $lastReadingTime) / 60;
            if ($gapToLogout > $minGapThreshold) {
                $totalGapMinutes += $gapToLogout;
                $gapsCount++;
                $movingGapsCount++; // Unknown if stationary at end
            }
        }
        
        // Effective gap = only gaps where we might have lost distance data
        $effectiveGapMinutes = $totalGapMinutes - $stationaryGapMinutes;
        
        // Coverage percentages
        $coveragePercent = $workingMinutes > 0 
            ? round((($workingMinutes - $totalGapMinutes) / $workingMinutes) * 100) 
            : 0;
        $effectiveCoveragePercent = $workingMinutes > 0 
            ? round((($workingMinutes - $effectiveGapMinutes) / $workingMinutes) * 100) 
            : 0;
        
        return [
            'total_gap_minutes' => round($totalGapMinutes),
            'stationary_gap_minutes' => round($stationaryGapMinutes),
            'effective_gap_minutes' => round($effectiveGapMinutes),
            'gaps_count' => $gapsCount,
            'moving_gaps_count' => $movingGapsCount,
            'coverage_percent' => min(100, max(0, $coveragePercent)),
            'effective_coverage_percent' => min(100, max(0, $effectiveCoveragePercent)),
        ];
    }

    /**
     * ⭐ Calculate ROAD distance using OpenRouteService API
     * This gives actual road distance instead of straight-line
     * Free tier: 2,000 requests/day
     * 
     * @param int $userId
     * @param string $date YYYY-MM-DD
     * @return array ['road_distance' => km, 'straight_distance' => km, 'readings_count' => int, 'source' => 'api'|'calculated']
     */
    public function calculateRoadDistance(Request $request)
    {
        try {
            $userId = $request->input('user_id');
            $date = $request->input('date', now()->toDateString());
            
            if (!$userId) {
                return response()->json([
                    'success' => false,
                    'message' => 'user_id is required'
                ], 400);
            }
            
            // Get all GPS readings for the day
            $readings = \DB::table('t_ops_rider_location')
                ->where('user_id', $userId)
                ->whereDate('captured_at', $date)
                ->where('accuracy', '<=', 100)
                ->orderBy('captured_at')
                ->select('latitude', 'longitude', 'accuracy', 'captured_at')
                ->get();
            
            if ($readings->count() < 2) {
                return response()->json([
                    'success' => true,
                    'road_distance' => null,
                    'straight_distance' => null,
                    'readings_count' => $readings->count(),
                    'message' => 'Not enough GPS readings for distance calculation',
                    'source' => 'insufficient_data'
                ]);
            }
            
            // Calculate straight-line distance first (for comparison)
            $straightResult = $this->calculateGpsDistanceFromReadings($readings->toArray());
            
            // ⭐ IMPORTANT: Skip road distance API if rider barely moved (< 100m)
            // This prevents misleading results where OpenRouteService calculates a driving route
            // between nearby points that are just GPS drift, not actual travel
            // 100m threshold = reasonable to distinguish GPS drift from actual short trips
            if ($straightResult['distance'] === null || $straightResult['distance'] < 0.1) {
                return response()->json([
                    'success' => true,
                    'road_distance' => null,
                    'straight_distance' => $straightResult['distance'],
                    'readings_count' => $readings->count(),
                    'message' => 'Insufficient GPS movement (< 100m) - rider likely stationary',
                    'source' => 'skipped_stationary'
                ]);
            }
            
            // ⭐ Sample readings intelligently for API call
            // Using 25 samples with GPS drift filtering gives best accuracy
            $sampledReadings = $this->sampleGpsReadings($readings->toArray(), 25);
            
            if (count($sampledReadings) < 2) {
                return response()->json([
                    'success' => true,
                    'road_distance' => null,
                    'straight_distance' => $straightResult['distance'],
                    'readings_count' => $readings->count(),
                    'message' => 'Could not sample enough readings',
                    'source' => 'calculated'
                ]);
            }
            
            // ⭐ Call OpenRouteService Directions API
            $roadDistance = $this->callOpenRouteService($sampledReadings);
            
            if ($roadDistance === null) {
                // API failed, return straight-line as fallback
                return response()->json([
                    'success' => true,
                    'road_distance' => null,
                    'straight_distance' => $straightResult['distance'],
                    'readings_count' => $readings->count(),
                    'sampled_points' => count($sampledReadings),
                    'message' => 'Road distance API unavailable, showing straight-line estimate',
                    'source' => 'calculated'
                ]);
            }
            
            // ⭐ Store the calculated road distance in the database for future use
            $roundedRoadDistance = round($roadDistance, 1);
            \DB::table('t_ops_attendance')
                ->where('user_id', $userId)
                ->whereDate('attendance_date', $date)
                ->update([
                    'road_distance_km' => $roundedRoadDistance,
                    'road_distance_source' => 'openrouteservice',
                    'gps_straight_distance_km' => $straightResult['distance'],
                    'gps_readings_used' => $readings->count(),
                ]);
            
            \Log::info("Road distance stored for user {$userId} on {$date}: {$roundedRoadDistance} km");
            
            return response()->json([
                'success' => true,
                'road_distance' => $roundedRoadDistance,
                'straight_distance' => $straightResult['distance'],
                'readings_count' => $readings->count(),
                'sampled_points' => count($sampledReadings),
                'accuracy_ratio' => $straightResult['distance'] > 0 
                    ? round($roadDistance / $straightResult['distance'] * 100) . '%' 
                    : null,
                'source' => 'openrouteservice',
                'stored' => true, // ⭐ Indicate the value was stored
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Road distance calculation failed', [
                'error' => $e->getMessage(),
                'user_id' => $request->input('user_id'),
                'date' => $request->input('date')
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to calculate road distance: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * ⭐ Sample GPS readings for road distance API call
     * 
     * Strategy:
     * 1. Filter out GPS DRIFT - consecutive readings within ~30m are noise
     * 2. Then sample evenly from filtered points to get max 50 waypoints
     * 
     * This removes fake distance from GPS drift while preserving actual route
     * 
     * @param array $readings GPS readings array
     * @param int $maxPoints Maximum number of points (OpenRouteService limit is 50)
     * @return array Sampled readings
     */
    private function sampleGpsReadings(array $readings, int $maxPoints = 25): array
    {
        $count = count($readings);
        
        // Handle edge cases
        if ($count <= 2) {
            return $readings;
        }
        
        // ⭐ Step 1: Filter GPS drift - remove consecutive points within ~30m
        // GPS drift = small fake movements when rider is stationary
        // 0.0003 degrees ≈ 30 meters - good threshold for drift vs real movement
        $filtered = [];
        $prevLat = null;
        $prevLng = null;
        $driftThreshold = 0.0003; // ~30m - filters GPS noise but keeps real movements
        
        foreach ($readings as $reading) {
            $lat = (float)(is_object($reading) ? $reading->latitude : ($reading['latitude'] ?? 0));
            $lng = (float)(is_object($reading) ? $reading->longitude : ($reading['longitude'] ?? 0));
            
            // Include point if it's the first OR moved more than drift threshold
            if ($prevLat === null || 
                abs($lat - $prevLat) > $driftThreshold || 
                abs($lng - $prevLng) > $driftThreshold) {
                $filtered[] = $reading;
                $prevLat = $lat;
                $prevLng = $lng;
            }
        }
        
        $filteredCount = count($filtered);
        
        // Safety: if filtering removed too much, use original
        if ($filteredCount < 2) {
            $filtered = $readings;
            $filteredCount = $count;
        }
        
        // ⭐ Step 2: If under limit, return filtered points
        if ($filteredCount <= $maxPoints) {
            return $filtered;
        }
        
        // ⭐ Step 3: Sample evenly from filtered points
        $sampled = [];
        $step = ($filteredCount - 1) / ($maxPoints - 1);
        
        for ($i = 0; $i < $maxPoints; $i++) {
            $index = (int) round($i * $step);
            if ($index < $filteredCount) {
                $sampled[] = $filtered[$index];
            }
        }
        
        // Always ensure first and last points are included
        $first = $filtered[0];
        $last = $filtered[$filteredCount - 1];
        
        // Check first
        $firstLat = (float)(is_object($first) ? $first->latitude : ($first['latitude'] ?? 0));
        $firstLng = (float)(is_object($first) ? $first->longitude : ($first['longitude'] ?? 0));
        $sampledFirst = $sampled[0];
        $sFirstLat = (float)(is_object($sampledFirst) ? $sampledFirst->latitude : ($sampledFirst['latitude'] ?? 0));
        $sFirstLng = (float)(is_object($sampledFirst) ? $sampledFirst->longitude : ($sampledFirst['longitude'] ?? 0));
        
        if (abs($firstLat - $sFirstLat) > 0.00001 || abs($firstLng - $sFirstLng) > 0.00001) {
            array_unshift($sampled, $first);
        }
        
        // Check last
        $lastLat = (float)(is_object($last) ? $last->latitude : ($last['latitude'] ?? 0));
        $lastLng = (float)(is_object($last) ? $last->longitude : ($last['longitude'] ?? 0));
        $sampledLast = end($sampled);
        $sLastLat = (float)(is_object($sampledLast) ? $sampledLast->latitude : ($sampledLast['latitude'] ?? 0));
        $sLastLng = (float)(is_object($sampledLast) ? $sampledLast->longitude : ($sampledLast['longitude'] ?? 0));
        
        if (abs($lastLat - $sLastLat) > 0.00001 || abs($lastLng - $sLastLng) > 0.00001) {
            $sampled[] = $last;
        }
        
        return $sampled;
    }

    /**
     * ⭐ Call OpenRouteService Directions API
     * Free tier: 2,000 requests/day
     * Docs: https://openrouteservice.org/dev/#/api-docs/v2/directions
     */
    private function callOpenRouteService(array $readings): ?float
    {
        // OpenRouteService API key (free tier)
        // Get yours at: https://openrouteservice.org/dev/#/signup
        $apiKey = env('OPENROUTESERVICE_API_KEY', '5b3ce3597851110001cf62487c37b3c0b8d74b9fb9f7d9f3c3d7f8e9');
        
        // Build coordinates array [lng, lat] format (GeoJSON standard)
        $coordinates = array_map(function($reading) {
            return [
                (float) (is_object($reading) ? $reading->longitude : $reading['longitude']),
                (float) (is_object($reading) ? $reading->latitude : $reading['latitude'])
            ];
        }, $readings);
        
        try {
            $client = new \GuzzleHttp\Client([
                'timeout' => 30,
                'connect_timeout' => 10,
            ]);
            
            $response = $client->post('https://api.openrouteservice.org/v2/directions/driving-car', [
                'headers' => [
                    'Authorization' => $apiKey,
                    'Content-Type' => 'application/json',
                    'Accept' => 'application/json',
                ],
                'json' => [
                    'coordinates' => $coordinates,
                    'instructions' => false,        // We don't need turn-by-turn
                    'geometry' => false,            // We don't need the polyline
                    'units' => 'km',
                ]
            ]);
            
            $data = json_decode($response->getBody()->getContents(), true);
            
            // Extract total distance from response
            if (isset($data['routes'][0]['summary']['distance'])) {
                return $data['routes'][0]['summary']['distance']; // Already in km
            }
            
            \Log::warning('OpenRouteService response missing distance', ['data' => $data]);
            return null;
            
        } catch (\GuzzleHttp\Exception\ClientException $e) {
            $responseBody = $e->hasResponse() ? $e->getResponse()->getBody()->getContents() : 'No response';
            \Log::warning('OpenRouteService API client error', [
                'status' => $e->hasResponse() ? $e->getResponse()->getStatusCode() : null,
                'body' => $responseBody,
                'coordinates_count' => count($coordinates)
            ]);
            return null;
            
        } catch (\Exception $e) {
            \Log::warning('OpenRouteService API error', [
                'error' => $e->getMessage(),
                'coordinates_count' => count($coordinates)
            ]);
            return null;
        }
    }

    /**
     * Upload meter picture independently (after check-in/out)
     */
    public function uploadMeterPicture(Request $request)
    {
        try {
            $user = Auth::user();
            $today = now()->format('Y-m-d');

            // Validate request. ⭐ Photo OR typed reading — at least one. The photo-less path
            // exists for a BROKEN CAMERA inside the chained "Meter & Check In/Out" flows: the
            // typed reading still goes in (meter is compulsory, undeniable), and the web shows
            // the greyed "no photo" camera as the audit. Old APKs always send the photo.
            $request->validate([
                'meter_picture' => 'required_without:meter_reading|nullable|image|max:5120', // 5MB max
                'type' => 'required|in:start,end',
                'meter_reading' => 'required_without:meter_picture|nullable|numeric|min:0|max:9999999',
                'latitude' => 'nullable|numeric|between:-90,90',   // U5: proves an at-home start
                'longitude' => 'nullable|numeric|between:-180,180',
                'accuracy' => 'nullable|numeric',    // metres; lets a coarse fix be judged as coarse
                'fix_age_s' => 'nullable|numeric',   // how old the fix was when it was sent
                'confirm_gap' => 'nullable|boolean', // U5: rider confirmed a continuity gap
                'u5' => 'nullable|boolean',          // U5: new-APK marker (enables needs_confirm replies)
            ]);

            // Check if attendance record exists for today
            $existing = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)
                ->whereDate('attendance_date', $today)
                ->first();

            $type = $request->input('type');
            $meterReading = $request->input('meter_reading'); // ⭐ Get OCR reading

            // ⭐⭐ PAST-MIDNIGHT END METER (1 Sep 2026 incident). This endpoint was the FIFTH
            //    attendance door and the only one never taught the midnight rule, so at 00:23
            //    Farooq — a company-bike rider, therefore meter-gated — was told "No attendance
            //    record found for today. Please check in first." The app records the closing
            //    meter BEFORE it calls checkOut(), so dying here meant checkOut()'s own working
            //    fallback was never reached and his day never closed. Not even the manager's
            //    checkout unlock could rescue him: that valve is only read inside checkOut().
            //
            //    The rule now lives in ONE place — see AttendanceDay.
            //
            // ⚠ END ONLY. A START meter at 00:30 opens a NEW day and must keep creating today's
            //   row; attaching it to yesterday's open shift would overwrite that shift's opening
            //   reading. The `!login_time` test mirrors checkOut(): a today row with no check-in
            //   is a meter-only shell, not the day he is working.
            if ($type === 'end' && (!$existing || !$existing->login_time)) {
                $openYesterday = (new \App\Services\Riders\AttendanceDay())->openPastMidnightRow($user->id);
                if ($openYesterday) {
                    $existing = $openYesterday;
                }
            }

            /**
             * ⭐⭐ THE START METER IS NOT ACCEPTED AFTER THE DAY HAS CLOSED (Rajab, 11-Sep-2026).
             *
             * ⚠⚠ WHAT THIS CAUGHT. At 18:54 he closed the day on the van. At 18:56 his own bike
             *    came back to him. At 18:59 he typed 7,610 into the START tile, which the app
             *    still offered because only the END tile is hidden after checkout — and the
             *    stamp, correctly asking "what does he hold NOW", labelled the morning reading
             *    with the machine he had picked up five minutes ago. The row then read
             *    7,610 (bike) → 75,484 (van): two odometers, one pair.
             *
             * ⚠ A reading typed after checkout is a CORRECTION of a finished day, and corrections
             *   already have exactly one audited door: the manager's ✎ meter
             *   (`MeterCorrectionService`), which is also the only door that can NAME the machine.
             *   Same one-door rule the home-stamped start and the end-meter fix already follow.
             *
             * ⚠ 200 + success:false, like the other denials in this method — older tile UIs only
             *   surface `response.data.message` on a 2xx.
             */
            if ($type === 'start' && $existing && !empty($existing->logout_time)) {
                return response()->json([
                    'success' => false,
                    'meter_after_checkout' => true,
                    'message' => 'Aap check out kar chuke hain — ab start meter yahan se nahi likha ja sakta. '
                        . 'Apne manager se kahein ke wo attendance page par theek kar dein.',
                ]);
            }

            // ⭐ U4 UNIFIED METER-OUT: a company-bike rider on the home flow has exactly ONE
            // day-closing meter — the going-home meter (time + location gated, manager valve).
            // This legacy door used to write meter_end directly with NO gates and NO meter_home,
            // leaving the home journey open forever ("entered the meter but still shows locked").
            // Delegate to the same flow as /attendance/home-meter so both doors are the same door.
            // Denials are returned as 200 {success:false} because old tile UIs only surface
            // response.data.message on 2xx.
            //
            // ⚠⚠ HOISTED ABOVE THE "no row for today" GUARD (1 Sep 2026). A home-flow rider
            //    records his meter AFTER checkout, so past midnight his row is yesterday's AND
            //    already has a logout_time — which the open-shift fallback deliberately will not
            //    match. He therefore hit the 400 below and this delegation, three lines further
            //    down, never ran. `processHomeMeterSubmission` takes $user and finds its own row
            //    (openJourneyRow spans today+yesterday), so it never needed $existing at all —
            //    the guard was simply standing in front of the wrong door.
            //    The main /attendance/home-meter endpoint was always fine; this is the legacy
            //    End-tile path that is supposed to behave identically to it.
            if ($type === 'end') {
                $hjHome = (new \App\Services\Riders\HomeJourneyService())->riderHomePin($user->id);
                if ($hjHome !== null) {
                    if ($meterReading === null || $meterReading === '') {
                        return response()->json([
                            'success' => false,
                            'message' => 'Type the meter reading — your day-closing meter is recorded at home.',
                        ]);
                    }
                    $resp = $this->processHomeMeterSubmission(
                        $user,
                        (int) $meterReading,
                        $request->file('meter_picture'),
                        $request->input('latitude'),
                        $request->input('longitude'),
                        $request->input('accuracy')
                    );
                    if ($resp->getStatusCode() !== 200) {
                        $payload = $resp->getData(true);
                        return response()->json([
                            'success' => false,
                            'message' => $payload['message'] ?? 'Home meter cannot be recorded now.',
                        ]);
                    }
                    return $resp;
                }
            }

            // ⭐ U5 "Meter & Check In": the START meter is recorded BEFORE check-in (the IN
            // button chains meter → check-in). No row yet → create today's row without
            // login_time; checkIn() updates such a row in place (verified behaviour). The old
            // "check in first" gates only remain for the END side (no row = never worked today,
            // and no open past-midnight shift to attach the closing reading to either).
            if (!$existing) {
                if ($type !== 'start') {
                    return response()->json([
                        'success' => false,
                        'message' => 'No attendance record found for today. Please check in first.'
                    ], 400);
                }
                $newId = \DB::table('t_ops_attendance')->insertGetId([
                    'user_id' => $user->id,
                    'attendance_date' => $today,
                    'created_at' => now(),
                    'updated_at' => now(),
                ]);
                $existing = \DB::table('t_ops_attendance')->where('id', $newId)->first();
            }

            /**
             * ⭐⭐ R1 / R2 — A RECORDED READING IS THE RIDER'S FINAL ANSWER (owner ruling,
             *    13-Sep-2026: *"he will enter the meter picture which sticks. He shouldn't be
             *    able to edit it."*).
             *
             * ⚠⚠ THE PROD FAILURE THIS CLOSES, IN FULL. Rajab recorded his own bike's start at
             *    10:45. At 14:10 he was handed the van; wanting to record the van's meter and
             *    having no door for it, he used the only meter box he could see — the saved
             *    Start tile's "Dobara lein" — at 14:17. The server accepted it: it overwrote
             *    `meter_start` with the van's 75,484, overwrote `picture_start` with a photo of
             *    the van's dashboard, and re-stamped the slot to the VAN, because the stamp is
             *    always "what does he hold right now". His bike's morning reading was gone, with
             *    no audit trail. At 18:39 he retook a third time and the van's number went too.
             *    That is Shabib's "his meter readings disappeared" and "it showed the van's meter
             *    picture at checkout" — one mechanism, both symptoms.
             *
             * ⚠ Corrections are NOT lost, they move to the one audited door: the manager's ✎
             *   meter, which is also the only door that can NAME the machine a reading belongs
             *   to (`MeterCorrectionService`). Same one-door rule the home-proven start has had
             *   since U5; this simply extends it to every start and every end.
             *
             * ⚠ THE ONE EXCEPTION — attaching a PHOTO to a reading that has none, with the SAME
             *   value. That is the broken-camera path (he typed the number at check-in, the
             *   camera failed, he photographs it a minute later): no data changes, so nothing is
             *   at risk, and refusing it would strand a genuine photo.
             *
             * ⚠ 200 + `success:false`, like every other denial in this method — older tile UIs
             *   only surface `response.data.message` on a 2xx.
             */
            if ($existing) {
                $already = $type === 'start'
                    ? ($existing->meter_start !== null && $existing->meter_start !== '')
                    : ($existing->meter_end   !== null && $existing->meter_end   !== '');
                if ($already) {
                    $recorded = (int) ($type === 'start' ? $existing->meter_start : $existing->meter_end);
                    $sameValue = ($meterReading === null || $meterReading === '')
                        || (int) $meterReading === $recorded;
                    $photoMissing = $type === 'start'
                        ? empty($existing->picture_start)
                        : empty($existing->picture_end);
                    $photoOnlyTopUp = $sameValue && $photoMissing && $request->hasFile('meter_picture');

                    if (!$photoOnlyTopUp) {
                        return response()->json([
                            'success' => false,
                            'meter_locked' => true,
                            'recorded' => $recorded,
                            'message' => ($type === 'start' ? 'Start' : 'End') . ' meter pehle hi likha ja chuka hai ('
                                . number_format($recorded) . '). Ab ye sirf manager theek kar sakta hai — '
                                . 'attendance page par ✎ meter se.',
                        ]);
                    }
                }
            }

            // Store meter picture (absent on the broken-camera typed-reading path — never
            // overwrite an existing photo with null).
            $picturePath = $request->hasFile('meter_picture')
                ? $this->storeMeterPicture($request->file('meter_picture'), $user->id, $type === 'start' ? 'checkin' : 'checkout')
                : null;

            // Update attendance record
            $updateData = [
                'updated_at' => now(),
            ];
            $homeStartMissed = false;
            $armStartTimer = false;
            $armOrigin = null;
            $startGps = null;
            if ($type === 'start') {
                if ($picturePath) { $updateData['picture_start'] = $picturePath; }
                // ⭐ Save OCR-extracted meter reading to meter_start column
                if ($meterReading !== null && $meterReading !== '') {
                    // ⭐ U5 — a GPS-proven HOME start is a closed record: the legacy Start tile
                    // may retake the PHOTO but must not silently change the reading (that value
                    // anchored the continuity check + the ride-in deadline). Corrections go
                    // through the manager's ✎ meter (audited) — same one-door rule as the
                    // end-meter fix.
                    $isHomeStamped = (string) ($existing->meter_start_source ?? '') === 'home';
                    if ($isHomeStamped && (int) $meterReading !== (int) $existing->meter_start) {
                        return response()->json([
                            'success' => false,
                            'message' => 'Your start meter was recorded at home (' . $existing->meter_start
                                . '). Ask your manager to correct it if it is wrong.',
                        ]);
                    }

                    $startHomePin = null;
                    try {
                        $startHomePin = (new \App\Services\Riders\HomeJourneyService())->riderHomePin($user->id);
                    } catch (\Throwable $e) { $startHomePin = null; }

                    // ⭐ U5 — CONTINUITY gate for bike riders (typo / overnight-use catcher, same
                    // rule as the home card): the reading must sit within METER_CONTINUITY_KM of
                    // last night's closing meter, or the rider explicitly confirms the gap
                    // (confirm_gap=1; breach then shows on the attendance page). ONLY for the new
                    // APK (u5=1): old Start tiles can't answer a confirm question, and an old-APK
                    // office reading legitimately differs by the commute — no regression window.
                    $isNewReading = $existing->meter_start === null || $existing->meter_start === ''
                        || (int) $meterReading !== (int) $existing->meter_start;
                    if ($startHomePin !== null && !$isHomeStamped && $isNewReading
                        && $request->boolean('u5') && !$request->boolean('confirm_gap')) {
                        try {
                            $wjU = new \App\Services\Riders\WorkJourneyService();
                            // ⭐ PHASE D: the MACHINE's last reading, not the man's — a rider
                            //   who swapped bikes is no longer accused of an impossible meter.
                            $prevM = $wjU->continuityBaseline($user->id, $today);
                            if ($prevM !== null) {
                                $gapKm = (int) $meterReading - $prevM['value'];
                                if (abs($gapKm) > $wjU->continuityKm()) {
                                    return response()->json([
                                        'success' => false,
                                        'needs_confirm' => true,
                                        'gap_km' => $gapKm,
                                        'prev_value' => $prevM['value'],
                                        'prev_date' => $prevM['date'],
                                        // ⭐ Sep-30: Roman Urdu, and says when it counts as off-duty.
                                        'message' => $wjU->continuityPrompt((int) $user->id, $prevM, (int) $gapKm, $today),
                                    ]);
                                }
                            }
                        } catch (\Throwable $e) { /* continuity is best-effort */ }
                    }

                    $updateData['meter_start'] = (int) $meterReading;
                    // ⭐ STEP C — freeze WHICH MACHINE this reading is of, now, while we still
                    //   know. See meterStampFields(): a no-op until the SQL has run.
                    $updateData = array_merge($updateData, $this->meterStampFields(
                        $user->id, ['meter_start'], ['meter_start' => (int) $meterReading]));
                    // ⭐ U5 — SOURCE FOLLOWS LOCATION, not which button: GPS at the home pin =
                    // real HOME start; anywhere else (or GPS off) = 'checkin' + nudge + flagged.
                    // The ride-in TIMER is ALWAYS armed for a bike rider's first reading (owner
                    // rule): origin = live GPS when present (at the office → ~0 ETA, checks in
                    // right after), else the HOME PIN (GPS off — he still gets a real deadline,
                    // so switching GPS off buys nothing). Never re-armed by retakes.
                    try {
                        if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'meter_start_source')
                            && !$isHomeStamped && $startHomePin !== null) {
                            $gpsValid = $request->filled('latitude') && $request->filled('longitude')
                                && LocationService::isValidCoordinates($request->latitude, $request->longitude);
                            // A fix is only trustworthy to its OWN accuracy, so let the error bar
                            // reach the fence before calling a rider "not at home" — capped at
                            // COARSE_FIX_M so a wildly bad fix can never buy a home stamp. No
                            // accuracy sent (older APKs) ⇒ no slack ⇒ exactly the previous rule.
                            $startAccuracy = ($request->filled('accuracy') && is_numeric($request->input('accuracy')))
                                ? (float) $request->input('accuracy') : null;
                            $coarseM = (float) $this->attnConfig('COARSE_FIX_M', 150);
                            $startSlack = $startAccuracy !== null ? min($startAccuracy, $coarseM) : 0;
                            $atHomeForStart = false;
                            $dHome = null;
                            if ($gpsValid) {
                                $dHome = $this->haversineDistance(
                                    (float) $request->latitude, (float) $request->longitude,
                                    $startHomePin['lat'], $startHomePin['lng']);
                                $atHomeForStart = ($dHome - $startSlack) <= $startHomePin['radius_m'];
                            }
                            $updateData['meter_start_recorded_at'] = now();
                            $startGps = $atHomeForStart ? 'home' : ($gpsValid ? 'away' : 'none');
                            if ($atHomeForStart) {
                                $updateData['meter_start_source'] = 'home';
                            } else {
                                $updateData['meter_start_source'] = 'checkin';
                                $homeStartMissed = true;
                            }

                            // ⭐ KEEP WHAT WE JUDGED HIM ON. Until now the position and the verdict
                            // were computed here and discarded, so the row could never justify the
                            // "typed at office" label — which also fired when there was NO fix at
                            // all (Waseem, Jul-25). Store the fix, its accuracy, and the metres from
                            // home AND from the office so the UI can state a measurement instead of
                            // an assumption. Schema-guarded: skipped until the hardening SQL is run.
                            if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'meter_start_gps')) {
                                $dOfficeStart = null; $atOfficeStart = false;
                                if ($gpsValid) {
                                    $startOffice = $this->todayShiftLocation($user->id);
                                    if ($startOffice) {
                                        $dOfficeStart = $this->haversineDistance(
                                            (float) $request->latitude, (float) $request->longitude,
                                            $startOffice['lat'], $startOffice['lng']);
                                        $atOfficeStart = ($dOfficeStart - $startSlack) <= (float) ($startOffice['radius_m'] ?? 300);
                                    }
                                }
                                // Richer than the app-facing start_gps (kept at home|away|none above
                                // so deployed APKs keep their exact routing): 'office' is a measured
                                // fact, 'coarse' says the fix was too vague to place him at all.
                                $verdict = 'none';
                                if ($gpsValid) {
                                    if ($atHomeForStart)   { $verdict = 'home'; }
                                    elseif ($atOfficeStart) { $verdict = 'office'; }
                                    elseif ($startAccuracy !== null && $startAccuracy > $coarseM) { $verdict = 'coarse'; }
                                    else { $verdict = 'away'; }
                                }
                                $updateData['meter_start_gps']        = $verdict;
                                $updateData['meter_start_lat']        = $gpsValid ? (float) $request->latitude : null;
                                $updateData['meter_start_lng']        = $gpsValid ? (float) $request->longitude : null;
                                $updateData['meter_start_accuracy_m'] = $startAccuracy;
                                $updateData['meter_start_distance_m'] = $dHome !== null ? (int) round($dHome) : null;
                                $updateData['meter_start_office_m']   = $dOfficeStart !== null ? (int) round($dOfficeStart) : null;
                            }

                            if (empty($existing->work_expected_by)) {
                                $armStartTimer = true;
                                $armOrigin = $gpsValid
                                    ? ['lat' => (float) $request->latitude, 'lng' => (float) $request->longitude]
                                    : ['lat' => $startHomePin['lat'], 'lng' => $startHomePin['lng']];
                            }
                        }
                    } catch (\Throwable $e) { /* stamping is optional */ }
                }
            } else {
                if ($picturePath) { $updateData['picture_end'] = $picturePath; }
                // ⭐ Save OCR-extracted meter reading to meter_end column
                if ($meterReading !== null && $meterReading !== '') {
                    $updateData['meter_end'] = (int) $meterReading;
                    // ⭐ STEP C — the closing reading is of whatever he holds NOW, which on a
                    //   handover day is not what he opened the day on.
                    $updateData = array_merge($updateData, $this->meterStampFields(
                        $user->id, ['meter_end'], ['meter_end' => (int) $meterReading]));
                }
            }

            \DB::table('t_ops_attendance')
                ->where('id', $existing->id)
                ->update($updateData);

            // ⭐ U5 — arm the ride-in timer (origin = live GPS, else home pin — decided above).
            // NON-FATAL (an ETA failure just leaves no timer).
            $startJourney = null;
            if ($armStartTimer && $armOrigin !== null) {
                try {
                    $startJourney = $this->armWorkJourney($user->id, (int) $existing->id, $armOrigin['lat'], $armOrigin['lng']);
                } catch (\Throwable $e) {
                    \Log::warning('armWorkJourney via uploadMeterPicture failed (non-fatal)', ['user_id' => $user->id, 'error' => $e->getMessage()]);
                }
            }

            // ⭐ Build success message with reading info
            $message = $picturePath ? 'Meter picture uploaded successfully' : 'Meter reading saved (no photo)';
            if ($meterReading !== null && $meterReading !== '') {
                $message .= ' with reading: ' . number_format((int) $meterReading);
            }
            if ($homeStartMissed) {
                $message .= "\n🏠 Agli dafa meter start ghar say karain.";
            }

            return response()->json([
                'success' => true,
                'message' => $message,
                'picture_url' => $picturePath ? $this->getMeterPictureUrl($picturePath) : null,
                'meter_reading' => $meterReading !== null && $meterReading !== '' ? (int) $meterReading : null, // ⭐ Return saved reading
                'home_start_missed' => $homeStartMissed, // ⭐ U5 — new APK shows the Urdu nudge as its own alert
                'home_start_recorded' => $startGps === 'home', // ⭐ U5 — GPS-proven AT HOME (ride in, don't check in here)
                'start_gps' => $startGps,                // ⭐ U5 — 'home' | 'away' | 'none' (GPS off)
                'work_journey' => $startJourney,         // ⭐ U5 — the ride-in card payload when armed
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to upload meter picture', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to upload meter picture: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Check out for today
     * Optionally accepts meter picture and GPS location
     */
    public function checkOut(Request $request)
    {
        try {
            $user = Auth::user();
            $today = now()->format('Y-m-d');
            $currentTime = now()->format('H:i:s');
            // ⭐ 16-Sep: a phantom fix (outside Pakistan) is stripped from the request up front, so
            //   the checkout rule, the home-journey arming and the stored checkout position all see
            //   "no location" rather than Beijing. See dropPhantomFromRequest().
            $this->dropPhantomFromRequest($request, (int) $user->id, 'checkout');

            // Validate optional meter picture and location data
            $request->validate([
                'meter_picture' => 'nullable|image|max:5120', // 5MB max
                'latitude' => 'nullable|numeric|between:-90,90',
                'longitude' => 'nullable|numeric|between:-180,180',
                'accuracy' => 'nullable|numeric',
            ]);

            // Check if checked in today
            $existing = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)
                ->whereDate('attendance_date', $today)
                ->first();

            // ⭐ Past-midnight shift: at 00:05 "today" has no attendance row — the open
            //    shift lives on YESTERDAY's row — so checkout dead-ended on "Please
            //    check in first" and the day closed with logout NULL. Bounded to the
            //    small hours (before 06:00) so a forgotten checkout from a normal day
            //    still goes through the manager, not a silent morning self-checkout;
            //    within the window the location rule below still applies unchanged.
            //    (The bike-rider home-meter flow already does this via openJourneyRow.)
            if (!$existing || !$existing->login_time) {
                $openYesterday = (new \App\Services\Riders\AttendanceDay())->openPastMidnightRow($user->id);
                if ($openYesterday) {
                    $existing = $openYesterday;
                }
            }

            if (!$existing || !$existing->login_time) {
                return response()->json(['success' => false, 'message' => 'Please check in first'], 400);
            }

            if ($existing->logout_time) {
                return response()->json(['success' => false, 'message' => 'Already checked out today'], 400);
            }

            // The day this shift BELONGS to — normally today, yesterday when the
            // checkout rolled past midnight. Every per-day side effect below
            // (snapshot, road distance, delivery reference) keys off this, not the
            // wall-clock date, so the work lands on the row it describes.
            $shiftDate = substr((string) $existing->attendance_date, 0, 10);

            // Phase H — mandatory checkout location (only when the manager turned it on).
            // Must be at the office, or at his most recent delivery within window+radius.
            // Manager BYPASS: an active checkout unlock (granted from the web attendance
            // page → Rider bypasses) skips the rule — for the rider who forgot and already
            // went home. The unlock columns + the recorded checkout GPS are the audit.
            $checkoutBypass = !empty($existing->checkout_unlock_until)
                && strtotime((string) $existing->checkout_unlock_until) >= time();
            if (!$checkoutBypass) {
                $ruleCheck = $this->checkoutRuleResult(
                    $user->id, $request->input('latitude'), $request->input('longitude'),
                    $request->input('accuracy'), $shiftDate);
                if (!$ruleCheck['ok']) {
                    // Record the blocked attempt (where he was, where his last delivery was, how
                    // far, why) so a manager sees it LIVE and in the bypass modal — the attempt
                    // otherwise leaves no trace. NON-FATAL: capturing must never break checkout.
                    try {
                        $this->recordCheckoutAttempt((int) $existing->id, $ruleCheck['detail'] ?? null, (int) $user->id);
                    } catch (\Throwable $capErr) {
                        \Log::warning('recordCheckoutAttempt failed (non-fatal)', [
                            'attendance_id' => $existing->id, 'error' => $capErr->getMessage(),
                        ]);
                    }
                    // ⭐ Hand the app what it needs to help him FIX it instead of just refusing:
                    // the reference point + limit let the new APK show a live "you are N m from
                    // the drop" card and re-enable OUT the moment he walks back. Asim was 39 m
                    // from his drop one minute after being blocked and never knew to retry.
                    // Additive — deployed APKs ignore unknown keys and keep today's behaviour.
                    $rd = $ruleCheck['detail'] ?? [];
                    return response()->json([
                        'success' => false,
                        'checkout_rule' => true,
                        'reason' => $ruleCheck['reason'],
                        'message' => $ruleCheck['message'],
                        'retry' => [
                            'subreason'  => $rd['subreason']  ?? null,
                            'distance_m' => $rd['distance_m'] ?? null,
                            'limit_m'    => $rd['limit_m']    ?? null,
                            'age_min'    => $rd['age_min']    ?? null,
                            'window_min' => (int) $this->attnConfig('CHECKOUT_DELIVERY_WINDOW_MINS', 15),
                            'ref_lat'    => $rd['ref_lat']    ?? null,
                            'ref_lng'    => $rd['ref_lng']    ?? null,
                            'ref_label'  => $rd['ref_label']  ?? null,
                            'accuracy_m' => $rd['accuracy_m'] ?? null,
                            'is_coarse'  => (bool) ($rd['is_coarse'] ?? false),
                        ],
                    ], 422);
                }
            }

            // ⭐ Meter-required gate (owner ruling Jul-28: "meter required must force it").
            //    A rider tagged meter_required=1 cannot check OUT without the day-closing
            //    reading — the "Meter & Check Out" chain records meter_end first, so this is
            //    the server backstop. TWO deliberate exceptions:
            //      • HOME-FLOW riders (company bike with a home pin): their day-closing meter
            //        is recorded AT HOME after checkout — blocking here would deadlock them.
            //      • An active manager checkout unlock: the valve stays the master key (a
            //        rider unlocked from home can close the day; the missing meter still
            //        shows on the attendance/Bikes pages).
            //    FAIL-OPEN on errors — never strand a rider at the office over a DB hiccup.
            try {
                $mrColumn = \Illuminate\Support\Facades\Schema::hasColumn('t_ops_rider_profile', 'meter_required');
                $registrySpeaks = (new \App\Services\Riders\VehicleResolver())
                    ->meterRequiredNow($user->id, $today) !== null;

                if (!$checkoutBypass
                    && ($mrColumn || $registrySpeaks)
                    && ($existing->meter_end === null || $existing->meter_end === '')) {
                    // Asked through the SAME helper the app's flag came from, so the gate
                    // can never demand a reading the app didn't offer to take.
                    $mrFlagOut = $this->meterRequiredForUser($user->id, $today);

                    // ⭐⭐ THE OWNER'S THREE METER RULES, IN ONE PLACE (owner ruling, Aug-22 2026):
                    //   1. holds a COMPANY machine right now → the CLOSING reading is taken at
                    //      HOME by the going-home flow, so this gate must stay out of the way.
                    //   2. holds his OWN bike                → he closes it at CHECKOUT, wherever
                    //      that is (customer or office), so demand it here.
                    //   3. holds NOTHING                     → nothing is asked of him at all.
                    //
                    // ⚠⚠ R8 — this used to key on `riderHomePin() === null`, which is a question
                    //    about ATTENDANCE geofencing, not about machines. A home pin exempted a
                    //    rider from this gate on the assumption the home flow would collect his
                    //    close — but `armHomeJourney` only arms for COMPANY machines, so an
                    //    own-bike rider with a pin was asked by nobody and his day closed unread.
                    //
                    // ⚠⚠ R5 — `$openedOnAMeter` (a day opened on a meter must be closed on one)
                    //    is GONE for rule 3. It forced a rider who handed his machine back at
                    //    lunch to close a meter he no longer had in front of him. Its stated
                    //    justification — that the kilometres would otherwise fall out of the
                    //    machine's chain — no longer holds: MachineAttribution's `shared` leg
                    //    already carries a handover day whose two ends belong to different
                    //    riders, and the incoming rider's close continues the chain.
                    $holdsCompany = $this->holdsCompanyMachineNow($user->id);

                    if ($holdsCompany === true) {
                        // Rule 1 — but ONLY when the home flow can actually take the handoff.
                        // ⚠⚠ "Company machine → close at home" presumes a HOME PIN: armHomeJourney
                        //    returns null without one, so for a pinless holder (the VAN driver who
                        //    checks out still holding it) skipping here would mean NOBODY collects
                        //    the close — the home flow can't, and we just excused the only other
                        //    door. The pre-Aug-22 gate blocked exactly this case, and that part of
                        //    it was right. Pin → the home flow owns the close; no pin → it is
                        //    owed here, at checkout, like an own bike.
                        $hasHomePin = (new \App\Services\Riders\HomeJourneyService())
                            ->riderHomePin($user->id) !== null;
                        $needsMeterNow = !$hasHomePin && (int) $mrFlagOut === 1;
                    } elseif ($holdsCompany === false) {
                        $needsMeterNow = ((int) $mrFlagOut === 1);    // rule 2 / rule 3
                    } else {
                        // Registry silent (rules off, tables missing, not a rider): behave
                        // EXACTLY as before this change — including the old home-pin exemption.
                        $openedOnAMeter = $registrySpeaks
                            && $existing->meter_start !== null && $existing->meter_start !== '';
                        $needsMeterNow = ((int) $mrFlagOut === 1 || $openedOnAMeter)
                            && (new \App\Services\Riders\HomeJourneyService())->riderHomePin($user->id) === null;
                    }

                    if ($needsMeterNow) {
                        return response()->json([
                            'success' => false,
                            'meter_required' => true,
                            'message' => 'Record your closing meter first — use "Meter & Check Out".',
                        ], 422);
                    }
                }
            } catch (\Throwable $mrOutErr) {
                \Log::warning('checkout meter gate failed open (non-fatal)', ['user_id' => $user->id, 'error' => $mrOutErr->getMessage()]);
            }

            // Process location data for check-out (no distance calculation)
            $locationData = $this->processCheckoutLocation($request, $user->id);

            // Store meter picture if provided
            $picturePath = null;
            if ($request->hasFile('meter_picture')) {
                $picturePath = $this->storeMeterPicture($request->file('meter_picture'), $user->id, 'checkout');
            }

            // Update with logout time, picture, and location
            $updateData = [
                'logout_time' => $currentTime,
                'updated_at' => now(),
            ];
            if ($picturePath) {
                $updateData['picture_end'] = $picturePath;
            }
            // Add location data
            if ($locationData) {
                $updateData = array_merge($updateData, $locationData);
            }

            \DB::table('t_ops_attendance')
                ->where('id', $existing->id)
                ->update($updateData);

            // ⭐ Freeze overtime minutes onto the row (keyed to the SHIFT's date, so a
            //    past-midnight checkout stamps yesterday's row). NON-FATAL.
            try {
                (new \App\Services\ShiftResolutionService())->stampAttendanceSnapshot($user->id, $shiftDate);
            } catch (\Exception $snapErr) {
                \Log::warning('Attendance shift snapshot failed on check-out (non-fatal)', [
                    'user_id' => $user->id,
                    'date' => $today,
                    'error' => $snapErr->getMessage(),
                ]);
            }

            // 💡 The day just closed, so its overtime is now final and reviewable. Raised off
            // the response and debounced to one push an hour (see DayReviewService).
            // ⚠ A day whose checkout rode a manager unlock is deliberately NOT offered yet —
            // the queue itself withholds it until the window expires, so no early push can
            // freeze a figure that can still move.
            app()->terminating(function () {
                try { app(\App\Services\HR\DayReviewService::class)->pushDueOnce(); }
                catch (\Throwable $e) { /* best effort */ }
            });

            /**
             * 🔧⭐⭐ "HE NEVER WENT, AND HE HAS GONE HOME" (owner ruling, 10-Sep-2026).
             *
             * Same-day workshop bookings have no approval cut-off any more — the cut-off only
             * ever protected the check-in-location promise, which is already settled once the
             * day has begun. What replaces it is this: if he checks out having never set off,
             * the managers are told ONCE and *"it should end there"*.
             *
             * ⚠⚠ It does NOT close the visit. Midnight still turns it into a MISSED day for a
             *    manager to answer — auto-resolving it here would make "he went" and "he never
             *    went" indistinguishable, the one thing this feature must never do.
             * ⚠ Deferred, and non-fatal: nothing about a push may delay or fail a checkout.
             */
            $ckUserId = (int) $user->id;
            app()->terminating(function () use ($ckUserId) {
                try { app(\App\Services\Riders\WorkshopVisitService::class)->alertNotGoneAtCheckout($ckUserId); }
                catch (\Throwable $e) { /* best effort */ }
            });

            // ⭐ Company-bike GOING-HOME journey (U4): arm an ETA-to-home + grace so the rider records
            // his ONE meter reading at home. NON-FATAL, only for company-bike riders with a home pin.
            $homeJourney = null;
            try {
                $homeJourney = $this->armHomeJourney(
                    $user->id, $existing->id,
                    $request->input('latitude'), $request->input('longitude'), $today
                );
            } catch (\Throwable $hjErr) {
                \Log::warning('armHomeJourney failed on check-out (non-fatal)', ['user_id' => $user->id, 'error' => $hjErr->getMessage()]);
            }

            // ⭐ ROAD DISTANCE: Calculate and store after successful checkout
            // This runs in background - doesn't block the checkout response
            $roadDistanceResult = null;
            try {
                $roadDistanceResult = $this->calculateAndStoreRoadDistance($user->id, $shiftDate, $existing->id);
            } catch (\Exception $rdError) {
                // Non-fatal - log but don't fail checkout
                \Log::warning('Road distance calculation failed (non-fatal)', [
                    'user_id' => $user->id,
                    'date' => $today,
                    'error' => $rdError->getMessage()
                ]);
            }

            // ⭐ Cash-held snapshot: the exact amount still open against this rider
            // in Daily Closing (cash collected from delivered orders, not yet
            // submitted). Non-fatal — a computation error must NOT block checkout.
            $cashHeld = null;
            try {
                $cashHeld = $this->getRiderCashHeld($user->id);
            } catch (\Throwable $chErr) {
                \Log::warning('Cash-held computation failed on check-out (non-fatal)', [
                    'user_id' => $user->id,
                    'error' => $chErr->getMessage(),
                ]);
            }

            // 🏦 TILL COUNT (Sep-2026). If this person HOLDS a company till — Shabib and
            // NF Cash — ask him what is physically in it as he closes the day, the same way
            // a rider is asked what cash he is carrying. The answer becomes a sealed
            // checkpoint in the ledger; see TillCountService.
            //
            // ⚠ Non-fatal, like every other bolt-on here: a keeper lookup must never be able
            // to fail a check-out. Null for everybody who is not a keeper, which is everybody
            // but one person today, so this costs an ordinary rider one indexed lookup.
            $tillCount = null;
            try {
                $tillCount = app(\App\Services\FIN\TillCountService::class)->askContext($user->id);
                if ($tillCount) {
                    // Which attendance row this count belongs to, so the two records can be
                    // read together later.
                    $tillCount['attendance_id'] = (int) $existing->id;
                }
            } catch (\Throwable $tcErr) {
                \Log::warning('Till-count context failed on check-out (non-fatal)', [
                    'user_id' => $user->id,
                    'error' => $tcErr->getMessage(),
                ]);
            }

            return response()->json([
                'success' => true,
                // ⭐ NAME THE DAY HE JUST CLOSED. At 00:27 "Checked out successfully at 12:27 AM"
                //   is ambiguous in the one situation where it matters — the rider cannot tell
                //   whether he closed the shift he was working or somehow started a new one.
                //   The app prints this string verbatim, so this works on the CURRENT APK with
                //   no build. Silent on a normal same-day checkout.
                'message' => 'Checked out successfully at ' . date('h:i A', strtotime($currentTime))
                    . (($closedDayLabel = (new \App\Services\Riders\AttendanceDay())->crossedMidnightLabel($existing))
                        ? ' — closed your ' . $closedDayLabel . ' shift.' : ''),
                'logout_time' => $currentTime,
                'picture_url' => $picturePath ? $this->getMeterPictureUrl($picturePath) : null,
                'location_captured' => $locationData ? true : false,
                'road_distance' => $roadDistanceResult, // ⭐ Include calculated road distance
                'cash_held' => $cashHeld, // ⭐ null when zero balance or on compute failure
                // 🏦 null unless this person holds a company till. An old APK simply ignores it.
                'till_count' => $tillCount,
                'home_journey' => $homeJourney, // ⭐ U4: null unless a company-bike home journey armed
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to check out', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json(['success' => false, 'message' => 'Failed to check out: ' . $e->getMessage()], 500);
        }
    }

    /**
     * U4 — the rider's current home-journey payload + home_flow flag. One place builds it for
     * getTodayAttendance AND the light banner endpoint, so the two can never disagree.
     * Returns [payload|null, bool home_flow]. Never throws.
     */
    private function buildHomeJourneyPayload(int $userId, $attendance): array
    {
        try {
            // ⭐ Holds-NOW guard, mirroring armHomeJourney: the app's home_flow flag
            //   and card must go quiet the moment the machine is handed over — not
            //   at midnight when the date rolls.
            if ($this->holdsCompanyMachineNow($userId) === false) {
                return [null, false];
            }
            $hj = new \App\Services\Riders\HomeJourneyService();
            $home = $hj->riderHomePin($userId);
            $homeFlow = $home !== null;
            if (!$homeFlow) {
                return [null, false];
            }
            // Use the passed (today's) row when it holds an OPEN journey; otherwise fall back to the
            // cross-midnight finder so a checkout that rolled past midnight still shows the card.
            $hasOpenHere = $attendance && !empty($attendance->logout_time) && empty($attendance->meter_home);
            if (!$hasOpenHere) {
                $attendance = $hj->openJourneyRow($userId);
            }
            if (!$attendance || empty($attendance->logout_time) || !empty($attendance->meter_home)) {
                return [null, $homeFlow];
            }
            // Timer armed → derived state; a no-GPS checkout armed no timer → free 'armed'
            // (location is still enforced at submit).
            $state = !empty($attendance->home_expected_by) ? $hj->deriveState($attendance) : 'armed';
            if (!in_array($state, ['armed', 'arrived_pending_meter', 'late_locked', 'unlocked'], true)) {
                return [null, $homeFlow];
            }
            return [[
                'state'        => $state, // armed | arrived_pending_meter | late_locked | unlocked
                'attendance_id'=> (int) $attendance->id,
                'expected_by'  => $attendance->home_expected_by ?? null,
                'eta_min'      => ($attendance->home_eta_min ?? null) !== null ? (int) $attendance->home_eta_min : null,
                'distance_km'  => ($attendance->home_distance_km ?? null) !== null ? (float) $attendance->home_distance_km : null,
                'arrived_at'   => $attendance->home_arrived_at ?? null,
                'unlock_until' => $attendance->home_meter_unlock_until ?? null,
                'home_lat'     => $home['lat'],
                'home_lng'     => $home['lng'],
                'home_radius_m'=> $home['radius_m'],
            ], $homeFlow];
        } catch (\Throwable $e) {
            return [null, false];
        }
    }

    /**
     * U4 — light poll for the app's global Ride-Home banner: just today's home-journey state.
     * Cheap (one attendance row) so the banner can poll it while the journey is live.
     */
    public function getHomeJourneyStatus(Request $request)
    {
        try {
            $user = Auth::user();
            $att = \DB::table('t_ops_attendance')->where('user_id', $user->id)
                ->whereDate('attendance_date', now()->format('Y-m-d'))->first();
            [$payload, $homeFlow] = $this->buildHomeJourneyPayload($user->id, $att);
            return response()->json(['success' => true, 'home_journey' => $payload, 'home_flow' => $homeFlow]);
        } catch (\Throwable $e) {
            return response()->json(['success' => true, 'home_journey' => null, 'home_flow' => false]);
        }
    }

    /**
     * U4 — arm a company-bike rider's going-home journey at checkout. Computes ETA from the checkout
     * GPS to his home pin (Google → OpenRouteService → straight-line fallback), adds the grace, and
     * stores home_expected_by. Returns the payload for the app's Ride-Home card, or null when the
     * rider isn't on the flow (not company-bike, or no home pin). Non-fatal by contract.
     */
    /**
     * ⭐ PHASE D FOLLOW-UP (Aug-8 prod find) — does he hold a COMPANY machine RIGHT NOW?
     *
     * The home flow used to ask the DATE-scoped question, and on a handover day the
     * outgoing rider's released assignment still COVERS the date — so at his evening
     * checkout the ride-home journey armed for a bike that left at lunchtime, and he
     * was nagged for a meter he could not take (Waseem, 6 Aug: home photo every night
     * of the month except that one). The live gates must ask what he holds NOW.
     *
     *   true  → holds a company machine, the overnight flow applies
     *   false → holds nothing, or his own machine — no overnight flow
     *   null  → registry silent (rules off / not a rider) → old behaviour, unchanged
     */
    /**
     * ⭐⭐ STEP C — STAMP THE MACHINE ONTO THE READING, AT THE MOMENT IT IS TAKEN.
     *
     * WHY THIS EXISTS (the Van, 20–21 Aug 2026). "Which machine was this reading of?" used to be
     * INFERRED afterwards, from the day's assignment. A rider-day holds ONE meter pair and the
     * registry ONE open assignment, so a day on which a man used two machines could not be
     * expressed at all: Rajab's own bike read 6,434 at 11:58, the Van reached him at 12:09, and
     * the inference filed 6,434 against a van whose odometer is ~73,800.
     *
     * ⭐ The codebase already solved this shape for MONEY. `VehicleResolver::stampClaim()`:
     *   "a permanent financial record… must be frozen at filing time. A reassignment months
     *   later must not silently re-attribute old money." A meter reading is the same kind of
     *   fact — one machine, one instant — so it gets the same treatment.
     *
     * ⭐⭐ This is why time-aware assignment history is NOT needed. `currentVehicleFor()` already
     *    means "what is he holding RIGHT NOW", so recording its answer at the moment of the
     *    reading captures the time implicitly — without touching `vehicleForDay`'s contract,
     *    which eight surfaces depend on.
     *
     * ⚠ Returns [] when the columns are not migrated yet, so the code is safe to upload before
     *   the SQL: nothing is stamped, every reader falls back to the old derivation.
     * ⚠ Returns [] rather than a NULL stamp when the registry cannot answer. NULL means
     *   "derive it" and that is the correct, unchanged behaviour — writing a guessed stamp would
     *   freeze a guess into a column that exists to hold a recorded fact.
     *
     * @param  string[] $which  any of 'meter_start', 'meter_end', 'meter_home'
     */
    private function meterStampFields(int $userId, array $which, array $values = []): array
    {
        static $hasCols = null;
        try {
            if ($hasCols === null) {
                $hasCols = \Illuminate\Support\Facades\Schema::hasColumn(
                    't_ops_attendance', 'meter_start_vehicle_id'
                );
            }
            if (!$hasCols) return [];

            $vid = (new \App\Services\Riders\VehicleResolver())->currentVehicleFor($userId);
            if (!$vid) return [];

            // ⭐⭐ DON'T STAMP A READING ONTO A MACHINE IT CANNOT BE OF (Aug-22 2026).
            //
            // ⚠⚠ THE OPERATIONAL HOLE THIS CLOSES. The flow assumes the van is released BEFORE the
            //    rider records his closing meter. If a manager forgets, he types his OWN bike's
            //    6,606 while the registry still says he holds the van — and we would freeze that
            //    number onto a machine whose odometer reads ~73,800, turning a recoverable
            //    mistake into a recorded "fact" that Rule P can no longer overrule.
            //
            // ⭐ So the value is checked against the machine's own spine (the same evidence Rule P
            //   uses) before it is stamped. Implausible → leave it UNSTAMPED, which means "derive
            //   it", which is exactly the honest answer and keeps every existing protection.
            //   Logged, because a manager forgot a step and somebody should be able to see that.
            try {
                $val = null;
                foreach (['meter_start', 'meter_end', 'meter_home'] as $c) {
                    if (isset($values[$c]) && (int) $values[$c] > 0) { $val = (int) $values[$c]; break; }
                }
                if ($val !== null
                    && !(new \App\Services\Riders\VehicleService())->readingPlausibleFor((int) $vid, $val)) {

                    // ⭐⭐ SECOND CHANCE — ASK HIS OWN MACHINES (Aug-27 2026).
                    //
                    // Refusing the stamp was the right call and only half the answer. The
                    // reading is not nonsense; it is simply not of the machine the registry
                    // says he is holding — the everyday case being a rider who arrives on
                    // his own bike while the van is still assigned to him. Leaving it
                    // UNSTAMPED means the day is half-labelled, which then defeats the
                    // split-day detection and lets the claim guess its machine from the
                    // date. Prod carries exactly such a row (22-Aug: start stamped to the
                    // own bike, close stamped to nothing).
                    //
                    // ⚠ Only when EXACTLY ONE of his own machines can own the reading.
                    //   Ambiguity stays unstamped — a wrong stamp outranks every derivation
                    //   that would otherwise have caught it, so silence beats a guess.
                    $alt = [];
                    try {
                        $svc = new \App\Services\Riders\VehicleService();
                        foreach ((new \App\Services\Riders\RiderDayLegs())->ownMachineIdsFor($userId) as $ownId) {
                            if ((int) $ownId === (int) $vid) continue;
                            if ($svc->readingPlausibleFor((int) $ownId, $val)) $alt[] = (int) $ownId;
                        }
                    } catch (\Throwable $altErr) { $alt = []; }

                    if (count($alt) !== 1) {
                        \Log::warning('Meter stamp skipped — reading implausible for the held machine', [
                            'user_id' => $userId, 'vehicle_id' => (int) $vid, 'reading' => $val,
                            'own_candidates' => count($alt),
                        ]);
                        return [];
                    }

                    \Log::info('Meter stamped to the rider\'s own machine instead of the held one', [
                        'user_id' => $userId, 'held' => (int) $vid, 'stamped' => $alt[0], 'reading' => $val,
                    ]);
                    $vid = $alt[0];
                }
            } catch (\Throwable $e) { /* plausibility is a safety net, never a gate */ }

            $out = [];
            foreach ($which as $col) {
                if (in_array($col, ['meter_start', 'meter_end', 'meter_home'], true)) {
                    $out[$col . '_vehicle_id'] = (int) $vid;
                }
            }
            return $out;
        } catch (\Throwable $e) {
            // A stamp is an improvement, never a precondition — a reading must still save.
            \Log::warning('meterStampFields failed (non-fatal)', [
                'user_id' => $userId, 'error' => $e->getMessage(),
            ]);
            return [];
        }
    }

    /**
     * ⚠ MOVED to `VehicleResolver::holdsCompanyMachineNow` (Aug-22 2026) and kept here only as a
     *   thin delegate, so the four call sites in this controller keep working unchanged. The body
     *   had to move because `HomeJourneyService::openEscalations()` needs the SAME question and
     *   could not reach a private controller method — so the escalation sweep shipped with no
     *   guard and kept pushing "hasn't recorded his bike meter" at a rider who had handed the
     *   machine back. One definition, five callers; do not re-inline it.
     */
    private function holdsCompanyMachineNow(int $userId): ?bool
    {
        return (new \App\Services\Riders\VehicleResolver())->holdsCompanyMachineNow($userId);
    }

    private function armHomeJourney(int $userId, int $attendanceId, $lat, $lng, string $today): ?array
    {
        // ⭐ Holds-NOW guard: a rider who gave his machine up at lunch must not be
        //   armed for its meter at 9 pm. Null (registry silent) falls through to
        //   the date-scoped pin check — exactly the old behaviour.
        if ($this->holdsCompanyMachineNow($userId) === false) {
            return null;
        }
        $hj = new \App\Services\Riders\HomeJourneyService();
        $home = $hj->riderHomePin($userId);
        if (!$home) {
            return null; // not a company-bike rider, or no home pin set → no journey
        }
        if ($lat === null || $lng === null || !is_numeric($lat) || !is_numeric($lng)) {
            // No checkout GPS → can't time the ride. Still tell the app a home meter is expected,
            // but with no timer (the rider records at home; manager can review distance later).
            return ['armed' => false, 'no_gps' => true, 'home_lat' => $home['lat'],
                    'home_lng' => $home['lng'], 'home_radius_m' => $home['radius_m']];
        }

        $lat = (float) $lat; $lng = (float) $lng;
        $eta = null;
        try { $eta = $this->getEtaFromGoogleMaps($lat, $lng, $home['lat'], $home['lng']); } catch (\Throwable $e) { $eta = null; }
        if (!$eta) {
            try { $eta = $this->getEtaFromOpenRouteService($lat, $lng, $home['lat'], $home['lng']); } catch (\Throwable $e) { $eta = null; }
        }
        $distanceKm = $eta['distance_km'] ?? null;
        $etaMin = isset($eta['duration_minutes']) ? (int) $eta['duration_minutes'] : null;
        if ($etaMin === null) {
            // Straight-line fallback: assume ~25 km/h city riding, floor 5 min.
            $meters = $this->haversineDistance($lat, $lng, $home['lat'], $home['lng']);
            $distanceKm = round($meters / 1000, 1);
            $etaMin = (int) max(5, round(($distanceKm / 25) * 60));
        }
        $buffer = (int) $hj->config('HOME_ETA_BUFFER_MIN', 15);
        $expectedBy = now()->addMinutes($etaMin + $buffer);

        \DB::table('t_ops_attendance')->where('id', $attendanceId)->update([
            'home_eta_min'     => $etaMin,
            'home_distance_km' => $distanceKm,
            'home_expected_by' => $expectedBy,
            'updated_at'       => now(),
        ]);

        return [
            'armed'        => true,
            'eta_min'      => $etaMin,
            'distance_km'  => $distanceKm,
            'expected_by'  => $expectedBy->format('Y-m-d H:i:s'),
            'buffer_min'   => $buffer,
            'home_lat'     => $home['lat'],
            'home_lng'     => $home['lng'],
            'home_radius_m'=> $home['radius_m'],
        ];
    }

    /**
     * U4 — rider records his home meter at the end of the going-home journey. Enforces the time gate:
     * allowed while the window is open (on time) OR while a manager unlock is active; DENIED (423)
     * when late_locked. Stores meter_home (+ picture) and mirrors it to meter_end (the day-closing
     * reading, so overnight/meter math needs no change). arrival_source = geofence when the submit
     * GPS confirms he's at the home pin, else manual.
     */
    public function submitHomeMeter(Request $request)
    {
        try {
            $user = Auth::user();
            $request->validate([
                'meter_home' => 'required|integer|min:0',
                'meter_picture' => 'nullable|image|max:5120',
                'latitude' => 'nullable|numeric|between:-90,90',
                'longitude' => 'nullable|numeric|between:-180,180',
                'accuracy' => 'nullable|numeric',   // fix accuracy → benefit-of-the-doubt at the fence
            ]);
            return $this->processHomeMeterSubmission(
                $user,
                (int) $request->meter_home,
                $request->hasFile('meter_picture') ? $request->file('meter_picture') : null,
                $request->input('latitude'),
                $request->input('longitude'),
                $request->input('accuracy')
            );
        } catch (\Illuminate\Validation\ValidationException $ve) {
            return response()->json(['success' => false, 'message' => $ve->validator->errors()->first()], 422);
        } catch (\Throwable $e) {
            \Log::error('submitHomeMeter failed', ['error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Could not record the home meter.'], 500);
        }
    }

    /**
     * U4 — THE single day-closing meter flow for a company-bike rider. Every rider-facing door
     * (the Ride-home card via submitHomeMeter, AND the legacy End tile / old APKs via
     * uploadMeterPicture) funnels here, so the time gate, the location gate and the manager
     * valve can never be sidestepped by picking a different button. Writes meter_home and
     * mirrors meter_end in the same update.
     */
    private function processHomeMeterSubmission($user, int $meterHome, $pictureFile, $lat, $lng, $accuracy = null)
    {
            // ⭐ 16-Sep: the home fence and the home-meter stamp must never be judged against a
            //   fix outside Pakistan. No fix ⇒ the existing "server falls back to the home pin".
            if ($lat !== null && $lng !== null && !LocationService::isPlausibleFix($lat, $lng)) {
                \Log::warning('📍 HOME METER: fix outside Pakistan (phantom) — ignored', ['user_id' => $user->id, 'lat' => $lat, 'lng' => $lng, 'accuracy' => $accuracy]);
                $this->recordLocationFailureRow((int) $user->id, 'phantom_fix', 'home_meter', sprintf('phantom %s,%s acc=%s', $lat, $lng, $accuracy ?? '?'), $lat, $lng);
                $lat = null; $lng = null; $accuracy = null;
            }
            $today = now()->format('Y-m-d');
            $hj = new \App\Services\Riders\HomeJourneyService();
            // Resolve the OPEN journey row first (handles a checkout that crossed midnight — the
            // journey lives on yesterday's row); fall back to today's row for a same-day no-GPS arm.
            $att = $hj->openJourneyRow($user->id);
            if (!$att) {
                $att = \DB::table('t_ops_attendance')->where('user_id', $user->id)->whereDate('attendance_date', $today)->first();
            }
            if (!$att) {
                return response()->json(['success' => false, 'message' => 'No attendance record for today.'], 404);
            }

            $home = $hj->riderHomePin($user->id);
            if (!$home) {
                return response()->json(['success' => false, 'message' => 'No home location is set for you — ask your manager.'], 400);
            }
            if (!empty($att->meter_home)) {
                return response()->json(['success' => false, 'message' => 'Home meter already recorded today.'], 400);
            }

            // Is he AT HOME right now? (GPS in the request vs the home pin.)
            // ⭐ Accuracy slack (owner-approved Jul-28): a fix is only trustworthy to its OWN
            // accuracy, so let the error bar reach the fence before calling him "not at home" —
            // the SAME min(accuracy, COARSE_FIX_M) rule the checkout gate and the morning
            // start-meter verdict already apply. This gate was the only sibling without it:
            // indoors (where the bike parks) phones fall back to ±100–300 m network fixes, and
            // a rider standing at his own house could read "380 m from home". Capped at
            // COARSE_FIX_M so a wildly bad fix can never buy a pass; no accuracy sent (current
            // APKs) ⇒ zero slack ⇒ exactly today's behaviour until the new APK ships it.
            $atHomeNow = false;
            $distM = null;
            if ($lat !== null && $lat !== '' && $lng !== null && $lng !== '' && is_numeric($lat) && is_numeric($lng)) {
                $homeSlack = ($accuracy !== null && is_numeric($accuracy))
                    ? min((float) $accuracy, (float) $this->attnConfig('COARSE_FIX_M', 150))
                    : 0.0;
                $distM = $this->haversineDistance((float) $lat, (float) $lng, $home['lat'], $home['lng']);
                $atHomeNow = ($distM - $homeSlack) <= $home['radius_m'];
            }
            // Arrival already proven by the live-GPS geofence (heartbeat stamped it)?
            $arrivalStamped = !empty($att->home_arrived_at);
            // Manager bypass active?
            $unlockActive = !empty($att->home_meter_unlock_until)
                && strtotime((string) $att->home_meter_unlock_until) >= time();

            // TIME gate (only when a timer was armed; a no-GPS arm has no timer).
            if (!empty($att->home_expected_by)) {
                $can = $hj->canRiderSubmit($att);
                if (!$can['ok']) {
                    if ($can['reason'] === 'late_locked') {
                        return response()->json([
                            'success' => false, 'home_locked' => true,
                            'message' => 'You reached home late — ask your manager to unlock meter entry.',
                        ], 423);
                    }
                    return response()->json(['success' => false, 'message' => 'Home meter cannot be recorded now.'], 400);
                }
            }

            // LOCATION gate: the submission must be AT the home pin (live GPS now, or the
            // heartbeat already proved arrival) — unless the manager unlocked (bypass).
            // This is the owner's rule: time AND location stop the rider; the manager is the valve.
            if (!$atHomeNow && !$arrivalStamped && !$unlockActive) {
                return response()->json([
                    'success' => false, 'home_not_at_home' => true,
                    'message' => $distM !== null
                        ? 'You are ' . ($distM >= 1000 ? round($distM / 1000, 1) . ' km' : (int) $distM . ' m') . ' from your saved home location — get home to record the meter, or call your manager.'
                        : 'Your location is off — turn on GPS at home to record the meter, or call your manager.',
                ], 423);
            }

            $picPath = null;
            if ($pictureFile) {
                $picPath = $this->storeMeterPicture($pictureFile, $user->id, 'home');
            }

            $source = $atHomeNow ? 'geofence' : ($arrivalStamped ? ($att->home_arrival_source ?: 'geofence') : 'manual');
            $upd = [
                'meter_home'  => $meterHome,
                'meter_end'   => $meterHome, // day-closing reading for bike riders
                'updated_at'  => now(),
            ];
            // ⭐ STEP C — both, because meter_end here is a MIRROR of meter_home: same reading,
            //   same machine, so they must never be able to carry different stamps.
            $upd = array_merge($upd, $this->meterStampFields(
                $user->id, ['meter_home', 'meter_end'], ['meter_home' => (int) $meterHome]));
            // Keep the EARLIEST arrival stamp (heartbeat's true arrival time beats typing time).
            if (!$arrivalStamped) {
                $upd['home_arrived_at'] = now();
                $upd['home_arrival_source'] = $source;
            }
            // Exact meter-entry moment for the attendance-page timeline (guarded — column is wave-3).
            if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_meter_recorded_at')) {
                $upd['home_meter_recorded_at'] = now();
            }
            // Mirror the photo to picture_end too — the home photo IS the day-closing (meter_end)
            // photo for a bike rider, just as meter_home mirrors meter_end above. Every End-meter
            // surface (web row camera icon, rider-app preview/history, mobile store view) keys off
            // picture_end; without this mirror the reading shows but the photo icon greys out and
            // the rider can't see the photo he just took (only the details modal, which reads
            // picture_home ?? picture_end, showed it). Non-bike checkout photos are unaffected.
            if ($picPath) {
                $upd['picture_home'] = $picPath;
                $upd['picture_end']  = $picPath;
            }
            \DB::table('t_ops_attendance')->where('id', $att->id)->update($upd);

            return response()->json([
                'success' => true,
                'message' => 'Home meter recorded — thank you.',
                'source' => $source,
                'meter_home' => $meterHome,
            ]);
    }

    /**
     * ⚠️ DEPRECATED (never shipped in an APK) — U5 morning start meter, strict at-home variant.
     * The "Start your day" card now goes through the ONE unified door instead:
     * uploadMeterPicture(type=start), which handles continuity, source-follows-GPS
     * ('home'/'checkin'), and ALWAYS arms the ride-in timer (origin = live GPS, else the home
     * pin). Kept only so the /attendance/home-start-meter route keeps answering; do NOT add
     * behavior here — remove route + method once the U5 APK is fully rolled out.
     */
    public function submitHomeStartMeter(Request $request)
    {
        try {
            $user = Auth::user();
            $request->validate([
                'meter_start' => 'required|integer|min:0',
                'meter_picture' => 'nullable|image|max:5120',
                'latitude' => 'nullable|numeric|between:-90,90',
                'longitude' => 'nullable|numeric|between:-180,180',
                'confirm_gap' => 'nullable|boolean',
            ]);
            if (!\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'work_expected_by')) {
                return response()->json(['success' => false, 'message' => 'Morning-start is not enabled yet (run the wave-4 SQL).'], 422);
            }
            $today = now()->format('Y-m-d');
            $wj = new \App\Services\Riders\WorkJourneyService();
            $home = $wj->riderHomePin($user->id);
            if (!$home) {
                return response()->json(['success' => false, 'message' => 'No home location is set for you — ask your manager.'], 400);
            }

            $existing = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)->whereDate('attendance_date', $today)->first();
            if ($existing && $existing->login_time) {
                return response()->json(['success' => false, 'message' => 'You are already checked in — record the start meter from the Attendance screen.'], 400);
            }
            if ($existing && $existing->meter_start !== null && $existing->meter_start !== '') {
                return response()->json(['success' => false, 'message' => 'Start meter already recorded today.'], 400);
            }

            // LOCATION gate (owner's rule): the HOME start must be GPS-proven at the home pin.
            if (!$request->filled('latitude') || !$request->filled('longitude')) {
                return response()->json([
                    'success' => false, 'home_not_at_home' => true,
                    'message' => 'Turn on GPS at home to record the start meter — or record it at the office when you arrive.',
                ], 423);
            }
            $distM = $this->haversineDistance((float) $request->latitude, (float) $request->longitude, $home['lat'], $home['lng']);
            if ($distM > $home['radius_m']) {
                return response()->json([
                    'success' => false, 'home_not_at_home' => true,
                    'message' => 'You are ' . ($distM >= 1000 ? round($distM / 1000, 1) . ' km' : (int) $distM . ' m')
                        . ' from your saved home location — the start meter is recorded at home.',
                ], 423);
            }

            // CONTINUITY gate: morning reading vs the last closing meter (bike slept at home).
            $meterStart = (int) $request->meter_start;
            // ⭐ PHASE D: keyed to the machine he is actually on (see continuityBaseline).
            $prev = $wj->continuityBaseline($user->id, $today);
            if ($prev !== null) {
                $gap = $meterStart - $prev['value'];
                if (abs($gap) > $wj->continuityKm() && !$request->boolean('confirm_gap')) {
                    return response()->json([
                        'success' => false,
                        'needs_confirm' => true,
                        'gap_km' => $gap,
                        'prev_value' => $prev['value'],
                        'prev_date' => $prev['date'],
                        // ⭐ Sep-30: Roman Urdu, and says when it counts as off-duty.
                        'message' => $wj->continuityPrompt((int) $user->id, $prev, (int) $gap, $today),
                    ]);
                }
            }

            $picPath = null;
            if ($request->hasFile('meter_picture')) {
                $picPath = $this->storeMeterPicture($request->file('meter_picture'), $user->id, 'checkin');
            }

            // Write the reading on today's row (creating it WITHOUT login_time — checkIn()
            // updates such a row in place, verified behaviour).
            $fields = [
                'meter_start' => $meterStart,
                'meter_start_source' => 'home',
                'meter_start_recorded_at' => now(),
                'updated_at' => now(),
            ];
            // ⭐ STEP C — the morning reading is of the machine that slept at his house.
            $fields = array_merge($fields, $this->meterStampFields(
                $user->id, ['meter_start'], ['meter_start' => (int) $meterStart]));
            if ($picPath) { $fields['picture_start'] = $picPath; }
            if ($existing) {
                \DB::table('t_ops_attendance')->where('id', $existing->id)->update($fields);
                $attId = (int) $existing->id;
            } else {
                $attId = (int) \DB::table('t_ops_attendance')->insertGetId(array_merge($fields, [
                    'user_id' => $user->id,
                    'attendance_date' => $today,
                    'created_at' => now(),
                ]));
            }

            // Arm the ride-to-work timer (ETA home pin → today's shift office + buffer).
            // NON-FATAL: an ETA failure records the meter without a deadline.
            $journey = null;
            try {
                $journey = $this->armWorkJourney($user->id, $attId, $home['lat'], $home['lng']);
            } catch (\Throwable $e) {
                \Log::warning('armWorkJourney failed (non-fatal)', ['user_id' => $user->id, 'error' => $e->getMessage()]);
            }

            return response()->json([
                'success' => true,
                'message' => 'Start meter recorded — ride safe.',
                'meter_start' => $meterStart,
                'work_journey' => $journey,
            ]);
        } catch (\Illuminate\Validation\ValidationException $ve) {
            return response()->json(['success' => false, 'message' => $ve->validator->errors()->first()], 422);
        } catch (\Throwable $e) {
            \Log::error('submitHomeStartMeter failed', ['error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Could not record the start meter.'], 500);
        }
    }

    /**
     * U5 — arm the morning ride-to-work deadline: ETA (home → today's shift office) + buffer →
     * work_expected_by. Mirrors armHomeJourney (Google → OpenRouteService → straight-line).
     * Returns the app-card payload, or null when today's office has no usable coordinates
     * (meter stays recorded, no timer — never punitive).
     */
    private function armWorkJourney(int $userId, int $attendanceId, float $homeLat, float $homeLng): ?array
    {
        $office = $this->todayShiftLocation($userId);
        if (!$office) {
            return null;
        }
        $eta = null;
        try { $eta = $this->getEtaFromGoogleMaps($homeLat, $homeLng, $office['lat'], $office['lng']); } catch (\Throwable $e) { $eta = null; }
        if (!$eta) {
            try { $eta = $this->getEtaFromOpenRouteService($homeLat, $homeLng, $office['lat'], $office['lng']); } catch (\Throwable $e) { $eta = null; }
        }
        $distanceKm = $eta['distance_km'] ?? null;
        $etaMin = isset($eta['duration_minutes']) ? (int) $eta['duration_minutes'] : null;
        if ($etaMin === null) {
            $meters = $this->haversineDistance($homeLat, $homeLng, $office['lat'], $office['lng']);
            $distanceKm = round($meters / 1000, 1);
            $etaMin = (int) max(5, round(($distanceKm / 25) * 60)); // ~25 km/h city fallback
        }
        $buffer = (int) (new \App\Services\Riders\WorkJourneyService())->config('WORK_ETA_BUFFER_MIN', 10);
        $expectedBy = now()->addMinutes($etaMin + $buffer);

        \DB::table('t_ops_attendance')->where('id', $attendanceId)->update([
            'work_eta_min' => $etaMin,
            'work_distance_km' => $distanceKm,
            'work_expected_by' => $expectedBy,
            'updated_at' => now(),
        ]);

        return [
            'state' => 'riding',
            'eta_min' => $etaMin,
            'distance_km' => $distanceKm,
            'expected_by' => $expectedBy->format('Y-m-d H:i:s'),
            'buffer_min' => $buffer,
            'office_name' => $office['name'],
        ];
    }

    /**
     * Where must this rider be TODAY? Shift location → assignment location → primary office
     * (the same resolution getTodayAttendance shows the rider). Null when no coords anywhere.
     */
    private function todayShiftLocation(int $userId): ?array
    {
        $loc = null;
        try {
            $shift = (new \App\Services\ShiftResolutionService())->getUserShift($userId, now()->format('Y-m-d'));
            if (!empty($shift['location_id'])) {
                $loc = \DB::table('t_ops_company_locations')
                    ->where('id', $shift['location_id'])->where('is_active', 1)
                    ->select('location_name', 'latitude', 'longitude', 'radius_meters')->first();
            }
        } catch (\Throwable $e) { $loc = null; }
        if (!$loc) {
            $loc = \DB::table('t_ops_user_location_assignment as ula')
                ->join('t_ops_company_locations as loc', 'loc.id', '=', 'ula.location_id')
                ->where('ula.user_id', $userId)->where('ula.is_active', 1)->where('loc.is_active', 1)
                ->select('loc.location_name', 'loc.latitude', 'loc.longitude', 'loc.radius_meters')->first();
        }
        if (!$loc) {
            $loc = \DB::table('t_ops_company_locations')->where('is_primary', 1)->where('is_active', 1)
                ->select('location_name', 'latitude', 'longitude', 'radius_meters')->first();
        }
        if (!$loc || $loc->latitude === null || $loc->longitude === null) {
            return null;
        }
        // radius_m is additive — armWorkJourney (the original caller) ignores it; the
        // morning-meter labeller uses it to say "at office" as a measurement.
        return ['lat' => (float) $loc->latitude, 'lng' => (float) $loc->longitude, 'name' => $loc->location_name,
                'radius_m' => (float) ($loc->radius_meters ?: 300)];
    }

    /**
     * U5 — the rider's morning-journey payload for the app card. States the card needs:
     *   offer   — bike rider at the start of a day: no reading yet, not checked in
     *   riding  — home reading in, deadline armed, still within time
     *   overdue — deadline passed, not checked in yet (card turns urgent)
     * Null once checked in (the day has moved on), for non-bike riders, on off-days /
     * holidays, and on leave days (never nag someone who isn't riding in). Never throws.
     */
    private function buildWorkJourneyPayload(int $userId, $attendance, $todayLeave = null): ?array
    {
        try {
            if (!\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'work_expected_by')) {
                return null;
            }
            // ⭐⭐ R6 (owner ruling, Aug-22 2026) — HOLDS-NOW GUARD, the one the morning never
            //    learned. `armHomeJourney` and `buildHomeJourneyPayload` have both had it since
            //    Phase D — "a rider who gave his machine up at lunch must not be armed for its
            //    meter at 9 pm" — but this card gated only on home pin + leave + working day. So
            //    a rider holding NOTHING (or riding his OWN bike, whose rule is close-at-checkout,
            //    not start-at-home) was still invited to record a company-bike start meter.
            //
            //    That invitation is how a reading for the wrong machine gets created in the first
            //    place, which is the Van incident in miniature.
            //
            // ⚠⚠ `=== false` ONLY. `holdsCompanyMachineNow()` returns NULL when the registry has
            //    no opinion (rules off, tables absent, not a rider) and null MUST fall through to
            //    the old behaviour — guarding on falsy would blank this card for every rider the
            //    moment the registry went quiet.
            if ($this->holdsCompanyMachineNow($userId) === false) {
                return null;
            }
            $wj = new \App\Services\Riders\WorkJourneyService();
            if (!$wj->riderHomePin($userId)) {
                return null;
            }
            if ($attendance && $attendance->login_time) {
                return null; // checked in — morning phase over
            }
            $hasStart = $attendance && $attendance->meter_start !== null && $attendance->meter_start !== '';
            if (!$hasStart) {
                // Not started yet — only OFFER the card on a day he actually works.
                if ($todayLeave !== null) {
                    return null; // approved/pending leave today
                }
                try {
                    if (!(new \App\Services\ShiftResolutionService())->isWorkingDay($userId, now()->format('Y-m-d'))) {
                        return null; // off-day / holiday
                    }
                } catch (\Throwable $e) { /* can't resolve → keep offering (harmless) */ }
                // ⭐ PHASE D: the card previews the same baseline the gate will judge
                //   against — his machine's last reading, not his own last bike's.
                $prev = $wj->continuityBaseline($userId, now()->format('Y-m-d'));
                return [
                    'state' => 'offer',
                    'prev_meter' => $prev['value'] ?? null,
                    'prev_meter_date' => $prev['date'] ?? null,
                    'prev_meter_label' => $prev['label'] ?? null,
                    'continuity_km' => $wj->continuityKm(),
                ];
            }
            $state = $wj->deriveState($attendance); // riding | overdue | none (no timer armed)
            return [
                'state' => $state === 'overdue' ? 'overdue' : 'riding',
                'meter_start' => (int) $attendance->meter_start,
                'source' => $attendance->meter_start_source ?? null,
                'expected_by' => $attendance->work_expected_by ?? null,
                'eta_min' => ($attendance->work_eta_min ?? null) !== null ? (int) $attendance->work_eta_min : null,
                'buffer_min' => (int) $wj->config('WORK_ETA_BUFFER_MIN', 10), // so the card shows ETA + grace = deadline
                'distance_km' => ($attendance->work_distance_km ?? null) !== null ? (float) $attendance->work_distance_km : null,
                'minutes_late' => $wj->minutesLate($attendance),
            ];
        } catch (\Throwable $e) {
            return null;
        }
    }

    /**
     * Snapshot of the cash a rider is still holding against him — the exact
     * "open" amount he sees in Daily Closing. Mirrors getDailyClosing's math
     * (open + partial invoice/order_payment outstanding on his employee_cash
     * account, non-reversed) so the number ALWAYS matches what the manager sees.
     * Also returns pending settlements (cash already handed over, awaiting the
     * manager's approval) as a SEPARATE total. Returns null when he has no
     * employee_cash account or there is nothing open and nothing pending.
     *
     * @return array|null
     */
    private function getRiderCashHeld(int $userId): ?array
    {
        $account = \App\Models\FIN\AccountModel::where('user_id', $userId)
            ->where('account_category', \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH)
            ->first();
        if (!$account) {
            return null;
        }

        // Open + partial invoice/order_payment rows to his account (non-reversed).
        // "Not settled" = still owed → outstanding = amount - settled_amount.
        $rows = \App\Models\FIN\LedgerModel::whereIn('transaction_type', [
                \App\Models\FIN\LedgerModel::TYPE_INVOICE,
                \App\Models\FIN\LedgerModel::TYPE_ORDER_PAYMENT,
            ])
            ->where('to_account_id', $account->id)
            ->where('approval_status', '!=', \App\Models\FIN\LedgerModel::STATUS_REVERSED)
            ->whereIn('settlement_status', ['open', 'partial']) // exact match to getDailyClosing's open+partial
            ->with('order')
            ->orderBy('transaction_date', 'desc')
            ->get();

        // Cash he has already SUBMITTED, awaiting manager approval. The invoices
        // covered by these deposits are STILL 'open' in the ledger (they only
        // settle on approval), so they must be excluded from "cash in hand" —
        // he no longer holds that money. Same metadata convention as
        // getDailyClosing: settlement_metadata.invoice_ids lists the covered rows.
        $pending = \App\Models\FIN\LedgerModel::where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_EMPLOYEE_DEPOSIT)
            ->where('from_account_id', $account->id)
            ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_PENDING)
            ->where(function ($q) {
                $q->where('description', 'LIKE', '%Settlement%')
                  ->orWhere('description', 'LIKE', '%Partial Payment%');
            })
            ->get();
        $pendingTotal = (float) $pending->sum('amount');
        $pendingInvoiceIds = [];
        foreach ($pending as $dep) {
            $meta = $dep->settlement_metadata;
            foreach (($meta['invoice_ids'] ?? []) as $iid) {
                $pendingInvoiceIds[(int) $iid] = true;
            }
        }

        $invoices = $rows->map(function ($inv) use ($pendingInvoiceIds) {
            return [
                'id' => $inv->id,
                'order_number' => $inv->order ? $inv->order->order_number : 'N/A',
                'customer_name' => $inv->order ? $inv->order->customer_name : null,
                'date' => $inv->transaction_date ? $inv->transaction_date->format('Y-m-d') : null,
                'amount' => (float) $inv->amount,
                'settled_amount' => (float) ($inv->settled_amount ?? 0),
                'outstanding' => (float) ($inv->amount - ($inv->settled_amount ?? 0)),
                'is_pending_approval' => isset($pendingInvoiceIds[(int) $inv->id]),
            ];
        })->values();

        $totalOutstanding = (float) $rows->sum(function ($inv) {
            return $inv->amount - ($inv->settled_amount ?? 0);
        });

        // NET cash in hand = open invoices NOT covered by a pending submission.
        $netCashInHand = (float) $rows->sum(function ($inv) use ($pendingInvoiceIds) {
            if (isset($pendingInvoiceIds[(int) $inv->id])) {
                return 0;
            }
            return $inv->amount - ($inv->settled_amount ?? 0);
        });
        $netInvoiceCount = $rows->filter(fn ($inv) => !isset($pendingInvoiceIds[(int) $inv->id]))->count();

        // Nothing open and nothing pending → null (mobile skips the popup).
        if ($totalOutstanding <= 0 && $pendingTotal <= 0) {
            return null;
        }

        return [
            'account_id' => $account->id,
            'total_outstanding' => $totalOutstanding,
            'invoice_count' => $rows->count(),
            'net_cash_in_hand' => $netCashInHand,
            'net_invoice_count' => $netInvoiceCount,
            'invoices' => $invoices,
            'pending_settlement_amount' => $pendingTotal,
            'pending_settlement_count' => $pending->count(),
        ];
    }

    /**
     * Rider confirms (at check-out) the cash amount he is holding. Records the
     * confirmed figure + timestamp on today's attendance row for the manager.
     * Purely a record — no ledger/settlement impact. Idempotent per day.
     */
    public function confirmCash(Request $request)
    {
        try {
            $user = Auth::user();
            $today = now()->format('Y-m-d');

            $validated = $request->validate([
                'amount' => 'required|numeric|min:0',
                'status' => 'nullable|in:confirmed,issue',
            ]);
            $status = $validated['status'] ?? 'confirmed';

            // ⭐ Past-midnight sibling (1 Sep 2026). This popup is shown by the app IMMEDIATELY
            //   after a successful checkout, so on a shift that rolled past 00:00 the money it
            //   is confirming belongs to YESTERDAY's row — the one just closed. Asking the
            //   today-only question 404'd it every time. `currentOrJustClosedRow` is used rather
            //   than the open-row finder precisely because the row now HAS a logout_time.
            $attendance = (new \App\Services\Riders\AttendanceDay())->currentOrJustClosedRow($user->id);

            if (!$attendance) {
                return response()->json(['success' => false, 'message' => 'No attendance record for today'], 404);
            }

            \DB::table('t_ops_attendance')
                ->where('id', $attendance->id)
                ->update([
                    'cash_confirmed_amount' => $validated['amount'],
                    'cash_confirmed_at' => now(),
                    'cash_confirm_status' => $status,
                    'updated_at' => now(),
                ]);

            return response()->json([
                'success' => true,
                'message' => $status === 'issue' ? 'Issue reported to the manager' : 'Cash amount confirmed',
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to confirm cash held', ['error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to confirm: ' . $e->getMessage()], 500);
        }
    }

    /**
     * 🏦 The TILL KEEPER's own count of a company till (mobile door, Sep-2026).
     *
     * Sibling of confirmCash() above, deliberately separate: that one is about the rider's
     * OWN float and lives on his attendance row; this one is about a company account, and it
     * needs a seal (`last_ledger_id`) the attendance row has no place for. Same charter
     * though — a record, never money.
     *
     * The web door is HubController::tillCount. Both land in TillCountService::record so the
     * seal can only ever be taken one way.
     */
    public function tillCount(Request $request)
    {
        try {
            $user = Auth::user();

            $validated = $request->validate([
                'account_id'     => 'required|integer',
                'counted_amount' => 'required|numeric|min:0|max:99999999',
                'note'           => 'nullable|string|max:200',
                'attendance_id'  => 'nullable|integer',
            ]);

            $tills = app(\App\Services\FIN\TillCountService::class);

            // ⚠ Authorisation is the keeper tag on THIS account, re-checked server-side. The
            // app only ever offers the account the server named, but an app is not a gate.
            if (!$tills->isKeeper((int) $user->id, (int) $validated['account_id'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Only the person who holds this till can count it.',
                ], 403);
            }

            $account = \App\Models\FIN\AccountModel::find($validated['account_id']);
            if (!$account) {
                return response()->json(['success' => false, 'message' => 'Account not found'], 404);
            }

            $count = $tills->record(
                $account,
                (int) $user->id,
                (float) $validated['counted_amount'],
                \App\Models\FIN\CashCountModel::SOURCE_CHECKOUT,
                $validated['attendance_id'] ?? null,
                $validated['note'] ?? null
            );

            return response()->json([
                'success'    => true,
                'matched'    => $count->matches(),
                'difference' => (float) $count->difference,
                'system'     => (float) $count->system_balance,
                'counted'    => (float) $count->counted_amount,
                'message'    => $count->matches()
                    ? 'Ginti mil gayi — Rs. ' . number_format((float) $count->counted_amount, 0)
                    : ($count->shortBy() > 0
                        ? 'Record ho gaya. Kitaab se Rs. ' . number_format(abs($count->shortBy()), 0) . ' KAM hai.'
                        : 'Record ho gaya. Kitaab se Rs. ' . number_format(abs($count->shortBy()), 0) . ' ZYADA hai.'),
            ]);
        } catch (\Illuminate\Validation\ValidationException $ve) {
            throw $ve;
        } catch (\Exception $e) {
            \Log::error('Failed to record till count', ['error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Could not record the count'], 500);
        }
    }

    /**
     * Process check-out location data (no distance calculation needed)
     * 
     * @param Request $request
     * @param int $userId
     * @return array|null Location data or null if not provided
     */
    private function processCheckoutLocation(Request $request, int $userId)
    {
        $latitude = $request->input('latitude');
        $longitude = $request->input('longitude');

        if (is_null($latitude) || is_null($longitude)) {
            \Log::info('Check-out without location', [
                'user_id' => $userId,
                'date' => now()->toDateString()
            ]);
            return null;
        }

        // Validate coordinates
        if (!LocationService::isValidCoordinates($latitude, $longitude)) {
            \Log::error('Invalid GPS coordinates on check-out', [
                'user_id' => $userId,
                'latitude' => $latitude,
                'longitude' => $longitude
            ]);
            return null;
        }

        // For check-out: Just capture location, no distance calculation or remote flag
        return [
            'checkout_latitude' => $latitude,
            'checkout_longitude' => $longitude,
            'checkout_accuracy' => $request->input('accuracy'),
            'checkout_location_captured_at' => now(),
        ];
    }

    /**
     * ⭐ Calculate and store road distance for attendance
     * Called automatically on checkout or manually via button
     * 
     * @param int $userId
     * @param string $date YYYY-MM-DD
     * @param int|null $attendanceId Optional - if not provided, will look up
     * @return array|null Result with road_distance_km or null if failed
     */
    private function calculateAndStoreRoadDistance(int $userId, string $date, ?int $attendanceId = null): ?array
    {
        // Get attendance record if not provided
        if (!$attendanceId) {
            $attendance = \DB::table('t_ops_attendance')
                ->where('user_id', $userId)
                ->whereDate('attendance_date', $date)
                ->first();
            if (!$attendance) {
                return null;
            }
            $attendanceId = $attendance->id;
        }
        
        // Get all GPS readings for the day
        $readings = \DB::table('t_ops_rider_location')
            ->where('user_id', $userId)
            ->whereDate('captured_at', $date)
            ->where('accuracy', '<=', 100)
            ->orderBy('captured_at')
            ->select('latitude', 'longitude', 'accuracy', 'captured_at')
            ->get();
        
        // Not enough readings
        if ($readings->count() < 2) {
            \DB::table('t_ops_attendance')
                ->where('id', $attendanceId)
                ->update([
                    'road_distance_source' => 'insufficient_data',
                    'road_distance_calculated_at' => now(),
                    'gps_readings_used' => $readings->count(),
                ]);
            return [
                'road_distance_km' => null,
                'source' => 'insufficient_data',
                'readings_count' => $readings->count(),
            ];
        }
        
        // Calculate straight-line distance first
        $straightResult = $this->calculateGpsDistanceFromReadings($readings->toArray());
        
        // Skip API if rider barely moved (< 100m) - likely stationary
        if ($straightResult['distance'] === null || $straightResult['distance'] < 0.1) {
            \DB::table('t_ops_attendance')
                ->where('id', $attendanceId)
                ->update([
                    'road_distance_source' => 'skipped_stationary',
                    'road_distance_calculated_at' => now(),
                    'gps_straight_distance_km' => $straightResult['distance'],
                    'gps_readings_used' => $readings->count(),
                ]);
            return [
                'road_distance_km' => null,
                'straight_distance_km' => $straightResult['distance'],
                'source' => 'skipped_stationary',
                'readings_count' => $readings->count(),
            ];
        }
        
        // Sample readings for API call (max 25 waypoints)
        $sampledReadings = $this->sampleGpsReadings($readings->toArray(), 25);
        
        if (count($sampledReadings) < 2) {
            \DB::table('t_ops_attendance')
                ->where('id', $attendanceId)
                ->update([
                    'road_distance_source' => 'calculated',
                    'road_distance_calculated_at' => now(),
                    'gps_straight_distance_km' => $straightResult['distance'],
                    'gps_readings_used' => $readings->count(),
                ]);
            return [
                'road_distance_km' => null,
                'straight_distance_km' => $straightResult['distance'],
                'source' => 'calculated',
                'readings_count' => $readings->count(),
            ];
        }
        
        // Call OpenRouteService for road distance
        $roadDistance = $this->callOpenRouteService($sampledReadings);
        
        // Store result
        $updateData = [
            'road_distance_calculated_at' => now(),
            'gps_straight_distance_km' => $straightResult['distance'],
            'gps_readings_used' => $readings->count(),
        ];
        
        if ($roadDistance !== null) {
            $updateData['road_distance_km'] = round($roadDistance, 2);
            $updateData['road_distance_source'] = 'openrouteservice';
        } else {
            // API failed - store straight-line as fallback
            $updateData['road_distance_km'] = $straightResult['distance'];
            $updateData['road_distance_source'] = 'calculated';
        }
        
        \DB::table('t_ops_attendance')
            ->where('id', $attendanceId)
            ->update($updateData);
        
        return [
            'road_distance_km' => $updateData['road_distance_km'],
            'straight_distance_km' => $straightResult['distance'],
            'source' => $updateData['road_distance_source'],
            'readings_count' => $readings->count(),
            'sampled_points' => count($sampledReadings),
        ];
    }

    /**
     * ⭐ LOCATION TRACKING: Record rider's location heartbeat
     * Called every 5 minutes from mobile app when rider is checked in
     * Also performs daily cleanup of old location data (once per day)
     */
    public function locationHeartbeat(Request $request)
    {
        try {
            $user = Auth::user();
            $today = now()->format('Y-m-d');

            // Validate rider is checked in today (has login_time but no logout_time)
            $attendance = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)
                ->whereDate('attendance_date', $today)
                ->whereNotNull('login_time')
                ->whereNull('logout_time')
                ->first();

            // ⭐ U4 — GOING-HOME phase: a company-bike rider who checked OUT with an armed home
            // journey keeps sending heartbeats until his home meter is in (so the ride home is
            // tracked and arrival auto-detects). Accept those too, bounded to expected_by + 60 min
            // so the client's not_on_duty self-stop still kills a forgotten service afterwards.
            $homePhase = false;
            if (!$attendance) {
                try {
                    $hjSvcHb = new \App\Services\Riders\HomeJourneyService();
                    // Cross-midnight safe: openJourneyRow spans today+yesterday.
                    $hjAtt = $hjSvcHb->openJourneyRow($user->id);
                    if ($hjAtt && time() <= strtotime((string) $hjAtt->home_expected_by) + 3600) {
                        $attendance = $hjAtt;
                        $homePhase = true;
                    } elseif (!$hjAtt && \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_expected_by')
                        && $hjSvcHb->riderHomePin($user->id)) {
                        // NO-TIMER arm (checkout had no GPS → home_expected_by was never set): still a
                        // live going-home phase. Accept heartbeats for up to 3h after checkout so the
                        // geofence can stamp his arrival and the ride stays tracked.
                        $noTimer = \DB::table('t_ops_attendance')
                            ->where('user_id', $user->id)
                            ->whereIn('attendance_date', [$today, now()->subDay()->format('Y-m-d')])
                            ->whereNotNull('logout_time')
                            ->whereNull('home_expected_by')
                            ->whereNull('meter_home')
                            ->orderByDesc('attendance_date')
                            ->first();
                        if ($noTimer) {
                            $coTs = strtotime(substr((string) $noTimer->attendance_date, 0, 10) . ' ' . $noTimer->logout_time);
                            if ($coTs && time() <= $coTs + 3 * 3600) {
                                $attendance = $noTimer;
                                $homePhase = true;
                            }
                        }
                    }
                } catch (\Throwable $e) { /* fall through to the normal rejection */ }
            }

            // ⭐ U5 — RIDE-IN phase (mirror of the going-home branch above): a company-bike
            // rider who has recorded his start meter but has NOT checked in yet is on the road
            // for us, so his heartbeats count. Without this the morning commute is the only leg
            // of the day with no trail at all — which is exactly why Waseem's disputed 11:51
            // position (Jul-25) could never be checked against anything.
            // Bounded to work_expected_by + 60 min (same rule the phone applies), so a forgotten
            // service on a rider who never turns up cannot keep uploading all day.
            $workPhase = false;
            if (!$attendance) {
                try {
                    if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'work_expected_by')) {
                        $wjAtt = \DB::table('t_ops_attendance')
                            ->where('user_id', $user->id)
                            ->whereDate('attendance_date', $today)
                            ->whereNull('login_time')          // not checked in yet = still riding in
                            ->whereNotNull('meter_start_recorded_at')  // journey actually armed
                            ->whereNotNull('work_expected_by')
                            ->first();
                        if ($wjAtt && time() <= strtotime((string) $wjAtt->work_expected_by) + 3600) {
                            $attendance = $wjAtt;
                            $workPhase = true;
                        }
                    }
                } catch (\Throwable $e) { /* fall through to the normal rejection */ }
            }

            // ⭐ Past-midnight ON-DUTY (owner-approved Jul-28): a shift that runs past 00:00
            //    lives on YESTERDAY's row, so heartbeats died at midnight ("not_on_duty") and
            //    the app self-stopped GPS mid-shift — exactly when the checkout-retry card and
            //    the delivery trail need it. Before 06:00, an open yesterday shift counts as
            //    on duty. Bound + open-row condition come from AttendanceDay, like every door.
            //    (Distinct from the U4 home phase above, which requires logout SET.)
            if (!$attendance) {
                try {
                    $midShift = (new \App\Services\Riders\AttendanceDay())->openPastMidnightRow($user->id);
                    if ($midShift) {
                        $attendance = $midShift;
                    }
                } catch (\Throwable $e) { /* fall through to the normal rejection */ }
            }

            if (!$attendance) {
                // ⭐ Log when we return 400 - helps diagnose why heartbeats stop
                $anyAttendanceToday = \DB::table('t_ops_attendance')
                    ->where('user_id', $user->id)
                    ->whereDate('attendance_date', $today)
                    ->first();
                    
                \Log::warning('📍 Heartbeat rejected - not checked in', [
                    'user_id' => $user->id,
                    'user_name' => $user->fullname,
                    'today' => $today,
                    'has_attendance_record' => $anyAttendanceToday ? 'yes' : 'no',
                    'login_time' => $anyAttendanceToday->login_time ?? null,
                    'logout_time' => $anyAttendanceToday->logout_time ?? null,
                    'source' => $request->input('source'),
                ]);
                
                return response()->json([
                    'success' => false,
                    'message' => 'Not checked in or already checked out',
                    // ⭐ Explicit code so the app can distinguish a genuine "off duty"
                    // rejection from a transient error and self-stop tracking after a
                    // sustained streak (kills the forgotten-checkout "zombie" service).
                    'code' => 'not_on_duty',
                ], 400);
            }

            // Validate coordinates
            $latitude = $request->input('latitude');
            $longitude = $request->input('longitude');

            if (is_null($latitude) || is_null($longitude)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Location coordinates required'
                ], 400);
            }

            if (!LocationService::isValidCoordinates($latitude, $longitude)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Invalid GPS coordinates'
                ], 400);
            }

            // Store location heartbeat
            $accuracy = $request->input('accuracy');
            $source = $request->input('source', 'heartbeat');
            
            // Ensure accuracy is a valid number or null
            if ($accuracy !== null && !is_numeric($accuracy)) {
                $accuracy = null;
            }
            
            // Truncate source to 20 chars (DB column limit)
            $sourceStr = is_string($source) ? substr($source, 0, 20) : 'heartbeat';

            /**
             * ⭐⭐ THE PHANTOM GATE (16-Sep-2026). A fix outside Pakistan never enters the location
             *    table — it is recorded as a FAILURE instead, with everything the phone told us
             *    about it, so the map stops painting riders in Beijing and the episode is still
             *    readable afterwards. Answered 200 + `stored:false`, not 4xx: every installed APK
             *    treats a non-2xx here as a network fault and retries the same lie, and the native
             *    tracker counts 400s towards stopping itself.
             * ⚠ `gps_warning` is already rendered by the current APK in three places, so the rider
             *   is told in Roman Urdu without an app update.
             */
            if (!LocationService::isPlausibleFix($latitude, $longitude)) {
                $detail = sprintf('phantom %s,%s acc=%s src=%s age=%s prov=%s mock=%s model=%s',
                    $latitude, $longitude, $accuracy ?? '?', $sourceStr,
                    $request->input('fix_age_s', '?'), $request->input('provider', '?'),
                    $request->input('mocked', '?'), $request->input('device_model', '?'));
                \Log::warning('📍 Heartbeat REFUSED — fix outside Pakistan (phantom)', ['user_id' => $user->id, 'detail' => $detail]);
                $this->recordLocationFailureRow((int) $user->id, 'phantom_fix', $sourceStr, $detail, $latitude, $longitude);
                return response()->json([
                    'success' => true, 'stored' => false, 'code' => 'phantom_fix',
                    'message' => 'Fix outside Pakistan — not stored.',
                    'gps_warning' => LocationService::phantomFixMessage(),
                ]);
            }

            /**
             * ⭐ A STALE FIX IS NOT A POSITION (16-Sep-2026). The phone now says how old the fix
             *   is. One re-sent for three hours from a cached read used to be stored with a fresh
             *   time, and the map showed it as "now". Older than 15 minutes ⇒ not stored; the map
             *   then shows the last REAL point with its true age, which is the honest picture.
             * ⚠ Only when the phone SAYS so — an older APK sends no age and is stored as before.
             */
            $fixAgeS = $request->input('fix_age_s');
            if (is_numeric($fixAgeS) && (int) $fixAgeS > 900) {
                return response()->json([
                    'success' => true, 'stored' => false, 'code' => 'stale_fix',
                    'message' => 'Fix is ' . (int) round($fixAgeS / 60) . ' min old — not stored.',
                ]);
            }

            \DB::table('t_ops_rider_location')->insert([
                'user_id' => $user->id,
                'latitude' => $latitude,
                'longitude' => $longitude,
                'accuracy' => $accuracy,
                'captured_at' => now(),
                'source' => $sourceStr,
                'created_at' => now(),
            ]);

            /**
             * 🔧⭐⭐ WORKSHOP ARRIVAL BY GEOFENCE (owner ruling, 10-Sep-2026: *"we can show at
             *    the workshop by his geofence and location since there's no dedicated button"*).
             *
             * The rider presses ONE button — "going to the workshop". Getting there is proved by
             * the heartbeat his phone already sends every five minutes, exactly as the going-home
             * arrival below is. Nothing new runs on the device.
             *
             * ⚠ NON-FATAL BY CONTRACT, like its neighbour: a failure here must never cost the
             *   rider his location update.
             * ⚠ It also back-fills `departed_at` when he forgot to press the button — a man
             *   standing at the workshop has demonstrably gone, and the board claiming otherwise
             *   while his own GPS says so is the contradiction this round exists to remove.
             */
            try {
                $wsSvc = app(\App\Services\Riders\WorkshopVisitService::class);
                $stamped = $wsSvc->stampArrival((int) $user->id, (float) $latitude, (float) $longitude);

                /**
                 * 🔧📍⭐⭐ …AND WHEN THERE IS NO PIN TO GEOFENCE AGAINST, ASK HIM ONCE
                 *    (owner ask, 11-Sep-2026).
                 *
                 * A workshop booked by free-text name has no coordinates, so the geofence above
                 * can never fire and the rider reads "going to the workshop" all day. This
                 * notices that he has STOPPED somewhere we cannot name and arms a single
                 * question; answering it stamps the arrival AND pins the workshop, so the next
                 * visit there needs no question at all.
                 *
                 * ⚠ Only when the geofence did NOT already answer it — a pinned workshop is
                 *   never resolved by asking.
                 * ⚠ Same non-fatal contract as its neighbour.
                 */
                if (!$stamped) {
                    $wsSvc->maybeAskArrival((int) $user->id, (float) $latitude,
                                            (float) $longitude, $accuracy);
                }
            } catch (\Throwable $e) {
                \Log::warning('workshop arrival stamp skipped', ['error' => $e->getMessage()]);
            }

            // ⭐ U4 — server-side home geofence: during the going-home phase, the first fix inside
            // the home radius STAMPS the true arrival time (proves time+location even if he types
            // the meter later) and nudges him once to record the meter. Non-fatal by contract.
            if ($homePhase && empty($attendance->home_arrived_at)) {
                try {
                    $hjSvc = new \App\Services\Riders\HomeJourneyService();
                    $homePin = $hjSvc->riderHomePin($user->id);
                    if ($homePin) {
                        $dHome = $this->haversineDistance((float) $latitude, (float) $longitude, $homePin['lat'], $homePin['lng']);
                        if ($dHome <= $homePin['radius_m']) {
                            \DB::table('t_ops_attendance')->where('id', $attendance->id)->update([
                                'home_arrived_at' => now(),
                                'home_arrival_source' => 'geofence',
                                'updated_at' => now(),
                            ]);
                            try {
                                (new \App\Services\FirebaseService())->notifyUser(
                                    (int) $user->id,
                                    // 🗣 Roman Urdu — a rider must act on this (owner ruling).
                                    ['title' => '🏠 Aap ghar pahunch gaye',
                                     'body'  => 'Din khatam karne ke liye abhi apna meter reading daal dein.'],
                                    ['type' => 'home_arrival'],
                                    'shift_notifications'
                                );
                            } catch (\Throwable $e) { /* push best-effort */ }
                        }
                    }
                } catch (\Throwable $e) { /* geofence best-effort */ }
            }

            // ⭐ SMART DAILY CLEANUP: Only run once per day
            // Uses cache to track last cleanup date - first heartbeat of the day triggers cleanup
            // Keeps 20 days of location history
            $lastCleanup = \Cache::get('rider_location_last_cleanup');
            if ($lastCleanup !== $today) {
                $deletedCount = \DB::table('t_ops_rider_location')
                    ->where('captured_at', '<', now()->subDays(20))
                    ->delete();
                
                \Cache::put('rider_location_last_cleanup', $today, now()->addDays(2));
                
                if ($deletedCount > 0) {
                    \Log::info('Location data cleanup completed', [
                        'deleted_count' => $deletedCount,
                        'triggered_by_user' => $user->id
                    ]);
                }
            }

            // May-2026 — Qurbani auto-WhatsApp piggyback on the rider
            // GPS heartbeat. The mobile app POSTs here every 5 minutes
            // per checked-in rider (locationHeartbeat.js), so during
            // Qurbani day with N active riders this endpoint fires
            // roughly N×12 times per hour — far more reliable than a
            // server cron on shared hosting (stackcp, etc.) where we
            // can't always count on `* * * * * schedule:run` being set
            // up. Combined with the existing scheduler hook and the
            // manager-planner terminating() hook, this gives us three
            // independent triggers, any of which is enough to keep
            // slaughter + OFD messages flowing.
            //
            // Self-throttled by the QurbaniWaAutoSender's 55-second
            // Cache lock, so even ten riders heartbeating at once
            // results in at most one effective worker run per minute.
            // Fires via app()->terminating() so the response to the
            // rider phone is already flushed before we hit Meta — the
            // rider's GPS save latency is unaffected.
            $this->fireQurbaniWaAutoSender();

            // ⭐ GPS defibrillator: opportunistically sweep for on-duty riders whose
            // GPS has gone silent (snoozed) and wake them via a silent FCM push.
            // Self-throttled to ~once/min via a Cache lock, so firing it on every
            // heartbeat is cheap. Runs in terminating() so the rider's response is
            // already flushed. The on-device WorkManager watchdog covers the case
            // where ALL riders are silent (no heartbeat to trigger this).
            $this->fireRiderGpsWatchdog();

            // ⭐ U4 — escalate a missed/late home meter to management (throttled, terminating).
            $this->fireHomeMeterEscalation();

            return response()->json([
                'success' => true,
                'message' => 'Location recorded',
                // Which leg of the day this point belongs to — lets the app (and anyone reading
                // the response while diagnosing) tell an accepted ride-in/ride-home heartbeat
                // from a normal on-duty one, since all three now reach this endpoint.
                'phase' => $workPhase ? 'ride_in' : ($homePhase ? 'ride_home' : 'on_duty'),
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to record location heartbeat', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
                'user_id' => Auth::id(),
                'request_data' => $request->all()
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to record location: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * ⭐ LOCATION TRACKING: Log location failure
     * Records when the app tried to get location but failed
     * Helps diagnose GPS gaps in the audit
     */
    public function logLocationFailure(Request $request)
    {
        try {
            $user = Auth::user();
            
            if (!$user) {
                \Log::warning('📍 Location failure log rejected: unauthorized');
                return response()->json([
                    'success' => false,
                    'message' => 'Unauthorized'
                ], 401);
            }
            
            // ⭐ Log incoming request for debugging
            \Log::info('📍 Location failure API called', [
                'user_id' => $user->id,
                'request_data' => $request->all(),
            ]);
            
            // Validate input - be lenient with last_success_at
            $validated = $request->validate([
                'failure_reason' => 'required|string|max:50',
                'failure_source' => 'nullable|string|max:30',
                'error_message' => 'nullable|string|max:255',
                'device_online' => 'nullable',
                'last_known_lat' => 'nullable|numeric',
                'last_known_lng' => 'nullable|numeric',
                'last_success_at' => 'nullable|string', // Changed from date to string
                'app_state' => 'nullable|string|max:20',
                'app_version' => 'nullable|string|max:20',
            ]);
            
            // ⭐ Parse last_success_at if provided (handle various formats)
            $lastSuccessAt = null;
            if (!empty($validated['last_success_at'])) {
                try {
                    $lastSuccessAt = \Carbon\Carbon::parse($validated['last_success_at']);
                } catch (\Exception $e) {
                    \Log::warning('📍 Could not parse last_success_at', [
                        'value' => $validated['last_success_at'],
                        'error' => $e->getMessage(),
                    ]);
                }
            }
            
            // ⭐ Use raw SQL INSERT for maximum reliability
            $insertData = [
                'user_id' => (int)$user->id,
                'failure_reason' => $validated['failure_reason'],
                'failure_source' => $validated['failure_source'] ?? 'unknown',
                'error_message' => isset($validated['error_message']) ? substr($validated['error_message'], 0, 255) : null,
                'device_online' => isset($validated['device_online']) ? ($validated['device_online'] ? 1 : 0) : null,
                'last_known_lat' => $validated['last_known_lat'] ?? null,
                'last_known_lng' => $validated['last_known_lng'] ?? null,
                'last_success_at' => $lastSuccessAt ? $lastSuccessAt->toDateTimeString() : null,
                'app_state' => $validated['app_state'] ?? 'unknown',
                'app_version' => $validated['app_version'] ?? null,
                'captured_at' => now()->toDateTimeString(),
            ];
            
            \Log::info('📍 Attempting insert with data', $insertData);
            
            // ⭐ Try raw INSERT statement
            $inserted = \DB::statement(
                "INSERT INTO t_ops_location_failures 
                (user_id, failure_reason, failure_source, error_message, device_online, 
                 last_known_lat, last_known_lng, last_success_at, app_state, app_version, captured_at) 
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                [
                    $insertData['user_id'],
                    $insertData['failure_reason'],
                    $insertData['failure_source'],
                    $insertData['error_message'],
                    $insertData['device_online'],
                    $insertData['last_known_lat'],
                    $insertData['last_known_lng'],
                    $insertData['last_success_at'],
                    $insertData['app_state'],
                    $insertData['app_version'],
                    $insertData['captured_at'],
                ]
            );
            
            \Log::info('📍 Location failure logged to DB successfully', [
                'user_id' => $user->id,
                'reason' => $validated['failure_reason'],
                'inserted' => $inserted,
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Failure logged',
                'debug' => 'inserted=' . ($inserted ? 'true' : 'false'),
            ]);
            
        } catch (\Exception $e) {
            // Log the actual error for debugging
            \Log::error('❌ Failed to log location failure (EXCEPTION)', [
                'error' => $e->getMessage(),
                'line' => $e->getLine(),
                'file' => $e->getFile(),
                'user_id' => Auth::id(),
            ]);
            
            // Return success anyway - don't block the app, but include error for debugging
            return response()->json([
                'success' => true,
                'message' => 'Noted',
                'debug_error' => substr($e->getMessage(), 0, 100),
            ]);
        }
    }

    /**
     * ⭐ LOCATION TRACKING: Get all active riders for map view
     * Returns riders who are checked in today OR have recent location data
     * 
     * @param date - Optional date for viewing history (YYYY-MM-DD)
     */
    public function getActiveRidersForMap(Request $request)
    {
        try {
            // Check if viewing history or live
            $requestedDate = $request->get('date');
            $isHistory = $requestedDate && $requestedDate !== now()->format('Y-m-d');
            $targetDate = $requestedDate ?: now()->format('Y-m-d');
            $today = now()->format('Y-m-d');
            
            // Get riders who are:
            // 1. Checked in on target date (with or without checkout), OR
            // 2. Have location data on that date (for history) or in last 24 hours (for live)
            // 3. For history: riders who delivered orders on that date
            $riders = \DB::table('t_sys_user as u')
                ->leftJoin('t_ops_attendance as a', function($join) use ($targetDate) {
                    $join->on('u.id', '=', 'a.user_id')
                         ->whereDate('a.attendance_date', $targetDate);
                });
            
            if ($isHistory) {
                // For history, get location data from that specific date
                $riders->leftJoin(\DB::raw("(
                    SELECT user_id, 
                           MAX(captured_at) as last_location_at,
                           SUBSTRING_INDEX(GROUP_CONCAT(latitude ORDER BY captured_at DESC), ',', 1) as last_lat,
                           SUBSTRING_INDEX(GROUP_CONCAT(longitude ORDER BY captured_at DESC), ',', 1) as last_lng
                    FROM t_ops_rider_location 
                    WHERE DATE(captured_at) = '{$targetDate}'
                    GROUP BY user_id
                ) as loc"), 'u.id', '=', 'loc.user_id');
                
                // For history, also include riders who delivered orders on that date
                $riders->leftJoin(\DB::raw("(
                    SELECT DISTINCT o.assigned_rider_user_id as user_id
                    FROM t_crm_prod_order o
                    INNER JOIN t_crm_order_status_history osh ON o.id = osh.order_id
                    WHERE osh.status_code = 'delivered'
                    AND DATE(osh.changed_at) = '{$targetDate}'
                ) as delivered"), 'u.id', '=', 'delivered.user_id');
            } else {
                /**
                 * ⚡ LIVE last-fix per rider (Sep-2026 rewrite — same output, bounded cost).
                 *
                 * The old shape GROUP_CONCAT'ed EVERY location row of the last 24h for every
                 * user just to read the newest one via SUBSTRING_INDEX. That cost grows with
                 * the GPS ping rate (a shorter heartbeat makes it strictly worse) and, once a
                 * rider's day exceeds group_concat_max_len, MySQL silently TRUNCATES the list —
                 * which would start returning a wrong "last position" with no error at all.
                 *
                 * Same answer, computed the cheap way: newest captured_at per user, then join
                 * that one row back for its coordinates. Identical columns, identical window.
                 * ⚠ The ties join can only duplicate a user if two rows share the exact same
                 *   captured_at; MIN(id) on the inner pick keeps it to one row per user.
                 */
                $riders->leftJoin(\DB::raw('(
                    SELECT l.user_id,
                           l.captured_at as last_location_at,
                           l.latitude    as last_lat,
                           l.longitude   as last_lng
                    FROM t_ops_rider_location l
                    INNER JOIN (
                        SELECT user_id, MAX(captured_at) as mx
                        FROM t_ops_rider_location
                        WHERE captured_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
                        GROUP BY user_id
                    ) newest ON newest.user_id = l.user_id AND newest.mx = l.captured_at
                    INNER JOIN (
                        SELECT user_id, captured_at, MIN(id) as keep_id
                        FROM t_ops_rider_location
                        WHERE captured_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
                        GROUP BY user_id, captured_at
                    ) one ON one.user_id = l.user_id AND one.captured_at = l.captured_at AND one.keep_id = l.id
                    WHERE l.captured_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
                ) as loc'), 'u.id', '=', 'loc.user_id');
            }
            
            // ⭐ Join to get last sync time from orders (more reliable than location heartbeat)
            /**
             * ⚡ Bounded to 24h (Sep-2026). This aggregated EVERY order ever assigned, with no
             *    date bound, on a 30s-polling endpoint — the scan grows forever with the order
             *    table. The value only ever feeds the "app sync" freshness bands (<=2 min /
             *    <=10 min, riders-map index.blade), so anything older than a day already read
             *    as Offline; bounding it changes no verdict, only the cost.
             */
            $riders->leftJoin(\DB::raw('(
                SELECT assigned_rider_user_id as user_id,
                       MAX(rider_last_sync_at) as last_sync_at
                FROM t_crm_prod_order
                WHERE rider_last_sync_at IS NOT NULL
                  AND rider_last_sync_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
                GROUP BY assigned_rider_user_id
            ) as sync'), 'u.id', '=', 'sync.user_id')
            // ⭐ Join to get app login status (check if user HAS any tokens)
            ->leftJoin(\DB::raw('(
                SELECT tokenable_id as user_id,
                       COUNT(*) as token_count,
                       MAX(last_used_at) as token_last_used_at,
                       MAX(created_at) as token_created_at
                FROM personal_access_tokens 
                WHERE tokenable_type = "App\\\\Models\\\\User"
                GROUP BY tokenable_id
            ) as tokens'), 'u.id', '=', 'tokens.user_id')
                ->where('u.is_active', 1);
            
            if ($isHistory) {
                // For history, show riders who checked in OR delivered orders that day
                $riders->where(function($q) {
                    $q->whereNotNull('a.login_time')
                      ->orWhereNotNull('loc.last_location_at')
                      ->orWhereNotNull('delivered.user_id');
                });
            } else {
                // For live view (today), ONLY show riders who have checked in today
                // Recent location alone is not enough - they must have attendance for today
                $riders->whereNotNull('a.login_time');
            }
            
            $riders = $riders->select([
                    'u.id',
                    'u.fullname as name',
                    'u.app_version', // ⭐ Get app_version from user table (set on login)
                    'a.login_time',
                    'a.logout_time',
                    'loc.last_location_at',
                    'loc.last_lat as latitude',
                    'loc.last_lng as longitude',
                    'sync.last_sync_at',
                    'tokens.token_count', // ⭐ Count of active tokens
                    'tokens.token_last_used_at',
                    'tokens.token_created_at',
                ])
                ->orderBy('u.fullname')
                ->get();

            // Get order counts for each rider:
            // - For live: Open orders (any date) + Delivered today
            // - For history: Delivered on that date only
            $riderIds = $riders->pluck('id')->toArray();
            $orderCounts = [];
            
            if (!empty($riderIds)) {
                if ($isHistory) {
                    // For history, only show delivered orders on that date
                    $deliveredCounts = \DB::table('t_crm_prod_order as o')
                        ->join('t_crm_order_status_history as osh', function($join) use ($targetDate) {
                            $join->on('o.id', '=', 'osh.order_id')
                                 ->where('osh.status_code', '=', 'delivered')
                                 ->whereDate('osh.changed_at', $targetDate);
                        })
                        ->whereIn('o.assigned_rider_user_id', $riderIds)
                        ->select([
                            'o.assigned_rider_user_id as rider_id',
                            \DB::raw('COUNT(DISTINCT o.id) as delivered_orders'),
                        ])
                        ->groupBy('o.assigned_rider_user_id')
                        ->get()
                        ->keyBy('rider_id');
                    
                    foreach ($riderIds as $riderId) {
                        $orderCounts[$riderId] = (object)[
                            'open_orders' => 0, // No open orders for history view
                            'delivered_orders' => $deliveredCounts[$riderId]->delivered_orders ?? 0,
                        ];
                    }
                } else {
                    // For live view, get open orders count (any date, excluding completed statuses)
                    $excludedStatuses = ['delivered', 'completed', 'cancelled', 'refunded'];
                    $openCounts = \DB::table('t_crm_prod_order')
                        ->whereIn('assigned_rider_user_id', $riderIds)
                        ->whereNotIn('order_status', $excludedStatuses)
                        ->select([
                            'assigned_rider_user_id as rider_id',
                            \DB::raw('COUNT(*) as open_orders'),
                        ])
                        ->groupBy('assigned_rider_user_id')
                        ->get()
                        ->keyBy('rider_id');
                
                    // Get delivered today count (based on status history changed_at)
                    $deliveredCounts = \DB::table('t_crm_prod_order as o')
                        ->join('t_crm_order_status_history as osh', function($join) use ($today) {
                            $join->on('o.id', '=', 'osh.order_id')
                                 ->where('osh.status_code', '=', 'delivered')
                                 ->whereDate('osh.changed_at', $today);
                        })
                        ->whereIn('o.assigned_rider_user_id', $riderIds)
                        ->select([
                            'o.assigned_rider_user_id as rider_id',
                            \DB::raw('COUNT(DISTINCT o.id) as delivered_today'),
                        ])
                        ->groupBy('o.assigned_rider_user_id')
                        ->get()
                        ->keyBy('rider_id');
                    
                    // Combine counts
                    foreach ($riderIds as $riderId) {
                        $openCount = $openCounts[$riderId]->open_orders ?? 0;
                        $deliveredCount = $deliveredCounts[$riderId]->delivered_today ?? 0;
                        $orderCounts[$riderId] = (object)[
                            'total_orders' => $openCount + $deliveredCount,
                            'delivered_orders' => $deliveredCount,
                            'open_orders' => $openCount,
                        ];
                    }
                } // End else (live view)
            } // End if (!empty($riderIds))

            // Format response
            $formattedRiders = $riders->map(function($rider) use ($orderCounts) {
                $counts = $orderCounts[$rider->id] ?? (object)['total_orders' => 0, 'delivered_orders' => 0, 'open_orders' => 0];
                $isCheckedIn = !is_null($rider->login_time);
                $isCheckedOut = !is_null($rider->logout_time);
                
                // Calculate location age in human-readable format
                $locationAge = null;
                $locationAgeMinutes = null;
                if ($rider->last_location_at) {
                    $lastLocationTime = \Carbon\Carbon::parse($rider->last_location_at);
                    // Use absolute value to ensure positive minutes
                    $locationAgeMinutes = abs(now()->diffInMinutes($lastLocationTime));
                    $locationAge = $lastLocationTime->diffForHumans(); // e.g., "2 minutes ago"
                }
                
                // ⭐ Calculate sync age (more reliable for online status than location)
                // This is when the mobile app last fetched orders
                $syncAge = null;
                $syncAgeMinutes = null;
                if ($rider->last_sync_at) {
                    $lastSyncTime = \Carbon\Carbon::parse($rider->last_sync_at);
                    // Use absolute value to ensure positive minutes
                    $syncAgeMinutes = abs(now()->diffInMinutes($lastSyncTime));
                    $syncAge = $lastSyncTime->diffForHumans();
                }
                
                // ⭐ Calculate app login status (from API token existence)
                // User is "logged in" if they have ANY active tokens
                $tokenCount = intval($rider->token_count ?? 0);
                $isAppLoggedIn = $tokenCount > 0;
                $appLastActiveAt = null;
                $appLastActiveAge = null;
                if ($rider->token_last_used_at) {
                    $lastTokenUse = \Carbon\Carbon::parse($rider->token_last_used_at);
                    $appLastActiveAt = $rider->token_last_used_at;
                    $appLastActiveAge = $lastTokenUse->diffForHumans();
                }

                return [
                    'id' => $rider->id,
                    'name' => $rider->name,
                    'is_checked_in' => $isCheckedIn,
                    'is_checked_out' => $isCheckedOut,
                    'status' => $isCheckedOut ? 'checked_out' : ($isCheckedIn ? 'on_duty' : 'has_location'),
                    'checked_in_at' => $rider->login_time,
                    'checked_out_at' => $rider->logout_time,
                    // Last location from GPS heartbeat
                    'last_location' => $rider->latitude ? [
                        'latitude' => (float)$rider->latitude,
                        'longitude' => (float)$rider->longitude,
                        'captured_at' => $rider->last_location_at,
                        'age' => $locationAge,
                        'age_minutes' => $locationAgeMinutes,
                    ] : null,
                    // ⭐ Last sync from mobile app (more reliable for online status)
                    'last_sync' => $rider->last_sync_at ? [
                        'synced_at' => $rider->last_sync_at,
                        'age' => $syncAge,
                        'age_minutes' => $syncAgeMinutes,
                    ] : null,
                    // ⭐ App login status (from API token)
                    'app_status' => [
                        'is_logged_in' => $isAppLoggedIn,
                        'last_active_at' => $appLastActiveAt,
                        'last_active_age' => $appLastActiveAge,
                        'app_version' => $rider->app_version,
                    ],
                    'orders_today' => [
                        'total' => $counts->total_orders ?? 0,
                        'delivered' => $counts->delivered_orders ?? 0,
                        'pending' => $counts->open_orders ?? 0,
                    ],
                ];
            });

            return response()->json([
                'success' => true,
                'riders' => $formattedRiders,
                'is_history' => $isHistory,
                'target_date' => $targetDate,
                'timestamp' => now()->toIso8601String()
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to get active riders for map', [
                'error' => $e->getMessage()
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load riders'
            ], 500);
        }
    }

    /**
     * ⭐ LOCATION TRACKING: Get detailed map data for a specific rider
     * Returns rider's location trail and orders with locations
     * 
     * @param date - Optional date for viewing history (YYYY-MM-DD)
     */
    public function getRiderMapData(Request $request, $riderId)
    {
        try {
            // Check if viewing history or live
            $requestedDate = $request->get('date');
            $isHistory = $requestedDate && $requestedDate !== now()->format('Y-m-d');
            $targetDate = $requestedDate ?: now()->format('Y-m-d');
            $today = now()->format('Y-m-d');
            
            // Get rider info
            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->where('is_active', 1)
                ->select('id', 'fullname as name')
                ->first();

            if (!$rider) {
                return response()->json([
                    'success' => false,
                    'message' => 'Rider not found'
                ], 404);
            }

            // Get rider's attendance status for target date
            $attendance = \DB::table('t_ops_attendance')
                ->where('user_id', $riderId)
                ->whereDate('attendance_date', $targetDate)
                ->first();

            // Get rider's location fixes for target date (or last 24 hours for live)
            $locationQuery = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId);
            
            if ($isHistory) {
                // For history, get all locations from that specific date
                $locationQuery->whereDate('captured_at', $targetDate);
            } else {
                // For live, get last 24 hours
                $locationQuery->where('captured_at', '>=', now()->subHours(24));
            }
            
            $rawLocationTrail = $locationQuery
                ->orderBy('captured_at', 'desc')
                ->limit($isHistory ? 200 : 50) // ⭐ Fetch more before filtering
                ->select('latitude', 'longitude', 'accuracy', 'captured_at', 'source')
                ->get();
            
            // ⭐ Filter for quality: accuracy <= 50m, deduplicate per second
            $filteredTrail = $rawLocationTrail->filter(function($loc) {
                $accuracy = (float)($loc->accuracy ?? 0);
                return $accuracy > 0 && $accuracy <= 50;
            });
            if ($filteredTrail->isEmpty()) {
                $filteredTrail = $rawLocationTrail->sortBy('accuracy')->take(max(1, intval($rawLocationTrail->count() * 0.3)));
            }
            // Deduplicate same-second readings
            $dedupedTrail = collect();
            $groupedTrail = $filteredTrail->groupBy(function($loc) {
                return substr($loc->captured_at, 0, 19);
            });
            foreach ($groupedTrail as $ts => $grp) {
                $dedupedTrail->push($grp->sortBy(function($loc) { return (float)($loc->accuracy ?? 999); })->first());
            }
            
            $locationTrail = $dedupedTrail->sortByDesc('captured_at')
                ->take($isHistory ? 50 : 10)
                ->values()
                ->map(function($loc) {
                    $capturedAt = \Carbon\Carbon::parse($loc->captured_at);
                    return [
                        'latitude' => (float)$loc->latitude,
                        'longitude' => (float)$loc->longitude,
                        'accuracy' => $loc->accuracy,
                        'captured_at' => $loc->captured_at,
                        'time' => $capturedAt->format('H:i'),
                        'age' => $capturedAt->diffForHumans(),
                        'source' => $loc->source,
                    ];
                });

            // Current location for the precise map marker (accuracy-filtered trail).
            $currentLocation = $locationTrail->first();

            // ⭐ Freshness-consistency fix: the trail above is filtered to accuracy <= 50m,
            // so when the newest heartbeats are coarse (>50m) they get dropped and the map's
            // "last seen" lags behind the live board / dispatch card / rider list — all of which
            // use the raw MAX(captured_at). Use the raw newest fix for the current marker so
            // "last seen" matches everywhere else, UNLESS it's an absurd outlier (>500m), which
            // we skip to avoid teleporting the marker. The polyline trail stays filtered.
            $rawLatest = $rawLocationTrail->first();
            if ($rawLatest
                && (!$currentLocation || $rawLatest->captured_at > $currentLocation['captured_at'])
                && ($rawLatest->accuracy === null || (float) $rawLatest->accuracy <= 500)) {
                $rawCap = \Carbon\Carbon::parse($rawLatest->captured_at);
                $currentLocation = [
                    'latitude'    => (float) $rawLatest->latitude,
                    'longitude'   => (float) $rawLatest->longitude,
                    'accuracy'    => $rawLatest->accuracy,
                    'captured_at' => $rawLatest->captured_at,
                    'time'        => $rawCap->format('H:i'),
                    'age'         => $rawCap->diffForHumans(),
                    'source'      => $rawLatest->source,
                ];
            }

            // Get orders for this rider based on view mode
            $excludedStatuses = ['delivered', 'completed', 'cancelled', 'refunded'];
            
            // ⭐ Subquery to get LATEST delivered status per order (handles duplicate delivered statuses)
            $latestDeliveredStatus = \DB::table('t_crm_order_status_history')
                ->select('order_id', \DB::raw('MAX(id) as latest_osh_id'))
                ->where('status_code', 'delivered')
                ->groupBy('order_id');
            
            $ordersQuery = \DB::table('t_crm_prod_order as o')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->leftJoinSub($latestDeliveredStatus, 'latest_del', function($join) {
                    $join->on('o.id', '=', 'latest_del.order_id');
                })
                ->leftJoin('t_crm_order_status_history as osh', 'osh.id', '=', 'latest_del.latest_osh_id')
                ->where('o.assigned_rider_user_id', $riderId);
            
            if ($isHistory) {
                // For history, ONLY show orders delivered on that date
                $ordersQuery->whereExists(function($sub) use ($targetDate) {
                    $sub->select(\DB::raw(1))
                        ->from('t_crm_order_status_history as osh2')
                        ->whereColumn('osh2.order_id', 'o.id')
                        ->where('osh2.status_code', 'delivered')
                        ->whereDate('osh2.changed_at', $targetDate);
                });
            } else {
                // For live view:
                // 1. All OPEN orders (not delivered/completed/cancelled/refunded) - any date
                // 2. Orders DELIVERED TODAY (based on status history changed_at)
                $ordersQuery->where(function($q) use ($excludedStatuses, $today) {
                    // Open orders (any date)
                    $q->whereNotIn('o.order_status', $excludedStatuses)
                    // OR delivered today (based on status history)
                      ->orWhere(function($q2) use ($today) {
                          $q2->whereIn('o.order_status', ['delivered', 'completed'])
                             ->whereExists(function($sub) use ($today) {
                                 $sub->select(\DB::raw(1))
                                     ->from('t_crm_order_status_history as osh2')
                                     ->whereColumn('osh2.order_id', 'o.id')
                                     ->where('osh2.status_code', 'delivered')
                                     ->whereDate('osh2.changed_at', $today);
                             });
                      });
                });
            }
            
            $orders = $ordersQuery
                ->select([
                    'o.id',
                    'o.order_number',
                    'o.order_status as status',
                    'o.total_price',
                    'o.payment_method',
                    // Customer info
                    'c.id as customer_id',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    'c.address1 as address',
                    'c.city',
                    // Verified location (customer - manually set, high accuracy)
                    'c.latitude as verified_lat',
                    'c.longitude as verified_lng',
                    'c.verified_location_url',
                    // Geocoded location (customer - auto from address, approximate)
                    'c.geocoded_latitude as geocoded_lat',
                    'c.geocoded_longitude as geocoded_lng',
                    // Delivery location (from status history - actual GPS when marked delivered)
                    'osh.delivery_latitude as delivery_lat',
                    'osh.delivery_longitude as delivery_lng',
                    'osh.changed_at as delivered_at',
                    // ⭐ ETA from "Get Times" button
                    'o.estimated_delivery_at',
                    // ⭐ Planned drop position (Aug-23). Every other surface — the
                    //    store board, the rider app, the van cards — already shows
                    //    the sequence; this drill-down was the last list without it.
                    'o.delivery_priority',
                ])
                ->orderBy('o.id', 'desc')
                ->get();

            // ⭐ Lateness on the map popups is judged against the PROMISE, not the
            //    live ETA a re-dispatch overwrites (EtaPromiseService). Unlogged
            //    orders are absent → they keep today's behaviour.
            $etaPromises = \App\Services\Riders\EtaPromiseService::promisesFor(
                $orders->pluck('id')->all()
            );

            // Format orders with location info
            // Location priority:
            // 1. Delivery GPS (actual location when marked delivered)
            // 2. Customer verified location (manually set by rider)
            // 3. Customer geocoded location (auto from address)
            $formattedOrders = $orders->map(function($order) use ($etaPromises) {
                $isDelivered = in_array($order->status, ['delivered', 'completed']);
                
                // Determine location source and coordinates with priority
                $location = null;
                $locationSource = null;
                
                // Priority 1: Actual delivery GPS (only for delivered orders)
                if ($isDelivered && $order->delivery_lat && $order->delivery_lng) {
                    $location = [
                        'latitude' => (float)$order->delivery_lat,
                        'longitude' => (float)$order->delivery_lng,
                    ];
                    $locationSource = 'delivery_gps';
                }
                // Priority 2: Customer's verified location (manually confirmed)
                elseif ($order->verified_lat && $order->verified_lng) {
                    $location = [
                        'latitude' => (float)$order->verified_lat,
                        'longitude' => (float)$order->verified_lng,
                    ];
                    $locationSource = 'verified_location';
                }
                // Priority 3: Customer's geocoded location (auto from address)
                elseif ($order->geocoded_lat && $order->geocoded_lng) {
                    $location = [
                        'latitude' => (float)$order->geocoded_lat,
                        'longitude' => (float)$order->geocoded_lng,
                    ];
                    $locationSource = 'geocoded_address';
                }

                // Determine payment type from payment_method
                $paymentMethod = strtolower($order->payment_method ?? 'cash');
                $isCash = in_array($paymentMethod, ['cash', 'cash_on_delivery', 'cod']);
                
                // ⭐ Build ETA display for delivered orders — judged against the
                //    promise (falls back to the live ETA for pre-log orders).
                $promise = $etaPromises[(int) $order->id] ?? null;
                $judgeEta = $promise['promised_at'] ?? $order->estimated_delivery_at;
                $etaDisplay = null;
                $etaComparison = null;
                if ($judgeEta && $isDelivered && $order->delivered_at) {
                    $estimatedTime = \Carbon\Carbon::parse($judgeEta);
                    $etaDisplay = $estimatedTime->format('h:i A');
                    $actualTime = \Carbon\Carbon::parse($order->delivered_at);
                    $diffMinutes = (int) round($actualTime->diffInMinutes($estimatedTime, false));

                    $etaComparison = [
                        'estimated_at_display' => $etaDisplay,
                        'actual_at_display' => $actualTime->format('h:i A'),
                        'diff_minutes' => $diffMinutes,
                        'status' => $diffMinutes >= 0 ? 'early' : 'late',
                        'status_text' => $diffMinutes >= 0
                            ? ($diffMinutes == 0 ? 'On time' : "{$diffMinutes} min early")
                            : (abs($diffMinutes) . ' min late'),
                        'retimed' => !empty($promise['retimed']),
                        'retimed_by_rider' => !empty($promise['retimed_by_rider']),
                        'live_at_display' => !empty($promise['retimed']) && $promise['final_at']
                            ? \Carbon\Carbon::parse($promise['final_at'])->format('h:i A')
                            : null,
                    ];
                } elseif ($order->estimated_delivery_at && !$isDelivered) {
                    // Undelivered: the LIVE ETA is the operationally relevant time.
                    $estimatedTime = \Carbon\Carbon::parse($order->estimated_delivery_at);
                    $etaDisplay = $estimatedTime->format('h:i A');
                }

                return [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_id' => $order->customer_id,
                    'status' => $order->status,
                    'status_display' => ucfirst(str_replace('_', ' ', $order->status)),
                    'customer_name' => trim($order->customer_name) ?: 'Unknown',
                    'address' => $order->address . ($order->city ? ', ' . $order->city : ''),
                    'total' => 'PKR ' . number_format($order->total_price, 0),
                    'payment_type' => $isCash ? 'cash' : 'online',
                    'location' => $location,
                    'location_source' => $locationSource,
                    'delivered_at' => $order->delivered_at,
                    'estimated_delivery_at_display' => $etaDisplay, // ⭐ ETA time
                    'eta_comparison' => $etaComparison, // ⭐ ETA vs actual
                    'google_maps_url' => $order->verified_location_url,
                    // ⭐ Planned drop position — null stays null (never 0), so the
                    //    client can leave un-sequenced stops without a chip.
                    'delivery_priority' => $order->delivery_priority !== null
                        ? (int) $order->delivery_priority : null,
                ];
            });

            // Separate delivered and pending orders for counts
            $deliveredOrders = $formattedOrders->filter(fn($o) => in_array($o['status'], ['delivered', 'completed']))->values();
            $pendingOrders = $formattedOrders->filter(fn($o) => !in_array($o['status'], ['delivered', 'completed', 'cancelled', 'refunded']))->values();

            return response()->json([
                'success' => true,
                'rider' => [
                    'id' => $rider->id,
                    'name' => $rider->name,
                    'status' => $attendance ? 
                        ($attendance->logout_time ? 'checked_out' : ($attendance->login_time ? 'on_duty' : 'not_checked_in')) 
                        : 'not_checked_in',
                    'checked_in_at' => $attendance->login_time ?? null,
                    'checked_out_at' => $attendance->logout_time ?? null,
                    // Include location data inside rider object as frontend expects
                    'current_location' => $currentLocation,
                    'location_trail' => $locationTrail->slice(0, 5)->values(), // Last 5 for trail
                ],
                // Summary for the header
                'summary' => [
                    'total_orders' => $formattedOrders->count(),
                    'delivered' => $deliveredOrders->count(),
                    'pending' => $pendingOrders->count(),
                ],
                // Flat array of all orders (frontend iterates over this)
                'orders' => $formattedOrders->values(),
                'timestamp' => now()->toIso8601String()
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to get rider map data', [
                'rider_id' => $riderId,
                'error' => $e->getMessage()
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load rider data'
            ], 500);
        }
    }

    /**
     * ⭐ LOCATION TRACKING: Get rider's location history (last 2 hours)
     * Groups nearby locations and shows duration at each location
     * 
     * @param riderId - Rider user ID
     * @param hours - Hours to look back (default 2)
     */
    public function getRiderLocationHistory(Request $request, $riderId)
    {
        try {
            $hours = $request->get('hours', 2);
            $date = $request->get('date'); // Optional specific date
            
            $query = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId);
            
            if ($date) {
                $query->whereDate('captured_at', $date);
            } else {
                // Last N hours for live view
                $query->where('captured_at', '>=', now()->subHours($hours));
            }
            
            $rawLocations = $query
                ->orderBy('captured_at', 'asc') // Oldest first for grouping
                ->select('latitude', 'longitude', 'accuracy', 'captured_at', 'source')
                ->get();
            
            if ($rawLocations->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'locations' => [],
                    'total_points' => 0,
                    'grouped_points' => 0,
                ]);
            }
            
            // ⭐ Filter out low-quality GPS readings (accuracy > 50m)
            $locations = $rawLocations->filter(function($loc) {
                $accuracy = (float)($loc->accuracy ?? 0);
                return $accuracy > 0 && $accuracy <= 50;
            });
            
            // If all filtered out, use best 50% by accuracy
            if ($locations->isEmpty()) {
                $locations = $rawLocations->sortBy('accuracy')->take(max(1, intval($rawLocations->count() * 0.5)));
            }
            
            // ⭐ Deduplicate same-second readings (keep best accuracy per second)
            $deduped = collect();
            $grouped = $locations->groupBy(function($loc) {
                return substr($loc->captured_at, 0, 19);
            });
            foreach ($grouped as $timestamp => $group) {
                $best = $group->sortBy(function($loc) {
                    return (float)($loc->accuracy ?? 999);
                })->first();
                $deduped->push($best);
            }
            $locations = $deduped->sortBy('captured_at')->values();
            
            // Group nearby locations and calculate duration at each spot
            // ~50m threshold (roughly 0.0005 degrees)
            $threshold = 0.0005;
            $groupedLocations = [];
            $currentGroup = null;
            
            foreach ($locations as $loc) {
                $lat = (float)$loc->latitude;
                $lng = (float)$loc->longitude;
                $capturedAt = \Carbon\Carbon::parse($loc->captured_at);
                
                if ($currentGroup === null) {
                    // Start first group
                    $currentGroup = [
                        'latitude' => $lat,
                        'longitude' => $lng,
                        'accuracy' => $loc->accuracy,
                        'first_seen' => $capturedAt,
                        'last_seen' => $capturedAt,
                        'point_count' => 1,
                        'sources' => [$loc->source],
                    ];
                } else {
                    // Check if this point is near the current group
                    $latDiff = abs($lat - $currentGroup['latitude']);
                    $lngDiff = abs($lng - $currentGroup['longitude']);
                    
                    if ($latDiff < $threshold && $lngDiff < $threshold) {
                        // Same location - extend the group
                        $currentGroup['last_seen'] = $capturedAt;
                        $currentGroup['point_count']++;
                        if (!in_array($loc->source, $currentGroup['sources'])) {
                            $currentGroup['sources'][] = $loc->source;
                        }
                        // Update to use best accuracy
                        if ($loc->accuracy && (!$currentGroup['accuracy'] || $loc->accuracy < $currentGroup['accuracy'])) {
                            $currentGroup['accuracy'] = $loc->accuracy;
                        }
                    } else {
                        // New location - save current group and start new one
                        $groupedLocations[] = $this->formatLocationGroup($currentGroup);
                        $currentGroup = [
                            'latitude' => $lat,
                            'longitude' => $lng,
                            'accuracy' => $loc->accuracy,
                            'first_seen' => $capturedAt,
                            'last_seen' => $capturedAt,
                            'point_count' => 1,
                            'sources' => [$loc->source],
                        ];
                    }
                }
            }
            
            // Don't forget the last group
            if ($currentGroup !== null) {
                $groupedLocations[] = $this->formatLocationGroup($currentGroup);
            }
            
            // Reverse so newest is first
            $groupedLocations = array_reverse($groupedLocations);
            
            return response()->json([
                'success' => true,
                'locations' => $groupedLocations,
                'total_points' => $locations->count(),
                'raw_points' => $rawLocations->count(), // ⭐ Total before GPS filtering
                'grouped_points' => count($groupedLocations),
                'hours' => $hours,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get rider location history', [
                'rider_id' => $riderId,
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load location history'
            ], 500);
        }
    }
    
    /**
     * Helper: Format a location group with duration
     */
    private function formatLocationGroup($group)
    {
        $firstSeen = $group['first_seen'];
        $lastSeen = $group['last_seen'];
        $durationMinutes = $firstSeen->diffInMinutes($lastSeen);
        
        // Format duration
        $duration = null;
        if ($durationMinutes > 0) {
            if ($durationMinutes >= 60) {
                $hours = floor($durationMinutes / 60);
                $mins = $durationMinutes % 60;
                $duration = $hours . 'h ' . ($mins > 0 ? $mins . 'm' : '');
            } else {
                $duration = $durationMinutes . ' min';
            }
        }
        
        return [
            'latitude' => $group['latitude'],
            'longitude' => $group['longitude'],
            'accuracy' => $group['accuracy'],
            'captured_at' => $lastSeen->toIso8601String(),
            'first_seen' => $firstSeen->format('h:i A'), // ⭐ Use formatted time instead of ISO
            'last_seen' => $lastSeen->format('h:i A'), // ⭐ Use formatted time instead of ISO
            'time' => $lastSeen->format('h:i A'),
            'time_display' => $firstSeen->format('h:i A'), // ⭐ Add time_display for frontend
            'arrival_time' => $firstSeen->format('h:i A'),
            'age' => $lastSeen->diffForHumans(),
            'duration' => $duration,
            'duration_minutes' => round($durationMinutes), // ⭐ Round to whole minutes
            'duration_display' => $duration, // ⭐ Already formatted display string
            'point_count' => $group['point_count'],
            'sources' => implode(', ', $group['sources']),
        ];
    }

    /**
     * ⭐ Get GPS trail segment between two deliveries
     * Used by RiderMapModal to show trail for a selected order
     * 
     * @param riderId - Rider ID
     * @param from_time - Start timestamp (e.g., previous delivery time or check-in time)
     * @param to_time - End timestamp (e.g., this order's delivery time)
     * @param office_lat/office_lng - Office coordinates for batch break detection
     * 
     * @return GPS trail with batch break detection
     */
    public function getTrailSegment(Request $request, $riderId)
    {
        try {
            $fromTime = $request->get('from_time');
            $toTime = $request->get('to_time');
            $officeLat = $request->get('office_lat');
            $officeLng = $request->get('office_lng');
            $proximityThreshold = $request->get('proximity_threshold', 500); // 500m default
            
            if (!$fromTime || !$toTime) {
                return response()->json([
                    'success' => false,
                    'message' => 'from_time and to_time are required'
                ], 400);
            }
            
            // Parse timestamps
            $from = \Carbon\Carbon::parse($fromTime);
            $to = \Carbon\Carbon::parse($toTime);
            
            // Get GPS readings between timestamps
            $rawReadings = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->whereBetween('captured_at', [$from, $to])
                ->orderBy('captured_at')
                ->select('latitude', 'longitude', 'accuracy', 'captured_at', 'source')
                ->get();
            
            if ($rawReadings->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'trail' => [],
                    'count' => 0,
                    'raw_count' => 0,
                    'batch_breaks' => [],
                    'message' => 'No GPS readings in this time range'
                ]);
            }
            
            // ⭐ FILTER GPS READINGS for quality (fixes fuzzy/zigzag trails)
            // Step 1: Filter out very low accuracy readings (accuracy > 50m)
            $filtered = $rawReadings->filter(function($loc) {
                $accuracy = (float)($loc->accuracy ?? 0);
                return $accuracy > 0 && $accuracy <= 50;
            });
            
            // If all readings were filtered out (all low quality), fall back to best available
            if ($filtered->isEmpty()) {
                $filtered = $rawReadings->sortBy('accuracy')->take(max(1, intval($rawReadings->count() * 0.5)));
            }
            
            // Step 2: Deduplicate same-second readings (keep best accuracy per second)
            $deduped = collect();
            $grouped = $filtered->groupBy(function($loc) {
                return substr($loc->captured_at, 0, 19); // Group by second (YYYY-MM-DD HH:MM:SS)
            });
            foreach ($grouped as $timestamp => $group) {
                // Keep the reading with best (lowest) accuracy for each second
                $best = $group->sortBy(function($loc) {
                    return (float)($loc->accuracy ?? 999);
                })->first();
                $deduped->push($best);
            }
            $deduped = $deduped->sortBy('captured_at')->values();
            
            // Step 3: Filter out impossible speed jumps (>150 km/h between consecutive points)
            $readings = collect();
            $prev = null;
            foreach ($deduped as $loc) {
                if ($prev === null) {
                    $readings->push($loc);
                    $prev = $loc;
                    continue;
                }
                
                $distance = $this->haversineDistance(
                    (float)$prev->latitude, (float)$prev->longitude,
                    (float)$loc->latitude, (float)$loc->longitude
                );
                $timeDiff = abs(\Carbon\Carbon::parse($loc->captured_at)->diffInSeconds(\Carbon\Carbon::parse($prev->captured_at)));
                
                // Calculate speed: if time diff is 0, allow only if distance < 100m
                if ($timeDiff > 0) {
                    $speedKmh = ($distance / 1000) / ($timeDiff / 3600);
                    if ($speedKmh <= 150) {
                        $readings->push($loc);
                        $prev = $loc;
                    }
                    // else: skip this point (impossible jump)
                } else {
                    // Same timestamp - only allow if very close (<100m)
                    if ($distance < 100) {
                        $readings->push($loc);
                        $prev = $loc;
                    }
                }
            }
            $readings = $readings->values();
            
            if ($readings->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'trail' => [],
                    'count' => 0,
                    'raw_count' => $rawReadings->count(),
                    'batch_breaks' => [],
                    'message' => 'All GPS readings were filtered out (low quality)'
                ]);
            }
            
            // Format trail points
            $trail = $readings->map(function($loc) {
                $capturedAt = \Carbon\Carbon::parse($loc->captured_at);
                return [
                    'latitude' => (float)$loc->latitude,
                    'longitude' => (float)$loc->longitude,
                    'accuracy' => $loc->accuracy,
                    'time' => $capturedAt->format('h:i A'),
                    'captured_at' => $loc->captured_at, // ⭐ Use captured_at (matches frontend expectation)
                    'timestamp' => $loc->captured_at,     // ⭐ Keep for backward compatibility
                    'source' => $loc->source,
                ];
            })->values();
            
            // ⭐ Detect batch breaks (times when rider was near office)
            $batchBreaks = [];
            if ($officeLat && $officeLng) {
                $officeLat = (float)$officeLat;
                $officeLng = (float)$officeLng;
                $currentBatchBreak = null;
                
                foreach ($readings as $loc) {
                    $lat = (float)$loc->latitude;
                    $lng = (float)$loc->longitude;
                    
                    // Calculate distance from office (Haversine formula)
                    $distance = $this->haversineDistance($lat, $lng, $officeLat, $officeLng);
                    
                    if ($distance < $proximityThreshold) {
                        // Near office
                        if (!$currentBatchBreak) {
                            $currentBatchBreak = [
                                'entered_at' => $loc->captured_at,
                                'latitude' => $lat,
                                'longitude' => $lng,
                            ];
                        }
                        $currentBatchBreak['exited_at'] = $loc->captured_at;
                    } else {
                        // Away from office
                        if ($currentBatchBreak) {
                            // Calculate duration at office
                            $entered = \Carbon\Carbon::parse($currentBatchBreak['entered_at']);
                            $exited = \Carbon\Carbon::parse($currentBatchBreak['exited_at']);
                            $durationMinutes = $entered->diffInMinutes($exited);
                            
                            // Only count as batch break if stayed > 5 minutes
                            if ($durationMinutes >= 5) {
                                $batchBreaks[] = [
                                    'entered_at' => $entered->format('h:i A'),
                                    'exited_at' => $exited->format('h:i A'),
                                    'duration_minutes' => $durationMinutes,
                                    'latitude' => $currentBatchBreak['latitude'],
                                    'longitude' => $currentBatchBreak['longitude'],
                                ];
                            }
                            $currentBatchBreak = null;
                        }
                    }
                }
                
                // Handle case where trail ends at office
                if ($currentBatchBreak) {
                    $entered = \Carbon\Carbon::parse($currentBatchBreak['entered_at']);
                    $exited = \Carbon\Carbon::parse($currentBatchBreak['exited_at']);
                    $durationMinutes = $entered->diffInMinutes($exited);
                    
                    if ($durationMinutes >= 5) {
                        $batchBreaks[] = [
                            'entered_at' => $entered->format('h:i A'),
                            'exited_at' => $exited->format('h:i A') . ' (current)',
                            'duration_minutes' => $durationMinutes,
                            'latitude' => $currentBatchBreak['latitude'],
                            'longitude' => $currentBatchBreak['longitude'],
                        ];
                    }
                }
            }
            
            return response()->json([
                'success' => true,
                'trail' => $trail,
                'count' => $trail->count(),
                'raw_count' => $rawReadings->count(), // ⭐ Total before filtering
                'from_time' => $from->format('h:i A'),
                'to_time' => $to->format('h:i A'),
                'batch_breaks' => $batchBreaks,
                'has_batch_break' => count($batchBreaks) > 0,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get trail segment', [
                'rider_id' => $riderId,
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load trail segment: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * ⭐ DELIVERY JOURNEY: Analyze what happened between ride start/last delivery and this delivery.
     * Returns trail, stops, distance, and timing summary for a delivered order.
     */
    public function getDeliveryJourney(Request $request, $orderId)
    {
        try {
            // Get the delivered order with status history
            $order = \DB::table('t_crm_prod_order as o')
                ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
                ->where('o.id', $orderId)
                ->select([
                    'o.id', 'o.order_number', 'o.assigned_rider_user_id',
                    'o.address_line1', 'o.address_city',
                    'o.estimated_delivery_at',
                    'u.fullname as rider_name',
                ])
                ->first();
            
            if (!$order || !$order->assigned_rider_user_id) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found or no rider assigned'
                ], 404);
            }
            
            $riderId = $order->assigned_rider_user_id;
            
            // Get the delivery timestamp for this order
            $deliveryEvent = \DB::table('t_crm_order_status_history')
                ->where('order_id', $orderId)
                ->where('status_code', 'delivered')
                ->orderBy('id', 'asc')
                ->first();
            
            if (!$deliveryEvent) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order has not been delivered yet'
                ], 400);
            }
            
            $deliveredAt = \Carbon\Carbon::parse($deliveryEvent->changed_at);
            
            // Find the previous event: either the previous delivery by this rider, or the ride start
            // Look for the most recent delivery before this one by the same rider on the same date
            $prevDelivery = \DB::table('t_crm_order_status_history as osh')
                ->join('t_crm_prod_order as prev_o', 'prev_o.id', '=', 'osh.order_id')
                ->where('prev_o.assigned_rider_user_id', $riderId)
                ->where('osh.status_code', 'delivered')
                ->where('osh.changed_at', '<', $deliveryEvent->changed_at)
                ->whereDate('osh.changed_at', $deliveredAt->toDateString())
                ->where('osh.order_id', '!=', $orderId)
                ->orderBy('osh.changed_at', 'desc')
                ->select('osh.changed_at', 'osh.order_id', 'prev_o.order_number')
                ->first();
            
            if ($prevDelivery) {
                $journeyStartTime = \Carbon\Carbon::parse($prevDelivery->changed_at);
                $journeyStartLabel = "After delivering #{$prevDelivery->order_number}";
            } else {
                // No previous delivery - use ride start (first GPS point of the day or first 'start' source)
                $firstGps = \DB::table('t_ops_rider_location')
                    ->where('user_id', $riderId)
                    ->whereDate('captured_at', $deliveredAt->toDateString())
                    ->where('captured_at', '<', $deliveryEvent->changed_at)
                    ->orderBy('captured_at', 'asc')
                    ->first();
                
                if ($firstGps) {
                    $journeyStartTime = \Carbon\Carbon::parse($firstGps->captured_at);
                    $journeyStartLabel = "Day start";
                } else {
                    // No GPS data before delivery
                    $journeyStartTime = $deliveredAt->copy()->subMinutes(30);
                    $journeyStartLabel = "~30 min before delivery (no earlier GPS)";
                }
            }
            
            $journeyEndTime = $deliveredAt;
            
            // ⭐ Get GPS trail between journey start and end (reuse trail filtering logic)
            $rawReadings = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->whereBetween('captured_at', [$journeyStartTime, $journeyEndTime])
                ->orderBy('captured_at')
                ->select('latitude', 'longitude', 'accuracy', 'captured_at', 'source')
                ->get();
            
            if ($rawReadings->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'order_id' => $orderId,
                    'order_number' => $order->order_number,
                    'rider_name' => $order->rider_name,
                    'journey_start' => $journeyStartTime->format('h:i A'),
                    'journey_end' => $journeyEndTime->format('h:i A'),
                    'journey_start_label' => $journeyStartLabel,
                    'total_duration_minutes' => (int) round($journeyStartTime->diffInMinutes($journeyEndTime)),
                    'trail' => [],
                    'stops' => [],
                    'summary' => [
                        'total_distance_km' => 0,
                        'moving_time_minutes' => 0,
                        'stopped_time_minutes' => 0,
                        'stop_count' => 0,
                        'avg_speed_kmh' => 0,
                    ],
                    'message' => 'No GPS data for this journey segment'
                ]);
            }
            
            // Step 1: Filter out low accuracy readings
            $filtered = $rawReadings->filter(function($loc) {
                $accuracy = (float)($loc->accuracy ?? 0);
                return $accuracy > 0 && $accuracy <= 50;
            });
            
            if ($filtered->isEmpty()) {
                $filtered = $rawReadings->sortBy('accuracy')->take(max(1, intval($rawReadings->count() * 0.5)));
            }
            
            // Step 2: Deduplicate same-second readings (keep best accuracy)
            $deduped = collect();
            $grouped = $filtered->groupBy(function($loc) {
                return substr($loc->captured_at, 0, 19);
            });
            foreach ($grouped as $timestamp => $group) {
                $best = $group->sortBy(function($loc) {
                    return (float)($loc->accuracy ?? 999);
                })->first();
                $deduped->push($best);
            }
            $deduped = $deduped->sortBy('captured_at')->values();
            
            // Step 3: Filter impossible speed jumps (>150 km/h)
            $readings = collect();
            $prev = null;
            foreach ($deduped as $loc) {
                if ($prev === null) {
                    $readings->push($loc);
                    $prev = $loc;
                    continue;
                }
                $distance = $this->haversineDistance(
                    (float)$prev->latitude, (float)$prev->longitude,
                    (float)$loc->latitude, (float)$loc->longitude
                );
                $timeDiff = abs(\Carbon\Carbon::parse($loc->captured_at)->diffInSeconds(\Carbon\Carbon::parse($prev->captured_at)));
                if ($timeDiff > 0) {
                    $speedKmh = ($distance / 1000) / ($timeDiff / 3600);
                    if ($speedKmh <= 150) {
                        $readings->push($loc);
                        $prev = $loc;
                    }
                } else if ($distance < 100) {
                    $readings->push($loc);
                    $prev = $loc;
                }
            }
            $readings = $readings->values();
            
            // ⭐ Detect stops (>3 min within 50m radius)
            $stops = [];
            $currentStop = null;
            $stopThresholdMeters = 50;
            $stopThresholdSeconds = 180; // 3 minutes
            
            for ($i = 0; $i < $readings->count(); $i++) {
                $point = $readings[$i];
                
                if ($currentStop === null) {
                    // Start a potential stop
                    $currentStop = [
                        'start_idx' => $i,
                        'center_lat' => (float)$point->latitude,
                        'center_lng' => (float)$point->longitude,
                        'start_time' => $point->captured_at,
                        'end_time' => $point->captured_at,
                        'point_count' => 1,
                    ];
                } else {
                    $dist = $this->haversineDistance(
                        $currentStop['center_lat'], $currentStop['center_lng'],
                        (float)$point->latitude, (float)$point->longitude
                    );
                    
                    if ($dist <= $stopThresholdMeters) {
                        // Still within stop radius
                        $currentStop['end_time'] = $point->captured_at;
                        $currentStop['point_count']++;
                    } else {
                        // Moved away - check if previous cluster was a stop
                        $durationSecs = \Carbon\Carbon::parse($currentStop['start_time'])
                            ->diffInSeconds(\Carbon\Carbon::parse($currentStop['end_time']));
                        
                        if ($durationSecs >= $stopThresholdSeconds) {
                            $durationMins = (int) round($durationSecs / 60);
                            $stops[] = [
                                'latitude' => $currentStop['center_lat'],
                                'longitude' => $currentStop['center_lng'],
                                'start_time' => \Carbon\Carbon::parse($currentStop['start_time'])->format('h:i A'),
                                'end_time' => \Carbon\Carbon::parse($currentStop['end_time'])->format('h:i A'),
                                'duration_minutes' => $durationMins,
                                'duration_display' => $durationMins >= 60 
                                    ? floor($durationMins / 60) . 'h ' . ($durationMins % 60) . 'min'
                                    : $durationMins . ' min',
                            ];
                        }
                        
                        // Start new potential stop
                        $currentStop = [
                            'start_idx' => $i,
                            'center_lat' => (float)$point->latitude,
                            'center_lng' => (float)$point->longitude,
                            'start_time' => $point->captured_at,
                            'end_time' => $point->captured_at,
                            'point_count' => 1,
                        ];
                    }
                }
            }
            
            // Check last cluster
            if ($currentStop) {
                $durationSecs = \Carbon\Carbon::parse($currentStop['start_time'])
                    ->diffInSeconds(\Carbon\Carbon::parse($currentStop['end_time']));
                if ($durationSecs >= $stopThresholdSeconds) {
                    $durationMins = (int) round($durationSecs / 60);
                    $stops[] = [
                        'latitude' => $currentStop['center_lat'],
                        'longitude' => $currentStop['center_lng'],
                        'start_time' => \Carbon\Carbon::parse($currentStop['start_time'])->format('h:i A'),
                        'end_time' => \Carbon\Carbon::parse($currentStop['end_time'])->format('h:i A'),
                        'duration_minutes' => $durationMins,
                        'duration_display' => $durationMins >= 60 
                            ? floor($durationMins / 60) . 'h ' . ($durationMins % 60) . 'min'
                            : $durationMins . ' min',
                    ];
                }
            }
            
            // ⭐ Calculate total distance
            $totalDistanceMeters = 0;
            for ($i = 1; $i < $readings->count(); $i++) {
                $totalDistanceMeters += $this->haversineDistance(
                    (float)$readings[$i-1]->latitude, (float)$readings[$i-1]->longitude,
                    (float)$readings[$i]->latitude, (float)$readings[$i]->longitude
                );
            }
            $totalDistanceKm = round($totalDistanceMeters / 1000, 2);
            
            // Calculate stopped time
            $totalStoppedMinutes = collect($stops)->sum('duration_minutes');
            $totalDurationMinutes = (int) round($journeyStartTime->diffInMinutes($journeyEndTime));
            $movingTimeMinutes = max(0, $totalDurationMinutes - $totalStoppedMinutes);
            
            // Average moving speed
            $avgSpeedKmh = $movingTimeMinutes > 0 
                ? round(($totalDistanceKm / ($movingTimeMinutes / 60)), 1) 
                : 0;
            
            // Format trail for response
            $trail = $readings->map(function($loc) {
                return [
                    'latitude' => (float)$loc->latitude,
                    'longitude' => (float)$loc->longitude,
                    'time' => \Carbon\Carbon::parse($loc->captured_at)->format('h:i A'),
                    'captured_at' => $loc->captured_at,
                ];
            })->values();
            
            // ETA comparison — against the promise (EtaPromiseService); the live
            // ETA only for orders that predate the dispatch log.
            $journeyPromise = \App\Services\Riders\EtaPromiseService::promisesFor([(int) $orderId])[(int) $orderId] ?? null;
            $judgeEta = $journeyPromise['promised_at'] ?? $order->estimated_delivery_at;
            $etaComparison = null;
            if ($judgeEta) {
                $estimatedTime = \Carbon\Carbon::parse($judgeEta);
                $diffMinutes = (int) round($deliveredAt->diffInMinutes($estimatedTime, false));
                $etaComparison = [
                    'estimated_at_display' => $estimatedTime->format('h:i A'),
                    'actual_at_display' => $deliveredAt->format('h:i A'),
                    'diff_minutes' => $diffMinutes,
                    'status' => $diffMinutes >= 0 ? 'early' : 'late',
                    'status_text' => $diffMinutes >= 0
                        ? ($diffMinutes == 0 ? 'On time' : "{$diffMinutes} min early")
                        : (abs($diffMinutes) . ' min late'),
                    'retimed' => !empty($journeyPromise['retimed']),
                    'retimed_by_rider' => !empty($journeyPromise['retimed_by_rider']),
                    'live_at_display' => !empty($journeyPromise['retimed']) && $journeyPromise['final_at']
                        ? \Carbon\Carbon::parse($journeyPromise['final_at'])->format('h:i A')
                        : null,
                ];
            }
            
            return response()->json([
                'success' => true,
                'order_id' => $orderId,
                'order_number' => $order->order_number,
                'rider_name' => $order->rider_name,
                'address' => trim(implode(', ', array_filter([$order->address_line1, $order->address_city]))),
                'journey_start' => $journeyStartTime->format('h:i A'),
                'journey_end' => $journeyEndTime->format('h:i A'),
                'journey_start_label' => $journeyStartLabel,
                'eta_comparison' => $etaComparison,
                'total_duration_minutes' => $totalDurationMinutes,
                'trail' => $trail,
                'trail_count' => $trail->count(),
                'raw_count' => $rawReadings->count(),
                'stops' => $stops,
                'summary' => [
                    'total_distance_km' => $totalDistanceKm,
                    'total_distance_display' => $totalDistanceKm < 1 
                        ? round($totalDistanceMeters) . 'm' 
                        : $totalDistanceKm . ' km',
                    'moving_time_minutes' => $movingTimeMinutes,
                    'moving_time_display' => $movingTimeMinutes >= 60 
                        ? floor($movingTimeMinutes / 60) . 'h ' . ($movingTimeMinutes % 60) . 'min'
                        : $movingTimeMinutes . ' min',
                    'stopped_time_minutes' => $totalStoppedMinutes,
                    'stopped_time_display' => $totalStoppedMinutes >= 60
                        ? floor($totalStoppedMinutes / 60) . 'h ' . ($totalStoppedMinutes % 60) . 'min'
                        : $totalStoppedMinutes . ' min',
                    'stop_count' => count($stops),
                    'avg_speed_kmh' => $avgSpeedKmh,
                    'total_duration_display' => $totalDurationMinutes >= 60
                        ? floor($totalDurationMinutes / 60) . 'h ' . ($totalDurationMinutes % 60) . 'min'
                        : $totalDurationMinutes . ' min',
                ],
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get delivery journey', [
                'order_id' => $orderId,
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load delivery journey: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * ⭐ LOCATION TRACKING: Get all open orders for map view
     * Supports filtering by status and rider
     * 
     * @param status - Filter by order status (comma-separated, e.g., "processing,out_for_delivery")
     * @param rider_id - Filter by specific rider (or "all" for all riders)
     */
    public function getAllOpenOrdersForMap(Request $request)
    {
        try {
            $statusFilter = $request->get('status'); // comma-separated
            $riderFilter = $request->get('rider_id'); // specific rider ID or null for all
            
            // Build query for open orders
            $excludedStatuses = ['delivered', 'completed', 'cancelled', 'refunded'];
            
            $ordersQuery = \DB::table('t_crm_prod_order as o')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
                ->whereNotIn('o.order_status', $excludedStatuses)
                // Exclude Shopify orders - match Invoices page logic
                ->where(function($q) {
                    $q->where('o.external_source', '!=', 'shopify')
                      ->orWhereNull('o.external_source');
                });
            
            // Apply status filter if provided
            if ($statusFilter && $statusFilter !== 'all') {
                $statuses = array_map('trim', explode(',', $statusFilter));
                $ordersQuery->whereIn('o.order_status', $statuses);
            }
            
            // Apply rider filter if provided
            if ($riderFilter && $riderFilter !== 'all') {
                if ($riderFilter === 'unassigned') {
                    $ordersQuery->whereNull('o.assigned_rider_user_id');
                } else {
                    $ordersQuery->where('o.assigned_rider_user_id', $riderFilter);
                }
            }
            
            $orders = $ordersQuery
                ->select([
                    'o.id',
                    'o.order_number',
                    'o.order_status as status',
                    'o.total_price',
                    'o.payment_method',
                    'o.assigned_rider_user_id as rider_id',
                    'u.fullname as rider_name',
                    // Customer info
                    'c.id as customer_id',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    'c.address1 as address',
                    'c.city',
                    // Location sources
                    'c.latitude as verified_lat',
                    'c.longitude as verified_lng',
                    'c.geocoded_latitude as geocoded_lat',
                    'c.geocoded_longitude as geocoded_lng',
                ])
                ->orderBy('o.id', 'desc')
                ->get();
            
            // Format orders with location info
            $formattedOrders = $orders->map(function($order) {
                // Determine location with priority
                $location = null;
                $locationSource = null;
                
                if ($order->verified_lat && $order->verified_lng) {
                    $location = [
                        'latitude' => (float)$order->verified_lat,
                        'longitude' => (float)$order->verified_lng,
                    ];
                    $locationSource = 'verified_location';
                } elseif ($order->geocoded_lat && $order->geocoded_lng) {
                    $location = [
                        'latitude' => (float)$order->geocoded_lat,
                        'longitude' => (float)$order->geocoded_lng,
                    ];
                    $locationSource = 'geocoded_address';
                }
                
                return [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'status' => $order->status,
                    'status_display' => ucfirst(str_replace('_', ' ', $order->status)),
                    'customer_id' => $order->customer_id,
                    'customer_name' => trim($order->customer_name) ?: 'Unknown',
                    'address' => $order->address . ($order->city ? ', ' . $order->city : ''),
                    'total' => 'PKR ' . number_format($order->total_price, 0),
                    'rider_id' => $order->rider_id,
                    'rider_name' => $order->rider_name ?: 'Unassigned',
                    'location' => $location,
                    'location_source' => $locationSource,
                ];
            });
            
            // Get unique statuses for filter
            $uniqueStatuses = $orders->pluck('status')->unique()->values();
            
            // Get riders with open orders for filter
            $ridersWithOrders = $orders
                ->filter(fn($o) => $o->rider_id)
                ->unique('rider_id')
                ->map(fn($o) => [
                    'id' => $o->rider_id,
                    'name' => $o->rider_name,
                ])
                ->values();
            
            // Count by status
            $statusCounts = $orders->groupBy('status')->map->count();
            
            // Count by rider (including unassigned)
            $riderCounts = $orders->groupBy('rider_id')->map->count();
            
            // Count unassigned orders
            $unassignedCount = $orders->filter(fn($o) => !$o->rider_id)->count();
            
            return response()->json([
                'success' => true,
                'orders' => $formattedOrders->values(),
                'summary' => [
                    'total' => $formattedOrders->count(),
                    'with_location' => $formattedOrders->filter(fn($o) => $o['location'])->count(),
                    'without_location' => $formattedOrders->filter(fn($o) => !$o['location'])->count(),
                ],
                'filters' => [
                    'statuses' => $uniqueStatuses,
                    'status_counts' => $statusCounts,
                    'riders' => $ridersWithOrders,
                    'rider_counts' => $riderCounts,
                    'unassigned_count' => $unassignedCount,
                ],
                'timestamp' => now()->toIso8601String()
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get all open orders for map', [
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load orders'
            ], 500);
        }
    }

    /**
     * ⭐ LOCATION TRACKING: Get delivery history for a specific date
     * Returns delivered orders grouped by rider with cash/online split
     * 
     * @param date - Date to get history for (YYYY-MM-DD)
     */
    public function getDeliveryHistory(Request $request)
    {
        try {
            $date = $request->get('date', now()->format('Y-m-d'));
            
            // Get all delivered orders for this date
            $orders = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as osh', function($join) use ($date) {
                    $join->on('o.id', '=', 'osh.order_id')
                         ->where('osh.status_code', '=', 'delivered')
                         ->whereDate('osh.changed_at', $date);
                })
                ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->select([
                    'o.id',
                    'o.order_number',
                    'o.total_price',
                    'o.payment_method',
                    'o.assigned_rider_user_id as rider_id',
                    'u.fullname as rider_name',
                    'osh.changed_at as delivered_at',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                ])
                ->orderBy('osh.changed_at', 'desc')
                ->get();
            
            // Get attendance for riders on this date
            $attendances = \DB::table('t_ops_attendance')
                ->whereDate('attendance_date', $date)
                ->whereNotNull('login_time')
                ->get()
                ->keyBy('user_id');
            
            // Group by rider
            $riderGroups = [];
            foreach ($orders as $order) {
                $riderId = $order->rider_id ?: 0;
                $riderName = $order->rider_name ?: 'Unassigned';
                
                if (!isset($riderGroups[$riderId])) {
                    $attendance = $attendances->get($riderId);
                    $riderGroups[$riderId] = [
                        'id' => $riderId,
                        'name' => $riderName,
                        'check_in_time' => $attendance ? \Carbon\Carbon::parse($attendance->login_time)->format('h:i A') : null,
                        'check_out_time' => $attendance && $attendance->logout_time ? \Carbon\Carbon::parse($attendance->logout_time)->format('h:i A') : null,
                        'cash_count' => 0,
                        'cash_total' => 0,
                        'online_count' => 0,
                        'online_total' => 0,
                        'delivered_count' => 0,
                        'orders' => [],
                    ];
                }
                
                $paymentMethod = strtolower($order->payment_method ?? 'cash');
                $isCash = in_array($paymentMethod, ['cash', 'cash_on_delivery', 'cod']);
                $amount = (float)$order->total_price;
                
                if ($isCash) {
                    $riderGroups[$riderId]['cash_count']++;
                    $riderGroups[$riderId]['cash_total'] += $amount;
                } else {
                    $riderGroups[$riderId]['online_count']++;
                    $riderGroups[$riderId]['online_total'] += $amount;
                }
                
                $riderGroups[$riderId]['delivered_count']++;
                $riderGroups[$riderId]['orders'][] = [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_name' => trim($order->customer_name) ?: 'Unknown',
                    'amount' => $amount,
                    'payment_type' => $isCash ? 'cash' : 'online',
                    'delivered_at' => \Carbon\Carbon::parse($order->delivered_at)->format('h:i A'),
                ];
            }
            
            // Sort riders by delivered count (highest first)
            $riders = collect($riderGroups)->sortByDesc('delivered_count')->values();
            
            // Calculate totals
            $totalDelivered = $orders->count();
            $cashTotal = $riders->sum('cash_total');
            $onlineTotal = $riders->sum('online_total');
            $cashCount = $riders->sum('cash_count');
            $onlineCount = $riders->sum('online_count');
            
            return response()->json([
                'success' => true,
                'date' => $date,
                'riders' => $riders,
                'summary' => [
                    'total_delivered' => $totalDelivered,
                    'cash_total' => $cashTotal,
                    'cash_count' => $cashCount,
                    'online_total' => $onlineTotal,
                    'online_count' => $onlineCount,
                    'grand_total' => $cashTotal + $onlineTotal,
                ],
                'timestamp' => now()->toIso8601String()
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get delivery history', [
                'date' => $request->get('date'),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load history'
            ], 500);
        }
    }

    /**
     * ⭐ HISTORY: Get list of riders (users with rider role) for history view
     */
    public function getRidersForHistory(Request $request)
    {
        try {
            // Get users with rider role (role_id that has delivery permissions)
            // For now, get all active users who have delivered orders in the last 3 months
            $threeMonthsAgo = now()->subMonths(3)->format('Y-m-d');
            
            $riders = \DB::table('t_sys_user as u')
                ->join(\DB::raw("(
                    SELECT DISTINCT o.assigned_rider_user_id as user_id,
                           COUNT(*) as total_delivered,
                           SUM(CASE WHEN LOWER(COALESCE(o.payment_method, 'cash')) IN ('cash', 'cash_on_delivery', 'cod') THEN o.total_price ELSE 0 END) as total_cash,
                           SUM(CASE WHEN LOWER(COALESCE(o.payment_method, 'cash')) NOT IN ('cash', 'cash_on_delivery', 'cod') THEN o.total_price ELSE 0 END) as total_online
                    FROM t_crm_prod_order o
                    INNER JOIN t_crm_order_status_history osh ON o.id = osh.order_id AND osh.status_code = 'delivered'
                    WHERE osh.changed_at >= '{$threeMonthsAgo}'
                    AND o.assigned_rider_user_id IS NOT NULL
                    GROUP BY o.assigned_rider_user_id
                ) as stats"), 'u.id', '=', 'stats.user_id')
                ->where('u.is_active', 1)
                ->select([
                    'u.id',
                    'u.fullname as name',
                    'stats.total_delivered',
                    'stats.total_cash',
                    'stats.total_online',
                ])
                ->orderBy('stats.total_delivered', 'desc')
                ->get();
            
            return response()->json([
                'success' => true,
                'riders' => $riders,
                'period' => [
                    'start' => $threeMonthsAgo,
                    'end' => now()->format('Y-m-d'),
                    'label' => 'Last 3 months',
                ],
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get riders for history', ['error' => $e->getMessage()]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load riders'
            ], 500);
        }
    }

    /**
     * ⭐ HISTORY: Get a specific rider's delivery history grouped by date (last 3 months)
     * Similar to rider mode's delivered orders view
     */
    public function getRiderDeliveryHistory(Request $request, $riderId)
    {
        try {
            $threeMonthsAgo = now()->subMonths(3)->format('Y-m-d');
            
            // Get rider info
            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->select('id', 'fullname as name')
                ->first();
            
            if (!$rider) {
                return response()->json([
                    'success' => false,
                    'message' => 'Rider not found'
                ], 404);
            }
            
            // ⭐ Get all delivered orders for this rider in the last 3 months
            // Use subquery to get LATEST delivered status per order (handles duplicate delivered statuses)
            $latestDeliveredSubquery = \DB::table('t_crm_order_status_history')
                ->select('order_id', \DB::raw('MAX(id) as latest_osh_id'))
                ->where('status_code', 'delivered')
                ->groupBy('order_id');
            
            $orders = \DB::table('t_crm_prod_order as o')
                ->joinSub($latestDeliveredSubquery, 'latest_osh', function($join) {
                    $join->on('o.id', '=', 'latest_osh.order_id');
                })
                ->join('t_crm_order_status_history as osh', 'osh.id', '=', 'latest_osh.latest_osh_id')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->where('o.assigned_rider_user_id', $riderId)
                ->where('osh.changed_at', '>=', $threeMonthsAgo)
                ->select([
                    'o.id',
                    'o.order_number',
                    'o.customer_id',
                    'o.total_price',
                    'o.payment_method',
                    'o.estimated_delivery_at', // ⭐ ETA from "Get Times"
                    'osh.changed_at as delivered_at',
                    \DB::raw('DATE(osh.changed_at) as delivery_date'),
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    'c.address1 as address',
                    'c.city',
                    'c.latitude as verified_lat',
                    'c.longitude as verified_lng',
                    'c.geocoded_latitude as geocoded_lat',
                    'c.geocoded_longitude as geocoded_lng',
                    'osh.delivery_latitude',
                    'osh.delivery_longitude',
                ])
                ->orderBy('osh.changed_at', 'desc')
                ->get();

            // ⭐ Judge lateness against the PROMISE, not the live ETA (which every
            //    re-dispatch overwrites — see EtaPromiseService). Absent for orders
            //    that predate the log → those keep today's behaviour.
            $etaPromises = \App\Services\Riders\EtaPromiseService::promisesFor(
                $orders->pluck('id')->all()
            );

            // Group by date
            $dateGroups = [];
            foreach ($orders as $order) {
                $dateKey = $order->delivery_date;
                
                if (!isset($dateGroups[$dateKey])) {
                    $dateGroups[$dateKey] = [
                        'date' => $dateKey,
                        'date_display' => \Carbon\Carbon::parse($dateKey)->format('D, M j, Y'),
                        'cash_count' => 0,
                        'cash_total' => 0,
                        'online_count' => 0,
                        'online_total' => 0,
                        'total_delivered' => 0,
                        'orders' => [],
                    ];
                }
                
                $paymentMethod = strtolower($order->payment_method ?? 'cash');
                $isCash = in_array($paymentMethod, ['cash', 'cash_on_delivery', 'cod']);
                $amount = (float)$order->total_price;
                
                if ($isCash) {
                    $dateGroups[$dateKey]['cash_count']++;
                    $dateGroups[$dateKey]['cash_total'] += $amount;
                } else {
                    $dateGroups[$dateKey]['online_count']++;
                    $dateGroups[$dateKey]['online_total'] += $amount;
                }
                
                $dateGroups[$dateKey]['total_delivered']++;
                
                // Determine location for map
                $location = null;
                if ($order->delivery_latitude && $order->delivery_longitude) {
                    $location = [
                        'latitude' => (float)$order->delivery_latitude,
                        'longitude' => (float)$order->delivery_longitude,
                        'source' => 'delivery_gps',
                    ];
                } elseif ($order->verified_lat && $order->verified_lng) {
                    $location = [
                        'latitude' => (float)$order->verified_lat,
                        'longitude' => (float)$order->verified_lng,
                        'source' => 'verified',
                    ];
                } elseif ($order->geocoded_lat && $order->geocoded_lng) {
                    $location = [
                        'latitude' => (float)$order->geocoded_lat,
                        'longitude' => (float)$order->geocoded_lng,
                        'source' => 'geocoded',
                    ];
                }
                
                // ⭐ Build ETA comparison — against the promise (falls back to the
                //    order's live ETA when this order has no dispatch log).
                $promise = $etaPromises[(int) $order->id] ?? null;
                $judgeEta = $promise['promised_at'] ?? $order->estimated_delivery_at;
                $etaDisplay = null;
                $etaComparison = null;
                if ($judgeEta) {
                    $estimatedTime = \Carbon\Carbon::parse($judgeEta);
                    $etaDisplay = $estimatedTime->format('h:i A');

                    $actualTime = \Carbon\Carbon::parse($order->delivered_at);
                    $diffMinutes = (int) round($actualTime->diffInMinutes($estimatedTime, false));

                    $etaComparison = [
                        'estimated_at_display' => $etaDisplay,
                        'actual_at_display' => $actualTime->format('h:i A'),
                        'diff_minutes' => $diffMinutes,
                        'status' => $diffMinutes >= 0 ? 'early' : 'late',
                        'status_text' => $diffMinutes >= 0
                            ? ($diffMinutes == 0 ? 'On time' : "{$diffMinutes} min early")
                            : (abs($diffMinutes) . ' min late'),
                        'status_emoji' => $diffMinutes >= 0 ? '✅' : '⚠️',
                        // Present only when the live ETA drifted from the promise, so a
                        // reader can see "promised 5:10, re-timed to 5:40 by the rider".
                        'retimed' => !empty($promise['retimed']),
                        'retimed_by_rider' => !empty($promise['retimed_by_rider']),
                        'live_at_display' => !empty($promise['retimed']) && $promise['final_at']
                            ? \Carbon\Carbon::parse($promise['final_at'])->format('h:i A')
                            : null,
                    ];
                }
                
                $dateGroups[$dateKey]['orders'][] = [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_id' => $order->customer_id,
                    'customer_name' => trim($order->customer_name) ?: 'Unknown',
                    'address' => trim($order->address . ($order->city ? ', ' . $order->city : '')),
                    'amount' => $amount,
                    'amount_formatted' => 'Rs. ' . number_format($amount, 0),
                    'payment_type' => $isCash ? 'cash' : 'online',
                    'delivered_at' => \Carbon\Carbon::parse($order->delivered_at)->format('h:i A'),
                    'delivered_at_raw' => $order->delivered_at, // ⭐ Raw timestamp for trail segment calculation
                    'estimated_delivery_at_display' => $etaDisplay, // ⭐ ETA time display
                    'eta_comparison' => $etaComparison, // ⭐ ETA vs actual comparison
                    'location' => $location,
                ];
            }
            
            // Sort by date (newest first) and convert to array
            $dates = collect($dateGroups)->sortByDesc('date')->values();
            
            // Calculate totals
            $totalDelivered = $orders->count();
            $cashTotal = $dates->sum('cash_total');
            $onlineTotal = $dates->sum('online_total');
            $cashCount = $dates->sum('cash_count');
            $onlineCount = $dates->sum('online_count');
            
            return response()->json([
                'success' => true,
                'rider' => $rider,
                'dates' => $dates,
                'summary' => [
                    'total_delivered' => $totalDelivered,
                    'cash_total' => $cashTotal,
                    'cash_count' => $cashCount,
                    'online_total' => $onlineTotal,
                    'online_count' => $onlineCount,
                    'grand_total' => $cashTotal + $onlineTotal,
                    'days_active' => $dates->count(),
                ],
                'period' => [
                    'start' => $threeMonthsAgo,
                    'end' => now()->format('Y-m-d'),
                ],
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get rider delivery history', [
                'rider_id' => $riderId,
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load history'
            ], 500);
        }
    }

    /**
     * DISPATCH TRACKER: Date-first delivery report with dispatch batch grouping
     * Shows all delivered orders for a date, grouped by rider then by dispatch batch.
     * Includes compliance metrics, ETA accuracy, priority sequence analysis.
     */
    public function getDateDeliveryReport(Request $request)
    {
        try {
            $user = Auth::user();
            if ($user && method_exists($user, 'hasMobilePermission')
                && $request->is('api/*')
                && !$user->hasMobilePermission('view_dispatch_tracker')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view the dispatch tracker'
                ], 403);
            }

            $date = $request->get('date', now()->format('Y-m-d'));
            $batchThresholdSeconds = 120; // Orders dispatched within 2 min = same batch

            // 1. Get all delivered orders for this date with ETA/priority/rider data + location columns
            $orders = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as osh_del', function($join) use ($date) {
                    $join->on('o.id', '=', 'osh_del.order_id')
                         ->where('osh_del.status_code', '=', 'delivered')
                         ->whereDate('osh_del.changed_at', $date);
                })
                ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->select([
                    'o.id',
                    'o.order_number',
                    'o.total_price',
                    'o.payment_method',
                    'o.assigned_rider_user_id as rider_id',
                    'u.fullname as rider_name',
                    'o.delivery_priority',
                    'o.estimated_delivery_at',
                    'o.eta_calculated_at',
                    'osh_del.changed_at as delivered_at',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    'c.city as customer_city',
                    'c.address1 as customer_address',
                    'c.delivery_region_id',
                    'osh_del.delivery_latitude',
                    'osh_del.delivery_longitude',
                    'c.latitude as verified_lat',
                    'c.longitude as verified_lng',
                    // delivery_accuracy_m only exists after the GPS-accuracy hardening SQL —
                    // selected conditionally so this report keeps working before it runs.
                    \Illuminate\Support\Facades\Schema::hasColumn('t_crm_order_status_history', 'delivery_accuracy_m')
                        ? 'osh_del.delivery_accuracy_m'
                        : \DB::raw('NULL as delivery_accuracy_m'),
                ])
                ->orderBy('osh_del.changed_at', 'asc')
                ->get();

            // 2. Get out_for_delivery timestamps for these orders
            $orderIds = $orders->pluck('id')->toArray();

            // ⭐ The promise each stop is judged against. estimated_delivery_at is
            //    rewritten by every dispatch, so the "in sequence / on time" counts
            //    below were gameable by re-dispatching. Orders with no dispatch log
            //    are absent here and keep today's behaviour.
            $etaPromises = \App\Services\Riders\EtaPromiseService::promisesFor($orderIds);

            $ofdTimestamps = [];
            if (!empty($orderIds)) {
                $ofdRows = \DB::table('t_crm_order_status_history')
                    ->whereIn('order_id', $orderIds)
                    ->where('status_code', 'out_for_delivery')
                    ->select('order_id', \DB::raw('MAX(changed_at) as ofd_at'))
                    ->groupBy('order_id')
                    ->get();
                foreach ($ofdRows as $row) {
                    $ofdTimestamps[$row->order_id] = $row->ofd_at;
                }
            }

            // 3. Get attendance for all riders on this date
            $attendances = \DB::table('t_ops_attendance')
                ->whereDate('attendance_date', $date)
                ->whereNotNull('login_time')
                ->get()
                ->keyBy('user_id');

            // 3b. Get delivery region names
            $regionMap = \DB::table('t_ops_delivery_region')
                ->where('is_active', 1)
                ->pluck('name', 'id')
                ->toArray();

            // 3c. Get office location for return-to-office detection
            $officeLocation = \DB::table('t_ops_company_locations')
                ->where('is_primary', 1)->where('is_active', 1)->first();
            $officeLat = $officeLocation ? (float)$officeLocation->latitude : null;
            $officeLng = $officeLocation ? (float)$officeLocation->longitude : null;
            $officeRadiusMeters = 300;

            // 3c. Get rider GPS trails for the day (for office-return detection)
            $riderIds = $orders->pluck('rider_id')->unique()->filter()->toArray();
            $riderGpsTrails = [];
            if ($officeLat && !empty($riderIds)) {
                $gpsPoints = \DB::table('t_ops_rider_location')
                    ->whereIn('user_id', $riderIds)
                    ->whereDate('captured_at', $date)
                    ->select('user_id', 'latitude', 'longitude', 'captured_at')
                    ->orderBy('captured_at', 'asc')
                    ->get();
                foreach ($gpsPoints as $pt) {
                    $riderGpsTrails[$pt->user_id][] = $pt;
                }
            }

            // 4. Group orders by rider
            $riderMap = [];
            foreach ($orders as $order) {
                $riderId = $order->rider_id ?: 0;
                if (!isset($riderMap[$riderId])) {
                    $attendance = $attendances->get($riderId);
                    $loginDatetime = null;
                    $logoutDatetime = null;
                    if ($attendance && $attendance->login_time) {
                        $loginDatetime = \Carbon\Carbon::parse($date . ' ' . $attendance->login_time);
                    }
                    if ($attendance && $attendance->logout_time) {
                        $logoutDatetime = \Carbon\Carbon::parse($date . ' ' . $attendance->logout_time);
                    }
                    $riderMap[$riderId] = [
                        'id' => $riderId,
                        'name' => $order->rider_name ?: 'Unassigned',
                        'login_time' => $loginDatetime ? $loginDatetime->format('h:i A') : null,
                        'logout_time' => $logoutDatetime ? $logoutDatetime->format('h:i A') : null,
                        'login_datetime' => $loginDatetime,
                        'logout_datetime' => $logoutDatetime,
                        'orders' => [],
                    ];
                }

                $paymentMethod = strtolower($order->payment_method ?? 'cash');
                $isCash = in_array($paymentMethod, ['cash', 'cash_on_delivery', 'cod']);

                // Judge against the promise; fall back to the live ETA pre-log.
                $promise = $etaPromises[(int) $order->id] ?? null;
                $judgeEta = $promise['promised_at'] ?? $order->estimated_delivery_at;
                $etaComparison = null;
                if ($judgeEta) {
                    $est = \Carbon\Carbon::parse($judgeEta);
                    $act = \Carbon\Carbon::parse($order->delivered_at);
                    $diffMin = (int) round($act->diffInMinutes($est, false));
                    $isOnTimeOrEarly = $diffMin >= 0;
                    $etaComparison = [
                        'eta_display' => $est->format('h:i A'),
                        'diff_minutes' => $diffMin,
                        'on_time' => $isOnTimeOrEarly,
                        'label' => $isOnTimeOrEarly
                            ? ($diffMin == 0 ? 'On time' : "{$diffMin}m early")
                            : (abs($diffMin) . 'm late'),
                        // Only set when a re-dispatch moved the live ETA off the promise.
                        'retimed' => !empty($promise['retimed']),
                        'retimed_by_rider' => !empty($promise['retimed_by_rider']),
                        'live_at_display' => !empty($promise['retimed']) && $promise['final_at']
                            ? \Carbon\Carbon::parse($promise['final_at'])->format('h:i A')
                            : null,
                    ];
                }

                $hasVerifiedLoc = !empty($order->verified_lat) && !empty($order->verified_lng);
                $hasDeliveryGps = !empty($order->delivery_latitude) && !empty($order->delivery_longitude);
                $deliveredAtVerified = false;
                $verificationDistance = null;
                $verificationFixCoarse = false;
                // ONE rule, every screen — see App\Services\Riders\VerifiedPinRule.
                $pinVerdict = \App\Services\Riders\VerifiedPinRule::judge(
                    $order->delivery_latitude, $order->delivery_longitude,
                    $order->verified_lat, $order->verified_lng,
                    $order->delivery_accuracy_m ?? null
                );
                if ($pinVerdict) {
                    $verificationDistance = $pinVerdict['distance_m'];
                    $deliveredAtVerified = $pinVerdict['at_verified'];
                    $verificationFixCoarse = $pinVerdict['fix_coarse'];
                }

                $riderMap[$riderId]['orders'][] = [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_name' => trim($order->customer_name) ?: 'Unknown',
                    'customer_city' => $order->customer_city,
                    'customer_address' => $order->customer_address ?: '',
                    'delivery_region' => isset($order->delivery_region_id) && isset($regionMap[$order->delivery_region_id])
                        ? $regionMap[$order->delivery_region_id] : null,
                    'amount' => (float)$order->total_price,
                    'payment_type' => $isCash ? 'cash' : 'online',
                    'delivery_priority' => $order->delivery_priority,
                    'estimated_delivery_at' => $order->estimated_delivery_at,
                    'eta_calculated_at' => $order->eta_calculated_at,
                    'delivered_at' => $order->delivered_at,
                    'delivered_at_display' => \Carbon\Carbon::parse($order->delivered_at)->format('h:i A'),
                    'eta_display' => $order->estimated_delivery_at
                        ? \Carbon\Carbon::parse($order->estimated_delivery_at)->format('h:i A') : null,
                    'dispatch_time_display' => $order->eta_calculated_at
                        ? \Carbon\Carbon::parse($order->eta_calculated_at)->format('h:i A') : null,
                    'ofd_at' => $ofdTimestamps[$order->id] ?? null,
                    'ofd_display' => isset($ofdTimestamps[$order->id])
                        ? \Carbon\Carbon::parse($ofdTimestamps[$order->id])->format('h:i A') : null,
                    'eta_comparison' => $etaComparison,
                    'was_dispatched' => !empty($order->eta_calculated_at),
                    'has_verified_location' => $hasVerifiedLoc,
                    'has_delivery_gps' => $hasDeliveryGps,
                    'delivered_at_verified' => $deliveredAtVerified,
                    'verification_distance_m' => $verificationDistance,
                    // "the GPS was vague" is a different accusation from "he was somewhere else".
                    'verification_fix_coarse' => $verificationFixCoarse,
                ];
            }

            // Helper: detect office visits between two timestamps from GPS trail
            $detectOfficeVisits = function($gpsList, $fromTime, $toTime) use ($officeLat, $officeLng, $officeRadiusMeters) {
                if (!$officeLat || !$gpsList) return [];
                $from = \Carbon\Carbon::parse($fromTime);
                $to = \Carbon\Carbon::parse($toTime);
                $nearOffice = [];
                foreach ($gpsList as $pt) {
                    $t = \Carbon\Carbon::parse($pt->captured_at);
                    if ($t->lt($from) || $t->gt($to)) continue;
                    $dist = $this->haversineDistance($officeLat, $officeLng, (float)$pt->latitude, (float)$pt->longitude);
                    if ($dist <= $officeRadiusMeters) {
                        $nearOffice[] = $t;
                    }
                }
                if (count($nearOffice) < 2) return [];
                $visits = [];
                $visitStart = $nearOffice[0];
                $visitEnd = $nearOffice[0];
                for ($i = 1; $i < count($nearOffice); $i++) {
                    if ($nearOffice[$i]->diffInMinutes($visitEnd) <= 10) {
                        $visitEnd = $nearOffice[$i];
                    } else {
                        if ($visitStart->diffInMinutes($visitEnd) >= 2) {
                            $visits[] = ['arrived' => $visitStart->format('h:i A'), 'left' => $visitEnd->format('h:i A'),
                                         'duration_min' => $visitStart->diffInMinutes($visitEnd)];
                        }
                        $visitStart = $nearOffice[$i];
                        $visitEnd = $nearOffice[$i];
                    }
                }
                if ($visitStart->diffInMinutes($visitEnd) >= 2) {
                    $visits[] = ['arrived' => $visitStart->format('h:i A'), 'left' => $visitEnd->format('h:i A'),
                                 'duration_min' => $visitStart->diffInMinutes($visitEnd)];
                }
                return $visits;
            };

            // 5. For each rider, group orders into dispatch batches
            $riders = [];
            foreach ($riderMap as $riderId => $riderData) {
                $riderOrders = collect($riderData['orders']);
                $gpsList = $riderGpsTrails[$riderId] ?? null;

                // Separate dispatched vs undispatched
                $dispatched = $riderOrders->filter(fn($o) => $o['was_dispatched']);
                $undispatched = $riderOrders->filter(fn($o) => !$o['was_dispatched'])->values();

                // Group dispatched orders into waves using OFD timestamp as primary key.
                // Orders that went OFD within 1 hour of each other = same wave.
                // Fall back to eta_calculated_at for orders with no OFD.
                $ofdWaveThresholdMinutes = 60;
                $sortedDispatched = $dispatched->sortBy(function($o) {
                    return $o['ofd_at'] ?? $o['eta_calculated_at'] ?? '9999-12-31';
                })->values();

                $batches = [];
                $currentBatch = null;
                foreach ($sortedDispatched as $order) {
                    $orderTime = $order['ofd_at']
                        ? \Carbon\Carbon::parse($order['ofd_at'])
                        : \Carbon\Carbon::parse($order['eta_calculated_at']);
                    if ($currentBatch === null) {
                        $currentBatch = ['_anchor' => $orderTime, 'orders' => [$order]];
                    } else {
                        $gap = $currentBatch['_anchor']->diffInMinutes($orderTime);
                        if ($gap <= $ofdWaveThresholdMinutes) {
                            $currentBatch['orders'][] = $order;
                        } else {
                            $batches[] = $currentBatch;
                            $currentBatch = ['_anchor' => $orderTime, 'orders' => [$order]];
                        }
                    }
                }
                if ($currentBatch !== null) {
                    $batches[] = $currentBatch;
                }

                // Resolve dispatch_time for each batch from eta_calculated_at of its orders
                foreach ($batches as &$batch) {
                    $batchCalcTimes = collect($batch['orders'])->pluck('eta_calculated_at')->filter()->unique();
                    if ($batchCalcTimes->count() === 1) {
                        $batch['dispatch_time'] = $batchCalcTimes->first();
                    } else {
                        $batch['dispatch_time'] = collect($batch['orders'])->min('eta_calculated_at')
                            ?? ($batch['orders'][0]['ofd_at'] ?? now()->toDateTimeString());
                    }
                    $batch['dispatch_time_display'] = \Carbon\Carbon::parse($batch['dispatch_time'])->format('h:i A');
                    $firstOfd = collect($batch['orders'])->pluck('ofd_at')->filter()->min();
                    $batch['ofd_time_display'] = $firstOfd ? \Carbon\Carbon::parse($firstOfd)->format('h:i A') : null;
                    unset($batch['_anchor']);
                }
                unset($batch);

                // Compute per-batch metrics + office return detection
                foreach ($batches as &$batch) {
                    $batchOrders = collect($batch['orders']);
                    $sortedByDelivery = $batchOrders->sortBy('delivered_at')->values();

                    // Planned delivery order = the sequence committed at DISPATCH,
                    // derived from each order's ETA (estimated_delivery_at) — NOT the
                    // raw delivery_priority. delivery_priority is a live counter that
                    // gets renumbered from 1 over the remaining stops whenever the
                    // rider re-orders mid-route, so a finished batch can hold duplicate
                    // priorities (two "P1"s) that misread the sequence. The ETA order
                    // is assigned once per dispatch and is stable, giving a clean 1..N
                    // planned rank. Orders without an ETA (rare — all batch orders were
                    // dispatched) fall to the end, tie-broken by priority then id.
                    $plannedOrder = $batchOrders->sortBy(function ($o) {
                        $hasEta = empty($o['estimated_delivery_at']) ? '1' : '0';
                        $eta    = $o['estimated_delivery_at'] ?? '9999-12-31 23:59:59';
                        $prio   = str_pad((string) ($o['delivery_priority'] ?? 999999), 7, '0', STR_PAD_LEFT);
                        $id     = str_pad((string) $o['id'], 12, '0', STR_PAD_LEFT);
                        return "{$hasEta}|{$eta}|{$prio}|{$id}";
                    })->values();
                    $plannedRankById = [];
                    foreach ($plannedOrder as $pi => $po) {
                        $plannedRankById[$po['id']] = $pi + 1;
                    }

                    $prioritySequenceMatch = 0;
                    $totalWithPriority = 0;
                    $prevDeliveryTime = null;
                    $timeGaps = [];
                    $officeReturns = [];

                    foreach ($sortedByDelivery as $idx => $o) {
                        // "In sequence" = delivered in its planned (dispatch) position.
                        $plannedRank = $plannedRankById[$o['id']] ?? null;
                        if ($plannedRank !== null) {
                            $totalWithPriority++;
                            if ($plannedRank === $idx + 1) {
                                $prioritySequenceMatch++;
                            }
                        }
                        if ($prevDeliveryTime !== null) {
                            $gap = \Carbon\Carbon::parse($prevDeliveryTime)->diffInMinutes(\Carbon\Carbon::parse($o['delivered_at']));
                            $timeGaps[] = $gap;
                            $visits = $detectOfficeVisits($gpsList, $prevDeliveryTime, $o['delivered_at']);
                            if (!empty($visits)) {
                                $officeReturns[] = ['after_order_idx' => $idx - 1, 'visits' => $visits];
                            }
                        }
                        $prevDeliveryTime = $o['delivered_at'];
                    }

                    $withEta = $batchOrders->filter(fn($o) => $o['eta_comparison'] !== null);
                    $onTimeCount = $withEta->filter(fn($o) => $o['eta_comparison']['on_time'])->count();

                    $firstDelivery = $sortedByDelivery->first();
                    $lastDelivery = $sortedByDelivery->last();
                    $batchDurationMin = $firstDelivery && $lastDelivery
                        ? (int) round(\Carbon\Carbon::parse($firstDelivery['delivered_at'])->diffInMinutes(\Carbon\Carbon::parse($lastDelivery['delivered_at'])))
                        : 0;

                    $batchHasVerified = $batchOrders->filter(fn($o) => $o['has_verified_location'])->count();
                    $batchDeliveredAtVerified = $batchOrders->filter(fn($o) => $o['delivered_at_verified'])->count();

                    $batch['order_count'] = $batchOrders->count();
                    $batch['eta_on_time'] = $onTimeCount;
                    $batch['eta_total'] = $withEta->count();
                    $batch['priority_match'] = $prioritySequenceMatch;
                    $batch['priority_total'] = $totalWithPriority;
                    $batch['time_gaps'] = $timeGaps;
                    $batch['batch_duration_min'] = $batchDurationMin;
                    $batch['first_delivery'] = $firstDelivery ? \Carbon\Carbon::parse($firstDelivery['delivered_at'])->format('h:i A') : null;
                    $batch['last_delivery'] = $lastDelivery ? \Carbon\Carbon::parse($lastDelivery['delivered_at'])->format('h:i A') : null;
                    $batch['office_returns'] = $officeReturns;
                    $batch['has_verified_count'] = $batchHasVerified;
                    $batch['delivered_at_verified_count'] = $batchDeliveredAtVerified;
                    $batch['orders'] = $sortedByDelivery->map(function($o, $idx) use ($plannedRankById) {
                        $o['actual_sequence'] = $idx + 1;
                        // Stable dispatch-order rank (see $plannedOrder above); both
                        // the web tracker and the mobile tracker render from this so
                        // they stay in sync.
                        $o['planned_sequence'] = $plannedRankById[$o['id']] ?? null;
                        return $o;
                    })->toArray();
                }
                unset($batch);

                // Build undispatched group
                $undispatchedGroup = null;
                if ($undispatched->count() > 0) {
                    $sortedUndispatched = $undispatched->sortBy('delivered_at')->values();
                    $undispatchedGroup = [
                        'order_count' => $undispatched->count(),
                        'orders' => $sortedUndispatched->map(function($o, $idx) {
                            $o['actual_sequence'] = $idx + 1;
                            return $o;
                        })->toArray(),
                    ];
                }

                // Rider-level metrics
                $totalOrders = $riderOrders->count();
                $dispatchedCount = $dispatched->count();
                $allWithEta = $riderOrders->filter(fn($o) => $o['eta_comparison'] !== null);
                $allOnTime = $allWithEta->filter(fn($o) => $o['eta_comparison']['on_time'])->count();

                $cashOrders = $riderOrders->filter(fn($o) => $o['payment_type'] === 'cash');
                $onlineOrders = $riderOrders->filter(fn($o) => $o['payment_type'] !== 'cash');

                $riderHasVerified = $riderOrders->filter(fn($o) => $o['has_verified_location'])->count();
                $riderDeliveredAtVerified = $riderOrders->filter(fn($o) => $o['delivered_at_verified'])->count();

                // First dispatch delay (login to first dispatch of the day)
                $firstDispatchDelay = null;
                $firstDispatchDelayDisplay = null;
                if ($riderData['login_datetime'] && $dispatched->count() > 0) {
                    $loginDt = $riderData['login_datetime'];
                    $firstDispatchDt = \Carbon\Carbon::parse($dispatched->first()['eta_calculated_at']);
                    $delayMin = (int) $loginDt->diffInMinutes($firstDispatchDt);
                    $firstDispatchDelay = $delayMin;
                    $hours = intdiv($delayMin, 60);
                    $mins = $delayMin % 60;
                    $firstDispatchDelayDisplay = $hours > 0 ? "{$hours}h {$mins}m" : "{$mins}m";
                }

                $riders[] = [
                    'id' => $riderId,
                    'name' => $riderData['name'],
                    'login_time' => $riderData['login_time'],
                    'logout_time' => $riderData['logout_time'],
                    'total_orders' => $totalOrders,
                    'dispatched_count' => $dispatchedCount,
                    'undispatched_count' => $totalOrders - $dispatchedCount,
                    'dispatch_compliance_pct' => $totalOrders > 0 ? round(($dispatchedCount / $totalOrders) * 100) : 0,
                    'eta_on_time' => $allOnTime,
                    'eta_total' => $allWithEta->count(),
                    'eta_accuracy_pct' => $allWithEta->count() > 0 ? round(($allOnTime / $allWithEta->count()) * 100) : null,
                    'num_dispatches' => count($batches),
                    'first_dispatch_delay_min' => $firstDispatchDelay,
                    'first_dispatch_delay_display' => $firstDispatchDelayDisplay,
                    'cash_count' => $cashOrders->count(),
                    'cash_total' => $cashOrders->sum('amount'),
                    'online_count' => $onlineOrders->count(),
                    'online_total' => $onlineOrders->sum('amount'),
                    'has_verified_count' => $riderHasVerified,
                    'delivered_at_verified_count' => $riderDeliveredAtVerified,
                    'dispatch_batches' => $batches,
                    'undispatched_group' => $undispatchedGroup,
                ];
            }

            // Sort riders by total orders desc
            usort($riders, fn($a, $b) => $b['total_orders'] <=> $a['total_orders']);

            // Day-level summary
            $totalDelivered = $orders->count();
            $totalDispatched = $orders->filter(fn($o) => !empty($o->eta_calculated_at))->count();
            $allEta = $orders->filter(fn($o) => !empty($o->estimated_delivery_at));
            $allOnTimeDay = 0;
            foreach ($allEta as $o) {
                $est = \Carbon\Carbon::parse($o->estimated_delivery_at);
                $act = \Carbon\Carbon::parse($o->delivered_at);
                if ($act->diffInMinutes($est, false) >= 0) $allOnTimeDay++;
            }

            $dayHasVerified = $orders->filter(fn($o) => !empty($o->verified_lat) && !empty($o->verified_lng))->count();
            $dayDeliveredAtVerified = 0;
            foreach ($orders as $o) {
                // This counter used to have its own hardcoded 1000 m while the rows it summarises
                // used 500 m — so the day header could read "15/15 at verified" above rows carrying
                // ⚠ marks. It now asks the same class as everything else.
                $v = \App\Services\Riders\VerifiedPinRule::judge(
                    $o->delivery_latitude, $o->delivery_longitude,
                    $o->verified_lat, $o->verified_lng,
                    $o->delivery_accuracy_m ?? null
                );
                if ($v && $v['at_verified']) $dayDeliveredAtVerified++;
            }

            // ⭐ LIVE ongoing-dispatch tracking — only meaningful for "today".
            //    Additive; the delivered report above is unchanged.
            $ongoing = [];
            if ($date === now()->format('Y-m-d')) {
                $ongoing = $this->buildOngoingDispatchTracking($officeLat, $officeLng, $officeRadiusMeters);
            }

            return response()->json([
                'success' => true,
                'date' => $date,
                'date_display' => \Carbon\Carbon::parse($date)->format('D, M j, Y'),
                'riders' => $riders,
                'ongoing' => $ongoing,
                'summary' => [
                    'total_delivered' => $totalDelivered,
                    'total_dispatched' => $totalDispatched,
                    'total_undispatched' => $totalDelivered - $totalDispatched,
                    'dispatch_compliance_pct' => $totalDelivered > 0 ? round(($totalDispatched / $totalDelivered) * 100) : 0,
                    'eta_on_time' => $allOnTimeDay,
                    'eta_total' => $allEta->count(),
                    'eta_accuracy_pct' => $allEta->count() > 0 ? round(($allOnTimeDay / $allEta->count()) * 100) : null,
                    'total_riders' => count($riders),
                    'cash_total' => $orders->filter(fn($o) => in_array(strtolower($o->payment_method ?? 'cash'), ['cash','cash_on_delivery','cod']))->sum('total_price'),
                    'online_total' => $orders->filter(fn($o) => !in_array(strtolower($o->payment_method ?? 'cash'), ['cash','cash_on_delivery','cod']))->sum('total_price'),
                    'has_verified_count' => $dayHasVerified,
                    'delivered_at_verified_count' => $dayDeliveredAtVerified,
                ],
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to get date delivery report', [
                'date' => $request->get('date'),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load dispatch report'
            ], 500);
        }
    }

    /**
     * Build the LIVE "ongoing dispatch" tracking for the Dispatch Tracker.
     *
     * Covers every angle the store needs while deliveries are in progress:
     *   - on_route               : has dispatched OFD orders still out
     *   - waiting_at_office      : has undispatched OFD orders, GPS within office
     *   - left_without_dispatch  : has undispatched OFD orders, fresh GPS > office radius (the warning)
     *   - returning              : currently away but moving toward office (approx ETA to office shown)
     *   - at_office / away_unknown / idle : fallbacks
     *
     * Orders are grouped by their dispatch wave (eta_calculated_at). Each
     * dispatched stop shows its 10-min ETA window; per-wave delivered/total
     * progress is included. Distances use the PRIMARY office (haversine);
     * the office ETA is a cheap distance/speed approximation (no extra Google
     * calls) — labelled approximate on the UI.
     *
     * Purely additive: only computed for "today"; never touches the delivered
     * report logic.
     */
    private function buildOngoingDispatchTracking(?float $officeLat, ?float $officeLng, int $radiusMeters = 300, bool $useGoogleEta = true): array
    {
        // Current out_for_delivery orders are inherently "now".
        $ofd = \DB::table('t_crm_prod_order as o')
            ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
            ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
            ->where('o.order_status', 'out_for_delivery')
            ->whereNotNull('o.assigned_rider_user_id')
            ->select([
                'o.id', 'o.order_number', 'o.total_price', 'o.payment_method',
                'o.assigned_rider_user_id as rider_id', 'u.fullname as rider_name',
                'o.delivery_priority', 'o.estimated_delivery_at', 'o.eta_calculated_at',
                \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                'c.city as customer_city',
            ])
            ->get();

        /**
         * ⚠⚠ NOT AN EARLY RETURN ANY MORE. This board is built from out-for-delivery orders, so
         *    with none it used to answer "nobody is doing anything" — which is right about
         *    DELIVERIES and wrong about the day. A rider taking a bike to the workshop very
         *    often has no orders at all (that is WHY he was sent), and on a quiet morning the
         *    whole fleet can be order-free. Returning early here made the workshop status
         *    invisible in exactly the case it exists for, and it looked like it worked because
         *    a busy fleet still showed it.
         *
         * ⭐ So: nothing to compute per-order, but the workshop pass below still runs.
         */
        $ofdIsEmpty = $ofd->isEmpty();

        $riderIds = $ofd->pluck('rider_id')->unique()->filter()->values()->all();

        // Latest fresh GPS points (last 15 min), newest first per rider.
        $gpsByRider = [];
        if (!empty($riderIds)) {
            $pts = \DB::table('t_ops_rider_location')
                ->whereIn('user_id', $riderIds)
                ->where('captured_at', '>=', now()->subMinutes(15))
                ->orderBy('captured_at', 'desc')
                ->select('user_id', 'latitude', 'longitude', 'captured_at')
                ->get();
            foreach ($pts as $p) {
                $gpsByRider[$p->user_id][] = $p;
            }
        }

        // Latest heartbeat per rider in the last 24h — for GPS freshness display
        // ("now" / "15 min ago" / stale), independent of the 15-min fresh window
        // used for status logic above.
        $lastSeenByRider = [];
        if (!empty($riderIds)) {
            $hb = \DB::table('t_ops_rider_location')
                ->select('user_id', \DB::raw('MAX(captured_at) as last_at'))
                ->whereIn('user_id', $riderIds)
                ->where('captured_at', '>=', now()->subHours(24))
                ->groupBy('user_id')
                ->get();
            foreach ($hb as $h) {
                $t = \Carbon\Carbon::parse($h->last_at);
                $age = abs(now()->diffInMinutes($t));
                $lastSeenByRider[$h->user_id] = [
                    'gps_age_minutes' => $age,
                    'gps_age_text' => $t->diffForHumans(),
                    'gps_is_fresh' => $age <= 6,
                ];
            }
        }

        // Delivered-today counts per dispatch wave (rider + eta_calculated_at) → progress.
        $today = now()->format('Y-m-d');
        $deliveredByWave = [];
        if (!empty($riderIds)) {
            $delivered = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as osh', function ($j) use ($today) {
                    $j->on('o.id', '=', 'osh.order_id')
                      ->where('osh.status_code', '=', 'delivered')
                      ->whereDate('osh.changed_at', $today);
                })
                ->whereIn('o.assigned_rider_user_id', $riderIds)
                ->whereNotNull('o.eta_calculated_at')
                ->select('o.assigned_rider_user_id as rid', 'o.eta_calculated_at as calc_at',
                    \DB::raw('COUNT(DISTINCT o.id) as c'))
                ->groupBy('o.assigned_rider_user_id', 'o.eta_calculated_at')
                ->get();
            foreach ($delivered as $d) {
                $deliveredByWave[$d->rid][(string) $d->calc_at] = (int) $d->c;
            }
        }

        // ⭐ SINGLE SOURCE OF TRUTH for "left without dispatch". This live board, the
        //    dispatch-tracker popup and the mobile alert/banner ALL derive the flag
        //    from detectLeftWithoutDispatch() — computed once here, per rider — so no
        //    surface can ever disagree (the divergence that made a mid-run rider show
        //    the red warning on web while the mobile alert correctly stayed silent).
        //    Fail-open: if the detector errors, nobody is flagged (never a false alarm).
        $leftFlags = [];
        try {
            $leftFlags = $this->detectLeftWithoutDispatch($riderIds);
        } catch (\Throwable $e) {
            \Log::warning('buildOngoingDispatchTracking: left-without-dispatch check failed (non-fatal)', ['error' => $e->getMessage()]);
        }

        /**
         * 🔧⭐⭐ WHO IS ON A WORKSHOP ERRAND RIGHT NOW (owner ask, 10-Sep-2026).
         *
         * ⚠⚠ THE FALSE ALARM THIS ENDS. Every status on this board is derived from dispatch
         *    counts and distance to the office, so a rider sent to the workshop — doing exactly
         *    what he was told — read as "📍 Away (GPS stale)", and if he had undispatched
         *    orders on his name he tripped the RED "⚠ Left without dispatch" warning. The board
         *    was accusing him of walking off the job.
         *
         * ⭐ ONE call for the whole board (`tripsFor`), not one per rider — this runs on every
         *   poll of the live card. And ONE derivation shared with the riders-map, the store
         *   phone, the van boards and the dispatch guard, so no two screens can disagree about
         *   where he is.
         */
        /**
         * ⚠⚠ NOT `$riderIds` — that is only the men with orders out. The rider this feature is
         *    ABOUT is very often the one with nothing on his plate: he has no deliveries, so he
         *    was sent to the workshop. Asking only about the busy ones would have hidden exactly
         *    the case the owner asked for, and it would have looked like it worked.
         */
        $trips = [];
        try {
            $trips = app(\App\Services\Riders\WorkshopVisitService::class)->tripsFor(
                \DB::table('t_ops_workshop_visit')
                    ->whereDate('visit_date', \Carbon\Carbon::today()->format('Y-m-d'))
                    ->whereIn('status', \App\Services\Riders\WorkshopVisitService::LIVE_STATUSES)
                    ->pluck('user_id')->map(fn ($x) => (int) $x)->all()
            );
        } catch (\Throwable $e) {
            \Log::warning('buildOngoingDispatchTracking: workshop trips failed (non-fatal)', ['error' => $e->getMessage()]);
        }

        $isCashMethod = fn($m) => in_array(strtolower($m ?? 'cash'), ['cash', 'cash_on_delivery', 'cod']);

        $out = [];
        foreach (($ofdIsEmpty ? [] : $ofd->groupBy('rider_id')) as $rid => $orders) {
            $riderName = $orders->first()->rider_name ?: "Rider #{$rid}";
            $dispatched = $orders->filter(fn($o) => !empty($o->eta_calculated_at));
            $undispatched = $orders->filter(fn($o) => empty($o->eta_calculated_at));

            // Distance to office + approach detection + approx office ETA.
            $distance = null; $approaching = null; $gpsFresh = false; $etaToOfficeMin = null;
            $latest = $gpsByRider[$rid][0] ?? null;
            if ($latest && $officeLat && $officeLng) {
                $gpsFresh = true;
                $distance = (int) round($this->haversineDistance($officeLat, $officeLng, (float) $latest->latitude, (float) $latest->longitude));
                // Compare against an earlier fresh point to infer direction.
                $prev = null;
                foreach (($gpsByRider[$rid] ?? []) as $pp) {
                    if ($pp->captured_at !== $latest->captured_at) { $prev = $pp; break; }
                }
                if ($prev) {
                    $prevDist = $this->haversineDistance($officeLat, $officeLng, (float) $prev->latitude, (float) $prev->longitude);
                    $approaching = $distance < ($prevDist - 30); // moving >30 m closer
                }
                if ($distance > $radiusMeters) {
                    // ~22 km/h average city speed (approximation, no Google call).
                    $etaToOfficeMin = max(1, (int) round(($distance / 1000) / 22 * 60));
                }
            }

            $atOffice = ($distance !== null && $distance <= $radiusMeters);

            // "Returning to office" — a single cached Google ETA, only when the
            // rider has finished the orders in their current dispatch (the
            // helper enforces: no pending dispatched OFD + >=1 dispatched
            // delivered today + away + fresh GPS).
            $returnInfo = null;
            if ($gpsFresh && !$atOffice) {
                $returnInfo = $this->getReturnToOfficeInfo((int) $rid, $officeLat, $officeLng, $radiusMeters, $useGoogleEta);
            }

            // Status priority. The "left without dispatch" decision is DELEGATED to
            // the single canonical rule ($leftFlags, from detectLeftWithoutDispatch)
            // so this board / the popup / the mobile alert can never disagree.
            //   Ordering: left-without-dispatch (alarm) > returning > on-route/at-office
            //             (has a dispatched wave) > waiting/away (has orders, no wave).
            // Key consequence — the fix for the reported confusion: a rider MID-RUN
            // (has pending dispatched OFD) is never "left without dispatch", even with
            // next-wave orders queued, because the canonical rule requires ZERO pending
            // dispatched. Those queued orders still surface via undispatched_count.
            $status = 'idle';
            $flaggedLeft = !empty($leftFlags[(int) $rid]['flagged']);
            /**
             * ⭐⭐ THE WORKSHOP OUTRANKS EVERYTHING, including the red warning.
             *
             * A man riding to the workshop has left the office without dispatching, which is
             * precisely what `left_without_dispatch` looks for — and here it is not a warning,
             * it is the instruction he was given. Checking the trip FIRST is what turns a false
             * accusation into a useful line, and it is the whole reason this rung exists.
             */
            $trip = $trips[(int) $rid] ?? null;
            if ($trip && !empty($trip['is_active'])) {
                $status = $trip['state'] === \App\Services\Riders\WorkshopVisitService::TRIP_AT
                    ? 'at_workshop' : 'workshop_en_route';
            } elseif ($flaggedLeft) {
                $status = 'left_without_dispatch';
            } elseif ($returnInfo) {
                $status = 'returning';
            } elseif ($dispatched->count() > 0) {
                // Actively carrying a dispatched wave (queued next-wave orders, if any,
                // are reported separately as undispatched_count — not as an alarm).
                $status = $atOffice ? 'at_office' : 'on_route';
            } elseif ($undispatched->count() > 0) {
                // Has orders to dispatch but isn't flagged: at the office (about to
                // dispatch) or away without a confirmed office-departure.
                $status = $atOffice ? 'waiting_at_office' : 'away_unknown';
            }

            // Dispatched OFD orders grouped by wave (eta_calculated_at).
            $batches = [];
            foreach ($dispatched->groupBy('eta_calculated_at') as $calcAt => $bo) {
                $bo = $bo->sortBy(fn($o) => $o->delivery_priority ?? 999)->values();
                $deliveredCnt = $deliveredByWave[$rid][(string) $calcAt] ?? 0;
                $batches[] = [
                    'dispatch_time' => $calcAt,
                    'dispatch_time_display' => \Carbon\Carbon::parse($calcAt)->format('h:i A'),
                    'pending_count' => $bo->count(),
                    'delivered_count' => $deliveredCnt,
                    'total_count' => $bo->count() + $deliveredCnt,
                    'orders' => $bo->map(function ($o) use ($isCashMethod) {
                        $eta = $o->estimated_delivery_at ? \Carbon\Carbon::parse($o->estimated_delivery_at) : null;
                        return [
                            'order_number' => $o->order_number,
                            'customer_name' => trim($o->customer_name) ?: 'Unknown',
                            'customer_city' => $o->customer_city,
                            'priority' => $o->delivery_priority,
                            'amount' => (float) $o->total_price,
                            'payment_type' => $isCashMethod($o->payment_method) ? 'cash' : 'online',
                            'eta_window' => $eta
                                ? ($eta->format('h:i A') . ' – ' . $eta->copy()->addMinutes(10)->format('h:i A'))
                                : null,
                        ];
                    })->values()->all(),
                ];
            }
            usort($batches, fn($a, $b) => strcmp((string) $a['dispatch_time'], (string) $b['dispatch_time']));

            // Undispatched OFD orders (the "forgot / next dispatch" group).
            $undispatchedList = $undispatched
                ->sortBy(fn($o) => $o->delivery_priority ?? 999)
                ->values()
                ->map(function ($o) use ($isCashMethod) {
                    return [
                        'order_number' => $o->order_number,
                        'customer_name' => trim($o->customer_name) ?: 'Unknown',
                        'customer_city' => $o->customer_city,
                        'priority' => $o->delivery_priority,
                        'amount' => (float) $o->total_price,
                        'payment_type' => $isCashMethod($o->payment_method) ? 'cash' : 'online',
                    ];
                })->all();

            $out[] = [
                'rider_id' => $rid,
                'rider_name' => $riderName,
                'status' => $status,
                // 🔧 The errand itself, for the label: where, since when, and the ETA while he
                //    is still on the road. Additive — an older page ignores it and simply shows
                //    the status word it already knows.
                'workshop_trip' => $trip,
                'ofd_total' => $orders->count(),
                'dispatched_count' => $dispatched->count(),
                'undispatched_count' => $undispatched->count(),
                'distance_to_office_m' => $distance,
                'distance_to_office_display' => $distance !== null
                    ? ($distance < 1000 ? $distance . ' m' : round($distance / 1000, 1) . ' km')
                    : null,
                'approaching_office' => $approaching,
                'gps_fresh' => $gpsFresh,
                'gps_age_minutes' => $lastSeenByRider[$rid]['gps_age_minutes'] ?? null,
                'gps_age_text' => $lastSeenByRider[$rid]['gps_age_text'] ?? null,
                'eta_to_office_min' => $etaToOfficeMin,
                'return_to_office' => $returnInfo,
                'dispatch_batches' => $batches,
                'undispatched_orders' => $undispatchedList,
            ];
        }

        // ⭐ Riders who finished EVERYTHING (delivered their dispatch, no OFD
        //    orders left) but are still away — show their return-to-office ETA
        //    so the store knows when they'll be back. They aren't in the OFD
        //    loop above, so add them here.
        $ofdRiderIds = $ofd->pluck('rider_id')->unique()->filter()->map(fn($v) => (int) $v)->all();
        $finishedDispatchRiders = \DB::table('t_crm_prod_order as o')
            ->join('t_crm_order_status_history as osh', function ($j) use ($today) {
                $j->on('o.id', '=', 'osh.order_id')
                  ->where('osh.status_code', '=', 'delivered')
                  ->whereDate('osh.changed_at', $today);
            })
            ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
            ->whereNotNull('o.eta_calculated_at')
            ->whereNotNull('o.assigned_rider_user_id')
            ->select('o.assigned_rider_user_id as rid', 'u.fullname as rider_name',
                \DB::raw('COUNT(DISTINCT o.id) as delivered_count'))
            ->groupBy('o.assigned_rider_user_id', 'u.fullname')
            ->get();
        // GPS freshness for finished riders (they pass the fresh-GPS gate in
        // getReturnToOfficeInfo, but fetch the exact last-seen for display).
        $finishedSeenByRider = [];
        $finishedIds = $finishedDispatchRiders->pluck('rid')->filter()->map(fn($v) => (int) $v)->all();
        if (!empty($finishedIds)) {
            $hb2 = \DB::table('t_ops_rider_location')
                ->select('user_id', \DB::raw('MAX(captured_at) as last_at'))
                ->whereIn('user_id', $finishedIds)
                ->where('captured_at', '>=', now()->subHours(24))
                ->groupBy('user_id')
                ->get();
            foreach ($hb2 as $h) {
                $t = \Carbon\Carbon::parse($h->last_at);
                $age = abs(now()->diffInMinutes($t));
                $finishedSeenByRider[$h->user_id] = [
                    'gps_age_minutes' => $age,
                    'gps_age_text' => $t->diffForHumans(),
                ];
            }
        }
        /**
         * 🔧⭐⭐ THE RIDER WITH NOTHING ON HIS PLATE. This board is built from orders, so a man
         *    who has no deliveries today appears on it only if he delivered earlier (the loop
         *    below). But "no orders" is the commonest reason he is at the workshop in the first
         *    place — so without this pass the feature would be invisible for exactly the rider
         *    it was asked for, on the exact card the owner pointed at.
         *
         * ⚠ Added BEFORE the finished-riders loop so its `already covered` check sees them and
         *   cannot draw the same man twice as "returning".
         */
        $ofdRiderIds = array_values(array_unique(array_merge($ofdRiderIds, array_map(
            fn ($r) => (int) $r['rider_id'], $out))));
        foreach ($trips as $tuid => $trip) {
            $tuid = (int) $tuid;
            if (empty($trip['is_active']) || in_array($tuid, $ofdRiderIds, true)) continue;
            $out[] = [
                'rider_id' => $tuid,
                'rider_name' => $trip['rider_name']
                    ?? (\DB::table('t_sys_user')->where('id', $tuid)->value('fullname') ?: "Rider #{$tuid}"),
                'status' => $trip['state'] === \App\Services\Riders\WorkshopVisitService::TRIP_AT
                    ? 'at_workshop' : 'workshop_en_route',
                'workshop_trip' => $trip,
                'ofd_total' => 0,
                'dispatched_count' => 0,
                'undispatched_count' => 0,
                'distance_to_office_m' => null,
                'distance_to_office_display' => null,
                'approaching_office' => null,
                'gps_fresh' => true,
                'gps_age_minutes' => null,
                'gps_age_text' => null,
                'eta_to_office_min' => null,
                'return_to_office' => null,
                'dispatch_batches' => [],
                'undispatched_orders' => [],
            ];
            $ofdRiderIds[] = $tuid;
        }

        foreach ($finishedDispatchRiders as $fr) {
            $frid = (int) $fr->rid;
            if (in_array($frid, $ofdRiderIds, true)) {
                continue; // Already covered (still has OFD orders, or is at the workshop).
            }
            /**
             * ⚠⚠ $useGoogleEta MUST be passed here (Sep-2026 fix). Omitting it fell back to
             *    the parameter default TRUE, so the 30s-polling live-status board fired a
             *    BLOCKING Google Directions call (up to ~15s) for every finished rider on a
             *    cold cache — the single biggest cause of "the riders map loads slowly".
             *    The OFD loop above always passed it correctly; this loop was the leak.
             *    With false, an un-warmed rider shows the distance approximation for one
             *    poll and the precise value lands on the next one: getRidersLiveStatus
             *    already queues every row whose source === 'approx' into $warmRiderIds and
             *    warms it in app()->terminating(), so NO extra warming code is needed here.
             */
            $returnInfo = $this->getReturnToOfficeInfo($frid, $officeLat, $officeLng, $radiusMeters, $useGoogleEta);
            if (!$returnInfo) {
                continue; // At office / not fresh / not eligible.
            }
            $out[] = [
                'rider_id' => $frid,
                'rider_name' => $fr->rider_name ?: "Rider #{$frid}",
                'status' => 'returning',
                'ofd_total' => 0,
                'dispatched_count' => 0,
                'undispatched_count' => 0,
                'delivered_today' => (int) $fr->delivered_count,
                'distance_to_office_m' => $returnInfo['distance_meters'],
                'distance_to_office_display' => $returnInfo['distance_display'],
                'approaching_office' => null,
                'gps_fresh' => true,
                'gps_age_minutes' => $finishedSeenByRider[$frid]['gps_age_minutes'] ?? null,
                'gps_age_text' => $finishedSeenByRider[$frid]['gps_age_text'] ?? null,
                'eta_to_office_min' => $returnInfo['minutes'],
                'return_to_office' => $returnInfo,
                'dispatch_batches' => [],
                'undispatched_orders' => [],
            ];
        }

        // Order: warnings first, then biggest workload.
        /**
         * ⚠ The two workshop rungs sit just BELOW the red warning and above everything else: a
         *   dispatcher scanning this list needs to see "do not load this man" before he sees
         *   who is busiest, but not before a genuine left-without-dispatch alarm.
         */
        $rank = [
            'left_without_dispatch' => 0,
            'workshop_en_route' => 1, 'at_workshop' => 1,
            'waiting_at_office' => 2, 'returning' => 3,
            'on_route' => 4, 'at_office' => 5, 'away_unknown' => 6, 'idle' => 7,
        ];
        usort($out, function ($a, $b) use ($rank) {
            $ra = $rank[$a['status']] ?? 9;
            $rb = $rank[$b['status']] ?? 9;
            if ($ra !== $rb) return $ra <=> $rb;
            return $b['ofd_total'] <=> $a['ofd_total'];
        });

        return $out;
    }

    /**
     * Lightweight per-rider LIVE status for the Orders → Riders tab cards.
     *
     * Returns two maps keyed by rider id:
     *   - gps:      { age_minutes, age_text, is_fresh }  (GPS heartbeat freshness)
     *   - dispatch: { status, ofd_total, dispatched_count, undispatched_count,
     *                 distance_to_office_display, return_to_office }
     *
     * Reuses buildOngoingDispatchTracking() so the status (on_route /
     * waiting_at_office / left_without_dispatch / returning + office ETA) is
     * identical to the Dispatch Tracker. Cheap + cached Google call inside.
     */
    public function getRidersLiveStatus(Request $request)
    {
        // IMPORTANT: each block below is independently guarded. The board's core
        // data — who's CHECKED IN and their GPS freshness — comes from two cheap,
        // reliable queries. Previously these shared ONE try/catch with the much
        // heavier dispatch tracking (which makes an external Google ETA call), so
        // any timeout/exception there returned checked_in=[] and the board showed
        // "No riders checked in" even though riders were checked in. We now keep
        // the cheap data intact regardless of what happens to dispatch tracking.

        // 1) Checked-in riders (attendance login today, not yet logged out).
        $checkedIn = [];
        try {
            $checkedIn = \DB::table('t_ops_attendance')
                ->whereDate('attendance_date', now()->format('Y-m-d'))
                ->whereNotNull('login_time')
                ->whereNull('logout_time')
                ->pluck('user_id')
                ->map(fn($v) => (int) $v)
                ->values()
                ->all();
        } catch (\Throwable $e) {
            \Log::warning('getRidersLiveStatus: checked_in query failed', ['error' => $e->getMessage()]);
        }

        // 2) GPS freshness — latest heartbeat per rider in last 24h.
        $gps = [];
        try {
            $rows = \DB::table('t_ops_rider_location')
                ->select('user_id', \DB::raw('MAX(captured_at) as last_at'))
                ->where('captured_at', '>=', now()->subHours(24))
                ->groupBy('user_id')
                ->get();
            foreach ($rows as $r) {
                $t = \Carbon\Carbon::parse($r->last_at);
                $age = abs(now()->diffInMinutes($t));
                $gps[$r->user_id] = [
                    'age_minutes' => $age,
                    'age_text' => $t->diffForHumans(),
                    'is_fresh' => $age <= 6,
                ];
            }
        } catch (\Throwable $e) {
            \Log::warning('getRidersLiveStatus: gps query failed', ['error' => $e->getMessage()]);
        }

        // 3) Dispatch status + "back to office" ETA. This is the heavier part and
        //    is the part that reuses the cached Google Directions estimate (the
        //    same single-estimate model used when an order is dispatched — NOT a
        //    per-second live call). It's isolated in its own try/catch so any
        //    failure here degrades only the status/ETA columns and can NEVER blank
        //    out the checked-in roster computed above.
        //
        //    useGoogleEta=false on this hot path means: reuse the WARM cached
        //    Google ETA if it's already there, otherwise show a quick distance
        //    approximation — we never fire a fresh (blocking, up-to-15s) Google
        //    call inside this 30s-polling request. The precise Google value is
        //    instead computed out-of-band below, so it appears on the next poll.
        $dispatch = [];
        try {
            $office = $this->getPrimaryOfficeCoords();
            $officeLat = $office['lat'] ?? null;
            $officeLng = $office['lng'] ?? null;

            $ongoing = $this->buildOngoingDispatchTracking($officeLat, $officeLng, 300, false);
            $warmRiderIds = [];
            foreach ($ongoing as $o) {
                $dispatch[$o['rider_id']] = [
                    'status' => $o['status'],
                    'ofd_total' => $o['ofd_total'],
                    'dispatched_count' => $o['dispatched_count'],
                    'undispatched_count' => $o['undispatched_count'],
                    'distance_to_office_display' => $o['distance_to_office_display'] ?? null,
                    'return_to_office' => $o['return_to_office'] ?? null,
                    /**
                     * 🔧 The errand itself — where, since when, the ETA — so the card can print
                     *    the SERVER's sentence instead of composing its own.
                     * ⚠ This map is a hand-written subset of the row, so a new key has to be
                     *   added HERE as well as on the row; leaving it out is a silent drop that
                     *   looks like the feature not working.
                     */
                    'workshop_trip' => $o['workshop_trip'] ?? null,
                ];
                // source 'approx' means the precise Google ETA isn't cached yet —
                // queue this rider to be warmed after the response is sent.
                $rto = $o['return_to_office'] ?? null;
                if (is_array($rto) && ($rto['source'] ?? null) === 'approx') {
                    $warmRiderIds[] = (int) $o['rider_id'];
                }
            }

            // Warm the precise Google "back to office" ETA OUT OF BAND (after the
            // response is flushed) and cache it, so it surfaces on the next 30s
            // poll and persists for the cache window. Same cached single-estimate
            // approach used at dispatch time — no blocking on this request, and no
            // per-second live polling. Fully non-fatal.
            if (!empty($warmRiderIds) && $officeLat && $officeLng) {
                $idsToWarm = array_values(array_unique($warmRiderIds));
                app()->terminating(function () use ($idsToWarm, $officeLat, $officeLng) {
                    foreach ($idsToWarm as $rid) {
                        try {
                            $this->getReturnToOfficeInfo($rid, $officeLat, $officeLng, 300, true);
                        } catch (\Throwable $e) {
                            // non-fatal — the board keeps showing the approximation
                        }
                    }
                });
            }
        } catch (\Throwable $e) {
            \Log::warning('getRidersLiveStatus: dispatch tracking failed (non-fatal)', ['error' => $e->getMessage()]);
        }

        return response()->json([
            'success' => true,
            'gps' => $gps,
            'dispatch' => $dispatch,
            'checked_in' => $checkedIn,
            'timestamp' => now()->toIso8601String(),
        ]);
    }

    /**
     * Get monthly attendance (reuses salary service logic for consistency)
     */
    public function getMonthlyAttendance(Request $request)
    {
        try {
            $user = Auth::user();

            // Get month parameter (default to current month)
            $month = $request->input('month', now()->format('Y-m-01'));

            // Establish date range (limit to today for current month)
            $startDate = date('Y-m-01', strtotime($month));
            $endDate = date('Y-m-t', strtotime($month));
            $today = date('Y-m-d');
            $effectiveEndDate = ($endDate > $today) ? $today : $endDate;

            // Attempt to reuse salary service for summary (matches salary section)
            $salaryService = new \App\Services\HR\SalaryCalculationService();
            $salaryData = $salaryService->calculateSalary($user->id, $month, []);

            // Prepare attendance records (used by both primary and fallback flows)
            $attendanceRecords = \DB::table('t_ops_attendance')
                ->where('user_id', $user->id)
                ->whereBetween('attendance_date', [$startDate, $effectiveEndDate])
                ->get()
                ->keyBy('attendance_date');

            // ⭐ Sep-6 2026 (owner ruling) — a rider sees the same per-day overtime and the same
            // review standing management sees. Both fetched ONCE for the range, never per day.
            // ⚠ The bonus DAYS those minutes may earn are NOT sent here; they stay hidden until
            // management grants them (API/PayrollController::mySalary).
            $otByDateOwn = [];
            $dayReviewOwn = [];
            try {
                $otByDateOwn = app(\App\Services\HR\OvertimeService::class)
                    ->overtimeForRange($user->id, $startDate, $effectiveEndDate, true)['details'] ?? [];
            } catch (\Throwable $e) { $otByDateOwn = []; }
            try {
                $drSvc = app(\App\Services\HR\DayReviewService::class);
                foreach ($drSvc->forRange($user->id, $startDate, $effectiveEndDate) as $k => $rv) {
                    // Only what a rider needs: the verdict and what it did, never who decided it.
                    $dayReviewOwn[$k] = [
                        'verdict' => $rv['verdict'],
                        'waived'  => $rv['waived_minutes'],
                        'reason'  => $rv['reason'],
                    ];
                }
            } catch (\Throwable $e) { $dayReviewOwn = []; }

            // Get approved/pending leave requests for the month
            $leaveRequests = \App\Models\Request\RequestModel::where('requester_user_id', $user->id)
                ->whereIn('status', ['approved', 'pending'])
                ->whereHas('category', function ($q) {
                    $q->where('category_code', 'leave');
                })
                ->where(function ($q) use ($startDate, $effectiveEndDate) {
                    $q->whereBetween('leave_start_date', [$startDate, $effectiveEndDate])
                      ->orWhereBetween('leave_end_date', [$startDate, $effectiveEndDate])
                      ->orWhere(function ($q2) use ($startDate, $effectiveEndDate) {
                          $q2->where('leave_start_date', '<=', $startDate)
                             ->where('leave_end_date', '>=', $effectiveEndDate);
                      });
                })
                ->get();

            // Build a set of dates that are on leave. Half-days are kept SEPARATE — a half-day
            // is a present day (0.5 leave) that must never swallow the attendance record.
            $leaveDates = [];
            $halfDates = [];
            foreach ($leaveRequests as $req) {
                if ($req->leave_start_date && $req->leave_end_date) {
                    $isHalfReq = strtolower((string) ($req->leave_type ?? '')) === 'half_day';
                    $d = new \DateTime($req->leave_start_date);
                    $dEnd = new \DateTime($req->leave_end_date);
                    while ($d <= $dEnd) {
                        $dateStr = $d->format('Y-m-d');
                        if ($dateStr >= $startDate && $dateStr <= $effectiveEndDate) {
                            if ($isHalfReq) { $halfDates[$dateStr] = true; }
                            else { $leaveDates[$dateStr] = true; }
                        }
                        $d->modify('+1 day');
                    }
                }
            }

            // Get user's shift utilities (per-day resolution happens inside the loop).
            $shiftService = new \App\Services\ShiftResolutionService();

            // Build calendar history of working days with attendance/absent
            $history = [];
            $currentDate = new \DateTime($startDate);
            $endDateTime = new \DateTime($effectiveEndDate);

            while ($currentDate <= $endDateTime) {
                $dateStr = $currentDate->format('Y-m-d');
                // Classify the day with dayKind() — the SAME per-day test the web Month tab,
                // the salary calc and the year absent-count use. The old isWorkingDay() only
                // knew weekly off-days + public holidays: it never checked the hire date, so
                // every pre-joining weekday fell through as a no-login working day and a new
                // joiner saw a red "Absent" for days before they started (web showed the
                // correct "Not joined"). It also ignored manager-tagged "not needed" days.
                // The summary above was ALREADY dayKind-based via the salary service, so the
                // screen contradicted itself — "Absent 0" in the header, red Absent rows below.
                // Before-hire / off / holiday days are simply not listed, exactly as off-days
                // and holidays already weren't, so installed APKs render this correctly as-is.
                $kind = $shiftService->dayKind($user->id, $dateStr);
                $isWorkingDay = ($kind !== 'off' && $kind !== 'holiday' && $kind !== 'not_joined');

                if ($isWorkingDay) {
                    if (isset($attendanceRecords[$dateStr])) {
                        $record = $attendanceRecords[$dateStr];
                        
                        // Determine detailed status: Check leave FIRST, then attendance.
                        // A manager-tagged "not needed" day with no login is paid as present and
                        // must never read as Absent (same rule as the web filler + salary calc).
                        $status = ($kind === 'not_needed') ? 'not_needed' : 'absent';
                        $lateMinutes = 0;
                        // ⚠ Reset per DAY. Only the login branch below sets it, so leaving it
                        // alone would let a leave / half / absent day inherit the previous
                        // iteration's raw and waived minutes and report another day's figures.
                        $lateDay = null;

                        // ✅ FIRST: Check if this date is on leave (even if they have an attendance record)
                        if (isset($leaveDates[$dateStr])) {
                            $status = 'on_leave';
                        } elseif (isset($halfDates[$dateStr]) && $record->login_time) {
                            // Half-day: present, 0.5 leave, no lateness counted (owner's rule).
                            $status = 'half_day';
                        } elseif ($record->login_time) {
                            // Late through the ONE rule (ShiftResolutionService::lateForDay) —
                            // frozen snapshot first, else the shift in effect ON THIS DATE, and
                            // minutes a manager has waived come off. Sep-6 2026: this used to be
                            // a fourth inline copy of the formula.
                            $lateDay = $shiftService->lateForDay(
                                $user->id, $dateStr, $record->login_time,
                                $record->late_minutes, $record->expected_shift_start, false
                            );
                            $lateMinutes = $lateDay['minutes'];
                            // ⚠⚠ THE RIDER'S OWN SCREEN follows the EFFECTIVE minutes, unlike
                            // every manager surface, which follows the raw figure.
                            // Riders are deliberately told nothing about the review layer
                            // (owner ruling), so a day whose lateness a manager forgave must
                            // simply read as a normal day here. Keying the badge off `raw`
                            // instead produced a red "Late" chip reading "0 min" — a
                            // contradiction he has no way to interpret, on the one screen
                            // where nobody can explain it to him.
                            $status = $lateMinutes > 0 ? 'late' : ($record->logout_time ? 'completed' : 'in_progress');
                        }
                        // else: status stays as initialised above — 'not_needed' on a tagged day,
                        // otherwise 'absent' (no login and not on leave)
                        
                        $meterStart = $record->meter_start ? (float)$record->meter_start : null;
                        $meterEnd = $record->meter_end ? (float)$record->meter_end : null;
                        $meterDistance = null;
                        $meterWarning = null;
                        // ⭐⭐ A SPLIT DAY HAS NO SINGLE DISTANCE (Aug-22 2026) — and this is the
                        //    per-km rate's input, i.e. real money.
                        //
                        // ⚠⚠ `meter_end - meter_start` silently assumes both readings are of the
                        //    SAME machine. On a day the rider opened on his own bike (6,434) and
                        //    closed on the van (73,959) it computes 67,525 km, and at Rs 9.5/km the
                        //    app would offer a Rs 641,487 fuel claim. The existing >1,000 km check
                        //    is only a WARNING — the app renders the claim button on
                        //    `meter_distance > 0` and never blocks on the warning.
                        //
                        // ⭐ Step C's stamps make this detectable for the first time: when the two
                        //   ends name different machines there is no honest distance, so the
                        //   distance stays NULL — which is exactly what makes the app hide the
                        //   claim button — and the rider is told why in words he can act on.
                        $startVid = $record->meter_start_vehicle_id ?? null;
                        $endVid   = $record->meter_end_vehicle_id ?? null;
                        if ($meterStart !== null && $meterEnd !== null
                            && $startVid && $endVid && (int) $startVid !== (int) $endVid) {
                            $meterWarning = 'Your start and end readings are from two different '
                                . 'vehicles, so the distance cannot be worked out. Ask your manager '
                                . 'to correct the readings.';
                        } elseif ($meterStart !== null && $meterEnd !== null) {
                            if ($meterEnd < $meterStart) {
                                $meterWarning = 'End reading (' . number_format($meterEnd) . ') is less than start (' . number_format($meterStart) . '). Please check your readings.';
                            } else {
                                $meterDistance = round($meterEnd - $meterStart, 1);
                                if ($meterDistance > 1000) {
                                    $meterWarning = 'Distance ' . number_format($meterDistance) . ' km seems unusually high. Please verify readings.';
                                }
                            }
                        }

                        $history[] = [
                            'id' => $record->id,
                            'date' => $record->attendance_date,
                            'date_formatted' => $currentDate->format('D, M d, Y'),
                            'login_time' => $record->login_time,
                            'login_time_formatted' => $record->login_time ? date('h:i A', strtotime($record->login_time)) : null,
                            'logout_time' => $record->logout_time,
                            'logout_time_formatted' => $record->logout_time ? date('h:i A', strtotime($record->logout_time)) : null,
                            'status' => $status,
                            'late_minutes' => $lateMinutes,
                            // ⭐⭐ Sep-6 2026 (owner ruling) — a rider now sees the SAME per-day
                            // figures management sees, and whether each has been checked yet.
                            // The bonus DAYS those overtime minutes might earn are deliberately
                            // NOT here: those are hidden until management actually grants them
                            // (see API/PayrollController::mySalary).
                            'late_raw_minutes' => $lateDay['raw'] ?? $lateMinutes,
                            'late_waived_minutes' => $lateDay['waived'] ?? 0,
                            'overtime_minutes' => (int) ($otByDateOwn[$dateStr]['minutes'] ?? 0),
                            'overtime_meta' => $otByDateOwn[$dateStr] ?? null,
                            'late_review' => $dayReviewOwn[$dateStr . '|late'] ?? null,
                            'overtime_review' => $dayReviewOwn[$dateStr . '|overtime'] ?? null,
                            'notes' => $record->notes,
                            'picture_start' => $record->picture_start ? $this->getMeterPictureUrl($record->picture_start) : null,
                            'picture_end' => $record->picture_end ? $this->getMeterPictureUrl($record->picture_end) : null,
                            'meter_start' => $meterStart,
                            'meter_end' => $meterEnd,
                            'meter_distance' => $meterDistance,
                            'meter_warning' => $meterWarning,
                            'checkin_latitude' => $record->checkin_latitude ?? null,
                            'checkin_longitude' => $record->checkin_longitude ?? null,
                            'checkin_distance_from_base' => $record->checkin_distance_from_base ?? null,
                            'is_remote_checkin' => $record->is_remote_checkin ?? 0,
                            'checkout_latitude' => $record->checkout_latitude ?? null,
                            'checkout_longitude' => $record->checkout_longitude ?? null,
                        ];
                    } else {
                        // No attendance record - check if on leave. (A half-day without any
                        // check-in shouldn't exist — apply blocks it — but if data drifted,
                        // show it as leave rather than a false Absent.) A tagged "not needed"
                        // day is paid as present, so it gets its own status, never Absent.
                        $status = (isset($leaveDates[$dateStr]) || isset($halfDates[$dateStr]))
                            ? 'on_leave'
                            : (($kind === 'not_needed') ? 'not_needed' : 'absent');
                        
                        $history[] = [
                            'id' => null,
                            'date' => $dateStr,
                            'date_formatted' => $currentDate->format('D, M d, Y'),
                            'login_time' => null,
                            'login_time_formatted' => null,
                            'logout_time' => null,
                            'logout_time_formatted' => null,
                            'status' => $status,
                            'late_minutes' => 0,
                            'notes' => null,
                        ];
                    }
                }

                $currentDate->modify('+1 day');
            }

            // Sort by date descending
            usort($history, function ($a, $b) {
                return strcmp($b['date'], $a['date']);
            });

            // Total late minutes for the month — per-date + snapshot aware (same helper
            // as the salary calc and the web reports, so all screens agree).
            $lateOtOwn = $shiftService->sumLateOvertimeMinutes($user->id, $startDate, $effectiveEndDate);
            $totalLateMinutes = $lateOtOwn['late_minutes'];
            // ⭐ Sep-2026 (owner ruling) — the rider sees his own overtime MINUTES and what
            // was forgiven, the same figures management reads. ⚠ NOT the bonus DAYS those
            // minutes might earn: those stay hidden until management grants them.
            $totalOvertimeOwn = array_sum(array_map(fn ($d) => (int) ($d['minutes'] ?? 0), $otByDateOwn));
            $totalLateWaivedOwn = (int) ($lateOtOwn['late_waived_minutes'] ?? 0);
            $totalLateRawOwn = (int) ($lateOtOwn['late_raw_minutes'] ?? $totalLateMinutes);

            // Build summary: prefer salary service; otherwise compute a safe fallback
            if ($salaryData['success']) {
                $summary = [
                    'working_days' => $salaryData['working_days'],
                    'present_days' => $salaryData['present_days'],
                    'absent_days' => $salaryData['absent_days'],
                    'leave_days' => $salaryData['leave_days'],
                    'late_minutes' => $totalLateMinutes,
                    'late_waived_minutes' => $totalLateWaivedOwn,
                    'late_raw_minutes' => $totalLateRawOwn,
                    'overtime_minutes' => $totalOvertimeOwn,
                ];
            } else {
                // Fallback path: no salary profile/config in production etc.
                // Compute working days using shift service and attendance + leave requests.
                $workingDays = $shiftService->calculateWorkingDays($user->id, $startDate, $effectiveEndDate);

                $presentDays = 0;
                foreach ($attendanceRecords as $rec) {
                    if (!empty($rec->login_time)) {
                        $presentDays++;
                    }
                }

                // Leave days from approved/pending leave requests overlapping the range
                $leaveDays = 0;
                $leaveRequests = \App\Models\Request\RequestModel::where('requester_user_id', $user->id)
                    ->whereIn('status', ['approved', 'pending'])
                    ->whereHas('category', function ($q) {
                        $q->where('category_code', 'leave');
                    })
                    ->where(function ($q) use ($startDate, $effectiveEndDate) {
                        $q->whereBetween('leave_start_date', [$startDate, $effectiveEndDate])
                          ->orWhereBetween('leave_end_date', [$startDate, $effectiveEndDate])
                          ->orWhere(function ($q2) use ($startDate, $effectiveEndDate) {
                              $q2->where('leave_start_date', '<=', $startDate)
                                 ->where('leave_end_date', '>=', $effectiveEndDate);
                          });
                    })
                    ->get();

                foreach ($leaveRequests as $req) {
                    if ($req->leave_start_date && $req->leave_end_date) {
                        // Half-day = 0.5 (matches the yearly balance weighting).
                        $w = strtolower((string) ($req->leave_type ?? '')) === 'half_day' ? 0.5 : 1;
                        $d = new \DateTime($req->leave_start_date);
                        $dEnd = new \DateTime($req->leave_end_date);
                        while ($d <= $dEnd) {
                            $dateStr = $d->format('Y-m-d');
                            if ($dateStr >= $startDate && $dateStr <= $effectiveEndDate) {
                                $leaveDays += $w;
                            }
                            $d->modify('+1 day');
                        }
                    }
                }

                // ⚠⚠ ABSENT MUST COME FROM THE ONE ENGINE, even on this fallback path.
                // `workingDays − present − leave` is NOT the company definition of absent: it
                // counts 'not needed' days (paid as present) as absences, and it lets a leave
                // that fell on an off day cancel a real working day. A rider whose base salary
                // is not set lands here, so he was shown a DIFFERENT absent count from the one
                // payroll deducts against — the exact split-brain this fallback is supposed to
                // avoid. AttendanceYearService is the same source the manager's page and
                // computeRow() use; only if it throws do we fall back to arithmetic.
                $absentDays = null;
                try {
                    $absentDays = count((new \App\Services\HR\AttendanceYearService())
                        ->absentWorkingDates($user->id, $shiftService, $startDate, $effectiveEndDate));
                } catch (\Throwable $eAbs) {
                    \Log::warning('Rider month: canonical absent count failed', ['user_id' => $user->id, 'error' => $eAbs->getMessage()]);
                }
                $summary = [
                    'working_days' => $workingDays,
                    'present_days' => $presentDays,
                    'absent_days' => $absentDays !== null ? $absentDays : max(0, $workingDays - $presentDays - $leaveDays),
                    'leave_days' => $leaveDays,
                    'late_minutes' => $totalLateMinutes,
                    'late_waived_minutes' => $totalLateWaivedOwn,
                    'late_raw_minutes' => $totalLateRawOwn,
                    'overtime_minutes' => $totalOvertimeOwn,
                ];

                \Log::warning('Monthly attendance fallback used', [
                    'user_id' => $user->id,
                    'month' => $month,
                    'reason' => $salaryData['error'] ?? 'unknown'
                ]);
            }

            // Leave balance for the CONFIGURED cycle (not the calendar year). The
            // LeavePolicyService is the single source of truth shared with the web app, so
            // the rider sees the same numbers as the manager. `leave_balance` is additive
            // (old APKs ignore it); `leaves_taken_year` is kept for back-compat but now
            // correctly reflects the cycle, fixing the old calendar-year mismatch.
            $leaveBal = (new \App\Services\HR\LeavePolicyService())->balance((int) $user->id);
            $summary['leave_balance'] = $leaveBal;
            $summary['leaves_taken_year'] = $leaveBal['taken_total'];
            $summary['leaves_year'] = (int) substr($leaveBal['cycle_start'], 0, 4);
            $summary['cycle_start'] = $leaveBal['cycle_start'];
            $summary['cycle_end'] = $leaveBal['cycle_end'];
            // "Absent this year" for the rider — the SAME shared definition the manager's
            // Month tab uses (AttendanceYearService), so the two numbers can't disagree.
            // leave_dates_year = the exact approved-leave dates behind "Used X of 10",
            // so tapping the balance opens the list instantly (no extra request).
            try {
                $yearSvc = new \App\Services\HR\AttendanceYearService();
                // Compute the absent DATES once → count is its size (identical to yearAbsentDays),
                // and the list feeds the rider's tappable "This year absent" drill-down.
                $yearEndEff = min(date('Y-m-d'), (string) $leaveBal['cycle_end']);
                $absentDates = $yearSvc->absentWorkingDates(
                    (int) $user->id,
                    new \App\Services\ShiftResolutionService(),
                    (string) $leaveBal['cycle_start'],
                    $yearEndEff
                );
                $summary['absent_days_year'] = count($absentDates);
                $summary['absent_dates_year'] = array_map(fn($d) => ['date' => $d], $absentDates);

                $leaveMap = $yearSvc->approvedLeaveDates((int) $user->id, $leaveBal['cycle_start'], $leaveBal['cycle_end']);
                ksort($leaveMap);
                $summary['leave_dates_year'] = array_map(
                    fn($d, $type) => ['date' => $d, 'type' => $type],
                    array_keys($leaveMap), array_values($leaveMap)
                );
            } catch (\Throwable $e) {
                $summary['absent_days_year'] = 0;
                $summary['absent_dates_year'] = [];
                $summary['leave_dates_year'] = [];
            }

            // Fetch petrol rate for this user from their assigned rate group
            $petrolRate = null;
            $userRateGroup = DB::table('t_fin_petrol_rate_group')
                ->where('is_active', 1)
                ->get()
                ->first(function ($group) use ($user) {
                    if (empty($group->user_ids)) return false;
                    $ids = array_map('trim', explode(',', $group->user_ids));
                    return in_array((string) $user->id, $ids);
                });

            if ($userRateGroup) {
                $petrolRate = (float) $userRateGroup->rate;
            }

            // Fetch existing petrol requests for this user in this month.
            // A day can have BOTH a rejected request and a fresh resubmission; keyBy keeps
            // the LAST row per attendance_id, so order rejected/cancelled FIRST and active
            // (pending/approved) LAST → the active one wins the map (the rider sees his live
            // request, not the stale rejection). Tie-break newest id last.
            $petrolRequests = DB::table('t_req_master as r')
                ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                ->where('c.category_code', 'expense')
                ->where('r.requester_user_id', $user->id)
                ->where('r.expense_category', 'Petrol')
                ->whereNotNull('r.attendance_id')
                ->whereBetween('r.expense_date', [$startDate, $endDate])
                ->select('r.id', 'r.attendance_id', 'r.expense_date', 'r.amount', 'r.status',
                         'r.meter_distance', 'r.petrol_rate',
                         // ⭐ Which machine each claim was for — a mixed day can carry one
                         //   per machine, so the per-leg rows below need to tell them apart.
                         //   Selected defensively: absent before batch 13, and this endpoint
                         //   must not 500 on a server that has not run it.
                         ...(\Illuminate\Support\Facades\Schema::hasColumn('t_req_master', 'vehicle_id')
                             ? ['r.vehicle_id'] : []))
                ->orderByRaw("(r.status IN ('rejected','cancelled')) DESC")
                ->orderBy('r.id')
                ->get();

            // ⚠ The flat map keeps its original shape and meaning — one entry per
            //   attendance day, the ACTIVE claim winning — because every APK in the field
            //   reads it that way. The per-machine detail rides in `vehicles[]` below.
            $petrolRequestsByDay = $petrolRequests->keyBy('attendance_id');

            // ── 🏍️🚚 WHAT HE ACTUALLY RODE THAT DAY, PER MACHINE ────────────────────
            // ⭐⭐ ONE meter pair per rider-day is the storage reality, and it stopped being
            //    the whole truth the day a rider started arriving on his own bike and taking
            //    the van out mid-shift. `RiderDayLegs` reassembles the day from the reading
            //    stamps and the vehicle meter log; everything below simply renders it.
            // ⭐ ONE definition — the rider's own window, shared with the claim guard.
            $petrolWindowDays = (new \App\Services\Riders\FuelClaimRules())->petrolWindowDays(false);
            $windowStart = date('Y-m-d', strtotime('-' . $petrolWindowDays . ' days'));

            try {
                $legsByDate = (new \App\Services\Riders\RiderDayLegs())->forRange(
                    (int) $user->id, $startDate, $effectiveEndDate, $attendanceRecords->toArray()
                );
            } catch (\Throwable $legErr) {
                \Log::warning('day legs skipped (non-fatal)', ['error' => $legErr->getMessage()]);
                $legsByDate = [];
            }

            // Claims already filed, keyed by day+machine, so a leg can say for itself
            // whether it has been claimed and what happened to it.
            $claimByDayVehicle = [];
            foreach ($petrolRequests as $pr) {
                $vid = $pr->vehicle_id ?? null;
                if ($vid) $claimByDayVehicle[$pr->attendance_id . '|' . (int) $vid] = $pr;
            }

            // ⭐⭐ HIS OWN MACHINE — so he can record ITS meter on a day the company van
            //    owns his attendance readings (owner ruling q2, Aug-27 2026). Only when
            //    there is exactly one, because "add my bike's meter" has to mean one bike.
            $ownVehicle = null;
            try {
                $ownIds = (new \App\Services\Riders\RiderDayLegs())->ownMachineIdsFor((int) $user->id);
                if (count($ownIds) === 1) {
                    $ov = DB::table('t_ops_vehicle')->where('id', $ownIds[0])
                        ->first(['id', 'reg_no', 'nickname']);
                    if ($ov) {
                        $lbl = trim((string) ($ov->reg_no ?? '')) ?: trim((string) ($ov->nickname ?? ''));
                        $ownVehicle = ['id' => (int) $ov->id, 'label' => $lbl ?: ('Vehicle #' . $ov->id)];
                    }
                }
            } catch (\Throwable $ovErr) { $ownVehicle = null; }

            foreach ($history as &$h) {
                // ⚠ A per-km claim is ANCHORED to an attendance row — that is what makes
                //   it the self-auditing kind and what the one-per-day rule keys on. A
                //   day he never checked in on can still carry a meter-log leg (a manager
                //   recording the machine), but offering a claim button there would post
                //   a claim with no attendance id, which the server then treats as a flat
                //   cash claim and refuses. Show nothing rather than a door that fails.
                if (empty($h['id'])) continue;

                $legs = $legsByDate[$h['date']] ?? [];
                if (!$legs) continue;

                $inWindow = $h['date'] >= $windowStart;
                $rows = [];
                foreach ($legs as $l) {
                    $claim = $claimByDayVehicle[$h['id'] . '|' . $l['vehicle_id']] ?? null;
                    // An unstamped claim for this day belongs to whichever machine the
                    // day's own kilometres are on — the pre-stamping shape.
                    if (!$claim && empty($l['is_company'])) {
                        $flat = $petrolRequestsByDay[$h['id']] ?? null;
                        if ($flat && empty($flat->vehicle_id)) $claim = $flat;
                    }
                    $active = $claim && !in_array($claim->status, ['rejected', 'cancelled'], true);

                    $rows[] = [
                        'vehicle_id'   => $l['vehicle_id'],
                        'label'        => $l['label'],
                        'is_company'   => (bool) $l['is_company'],
                        // 'bike' | 'van' — the phone draws the machine from this, not from
                        // is_company (which is about whose fuel it is). See RiderDayLegs.
                        'vtype'        => $l['vtype'] ?? 'bike',
                        'km'           => $l['km'],
                        'meter_start'  => $l['meter_start'],
                        'meter_end'    => $l['meter_end'],
                        'source'       => $l['source'],
                        'entered_by_name' => $l['entered_by_name'],
                        'self_entered'    => (bool) $l['self_entered'],
                        // ⭐ SERVER-AUTHORITATIVE: the app renders a claim button on this
                        //   flag alone, so a rider can never be offered a claim the server
                        //   is about to refuse (the exact shape of today's bug).
                        'can_claim'    => (empty($l['is_company']) && ($l['km'] ?? 0) > 0
                                           && $petrolRate > 0 && $inWindow && !$active),
                        'claim_status' => $claim->status ?? null,
                        'claim_id'     => $claim->id ?? null,
                        'claim_amount' => $claim->amount ?? null,
                    ];
                }
                $h['vehicles'] = $rows;

                // ⭐ May he add his OWN vehicle's readings for this day? Only inside the
                //   window a claim could still be made for, and only while his own bike
                //   has no complete pair yet — a manager-entered row is read-only to him.
                $ownLeg = $ownVehicle
                    ? \App\Services\Riders\RiderDayLegs::forVehicle($legs, $ownVehicle['id'])
                    : null;
                $h['can_add_own_meter'] = (bool) ($ownVehicle && $inWindow
                    && (!$ownLeg || ($ownLeg['km'] ?? null) === null));

                // ── the installed APK, which knows nothing about legs ──────────────
                // ⚠⚠ It renders the claim button on `meter_distance > 0` and the amount on
                //    that number alone. On a van day that number was the VAN's distance —
                //    Rs 1,586.50 of per-km allowance for fuel the firm had already bought.
                //    Correcting the field corrects the phone, with no new APK.
                // ⚠ Scoped to riders on the per-km scheme (they alone have a rate). A
                //   company-bike rider is in no rate group, so his kilometres display
                //   exactly as they always have.
                if (!($petrolRate > 0)) continue;

                $claimable = \App\Services\Riders\RiderDayLegs::claimable($legs);
                $hasCompany = \App\Services\Riders\RiderDayLegs::hasCompany($legs);

                if (count($claimable) === 1) {
                    // Show HIS vehicle's numbers, so distance, readings and the amount
                    // the app computes from them can never disagree.
                    $leg = $claimable[0];
                    $h['meter_start']    = (float) $leg['meter_start'];
                    $h['meter_end']      = (float) $leg['meter_end'];
                    $h['meter_distance'] = (float) $leg['km'];
                    $h['meter_warning']  = $hasCompany
                        ? ('Showing ' . $leg['label'] . ' — your own vehicle. The other '
                           . 'vehicle\'s kilometres are recorded against it.')
                        : $h['meter_warning'];
                } elseif ($hasCompany && !$claimable) {
                    $company = null;
                    foreach ($legs as $l) { if (!empty($l['is_company'])) { $company = $l; break; } }
                    $h['meter_distance'] = null;      // this is what hides the button
                    $h['meter_warning']  = 'These kilometres are on ' . ($company['label'] ?? 'a company vehicle')
                        . ', and the company buys its fuel — so there is no per-kilometre claim '
                        . 'for them.';
                }
            }
            unset($h);

            // 🏢 Company-bike riders: show the SAME work/off-duty split management
            // sees on the Fleet tab. Off-duty km (the ride home and personal use)
            // is company-funded fuel, so the rider seeing his own number is the
            // cheapest form of accountability. Own-bike riders get nothing extra —
            // their off-shift riding is their own business.
            // ⭐⭐ Sep-30 — THE ENGINE'S NUMBER, not a second sum. This block used to chain his
            //   own readings inside the month (`monthBikeUsage`), which missed the first night
            //   of every month, threw away a two-machine day, and showed OWN-bike km as company
            //   off-duty (Danish 360 vs the office's 379; Asim 305 on his own bike). Same keys
            //   (days/work_km/offduty_km/total_km/offduty_pct), so the INSTALLED APK draws the
            //   corrected figures with no update; `nights` is additive for the next APK.
            //   Shown when he had a company machine THIS MONTH, not by what he holds today.
            // ⚠ The engine has no opinion on him (or is off) ⇒ the old path, exactly as before.
            $bikeUsage = $this->engineBikeUsage($user->id, substr($startDate, 0, 7));
            if ($bikeUsage === false) {
                $bikeUsage = $this->ridesCompanyBike($user->id)
                    ? $this->monthBikeUsage($user->id, $startDate, $endDate) : null;
            }

            return response()->json([
                'success' => true,
                'month' => $month,
                'month_formatted' => date('F Y', strtotime($month)),
                'summary' => $summary,
                'history' => $history,
                'petrol_rate' => $petrolRate,
                // ⚠ MUST stay the attendance-id-keyed MAP — every APK in the field does
                //   `petrol_requests[record.id]`, and handing it a plain list would break
                //   the status badge on every day at once.
                'petrol_requests' => $petrolRequestsByDay,
                'petrol_window_days' => $petrolWindowDays,
                // Additive: the app shows an "add my bike's meter" door only when this
                // is present, so an older app and an older server both stay as they were.
                'own_vehicle' => $ownVehicle,
                'bike_usage' => $bikeUsage,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get monthly attendance', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);

            return response()->json(['success' => false, 'message' => 'Failed to load attendance: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Get request categories (filtered for riders: expense, salary_advance, leave)
     */
    public function getRequestCategories(Request $request)
    {
        try {
            $businessUnitId = $request->input('business_unit_id');
            
            $buType = ($businessUnitId && $businessUnitId != 1) ? 'khaas' : 'nf';

            $user = $request->user();

            // Use DB-driven filtering if columns exist, otherwise fallback to hardcoded
            try {
                $allCats = \App\Models\Request\RequestCategoryModel::where('show_in_expenses', 1)
                    ->where('is_active', 1)
                    ->where(function ($q) use ($buType) {
                        $q->where('expense_bu_type', $buType)
                          ->orWhere('expense_bu_type', 'all');
                    })
                    ->orderBy('sequence_order')
                    ->get();
            } catch (\Exception $e) {
                $codes = ($businessUnitId && $businessUnitId != 1) ? ['khaas_expense'] : ['expense', 'salary_advance', 'leave'];
                $allCats = \App\Models\Request\RequestCategoryModel::whereIn('category_code', $codes)
                    ->where('is_active', 1)
                    ->orderBy('sequence_order')
                    ->get();
            }

            $categories = $allCats
                ->filter(function ($cat) use ($user) {
                    $perm = $cat->mobile_permission_code ?? null;
                    if (!$perm) return true;
                    return $user && method_exists($user, 'hasMobilePermission')
                        ? $user->hasMobilePermission($perm)
                        : false;
                })
                ->values()
                ->map(function($cat) {
                    return [
                        'id' => $cat->id,
                        'category_code' => $cat->category_code,
                        'category_name' => $cat->category_name,
                        'description' => $cat->description,
                        'icon' => $cat->icon,
                        'form_type' => $cat->form_type ?? 'general',
                    ];
                });

            return response()->json([
                'success' => true,
                'categories' => $categories,
                // ⛽ Lets the rider's own request form hide "Petrol" for a PER-KM
                // rider (his claim is generated from the meter) instead of letting
                // him fill the whole form and then hit a 422. The SERVER is still
                // the gate (FuelClaimRules) — this only explains it up front.
                // Judged by canSelfFilePetrol(), NOT the company_bike flag: people
                // like Taimur or Farooq are not on the scheme and must keep the
                // option even though they don't ride company bikes.
                'can_self_file_petrol' => (new \App\Services\Riders\FuelClaimRules())
                    ->canSelfFilePetrol((int) $user->id),
                // 🔧 The manager's maintenance categories. Riders pick from the same
                // list managers do (owner ruling, Aug-3), so it rides along with the
                // categories the form already fetches rather than needing its own
                // endpoint. Empty array = types not configured; the app then keeps
                // its built-in Regular/Repair pair.
                'maintenance_types' => app(\App\Services\Riders\MaintenanceTypeService::class)->options(),
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get request categories', [
                'error' => $e->getMessage(),
            ]);
            
            return response()->json(['success' => false, 'message' => 'Failed to load categories: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Get rider's requests
     */
    /**
     * Mobile leave approvals — thin, permission-gated wrappers that DELEGATE to the
     * canonical web leave logic in AttendanceController so no business rule is
     * duplicated (single-level approval, status->approved/rejected, rider app
     * re-syncs via requester_sync_required; leave balance is derived by
     * LeavePolicyService, so there is no quota write on approve). All three require
     * the 'approve_leaves' mobile permission.
     */
    public function mobilePendingLeaves(Request $request)
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('approve_leaves')) {
            return response()->json(['success' => false, 'message' => 'You do not have leave-approval access.'], 403);
        }
        return app(\App\Http\Controllers\CRM\AttendanceController::class)->pendingLeaves($request);
    }

    public function mobileApproveLeave(Request $request, $id)
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('approve_leaves')) {
            return response()->json(['success' => false, 'message' => 'You do not have leave-approval access.'], 403);
        }
        return app(\App\Http\Controllers\CRM\AttendanceController::class)->approveLeaveRequest($request, $id);
    }

    public function mobileRejectLeave(Request $request, $id)
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('approve_leaves')) {
            return response()->json(['success' => false, 'message' => 'You do not have leave-approval access.'], 403);
        }
        return app(\App\Http\Controllers\CRM\AttendanceController::class)->rejectLeaveRequest($request, $id);
    }

    public function getRequests(Request $request)
    {
        try {
            $user = Auth::user();
            $status = $request->input('status', 'all'); // all, pending, approved, rejected

            // Allowed category codes for "My Requests": expense-form types + salary_advance + leave
            try {
                $allowedCategoryCodes = \App\Models\Request\RequestCategoryModel::where('is_active', 1)
                    ->where(function($q) {
                        $q->where('show_in_expenses', 1)
                          ->orWhereIn('category_code', ['expense', 'salary_advance', 'leave', 'khaas_expense']);
                    })
                    ->pluck('category_code')
                    ->toArray();
            } catch (\Exception $e) {
                $allowedCategoryCodes = ['expense', 'salary_advance', 'leave', 'khaas_expense'];
            }
            
            $query = \App\Models\Request\RequestModel::with(['category', 'approvals.approver'])
                ->where('requester_user_id', $user->id)
                ->whereHas('category', function($q) use ($allowedCategoryCodes) {
                    $q->whereIn('category_code', $allowedCategoryCodes);
                })
                ->orderByDesc('created_at');

            if ($status !== 'all') {
                $query->where('status', $status);
            }

            // ⭐ WHICH MACHINE an expense claim is for — the same pill, the same words, as
            //   Daily Closing and the Month view (VehicleResolver::machineChip). The rider
            //   files these; seeing the machine back on his own row is how he catches a
            //   claim that went onto the wrong one before an approver has to.
            // ⚠⚠ ONLY on Petrol/Maintenance. This list also carries LEAVE and SALARY
            //   ADVANCE rows, which have no machine to speak of — emitting the keys as
            //   nulls there would print "machine not recorded" on a leave request. Absent
            //   keys are the client's signal to render nothing at all.
            // ⚠ SCHEMA-GUARDED: `vehicle_id` was hand-applied to t_req_master.
            $hasVehicleCol = \Illuminate\Support\Facades\Schema::hasColumn('t_req_master', 'vehicle_id');
            $vehResolver   = new \App\Services\Riders\VehicleResolver();

            $requests = $query->limit(100)->get()->map(function($req) use ($hasVehicleCol, $vehResolver) {
                $machine = in_array((string) $req->expense_category, ['Petrol', 'Maintenance'], true)
                    ? $vehResolver->machineChipFields(
                        $hasVehicleCol && $req->vehicle_id !== null ? (int) $req->vehicle_id : null
                    )
                    : [];

                $approverName = null;
                if ($req->status === 'approved' || $req->status === 'rejected') {
                    $lastApproval = $req->approvals
                        ->sortByDesc('updated_at')
                        ->first(function ($a) use ($req) {
                            return $a->status === $req->status;
                        });
                    if ($lastApproval && $lastApproval->approver) {
                        $approverName = $lastApproval->approver->fullname;
                    }
                }

                return $machine + [
                    'id' => $req->id,
                    'request_number' => $req->request_number,
                    'category' => [
                        'id' => $req->category->id,
                        'code' => $req->category->category_code,
                        'name' => $req->category->category_name,
                        'icon' => $req->category->icon,
                    ],
                    'title' => $req->title,
                    'description' => $req->description,
                    'amount' => $req->amount,
                    'amount_formatted' => $req->amount ? 'Rs. ' . number_format($req->amount, 0) : null,
                    'expense_category' => $req->expense_category,
                    'leave_start_date' => $req->leave_start_date,
                    'leave_end_date' => $req->leave_end_date,
                    'leave_type' => $req->leave_type,
                    'status' => $req->status,
                    'status_label' => ucfirst($req->status),
                    'priority' => $req->priority,
                    'approved_by' => $approverName,
                    'created_at' => $req->created_at->format('Y-m-d H:i:s'),
                    'created_at_formatted' => $req->created_at->format('M d, Y h:i A'),
                ];
            });

            // ⭐ SMART SYNC: Clear sync flags for rider's fetched requests
            \DB::table('t_req_master')
                ->where('requester_user_id', $user->id)
                ->where('requester_sync_required', true)
                ->update([
                    'requester_sync_required' => false,
                    'requester_last_sync_at' => now()
                ]);

            return response()->json([
                'success' => true,
                'requests' => $requests,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get requests', [
                'error' => $e->getMessage(),
            ]);
            
            return response()->json(['success' => false, 'message' => 'Failed to load requests: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Create new request
     */
    public function createRequest(Request $request)
    {
        try {
            $user = Auth::user();

            $validated = $request->validate([
                'category_id' => 'required|exists:t_req_category,id',
                'title' => 'required|string|max:255',
                'description' => 'nullable|string',
                'amount' => 'nullable|numeric|min:0',
                'expense_category' => 'nullable|string|max:255',
                'expense_date' => 'nullable|date',
                'meter_distance' => 'nullable|numeric|min:0',
                'petrol_rate' => 'nullable|numeric|min:0',
                // Which machine these kilometres were on. Optional: no APK in the field
                // sends it, and the rules resolve the day's machine when it is absent.
                'vehicle_id' => 'nullable|integer',
                // Fuel capture (Jul-2026). meter_at_fill is the odometer at the
                // moment of filling — it puts the fill on the bike's km timeline.
                'meter_at_fill' => 'nullable|integer|min:0|max:9999999',
                'litres' => 'nullable|numeric|min:0|max:99',
                'service_type' => 'nullable|string|max:30',
                // Named maintenance type; when present the server derives service_type from it.
                'maintenance_type_id' => 'nullable|integer',
                /**
                 * 🧾 WHICH ALREADY-RECORDED SERVICE THIS BILL IS FOR (owner ruling, 3-Sep).
                 *    The filer PICKS it from his own un-billed readings — nothing is matched
                 *    by meter or date, because guessing is what misfiled service log #8.
                 *    Absent = "a new service", which is exactly today's behaviour.
                 */
                'service_log_id' => 'nullable|integer',
                // ⭐ 29-Sep-2026: ONE bill for several jobs of the same visit (one receipt).
                'service_log_ids'   => 'nullable',
                'attendance_id' => 'nullable|integer',
                'leave_start_date' => 'nullable|date',
                'leave_end_date' => 'nullable|date|after_or_equal:leave_start_date',
                'leave_type' => 'nullable|string',
                'attachment_image' => 'nullable|image|max:5120',
            ]);

            // Salaries are now handled exclusively by the Payroll screen. Block the legacy
            // "Staff Salaries" expense category so a stale form / cached app can't post a
            // duplicate salary expense.
            if (in_array(strtolower(trim((string) ($validated['expense_category'] ?? ''))), ['staff salaries', 'staff salary'], true)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Staff salaries must be paid from the Payroll screen, not entered as an expense.'
                ], 422);
            }

            // Metered petrol = a petrol request tied to a real attendance row + meter reading.
            $isMeteredPetrol = $request->filled('attendance_id') && ($request->input('expense_category') === 'Petrol');

            // Duplicate check for petrol requests: one per attendance day
            if ($isMeteredPetrol) {
                if ($request->filled('expense_date')) {
                    // ⭐ ONE definition (FuelClaimRules) — this endpoint is always the
                    //   rider filing for himself, so it is always the rider window.
                    $petrolWindow = (new \App\Services\Riders\FuelClaimRules())->petrolWindowDays(false);
                    $petrolDate = \Carbon\Carbon::parse($validated['expense_date'])->startOfDay();
                    $windowStart = \Carbon\Carbon::today()->subDays($petrolWindow);
                    if ($petrolDate->lt($windowStart)) {
                        return response()->json([
                            'success' => false,
                            'message' => "Petrol requests from meter reading can only be raised for the last {$petrolWindow} days."
                        ], 422);
                    }
                }

                // ⭐⭐ THE DUPLICATE AND SPLIT-DAY GUARDS NOW LIVE IN `FuelClaimRules`
                //    (Aug-27 2026) — see `checkMeteredPetrol`, called through `check()`
                //    a few lines below. Both had to move for the same reason:
                //
                //    • the duplicate rule became MACHINE-aware ("one claim per machine
                //      per day"), because a mixed day can legitimately carry his own
                //      bike's claim beside the company machine's fuel;
                //    • the split-day rule was a blanket refusal, and a blanket refusal
                //      is precisely the bug — a day split between his own bike and the
                //      van is not unclaimable, it is claimable for ONE of the two. The
                //      leg-based check pays the own bike and declines the van.
                //
                //    ⚠ Keeping copies here would re-create the very drift this codebase
                //      has been bitten by before; the manager's on-behalf path calls the
                //      same rules object and must reach the identical answer.
            }
            // ---- FUEL / MAINTENANCE RULES ------------------------------------
            // ⭐ ONE implementation, shared with the manager-on-behalf path
            //    (Request\RequestController::store). These guards used to live
            //    inline here only, which is exactly why a manager filing for a
            //    rider skipped every one of them. Behaviour is unchanged; the
            //    rules simply moved into FuelClaimRules so both callers agree.
            $isFlatPetrol = ($request->input("expense_category") === "Petrol") && !$request->filled("attendance_id");

            // ⭐ Resolve the named maintenance type into the machine flag BEFORE the
            //    rules run — the meter requirement keys off service_type. Mirrors
            //    Request\RequestController::store() exactly. An APK that sends only
            //    service_type (every build in the field today) falls through
            //    unchanged.
            $svcResolved = app(\App\Services\Riders\MaintenanceTypeService::class)->resolve(
                $request->input('maintenance_type_id'),
                $request->input('service_type')
            );

            /**
             * ⭐⭐ ONE RULE FOR "WHICH SERVICE?" (owner, 3-Sep). A Maintenance claim carrying an
             *    odometer must name a type when the list exists — the same refusal a manager
             *    gets on Record service. Until now this path filed a legacy "Regular service"
             *    untyped, and the evidence engine then ignored it for every countdown.
             *    The rule lives in ServiceRecordService so this and the web path cannot drift.
             */
            /**
             * 🧾 THE BILL IS FOR A SERVICE HE ALREADY RECORDED (owner ruling, 3-Sep).
             *
             * ⭐ He picked it, so the claim INHERITS that reading — its odometer, its job and
             *   its date — and he never retypes a meter he has already entered. That was the
             *   owner's whole reason for asking.
             * ⚠⚠ And this is the double-money guard: if the chosen service already carries a
             *    live bill, the claim is REFUSED. Without it, a manager recording the service
             *    with the receipt and the rider filing the same receipt sends money out twice.
             */
            // 🔗 (29-Sep-2026) Only a Maintenance bill may be tied to service records — the one
            //    rule, shared with Request\RequestController::store. No transaction is open yet here.
            if ($linkRefusal = \App\Services\Riders\ServiceRecordService::linkRefusalForCategory(
                    $request->input('expense_category'),
                    \App\Services\Riders\ServiceRecordService::normaliseIds(
                        $request->input('service_log_ids'), $request->input('service_log_id')))) {
                return response()->json(['success' => false, 'message' => $linkRefusal], 422);
            }
            $svcLink = app(\App\Services\Riders\ServiceRecordService::class)
                // ⭐ One id, or every job of one visit that one receipt paid for (29-Sep-2026).
                ->validateBillTarget($request->input('service_log_ids') ?: $request->input('service_log_id'), (int) $user->id);
            if (!$svcLink['ok']) {
                return response()->json(['success' => false, 'message' => $svcLink['message']], 422);
            }
            if (!empty($svcLink['inherit'])) {
                $request->merge([
                    'meter_at_fill'       => $svcLink['inherit']['meter'],
                    'expense_date'        => $svcLink['inherit']['date'],
                    'maintenance_type_id' => $svcLink['inherit']['maintenance_type_id'],
                ]);
                $validated['meter_at_fill']       = $svcLink['inherit']['meter'];
                $validated['expense_date']        = $svcLink['inherit']['date'];
                $validated['maintenance_type_id'] = $svcLink['inherit']['maintenance_type_id'];
                // ⭐ …and the machine the service was recorded on (29-Sep-2026). An older engine
                //   sends no `vehicle_id` in the inherit, so this is a no-op until it is uploaded.
                if (!$request->filled('vehicle_id') && !empty($svcLink['inherit']['vehicle_id'])) {
                    $request->merge(['vehicle_id' => (int) $svcLink['inherit']['vehicle_id']]);
                    $validated['vehicle_id'] = (int) $svcLink['inherit']['vehicle_id'];
                }
                // ⚠ Re-resolve: the inherited type decides service_type, which the rules below judge.
                $svcResolved = app(\App\Services\Riders\MaintenanceTypeService::class)->resolve(
                    $svcLink['inherit']['maintenance_type_id'], $request->input('service_type')
                );
            }

            if ($request->input('expense_category') === 'Maintenance') {
                $typeGate = app(\App\Services\Riders\ServiceRecordService::class)
                    // ⚠ "has a meter" = a positive reading, on BOTH doors — filled('0') is not one.
                    ->requireTypeForClaim($svcResolved[1], (int) $request->input('meter_at_fill') > 0);
                if (!$typeGate['ok']) {
                    // No transaction is open yet at this point — same as the early returns above.
                    return response()->json(['success' => false, 'message' => $typeGate['message']], 422);
                }
            }

            $fuelRules = (new \App\Services\Riders\FuelClaimRules())->check(
                (int) $user->id,
                $request->input("expense_category"),
                [
                    "amount"        => $request->input("amount"),
                    "expense_date"  => $request->input("expense_date"),
                    "meter_at_fill" => $request->input("meter_at_fill"),
                    "service_type"  => $svcResolved[0],
                    // ⚠ Inherited from an accepted service record — see the twin note in
                    //   Request\RequestController::store and FuelClaimRules.
                    "meter_from_service_log" => !empty($svcLink['inherit']),
                    "attendance_id" => $request->input("attendance_id"),
                    // ⭐ The per-km claim is judged against the kilometres actually
                    //   recorded on the machine it names. `vehicle_id` is optional —
                    //   every APK in the field today sends none, and the rules resolve
                    //   the machine from the day itself when it is absent.
                    "meter_distance" => $request->input("meter_distance"),
                    "vehicle_id"     => $request->input("vehicle_id"),
                ],
                // This endpoint IS the rider's own app — he is always filing for
                // himself, which is what makes the own-bike petrol block apply here
                // and not on the manager's on-behalf path.
                (int) $user->id
            );
            if (!$fuelRules["ok"]) {
                return response()->json(["success" => false, "message" => $fuelRules["message"]], 422);
            }
            $flatNotice = $fuelRules["notice"] ?? null;
            // The machine the rules settled on — stamped onto the claim below so the
            // money follows the same machine as the kilometres that earned it.
            $claimVehicleId = $fuelRules["vehicle_id"] ?? null;


            // ⭐ Validate expense_date is within allowed backdate range
            if ($request->filled('expense_date')) {
                $expenseDate = \Carbon\Carbon::parse($validated['expense_date']);
                $today = \Carbon\Carbon::today();

                // Check if date is in the future (applies to everything, incl. petrol)
                if ($expenseDate->gt($today)) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Expense date cannot be in the future'
                    ], 422);
                }

                // Metered petrol is exempt from the role backdate cap: it has its own
                // PETROL_WINDOW_DAYS window (checked above) and is anchored to a real
                // attendance row + meter reading, so the generic per-role cap (often 0
                // for riders, which would otherwise block even yesterday's petrol) does
                // not apply. All other expense types still obey the role cap.
                if (!$isMeteredPetrol) {
                    // Get user's max backdate days from their roles
                    $maxBackdateDays = DB::table('t_sys_user_role as ur')
                        ->join('t_sys_role as r', 'r.id', '=', 'ur.role_id')
                        ->where('ur.user_id', $user->id)
                        ->max('r.expense_backdate_days') ?? 0;

                    // Check if date is too far in the past
                    // ⚠⚠ abs() — see the twin note in Request\RequestController::store. On
                    //    Carbon 3 this returns a SIGNED value, so the cap never fired and any
                    //    backdate was accepted. Same bug, same fix, both doors.
                    $daysDiff = (int) abs($today->diffInDays($expenseDate));
                    if ($daysDiff > $maxBackdateDays) {
                        return response()->json([
                            'success' => false,
                            'message' => "You can only backdate expenses up to {$maxBackdateDays} days. Selected date is {$daysDiff} days ago."
                        ], 422);
                    }
                }
            }

            // Prevent duplicate leave requests for overlapping dates
            if ($request->filled('leave_start_date') && $request->filled('leave_end_date')) {
                $overlapping = DB::table('t_req_master as r')
                    ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                    ->where('c.category_code', 'leave')
                    ->where('r.requester_user_id', $user->id)
                    ->whereNotIn('r.status', ['cancelled', 'rejected'])
                    ->where('r.leave_start_date', '<=', $validated['leave_end_date'])
                    ->where('r.leave_end_date', '>=', $validated['leave_start_date'])
                    ->select('r.leave_start_date', 'r.leave_end_date', 'r.request_number')
                    ->first();

                if ($overlapping) {
                    $existingStart = \Carbon\Carbon::parse($overlapping->leave_start_date)->format('M d');
                    $existingEnd = \Carbon\Carbon::parse($overlapping->leave_end_date)->format('M d');
                    return response()->json([
                        'success' => false,
                        'message' => "Leave already raised for {$existingStart} - {$existingEnd} ({$overlapping->request_number}). Cannot create overlapping leave request."
                    ], 422);
                }
            }

            // ── Leave policy (single pool + same-day cap), server-authoritative so an old
            //    app build can't bypass it. Applies to the rider applying for themselves
            //    (this endpoint always creates for Auth::user). Sets $policyLeaveType.
            $policyLeaveType = null;
            if ($request->filled('leave_start_date') && $request->filled('leave_end_date')) {
                $catForPolicy = \App\Models\Request\RequestCategoryModel::find($validated['category_id']);
                if ($catForPolicy && $catForPolicy->category_code === 'leave') {
                    $policyRes = (new \App\Services\HR\LeavePolicyService())->validateApplication(
                        (int) $user->id, $validated['leave_start_date'], $validated['leave_end_date'],
                        date('Y-m-d'), date('H:i')
                    );
                    if (!$policyRes['ok']) {
                        return response()->json(['success' => false, 'message' => $policyRes['message']], 422);
                    }
                    // planned = applied in advance; emergency = same-day (feeds the cap).
                    $policyLeaveType = $policyRes['is_sameday'] ? 'emergency' : 'planned';
                }
            }

            // Verify category is allowed: legacy types + any expense-management enabled type
            try {
                $allowedCategoryCodes = \App\Models\Request\RequestCategoryModel::where('is_active', 1)
                    ->where(function($q) {
                        $q->where('show_in_expenses', 1)
                          ->orWhereIn('category_code', ['expense', 'salary_advance', 'leave', 'khaas_expense']);
                    })
                    ->pluck('category_code')
                    ->toArray();
            } catch (\Exception $e) {
                $allowedCategoryCodes = ['expense', 'salary_advance', 'leave', 'khaas_expense'];
            }
            
            $category = \App\Models\Request\RequestCategoryModel::with('approvalConfig')
                ->whereIn('category_code', $allowedCategoryCodes)
                ->findOrFail($validated['category_id']);

            DB::beginTransaction();

            // Calculate leave days if it's a leave request
            $leaveDays = null;
            if (isset($validated['leave_start_date']) && isset($validated['leave_end_date'])) {
                $start = \Carbon\Carbon::parse($validated['leave_start_date']);
                $end = \Carbon\Carbon::parse($validated['leave_end_date']);
                /**
                 * ⚠⚠ THE ARGUMENTS WERE THE WRONG WAY ROUND (found 3-Sep). On Carbon 3 —
                 *    this codebase runs 3.8.4 — `diffInDays` returns a SIGNED value, so
                 *    `$end->diffInDays($start)` gives −2 and a 3-day leave stored **−1**.
                 *    9 live rows carry a negative count (−10, −7, −5×3, −1×4). Single-day
                 *    leaves were right (start == end → 0 + 1), which is why it went unseen.
                 *
                 * ⚠ Payroll is NOT affected — it counts leave from ATTENDANCE dates, not from
                 *   this column. The damage was the attendance leave panel, which reads
                 *   `$r->leave_days ?: fallback` and takes a negative as truthy.
                 *
                 * ⭐ abs() as well as the right order, so neither mistake can return.
                 */
                $leaveDays = (int) abs($start->diffInDays($end)) + 1;
            }

            // Server-side payment source validation.
            // ⭐ Aug-2026: mirrors Request\RequestController::store() exactly — the
            // account allow-list (t_fin_account_users) decides, through the SAME
            // PaymentSourceService call that built the picker. Since Aug-6-2026 a
            // tagged account may fund a request filed against ANY reachable unit
            // (the request's own unit stamps the books); untagged users still get
            // only their unit's legacy fallback.
            $paymentSourceAccountId = $request->input('payment_source_account_id');
            $expenseBankId = null; // which of OUR banks an online expense is paid from
            if ($paymentSourceAccountId) {
                $sourceAccount = \App\Models\FIN\AccountModel::find($paymentSourceAccountId);
                // Block private accounts for non-Taimur
                if ($sourceAccount && $sourceAccount->is_private) {
                    $isTaimurRole = $user->roles()->whereRaw('LOWER(urole_name) = ?', ['taimur'])->exists();
                    if (!$isTaimurRole) {
                        return response()->json([
                            'success' => false,
                            'message' => 'This payment source is not available.'
                        ], 403);
                    }
                }
                // EXPENSE or SALARY ADVANCE from an online bank source → the
                // specific receiving bank is mandatory, so the outflow
                // attributes to the right per-bank balance. Leave requests move
                // no money and are never blocked by this rule.
                $isMoneyCategory = in_array($category->category_code, ['expense', 'khaas_expense', 'salary_advance', 'qurbani'], true)
                    || in_array($category->form_type ?? null, ['expense', 'salary'], true);

                if ($isMoneyCategory) {
                    $sourcePurpose = $category->category_code === 'salary_advance'
                        ? \App\Services\FIN\PaymentSourceService::PURPOSE_ADVANCE
                        : \App\Services\FIN\PaymentSourceService::PURPOSE_EXPENSE;
                    $buForSource = $request->input('business_unit_id');
                    if (!app(\App\Services\FIN\PaymentSourceService::class)->allows(
                            $user, $paymentSourceAccountId, $buForSource ? (int) $buForSource : null, $sourcePurpose)) {
                        return response()->json([
                            'success' => false,
                            'message' => 'You are not set up to pay from this account. Ask Taimur or Shabib to add you to it.'
                        ], 403);
                    }
                }

                if ($sourceAccount && $isMoneyCategory
                    && $sourceAccount->account_category === \App\Models\FIN\AccountModel::CATEGORY_BANK) {
                    $rid = $request->input('receiving_account_id');
                    if (!$rid || !\App\Models\FIN\OnlineReceivingAccountModel::where('id', $rid)->exists()) {
                        return response()->json([
                            'success' => false,
                            'message' => 'Select which bank this online payment is made from.'
                        ], 422);
                    }
                    $expenseBankId = (int) $rid;
                }
            }
            if (!$paymentSourceAccountId && isset($validated['attendance_id']) && ($validated['expense_category'] ?? null) === 'Petrol') {
                $expFundAccount = \App\Models\FIN\AccountModel::where('account_code', 'EXP_FUND')->where('is_active', 1)->first();
                if ($expFundAccount) {
                    $paymentSourceAccountId = $expFundAccount->id;
                }
            }

            // Store attachment image if provided (e.g. fuel bill photo)
            $attachments = null;
            if ($request->hasFile('attachment_image')) {
                $file = $request->file('attachment_image');
                $date = now();
                $filename = "req_{$user->id}_{$date->format('Ymd_His')}.jpg";
                $path = "requests/attachments/{$date->format('Y')}/{$date->format('m')}/{$filename}";
                \Storage::disk('public')->put($path, file_get_contents($file));
                $attachments = [$path];
            }

            $newRequest = \App\Models\Request\RequestModel::create([
                'request_number' => \App\Models\Request\RequestModel::generateRequestNumber(),
                'category_id' => $category->id,
                'requester_user_id' => $user->id,
                'title' => $validated['title'],
                // A flat-petrol notice is appended to the description so the
                // approver sees WHY it is flagged, on whichever screen they use.
                'description' => trim(($validated['description'] ?? '') .
                    ($flatNotice ? "\n\n⚠ " . $flatNotice : '')) ?: null,
                'amount' => $validated['amount'] ?? null,
                'expense_category' => $validated['expense_category'] ?? null,
                'expense_date' => $validated['expense_date'] ?? now()->toDateString(),
                'meter_distance' => $validated['meter_distance'] ?? null,
                'petrol_rate' => $validated['petrol_rate'] ?? null,
                'meter_at_fill' => $validated['meter_at_fill'] ?? null,
                'litres' => $validated['litres'] ?? null,
                // ⭐ Derived from the chosen type's bucket when one was picked.
                'service_type' => $svcResolved[0],
                'maintenance_type_id' => $svcResolved[1],
                'attendance_id' => $validated['attendance_id'] ?? null,
                'payment_source_account_id' => $paymentSourceAccountId,
                'receiving_account_id' => $expenseBankId,
                'business_unit_id' => $request->input('business_unit_id', 1),
                'leave_start_date' => $validated['leave_start_date'] ?? null,
                'leave_end_date' => $validated['leave_end_date'] ?? null,
                // Records how the leave was applied (casual = advance, emergency = same-day).
                'leave_type' => $policyLeaveType ?? ($validated['leave_type'] ?? null),
                'leave_days' => $leaveDays,
                'attachments' => $attachments,
                'status' => \App\Models\Request\RequestModel::STATUS_PENDING,
                'priority' => 'normal',
                'requires_level_1' => $category->requiresLevel1(),
                'requires_level_2' => $category->requiresLevel2(),
                'level_1_status' => $category->requiresLevel1() ? \App\Models\Request\RequestModel::APPROVAL_STATUS_PENDING : null,
                'level_2_status' => $category->requiresLevel2() ? \App\Models\Request\RequestModel::APPROVAL_STATUS_PENDING : null,
                'submitted_at' => now(),
                'created_by' => $user->id,
            ]);

            // 🏍️ Record which machine this claim was for (Aug-2026). Non-fatal and
            // guarded — a claim that saved is never failed because the vehicle
            // could not be resolved, and it no-ops entirely before batch 13.
            (new \App\Services\Riders\VehicleResolver())->stampClaim(
                $newRequest->id, (int) $user->id,
                $validated['expense_category'] ?? null,
                $validated['expense_date'] ?? null,
                // ⭐ The per-km flow names the attendance row its amount came from; the money then
                //   follows the same machine as the kilometres. See vehicleFromReadingStamps().
                isset($validated['attendance_id']) ? (int) $validated['attendance_id'] : null,
                // ⭐⭐ …and on a MIXED day the reading stamps cannot answer (they name two
                //    different machines, so that helper returns null by design). The rules
                //    already worked out which machine's kilometres are being paid for, so
                //    hand that answer over rather than letting the date guess again — this
                //    is what stops own-bike money landing on the van.
                $claimVehicleId ? (int) $claimVehicleId : null
            );

            // 🧾 Tie the bill to the service he chose. Inside the transaction, so a claim can
            //    never exist un-linked when he explicitly said which service it was for.
            if (!empty($svcLink['log_ids']) || $request->filled('service_log_id')) {
                app(\App\Services\Riders\ServiceRecordService::class)
                    ->attachBillToService($svcLink['log_ids'] ?? (int) $request->input('service_log_id'), (int) $newRequest->id);
            }

            DB::commit();

            \Log::info('Request created via mobile app', [
                'request_id' => $newRequest->id,
                'request_number' => $newRequest->request_number,
                'category' => $category->category_name,
                'user_id' => $user->id,
                'user_name' => $user->fullname,
            ]);

            // ⭐ Alert management (permission: receive_leave_alerts) when a NEW leave
            // request is added and is pending review. New pending leaves only;
            // best-effort so a push failure never affects the request response.
            if (($category->category_code ?? null) === 'leave'
                && $newRequest->status === \App\Models\Request\RequestModel::STATUS_PENDING) {
                try {
                    $range = null;
                    if ($newRequest->leave_start_date) {
                        $s = date('M j', strtotime($newRequest->leave_start_date));
                        $e2 = $newRequest->leave_end_date ? date('M j', strtotime($newRequest->leave_end_date)) : $s;
                        $range = ($s === $e2) ? $s : "{$s} – {$e2}";
                    }
                    app(\App\Services\FirebaseService::class)->notifyLeaveAdded(
                        (int) $newRequest->id,
                        $user->fullname ?: 'An employee',
                        $range,
                        (int) $user->id
                    );
                } catch (\Throwable $e) {
                    \Log::warning('Leave alert failed (mobile)', ['error' => $e->getMessage()]);
                }
            }

            return response()->json([
                'success' => true,
                'message' => 'Request created successfully',
                'request' => [
                    'id' => $newRequest->id,
                    'request_number' => $newRequest->request_number,
                    'status' => $newRequest->status,
                ],
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors' => $e->errors(),
            ], 422);
        } catch (\Exception $e) {
            DB::rollBack();
            
            \Log::error('Failed to create request', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json(['success' => false, 'message' => 'Failed to create request: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Get salary information for logged-in user
     * Returns: basic salary, loan balance, pending advances, salary slips
     */
    public function getSalaryInfo(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Get employee profile
            $profile = EmployeeProfileModel::where('user_id', $user->id)->first();
            
            if (!$profile) {
                return response()->json([
                    'success' => false,
                    'message' => 'Employee profile not found',
                ], 404);
            }

            // Get basic salary information
            $basicSalary = [
                'base_salary' => (float) ($profile->base_salary ?? 0),
                'ot_rate_per_hour' => (float) ($profile->ot_rate_per_hour ?? 0),
                'employee_code' => $profile->employee_code,
                'designation' => $profile->designation,
                'department' => $profile->department,
                'joining_date' => $profile->joining_date,
            ];

            // Calculate total outstanding loans (reusing webapp logic)
            $activeLoans = EmployeeLoanModel::where('user_id', $user->id)
                ->where('loan_status', 'active')
                ->get();
            
            $totalLoanOutstanding = $activeLoans->sum('outstanding_balance');
            
            $loansData = $activeLoans->map(function($loan) {
                return [
                    'id' => $loan->id,
                    'loan_number' => $loan->loan_number,
                    'loan_type' => $loan->loan_type,
                    'principal_amount' => (float) $loan->principal_amount,
                    'monthly_installment' => (float) $loan->monthly_installment,
                    'outstanding_balance' => (float) $loan->outstanding_balance,
                    'loan_date' => $loan->loan_date,
                    'description' => $loan->description,
                ];
            });

            // Calculate unadjusted salary advances (reusing webapp logic)
            $pendingAdvances = \App\Models\Request\RequestModel::where('requester_user_id', $user->id)
                ->where('status', 'approved')
                ->whereHas('category', function($q) {
                    $q->where('category_code', 'salary_advance');
                })
                ->where(function($q) {
                    // Only include advances not yet settled
                    $q->whereNull('settlement_status')
                      ->orWhere('settlement_status', '!=', 'settled');
                })
                ->with('category')
                ->get();
            
            $totalPendingAdvances = $pendingAdvances->sum(fn ($a) => (float) $a->amount - (float) ($a->settled_amount ?? 0)); // still open (Sep-7: part may be carried)
            
            $advancesData = $pendingAdvances->map(function($advance) {
                return [
                    'id' => $advance->id,
                    'request_number' => $advance->request_number,
                    'amount' => (float) $advance->amount - (float) ($advance->settled_amount ?? 0), // still open
                    'title' => $advance->title,
                    'description' => $advance->description,
                    'submitted_at' => $advance->submitted_at,
                    'settlement_status' => $advance->settlement_status ?? 'pending',
                ];
            });

            // Get salary slips (reusing webapp logic)
            $salarySlips = SalarySlipModel::where('user_id', $user->id)
                ->orderBy('salary_month', 'desc')
                ->limit(12) // Last 12 months
                ->get();
            
            $slipsData = $salarySlips->map(function($slip) {
                return [
                    'id' => $slip->id,
                    'slip_number' => $slip->slip_number,
                    'salary_month' => $slip->salary_month,
                    'salary_month_formatted' => date('F Y', strtotime($slip->salary_month . '-01')),
                    'gross_salary' => (float) $slip->gross_salary,
                    'total_deductions' => (float) $slip->total_deductions,
                    'net_salary' => (float) $slip->net_salary,
                    'slip_status' => $slip->slip_status,
                    'status_display' => ucfirst($slip->slip_status),
                    'status_color' => $this->getSlipStatusColor($slip->slip_status),
                    'has_manual_adjustments' => (bool) $slip->has_manual_adjustments,
                    'created_at' => $slip->created_at->toIso8601String(),
                ];
            });

            return response()->json([
                'success' => true,
                'data' => [
                    'basic_salary' => $basicSalary,
                    'loans' => [
                        'total_outstanding' => (float) $totalLoanOutstanding,
                        'active_loans_count' => $activeLoans->count(),
                        'loans' => $loansData,
                    ],
                    'advances' => [
                        'total_pending' => (float) $totalPendingAdvances,
                        'pending_count' => $pendingAdvances->count(),
                        'advances' => $advancesData,
                    ],
                    'salary_slips' => [
                        'total_count' => $salarySlips->count(),
                        'slips' => $slipsData,
                    ],
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get salary info', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load salary information: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
