            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch users',
                'users' => []
            ], 500);
        }
    }

    /**
     * STORE MODE: Get available order statuses
     * Filters based on mobile visibility settings and user role
     */
    public function getOrderStatuses(Request $request)
    {
        try {
            $user = Auth::user();
            $userRoleIds = $user ? $user->roles()->pluck('t_sys_role.id')->toArray() : [];
            
            $statusQuery = DB::table('t_crm_order_status_master')
                ->where('is_active', 1)
                ->where('show_in_mobile', 1)  // ⭐ Only show statuses enabled for mobile
                // Exclude legacy status codes (keep only underscore versions)
                ->whereNotIn('status_code', ['on-hold', 'on hold']);

            // Status Hub: never offer "legacy" (retiring) statuses in the picker.
            // Guarded so this stays safe if the Hub migration hasn't run yet.
            if (\Schema::hasColumn('t_crm_order_status_master', 'lane')) {
                $statusQuery->where('lane', '!=', 'legacy');
            }

            $statuses = $statusQuery
                ->orderBy('sequence_order')
                ->get(['id', 'status_code', 'status_name', 'icon', 'color_class', 'visible_to_roles', 'sequence_order', 'is_final']);
            
            // Filter by role visibility
            $filteredStatuses = $statuses->filter(function($status) use ($userRoleIds) {
                // If no role restriction (null or empty), visible to all
                $visibleRoles = $status->visible_to_roles;
                if (empty($visibleRoles)) {
                    return true;
                }
                
                // Decode JSON if it's a string
                if (is_string($visibleRoles)) {
                    $visibleRoles = json_decode($visibleRoles, true);
                }
                
                // If still empty after decode, visible to all
                if (empty($visibleRoles)) {
                    return true;
                }
                
                // Check if user has any of the required roles
                return !empty(array_intersect($userRoleIds, $visibleRoles));
            })->map(function($status) {
                // Include sequence_order for mobile app sorting
                return [
                    'status_code' => $status->status_code,
                    'status_name' => $status->status_name,
                    'icon' => $status->icon,
                    'color_class' => $status->color_class,
                    'sequence_order' => $status->sequence_order,  // For sorting in mobile
                    'is_final' => (bool) $status->is_final         // For the closed-order gate (additive; old apps ignore it)
                ];
            })->values();
            
            return response()->json([
                'success' => true,
                'statuses' => $filteredStatuses
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to fetch order statuses', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch statuses',
                'statuses' => []
            ], 500);
        }
    }

    /**
     * STORE MODE: Get open orders
     * Reuses webapp logic from OrderController::index
     */
    public function getStoreOpenOrders(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_open_orders')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view open orders'
                ], 403);
            }

            // Flush any queued auto location-requests off this store poll (no-op
            // when the location automation is off). This is the "send in the
            // morning" trigger — the queue drains on the sync, not the cron.
            $this->fireLocationAutoDrain();

            // Get status filter if provided
            $statusFilter = $request->get('status', null);

            // Build query - same logic as webapp OrderController::index with tab='open'
            $query = OrderModel::with(['customer', 'lineItems', 'assignedRider', 'discounts'])
                ->where(function($q) {
                    $q->where('external_source', '!=', 'shopify')
                      ->orWhereNull('external_source');
                })
                ->whereNotIn('order_status', ['delivered', 'completed', 'cancelled', 'refunded']);

            // Exclude qurbani orders from store mode
            $qurbaniExcludeIds = \DB::table('t_crm_prod_order_line_item')
                ->join('t_crm_prod_product', 't_crm_prod_order_line_item.product_id', '=', 't_crm_prod_product.id')
                ->whereRaw("LOWER(t_crm_prod_product.attribute_1) = 'qurbani'")
                ->distinct()
                ->pluck('t_crm_prod_order_line_item.order_id');

            if ($qurbaniExcludeIds->isNotEmpty()) {
                $query->whereNotIn('id', $qurbaniExcludeIds);
            }

            // Apply status filter if provided
            if ($statusFilter) {
                $query->where('order_status', $statusFilter);
            }
            
            // Order by date
            $orders = $query->orderBy('order_date', 'desc')->get();
            
            // Format for mobile
            $formattedOrders = $orders->map(function($order) {
            // Build customer name (same logic as webapp)
            $customerName = $order->name ?? 'N/A';
            if (!$order->name && ($order->address_first_name || $order->address_last_name)) {
                $customerName = trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? ''));
            }
            if ($customerName === 'N/A' && $order->customer) {
                // Customer table has first_name and last_name, not name
                $customerName = trim(($order->customer->first_name ?? '') . ' ' . ($order->customer->last_name ?? '')) ?: 'Unknown';
            }
                
                // Check if customer has verified location and build verified_location object
                $hasVerifiedLocation = false;
                $verifiedLocation = null;
                if ($order->customer) {
                    $hasCoords = !empty($order->customer->latitude) && !empty($order->customer->longitude);
                    $hasUrl = !empty($order->customer->verified_location_url);
                    $hasVerifiedLocation = $hasCoords || $hasUrl;
                    
                    if ($hasVerifiedLocation) {
                        // Get coordinates: prioritize stored coords, else parse from URL
                        $lat = $order->customer->latitude ? (float)$order->customer->latitude : null;
                        $lng = $order->customer->longitude ? (float)$order->customer->longitude : null;
                        
                        // If no stored coords but URL exists, try to parse coords from URL
                        if ((!$lat || !$lng) && $hasUrl) {
                            $parsedCoords = $this->parseCoordinatesFromGoogleMapsUrl($order->customer->verified_location_url);
                            if ($parsedCoords) {
                                $lat = $parsedCoords['latitude'];
                                $lng = $parsedCoords['longitude'];
                            }
                        }
                        
                        // Build google_maps_url: prioritize stored URL, else construct from coordinates
                        $googleMapsUrl = $order->customer->verified_location_url;
                        if (!$googleMapsUrl && $lat && $lng) {
                            $googleMapsUrl = "https://www.google.com/maps?q={$lat},{$lng}";
                        }
                        
                        $verifiedLocation = [
                            'latitude' => $lat,
                            'longitude' => $lng,
                            'url' => $order->customer->verified_location_url ?? null,
                            'google_maps_url' => $googleMapsUrl,
                        ];
                    }
                }
                
                // Generate invoice URLs
                $invoiceImageUrl = route('orders.invoice.pdf', ['id' => $order->id, 'download_image' => 1]);
                $invoicePdfUrl = route('orders.invoice.pdf', ['id' => $order->id, 'force_pdf' => 1]);
                
                // Calculate preparation summary
                $totalItems = $order->lineItems->count();
                $preparingCount = $order->lineItems->where('preparation_status', 'preparing')->count();
                
                return [
                    'id' => $order->id,
                    'order_number' => $order->order_number ?? 'NF-' . str_pad($order->id, 4, '0', STR_PAD_LEFT),
                    'order_date' => $order->order_date,
                    'order_status' => $order->order_status,
                    'total_price' => $order->total_price,
                    'payment_method' => $order->payment_method,
                    'expected_packets' => $order->expected_packets,
                    'customer_name' => $customerName,
                    'customer_phone' => $order->customer->phone_original ?? $order->customer->phone ?? $order->address_phone ?? '',
                    'customer_address' => $order->customer->address1 ?? $order->address_address ?? '',
                    'customer_address1' => $order->customer->address1 ?? '',
                    'customer_address2' => $order->customer->address2 ?? '',
                    'customer_city' => $order->customer->city ?? '',
                    'customer_province' => $order->customer->province ?? '',
                    'customer_postal_code' => $order->customer->postal_code ?? '',
                    'customer_id' => $order->customer_id,
                    // ⭐ Customer Notes - use primary customer notes if order linked to merged duplicate
                    'customer_notes' => $order->customer ? (
                        $order->customer->merged_into_customer_id
                            ? (\App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id)?->notes ?? null)
                            : ($order->customer->notes ?? null)
                    ) : null,
                    'has_customer_notes' => $order->customer && !empty(
                        $order->customer->merged_into_customer_id
                            ? (\App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id)?->notes ?? null)
                            : ($order->customer->notes ?? null)
                    ),
                    // ⭐ Order Notes - order-specific notes
                    'order_note' => $order->note ?? null,
                    'has_order_note' => !empty($order->note),
                    'has_verified_location' => $hasVerifiedLocation,
                    'verified_location' => $verifiedLocation,
                    'assigned_rider' => $order->assignedRider ? [
                        'id' => $order->assignedRider->id,
                        'name' => $order->assignedRider->fullname,
                    ] : null,
                    'items_count' => $totalItems,
                    'items_summary' => $order->lineItems->map(function($item) {
                        return $item->name . ' (x' . $item->quantity . ')';
                    })->join(', '),
                    'line_items' => $order->lineItems->map(function($item) {
                        return [
                            'id' => $item->id,
                            'product_name' => $item->name ?? 'N/A',
                            'variant_name' => $item->sku ?? '',
                            'quantity' => $item->quantity,
                            'unit_price' => $item->unit_price,
                            'unit_price_formatted' => 'Rs. ' . number_format($item->unit_price, 0),
                            'line_total' => $item->line_total,
                            'total' => $item->line_total,
                            'total_formatted' => $item->is_free ? 'FREE' : 'Rs. ' . number_format($item->line_total, 0),
                            'preparation_status' => $item->preparation_status,
                            'is_free' => (bool) $item->is_free,
                            'instructions' => $item->instructions,
                        ];
                    }),
                    'shipping_total' => $order->shipping_total ?? 0,
                    'tip_amount' => $order->tip_amount ?? 0,
                    'discounts' => $order->discounts ? $order->discounts->map(function($discount) {
                        return [
                            'discount_amount' => $discount->discount_amount,
                            'discount_type' => $discount->discount_type,
                            // ⭐ The mobile receipt/invoice needs these to tell the
                            // customer's own ACCOUNT_BALANCE line apart from a real
                            // discount — without them it printed their money as a
                            // "Discount". Additive: older APKs ignore extra keys.
                            'coupon_code' => $discount->coupon_code,
                            'discount_title' => $discount->discount_title,
                        ];
                    })->toArray() : [],
                    'preparation_summary' => [
                        'preparing_count' => $preparingCount,
                        'total_items' => $totalItems,
                    ],
                    'invoice' => [
                        'image_url' => $invoiceImageUrl,
                        'pdf_url' => $invoicePdfUrl,
                    ],
                ];
            });
            
            return response()->json([
                'success' => true,
                'orders' => $formattedOrders,
                'total_count' => $formattedOrders->count()
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to fetch store open orders', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch open orders: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Get open orders (lightweight for list view)
     * Returns minimal data for fast loading, use getStoreOpenOrderDetails for full data
     */
    public function getStoreOpenOrdersLight(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_open_orders')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view open orders'
                ], 403);
            }

            // Flush queued auto location-requests off this poll (no-op when off).
            $this->fireLocationAutoDrain();

            // Get status filter if provided
            $statusFilter = $request->get('status', null);

            // Build optimized query - load line items for immediate "mark prepared" functionality
            // Note: Not using select() to avoid column name issues - optimization is in relationships
            $query = OrderModel::with(['customer' => function($q) {
                    // geocode_precision rides along so the board can tell a rooftop
                    // Google pin from an area guess BEFORE dispatch is pressed —
                    // that is what the pin prompts and the Auto Route gate key off.
                    // Aug-2026 — the three default_payment_method columns ride this
                    // existing select so the store Edit modal can say "the customer's
                    // default is Online, set by Taimur" before anyone overwrites it.
                    // The actor NAME is resolved once for the whole board below
                    // (never per row) — see $defaultPmActorMap.
                    $q->select('id', 'first_name', 'last_name', 'phone_original', 'latitude', 'longitude', 'geocoded_latitude', 'geocoded_longitude', 'geocode_precision', 'verified_location_url', 'notes', 'verified_location_saved_by', 'verified_location_saved_at', 'merged_into_customer_id', 'delivery_region_id', 'default_payment_method', 'default_payment_method_set_by', 'default_payment_method_set_at');
                }])
                ->with(['assignedRider' => function($q) {
                    $q->select('id', 'fullname');
                }])
                ->with(['lineItems' => function($q) {
                    $q->select('id', 'order_id', 'product_id', 'variant_id', 'name', 'sku', 'quantity', 'unit_price', 'line_total', 'preparation_status', 'is_free', 'instructions', 'quantity_source', 'quantity_updated_at', 'quantity_updated_by')
                      ->with(['product:id,attribute_1', 'qtyUpdater:id,fullname']); // category + barcode-qty updater
                }])
                ->with(['discounts']) // ⭐ Load discounts for invoice view
                ->where(function($q) {
                    $q->where('external_source', '!=', 'shopify')
                      ->orWhereNull('external_source');
                })
                ->whereNotIn('order_status', ['delivered', 'completed', 'cancelled', 'refunded']);

            // Exclude qurbani orders from store mode (mixed orders are blocked at creation)
            $qurbaniExcludeIds = \DB::table('t_crm_prod_order_line_item')
                ->join('t_crm_prod_product', 't_crm_prod_order_line_item.product_id', '=', 't_crm_prod_product.id')
                ->whereRaw("LOWER(t_crm_prod_product.attribute_1) = 'qurbani'")
                ->distinct()
                ->pluck('t_crm_prod_order_line_item.order_id');

            if ($qurbaniExcludeIds->isNotEmpty()) {
                $query->whereNotIn('id', $qurbaniExcludeIds);
            }

            // Apply status filter if provided
            if ($statusFilter) {
                $query->where('order_status', $statusFilter);
            }
            
            /**
             * ⭐ OPTIONAL RIDER FILTER (Sep-2026) — for the van board's route sheet.
             *
             * The sheet needs ONE rider's complete sequenceable list, and the van payload
             * cannot supply it: the manifest only knows boxes physically aboard, so it cannot
             * see his non-van out-for-delivery stops, his `processing` rows, or (for a cargo
             * rider) the run he is on right now. Renumbering from a partial list would write
             * priorities that collide with orders the screen never saw.
             *
             * ⚠ Absent = the whole board, exactly as every existing caller expects. This only
             *   spares the sheet from pulling every open order in the store to filter five.
             */
            $riderFilter = $request->get('rider_id');
            if ($riderFilter !== null && $riderFilter !== '') {
                $query->where('assigned_rider_user_id', (int) $riderFilter);
            }

            // Order by date
            $orders = $query->orderBy('order_date', 'desc')->get();

            // Barcode-qty: batch-resolve Czerlop ids (sku -> variant -> product) for all line items,
            // so the list view can match scans + show the weighed badge without a detail fetch.
            $allSkus = $orders->pluck('lineItems')->flatten(1)->pluck('sku')->filter()->unique()->values()->all();
            $skuCzerlop = [];
            $skuWeightFactor = []; // sku -> product weight_factor (for scan/manual qty division; default 1)
            // 📦 sku -> 'kg' | 'pcs'. Tells the scanner whether a scale label's five
            // middle digits are GRAMS or a piece count it must ignore. Absent column
            // (web uploaded before the SQL) => every product reads 'kg', i.e. today.
            $skuSellUnit = [];
            $hasSellUnit = \App\Models\CRM\ProductModel::supportsSellUnit();
            if (!empty($allSkus)) {
                $sellCols = ['v.sku', 'p.czerlop_product_id', 'p.weight_factor'];
                if ($hasSellUnit) { $sellCols[] = 'p.sell_unit'; }
                foreach (\DB::table('t_crm_prod_product_variant as v')
                    ->join('t_crm_prod_product as p', 'p.id', '=', 'v.product_id')
                    ->whereIn('v.sku', $allSkus)
                    ->select($sellCols)->get() as $row) {
                    if ($row->czerlop_product_id !== null) {
                        $skuCzerlop[$row->sku] = (int) $row->czerlop_product_id;
                    }
                    $skuWeightFactor[$row->sku] = (float) ($row->weight_factor ?? 1.0);
                    $skuSellUnit[$row->sku] = $hasSellUnit
                        ? \App\Models\CRM\ProductModel::normaliseSellUnit($row->sell_unit ?? null)
                        : \App\Models\CRM\ProductModel::SELL_UNIT_KG;
                }
            }

            // Get preparation summaries in single query (avoid N+1)
            $prepSummaries = \DB::table('t_crm_prod_order_line_item')
                ->whereIn('order_id', $orders->pluck('id'))
                ->groupBy('order_id')
                ->selectRaw('order_id, COUNT(*) as total, SUM(CASE WHEN preparation_status = "preparing" THEN 1 ELSE 0 END) as preparing')
                ->get()
                ->keyBy('order_id');
            
            // ❄️ Detect orders containing Khaas (non-default BU) products in single query
            $orderIds = $orders->pluck('id');
            $khaasOrderIds = collect();
            if ($orderIds->isNotEmpty()) {
                $khaasOrderIds = \DB::table('t_crm_prod_order_line_item')
                    ->join('t_crm_prod_product', 't_crm_prod_order_line_item.product_id', '=', 't_crm_prod_product.id')
                    ->whereIn('t_crm_prod_order_line_item.order_id', $orderIds)
                    ->where('t_crm_prod_product.business_unit_id', '!=', 1)
                    ->distinct()
                    ->pluck('t_crm_prod_order_line_item.order_id');
            }
            
            $regionMap = [];
            try {
                $regionMap = \DB::table('t_ops_delivery_region')
                    ->where('is_active', 1)
                    ->pluck('name', 'id')
                    ->toArray();
            } catch (\Exception $e) {}

            // Batch WhatsApp unread check: find which customers have unread messages for this user
            $unreadCustomerIds = [];
            $hasWaAccess = false;
            try {
                $hasFull = $user->hasMobilePermission('view_whatsapp_messages');
                $hasLimited = $user->hasMobilePermission('view_whatsapp_messages_limited');
                $hasWaAccess = $hasFull || $hasLimited;

                if ($hasWaAccess) {
                    $customerIds = $orders->pluck('customer_id')->filter()->unique()->values()->toArray();
                    if (!empty($customerIds)) {
                        $convMap = DB::table('t_wa_conversations')
                            ->whereIn('customer_id', $customerIds)
                            ->pluck('id', 'customer_id')
                            ->toArray();

                        if (!empty($convMap)) {
                            $convIds = array_values($convMap);
                            $cutoff = $hasLimited ? now()->subDay()->startOfDay() : null;

                            $unreadConvQ = DB::table('t_wa_messages as m')
                                ->leftJoin('t_wa_conversation_reads as r', function ($j) use ($user) {
                                    $j->on('r.conversation_id', '=', 'm.conversation_id')
                                      ->where('r.user_id', '=', $user->id);
                                })
                                ->whereIn('m.conversation_id', $convIds)
                                ->where('m.direction', 'inbound')
                                ->where('m.created_at', '>=', \App\Models\FIN\ConfigModel::get('wa_unread_floor_date', '2026-06-28'))
                                ->where(function ($w) {
                                    $w->whereNull('r.last_read_at')
                                      ->orWhereColumn('m.created_at', '>', 'r.last_read_at');
                                })
                                ->whereRaw('NOT EXISTS (
                                    SELECT 1 FROM t_wa_messages m2
                                    WHERE m2.conversation_id = m.conversation_id
                                      AND m2.direction = \'outbound\' AND m2.sent_by IS NOT NULL
                                      AND m2.created_at > m.created_at
                                )');

                            if (\Schema::hasColumn('t_wa_conversations', 'global_read_at')) {
                                $unreadConvQ->leftJoin('t_wa_conversations as wc', 'wc.id', '=', 'm.conversation_id')
                                    ->where(function ($w) {
                                        $w->whereNull('wc.global_read_at')
                                          ->orWhereColumn('m.created_at', '>', 'wc.global_read_at');
                                    });
                            }

                            if ($cutoff) {
                                $unreadConvQ->where('m.created_at', '>=', $cutoff);
                            }

                            $unreadConvIds = $unreadConvQ->distinct()->pluck('m.conversation_id')->all();
                            $unreadConvIdSet = array_flip(array_map('intval', $unreadConvIds));

                            foreach ($convMap as $custId => $convId) {
                                if (isset($unreadConvIdSet[(int) $convId])) {
                                    $unreadCustomerIds[(int) $custId] = true;
                                }
                            }
                        }
                    }
                }
            } catch (\Exception $e) {
                Log::debug('Open orders unread check skipped', ['error' => $e->getMessage()]);
            }

            // Jun-2026 — Payment-proof status for online-payment orders (bulk, no N+1).
            $paymentProofMap = [];
            if (config('payment_signals.enabled') && $orderIds->isNotEmpty()) {
                $onlineProofOrderIds = $orders->filter(function($o) {
                    return !in_array(strtolower($o->payment_method ?? ''), ['cash', 'cash_on_delivery', 'cod']);
                })->pluck('id')->all();
                if (!empty($onlineProofOrderIds)) {
                    $paymentProofMap = app(\App\Services\Payments\Signals\PaymentProofStatusService::class)
                        ->forOrders($onlineProofOrderIds);
                }
            }

            // ⭐ Dispatch attribution names (bulk, no N+1) — resolve who dispatched
            //    / reordered so the UI can show "Dispatched by <name>".
            $dispatchActorMap = [];
            $actorIds = $orders->pluck('eta_calculated_by')
                ->merge($orders->pluck('delivery_priority_updated_by'))
                ->merge($orders->pluck('dispatch_scanned_by'))
                ->filter()
                ->unique()
                ->values()
                ->all();
            if (!empty($actorIds)) {
                $dispatchActorMap = \DB::table('t_sys_user')
                    ->whereIn('id', $actorIds)
                    ->pluck('fullname', 'id')
                    ->toArray();
            }

            // ⭐ Aug-2026 — customers on this board sitting on a location pin we
            //    received but did not save. ONE batched, indexed lookup for the
            //    whole board (never per row), same shape as the maps above. Empty
            //    if the audit table isn't on this environment yet.
            $pinPendingByCustomer = [];
            try {
                $pinPendingByCustomer = app(\App\Services\Location\PinHistoryService::class)
                    ->pendingReplies($orders->pluck('customer_id')->filter()->unique()->values()->all());
            } catch (\Throwable $e) {
                \Log::debug('store open-orders: pin-pending map skipped', ['error' => $e->getMessage()]);
            }

            // ⭐ Aug-2026 — names behind each customer's DEFAULT payment method, so
            //    the store Edit modal can show "set by Taimur" before anyone
            //    overwrites it. One batched lookup for the whole board, same shape
            //    as $dispatchActorMap above — never a per-row query.
            $defaultPmActorMap = [];
            $defaultPmActorIds = $orders->pluck('customer.default_payment_method_set_by')
                ->filter()->unique()->values()->all();
            if (!empty($defaultPmActorIds)) {
                $defaultPmActorMap = \DB::table('t_sys_user')
                    ->whereIn('id', $defaultPmActorIds)
                    ->pluck('fullname', 'id')
                    ->toArray();
            }

            // Format for mobile (lightweight)
            $formattedOrders = $orders->map(function($order) use ($prepSummaries, $khaasOrderIds, $regionMap, $unreadCustomerIds, $hasWaAccess, $paymentProofMap, $dispatchActorMap, $skuCzerlop, $skuWeightFactor, $skuSellUnit, $pinPendingByCustomer, $defaultPmActorMap) {
                // Build customer name
                $customerName = $order->name ?? 'N/A';
                if (!$order->name && ($order->address_first_name || $order->address_last_name)) {
                    $customerName = trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? ''));
                }
                if ($customerName === 'N/A' && $order->customer) {
                    // Customer table has first_name and last_name, not name
                    $customerName = trim(($order->customer->first_name ?? '') . ' ' . ($order->customer->last_name ?? '')) ?: 'Unknown';
                }
                
                // Check verified location and build verified_location object
                $hasVerifiedLocation = false;
                $verifiedLocation = null;
                if ($order->customer) {
                    $hasCoords = !empty($order->customer->latitude) && !empty($order->customer->longitude);
                    $hasUrl = !empty($order->customer->verified_location_url);
                    $hasVerifiedLocation = $hasCoords || $hasUrl;
                    
                    if ($hasVerifiedLocation) {
                        // Get coordinates: prioritize stored coords, else parse from URL
                        $lat = $order->customer->latitude ? (float)$order->customer->latitude : null;
                        $lng = $order->customer->longitude ? (float)$order->customer->longitude : null;
                        
                        // If no stored coords but URL exists, try to parse coords from URL
                        if ((!$lat || !$lng) && $hasUrl) {
                            $parsedCoords = $this->parseCoordinatesFromGoogleMapsUrl($order->customer->verified_location_url);
                            if ($parsedCoords) {
                                $lat = $parsedCoords['latitude'];
                                $lng = $parsedCoords['longitude'];
                            }
                        }
                        
                        // Build google_maps_url: prioritize stored URL, else construct from coordinates
                        $googleMapsUrl = $order->customer->verified_location_url;
                        if (!$googleMapsUrl && $lat && $lng) {
                            $googleMapsUrl = "https://www.google.com/maps?q={$lat},{$lng}";
                        }
                        
                        // ⭐ Get saved_by label (staff name, or "Customer" for app-set pins)
                        $savedByName = \App\Models\CRM\CustomerModel::verifierLabel($order->customer->verified_location_saved_by);
                        
                        $verifiedLocation = [
                            'latitude' => $lat,
                            'longitude' => $lng,
                            'url' => $order->customer->verified_location_url ?? null,
                            'google_maps_url' => $googleMapsUrl,
                            // ⭐ Who saved and when - for display in UI
                            'saved_by' => $savedByName,
                            'saved_at' => $order->customer->verified_location_saved_at,
                        ];
                    }
                }
                
                // Get preparation summary from pre-fetched data
                $prepSummary = $prepSummaries[$order->id] ?? null;
                
                // ⭐ Safety net: if the order's customer is a merged duplicate, use the primary customer's notes
                $effectiveCustomerNotes = null;
                if ($order->customer) {
                    if ($order->customer->merged_into_customer_id) {
                        // This order is linked to a merged duplicate - get primary customer's notes
                        $primaryCustomer = \App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id);
                        $effectiveCustomerNotes = $primaryCustomer ? ($primaryCustomer->notes ?? null) : null;
                    } else {
                        $effectiveCustomerNotes = $order->customer->notes ?? null;
                    }
                }
                
                return [
                    'id' => $order->id,
                    'order_number' => $order->order_number ?? 'NF-' . str_pad($order->id, 4, '0', STR_PAD_LEFT),
                    'order_date' => $order->order_date,
                    'order_status' => $order->order_status,
                    'total_price' => $order->total_price,
                    // ⭐ Aug-2026 — shipping/delivery fee for the store board's order
                    //    card. Same `shipping_total` column the invoice's SHIPPING
                    //    line prints, so the card and the invoice can never disagree;
                    //    edit the fee and the next poll shows the new number.
                    //    Cast to float so 0 arrives as 0, not the string "0.00"
                    //    (the card has to tell "free delivery" from "no data").
                    'shipping_total' => (float) ($order->shipping_total ?? 0),
                    'delivery_priority' => $order->delivery_priority, // ⭐ Delivery sequence priority
                    // ⭐ Estimated delivery time (from "Get Times" / Dispatch)
                    'estimated_delivery_at' => $order->estimated_delivery_at,
                    'estimated_delivery_at_display' => $order->estimated_delivery_at 
                        ? \Carbon\Carbon::parse($order->estimated_delivery_at)->format('h:i A')
                        : null,
                    // ⭐ Dispatch attribution — lets Store Mode see when a rider (or another
                    //    manager) reordered / dispatched. is_dispatched = ETAs were calculated.
                    'is_dispatched' => !empty($order->eta_calculated_at),
                    'eta_calculated_at' => $order->eta_calculated_at,
                    'dispatched_at_display' => $order->eta_calculated_at
                        ? \Carbon\Carbon::parse($order->eta_calculated_at)->format('h:i A')
                        : null,
                    'eta_calculated_by' => $order->eta_calculated_by,
                    'eta_calculated_by_name' => $order->eta_calculated_by
                        ? ($dispatchActorMap[$order->eta_calculated_by] ?? null)
                        : null,
                    'delivery_priority_updated_by' => $order->delivery_priority_updated_by,
                    'delivery_priority_updated_by_name' => $order->delivery_priority_updated_by
                        ? ($dispatchActorMap[$order->delivery_priority_updated_by] ?? null)
                        : null,
                    'delivery_priority_updated_at' => $order->delivery_priority_updated_at,
                    'expected_packets' => $order->expected_packets, // ⭐ Packet info (from manager)
                    'actual_packets' => $order->actual_packets,     // ⭐ Actual packets (from rider, after delivery)
                    // ⭐ Aug-2026 — the CUSTOMER's remembered payment choice + who set
                    //    it, shown in the store Edit modal before anyone overwrites it.
                    //    null = no default. Deliberately NOT sent to rider mode (the
                    //    rider only needs this order's own payment_method).
                    'customer_default_payment' => $order->customer && $order->customer->default_payment_method
                        ? [
                            'method' => $order->customer->default_payment_method,
                            'label' => $order->customer->default_payment_method === 'online' ? 'Online' : 'Cash',
                            'set_by_name' => $order->customer->default_payment_method_set_by
                                ? ($defaultPmActorMap[$order->customer->default_payment_method_set_by] ?? null)
                                : null,
                            'set_at_short' => $order->customer->default_payment_method_set_at
                                ? \Carbon\Carbon::parse($order->customer->default_payment_method_set_at)->format('M d')
                                : null,
                        ]
                        : null,
                    // Dispatch package-scan (store hand-over). scanned_count vs expected_packets
                    // drives the progress; dispatch_scanned_at set = "ready to leave" tick.
                    'dispatch_scanned_count' => $order->dispatch_scanned_packets ? count((array) json_decode($order->dispatch_scanned_packets, true)) : 0,
                    'dispatch_scanned_at' => $order->dispatch_scanned_at,
                    'dispatch_scanned_by_name' => $order->dispatch_scanned_by ? ($dispatchActorMap[$order->dispatch_scanned_by] ?? null) : null,
                    // 🚚 Van load-scan (Aug-2026): "On Van" status = the PLAN, these
                    // stamps = the box physically scanned aboard. The store's Load-van
                    // button shows on tagged rows until van_loaded_at lands. NULL on
                    // servers without batch 14 — the button just never appears.
                    'van_loaded_count' => $order->van_loaded_packets ? count((array) json_decode($order->van_loaded_packets, true)) : 0,
                    'van_loaded_at' => $order->van_loaded_at,
                    // ⭐ WHOSE van (Aug-31). Without this the store's load-scan list
                    //    could only be filtered on "tagged and not yet loaded", so an
                    //    order already aboard — or already sent out — was absent from
                    //    the scanner and answered "not in this load" instead of
                    //    reaching the server. That made the after-dispatch pull-back
                    //    unreachable from the one screen the store actually scans in.
                    'van_user_id' => $order->van_user_id,
                    'payment_method' => $order->payment_method,     // ⭐ Payment method (cash/online)
                    'payment_proof' => $paymentProofMap[$order->id] ?? null, // Jun-2026: WhatsApp/email proof status
                    'customer_id' => $order->customer_id, // Added for verified location functionality
                    'customer_name' => $customerName,
                    // Eager address/phone for immediate display on list
                    'customer_address' => trim(implode(', ', array_filter([
                        $order->address_line1,
                        $order->address_line2,
                        $order->address_city,
                        $order->address_province
                    ]))),
                    'customer_phone' => $order->address_phone ?? ($order->customer->phone_original ?? null),
                    // ⭐ Customer Notes - use primary customer's notes if order is linked to merged duplicate
                    'customer_notes' => $effectiveCustomerNotes,
                    'has_customer_notes' => !empty($effectiveCustomerNotes),
                    // ⭐ Order Notes - order-specific notes
                    'order_note' => $order->note ?? null,
                    'has_order_note' => !empty($order->note),
                    'assigned_rider_id' => $order->assigned_rider_user_id,
                    'assigned_rider' => $order->assignedRider ? [
                        'id' => $order->assignedRider->id,
                        'name' => $order->assignedRider->fullname,
                    ] : null,
                    'preparation_summary' => [
                        'preparing_count' => $prepSummary->preparing ?? 0,
                        'total_items' => $prepSummary->total ?? 0,
                    ],
                    'has_verified_location' => $hasVerifiedLocation,
                    'verified_location' => $verifiedLocation,
                    'has_khaas_item' => $khaasOrderIds->contains($order->id), // ❄️ Khaas product indicator
                    'has_unread_message' => isset($unreadCustomerIds[(int) $order->customer_id]),
                    // ⭐ Aug-2026 — this customer sent a location pin we did NOT
                    //    save, and nobody has dealt with it. Fires precisely when
                    //    a verified pin already exists, so the row chip must NOT
                    //    go through locationChip() (which shows nothing once a
                    //    customer is verified, by design).
                    'pin_reply_pending' => $pinPendingByCustomer[(int) $order->customer_id] ?? null,
                    'has_wa_access' => $hasWaAccess,
                    // ⭐ Customer location data for route map + the location-confidence
                    //    chip. The client derives the tier from these four fields, so
                    //    it re-derives on every poll and clears itself the moment a
                    //    pin is added — nothing to invalidate by hand.
                    'customer' => $order->customer ? [
                        'id' => $order->customer->id,
                        'latitude' => $order->customer->latitude,
                        'longitude' => $order->customer->longitude,
                        'geocoded_latitude' => $order->customer->geocoded_latitude,
                        'geocoded_longitude' => $order->customer->geocoded_longitude,
                        'geocode_precision' => $order->customer->geocode_precision,
                    ] : null,
                    'external_source' => $order->external_source,
                    'delivery_region_id' => $order->customer->delivery_region_id ?? null,
                    'delivery_region_name' => ($order->customer->delivery_region_id ?? null) ? ($regionMap[$order->customer->delivery_region_id] ?? null) : null,
                    'updated_at' => $order->updated_at ? $order->updated_at->toIso8601String() : null, // ⭐ For processing time calculation
                    // ⭐ Invoice fields - needed for invoice view
                    'subtotal_price' => $order->subtotal_price ?? 0,
                    'discount_total' => $order->discount_total ?? 0,
                    'shipping_total' => $order->shipping_total ?? 0,
                    'tip_amount' => $order->tip_amount ?? 0,
                    'discounts' => $order->discounts ? $order->discounts->map(function($discount) {
                        return [
                            'discount_amount' => $discount->discount_amount,
                            'discount_type' => $discount->discount_type,
                            // ⭐ The mobile receipt/invoice needs these to tell the
                            // customer's own ACCOUNT_BALANCE line apart from a real
                            // discount — without them it printed their money as a
                            // "Discount". Additive: older APKs ignore extra keys.
                            'coupon_code' => $discount->coupon_code,
                            'discount_title' => $discount->discount_title,
                        ];
                    })->toArray() : [],
                    'line_items' => $order->lineItems->map(function($item) use ($skuCzerlop, $skuWeightFactor, $skuSellUnit) {
                        $liSku = trim((string) ($item->sku ?? ''));
                        return [
                            'id' => $item->id,
                            'name' => $item->name ?? 'N/A',
                            'product_name' => $item->name ?? 'N/A',
                            'variant_name' => $item->sku ?? '',
                            'sku' => $item->sku ?? '',
                            'czerlop_product_id' => ($liSku !== '' && isset($skuCzerlop[$liSku])) ? $skuCzerlop[$liSku] : null,
                            'weight_factor' => ($liSku !== '' && isset($skuWeightFactor[$liSku])) ? $skuWeightFactor[$liSku] : 1.0,
                            // 📦 'kg' = weighed (label carries grams) | 'pcs' = counted boxes
                            //    (label identifies the product; quantity stays as ordered).
                            'sell_unit' => ($liSku !== '' && isset($skuSellUnit[$liSku])) ? $skuSellUnit[$liSku] : 'kg',
                            'quantity' => (float) $item->quantity,
                            'quantity_source' => $item->quantity_source ?? null,
                            'quantity_updated_at' => $item->quantity_updated_at ? $item->quantity_updated_at->toIso8601String() : null,
                            'quantity_updated_by_name' => optional($item->qtyUpdater)->fullname,
                            'unit_price' => (float) $item->unit_price,
                            'unit_price_formatted' => $item->unit_price ? 'Rs. ' . number_format($item->unit_price, 0) : null,
                            'line_total' => (float) $item->line_total,
                            'preparation_status' => $item->preparation_status,
                            'is_free' => (bool) $item->is_free,
                            'instructions' => $item->instructions,
                            'category' => optional($item->product)->attribute_1 ?: null, // product category for grouping
                        ];
                    })->values()->toArray(),
                ];
            });
            
            // ⭐ PINNED RIDER DASHBOARD: Include rider summaries for pinned riders
            // Supports both single rider (pinned_rider_id) and multiple riders (pinned_rider_ids)
            $riderSummary = null;
            $riderSummaries = null;
            
            // Single rider (backward compatible)
            $pinnedRiderId = $request->get('pinned_rider_id');
            if ($pinnedRiderId) {
                $riderSummary = $this->getRiderDashboardSummary($pinnedRiderId);
            }
            
            // Multiple riders (new: prefetch all at once for seamless tab switching)
            $pinnedRiderIds = $request->get('pinned_rider_ids');
            if ($pinnedRiderIds) {
                // Accept comma-separated string or array
                if (is_string($pinnedRiderIds)) {
                    $pinnedRiderIds = array_filter(array_map('trim', explode(',', $pinnedRiderIds)));
                }
                if (!empty($pinnedRiderIds)) {
                    $riderSummaries = [];
                    foreach ($pinnedRiderIds as $id) {
                        $summary = $this->getRiderDashboardSummary($id);
                        if ($summary) {
                            $riderSummaries[$id] = $summary;
                        }
                    }
                }
            }
            
            $response = [
                'success' => true,
                'orders' => $formattedOrders,
                'total_count' => $formattedOrders->count()
            ];

            // ⭐ Store-wide "left office without dispatching" watch (for the
            //    dismissible banner shown to all store users). Only checks
            //    riders who actually have undispatched OFD orders, so it's
            //    cheap and self-clearing.
            try {
                $candidateRiderIds = \DB::table('t_crm_prod_order')
                    ->where('order_status', 'out_for_delivery')
                    ->whereNull('eta_calculated_at')
                    ->whereNotNull('assigned_rider_user_id')
                    ->distinct()
                    ->pluck('assigned_rider_user_id')
                    ->toArray();
                $leftRiders = [];
                if (!empty($candidateRiderIds)) {
                    foreach ($this->detectLeftWithoutDispatch($candidateRiderIds) as $rid => $info) {
                        // C7 (Sep-29): a store cancel while he was out, never re-sent, stays
                        // on the banner with `store_cancelled` (new APK words it as such; an
                        // old APK lists him under the plain warning). He is not blamed.
                        if (!empty($info['flagged']) || !empty($info['store_cancelled'])) {
                            $leftRiders[] = [
                                'rider_id' => $rid,
                                'rider_name' => $info['rider_name'] ?: "Rider #{$rid}",
                                'undispatched_count' => $info['undispatched_count'],
                                'distance_meters' => $info['distance_meters'],
                                'store_cancelled' => empty($info['flagged']) && !empty($info['store_cancelled']),
                            ];
                        }
                    }
                }
                $response['left_without_dispatch_riders'] = $leftRiders;
            } catch (\Throwable $e) {
                // Never let the watch break the orders feed.
                $response['left_without_dispatch_riders'] = [];
                \Log::warning('left_without_dispatch watch failed (non-fatal)', ['error' => $e->getMessage()]);
            }

            // ⭐ Store-wide watch: orders that went out WITH A GUESSED TIME because
            //    the customer has no location at all — no verified pin and no Google
            //    pin either. The rider is driving to a written address and the ETA on
            //    that stop is a flat estimate, so the store should know while the run
            //    is still live and can still fix it.
            //
            //    Deliberately DERIVED, not a stored flag: "dispatched" = OFD with an
            //    eta_calculated_at, "no location" = both coordinate pairs empty. So it
            //    disappears by itself the moment anyone adds a pin or the order is
            //    delivered — there is no stale alert to clear, and no schema for it.
            //
            //    A Google pin (any precision) does NOT appear here. That is the whole
            //    point of the tiers: raising this for stops we CAN time would train
            //    everyone to ignore the banner.
            try {
                $noPinRows = \DB::table('t_crm_prod_order as o')
                    ->join('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                    ->leftJoin('t_sys_user as u', 'u.id', '=', 'o.assigned_rider_user_id')
                    ->where('o.order_status', 'out_for_delivery')
                    ->whereNotNull('o.eta_calculated_at')
                    ->where(function ($q) {
                        $q->whereNull('c.latitude')->orWhereNull('c.longitude');
                    })
                    ->where(function ($q) {
                        $q->whereNull('c.geocoded_latitude')->orWhereNull('c.geocoded_longitude');
                    })
                    ->orderBy('o.delivery_priority')
                    ->limit(25)
                    ->get([
                        'o.id',
                        'o.order_number',
                        'o.assigned_rider_user_id',
                        'u.fullname as rider_name',
                        \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    ]);

                $response['no_pin_dispatch_orders'] = $noPinRows->map(fn($r) => [
                    'order_id'      => (int) $r->id,
                    'order_number'  => $r->order_number,
                    'customer_name' => trim((string) $r->customer_name),
                    'rider_id'      => $r->assigned_rider_user_id ? (int) $r->assigned_rider_user_id : null,
                    'rider_name'    => $r->rider_name ?: null,
                ])->values()->all();
            } catch (\Throwable $e) {
                $response['no_pin_dispatch_orders'] = [];
                \Log::warning('no_pin_dispatch watch failed (non-fatal)', ['error' => $e->getMessage()]);
            }

            // ⭐ Riders stuck at a door on a LOCKED verified pin. Pressing
            //    "verify" raised this; the store banner offers the unlock so no
            //    phone call is needed. Clears itself the moment it is answered
            //    (unlock / save / relock / dismiss) — see PinUnlockRequestService.
            $response['pin_unlock_requests'] = \App\Services\Location\PinUnlockRequestService::live();

            // ⭐ 🔁 Sep-2026 — riders waiting for a VEHICLE HANDOVER to be approved
            //    (Rajab asking for the van in the morning, handing it back at night).
            //    Rides THIS poll rather than opening a second one, exactly as the
            //    unlock banner does: the store screen already asks every 30s, and a
            //    separate timer would just be more traffic for the same answer.
            // ⚠ The service returns an EMPTY LIST for anyone without `assign_vehicles`,
            //   so this is safe to attach for every store user — the payload itself
            //   carries the permission decision and the phone renders what it is given.
            // ⚠ Try-wrapped: a broken banner must never break the orders board.
            try {
                $vhrSvc = new \App\Services\Riders\VehicleHandoverRequestService();
                $vhrUser = $request->user() ?: auth()->user();
                $vhrCan = $vhrUser && method_exists($vhrUser, 'hasPermission')
                    && (!method_exists($vhrUser, 'isReadOnly') || !$vhrUser->isReadOnly())
                    && $vhrUser->hasPermission('assign_vehicles');
                $response['vehicle_requests'] = $vhrCan ? $vhrSvc->live() : [];
            } catch (\Throwable $e) {
                $response['vehicle_requests'] = [];
                \Log::warning('vehicle handover banner failed (non-fatal)', ['error' => $e->getMessage()]);
            }

            // ⭐ Aug-2026 — customers on THIS board who sent us a location pin we
            //    did not save. Same self-clearing contract as the unlock banner:
            //    the flag lives only while the refusal is still the customer's
            //    latest pin event, so saving a pin (from anywhere — web, store,
            //    rider, or the customer's own next reply) makes the banner go by
            //    itself on the next poll. Nothing to dismiss by hand.
            $response['pin_reply_pending_orders'] = collect($formattedOrders)
                ->filter(fn ($o) => !empty($o['pin_reply_pending']))
                ->map(fn ($o) => [
                    'order_id'      => (int) $o['id'],
                    'order_number'  => $o['order_number'] ?? null,
                    'customer_id'   => (int) $o['customer_id'],
                    'customer_name' => $o['customer_name'] ?? 'Customer',
                    'away_text'     => $o['pin_reply_pending']['away_text'] ?? null,
                    'at_human'      => $o['pin_reply_pending']['at_human'] ?? null,
                    'offered'       => $o['pin_reply_pending']['offered'] ?? null,
                ])
                ->values()
                ->all();
            
            // Single rider summary (backward compatible)
            if ($riderSummary) {
                $response['rider_summary'] = $riderSummary;
            }
            
            // Multiple rider summaries (new: keyed by rider ID)
            if ($riderSummaries && !empty($riderSummaries)) {
                $response['rider_summaries'] = $riderSummaries;
            }
            
            return response()->json($response);
            
        } catch (\Exception $e) {
            \Log::error('Failed to fetch store open orders (light)', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch open orders: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * ⭐ PINNED RIDER DASHBOARD: Get rider summary for dashboard header
     * Returns delivered count, last delivered order, location and distance from office
     * 
     * @param int $riderId
     * @return array|null
     */
    private function getRiderDashboardSummary($riderId)
    {
        try {
            $today = now()->format('Y-m-d');
            
            // Get rider info
            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->where('is_active', 1)
                ->select('id', 'fullname as name')
                ->first();
            
            if (!$rider) {
                return null;
            }
            
            // ⭐ Get delivered orders count TODAY for this rider
            // Based on status history (when order was marked delivered)
            $deliveredToday = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as osh', function($join) use ($today) {
                    $join->on('o.id', '=', 'osh.order_id')
                         ->where('osh.status_code', '=', 'delivered')
                         ->whereDate('osh.changed_at', $today);
                })
                ->where('o.assigned_rider_user_id', $riderId)
                ->select(\DB::raw('COUNT(DISTINCT o.id) as count'))
                ->first();
            
            $deliveredTodayCount = $deliveredToday->count ?? 0;
            
            // ⭐ Get last delivered order for this rider (today)
            $lastDelivered = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as osh', function($join) use ($today) {
                    $join->on('o.id', '=', 'osh.order_id')
                         ->where('osh.status_code', '=', 'delivered')
                         ->whereDate('osh.changed_at', $today);
                })
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->where('o.assigned_rider_user_id', $riderId)
                ->select([
                    'o.id',
                    'o.order_number',
                    \DB::raw('CONCAT(COALESCE(c.first_name, ""), " ", COALESCE(c.last_name, "")) as customer_name'),
                    'osh.changed_at as delivered_at',
                ])
                ->orderBy('osh.changed_at', 'desc')
                ->first();
            
            // ⭐ Get rider's current location (from heartbeat)
            $riderLocation = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->where('captured_at', '>=', now()->subHours(24))
                ->orderBy('captured_at', 'desc')
                ->select('latitude', 'longitude', 'accuracy', 'captured_at')
                ->first();
            
            // ⭐ Calculate distance from office using LocationService — against TODAY's
            // shift location (same base check-in uses), not the rider's default assigned
            // location, so a rider working at LaCarne today reads distance-from-LaCarne.
            $distanceInfo = null;
            if ($riderLocation) {
                $shiftLocId = null;
                try {
                    $shiftLocId = (new \App\Services\ShiftResolutionService())
                        ->getUserShift($riderId, now()->format('Y-m-d'))['location_id'] ?? null;
                } catch (\Throwable $e) { /* fall back to assigned → primary */ }
                $distanceInfo = \App\Services\LocationService::calculateDistanceFromBase(
                    $riderLocation->latitude,
                    $riderLocation->longitude,
                    $riderId,
                    $shiftLocId
                );
            }
            
            // ⭐ Get rider's online status (based on last sync or location)
            $lastSync = \DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $riderId)
                ->whereNotNull('rider_last_sync_at')
                ->max('rider_last_sync_at');
            
            // Determine online status
            $lastSeenTime = null;
            $lastSeenText = 'Unknown';
            $isOnline = false;
            
            // Use the most recent: location heartbeat or order sync
            if ($riderLocation && $riderLocation->captured_at) {
                $locTime = \Carbon\Carbon::parse($riderLocation->captured_at);
                if (!$lastSeenTime || $locTime->gt($lastSeenTime)) {
                    $lastSeenTime = $locTime;
                }
            }
            if ($lastSync) {
                $syncTime = \Carbon\Carbon::parse($lastSync);
                if (!$lastSeenTime || $syncTime->gt($lastSeenTime)) {
                    $lastSeenTime = $syncTime;
                }
            }
            
            if ($lastSeenTime) {
                $ageMinutes = abs(now()->diffInMinutes($lastSeenTime));
                $lastSeenText = $lastSeenTime->diffForHumans();
                $isOnline = $ageMinutes <= 5;  // Online if seen within 5 minutes
            }
            
            return [
                'rider' => [
                    'id' => $rider->id,
                    'name' => $rider->name,
                    'is_online' => $isOnline,
                    'last_seen' => $lastSeenText,
                    'last_seen_at' => $lastSeenTime ? $lastSeenTime->toIso8601String() : null,
                ],
                'delivered_today' => $deliveredTodayCount,
                'last_delivered' => $lastDelivered ? [
                    'order_id' => $lastDelivered->id,
                    'order_number' => $lastDelivered->order_number,
                    'customer_name' => trim($lastDelivered->customer_name) ?: 'Unknown',
                    'delivered_at' => \Carbon\Carbon::parse($lastDelivered->delivered_at)->format('h:i A'),
                ] : null,
                'location' => $riderLocation ? [
                    'latitude' => (float)$riderLocation->latitude,
                    'longitude' => (float)$riderLocation->longitude,
                    'accuracy' => $riderLocation->accuracy,
                    'captured_at' => $riderLocation->captured_at,
                    // ⭐ Pre-computed age for consistent display (avoids client-side timezone issues)
                    'age' => \Carbon\Carbon::parse($riderLocation->captured_at)->diffForHumans(),
                ] : null,
                'office' => $distanceInfo && $distanceInfo['base_location'] ? [
                    'name' => $distanceInfo['base_location']->location_name ?? 'Office',
                    'latitude' => (float)$distanceInfo['base_location']->latitude,
                    'longitude' => (float)$distanceInfo['base_location']->longitude,
                    'distance_meters' => $distanceInfo['distance_meters'],
                    'distance_display' => $distanceInfo['distance_meters'] 
                        ? \App\Services\LocationService::formatDistance($distanceInfo['distance_meters'])
                        : null,
                ] : null,
                'route_lock' => $this->getRouteLockInfo($riderId),
                /**
                 * 🔧⭐ HIS WORKSHOP ERRAND, if he is on one (owner ask, 10-Sep-2026).
                 *
                 * This payload is what the store phone's PINNED-RIDER tab draws its header
                 * from, and the owner asked for the same "going to / at the workshop" line
                 * there as on the web card. Same `tripFor()` derivation, same sentence.
                 * ⚠ Null for everybody else, so the chip simply does not render.
                 */
                'workshop_trip' => (function () use ($riderId) {
                    try { return app(\App\Services\Riders\WorkshopVisitService::class)->tripFor($riderId); }
                    catch (\Throwable $e) { return null; }
                })(),
                /**
                 * 🔧📍 "ARE YOU AT THE WORKSHOP?" — present ONLY while the server is actually
                 *    asking (a free-text workshop with no pin, and he has stopped somewhere
                 *    unrecognised). See `arrivalPromptFor()`.
                 *
                 * ⚠⚠ THE SHEET LIVES AND DIES BY THIS FIELD. It is null the instant the
                 *    question stops applying — answered here or elsewhere, visit closed, a
                 *    manager stamped it, or the ask went stale — so the phone has no timer of
                 *    its own to get stuck on. That is the anti-bug design, not an accident.
                 */
                'arrival_prompt' => (function () use ($riderId) {
                    try { return app(\App\Services\Riders\WorkshopVisitService::class)->arrivalPromptFor($riderId); }
                    catch (\Throwable $e) { return null; }
                })(),
                // ⭐ "Left office without dispatching" flag (live; auto-clears).
                'left_without_dispatch' => $this->detectLeftWithoutDispatch([$riderId])[$riderId] ?? null,
                // ⭐ "Returning to office" ETA (single Google call, cached) once
                //    the rider has delivered the last order in their dispatch.
                'return_to_office' => $this->getReturnToOfficeInfo($riderId),
            ];
            
        } catch (\Exception $e) {
            \Log::error('Failed to get rider dashboard summary', [
                'rider_id' => $riderId,
                'error' => $e->getMessage()
            ]);
            return null;
        }
    }

    /**
     * Detect riders who have left the PRIMARY office without pressing Dispatch.
     *
     * A rider is flagged when ALL of these hold:
     *   - has >= 1 out_for_delivery order that is NOT dispatched (eta_calculated_at IS NULL)
     *   - their latest GPS heartbeat is fresh (<= 15 min old)
     *   - that GPS is > 300 m from the PRIMARY office (t_ops_company_locations.is_primary)
     *
     * It clears itself once they dispatch, return within 300 m, or have no
     * undispatched OFD orders left — nothing is persisted, so it never lingers.
     *
     * Uses the single primary office for ALL riders (per requirement), NOT the
     * per-rider assigned base. Batched (a handful of queries total) so it can
     * cover many riders cheaply.
     *
     * @param int[] $riderIds
     * @return array<int, array{flagged:bool,undispatched_count:int,distance_meters:?int,gps_fresh:bool,rider_name:?string}>
     */
    private function detectLeftWithoutDispatch(array $riderIds): array
    {
        $result = [];
        $riderIds = array_values(array_unique(array_filter(array_map('intval', $riderIds), fn($v) => $v > 0)));
        if (empty($riderIds)) {
            return $result;
        }

        // Primary office — single source of truth for all dispatch checks.
        $office = \DB::table('t_ops_company_locations')
            ->where('is_primary', 1)
            ->where('is_active', 1)
            ->select('latitude', 'longitude')
            ->first();
        if (!$office || !$office->latitude || !$office->longitude) {
            return $result; // Cannot assert "left office" without office coords.
        }
        $officeLat = (float) $office->latitude;
        $officeLng = (float) $office->longitude;
        $radiusMeters = 300;
        $freshCutoff = now()->subMinutes(15);

        // Undispatched OFD order counts per rider.
        $undispatched = \DB::table('t_crm_prod_order')
            ->whereIn('assigned_rider_user_id', $riderIds)
            ->where('order_status', 'out_for_delivery')
            ->whereNull('eta_calculated_at')
            ->select('assigned_rider_user_id as rider_id', \DB::raw('COUNT(*) as cnt'))
            ->groupBy('assigned_rider_user_id')
            ->pluck('cnt', 'rider_id')
            ->toArray();

        // Pending DISPATCHED OFD counts — a rider mid-delivery isn't "forgot".
        $pendingDispatched = \DB::table('t_crm_prod_order')
            ->whereIn('assigned_rider_user_id', $riderIds)
            ->where('order_status', 'out_for_delivery')
            ->whereNotNull('eta_calculated_at')
            ->select('assigned_rider_user_id as rider_id', \DB::raw('COUNT(*) as cnt'))
            ->groupBy('assigned_rider_user_id')
            ->pluck('cnt', 'rider_id')
            ->toArray();

        // Dispatched orders delivered TODAY, with the LATEST such delivery time per
        // rider. A rider who completed a wave and is away is "returning for next
        // dispatch" — UNLESS he already came back to the office (a GPS fix at the
        // office AFTER this last-delivery time) and left again without dispatching,
        // which is the "forgot the next wave" case handled below.
        $today = now()->format('Y-m-d');
        $deliveredDispatched = [];
        $lastDispatchedDeliveryAt = [];
        $ddRows = \DB::table('t_crm_prod_order as o')
            ->join('t_crm_order_status_history as osh', function ($j) use ($today) {
                $j->on('o.id', '=', 'osh.order_id')
                  ->where('osh.status_code', '=', 'delivered')
                  ->whereDate('osh.changed_at', $today);
            })
            ->whereIn('o.assigned_rider_user_id', $riderIds)
            ->whereNotNull('o.eta_calculated_at')
            ->select('o.assigned_rider_user_id as rider_id',
                \DB::raw('COUNT(DISTINCT o.id) as cnt'),
                \DB::raw('MAX(osh.changed_at) as last_delivery_at'))
            ->groupBy('o.assigned_rider_user_id')
            ->get();
        foreach ($ddRows as $r) {
            $deliveredDispatched[$r->rider_id] = (int) $r->cnt;
            $lastDispatchedDeliveryAt[$r->rider_id] = $r->last_delivery_at;
        }

        // Latest fresh GPS point per rider (desc order → first seen = latest).
        $latestByRider = [];
        $gpsPoints = \DB::table('t_ops_rider_location')
            ->whereIn('user_id', $riderIds)
            ->where('captured_at', '>=', $freshCutoff)
            ->orderBy('captured_at', 'desc')
            ->select('user_id', 'latitude', 'longitude')
            ->get();
        foreach ($gpsPoints as $pt) {
            if (!isset($latestByRider[$pt->user_id])) {
                $latestByRider[$pt->user_id] = $pt;
            }
        }

        // 🚚 Riders who have JUST COLLECTED OFF THE VAN. A handover scan makes
        // orders out_for_delivery with no ETA, away from the office — the exact
        // shape this detector flags — but pressing Dispatch is the very NEXT step
        // of the sanctioned van flow, not a forgotten one. Without this exclusion
        // a rider whose first job of the day is a van collection gets a permanent
        // `t_ops_dispatch_missed` row written against him for doing it right.
        // Same 45-minute window the dispatch-origin guard uses. Schema-guarded and
        // fail-safe: on any error the set is empty = today's behaviour exactly.
        $justCollected = [];
        try {
            if (\Schema::hasColumn('t_crm_prod_order', 'handover_at')) {
                $justCollected = array_flip(array_map('intval',
                    \DB::table('t_crm_prod_order')
                        ->whereIn('assigned_rider_user_id', $riderIds)
                        ->where('order_status', 'out_for_delivery')
                        ->whereNull('eta_calculated_at')
                        ->whereNotNull('handover_at')
                        ->where('handover_at', '>=', now()->subMinutes(45))
                        ->distinct()->pluck('assigned_rider_user_id')->all()
                ));
            }
        } catch (\Throwable $e) {
            $justCollected = [];
        }

        // 🧭 Sep-2026: the store cleared his times while he was OUT (mid re-plan).
        //    His orders are untimed because of the store, not because he forgot —
        //    never write a missed-dispatch row against him for it.
        $storeCleared = \App\Services\Riders\EtaPromiseService::storeClearedWhileAway($riderIds);
        // …but only while he has NOT been back to the office since that cancel. Once
        // he returns, a fresh departure with still-untimed orders is his own again.
        foreach ($storeCleared as $rid => $cancelAt) {
            if ($this->riderWasAtOfficeSince((int) $rid, $officeLat, $officeLng, $radiusMeters, (string) $cancelAt)) {
                unset($storeCleared[$rid]);
            }
        }

        // Names (only needed for flagged riders, but cheap to fetch all).
        $names = \DB::table('t_sys_user')
            ->whereIn('id', $riderIds)
            ->pluck('fullname', 'id')
            ->toArray();

        foreach ($riderIds as $rid) {
            $cnt = (int) ($undispatched[$rid] ?? 0);
            $entry = [
                'flagged' => false,
                'undispatched_count' => $cnt,
                'distance_meters' => null,
                'gps_fresh' => isset($latestByRider[$rid]),
                'rider_name' => $names[$rid] ?? null,
            ];
            // Only the pure "forgot to dispatch" case: has undispatched orders,
            // but has NOT dispatched anything yet today (no pending dispatched
            // OFD and none delivered from a dispatch). Riders who already
            // dispatched/delivered a wave and are away are "returning", handled
            // separately by the return-to-office logic.
            $hasPendingDispatched = (int) ($pendingDispatched[$rid] ?? 0) > 0;
            $hasDeliveredDispatched = (int) ($deliveredDispatched[$rid] ?? 0) > 0;
            // Never flag a rider MID-RUN (still carrying a dispatched wave) — he's
            // working, not "forgot". Requires undispatched OFD + fresh GPS.
            // A fresh van collection is not a forgotten dispatch — see above.
            if (isset($justCollected[$rid])) {
                $entry['van_handover_recent'] = true;
            }
            if (isset($storeCleared[$rid])) {
                $entry['store_cleared'] = true;
                /**
                 * C7 (Sep-29): he is still never blamed (no `flagged`, so no missed-dispatch
                 * row), but the STORE must still see that his orders are out untimed. The
                 * banner reads `store_cancelled`: "dispatch cancelled while he was out — not
                 * re-sent". Same live conditions as the warning: untimed orders, nothing
                 * dispatched pending, fresh GPS away from the office, not a van collection.
                 */
                if ($cnt > 0 && !$hasPendingDispatched && isset($latestByRider[$rid]) && !isset($justCollected[$rid])) {
                    $pt = $latestByRider[$rid];
                    $dist = $this->haversineDistance($officeLat, $officeLng, (float) $pt->latitude, (float) $pt->longitude);
                    if ($dist > $radiusMeters) {
                        $entry['store_cancelled'] = true;
                        $entry['distance_meters'] = (int) round($dist);
                    }
                }
            }
            if ($cnt > 0 && !$hasPendingDispatched && isset($latestByRider[$rid])
                && !isset($justCollected[$rid]) && !isset($storeCleared[$rid])) {
                $pt = $latestByRider[$rid];
                $dist = $this->haversineDistance($officeLat, $officeLng, (float) $pt->latitude, (float) $pt->longitude);
                $entry['distance_meters'] = (int) round($dist);
                if ($dist > $radiusMeters) {
                    if (!$hasDeliveredDispatched) {
                        // FIRST run — dispatched nothing yet today. Flag a genuine
                        // "left the office" transition: he must have been AT the
                        // office earlier today (someone who started from home is not
                        // "forgot").
                        $entry['was_at_office_today'] = $this->riderWasAtOfficeToday($rid, $officeLat, $officeLng, $radiusMeters);
                        if ($entry['was_at_office_today']) {
                            $entry['flagged'] = true;
                            $entry['context'] = 'first_run';
                        }
                    } else {
                        // Already completed a wave today. This is "forgot the NEXT
                        // wave" only if he RETURNED to the office after his last
                        // delivery and then left again (a fresh departure without
                        // dispatching). A rider still on his way back has NOT been to
                        // the office since his last delivery → that stays "returning".
                        $since = $lastDispatchedDeliveryAt[$rid] ?? null;
                        if ($since && $this->riderWasAtOfficeSince((int) $rid, $officeLat, $officeLng, $radiusMeters, (string) $since)) {
                            $entry['flagged'] = true;
                            $entry['context'] = 'returned_then_left';
                        }
                    }
                }
            }
            $result[$rid] = $entry;

            // Persist the departure the first time it is seen (no cron — logged by
            // whichever surface runs the detector). Idempotent + fail-safe.
            if (!empty($entry['flagged'])) {
                $this->logMissedDispatch((int) $rid, $entry);
            }
        }

        return $result;
    }

    /**
     * Did the rider have a GPS fix AT the primary office earlier today?
     *
     * Used to assert a genuine "left the office" transition for the
     * left-without-dispatch warning — a rider who started the day away from
     * the office (e.g. from home) should NOT be flagged just for being away.
     * Uses a square bounding box (slightly larger than the circle) so the
     * check is a single cheap indexed existence query, no haversine in SQL.
     */
    private function riderWasAtOfficeToday(int $riderId, float $officeLat, float $officeLng, int $radiusMeters = 300): bool
    {
        $latDelta = $radiusMeters / 111320.0;
        $lngDelta = $radiusMeters / (111320.0 * max(0.1, cos(deg2rad($officeLat))));
        return \DB::table('t_ops_rider_location')
            ->where('user_id', $riderId)
            ->whereDate('captured_at', now()->format('Y-m-d'))
            ->whereBetween('latitude', [$officeLat - $latDelta, $officeLat + $latDelta])
            ->whereBetween('longitude', [$officeLng - $lngDelta, $officeLng + $lngDelta])
            ->exists();
    }

    /**
     * Was the rider AT the office at any point strictly AFTER $since?
     *
     * Distinguishes "genuinely still returning" (no office fix since his last
     * delivery) from "returned to the office and then left again without
     * dispatching the next wave" (an office fix exists after the last delivery).
     * Same cheap square-bounding-box existence check as riderWasAtOfficeToday.
     */
    private function riderWasAtOfficeSince(int $riderId, float $officeLat, float $officeLng, int $radiusMeters, string $since): bool
    {
        $latDelta = $radiusMeters / 111320.0;
        $lngDelta = $radiusMeters / (111320.0 * max(0.1, cos(deg2rad($officeLat))));
        return \DB::table('t_ops_rider_location')
            ->where('user_id', $riderId)
            ->where('captured_at', '>', $since)
            ->whereBetween('latitude', [$officeLat - $latDelta, $officeLat + $latDelta])
            ->whereBetween('longitude', [$officeLng - $lngDelta, $officeLng + $lngDelta])
            ->exists();
    }

    /**
     * Estimate WHEN the rider actually left the office today: the first GPS fix
     * that is OUTSIDE the office radius, captured after his last fix AT the office.
     * Computed from the persisted GPS trail, so it is accurate even if the alert is
     * only DETECTED (and logged) a little later. Best-effort → null if unknown.
     */
    private function estimateOfficeDepartureAt(int $riderId): ?string
    {
        try {
            $office = $this->getPrimaryOfficeCoords();
            if (!$office) {
                return null;
            }
            $officeLat = (float) $office['lat'];
            $officeLng = (float) $office['lng'];
            $radiusMeters = 300;
            $latDelta = $radiusMeters / 111320.0;
            $lngDelta = $radiusMeters / (111320.0 * max(0.1, cos(deg2rad($officeLat))));
            $today = now()->format('Y-m-d');

            $lastOfficeAt = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->whereDate('captured_at', $today)
                ->whereBetween('latitude', [$officeLat - $latDelta, $officeLat + $latDelta])
                ->whereBetween('longitude', [$officeLng - $lngDelta, $officeLng + $lngDelta])
                ->max('captured_at');
            if (!$lastOfficeAt) {
                return null;
            }

            $firstAwayAt = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->where('captured_at', '>', $lastOfficeAt)
                ->where(function ($q) use ($officeLat, $officeLng, $latDelta, $lngDelta) {
                    $q->whereNotBetween('latitude', [$officeLat - $latDelta, $officeLat + $latDelta])
                      ->orWhereNotBetween('longitude', [$officeLng - $lngDelta, $officeLng + $lngDelta]);
                })
                ->min('captured_at');

            return $firstAwayAt ?: $lastOfficeAt;
        } catch (\Throwable $e) {
            return null;
        }
    }

    /**
     * Persist a "left without dispatch" departure the FIRST time it is detected
     * (issues report source). No cron: called by whichever surface runs
     * detectLeftWithoutDispatch(). Idempotent (one row per rider/day via the unique
     * key) and fail-safe: if the table is absent or anything errors, detection is
     * never affected. Resolution ("who dispatched, when") is NOT stored here — it is
     * derivable from the orders' eta_calculated_by / eta_calculated_at.
     */
    private function logMissedDispatch(int $riderId, array $entry): void
    {
        try {
            if (!\Schema::hasTable('t_ops_dispatch_missed')) {
                return;
            }
            $today = now()->format('Y-m-d');
            $exists = \DB::table('t_ops_dispatch_missed')
                ->where('rider_id', $riderId)
                ->where('issue_date', $today)
                ->exists();
            if ($exists) {
                return;
            }

            $orderIds = \DB::table('t_crm_prod_order')
                ->where('assigned_rider_user_id', $riderId)
                ->where('order_status', 'out_for_delivery')
                ->whereNull('eta_calculated_at')
                ->pluck('id')
                ->all();

            \DB::table('t_ops_dispatch_missed')->insertOrIgnore([
                'rider_id'               => $riderId,
                'issue_date'             => $today,
                'left_at'                => $this->estimateOfficeDepartureAt($riderId),
                'detected_at'            => now(),
                'undispatched_count'     => (int) ($entry['undispatched_count'] ?? count($orderIds)),
                'undispatched_order_ids' => json_encode(array_values($orderIds)),
                'distance_meters'        => $entry['distance_meters'] ?? null,
                'context'                => $entry['context'] ?? null,
                'created_at'             => now(),
            ]);
        } catch (\Throwable $e) {
            // Never let logging break the live detector.
            try {
                \Log::warning('logMissedDispatch failed (non-fatal)', ['rider_id' => $riderId, 'error' => $e->getMessage()]);
            } catch (\Throwable $ignored) {
            }
        }
    }

    /**
     * Primary office coordinates (single source for all dispatch checks).
     * Cached for the lifetime of the request to avoid repeat lookups.
     */
    private function getPrimaryOfficeCoords(): ?array
    {
        static $cached = null; // null = not loaded, false = none, array = coords
        if ($cached !== null) {
            return $cached ?: null;
        }
        $o = \DB::table('t_ops_company_locations')
            ->where('is_primary', 1)
            ->where('is_active', 1)
            ->select('latitude', 'longitude')
            ->first();
        if ($o && $o->latitude && $o->longitude) {
            return $cached = ['lat' => (float) $o->latitude, 'lng' => (float) $o->longitude];
        }
        $cached = false;
        return null;
    }

    /**
     * Compute a rider's "return to office" ETA with a SINGLE Google call.
     *
     * Only returns a value when the rider has FINISHED the orders in their
     * dispatch — i.e. the last order in the dispatch has been delivered:
     *   - no pending dispatched OFD orders still out, AND
     *   - >= 1 dispatched order was delivered today, AND
     *   - GPS is fresh (<= 15 min), AND
     *   - they are away from the primary office (> radius).
     * Otherwise null (still delivering / already at office / no GPS).
     *
     * The Google Directions result is cached per rider for 3 minutes, so
     * repeated store/tracker polls never trigger more than ~1 call per rider
     * per window. Falls back to a distance/speed approximation if Google is
     * unavailable. Reuses getMultiStopEtaFromGoogle (monthly cap + usage
     * counter handled there).
     *
     * @return array{minutes:int,arrival_at:string,arrival_display:string,distance_meters:int,distance_display:string,source:string}|null
     */
    /**
     * ⭐ PUBLIC so the VAN BOARD can ask the same question (Aug-2026) — it is the
     *    one place that already knows a van driver is NOT "returning" while he is
     *    heading to a rendezvous or still carrying somebody's boxes. The van panel
     *    reuses it rather than computing a second, van-blind arrival time.
     *
     * ⚠ POLLING CALLERS MUST PASS `$useGoogleEta = false` — see the cache note
     *   below. The van board polls every 30s exactly like the live rider board.
     */
    public function getReturnToOfficeInfo(int $riderId, ?float $officeLat = null, ?float $officeLng = null, int $radiusMeters = 300, bool $useGoogleEta = true): ?array
    {
        if ($officeLat === null || $officeLng === null) {
            $office = $this->getPrimaryOfficeCoords();
            if (!$office) {
                return null;
            }
            $officeLat = $office['lat'];
            $officeLng = $office['lng'];
        }

        // Latest fresh GPS point.
        $loc = \DB::table('t_ops_rider_location')
            ->where('user_id', $riderId)
            ->where('captured_at', '>=', now()->subMinutes(15))
            ->orderBy('captured_at', 'desc')
            ->select('latitude', 'longitude')
            ->first();
        if (!$loc || !$loc->latitude || !$loc->longitude) {
            return null;
        }

        $distance = $this->haversineDistance($officeLat, $officeLng, (float) $loc->latitude, (float) $loc->longitude);
        if ($distance <= $radiusMeters) {
            return null; // Already at / near office — nothing to estimate.
        }
        // Sanity guard: a fix more than 60 km from the office is almost
        // certainly a stale/cross-city GPS glitch (common in dev), not a real
        // "coming back soon" — skip it so we never show absurd ETAs.
        if ($distance > 60000) {
            return null;
        }

        // Must have NO pending dispatched OFD orders (the dispatch is done).
        $pendingDispatched = \DB::table('t_crm_prod_order')
            ->where('assigned_rider_user_id', $riderId)
            ->where('order_status', 'out_for_delivery')
            ->whereNotNull('eta_calculated_at')
            ->count();
        if ($pendingDispatched > 0) {
            return null; // Still delivering the current dispatch.
        }

        // 🚚 HE IS NOT GOING TO THE OFFICE — HE IS GOING TO MEET THE VAN.
        // This check knows nothing about van cargo, so it used to announce
        // "returning · back at 3:40" about two people whose destination was the
        // meet-up point: the rider whose NEXT batch is still on the van (he has
        // finished this wave, so every gate above passes), and the VAN DRIVER on
        // his way to the rendezvous with a second wave still aboard. A confident
        // wrong arrival time is worse than none. Schema-guarded and fail-open:
        // any error leaves the pre-van behaviour untouched.
        try {
            if (\Schema::hasColumn('t_crm_prod_order', 'van_loaded_at')) {
                // His own next batch is sitting on somebody's van.
                //
                // ⚠ TIME-BOUNDED (the review's rule: anything keyed on a live van
                //   pointer carries a bound). `unload` still has no button, so
                //   stranded on_van boxes are real — three sat on Mashood's van
                //   for DAYS. Unbounded, one stale box would hide this rider's
                //   "back at office" time indefinitely. 20h = the store panel's
                //   own freshness window for the same column.
                $awaitingVan = \DB::table('t_crm_prod_order')
                    ->where('assigned_rider_user_id', $riderId)
                    ->where('order_status', 'on_van')
                    ->whereNotNull('van_loaded_at')
                    ->where('van_loaded_at', '>=', now()->subHours(20))
                    ->exists();
                if ($awaitingVan) return null;

                // The driver: heading to the stop, or still carrying for others.
                // Deliberately NOT "has an open trip" — once the van is empty and
                // his deliveries are done, the drive home IS a genuine return and
                // the store should see when he lands.
                if (\Schema::hasTable('t_ops_van_trip')) {
                    $trip = \DB::table('t_ops_van_trip')
                        ->where('van_user_id', $riderId)
                        ->whereNull('ended_at')->whereNotNull('departed_at')
                        ->where('departed_at', '>=', now()->subHours(14))
                        ->orderByDesc('id')->first();
                    if ($trip) {
                        if ((string) $trip->current_leg === 'to_stop') return null;
                        $stillCarrying = \DB::table('t_crm_prod_order')
                            ->where('van_user_id', $riderId)
                            ->where('order_status', 'on_van')
                            ->whereNotNull('van_loaded_at')
                            // Same stranded-box bound as above.
                            ->where('van_loaded_at', '>=', now()->subHours(20))
                            ->exists();
                        if ($stillCarrying) return null;
                    }
                }
            }
        } catch (\Throwable $e) {
            // Fall through — a van lookup must never cost the live board its ETA.
        }

        // Must have delivered at least one DISPATCHED order today (i.e. there
        // genuinely was a dispatch that has now been completed).
        $today = now()->format('Y-m-d');
        $dd = \DB::table('t_crm_prod_order as o')
            ->join('t_crm_order_status_history as osh', function ($j) use ($today) {
                $j->on('o.id', '=', 'osh.order_id')
                  ->where('osh.status_code', '=', 'delivered')
                  ->whereDate('osh.changed_at', $today);
            })
            ->where('o.assigned_rider_user_id', $riderId)
            ->whereNotNull('o.eta_calculated_at')
            ->selectRaw('COUNT(*) as cnt, MAX(osh.changed_at) as last_delivery_at')
            ->first();
        if (!$dd || (int) $dd->cnt < 1) {
            return null; // No completed dispatch today.
        }

        // Mutual exclusion with "left without dispatch": if he has ALREADY returned
        // to the office since that last delivery and is out again, he is NOT
        // returning — he left again (that surfaces as left_without_dispatch). Keep
        // them exclusive so every consumer agrees, incl. the mobile banner which
        // suppresses the alert whenever a return_to_office ETA is present.
        if (!empty($dd->last_delivery_at)
            && $this->riderWasAtOfficeSince($riderId, $officeLat, $officeLng, $radiusMeters, (string) $dd->last_delivery_at)) {
            return null;
        }

        // Precise ETA needs one (cached) Google Directions call. The live board
        // polls every 30s and must NEVER block on an external call — Google can
        // take up to 15s per rider on a cold cache (or stall entirely if the
        // production server has no/limited outbound), which is exactly what made
        // the board fail to load intermittently. Callers that only need a glance
        // pass $useGoogleEta=false: we reuse a warm cached value if present,
        // otherwise fall back to a distance-based approximation — without ever
        // firing a fresh Google request on the board's hot path.
        $lat = (float) $loc->latitude;
        $lng = (float) $loc->longitude;
        if ($useGoogleEta) {
            $cached = \Cache::remember("return_office_eta:{$riderId}", 180, function () use ($lat, $lng, $officeLat, $officeLng) {
                $eta = $this->getMultiStopEtaFromGoogle([
                    ['lat' => $lat, 'lng' => $lng],
                    ['lat' => $officeLat, 'lng' => $officeLng],
                ]);
                return $eta['legs'][0] ?? -1;
            });
        } else {
            // Board path: only use an already-warm cached value; no API call.
            $cached = \Cache::get("return_office_eta:{$riderId}");
        }

        $source = 'google_maps';
        $minutes = (is_numeric($cached) && $cached >= 0) ? (int) round($cached) : null;
        if ($minutes === null) {
            // Fallback approximation (~22 km/h average city speed).
            $minutes = max(1, (int) round(($distance / 1000) / 22 * 60));
            $source = 'approx';
        }

        $arrival = now()->addMinutes($minutes);
        return [
            'minutes' => $minutes,
            'arrival_at' => $arrival->toIso8601String(),
            'arrival_display' => $arrival->format('h:i A'),
            'distance_meters' => (int) round($distance),
            'distance_display' => $distance < 1000 ? ((int) round($distance)) . ' m' : round($distance / 1000, 1) . ' km',
            'source' => $source,
        ];
    }

    private function getRouteLockInfo($riderId)
    {
        $lock = \DB::table('t_crm_route_lock as rl')
            ->leftJoin('t_sys_user as u', 'u.id', '=', 'rl.locked_by')
            ->where('rl.rider_id', $riderId)
            ->select('rl.locked_by', 'u.fullname as locked_by_name', 'rl.locked_at')
            ->first();

        if (!$lock) return null;

        return [
            'locked_by' => $lock->locked_by,
            'locked_by_name' => $lock->locked_by_name,
            'locked_at' => $lock->locked_at,
        ];
    }

    /**
     * STORE MODE: Get full order details (for expanded view)
     */
    public function getStoreOpenOrderDetails($orderId)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_open_orders')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view open orders'
                ], 403);
            }
            
            // Get full order with all relationships (lineItems.product for category grouping)
            $order = OrderModel::with(['customer', 'lineItems', 'lineItems.product:id,attribute_1', 'lineItems.qtyUpdater:id,fullname', 'assignedRider', 'discounts'])
                ->findOrFail($orderId);
            
            // Build customer name
            $customerName = $order->name ?? 'N/A';
            if (!$order->name && ($order->address_first_name || $order->address_last_name)) {
                $customerName = trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? ''));
            }
            if ($customerName === 'N/A' && $order->customer) {
                $customerName = $order->customer->name ?? 'Unknown';
            }
            
            // Check verified location and build verified_location object
            $hasVerifiedLocation = false;
            $verifiedLocation = null;
            if ($order->customer) {
                $hasCoords = !empty($order->customer->latitude) && !empty($order->customer->longitude);
                $hasUrl = !empty($order->customer->verified_location_url);
                $hasVerifiedLocation = $hasCoords || $hasUrl;
                
                if ($hasVerifiedLocation) {
                    // Get coordinates: prioritize stored coords, else parse from URL
                    $lat = $order->customer->latitude ? (float)$order->customer->latitude : null;
                    $lng = $order->customer->longitude ? (float)$order->customer->longitude : null;
                    
                    // If no stored coords but URL exists, try to parse coords from URL
                    if ((!$lat || !$lng) && $hasUrl) {
                        $parsedCoords = $this->parseCoordinatesFromGoogleMapsUrl($order->customer->verified_location_url);
                        if ($parsedCoords) {
                            $lat = $parsedCoords['latitude'];
                            $lng = $parsedCoords['longitude'];
                        }
                    }
                    
                    // Build google_maps_url: prioritize stored URL, else construct from coordinates
                    $googleMapsUrl = $order->customer->verified_location_url;
                    if (!$googleMapsUrl && $lat && $lng) {
                        $googleMapsUrl = "https://www.google.com/maps?q={$lat},{$lng}";
                    }
                    
                    $verifiedLocation = [
                        'latitude' => $lat,
                        'longitude' => $lng,
                        'url' => $order->customer->verified_location_url ?? null,
                        'google_maps_url' => $googleMapsUrl,
                    ];
                }
            }
            
            // Generate invoice URLs
            $invoiceImageUrl = route('orders.invoice.pdf', ['id' => $order->id, 'download_image' => 1]);
            $invoicePdfUrl = route('orders.invoice.pdf', ['id' => $order->id, 'force_pdf' => 1]);

            // ⭐ Barcode-qty: resolve each line item's Czerlop product id by SKU
            // (sku -> variant -> product). SKU is the reliable key — the line item's
            // own product_id is an EXTERNAL id and does not map to t_crm_prod_product.
            // variant_id is a secondary fallback for the rare empty-sku line.
            $liSkus = $order->lineItems->pluck('sku')->filter()->unique()->values()->all();
            $liVariantIds = $order->lineItems->pluck('variant_id')->filter()->unique()->values()->all();
            $skuCzerlop = [];
            $variantCzerlop = [];
            $skuWeightFactor = [];     // sku -> weight_factor (default 1)
            $variantWeightFactor = []; // variant_id -> weight_factor (fallback, default 1)
            // 📦 'kg' | 'pcs' — resolved with the SAME sku-first / variant-fallback
            //    priority as the PLU, so a line can never be matched by one map and
            //    read by the other. Column absent => everything is 'kg' (today).
            $skuSellUnit = [];
            $variantSellUnit = [];
            $hasSellUnit = \App\Models\CRM\ProductModel::supportsSellUnit();
            $kgUnit = \App\Models\CRM\ProductModel::SELL_UNIT_KG;
            if (!empty($liSkus)) {
                $cols = ['v.sku', 'p.czerlop_product_id', 'p.weight_factor'];
                if ($hasSellUnit) { $cols[] = 'p.sell_unit'; }
                foreach (\DB::table('t_crm_prod_product_variant as v')
                    ->join('t_crm_prod_product as p', 'p.id', '=', 'v.product_id')
                    ->whereIn('v.sku', $liSkus)
                    ->select($cols)->get() as $row) {
                    if ($row->czerlop_product_id !== null) {
                        $skuCzerlop[$row->sku] = (int) $row->czerlop_product_id;
                    }
                    $skuWeightFactor[$row->sku] = (float) ($row->weight_factor ?? 1.0);
                    $skuSellUnit[$row->sku] = $hasSellUnit
                        ? \App\Models\CRM\ProductModel::normaliseSellUnit($row->sell_unit ?? null)
                        : $kgUnit;
                }
            }
            if (!empty($liVariantIds)) {
                $vcols = ['v.id', 'p.czerlop_product_id', 'p.weight_factor'];
                if ($hasSellUnit) { $vcols[] = 'p.sell_unit'; }
                foreach (\DB::table('t_crm_prod_product_variant as v')
                    ->join('t_crm_prod_product as p', 'p.id', '=', 'v.product_id')
                    ->whereIn('v.id', $liVariantIds)
                    ->select($vcols)->get() as $row) {
                    if ($row->czerlop_product_id !== null) {
                        $variantCzerlop[(int) $row->id] = (int) $row->czerlop_product_id;
                    }
                    $variantWeightFactor[(int) $row->id] = (float) ($row->weight_factor ?? 1.0);
                    $variantSellUnit[(int) $row->id] = $hasSellUnit
                        ? \App\Models\CRM\ProductModel::normaliseSellUnit($row->sell_unit ?? null)
                        : $kgUnit;
                }
            }

            return response()->json([
                'success' => true,
                'order' => [
                    'id' => $order->id,
                    'order_number' => $order->order_number ?? 'NF-' . str_pad($order->id, 4, '0', STR_PAD_LEFT),
                    'order_date' => $order->order_date,
                    'order_status' => $order->order_status,
                    'total_price' => $order->total_price,
                    'payment_method' => $order->payment_method,
                    'expected_packets' => $order->expected_packets,
                    'customer_name' => $customerName,
                    'customer_phone' => $order->customer->phone_original ?? $order->customer->phone ?? $order->address_phone ?? '',
                    'customer_address' => $order->customer->address1 ?? $order->address_address ?? '',
                    'customer_address1' => $order->customer->address1 ?? '',
                    'customer_address2' => $order->customer->address2 ?? '',
                    'customer_city' => $order->customer->city ?? '',
                    'customer_province' => $order->customer->province ?? '',
                    'customer_postal_code' => $order->customer->postal_code ?? '',
                    'customer_id' => $order->customer_id,
                    // ⭐ Customer Notes - use primary customer notes if order linked to merged duplicate
                    'customer_notes' => $order->customer ? (
                        $order->customer->merged_into_customer_id
                            ? (\App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id)?->notes ?? null)
                            : ($order->customer->notes ?? null)
                    ) : null,
                    'has_customer_notes' => $order->customer && !empty(
                        $order->customer->merged_into_customer_id
                            ? (\App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id)?->notes ?? null)
                            : ($order->customer->notes ?? null)
                    ),
                    // ⭐ Order Notes - order-specific notes
                    'order_note' => $order->note ?? null,
                    'has_order_note' => !empty($order->note),
                    'has_verified_location' => $hasVerifiedLocation,
                    'verified_location' => $verifiedLocation,
                    'has_khaas_item' => (function() use ($order) { // ❄️ Khaas product indicator
                        $productIds = $order->lineItems->pluck('product_id')->filter()->unique()->values();
                        if ($productIds->isEmpty()) return false;
                        return \DB::table('t_crm_prod_product')
                            ->whereIn('id', $productIds)
                            ->where('business_unit_id', '!=', 1)
                            ->exists();
                    })(),
                    'items_count' => $order->lineItems->count(),
                    'items_summary' => $order->lineItems->map(function($item) {
                        return $item->name . ' (x' . $item->quantity . ')';
                    })->join(', '),
                    'line_items' => $order->lineItems->map(function($item) use ($skuCzerlop, $variantCzerlop, $skuWeightFactor, $variantWeightFactor, $skuSellUnit, $variantSellUnit) {
                        // Resolve Czerlop id: SKU first (reliable), variant_id as fallback.
                        $czerlop = null;
                        $liSku = trim((string) ($item->sku ?? ''));
                        if ($liSku !== '' && isset($skuCzerlop[$liSku])) {
                            $czerlop = $skuCzerlop[$liSku];
                        } elseif ($item->variant_id && isset($variantCzerlop[(int) $item->variant_id])) {
                            $czerlop = $variantCzerlop[(int) $item->variant_id];
                        }
                        // Resolve weight factor with the same priority (SKU first, variant fallback).
                        $wf = 1.0;
                        if ($liSku !== '' && isset($skuWeightFactor[$liSku])) {
                            $wf = $skuWeightFactor[$liSku];
                        } elseif ($item->variant_id && isset($variantWeightFactor[(int) $item->variant_id])) {
                            $wf = $variantWeightFactor[(int) $item->variant_id];
                        }
                        // 📦 Sold by weight or by the box? Same priority again.
                        $sellUnit = 'kg';
                        if ($liSku !== '' && isset($skuSellUnit[$liSku])) {
                            $sellUnit = $skuSellUnit[$liSku];
                        } elseif ($item->variant_id && isset($variantSellUnit[(int) $item->variant_id])) {
                            $sellUnit = $variantSellUnit[(int) $item->variant_id];
                        }
                        return [
                            'id' => $item->id,
                            'product_name' => $item->name ?? 'N/A',
                            'variant_name' => $item->sku ?? '',
                            'sku' => $item->sku ?? '',                       // explicit SKU (barcode match key)
                            'czerlop_product_id' => $czerlop,               // for matching a scanned PLU
                            'weight_factor' => $wf,                          // qty divisor for scan/manual (default 1)
                            'sell_unit' => $sellUnit,                        // 📦 'kg' weighed | 'pcs' counted boxes
                            'quantity' => $item->quantity,
                            'quantity_source' => $item->quantity_source ?? null, // 'barcode' | 'box_scan' | 'manual' | null
                            'quantity_updated_at' => $item->quantity_updated_at ? $item->quantity_updated_at->toIso8601String() : null,
                            'quantity_updated_by_name' => optional($item->qtyUpdater)->fullname,
                            'unit_price' => $item->unit_price,
                            'unit_price_formatted' => 'Rs. ' . number_format($item->unit_price, 0),
                            'line_total' => $item->line_total,
                            'total' => $item->line_total,
                            'total_formatted' => $item->is_free ? 'FREE' : 'Rs. ' . number_format($item->line_total, 0),
                            'preparation_status' => $item->preparation_status,
                            'is_free' => (bool) $item->is_free,
                            'instructions' => $item->instructions,
                            'category' => optional($item->product)->attribute_1 ?: null, // product category for grouping
                        ];
                    }),
                    'shipping_total' => $order->shipping_total ?? 0,
                    'tip_amount' => $order->tip_amount ?? 0,
                    'discounts' => $order->discounts ? $order->discounts->map(function($discount) {
                        return [
                            'discount_amount' => $discount->discount_amount,
                            'discount_type' => $discount->discount_type,
                            // ⭐ The mobile receipt/invoice needs these to tell the
                            // customer's own ACCOUNT_BALANCE line apart from a real
                            // discount — without them it printed their money as a
                            // "Discount". Additive: older APKs ignore extra keys.
                            'coupon_code' => $discount->coupon_code,
                            'discount_title' => $discount->discount_title,
                        ];
                    })->toArray() : [],
                    'invoice' => [
                        'image_url' => $invoiceImageUrl,
                        'pdf_url' => $invoicePdfUrl,
                    ],
                ]
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to fetch order details', [
                'user_id' => Auth::id(),
                'order_id' => $orderId,
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch order details: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Get active riders for assignment
     * Reuses webapp logic from RiderController::active
     */
    public function getActiveRiders(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('assign_riders')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to assign riders'
                ], 403);
            }
            
            // Delivery riders = users with an ACTIVE rider profile (rider_profile.active=1).
            // This is the single "who can be assigned deliveries" list, curated in the
            // People list; managers/office (no profile) and stood-down riders are excluded.
            $riders = DB::table('t_sys_user as u')
                ->join('t_ops_rider_profile as p', 'p.user_id', '=', 'u.id')
                ->where('p.active', 1)
                ->where('u.is_active', 1)
                ->orderBy('u.fullname')
                ->get([
                    'u.id',
                    'u.fullname',
                ]);

            // May-2026 — `mode=qurbani` opts into the Qurbani-rider
            // whitelist configured in Qurbani Settings. When the
            // config is empty we fall through to the default
            // "all active riders" list so existing installs don't
            // break. Both the individual order detail picker and the
            // bulk-rider modal in QurbaniOpenOrdersScreen request
            // this filtered list so the same names show up in both.
            if ($request->input('mode') === 'qurbani') {
                $raw = (string) \App\Models\FIN\ConfigModel::get('qurbani_rider_ids', '[]');
                $ids = json_decode($raw, true);
                $whitelistApplied = false;
                if (is_array($ids)) {
                    $ids = array_values(array_filter(array_map('intval', $ids), fn($v) => $v > 0));
                    if (!empty($ids)) {
                        $filtered = $riders->filter(fn($r) => in_array((int) $r->id, $ids, true))->values();
                        // Defensive — if every whitelisted user has since
                        // been deactivated we'd otherwise hand back an
                        // empty list, which would silently hide riders
                        // from the mobile picker. Fall back to "all
                        // active" with a hint flag instead.
                        if ($filtered->count() > 0) {
                            $riders = $filtered;
                            $whitelistApplied = true;
                        }
                    }
                }

                // May-2026 — Enrich each rider row with `qurbani_region`
                // and `qurbani_contact` from the new per-rider meta
                // config (qurbani_rider_meta). Empty strings when no
                // meta is configured for that rider so the mobile
                // picker can render unconditionally (it already
                // tolerates falsy values). Kept additive — every
                // existing field stays in place so consumers that
                // only read id/fullname continue to work unchanged.
                $metaRaw = (string) \App\Models\FIN\ConfigModel::get('qurbani_rider_meta', '{}');
                $metaMap = json_decode($metaRaw, true);
                if (!is_array($metaMap)) { $metaMap = []; }
                $riders = $riders->map(function ($r) use ($metaMap) {
                    $key = (string) $r->id;
                    $m = isset($metaMap[$key]) && is_array($metaMap[$key]) ? $metaMap[$key] : null;
                    $r->qurbani_region  = $m ? (string) ($m['region']  ?? '') : '';
                    $r->qurbani_contact = $m ? (string) ($m['contact'] ?? '') : '';
                    return $r;
                })->values();

                return response()->json([
                    'success'   => true,
                    'riders'    => $riders,
                    'mode'      => 'qurbani',
                    'whitelist' => $whitelistApplied,
                ]);
            }

            /**
             * 🔧⭐ THE PICKER SAYS WHOSE MACHINE IS IN (promised 10-Sep, built 11-Sep).
             *
             * ⭐ NOT a filter and NOT a grey-out — the owner's rule is that he stays fully
             *   pickable. This is a TAG, so the dispatcher chooses him knowing, instead of
             *   finding out from a warning after the fact.
             * ⚠ ONE query for the whole list (`tripsFor`, no ETA), never per row: this list
             *   is drawn on every open of the assign sheet.
             */
            try {
                $trips = app(\App\Services\Riders\WorkshopVisitService::class)
                    ->tripsFor($riders->pluck('id')->all(), null, false);
                $riders = $riders->map(function ($r) use ($trips) {
                    $t = $trips[(int) $r->id] ?? null;
                    $r->workshop_trip = ($t && !empty($t['is_active'])) ? [
                        'state'        => $t['state']        ?? null,
                        'label'        => $t['label']        ?? null,
                        'label_ur'     => $t['label_ur']     ?? null,
                        'vehicle_name' => $t['vehicle_name'] ?? null,
                    ] : null;
                    return $r;
                })->values();
            } catch (\Throwable $e) {
                // ⚠ A tag must never cost the picker its list.
                \Log::warning('rider picker workshop tag skipped', ['error' => $e->getMessage()]);
            }

            return response()->json([
                'success' => true,
                'riders' => $riders
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to fetch active riders', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch riders: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * 🔧 One line, so every order-side door in this controller reports the workshop the
     *    same way. The engine is `WorkshopVisitService::warningFor()` — see the ⚠⚠ there
     *    for why this is a WARNING and not the refusal it used to be.
     */
    private function workshopWarningFor(int $riderId, string $context, array $meta = []): ?array
    {
        return app(\App\Services\Riders\WorkshopVisitService::class)
            ->warningFor($riderId, $context, $meta);
    }

    /**
     * STORE MODE: Assign rider to order
     * Uses the model's assignRider() method to properly create history records
     */
    public function assignRiderToOrder(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('assign_riders')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to assign riders'
                ], 403);
            }
            
            $validated = $request->validate([
                'order_id' => 'required|exists:t_crm_prod_order,id',
                'rider_id' => 'required|integer|min:0'
            ]);
            
            $order = OrderModel::findOrFail($validated['order_id']);
            
            // ⚠️ SAFETY CHECK: Don't allow rider change for delivered/completed orders
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cannot change rider for delivered or completed orders'
                ], 422);
            }
            
            // Unassign rider when rider_id is 0
            if ((int)$validated['rider_id'] === 0) {
                DB::table('t_ops_order_rider_history')
                    ->where('order_id', $order->id)
                    ->where('is_current', 1)
                    ->update(['is_current' => 0, 'unassigned_at' => now()]);
                $order->assigned_rider_user_id = null;
                $order->save();
                return response()->json([
                    'success' => true,
                    'message' => 'Rider unassigned successfully',
                ]);
            }

            /**
             * 🔧⭐⭐ IS HE AT THE WORKSHOP? (owner ruling REVISED, 11-Sep-2026 — TELL, don't ask.)
             *
             * ⚠⚠ THIS USED TO REFUSE, AND ON 11-Sep IT COST A REAL ASSIGNMENT. It returned 409
             *    `needs_confirmation` expecting a client to re-send `confirm` — but neither client
             *    was ever taught to, so the store tablet showed "Partial Update — Failed to assign
             *    rider" and the order could not be given to him at all. A server-side QUESTION is
             *    not a feature until a client can ANSWER it; until then it is only a wall.
             *
             * ⭐ The owner's rule: **out for delivery is not on the road.** Nothing leaves until
             *   Dispatch is pressed, so assigning to a man at the workshop is a perfectly ordinary
             *   thing to do — he takes them when he is back. The one place the fleet must actually
             *   stop is DISPATCH (see `calculateDeliveryEtas`), and even that is overridable.
             *
             * So this now ASSIGNS and reports a WARNING alongside the success. A client that does
             * not understand `warning` simply assigns, which is the correct outcome anyway.
             */
            $wsWarning = $this->workshopWarningFor((int) $validated['rider_id'], 'assign', [
                'order_id' => (int) $order->id,
                'by'       => $user->id ?? null,
            ]);

            // Get rider name for response
            $rider = DB::table('t_sys_user')->where('id', $validated['rider_id'])->first();
            
            if (!$rider) {
                return response()->json([
                    'success' => false,
                    'message' => 'Rider not found'
                ], 404);
            }
            
            $success = $order->assignRider(
                $validated['rider_id'],
                'Assigned via Store Mode',
                $user->id
            );
            
            if (!$success) {
                throw new \Exception('Failed to assign rider - model method returned false');
            }
            
            \Log::info('Rider assigned to order (Store Mode) - with history', [
                'order_id' => $order->id,
                'rider_id' => $validated['rider_id'],
                'rider_name' => $rider->fullname,
                'assigned_by' => $user->id,
                'assigned_by_name' => $user->fullname
            ]);
            
            // 🚚 STRANDED-ON-THE-VAN HINT (Aug-2026, from prod).
            //
            //    Reassigning an order that is still ON the van is fine and needs
            //    no help — the manifest regroups it and the new rider's meet-card
            //    picks it up within a poll (proven on 21 Aug).
            //
            //    The gap is the order the DRIVER already dispatched as his own
            //    before the manager handed it to somebody else. It is out for
            //    delivery, still stamped with the van, and never collected — so
            //    the new rider gets no card and no scan, and the board keeps
            //    counting it as aboard. The store fixed this by hand that night
            //    (put it back to On Van, which is exactly right); this just says
            //    so instead of leaving them to work it out.
            $vanHint = null;
            try {
                $order->refresh();
                $vs = new \App\Services\Riders\VanService();
                if ($vs->available()
                    && $order->order_status !== \App\Services\Riders\VanService::STATUS_ON_VAN
                    && !empty($order->van_loaded_at) && !empty($order->van_user_id)
                    && empty($order->handover_at)
                    && (int) $order->van_user_id !== (int) $rider->id
                    && $order->van_loaded_at >= now()->subHours(\App\Services\Riders\VanService::STALE_TAG_HOURS)) {
                    $vanHint = [
                        'order_id' => (int) $order->id,
                        'message'  => 'Ye order abhi van par hai aur kisi ne collect nahi kiya. '
                                    . 'Isay wapas "On Van" karein taake ' . $rider->fullname
                                    . ' van se scan kar ke le sake.',
                        'suggest_status' => \App\Services\Riders\VanService::STATUS_ON_VAN,
                    ];
                }
            } catch (\Throwable $e) {
                // A hint must never cost a successful assignment.
            }

            return response()->json([
                'success' => true,
                'message' => 'Rider assigned successfully',
                'assigned_rider' => [
                    'id' => $rider->id,
                    'name' => $rider->fullname
                ],
                'van_hint' => $vanHint,
                // 🔧 He is at the workshop — assigned anyway, and the phone says so ONCE.
                //    Null for the ordinary case, so a client that ignores it loses nothing.
                'warning' => $wsWarning,
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to assign rider (Store Mode)', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to assign rider: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Update order status
     */
    public function updateOrderStatus(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('change_order_status')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to change order status'
                ], 403);
            }
            
            $validated = $request->validate([
                'order_id' => 'required|exists:t_crm_prod_order,id',
                'status' => 'required|string|exists:t_crm_order_status_master,status_code'
            ]);
            
            $order = OrderModel::findOrFail($validated['order_id']);
            $oldStatus = $order->order_status;

            // ⭐⭐ RETURNS (Sep-2026) — refused on mobile, server-side.
            // The status is already hidden from this picker (show_in_mobile = 0),
            // but a stale APK still holds the old list, and hiding a thing is not
            // the same as forbidding it. A return has to answer where the money
            // goes; there is no dialog here to ask, and guessing moves real money.
            if ($validated['status'] === \App\Services\CRM\OrderReturnService::STATUS_CODE) {
                return response()->json([
                    'success' => false,
                    'message' => 'Returns are taken on the web by Shabib or Taimur — the money and the stock have to be decided there. The store is asked to scan the items back afterwards.',
                ], 422);
            }

            // 🚚 An order ON THE VAN is not moved from a status picker (owner
            // ruling Aug-4) — the handover scan is what proves who took it and
            // where. Cancel/refund/hold stay allowed; everything else is steered
            // to the van doors.
            $vanBlock = \App\Services\Riders\VanService::manualChangeBlock($order, $validated['status']);
            if ($vanBlock !== null) {
                // ⭐⭐ OFFER THE DOOR, DON'T JUST SHUT ONE (Aug-31). Farooq read
                //    this refusal at 12:52:00 and did the `on_hold` two-hop six
                //    seconds later — the message named the DRIVER's panel and gave
                //    the store nothing it could press, and the web button that
                //    could have done it went unused all day because the store
                //    works here, in mobile store mode. `van_release` lets the app
                //    put "Send it out with a delivery time" on this very alert.
                //    Null for every other refusal, so nothing else changes.
                return response()->json([
                    'success'     => false,
                    'message'     => $vanBlock,
                    'van_release' => \App\Services\Riders\VanService::releaseHint($order, $validated['status']),
                ], 422);
            }

            // Use the same method as webapp (OrderModel::changeStatus)
            $success = $order->changeStatus(
                $validated['status'],
                'Status changed via Store Mode',
                $user->id
            );

            if (!$success) {
                // A deliberate refusal (e.g. "this order was returned") explains
                // itself; anything else stays generic — see OrderModel::$lastStatusError.
                throw new \Exception($order->lastStatusError ?: 'Failed to change order status');
            }
            
            \Log::info('Order status updated (Store Mode)', [
                'order_id' => $order->id,
                'old_status' => $oldStatus,
                'new_status' => $validated['status'],
                'updated_by' => $user->id
            ]);

            /**
             * 🔧 MARKED "OUT FOR DELIVERY" WHILE HIS BIKE IS IN — allowed, and said once
             *    (owner ruling, 11-Sep-2026: out for delivery is NOT on the road).
             *
             * ⚠ Asked only for the one status that implies a rider is taking it, and only
             *   AFTER the change has succeeded — this reports, it never gates.
             */
            $wsWarning = null;
            if ($validated['status'] === 'out_for_delivery' && !empty($order->assigned_rider_user_id)) {
                $wsWarning = $this->workshopWarningFor(
                    (int) $order->assigned_rider_user_id,
                    'out_for_delivery',
                    ['order_id' => (int) $order->id, 'by' => $user->id ?? null]
                );
            }

            return response()->json([
                'success' => true,
                'message' => 'Order status updated successfully',
                'new_status' => $validated['status'],
                'warning' => $wsWarning,
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to update order status', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to update status: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Update packet information
     */
    public function updatePacketInfo(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('enter_packet_info')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to enter packet information'
                ], 403);
            }
            
            $validated = $request->validate([
                'order_id' => 'required|exists:t_crm_prod_order,id',
                'expected_packets' => 'required|integer|min:0'
            ]);
            
            $order = OrderModel::findOrFail($validated['order_id']);
            
            // Don't allow editing if already delivered
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cannot edit packet information for delivered orders'
                ], 422);
            }
            
            $previousExpected = (int) ($order->expected_packets ?: 0);
            $order->expected_packets = $validated['expected_packets'];
            $order->save();

            // ⭐ A scan-help approval means "this rider, this order, THIS many packets". The count
            //    just moved, so anything riding on the old number is void — otherwise a 1-of-2
            //    approval would still be sitting there after the store corrected the order to 3.
            //    (ScanHelpService::approvalFor re-checks this too; belt and braces on purpose.)
            if ($previousExpected !== (int) $validated['expected_packets']) {
                (new \App\Services\Riders\ScanHelpService())->clear($order, 'store changed expected_packets');
            }

            \Log::info('Packet info updated (Store Mode)', [
                'order_id' => $order->id,
                'expected_packets' => $validated['expected_packets'],
                'updated_by' => $user->id
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Packet information updated successfully',
                'expected_packets' => $validated['expected_packets']
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to update packet info', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to update packet information: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Update order note/instructions
     */
    public function updateOrderNote(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission - reuse enter_packet_info permission (general order editing)
            if (!$user->hasMobilePermission('enter_packet_info')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to edit order instructions'
                ], 403);
            }
            
            $validated = $request->validate([
                'order_id' => 'required|exists:t_crm_prod_order,id',
                'note' => 'nullable|string|max:1000'
            ]);
            
            $order = OrderModel::findOrFail($validated['order_id']);
            
            // Don't allow editing if already delivered
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cannot edit instructions for delivered orders'
                ], 422);
            }
            
            // Build the new note with attribution
            $newNote = trim($validated['note'] ?? '');
            $existingNote = trim($order->note ?? '');
            
            if (!empty($newNote)) {
                // Add attribution: "Note by [User Name]: [note text]"
                $attribution = "[{$user->fullname} - " . now()->format('d M H:i') . "]";
                
                if (!empty($existingNote)) {
                    // Append to existing note
                    $finalNote = $existingNote . "\n" . $attribution . " " . $newNote;
                } else {
                    // New note
                    $finalNote = $attribution . " " . $newNote;
                }
                
                $order->note = $finalNote;
            }
            
            $order->save();
            
            \Log::info('Order note updated (Store Mode)', [
                'order_id' => $order->id,
                'note_length' => strlen($order->note ?? ''),
                'updated_by' => $user->id,
                'user_name' => $user->fullname
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Order instructions updated successfully',
                'note' => $order->note
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to update order note', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to update order instructions: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Add note to customer (saves to customer record for future orders)
     */
    public function addCustomerNote(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission - reuse enter_packet_info permission (general order editing)
            if (!$user->hasMobilePermission('enter_packet_info')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to add customer notes'
                ], 403);
            }
            
            $validated = $request->validate([
                'customer_id' => 'required|exists:t_crm_prod_customer,id',
                'note' => 'required|string|max:1000'
            ]);
            
            $customer = \App\Models\CRM\CustomerModel::findOrFail($validated['customer_id']);
            
            // Build the new note with attribution
            $newNote = trim($validated['note']);
            $existingNote = trim($customer->notes ?? '');
            $timestamp = now()->format('Y-m-d H:i');
            $attribution = "[{$timestamp} - {$user->fullname}]";
            
            if (!empty($existingNote)) {
                // Append to existing notes
                $finalNote = $existingNote . "\n\n" . $attribution . " " . $newNote;
            } else {
                // New note
                $finalNote = $attribution . " " . $newNote;
            }
            
            $customer->notes = $finalNote;
            $customer->save();
            
            \Log::info('Customer note added (Store Mode)', [
                'customer_id' => $customer->id,
                'customer_name' => $customer->first_name . ' ' . $customer->last_name,
                'added_by' => $user->id,
                'user_name' => $user->fullname
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Note saved to customer profile',
                'notes' => $customer->notes
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to add customer note', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to save customer note: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Update payment method for an order
     */
    public function updatePaymentMethod(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission - reuse change_order_status permission
            if (!$user->hasMobilePermission('change_order_status')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to change payment method'
                ], 403);
            }
            
            $validated = $request->validate([
                'order_id' => 'required|exists:t_crm_prod_order,id',
                'payment_type' => 'required|in:cash,online',
                // Aug-2026 — "Set as default for this customer" tick in the store
                // Edit modal. Same flag name and meaning as the web quick-change
                // modal and both create-order forms.
                'set_default_payment_method' => 'nullable|boolean',
            ]);

            $order = OrderModel::findOrFail($validated['order_id']);
            
            // Don't allow editing if already delivered
            if (in_array($order->order_status, ['delivered', 'completed'])) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cannot change payment method for delivered orders'
                ], 422);
            }
            
            $oldPaymentMethod = $order->payment_method;
            
            // Map payment type to method (consistent with Rider Mode)
            // Using 'cash_on_delivery' and 'online_payment' for consistency across the system
            $newPaymentMethod = $validated['payment_type'] === 'cash' ? 'cash_on_delivery' : 'online_payment';
            
            $order->payment_method = $newPaymentMethod;
            $order->save();
            
            \Log::info('Payment method updated (Store Mode)', [
                'order_id' => $order->id,
                'old_payment_method' => $oldPaymentMethod,
                'new_payment_method' => $newPaymentMethod,
                'updated_by' => $user->id
            ]);

            // Aug-2026 — remember it on the CUSTOMER as well, when ticked. Written
            // through the single helper (value + attribution together) so this
            // surface stamps "set by X" exactly like the web ones. Resolved from
            // the order's own customer_id, never a client-supplied id.
            //
            // Note the modal may call this endpoint with an UNCHANGED payment_type
            // purely to carry the tick — that is deliberate. Eloquent leaves an
            // unchanged attribute clean, so no order UPDATE and no payment-change
            // observer fire in that case; only the customer default is written.
            //
            // Non-fatal: remembering a preference must never fail the order edit.
            $defaultSaved = null;
            if ($order->customer_id
                && filter_var($request->input('set_default_payment_method', false), FILTER_VALIDATE_BOOLEAN)) {
                try {
                    $stored = \App\Models\CRM\CustomerModel::setDefaultPaymentMethod(
                        $order->customer_id, $newPaymentMethod, $user->id
                    );
                    if ($stored !== false) {
                        $defaultSaved = $stored;
                        \Log::info('Customer default payment method set from store Edit modal', [
                            'customer_id' => $order->customer_id,
                            'order_id' => $order->id,
                            'default_payment_method' => $stored,
                            'user_id' => $user->id,
                        ]);
                    }
                } catch (\Throwable $e) {
                    \Log::warning('Failed to set customer default from store modal (non-fatal)', [
                        'customer_id' => $order->customer_id, 'error' => $e->getMessage(),
                    ]);
                }
            }

            return response()->json([
                'success' => true,
                'message' => 'Payment method updated successfully',
                'payment_method' => $newPaymentMethod,
                'payment_type' => $validated['payment_type'],
                'default_payment_method_saved' => $defaultSaved,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to update payment method', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to update payment method: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE MODE: Get open order quantities with drill-down
     * Reuses webapp logic from OrderController::openQuantitiesData
     */
    public function getOpenOrderQuantitiesTree(Request $request)
    {
        try {
            $user = Auth::user();

            if (!$user->hasMobilePermission('view_open_quantities')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view open order quantities'
                ], 403);
            }

            $statusFilter = $request->get('status_filter');
            if ($statusFilter === 'all') {
                $statusFilter = null;
            }

            // ⭐ Dedicated "Prepared" view. When ON, the query shows ONLY prepared
            //    items (preparation_status = 'preparing') instead of excluding
            //    them, and additionally hides dispatched (out_for_delivery) orders
            //    so prepared items drop off once they go out. Everything else
            //    (excluded statuses, 20-day window, qurbani/shopify rules) is
            //    identical. Default (no flag) is unchanged.
            $preparedOnly = filter_var($request->get('prepared_only', false), FILTER_VALIDATE_BOOLEAN);

            // Allow explicit hierarchy override (used by mobile fixed-endpoint),
            // otherwise fall back to the dynamic settings used by the web app.
            $overrideHierarchy = $request->get('hierarchy_override');
            if (is_array($overrideHierarchy) && !empty($overrideHierarchy)) {
                $hierarchy = $overrideHierarchy;
            } else {
                $hierarchySetting = DB::table('t_crm_open_quantities_settings')
                    ->where('setting_key', 'hierarchy_levels')
                    ->first();
                $hierarchy = $hierarchySetting ? json_decode($hierarchySetting->setting_value, true) : ['product_type', 'product_name', 'orders'];
                if (!is_array($hierarchy) || empty($hierarchy)) {
                    $hierarchy = ['product_type', 'product_name', 'orders'];
                }
            }
            if (!in_array('orders', $hierarchy, true)) {
                $hierarchy[] = 'orders';
            }

            // Central Order-Status rule service (Phase 1 = same values as before, centralised).
            $statusRules = app(\App\Services\CRM\OrderStatusRuleService::class);
            $excludedStatuses = $statusRules->quantitiesExcluded();

            // FIX: Use exclusive/priority-based JOIN to prevent duplicate rows
            // When SKU exists and matches, don't also match via product_id/variant_id
            // This prevents cross-matches where li.product_id (WooCommerce ID) accidentally 
            // matches pv.shopify_variant_id of a different product
            $query = DB::table('t_crm_prod_order_line_item as li')
                ->join('t_crm_prod_order as o', 'li.order_id', '=', 'o.id')
                ->leftJoin('t_crm_prod_product_variant as pv', function ($join) {
                    // EXCLUSIVE matching: SKU match OR (fallbacks only when no SKU)
                    $join->where(function ($q) {
                        // PRIORITY 1: SKU match (most reliable) - when SKU exists
                        $q->where(function($skuMatch) {
                            $skuMatch->whereNotNull('li.sku')
                                     ->where('li.sku', '!=', '')
                                     ->whereColumn('li.sku', 'pv.sku');
                        })
                        // PRIORITY 2-5: Fallbacks ONLY when no valid SKU exists
                        ->orWhere(function($fallback) {
                            $fallback->where(function($noSku) {
                                $noSku->whereNull('li.sku')
                                      ->orWhere('li.sku', '');
                            })
                            ->where(function($idMatch) {
                                $idMatch->whereColumn('li.variant_id', 'pv.shopify_variant_id')
                                        ->orWhereColumn('li.variant_id', 'pv.id')
                                        ->orWhereColumn('li.product_id', 'pv.shopify_variant_id')
                                        ->orWhereColumn('li.product_id', 'pv.id');
                            });
                        });
                    });
                })
                ->leftJoin('t_crm_prod_product as p', function ($join) {
                    // Product match: via variant (covers SKU match) or name fallback for legacy
                    $join->where(function ($q) {
                        // Primary: Match via variant's product_id (safe, no cross-match risk)
                        $q->whereColumn('pv.product_id', 'p.id')
                          // PRIORITY 7: Name fallback for legacy orders without SKU/IDs
                          ->orWhere(function($nameFallback) {
                              $nameFallback->whereNull('li.sku')
                                           ->where(function($noIds) {
                                               $noIds->whereNull('li.variant_id')
                                                     ->orWhere('li.variant_id', '');
                                           })
                                           ->where(function($noProdId) {
                                               $noProdId->whereNull('li.product_id')
                                                        ->orWhere('li.product_id', '');
                                           })
                                           ->whereRaw('LOWER(TRIM(li.name)) = LOWER(TRIM(p.title))');
                          });
                    });
                })
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->where(function ($q) {
                    $q->where('o.external_source', '!=', 'shopify')
                      ->orWhereNull('o.external_source');
                })
                ->whereNotIn('o.order_status', $excludedStatuses)
                ->where('o.order_date', '>=', Carbon::now()->subDays(20))
                ->where(function($q) {
                    $q->whereNull('p.attribute_1')
                      ->orWhereRaw("LOWER(p.attribute_1) != 'qurbani'");
                });

            // ⭐ Preparation filter — inverted for the dedicated Prepared view.
            //    Besides showing only prepared items, we must also drop orders
            //    that have moved PAST preparation. The normal view hides these
            //    incidentally (their items are prepared, so the "not prepared"
            //    filter removes them), but the Prepared view shows prepared
            //    items, so we exclude the terminal/post-prep statuses here.
            //    NOTE: excluded_statuses (cancelled/refunded/pending) is already
            //    applied above; delivered/completed/out_for_delivery are NOT in
            //    that list, so they must be excluded explicitly.
            if ($preparedOnly) {
                $query->where('li.preparation_status', 'preparing')
                      ->whereNotIn('o.order_status', $statusRules->outTheDoor());
            } else {
                $query->where(function($q) {
                    $q->whereNull('li.preparation_status')
                      ->orWhere('li.preparation_status', '!=', 'preparing');
                });
            }

            if ($statusFilter) {
                $query->where('o.order_status', $statusFilter);
            }

            $rows = $query->select([
                    'o.id as order_id',
                    'o.order_number',
                    'o.order_status',
                    'o.order_date',
                    DB::raw("COALESCE(
                        NULLIF(TRIM(o.name), ''),
                        NULLIF(TRIM(CONCAT(COALESCE(c.first_name, ''), ' ', COALESCE(c.last_name, ''))), ''),
                        TRIM(CONCAT(COALESCE(o.address_first_name, ''), ' ', COALESCE(o.address_last_name, '')))
                    ) as customer_name"),
                    'li.id as line_item_id',
                    'li.quantity as line_item_quantity',
                    'li.preparation_status as line_item_status',
                    'li.product_id as line_item_product_id',
                    'li.variant_id as line_item_variant_id',
                    'li.name as line_item_name',
                    'li.instructions as line_item_instructions',
                    'p.id as product_id',
                    'p.title as product_title',
                    'p.product_type',
                    'p.attribute_1',
                    'p.attribute_2',
                    'p.attribute_3',
                    DB::raw('COALESCE(p.is_lean, 0) as is_lean'),
                    // ⭐ Kg represented by ONE qty unit (0.5 for a 500g pack). Read-only:
                    //    every node carries weight = SUM(qty * unit_weight_kg) alongside qty.
                    //    NOT weight_factor (that is the weighing/scan divisor). Column comes
                    //    from the product row already joined above — no extra join or filter.
                    DB::raw('COALESCE(p.unit_weight_kg, 1) as unit_weight_kg')
                ])
                ->orderBy('o.order_date', 'desc')
                ->get();

            // ⭐ Overnight-storage (chiller/freezer) stock per PRODUCT.
            //    This is product STATE, not order flow: the same product on 10 open
            //    orders still has ONE physical stock figure. So it is deliberately
            //    NOT accumulated per line-item row (that would multiply it) — it is
            //    read once here into a tiny map and attached per node in
            //    $finalizeNode, against each node's DISTINCT products.
            //    Never throws: the overnight tables may not exist on a given
            //    environment yet, and quantities must keep working regardless.
            $stockService = app(\App\Services\CRM\OvernightStockService::class);
            $storageMap = $stockService->map();
            $storageCatalog = $stockService->catalog();

            $totalQuantity = 0.0;
            $totalWeight = 0.0;
            $totalLineItems = 0;
            $uniqueOrderIds = [];
            $orderStatusesByOrder = [];

            $tree = [];
            $rootMap = [];

            $addMetrics = function (&$node, $row) {
                $qty = (float) ($row->line_item_quantity ?? 0);
                $unitWeight = (float) ($row->unit_weight_kg ?? 1);
                $isLean = (int) ($row->is_lean ?? 0) === 1;
                $orderStatus = strtolower((string) ($row->order_status ?? ''));
                $lineStatus = strtolower((string) ($row->line_item_status ?? ''));

                // ✅ Defensive initialization to avoid \"Undefined array key\" issues
                if (!isset($node['quantity'])) {
                    $node['quantity'] = 0.0;
                }
                if (!isset($node['weight'])) {
                    $node['weight'] = 0.0;
                }
                if (!isset($node['lean_quantity'])) {
                    $node['lean_quantity'] = 0.0;
                }
                if (!isset($node['non_lean_quantity'])) {
                    $node['non_lean_quantity'] = 0.0;
                }
                if (!isset($node['processing_quantity'])) {
                    $node['processing_quantity'] = 0.0;
                }
                if (!isset($node['prepared_quantity'])) {
                    $node['prepared_quantity'] = 0.0;
                }

                $node['quantity'] += $qty;
                $node['weight'] += $qty * $unitWeight;
                if ($isLean) {
                    $node['lean_quantity'] += $qty;
                } else {
                    $node['non_lean_quantity'] += $qty;
                }
                if ($orderStatus === 'processing') {
                    $node['processing_quantity'] += $qty;
                }
                if ($lineStatus === 'preparing') {
                    $node['prepared_quantity'] += $qty;
                }
            };

            foreach ($rows as $row) {
                $qty = (float) ($row->line_item_quantity ?? 0);
                $totalQuantity += $qty;
                $totalWeight += $qty * (float) ($row->unit_weight_kg ?? 1);
                $totalLineItems++;
                $uniqueOrderIds[$row->order_id] = true;

                if (!isset($orderStatusesByOrder[$row->order_id])) {
                    $orderStatusesByOrder[$row->order_id] = $row->order_status ?? 'new';
                }

                $currentList =& $tree;
                $currentMap =& $rootMap;
                $currentFilters = [];

                foreach ($hierarchy as $levelIndex => $field) {
                    if ($field === 'orders') {
                        // CRITICAL FIX: Order nodes must be unique per product
                        // Use a composite key: product_name + order_id
                        $productContext = $currentFilters['product_name'] ?? 'unknown';
                        $orderKey = $productContext . '_' . $row->order_id;
                        
                        if (!isset($currentMap[$orderKey])) {
                            $orderLabel = $row->order_number ? 'Order #' . $row->order_number : 'Order ' . $row->order_id;
                            if (!empty($row->customer_name)) {
                                $orderLabel .= ' - ' . $row->customer_name;
                            }

                            $orderNode = [
                                'name' => $orderLabel,
                                'field' => 'orders',
                                'level' => $levelIndex,
                                'quantity' => 0,
                                'weight' => 0,
                                'lean_quantity' => 0,
                                'non_lean_quantity' => 0,
                                'processing_quantity' => 0,
                                'prepared_quantity' => 0,
                                'order_count' => 0,
                                'product_count' => 0,
                                'order_id' => $row->order_id,
                                'order_number' => $row->order_number,
                                'status' => $row->order_status,
                                'order_date' => $row->order_date ? Carbon::parse($row->order_date)->toIso8601String() : null,
                                'customer_name' => $row->customer_name,
                                'instructions' => null,
                                'filters' => array_merge($currentFilters, ['order_id' => $row->order_id]),
                                'children' => [],
                                '_children_map' => [],
                                '_order_ids' => [$row->order_id => true],
                                '_product_ids' => [],
                                '_li_product_ids' => [],
                                // INTERNAL t_crm_prod_product ids only (p.id). Kept apart from
                                // _product_ids, which also holds li.product_id — an EXTERNAL id
                                // on synced orders that can collide with an unrelated p.id.
                                // Overnight stock is keyed by the internal id, so it must never
                                // be looked up through the mixed set.
                                '_int_product_ids' => [],
                            ];

                            $currentList[] = $orderNode;
                            $currentMap[$orderKey] = &$currentList[count($currentList) - 1];
                        }

                        // CRITICAL FIX: Don't use reference here, update the array directly
                        // Get current quantity
                        $qtyBefore = $currentMap[$orderKey]['quantity'];
                        
                        // Add metrics directly to the map entry
                        // ⚠️ This block is a DUPLICATE of $addMetrics (order nodes do not go
                        //    through it). Any new accumulator must be added in BOTH places.
                        $qty = (float) ($row->line_item_quantity ?? 0);
                        $unitWeight = (float) ($row->unit_weight_kg ?? 1);
                        $isLean = (int) ($row->is_lean ?? 0) === 1;
                        $orderStatus = strtolower((string) ($row->order_status ?? ''));
                        $lineStatus = strtolower((string) ($row->line_item_status ?? ''));

                        $currentMap[$orderKey]['quantity'] += $qty;
                        $currentMap[$orderKey]['weight'] = ($currentMap[$orderKey]['weight'] ?? 0) + ($qty * $unitWeight);
                        if ($isLean) {
                            $currentMap[$orderKey]['lean_quantity'] += $qty;
                        } else {
                            $currentMap[$orderKey]['non_lean_quantity'] += $qty;
                        }
                        if ($orderStatus === 'processing') {
                            $currentMap[$orderKey]['processing_quantity'] += $qty;
                        }
                        if ($lineStatus === 'preparing') {
                            $currentMap[$orderKey]['prepared_quantity'] += $qty;
                        }
                        
                        // Collect line item instructions for this order node
                        $lineInstructions = trim((string) ($row->line_item_instructions ?? ''));
                        if ($lineInstructions !== '') {
                            if ($currentMap[$orderKey]['instructions'] === null) {
                                $currentMap[$orderKey]['instructions'] = $lineInstructions;
                            } elseif (strpos($currentMap[$orderKey]['instructions'], $lineInstructions) === false) {
                                $currentMap[$orderKey]['instructions'] .= ' | ' . $lineInstructions;
                            }
                        }

                        // Sync updated values back to the actual array in $currentList
                        foreach ($currentList as $idx => &$listItem) {
                            if (isset($listItem['order_id']) && $listItem['order_id'] == $row->order_id) {
                                $listItem['quantity'] = $currentMap[$orderKey]['quantity'];
                                $listItem['weight'] = $currentMap[$orderKey]['weight'];
                                $listItem['lean_quantity'] = $currentMap[$orderKey]['lean_quantity'];
                                $listItem['non_lean_quantity'] = $currentMap[$orderKey]['non_lean_quantity'];
                                $listItem['processing_quantity'] = $currentMap[$orderKey]['processing_quantity'];
                                $listItem['prepared_quantity'] = $currentMap[$orderKey]['prepared_quantity'];
                                $listItem['instructions'] = $currentMap[$orderKey]['instructions'];
                                break;
                            }
                        }
                        unset($listItem);

                        if ($row->line_item_product_id) {
                            $currentMap[$orderKey]['_product_ids'][(int) $row->line_item_product_id] = true;
                            $currentMap[$orderKey]['_li_product_ids'][(int) $row->line_item_product_id] = true;
                        }
                        if ($row->product_id) {
                            $currentMap[$orderKey]['_product_ids'][(int) $row->product_id] = true;
                            $currentMap[$orderKey]['_int_product_ids'][(int) $row->product_id] = true;
                        }

                        break;
                    }

                    if ($field === 'orders') {
                        continue;
                    }

                    if ($field === 'product_name') {
                        $label = $row->line_item_name ?: ($row->product_title ?: 'Uncategorized');
                    } else {
                        $value = $row->{$field} ?? null;
                        // CRITICAL: Always treat NULL or empty string as "Uncategorized" to ensure tree continues building
                        $label = ($value !== null && trim((string)$value) !== '') ? $value : 'Uncategorized';
                    }

                    $nodeKey = $label;

                    if (!isset($currentMap[$nodeKey])) {
                        $nodeFilters = array_merge($currentFilters, [$field => $label]);

                        $newNode = [
                            'name' => $label,
                            'field' => $field,
                            'level' => $levelIndex,
                            'quantity' => 0,
                            'weight' => 0,
                            'lean_quantity' => 0,
                            'non_lean_quantity' => 0,
                            'processing_quantity' => 0,
                            'prepared_quantity' => 0,
                            'order_count' => 0,
                            'product_count' => 0,
                            'filters' => $nodeFilters,
                            'children' => [],
                            '_children_map' => [],
                            '_order_ids' => [],
                            '_product_ids' => [],
                            '_int_product_ids' => [], // p.id only — see the order-node note above
                        ];

                        if ($field === 'product_name') {
                            $newNode['product_ids'] = [];
                            $newNode['has_instructions'] = false;
                        }

                        // Add to current list
                        $currentList[] = $newNode;
                        // Store a REFERENCE to the node in the map
                        $currentMap[$nodeKey] =& $currentList[count($currentList) - 1];
                    }

                    // Get reference to the node (BEFORE we change $currentList)
                    $node =& $currentMap[$nodeKey];
                    $addMetrics($node, $row);

                    $node['_order_ids'][$row->order_id] = true;
                    if ($row->line_item_product_id) {
                        $node['_product_ids'][(int) $row->line_item_product_id] = true;
                    }
                    if ($row->product_id) {
                        $node['_product_ids'][(int) $row->product_id] = true;
                        $node['_int_product_ids'][(int) $row->product_id] = true;
                    }

                    if ($field === 'product_name') {
                        if (!isset($node['product_ids'])) {
                            $node['product_ids'] = [];
                        }
                        if ($row->line_item_product_id) {
                            $node['product_ids'][(int) $row->line_item_product_id] = true;
                        }
                        if ($row->product_id) {
                            $node['product_ids'][(int) $row->product_id] = true;
                        }

                        $node['filters']['product_name'] = $label;
                        if (!empty($node['product_ids'])) {
                            $node['filters']['product_ids'] = implode(',', array_keys($node['product_ids']));
                        }

                        // Mark product_name node if any contributing line item has instructions
                        if (!empty(trim((string) ($row->line_item_instructions ?? '')))) {
                            $node['has_instructions'] = true;
                        }
                    }

                    // CRITICAL FIX: Navigate to next level
                    // We MUST get references to the node's children BEFORE reassigning $currentList
                    $nextChildren =& $node['children'];
                    $nextMap =& $node['_children_map'];
                    $currentFilters = $node['filters'];
                    
                    // Now it's safe to reassign these variables
                    $currentList =& $nextChildren;
                    $currentMap =& $nextMap;
                }
            }

            // Summed once per node (never per row), so a product on many orders
            // contributes its physical stock exactly once.
            //  - CATEGORY nodes count EVERY stocked product in that category, even
            //    ones with no open orders today (owner's call) — matched on the
            //    node's full ancestor path, so a shared child label can't leak.
            //  - PRODUCT / ORDER nodes use the exact internal product ids, which is
            //    more precise than a name match when titles are duplicated.
            $sumStorage = function (array $node) use ($stockService, $storageMap, $storageCatalog) {
                $field = $node['field'] ?? null;
                if (in_array($field, \App\Services\CRM\OvernightStockService::CATEGORY_FIELDS, true)) {
                    return $stockService->sumForCategory($storageCatalog, $node['filters'] ?? []);
                }

                return $stockService->sumFor($storageMap, $node['_int_product_ids'] ?? []);
            };

            // ⭐ Which products make up this node's figure — published as `storage_ids`
            //    so the breakdown sheet is a local lookup against `storage_catalog`
            //    (no request on tap, works on the cached tree) and can never disagree
            //    with the number that opened it. Same matcher as $sumStorage above.
            $storageIdsFor = function (array $node) use ($stockService, $storageMap, $storageCatalog) {
                $field = $node['field'] ?? null;
                if (in_array($field, \App\Services\CRM\OvernightStockService::CATEGORY_FIELDS, true)) {
                    return $stockService->matchCategoryIds($storageCatalog, $node['filters'] ?? []) ?? [];
                }

                return $stockService->stockedIds($storageMap, $node['_int_product_ids'] ?? []);
            };

            $finalizeNode = function (&$node) use (&$finalizeNode, $sumStorage, $storageIdsFor) {
                $node['order_count'] = count($node['_order_ids']);
                $node['product_count'] = count(array_filter(array_keys($node['_product_ids'])));

                // Kill float drift (0.5 * 21 style sums) before the value leaves the server.
                $node['weight'] = round((float) ($node['weight'] ?? 0), 2);

                // Physical stock for this node. Key omitted when there is none.
                // ⚠️ Both reads must happen BEFORE the unset() below — _int_product_ids
                //    is what the product/order branch matches on.
                $storage = $sumStorage($node);
                if ($storage !== null) {
                    $node['storage'] = $storage;
                    $node['storage_ids'] = $storageIdsFor($node);
                }

                unset($node['_order_ids'], $node['_product_ids'], $node['_children_map'], $node['_int_product_ids']);

                if (isset($node['product_ids']) && is_array($node['product_ids'])) {
                    $productIds = array_keys($node['product_ids']);
                    sort($productIds);
                    $node['product_ids'] = $productIds;
                }

                if (isset($node['_li_product_ids'])) {
                    if (!empty($node['_li_product_ids'])) {
                        $node['product_ids'] = array_values(array_map('intval', array_keys($node['_li_product_ids'])));
                    }
                    unset($node['_li_product_ids']);
                }

                if (!empty($node['children'])) {
                    // Finalize children first (to calculate their quantities)
                    foreach ($node['children'] as &$child) {
                        $finalizeNode($child);
                    }
                    unset($child); // Break the reference to avoid issues
                }
            };

            foreach ($tree as &$rootNode) {
                $finalizeNode($rootNode);
            }
            unset($rootNode);

            usort($tree, function ($a, $b) {
                return $b['quantity'] <=> $a['quantity'];
            });

            // DISABLED: Fallback logic - the primary tree builder handles all hierarchies correctly
            // including NULL values as "Uncategorized" and builds the full depth.
            $needsFallback = false;

            if ($needsFallback) {
                try {
                    $field0 = $hierarchy[0] ?? 'attribute_1';
                    $field1 = $hierarchy[1] ?? null;
                    $labelFor = function ($row, $field) {
                        if ($field === 'product_name') {
                            return $row->line_item_name ?: ($row->product_title ?: 'Uncategorized');
                        }
                        $value = $row->{$field} ?? null;
                        return ($value !== null && $value !== '') ? $value : 'Uncategorized';
                    };
                    $addMetrics = function (&$node, $row) {
                        $qty = (float) ($row->line_item_quantity ?? 0);
                        $isLean = (int) ($row->is_lean ?? 0) === 1;
                        $orderStatus = strtolower((string) ($row->order_status ?? ''));
                        $lineStatus = strtolower((string) ($row->line_item_status ?? ''));
                        $node['quantity'] += $qty;
                        if ($isLean) { $node['lean_quantity'] += $qty; } else { $node['non_lean_quantity'] += $qty; }
                        if ($orderStatus === 'processing') { $node['processing_quantity'] += $qty; }
                        if ($lineStatus === 'preparing') { $node['prepared_quantity'] += $qty; }
                    };

                    $groups0 = [];
                    foreach ($rows as $row) {
                        $key0 = $labelFor($row, $field0);
                        if (!isset($groups0[$key0])) { $groups0[$key0] = []; }
                        $groups0[$key0][] = $row;
                    }

                    $rebuilt = [];
                    foreach ($groups0 as $label0 => $rows0) {
                        $node0 = [
                            'name' => $label0,
                            'field' => $field0,
                            'level' => 0,
                            'quantity' => 0,
                            'lean_quantity' => 0,
                            'non_lean_quantity' => 0,
                            'processing_quantity' => 0,
                            'prepared_quantity' => 0,
                            'order_count' => 0,
                            'product_count' => 0,
                            'filters' => [$field0 => $label0],
                            'children' => [],
                        ];
                        $orderIds = [];
                        $productIds = [];
                        foreach ($rows0 as $r0) {
                            $addMetrics($node0, $r0);
                            $orderIds[$r0->order_id] = true;
                            if ($r0->line_item_product_id) { $productIds[(int)$r0->line_item_product_id] = true; }
                            if ($r0->product_id) { $productIds[(int)$r0->product_id] = true; }
                        }
                        $node0['order_count'] = count($orderIds);
                        $node0['product_count'] = count(array_filter(array_keys($productIds)));

                        // Optional level 1 (attribute_2)
                        if ($field1) {
                            $groups1 = [];
                            foreach ($rows0 as $row1) {
                                $key1 = $labelFor($row1, $field1);
                                if (!isset($groups1[$key1])) { $groups1[$key1] = []; }
                                $groups1[$key1][] = $row1;
                            }
                            foreach ($groups1 as $label1 => $rows1) {
                                $child = [
                                    'name' => $label1,
                                    'field' => $field1,
                                    'level' => 1,
                                    'quantity' => 0,
                                    'lean_quantity' => 0,
                                    'non_lean_quantity' => 0,
                                    'processing_quantity' => 0,
                                    'prepared_quantity' => 0,
                                    'order_count' => 0,
                                    'product_count' => 0,
                                    'filters' => [$field0 => $label0, $field1 => $label1],
                                    'children' => [],
                                ];
                                $oIds = []; $pIds = [];
                                foreach ($rows1 as $r1) {
                                    $addMetrics($child, $r1);
                                    $oIds[$r1->order_id] = true;
                                    if ($r1->line_item_product_id) { $pIds[(int)$r1->line_item_product_id] = true; }
                                    if ($r1->product_id) { $pIds[(int)$r1->product_id] = true; }
                                }
                                $child['order_count'] = count($oIds);
                                $child['product_count'] = count(array_filter(array_keys($pIds)));

                                // Optional level 2 (could be attribute_3, product_name, or other)
                                $field2 = $hierarchy[2] ?? null;
                                if ($field2 && $field2 !== 'orders') {
                                    $groups2 = [];
                                    foreach ($rows1 as $row2) {
                                        $key2 = $labelFor($row2, $field2);
                                        if (!isset($groups2[$key2])) { $groups2[$key2] = []; }
                                        $groups2[$key2][] = $row2;
                                    }
                                    foreach ($groups2 as $label2 => $rows2) {
                                        $node2 = [
                                            'name' => $label2,
                                            'field' => $field2,
                                            'level' => 2,
                                            'quantity' => 0,
                                            'lean_quantity' => 0,
                                            'non_lean_quantity' => 0,
                                            'processing_quantity' => 0,
                                            'prepared_quantity' => 0,
                                            'order_count' => 0,
                                            'product_count' => 0,
                                            'filters' => [$field0 => $label0, $field1 => $label1, $field2 => $label2],
                                            'children' => [],
                                        ];
                                        
                                        if ($field2 === 'product_name') {
                                            $node2['product_ids'] = [];
                                        }
                                        $o2 = []; $p2 = [];
                                        foreach ($rows2 as $r2) {
                                            $addMetrics($prodNode, $r2);
                                            $o2[$r2->order_id] = true;
                                            if ($r2->line_item_product_id) { $p2[(int)$r2->line_item_product_id] = true; }
                                            if ($r2->product_id) { $p2[(int)$r2->product_id] = true; }
                                        }
                                        $prodNode['order_count'] = count($o2);
                                        $prodNode['product_count'] = count(array_filter(array_keys($p2)));
                                        if (!empty($p2)) {
                                            $ids = array_keys($p2);
                                            sort($ids);
                                            $prodNode['product_ids'] = $ids;
                                            $prodNode['filters']['product_ids'] = implode(',', $ids);
                                        }

                                        // Optional level 3 (orders)
                                        $field3 = $hierarchy[3] ?? null;
                                        if ($field3 === 'orders') {
                                            $orders = [];
                                            foreach ($rows2 as $r3) {
                                                $orderKey = (string) $r3->order_id;
                                                if (!isset($orders[$orderKey])) {
                                                    $orderLabel = $r3->order_number ? ('Order #' . $r3->order_number) : ('Order ' . $r3->order_id);
                                                    if (!empty($r3->customer_name)) {
                                                        $orderLabel .= ' - ' . $r3->customer_name;
                                                    }
                                                    $orders[$orderKey] = [
                                                        'name' => $orderLabel,
                                                        'field' => 'orders',
                                                        'level' => 3,
                                                        'quantity' => 0,
                                                        'lean_quantity' => 0,
                                                        'non_lean_quantity' => 0,
                                                        'processing_quantity' => 0,
                                                        'prepared_quantity' => 0,
                                                        'order_count' => 0,
                                                        'product_count' => 0,
                                                        'order_id' => $r3->order_id,
                                                        'order_number' => $r3->order_number,
                                                        'status' => $r3->order_status,
                                                        'order_date' => $r3->order_date ? \Carbon\Carbon::parse($r3->order_date)->toIso8601String() : null,
                                                        'customer_name' => $r3->customer_name,
                                                        'filters' => array_merge($prodNode['filters'], ['order_id' => $r3->order_id]),
                                                        'children' => [],
                                                    ];
                                                }
                                                $addMetrics($orders[$orderKey], $r3);
                                            }
                                            // finalize counts and append
                                            foreach ($orders as &$ordNode) {
                                                $ordNode['order_count'] = 1;
                                            }
                                            uasort($orders, function ($a, $b) { return $b['quantity'] <=> $a['quantity']; });
                                            $prodNode['children'] = array_values($orders);
                                        }

                                        $child['children'][] = $prodNode;
                                    }
                                    usort($child['children'], function ($a, $b) { return $b['quantity'] <=> $a['quantity']; });
                                }
                                $node0['children'][] = $child;
                            }
                            usort($node0['children'], function ($a, $b) { return $b['quantity'] <=> $a['quantity']; });
                        }

                        $rebuilt[] = $node0;
                    }
                    usort($rebuilt, function ($a, $b) { return $b['quantity'] <=> $a['quantity']; });
                    $tree = $rebuilt;
                    Log::info('Applied fallback tree rebuild', ['root_count' => count($tree)]);
                } catch (\Throwable $e) {
                    Log::warning('Fallback tree rebuild failed', ['error' => $e->getMessage()]);
                }
            }

            $orderStatusCounts = [];
            foreach ($orderStatusesByOrder as $status) {
                $orderStatusCounts[$status] = ($orderStatusCounts[$status] ?? 0) + 1;
            }

            // ✅ CRITICAL: Break all PHP references before JSON encoding
            // The tree uses references (&) for performance during building,
            // but these create circular references that break json_encode()
            // Deep clone via unserialize(serialize()) breaks all references
            $treeClean = unserialize(serialize($tree));

            return response()->json([
                'success' => true,
                'generated_at' => Carbon::now()->toIso8601String(),
                'status_filter' => $statusFilter ?? 'all',
                'hierarchy' => $hierarchy,
                'summary' => [
                    'total_orders' => count($uniqueOrderIds),
                    'total_line_items' => $totalLineItems,
                    'total_quantity' => round($totalQuantity, 2),
                    'total_weight' => round($totalWeight, 2),
                ],
                'order_status_counts' => $orderStatusCounts,
                'tree' => $treeClean,
                // ⭐ Everything physically in the chiller/freezer right now — sent ONCE
                //    with the tree (bounded by "one night's leftovers"), so a breakdown
                //    sheet never needs a request and works from the cached tree offline.
                'storage_catalog' => $stockService->catalogRows(),
                // The whole room. The tree only contains products that are on open
                // orders, so summing node storage can never reach this — a category with
                // no orders has no node at all. This is the honest headline figure.
                'storage_total' => $stockService->grandTotal(),
            ]);
        } catch (\Exception $e) {
            Log::error('Failed to build open quantities tree', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load quantities tree: ' . $e->getMessage(),
            ], 500);
        }
    }

    /**
     * Per-user display sort preferences for the Open Order Quantities screen.
     *
     * Stored per authenticated user in t_crm_open_quantities_user_sort, keyed by
     * hierarchy FIELD name (attribute_1, product_name, ...) — never by level
     * index, so a hierarchy change can't misapply an old preference.
     * Shape: {"attribute_1":{"mode":"custom","sequence":["Chicken","Beef"]}}
     * Modes: qty_desc (default when a field is absent) | alpha | custom.
     *
     * ⭐ Sorting itself happens ON THE PHONE at display time. These endpoints only
     *    store/return the preference — the tree endpoint is deliberately untouched
     *    (same payload, same speed, no per-request preference lookup).
     */
    public function getQuantitiesSortPrefs()
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('view_open_quantities')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $prefs = app(\App\Services\CRM\QuantitiesSortService::class)->getPrefs($user->id);

            return response()->json([
                'success' => true,
                'prefs' => empty($prefs) ? (object) [] : $prefs,
            ]);
        } catch (\Exception $e) {
            Log::error('Failed to load quantities sort prefs', ['user_id' => Auth::id(), 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to load sort preferences'], 500);
        }
    }

    public function saveQuantitiesSortPrefs(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('view_open_quantities')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $raw = $request->input('prefs');
            if (is_string($raw)) {
                $raw = json_decode($raw, true);
            }
            if (!is_array($raw)) {
                return response()->json(['success' => false, 'message' => 'prefs must be an object'], 422);
            }

            // Sanitizing + persisting lives in the service so the web page and the
            // app can never drift apart on what a valid preference is.
            $clean = app(\App\Services\CRM\QuantitiesSortService::class)->savePrefs($user->id, $raw);

            return response()->json(['success' => true, 'prefs' => empty($clean) ? (object) [] : $clean]);
        } catch (\Exception $e) {
            Log::error('Failed to save quantities sort prefs', ['user_id' => Auth::id(), 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to save sort preferences'], 500);
        }
    }

    public function getOpenOrderQuantities(Request $request)
    {
        try {
            $user = Auth::user();

            // Check permission
            if (!$user->hasMobilePermission('view_open_quantities')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view open order quantities'
                ], 403);
            }
            
            // Get parameters
            $level = (int) $request->get('level', 0);
            
            // Handle filters - can be JSON string or already an array (from mobile)
            $filtersInput = $request->get('filters', '{}');
            if (is_array($filtersInput)) {
                $filters = $filtersInput;
            } else {
                $filters = json_decode($filtersInput, true) ?: [];
            }
            
            $statusFilter = $request->get('status_filter'); // Optional status filter
            // ⭐ Prepared view (see getOpenOrderQuantitiesTree). Only prepared
            //    items, and hides dispatched orders. Default unchanged.
            $preparedOnly = filter_var($request->get('prepared_only', false), FILTER_VALIDATE_BOOLEAN);
            
            // Allow mobile to override hierarchy (same as tree endpoint)
            $overrideHierarchy = $request->get('hierarchy_override');
            if ($overrideHierarchy) {
                // Handle both JSON string and array
                $hierarchy = is_array($overrideHierarchy) ? $overrideHierarchy : json_decode($overrideHierarchy, true);
            }
            
            // If no override, get global settings from database (same as web app)
            if (empty($hierarchy) || !is_array($hierarchy)) {
                $hierarchySetting = DB::table('t_crm_open_quantities_settings')
                    ->where('setting_key', 'hierarchy_levels')
                    ->first();
                $hierarchy = $hierarchySetting ? json_decode($hierarchySetting->setting_value, true) : ['product_type', 'product_name'];
            }
            
            // Central Order-Status rule service (Phase 1 = same values as before, centralised).
            $statusRules = app(\App\Services\CRM\OrderStatusRuleService::class);
            $excludedStatuses = $statusRules->quantitiesExcluded();

            // Build base query — joins MIRROR getOpenOrderQuantitiesTree exactly.
            // ⭐ Aligned Aug-2026: this endpoint previously used a plain OR chain here,
            //    which let one line item match several variants (row fan-out that
            //    inflated every SUM on this fallback path). Keep the two endpoints'
            //    joins identical or their numbers drift apart again.
            $query = DB::table('t_crm_prod_order_line_item as li')
                ->join('t_crm_prod_order as o', 'li.order_id', '=', 'o.id')
                ->leftJoin('t_crm_prod_product_variant as pv', function($join) {
                    // EXCLUSIVE matching: SKU match OR (fallbacks only when no SKU)
                    $join->where(function($q) {
                        // PRIORITY 1: SKU match (most reliable) - when SKU exists
                        $q->where(function($skuMatch) {
                            $skuMatch->whereNotNull('li.sku')
                                     ->where('li.sku', '!=', '')
                                     ->whereColumn('li.sku', 'pv.sku');
                        })
                        // PRIORITY 2-5: Fallbacks ONLY when no valid SKU exists
                        ->orWhere(function($fallback) {
                            $fallback->where(function($noSku) {
                                $noSku->whereNull('li.sku')
                                      ->orWhere('li.sku', '');
                            })
                            ->where(function($idMatch) {
                                $idMatch->whereColumn('li.variant_id', 'pv.shopify_variant_id')
                                        ->orWhereColumn('li.variant_id', 'pv.id')
                                        ->orWhereColumn('li.product_id', 'pv.shopify_variant_id')
                                        ->orWhereColumn('li.product_id', 'pv.id');
                            });
                        });
                    });
                })
                ->leftJoin('t_crm_prod_product as p', function($join) {
                    // Product match: via variant (covers SKU match) or name fallback for
                    // legacy rows — same as the tree. The old extra arm `li.product_id = p.id`
                    // was removed: li.product_id is an EXTERNAL id for synced orders and can
                    // collide with an unrelated internal p.id (mis-categorised, double rows).
                    $join->where(function($q) {
                        $q->whereColumn('pv.product_id', 'p.id')
                          // PRIORITY 7: Name fallback for legacy orders without SKU/IDs
                          ->orWhere(function($nameFallback) {
                              $nameFallback->whereNull('li.sku')
                                           ->where(function($noIds) {
                                               $noIds->whereNull('li.variant_id')
                                                     ->orWhere('li.variant_id', '');
                                           })
                                           ->where(function($noProdId) {
                                               $noProdId->whereNull('li.product_id')
                                                        ->orWhere('li.product_id', '');
                                           })
                                           ->whereRaw('LOWER(TRIM(li.name)) = LOWER(TRIM(p.title))');
                          });
                    });
                })
                ->where(function($q) {
                    $q->where('o.external_source', '!=', 'shopify')
                      ->orWhereNull('o.external_source');
                })
                ->whereNotIn('o.order_status', $excludedStatuses)
                ->where(function($q) {
                    $q->whereNull('p.attribute_1')
                      ->orWhereRaw("LOWER(p.attribute_1) != 'qurbani'");
                });
            
            // Apply status filter if provided
            if ($statusFilter) {
                $query->where('o.order_status', $statusFilter);
            }

            // ⭐ Prepared view: only prepared items, hide orders that have moved
            //    past preparation. excluded_statuses (cancelled/refunded/pending)
            //    is applied above; delivered/completed/out_for_delivery are NOT in
            //    that list, so exclude them explicitly here (mirrors the tree
            //    endpoint so the standalone and split views stay consistent).
            if ($preparedOnly) {
                $query->where('li.preparation_status', 'preparing')
                      ->whereNotIn('o.order_status', $statusRules->outTheDoor());
            } else {
                // ⭐ Aligned Aug-2026 (mirrors the tree endpoint): the default view must
                //    EXCLUDE line items already marked 'preparing'. Without this, and with
                //    delivered/completed absent from excluded_statuses, this fallback
                //    counted every fulfilled order in the 20-day window — numbers ~30x
                //    the tree's for the same level.
                $query->where(function($q) {
                    $q->whereNull('li.preparation_status')
                      ->orWhere('li.preparation_status', '!=', 'preparing');
                });
            }

            // Default: Only show orders from last 20 days for performance
            $query->where('o.order_date', '>=', \Carbon\Carbon::now()->subDays(20));
            
            // Apply parent filters - but only filter on fields where we have product data
            \Log::debug('Open Quantities Mobile - Filters:', [
                'level' => $level,
                'current_field' => $hierarchy[$level] ?? 'unknown',
                'filters' => $filters
            ]);
            
            foreach ($filters as $field => $value) {
                if ($field === 'product_name') {
                    $query->where('li.name', $value);
                } elseif ($field === 'product_ids') {
                    // CSV or array
                    if (is_string($value)) {
                        $ids = array_filter(array_map('intval', explode(',', $value)));
                    } else {
                        $ids = array_map('intval', (array)$value);
                    }
                    if (!empty($ids)) {
                        $query->where(function($q) use ($ids) {
                            $q->whereIn('li.product_id', $ids)
                              ->orWhereIn('p.id', $ids);
                        });
                    }
                } elseif ($field === 'product_id') {
                    // Keep consistency between product level and orders level filtering
                    $query->where(function($q) use ($value) {
                        $q->where('li.product_id', $value)
                          ->orWhere('p.id', $value);
                    });
                } elseif ($field === 'product_type') {
                    $query->where(function($q) use ($value) {
                        if ($value === 'Uncategorized') {
                            $q->whereNull('p.product_type')->orWhere('p.product_type', '');
                        } else {
                            $q->where('p.product_type', $value);
                        }
                    });
                } elseif (in_array($field, ['attribute_1', 'attribute_2', 'attribute_3'])) {
                    $query->where(function($q) use ($field, $value) {
                        if ($value === 'Uncategorized') {
                            $q->whereNull('p.' . $field)->orWhere('p.' . $field, '');
                        } else {
                            $q->where('p.' . $field, $value);
                        }
                    });
                } else {
                    // Fallback for any other field (same as web app)
                    $query->where('p.' . $field, $value);
                }
            }
            
            \Log::debug('Open Quantities Mobile - Query SQL:', [
                'sql' => $query->toSql(),
                'bindings' => $query->getBindings()
            ]);
            
            // Determine grouping based on level (use hierarchy from settings)
            $currentField = $hierarchy[$level] ?? 'product_name';
            
            if ($currentField === 'orders') {
                // Orders level - show individual orders
                $results = $query->select([
                    'o.id as order_id',
                    'o.order_number',
                    DB::raw("CONCAT('Order #', o.order_number, ' - ', COALESCE(o.name, CONCAT(o.address_first_name, ' ', o.address_last_name))) as name"),
                    'o.order_status as status',
                    DB::raw('SUM(li.quantity) as quantity'),
                    DB::raw('SUM(li.quantity * COALESCE(p.unit_weight_kg, 1)) as weight'),
                    DB::raw('SUM(CASE WHEN p.is_lean = 1 THEN li.quantity ELSE 0 END) as lean_quantity'),
                    DB::raw('SUM(CASE WHEN p.is_lean = 0 THEN li.quantity ELSE 0 END) as non_lean_quantity'),
                    DB::raw('SUM(CASE WHEN o.order_status = "processing" THEN li.quantity ELSE 0 END) as processing_quantity'),
                    DB::raw('SUM(CASE WHEN li.preparation_status = "preparing" THEN li.quantity ELSE 0 END) as prepared_quantity'),
                    DB::raw("GROUP_CONCAT(DISTINCT NULLIF(TRIM(li.instructions), '') SEPARATOR ' | ') as instructions")
                ])
                ->groupBy('o.id', 'o.order_number', 'o.name', 'o.address_first_name', 'o.address_last_name', 'o.order_status')
                ->orderBy('o.order_number', 'desc')
                ->get();
            } elseif ($currentField === 'product_name') {
                // Product level
                $results = $query->select([
                    'li.name as name',
                    DB::raw('GROUP_CONCAT(DISTINCT COALESCE(li.product_id, p.id)) as product_ids'),
                    // Internal p.id only — the list above is mixed (li.product_id is an
                    // EXTERNAL id on synced orders) and must not be used to look up stock.
                    DB::raw('GROUP_CONCAT(DISTINCT p.id) as internal_product_ids'),
                    DB::raw('SUM(li.quantity) as quantity'),
                    DB::raw('SUM(li.quantity * COALESCE(p.unit_weight_kg, 1)) as weight'),
                    DB::raw('SUM(CASE WHEN p.is_lean = 1 THEN li.quantity ELSE 0 END) as lean_quantity'),
                    DB::raw('SUM(CASE WHEN p.is_lean = 0 THEN li.quantity ELSE 0 END) as non_lean_quantity'),
                    DB::raw('SUM(CASE WHEN o.order_status = "processing" THEN li.quantity ELSE 0 END) as processing_quantity'),
                    DB::raw('SUM(CASE WHEN li.preparation_status = "preparing" THEN li.quantity ELSE 0 END) as prepared_quantity'),
                    DB::raw('COUNT(DISTINCT o.id) as order_count'),
                    DB::raw("CASE WHEN COUNT(DISTINCT NULLIF(TRIM(li.instructions), '')) > 0 THEN 1 ELSE 0 END as has_instructions")
                ])
                ->groupBy('li.name')
                ->orderBy('quantity', 'desc')
                ->get();
            } else {
                // Category level
                $results = $query->select([
                    DB::raw("COALESCE(p.{$currentField}, 'Uncategorized') as name"),
                    DB::raw('SUM(li.quantity) as quantity'),
                    DB::raw('SUM(li.quantity * COALESCE(p.unit_weight_kg, 1)) as weight'),
                    DB::raw('SUM(CASE WHEN p.is_lean = 1 THEN li.quantity ELSE 0 END) as lean_quantity'),
                    DB::raw('SUM(CASE WHEN p.is_lean = 0 THEN li.quantity ELSE 0 END) as non_lean_quantity'),
                    DB::raw('SUM(CASE WHEN o.order_status = "processing" THEN li.quantity ELSE 0 END) as processing_quantity'),
                    DB::raw('SUM(CASE WHEN li.preparation_status = "preparing" THEN li.quantity ELSE 0 END) as prepared_quantity'),
                    DB::raw('COUNT(DISTINCT o.id) as order_count'),
                    DB::raw('COUNT(DISTINCT li.product_id) as product_count')
                ])
                ->groupBy(DB::raw("COALESCE(p.{$currentField}, 'Uncategorized')"))
                ->orderBy('quantity', 'desc')
                ->get();
                
                // Apply priority-based sorting for attribute levels
                if (in_array($currentField, ['attribute_1', 'attribute_2', 'attribute_3'])) {
                    $attributeKey = (int)str_replace('attribute_', '', $currentField);
                    $priorityMap = $this->getAttributePriorityMap($attributeKey);
                    
                    if (!empty($priorityMap)) {
                        $results = $results->sort(function($a, $b) use ($priorityMap) {
                            $nameA = $a->name ?? '';
                            $nameB = $b->name ?? '';
                            
                            // Get priorities (higher number = higher priority = show first)
                            $priorityA = $priorityMap[$nameA] ?? 0;
                            $priorityB = $priorityMap[$nameB] ?? 0;
                            
                            // Sort descending by priority (higher priority first)
                            if ($priorityA != $priorityB) {
                                return $priorityB - $priorityA;
                            }
                            
                            // If same priority, sort by quantity
                            return ($b->quantity ?? 0) - ($a->quantity ?? 0);
                        })->values(); // Reset keys
                    }
                }
            }
            
            \Log::debug('Open Quantities Mobile - Results:', [
                'count' => $results->count(),
                'first_item' => $results->first()
            ]);
            
            // Chiller/freezer stock for this fallback path, matching the tree:
            // category rows are matched on their attribute path (no product-id list
            // needed, so no GROUP_CONCAT truncation risk), product rows on exact ids.
            $stockService = app(\App\Services\CRM\OvernightStockService::class);
            $isCategoryLevel = in_array($currentField, \App\Services\CRM\OvernightStockService::CATEGORY_FIELDS, true);
            $stockMap = $currentField === 'product_name' ? $stockService->map() : [];
            // Full catalog regardless of level: the scope ids + breakdown sheet need it
            // even at the orders level, where no row carries a storage figure of its own.
            $stockCatalog = $stockService->catalog();

            // Format for mobile - keep it simple and light
            $formattedResults = $results->map(function($item) use ($currentField, $stockService, $stockMap, $stockCatalog, $isCategoryLevel, $filters) {
                $result = [
                    'name' => $item->name ?? 'Uncategorized',
                    'quantity' => (float) ($item->quantity ?? 0),
                    // ⭐ Read-only kg figure (qty * product unit_weight_kg). Must stay in this
                    //    whitelist or it never reaches the app — same as the tree's node keys.
                    'weight' => round((float) ($item->weight ?? 0), 2),
                    'lean_quantity' => (float) ($item->lean_quantity ?? 0),
                    'non_lean_quantity' => (float) ($item->non_lean_quantity ?? 0),
                    'processing_quantity' => (float) ($item->processing_quantity ?? 0),
                    'prepared_quantity' => (float) ($item->prepared_quantity ?? 0),
                ];
                
                // Add order-specific fields
                if ($currentField === 'orders') {
                    $result['order_id'] = $item->order_id ?? null;
                    $result['order_number'] = $item->order_number ?? null;
                    $result['status'] = $item->status ?? 'new';
                    if (!empty($item->instructions)) {
                        $result['instructions'] = $item->instructions;
                    }
                } else {
                    $result['order_count'] = (int) ($item->order_count ?? 0);
                    $result['product_count'] = isset($item->product_count) ? (int) $item->product_count : null;

                    if ($isCategoryLevel) {
                        // Own value + the ancestor filters = this row's full attribute path.
                        $rowFilters = array_merge($filters, [$currentField => $item->name ?? '']);
                        $storage = $stockService->sumForCategory($stockCatalog, $rowFilters);
                        if ($storage !== null) {
                            $result['storage'] = $storage;
                            $result['storage_ids'] = $stockService->matchCategoryIds($stockCatalog, $rowFilters) ?? [];
                        }
                    }
                    if ($currentField === 'product_name') {
                        $result['product_id'] = $item->product_id ?? null;
                        if (!empty($item->has_instructions)) {
                            $result['has_instructions'] = true;
                        }
                        $ids = $stockService->idsFromConcat($item->internal_product_ids ?? null);
                        $storage = $stockService->sumFor($stockMap, $ids);
                        if ($storage !== null) {
                            $result['storage'] = $storage;
                            $result['storage_ids'] = $stockService->stockedIds($stockMap, $ids);
                        }
                    }
                }
                
                return $result;
            });
            
            return response()->json([
                'success' => true,
                'level' => $level,
                'field' => $currentField,
                'items' => $formattedResults,
                'total_count' => $formattedResults->count(),
                'settings' => [
                    'hierarchy' => $hierarchy,
                    'excluded_statuses' => $excludedStatuses
                ],
                // Same three keys the tree endpoint sends — see the notes there.
                'storage_catalog' => $stockService->catalogRows(),
                'storage_scope_ids' => $stockService->matchCategoryIds($stockCatalog, $filters)
                    ?? array_map('intval', array_keys($stockCatalog)),
                'storage_total' => $stockService->grandTotal(),
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to fetch open order quantities', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to fetch quantities: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Bulk update line item preparation status
     * POST /api/rider/orders/{orderId}/line-items/bulk-update-status
     */
    public function bulkUpdateLineItemStatus(Request $request, $orderId)
    {
        try {
            $user = Auth::user();
            
            // Validate request
            $request->validate([
                'line_item_ids' => 'required|array',
                'line_item_ids.*' => 'required|integer',
                'preparation_status' => 'nullable|in:preparing',
            ]);
            
            $lineItemIds = $request->input('line_item_ids');
            $preparationStatus = $request->input('preparation_status');
            
            // If preparation_status is empty string or null, set to null
            if (empty($preparationStatus)) {
                $preparationStatus = null;
            }
            
            // Check if user has permission to update orders
            if (!$user->hasMobilePermission('view_open_orders') && !$user->hasMobilePermission('mark_order_delivered')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to update line items'
                ], 403);
            }
            
            // Only allow updates for regular orders (not Shopify)
            $order = \App\Models\CRM\OrderModel::with('lineItems')->find($orderId);
            
            if (!$order) {
                return response()->json([
                    'success' => false,
                    'message' => 'Order not found or not eligible for preparation status updates'
                ], 404);
            }
            
            // Check if order is open (not delivered/completed/cancelled)
            $closedStatuses = ['delivered', 'completed', 'cancelled', 'refunded'];
            if (in_array($order->order_status, $closedStatuses)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Cannot update preparation status for closed orders'
                ], 400);
            }
            
            // Update line items + handle inventory deduction/restoration
            $updated = 0;
            $inventoryDeducted = 0;
            $inventoryRestored = 0;
            foreach ($lineItemIds as $lineItemId) {
                $lineItem = $order->lineItems->where('id', $lineItemId)->first();
                if ($lineItem) {
                    $oldStatus = $lineItem->preparation_status;
                    $lineItem->preparation_status = $preparationStatus;
                    $lineItem->updated_by = $user->id;
                    $lineItem->save();
                    $updated++;

                    // ⭐ INVENTORY: Deduct when marking as prepared
                    if ($preparationStatus === 'preparing' && $oldStatus !== 'preparing') {
                        if ($lineItem->deductInventory()) {
                            $inventoryDeducted++;
                        }
                    }
                    // ⭐ INVENTORY: Restore when un-marking as prepared
                    elseif ($preparationStatus === null && $oldStatus === 'preparing') {
                        if ($lineItem->restoreInventory()) {
                            $inventoryRestored++;
                        }
                    }
                }
            }
            
            // Get updated counts (refresh from DB)
            $order->load('lineItems');
            $totalItems = $order->lineItems->count();
            $preparingCount = $order->lineItems->where('preparation_status', 'preparing')->count();
            
            return response()->json([
                'success' => true,
                'message' => "Updated {$updated} line item(s)",
                'updated_count' => $updated,
                'preparing_count' => $preparingCount,
                'total_items' => $totalItems,
                'inventory_deducted' => $inventoryDeducted,
                'inventory_restored' => $inventoryRestored,
            ]);
            
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors' => $e->errors()
            ], 422);
        } catch (\Exception $e) {
            \Log::error('Failed to bulk update line item status', [
                'order_id' => $orderId,
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to update line items: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Get expense management data for mobile
     * Includes: expenses, pending approvals, KPIs, top categories
     */
    public function getExpenses(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view expenses'
                ], 403);
            }
            
            // Get filter parameters
            $month = $request->input('month'); // Format: YYYY-MM
            $category = $request->input('category');
            $settlementStatus = $request->input('settlement_status');
            $paymentSourceFilter = $request->input('payment_source'); // New filter: account_id or 'all'
            $businessUnitId = $request->input('business_unit_id'); // ⭐ Filter by business unit (for Khaas mode)
            // May-2026 (Phase 2/3) — Qurbani requests are silo'd into
            // a dedicated screen inside Qurbani mode. The flag below
            // toggles which side of the silo this endpoint serves:
            //   qurbani=1 → only Qurbani requests (powers the new
            //               mobile QurbaniExpensesScreen)
            //   qurbani=0 (default) → everything EXCEPT Qurbani
            //               (the regular Expense screen).
            // Default of "exclude" matches the web behaviour and
            // keeps existing mobile callers (no flag) showing
            // regular spend.
            $qurbaniMode = filter_var($request->input('qurbani', false), FILTER_VALIDATE_BOOLEAN);
            
            // ⭐ Check if user can see ALL payment sources (EXP_FUND, NF_CASH, ONLINE)
            // Without this permission, user only sees EXP_FUND expenses
            // In Khaas mode: also grant this if user has approve_khaas_transfer (admin)
            $hasAllPaymentSourcesPermission = $user->hasMobilePermission('expense_all_payment_sources')
                || ($businessUnitId && $user->hasMobilePermission('approve_khaas_transfer'));
            
            \Log::debug('Expense filter params received', [
                'month' => $month,
                'category' => $category,
                'settlement_status' => $settlementStatus,
                'payment_source' => $paymentSourceFilter,
                'has_all_sources_permission' => $hasAllPaymentSourcesPermission,
                'all_params' => $request->all()
            ]);
            
            // ⭐ Get EXP_FUND account ID for filtering
            $expenseFundAccount = \App\Models\FIN\ConfigModel::getExpenseFundingAccount() 
                ?? \App\Models\FIN\AccountModel::where('account_code', 'EXP_FUND')->first();
            $expenseFundAccountId = $expenseFundAccount ? $expenseFundAccount->id : null;
            
            // Dynamically get all expense-management category codes
            try {
                $expenseCategoryCodes = \App\Models\Request\RequestCategoryModel::where('show_in_expenses', 1)
                    ->where('is_active', 1)
                    ->pluck('category_code')
                    ->toArray();
            } catch (\Exception $e) {
                $expenseCategoryCodes = $businessUnitId ? ['expense', 'khaas_expense'] : ['expense', 'salary_advance'];
            }
            if (empty($expenseCategoryCodes)) {
                $expenseCategoryCodes = $businessUnitId ? ['expense', 'khaas_expense'] : ['expense', 'salary_advance'];
            }
            
            $expensesQuery = \App\Models\Request\RequestModel::whereHas('category', function($q) use ($expenseCategoryCodes, $qurbaniMode) {
                    $q->whereIn('category_code', $expenseCategoryCodes);
                    if ($qurbaniMode) {
                        $q->where('category_code', 'qurbani');
                    } else {
                        $q->where('category_code', '!=', 'qurbani');
                    }
                })
                ->whereNotNull('ledger_transaction_id')
                ->where('status', \App\Models\Request\RequestModel::STATUS_APPROVED)
                ->with(['requester', 'paymentSourceAccount', 'category', 'settledBy', 'settlementDestinationAccount']);
            
            // ⭐ Apply business unit filter (for Khaas mode)
            if ($businessUnitId) {
                $expensesQuery->where('business_unit_id', $businessUnitId);
            }
            
            // ⭐ Apply payment source filter — all users can VIEW all payment source expenses
            // Permission only controls which sources they can CREATE from (handled in getPaymentSources)
            if ($paymentSourceFilter && $paymentSourceFilter !== 'all') {
                $expensesQuery->where('payment_source_account_id', $paymentSourceFilter);
            }
            
            // Apply date filter — Qurbani mode uses year-scope, regular
            // mode uses month-scope. The Qurbani Expenses screen never
            // needs month granularity (it's an annual event), so we
            // honor a `year=YYYY` param when qurbaniMode is on and
            // ignore `month` in that case.
            $year = $request->input('year');
            if ($qurbaniMode && $year && preg_match('/^\d{4}$/', (string) $year)) {
                $dateFrom = $year . '-01-01';
                $dateTo   = $year . '-12-31';
                $expensesQuery->whereRaw('DATE(COALESCE(expense_date, created_at)) >= ?', [$dateFrom])
                              ->whereRaw('DATE(COALESCE(expense_date, created_at)) <= ?', [$dateTo]);
            } elseif ($qurbaniMode) {
                // Default Qurbani window = current calendar year.
                $dateFrom = date('Y') . '-01-01';
                $dateTo   = date('Y') . '-12-31';
                $expensesQuery->whereRaw('DATE(COALESCE(expense_date, created_at)) >= ?', [$dateFrom])
                              ->whereRaw('DATE(COALESCE(expense_date, created_at)) <= ?', [$dateTo]);
            } elseif ($month && preg_match('/^\d{4}-\d{2}$/', $month)) {
                $dateFrom = $month . '-01';
                $dateTo = date('Y-m-t', strtotime($dateFrom)); // Last day of month

                \Log::debug('Expense date filter applied', [
                    'month' => $month,
                    'date_from' => $dateFrom,
                    'date_to' => $dateTo
                ]);

                // ⭐ Filter by expense_date (falls back to created_at for old records)
                $expensesQuery->whereRaw('DATE(COALESCE(expense_date, created_at)) >= ?', [$dateFrom])
                              ->whereRaw('DATE(COALESCE(expense_date, created_at)) <= ?', [$dateTo]);
            } else if ($month) {
                \Log::warning('Invalid month format received', ['month' => $month]);
            }
            
            // Apply category filter
            if ($category) {
                if (strtolower($category) === 'salary') {
                    $expensesQuery->whereRaw('1 = 0'); // Exclude all (salary comes from slips)
                } else {
                    $expensesQuery->where(function($q) use ($category) {
                        $q->whereRaw('LOWER(expense_category) = ?', [strtolower($category)])
                          ->orWhere(function($q2) use ($category) {
                              if (strtolower($category) === 'salary advance') {
                                  $q2->whereNull('expense_category')
                                     ->orWhere('expense_category', '')
                                     ->whereHas('category', function($q3) {
                                         $q3->where('category_code', 'salary_advance');
                                     });
                              }
                          });
                    });
                }
            }
            
            // Apply settlement status filter
            if ($settlementStatus) {
                $expensesQuery->where('settlement_status', $settlementStatus);
            }
            
            $allExpenses = $expensesQuery->orderBy('created_at', 'desc')->get();
            
            // Debug: Log the dates of returned expenses
            \Log::debug('Expenses returned', [
                'count' => $allExpenses->count(),
                'month_filter' => $month,
                'date_range' => $allExpenses->count() > 0 ? [
                    'first' => $allExpenses->first()->created_at->format('Y-m-d'),
                    'last' => $allExpenses->last()->created_at->format('Y-m-d'),
                ] : 'no records',
                'all_dates' => $allExpenses->pluck('created_at')->map(fn($d) => $d->format('Y-m-d'))->toArray()
            ]);
            
            // Get salary slips
            $salarySlipsQuery = SalarySlipModel::with(['employee'])
                ->whereIn('slip_status', ['approved', 'paid'])
                ->whereNotNull('ledger_transaction_id');
            
            // Apply date filter to salary slips if month is provided.
            // (Qurbani mode skips salary slips entirely; the date is
            // still applied here for consistency in case the include
            // flag flips above.)
            if ($qurbaniMode) {
                $yr = $year && preg_match('/^\d{4}$/', (string) $year) ? (int) $year : (int) date('Y');
                $salarySlipsQuery->whereRaw('YEAR(created_at) = ?', [$yr]);
            } elseif ($month && preg_match('/^\d{4}-\d{2}$/', $month)) {
                $dateFrom = $month . '-01';
                $dateTo = date('Y-m-t', strtotime($dateFrom));
                $salarySlipsQuery->whereRaw('DATE(created_at) >= ?', [$dateFrom])
                                 ->whereRaw('DATE(created_at) <= ?', [$dateTo]);
            }
            
            // ⭐ FIX: Only include salary slips if:
            // 1. No category filter OR category is 'salary'
            // 2. AND no payment source filter OR filter is EXP_FUND
            // 3. AND no business unit filter (salary slips don't have BU concept)
            $includeSalarySlips = (!$category || strtolower($category) === 'salary');
            
            // ⭐ If user filters by a specific non-EXP_FUND source, exclude salary slips
            if ($paymentSourceFilter && $paymentSourceFilter !== 'all' && $paymentSourceFilter != $expenseFundAccountId) {
                $includeSalarySlips = false;
            }
            
            // ⭐ If filtering by business unit (Khaas mode), exclude salary slips
            // Salary slips don't belong to a business unit
            if ($businessUnitId) {
                $includeSalarySlips = false;
            }
            // May-2026 — Qurbani Expenses screen never wants salary
            // slips. The qurbani event has its own short-term staff
            // costed via the request-based qurbani sub-categories,
            // not via the regular salary slip pipeline.
            if ($qurbaniMode) {
                $includeSalarySlips = false;
            }
            
            $salarySlips = $includeSalarySlips ? $salarySlipsQuery->orderBy('created_at', 'desc')->get() : collect([]);
            $totalSalaryExpenses = $salarySlips->sum('net_salary');
            
            // Transform salary slips for display
            $salarySlipsForDisplay = $salarySlips->map(function($slip) {
                return [
                    'id' => 'SALARY-' . $slip->id,
                    'type' => 'salary',
                    'request_number' => $slip->slip_number ?? ('SLIP-' . $slip->id),
                    'date' => $slip->created_at->format('Y-m-d'),
                    'employee' => $slip->employee ? $slip->employee->fullname : 'Unknown',
                    'category' => 'Salary',
                    'amount' => $slip->net_salary,
                    'payment_source' => 'Expense Fund',
                    'settlement_status' => 'not_applicable',
                    'status' => $slip->slip_status
                ];
            });
            
            // Transform expenses for display
            $expensesForDisplay = $allExpenses->map(function($expense) {
                return [
                    'id' => $expense->id,
                    'type' => 'expense',
                    'request_number' => $expense->request_number,
                    'date' => ($expense->expense_date ?? $expense->created_at)->format('Y-m-d'),
                    'employee' => $expense->requester ? $expense->requester->fullname : 'Unknown',
                    'category' => $expense->expense_category ?? ($expense->category ? $expense->category->category_name : 'Uncategorized'),
                    'notes' => $expense->description,
                    'description' => $expense->description,
                    'request_type' => $expense->category ? $expense->category->category_name : 'Expense',
                    'request_type_code' => $expense->category ? $expense->category->category_code : 'expense',
                    'amount' => $expense->amount,
                    'payment_source' => $expense->paymentSourceAccount ? $expense->paymentSourceAccount->account_name : 'Unknown',
                    'settlement_status' => $expense->settlement_status,
                    'status' => $expense->status,
                    'settled_at' => $expense->settled_at ? $expense->settled_at->format('Y-m-d H:i') : null,
                    'settled_by' => $expense->settledBy ? $expense->settledBy->fullname : null
                ];
            });
            
            // Merge and sort
            $allExpensesForDisplay = $expensesForDisplay->concat($salarySlipsForDisplay)->sortByDesc('date')->values();
            
            // Calculate KPIs
            $totalExpenses = $allExpenses->sum('amount') + $totalSalaryExpenses;
            $needsSettlement = $allExpenses->filter(fn($exp) => $exp->settlement_status === 'pending')->sum('amount');
            $settled = $allExpenses->filter(fn($exp) => $exp->settlement_status === 'settled')->sum('amount');
            
            // ⭐ Calculate expenses breakdown by payment source
            $expensesBySource = [];
            
            // Group expenses by source account
            foreach ($allExpenses as $expense) {
                $sourceId = $expense->payment_source_account_id ?? 'exp_fund'; // Default to exp_fund for old records
                $sourceName = $expense->paymentSourceAccount ? $expense->paymentSourceAccount->account_name : 'Expense Fund';
                
                if (!isset($expensesBySource[$sourceId])) {
                    $expensesBySource[$sourceId] = [
                        'id' => $sourceId,
                        'name' => $sourceName,
                        'amount' => 0,
                        'count' => 0
                    ];
                }
                $expensesBySource[$sourceId]['amount'] += $expense->amount;
                $expensesBySource[$sourceId]['count']++;
            }
            
            // Add salary slips (always from Expense Fund / EXP_FUND)
            if ($totalSalaryExpenses > 0) {
                $expFundId = $expenseFundAccount ? $expenseFundAccount->id : 'exp_fund';
                $expFundName = $expenseFundAccount ? $expenseFundAccount->account_name : 'Expense Fund';
                
                if (!isset($expensesBySource[$expFundId])) {
                    $expensesBySource[$expFundId] = [
                        'id' => $expFundId,
                        'name' => $expFundName,
                        'amount' => 0,
                        'count' => 0
                    ];
                }
                $expensesBySource[$expFundId]['amount'] += $totalSalaryExpenses;
                $expensesBySource[$expFundId]['count'] += $salarySlips->count();
            }
            
            // Sort by amount descending and convert to array
            $expensesBySourceArray = array_values($expensesBySource);
            usort($expensesBySourceArray, fn($a, $b) => $b['amount'] <=> $a['amount']);
            
            // Get expense fund balance
            // ⭐ For non-NF BUs (Khaas etc): use the BU's configured default expense account
            // For NF main (BU 1) or no BU: use standard EXP_FUND
            if ($businessUnitId && (int) $businessUnitId !== 1) {
                $expenseFund = \App\Models\FIN\ConfigModel::getBuDefaultExpenseAccount((int) $businessUnitId);
            } else {
                $expenseFund = $expenseFundAccount;
            }
            
            // Get pending approvals (real-time, not filtered by month)
            $pendingApprovalsQuery = \App\Models\Request\RequestModel::whereHas('category', function($q) use ($expenseCategoryCodes, $qurbaniMode) {
                    $q->whereIn('category_code', $expenseCategoryCodes);
                    if ($qurbaniMode) {
                        $q->where('category_code', 'qurbani');
                    } else {
                        $q->where('category_code', '!=', 'qurbani');
                    }
                })
                ->where('status', \App\Models\Request\RequestModel::STATUS_PENDING)
                ->with(['requester', 'paymentSourceAccount', 'category', 'approvals.approver'])
                ->orderBy('created_at', 'asc');
            
            // ⭐ Filter pending approvals by business unit (for Khaas mode)
            if ($businessUnitId) {
                $pendingApprovalsQuery->where('business_unit_id', $businessUnitId);
            }
            
            $pendingApprovals = $pendingApprovalsQuery->get();
            
            // Transform pending approvals with level information
            $allPendingApprovals = $pendingApprovals->map(function($request) {
                // ⭐ Check approvals relationship for L1 status
                $l1Approval = $request->approvals->where('approval_level', 1)->where('status', 'approved')->first();
                $l2Approval = $request->approvals->where('approval_level', 2)->where('status', 'approved')->first();
                
                // Determine which level is pending
                $pendingLevel = 1; // Default to L1
                if ($l1Approval) {
                    $pendingLevel = 2; // L1 done, L2 pending
                }
                
                return [
                    'id' => $request->id,
                    'request_number' => $request->request_number,
                    'date' => $request->created_at->format('Y-m-d'),
                    'employee' => $request->requester ? $request->requester->fullname : 'Unknown',
                    'category' => $request->expense_category ?? ($request->category ? $request->category->category_name : 'Uncategorized'),
                    'notes' => $request->description,
                    'description' => $request->description,
                    'amount' => $request->amount,
                    'payment_source' => $request->paymentSourceAccount ? $request->paymentSourceAccount->account_name : 'Unknown',
                    'status' => $request->status,
                    'pending_level' => $pendingLevel, // ⭐ Which level needs approval
                    'l1_approved' => $l1Approval ? true : false,
                    'l1_approved_by_name' => $l1Approval && $l1Approval->approver ? $l1Approval->approver->fullname : null,
                ];
            });
            
            // ⭐ Separate L1 and L2 pending approvals
            $pendingL1 = $allPendingApprovals->where('pending_level', 1)->values();
            $pendingL2 = $allPendingApprovals->where('pending_level', 2)->values();
            
            // For backwards compatibility, keep the combined list
            $pendingApprovalsForDisplay = $allPendingApprovals;
            
            // Calculate expense categories with user breakdown (like web version)
            $expensesByCategory = [];
            $expensesByCategoryUser = []; // Track user-wise breakdown
            
            foreach ($allExpenses as $expense) {
                $cat = $expense->expense_category;
                if (empty($cat) && $expense->category && $expense->category->category_code === 'salary_advance') {
                    $cat = 'Salary Advance';
                } elseif (empty($cat)) {
                    $cat = 'Uncategorized';
                }
                
                // Category total
                if (!isset($expensesByCategory[$cat])) {
                    $expensesByCategory[$cat] = 0;
                }
                $expensesByCategory[$cat] += $expense->amount;
                
                // User breakdown within category
                $userName = $expense->requester ? $expense->requester->fullname : 'Unknown';
                if (!isset($expensesByCategoryUser[$cat])) {
                    $expensesByCategoryUser[$cat] = [];
                }
                if (!isset($expensesByCategoryUser[$cat][$userName])) {
                    $expensesByCategoryUser[$cat][$userName] = 0;
                }
                $expensesByCategoryUser[$cat][$userName] += $expense->amount;
            }
            
            // Add salary slips to category totals with user breakdown
            if ($totalSalaryExpenses > 0) {
                if (!isset($expensesByCategory['Salary'])) {
                    $expensesByCategory['Salary'] = 0;
                }
                $expensesByCategory['Salary'] += $totalSalaryExpenses;
                
                // Track salary by employee
                if (!isset($expensesByCategoryUser['Salary'])) {
                    $expensesByCategoryUser['Salary'] = [];
                }
                foreach ($salarySlips as $slip) {
                    $empName = $slip->employee ? $slip->employee->fullname : 'Unknown';
                    if (!isset($expensesByCategoryUser['Salary'][$empName])) {
                        $expensesByCategoryUser['Salary'][$empName] = 0;
                    }
                    $expensesByCategoryUser['Salary'][$empName] += $slip->net_salary;
                }
            }
            
            // Sort categories by amount descending
            arsort($expensesByCategory);
            
            // Build top categories with user breakdown (return all like web, up to 15)
            $topCategories = [];
            $othersTotal = 0;
            $othersUsers = [];
            $count = 0;
            
            foreach ($expensesByCategory as $cat => $amount) {
                if ($count < 15 && $cat !== 'Uncategorized') {
                    // Sort users within category by amount descending
                    $usersInCategory = $expensesByCategoryUser[$cat] ?? [];
                    arsort($usersInCategory);
                    
                    $topCategories[$cat] = [
                        'total' => $amount,
                        'users' => $usersInCategory
                    ];
                    $count++;
                } else {
                    $othersTotal += $amount;
                    // Merge users from other categories
                    foreach (($expensesByCategoryUser[$cat] ?? []) as $userName => $userAmount) {
                        if (!isset($othersUsers[$userName])) {
                            $othersUsers[$userName] = 0;
                        }
                        $othersUsers[$userName] += $userAmount;
                    }
                }
            }
            
            if ($othersTotal > 0) {
                arsort($othersUsers);
                $topCategories['Other Expenses'] = [
                    'total' => $othersTotal,
                    'users' => $othersUsers
                ];
            }

            // ── Phase 4 (mobile): NF vs Khaas split for the top
            // categories card. Only populated when the request did
            // NOT pin a specific business_unit_id (i.e. user is on
            // the regular NF expense screen, not deep-linked Khaas
            // mode). Mirrors the web payload at $kpis['bu_breakdown'].
            $buBreakdown = null;
            if (!$businessUnitId && !$qurbaniMode) {
                $nfBuId = (int) (\App\Models\FIN\BusinessUnitModel::where('code', 'NF')->value('id') ?? 0);
                $khaasBuId = (int) (\App\Models\FIN\BusinessUnitModel::where('code', 'KHAAS')->value('id') ?? 0);
                $userPerms = method_exists($user, 'getMobilePermissions') ? $user->getMobilePermissions() : [];
                $canViewKhaas = in_array('access_khaas_mode', $userPerms, true);

                $buBreakdown = [
                    'NF'    => ['total' => 0.0, 'categories' => []],
                    'KHAAS' => ['total' => 0.0, 'categories' => []],
                ];
                $buUserMap = ['NF' => [], 'KHAAS' => []];
                foreach ($allExpenses as $exp) {
                    $bu = ($khaasBuId && (int) ($exp->business_unit_id ?? 0) === $khaasBuId) ? 'KHAAS' : 'NF';
                    if ($bu === 'KHAAS' && !$canViewKhaas) continue;
                    $cat = $exp->expense_category;
                    if (empty($cat) && $exp->category && $exp->category->category_code === 'salary_advance') {
                        $cat = 'Salary Advance';
                    } elseif (empty($cat)) {
                        $cat = 'Uncategorized';
                    }
                    $buBreakdown[$bu]['total'] += (float) $exp->amount;
                    if (!isset($buBreakdown[$bu]['categories'][$cat])) {
                        $buBreakdown[$bu]['categories'][$cat] = 0.0;
                    }
                    $buBreakdown[$bu]['categories'][$cat] += (float) $exp->amount;
                    $userName = $exp->requester ? $exp->requester->fullname : 'Unknown';
                    if (!isset($buUserMap[$bu][$cat])) $buUserMap[$bu][$cat] = [];
                    if (!isset($buUserMap[$bu][$cat][$userName])) $buUserMap[$bu][$cat][$userName] = 0.0;
                    $buUserMap[$bu][$cat][$userName] += (float) $exp->amount;
                }
                if ($totalSalaryExpenses > 0) {
                    $buBreakdown['NF']['total'] += (float) $totalSalaryExpenses;
                    if (!isset($buBreakdown['NF']['categories']['Salary'])) {
                        $buBreakdown['NF']['categories']['Salary'] = 0.0;
                    }
                    $buBreakdown['NF']['categories']['Salary'] += (float) $totalSalaryExpenses;
                    if (!isset($buUserMap['NF']['Salary'])) $buUserMap['NF']['Salary'] = [];
                    foreach ($salarySlips as $slip) {
                        $empName = $slip->employee ? $slip->employee->fullname : 'Unknown';
                        if (!isset($buUserMap['NF']['Salary'][$empName])) $buUserMap['NF']['Salary'][$empName] = 0.0;
                        $buUserMap['NF']['Salary'][$empName] += (float) $slip->net_salary;
                    }
                }
                foreach ($buBreakdown as $bc => &$payload) {
                    arsort($payload['categories']);
                    $shaped = [];
                    foreach ($payload['categories'] as $cName => $cTotal) {
                        $usersInCat = $buUserMap[$bc][$cName] ?? [];
                        arsort($usersInCat);
                        $shaped[$cName] = ['total' => $cTotal, 'users' => $usersInCat];
                    }
                    $payload['categories'] = $shaped;
                }
                unset($payload);
                if (!$canViewKhaas) {
                    unset($buBreakdown['KHAAS']);
                }
            }

            // Get all unique categories for filter
            // ⭐ Use same category codes as for the main expenses query (includes khaas_expense for Khaas mode)
            $categoriesFilterQuery = \App\Models\Request\RequestModel::whereHas('category', function($q) use ($expenseCategoryCodes, $qurbaniMode) {
                    $q->whereIn('category_code', $expenseCategoryCodes);
                    if ($qurbaniMode) {
                        $q->where('category_code', 'qurbani');
                    } else {
                        $q->where('category_code', '!=', 'qurbani');
                    }
                })
                ->whereNotNull('ledger_transaction_id')
                ->where('status', \App\Models\Request\RequestModel::STATUS_APPROVED)
                ->whereNotNull('expense_category')
                ->where('expense_category', '!=', '');
            
            // ⭐ Filter categories by business unit (for Khaas mode)
            if ($businessUnitId) {
                $categoriesFilterQuery->where('business_unit_id', $businessUnitId);
            }
            
            $categoriesFromExpenses = $categoriesFilterQuery->distinct()->pluck('expense_category');
            
            // ⭐ In Khaas mode: don't add Salary/Salary Advance to categories filter
            if ($businessUnitId) {
                $categories = $categoriesFromExpenses->unique()->sort()->values();
            } else {
                $categories = $categoriesFromExpenses
                    ->merge(['Salary', 'Salary Advance'])
                    ->unique()
                    ->sort()
                    ->values();
            }
            
            // ⭐ Check user's approval rights
            $hasL1Rights = \App\Models\SysAdmin\RoleApprovalLevelModel::userHasApprovalLevel($user->id, 1);
            $hasL2Rights = \App\Models\SysAdmin\RoleApprovalLevelModel::userHasApprovalLevel($user->id, 2);
            
            // ⭐ Get available payment sources for filter dropdown — all users can see all sources for filtering
            $availablePaymentSources = [];
            
            if ($businessUnitId) {
                // BU-specific mode: show ALL accounts for this BU (excluding employee/vendor)
                $buAccounts = \App\Models\FIN\AccountModel::where('is_active', 1)
                    ->where('business_unit_id', $businessUnitId)
                    ->where('is_private', 0)
                    ->whereNotIn('account_category', [
                        \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH,
                        \App\Models\FIN\AccountModel::CATEGORY_VENDOR_PAYABLE,
                    ])
                    ->get();
                foreach ($buAccounts as $account) {
                    $availablePaymentSources[] = [
                        'id' => $account->id,
                        'code' => $account->account_code,
                        'name' => $account->account_name,
                        'balance' => $account->current_balance
                    ];
                }
            } else {
                // NF mode: always show all company payment sources for filtering
                $nfCashAccount = \App\Models\FIN\ConfigModel::getNFCashAccount();
                $onlineAccount = \App\Models\FIN\ConfigModel::getOnlineBankAccount();
                
                // Check Taimur role for private account visibility
                $isTaimurRole = $user->roles()->whereRaw('LOWER(urole_name) = ?', ['taimur'])->exists();
                
                if ($expenseFund) {
                    $availablePaymentSources[] = [
                        'id' => $expenseFund->id,
                        'code' => $expenseFund->account_code,
                        'name' => $expenseFund->account_name,
                        'balance' => $expenseFund->current_balance
                    ];
                }
                if ($nfCashAccount && !$nfCashAccount->is_private) {
                    $availablePaymentSources[] = [
                        'id' => $nfCashAccount->id,
                        'code' => $nfCashAccount->account_code,
                        'name' => $nfCashAccount->account_name,
                        'balance' => $nfCashAccount->current_balance
                    ];
                }
                if ($onlineAccount && !$onlineAccount->is_private) {
                    $availablePaymentSources[] = [
                        'id' => $onlineAccount->id,
                        'code' => $onlineAccount->account_code,
                        'name' => $onlineAccount->account_name,
                        'balance' => $onlineAccount->current_balance
                    ];
                }
                
                // Add NF Food accounts
                $nfFoodAccounts = \App\Models\FIN\AccountModel::where('is_active', 1)
                    ->where('account_code', 'LIKE', 'NF_FOOD%')
                    ->where('is_private', 0)
                    ->get();
                foreach ($nfFoodAccounts as $nfFoodAccount) {
                    $availablePaymentSources[] = [
                        'id' => $nfFoodAccount->id,
                        'code' => $nfFoodAccount->account_code,
                        'name' => $nfFoodAccount->account_name,
                        'balance' => $nfFoodAccount->current_balance
                    ];
                }
                
                // Include private accounts only for Taimur
                if ($isTaimurRole) {
                    $privateAccounts = \App\Models\FIN\AccountModel::where('is_active', 1)
                        ->where('is_private', 1)
                        ->whereIn('account_category', [
                            \App\Models\FIN\AccountModel::CATEGORY_CASH,
                            \App\Models\FIN\AccountModel::CATEGORY_BANK,
                        ])
                        ->get();
                    foreach ($privateAccounts as $pa) {
                        $availablePaymentSources[] = [
                            'id' => $pa->id,
                            'code' => $pa->account_code,
                            'name' => $pa->account_name,
                            'balance' => $pa->current_balance
                        ];
                    }
                }
            }
            
            return response()->json([
                'success' => true,
                'data' => [
                    'expenses' => $allExpensesForDisplay,
                    'pending_approvals' => $pendingApprovalsForDisplay,
                    // ⭐ Separated L1/L2 pending approvals for tabbed view
                    'pending_l1' => $pendingL1,
                    'pending_l2' => $pendingL2,
                    'kpis' => [
                        'total_expenses' => $totalExpenses,
                        'needs_settlement' => $needsSettlement,
                        'settled' => $settled,
                        'fund_balance' => $expenseFund ? $expenseFund->current_balance : 0,
                        'pending_approvals' => $pendingApprovals->sum('amount'),
                        'pending_approvals_count' => $pendingApprovals->count(),
                        // ⭐ Separate L1/L2 counts and amounts
                        'pending_l1_count' => $pendingL1->count(),
                        'pending_l1_amount' => $pendingL1->sum('amount'),
                        'pending_l2_count' => $pendingL2->count(),
                        'pending_l2_amount' => $pendingL2->sum('amount'),
                        'top_categories' => $topCategories,
                        // Phase 4 — NF vs Khaas split (null when caller
                        // already pinned a business_unit_id, e.g. Khaas
                        // mode, or when on the Qurbani tab).
                        'bu_breakdown' => $buBreakdown,
                        // ⭐ Expenses breakdown by source
                        'expenses_by_source' => $expensesBySourceArray
                    ],
                    // ⭐ User's approval rights
                    'user_approval_rights' => [
                        'has_l1' => $hasL1Rights,
                        'has_l2' => $hasL2Rights,
                    ],
                    // ⭐ Payment source permission and available sources
                    'has_all_payment_sources_permission' => $hasAllPaymentSourcesPermission,
                    'available_payment_sources' => $availablePaymentSources,
                    'categories' => $categories,
                    'current_month' => $month ?: now()->format('Y-m'),
                    // ⭐ BU default expense account info (for admin to configure)
                    'default_expense_account_id' => $expenseFund ? $expenseFund->id : null,
                    'default_expense_account_name' => $expenseFund ? $expenseFund->account_name : null,
                ]
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get expenses', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load expenses: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Get fund transfers into the expense fund account
     * Shows transfers from NF Cash or Online into EXP_FUND
     */
    public function getFundTransfers(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view fund transfers'
                ], 403);
            }
            
            // Get month parameter (YYYY-MM format)
            $month = $request->input('month', now()->format('Y-m'));
            $businessUnitId = $request->input('business_unit_id');
            
            // ⭐ For non-NF BUs (Khaas etc): use the BU's configured default account
            // For NF main (BU 1) or no BU: use standard EXP_FUND
            if ($businessUnitId && (int) $businessUnitId !== 1) {
                $expenseFund = \App\Models\FIN\ConfigModel::getBuDefaultExpenseAccount((int) $businessUnitId);
            } else {
                $expenseFund = \App\Models\FIN\ConfigModel::getExpenseFundingAccount() 
                    ?? \App\Models\FIN\AccountModel::where('account_code', 'EXP_FUND')->first();
            }
            
            if (!$expenseFund) {
                return response()->json([
                    'success' => false,
                    'message' => 'Expense fund account not found'
                ], 404);
            }
            
            // Calculate date range for the month
            $startDate = $month . '-01';
            $endDate = \Carbon\Carbon::parse($startDate)->endOfMonth()->toDateString();
            
            // Get transfers INTO the expense fund
            $transfers = \App\Models\FIN\LedgerModel::with(['fromAccount', 'toAccount', 'createdBy'])
                ->where('to_account_id', $expenseFund->id)
                ->where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_TRANSFER)
                ->whereBetween('transaction_date', [$startDate, $endDate])
                ->orderByDesc('transaction_date')
                ->orderByDesc('id')
                ->get();
            
            // Format transfers for response
            $formattedTransfers = $transfers->map(function($transfer) {
                return [
                    'id' => $transfer->id,
                    'transaction_date' => $transfer->transaction_date->format('Y-m-d'),
                    'amount' => (float) $transfer->amount,
                    'from_account' => $transfer->fromAccount ? $transfer->fromAccount->account_name : 'Unknown',
                    'from_account_code' => $transfer->fromAccount ? $transfer->fromAccount->account_code : null,
                    'description' => $transfer->description,
                    'mode' => $transfer->mode,
                    'created_by' => $transfer->createdBy ? $transfer->createdBy->fullname : 'System',
                    'created_at' => $transfer->created_at->format('Y-m-d H:i'),
                ];
            });
            
            // Calculate totals
            $totalAmount = $transfers->sum('amount');
            
            return response()->json([
                'success' => true,
                'transfers' => $formattedTransfers,
                'summary' => [
                    'total_transfers' => $transfers->count(),
                    'total_amount' => (float) $totalAmount,
                    'fund_balance' => (float) $expenseFund->current_balance,
                ],
                'month' => $month,
                'month_display' => \Carbon\Carbon::parse($startDate)->format('F Y'),
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get fund transfers', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load fund transfers: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * GET /rider/expenses/account-activity
     *
     * The last N movements — IN **and** OUT — of the expense account the Expenses screen is
     * showing a balance for, with date, time and who moved it.
     *
     * Why this exists: getFundTransfers() above is deliberately narrow — it answers "how much
     * was ADDED to the fund this month" (to_account only, transaction_type = 'transfer',
     * current month). For the Frozen fund account that returns 2 rows, while the account
     * actually has hundreds of movements, almost all of them vendor_payment OUTflows. So the
     * balance changed constantly and nothing on screen explained why.
     *
     * getFundTransfers is left untouched (old APKs keep working, and "money added this month"
     * is still a useful view in its own right) — this is a separate, additive endpoint.
     */
    public function getAccountActivity(Request $request)
    {
        try {
            $user = Auth::user();

            // Same gate as the screen this feeds.
            if (!$user->hasMobilePermission('view_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view expenses'
                ], 403);
            }

            $businessUnitId = $request->input('business_unit_id');
            $limit = (int) $request->input('limit', 10);
            $limit = max(1, min(50, $limit));

            // Resolve the SAME account getFundTransfers resolves, so the list always explains
            // the balance shown on the card next to it.
            if ($businessUnitId && (int) $businessUnitId !== 1) {
                $account = \App\Models\FIN\ConfigModel::getBuDefaultExpenseAccount((int) $businessUnitId);
            } else {
                $account = \App\Models\FIN\ConfigModel::getExpenseFundingAccount()
                    ?? \App\Models\FIN\AccountModel::where('account_code', 'EXP_FUND')->first();
            }

            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Expense account not found'
                ], 404);
            }

            // One shared implementation with the web Frozen Operations tab, so the two views
            // can never disagree about what counts as a movement.
            $payload = (new \App\Services\FIN\AccountActivityService())->recent($account, $limit);

            return response()->json(['success' => true] + $payload);

        } catch (\Exception $e) {
            \Log::error('Failed to get account activity', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);

            return response()->json([
                'success' => false,
                'message' => 'Failed to load account activity'
            ], 500);
        }
    }

    /**
     * Get available payment sources for expense creation
     * Returns sources based on user's Business Unit access and expense_all_payment_sources permission
     * - Without permission: Only EXP_FUND
     * - With permission: All company accounts (cash, bank) filtered by user's BU access
     *
     * ⭐ Aug-2026: the ~130 lines of rules that used to live here now live in
     * PaymentSourceService, unchanged — the JSON this returns is byte-identical.
     * They moved because the Bikes screens (web + mobile) needed the same list
     * and could not call this endpoint (it is gated on `view_expenses`, which a
     * Bikes-only user need not hold). Any rule change belongs in the service, so
     * every picker keeps agreeing with what the submit endpoints enforce.
     */
    public function getPaymentSources(Request $request)
    {
        try {
            $user = Auth::user();
            $businessUnitId = $request->input('business_unit_id');

            // Check permission to view expenses
            if (!$user->hasMobilePermission('view_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view expenses'
                ], 403);
            }

            $svc = app(\App\Services\FIN\PaymentSourceService::class);

            $hasAllPaymentSourcesPermission = $svc->canUseAllSources($user, $businessUnitId ? (int) $businessUnitId : null);
            $paymentSources    = $svc->sourcesFor($user, $businessUnitId ? (int) $businessUnitId : null);
            $receivingAccounts = $svc->banks();

            \Log::info('Payment sources returned', [
                'user_id' => Auth::id(),
                'count' => count($paymentSources),
                'has_all_permission' => $hasAllPaymentSourcesPermission,
                'business_unit_id' => $businessUnitId,
            ]);

            return response()->json([
                'success' => true,
                'payment_sources' => $paymentSources,
                'receiving_accounts' => $receivingAccounts,
                'has_all_payment_sources_permission' => $hasAllPaymentSourcesPermission
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get payment sources', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load payment sources: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Set the default expense account for a business unit.
     * Only accessible to users with expense_all_payment_sources permission.
     */
    public function setBuDefaultExpenseAccount(Request $request)
    {
        try {
            $user = Auth::user();
            
            if (!$user->hasMobilePermission('expense_all_payment_sources') && 
                !$user->hasMobilePermission('approve_khaas_transfer')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to change this setting'
                ], 403);
            }
            
            $request->validate([
                'business_unit_id' => 'required|integer',
                'account_id' => 'required|integer',
            ]);
            
            $businessUnitId = (int) $request->input('business_unit_id');
            $accountId = (int) $request->input('account_id');
            
            // Verify the account exists, is active, and belongs to this BU
            $account = \App\Models\FIN\AccountModel::where('id', $accountId)
                ->where('business_unit_id', $businessUnitId)
                ->where('is_active', 1)
                ->first();
            
            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Account not found or does not belong to this business unit'
                ], 400);
            }
            
            \App\Models\FIN\ConfigModel::setBuDefaultExpenseAccount($businessUnitId, $accountId);
            
            return response()->json([
                'success' => true,
                'message' => "Default expense account set to: {$account->account_name}",
                'account' => [
                    'id' => $account->id,
                    'name' => $account->account_name,
                    'code' => $account->account_code,
                    'balance' => (float) $account->current_balance,
                ]
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to set BU default expense account', [
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to save setting: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Approve a pending expense request
     */
    public function approveExpense(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('approve_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to approve expenses'
                ], 403);
            }
            
            $expenseRequest = \App\Models\Request\RequestModel::with('approvals')->findOrFail($id);
            
            // ⭐ Determine which level is NEEDED for this request by checking approvals
            $l1Approval = $expenseRequest->approvals->where('approval_level', 1)->where('status', 'approved')->first();
            $pendingLevel = 1;
            if ($l1Approval) {
                $pendingLevel = 2; // L1 done, needs L2
            }
            
            // Check if user has the required approval level
            if (!\App\Models\SysAdmin\RoleApprovalLevelModel::userHasApprovalLevel($user->id, $pendingLevel)) {
                return response()->json([
                    'success' => false,
                    'message' => "This request requires Level {$pendingLevel} approval, which you don't have"
                ], 403);
            }
            
            // Use the existing approval controller logic
            $approvalController = new \App\Http\Controllers\Request\RequestApprovalController();
            $approvalRequest = new Request([
                'level' => $pendingLevel, // ⭐ Use the level the request needs
                'comments' => $request->input('notes', ''),
                'payment_source_account_id' => $request->input('payment_source_account_id', null)
            ]);
            
            $response = $approvalController->approve($approvalRequest, $id);
            $responseData = $response->getData(true);
            
            return response()->json($responseData, $response->status());
            
        } catch (\Exception $e) {
            \Log::error('Failed to approve expense', [
                'expense_id' => $id,
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to approve expense: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * Reject a pending expense request
     */
    public function rejectExpense(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('approve_expenses')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to reject expenses'
                ], 403);
            }
            
            $expenseRequest = \App\Models\Request\RequestModel::with('approvals')->findOrFail($id);
            
            // Determine which level is pending by checking approvals
            $l1Approval = $expenseRequest->approvals->where('approval_level', 1)->where('status', 'approved')->first();
            $pendingLevel = 1;
            if ($l1Approval) {
                $pendingLevel = 2;
            }
            
            // Check if user has the required approval level
            if (!\App\Models\SysAdmin\RoleApprovalLevelModel::userHasApprovalLevel($user->id, $pendingLevel)) {
                return response()->json([
                    'success' => false,
                    'message' => "This request requires Level {$pendingLevel} rights to reject, which you don't have"
                ], 403);
            }
            
            $notes = $request->input('notes', '');
            if (empty($notes)) {
                return response()->json([
                    'success' => false,
                    'message' => 'Please provide a reason for rejection'
                ], 400);
            }
            
            // Use the existing approval controller logic
            $approvalController = new \App\Http\Controllers\Request\RequestApprovalController();
            $rejectRequest = new Request([
                'level' => $pendingLevel,
                'comments' => $notes,
            ]);
            
            $response = $approvalController->reject($rejectRequest, $id);
            $responseData = $response->getData(true);
            
            return response()->json($responseData, $response->status());
            
        } catch (\Exception $e) {
            \Log::error('Failed to reject expense', [
                'expense_id' => $id,
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to reject expense: ' . $e->getMessage()
            ], 500);
        }
    }

