    /**
     * Delete an approved expense (L2 only)
     * Reverses ledger entry and account balances
     */
    public function deleteExpense(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            \Log::info('Delete expense attempt', [
                'expense_id' => $id,
                'user_id' => $user->id,
                'user_name' => $user->fullname
            ]);
            
            // ⭐ Check if user has L2 approval rights (required for delete)
            $hasL2Rights = \App\Models\SysAdmin\RoleApprovalLevelModel::userHasApprovalLevel($user->id, 2);
            
            \Log::info('L2 rights check', [
                'user_id' => $user->id,
                'has_l2_rights' => $hasL2Rights
            ]);
            
            if (!$hasL2Rights) {
                return response()->json([
                    'success' => false,
                    'message' => 'Only Level 2 approvers can delete expenses'
                ], 403);
            }
            
            $expenseRequest = \App\Models\Request\RequestModel::with(['paymentSourceAccount', 'category'])
                ->findOrFail($id);

            // ⛔ SALARY ADVANCES ARE NOT DELETABLE HERE (mirrors the web guard in
            // FIN\ExpenseManagementController::destroy). This endpoint is category-blind and
            // blindly reverses `settlement_transaction_id`, which on a payroll-settled advance
            // points at the WHOLE MONTH'S salary_payment row — deleting one advance would
            // un-post an entire salary. Advances are voided from the web Payroll page only.
            if ($expenseRequest->category && $expenseRequest->category->category_code === 'salary_advance') {
                return response()->json([
                    'success' => false,
                    'message' => 'Salary advances cannot be deleted here — void it from the Payroll page on the web app.'
                ], 403);
            }

            // Check if expense is approved
            if ($expenseRequest->status !== 'approved') {
                return response()->json([
                    'success' => false,
                    'message' => 'Only approved expenses can be deleted'
                ], 400);
            }
            
            $notes = $request->input('notes', '');
            
            \DB::beginTransaction();
            
            // ⭐ If expense has ledger entry, reverse it
            if ($expenseRequest->ledger_transaction_id) {
                $ledger = \App\Models\FIN\LedgerModel::find($expenseRequest->ledger_transaction_id);
                
                if ($ledger && $ledger->approval_status === \App\Models\FIN\LedgerModel::STATUS_APPROVED) {
                    // Reverse balances via the canonical engine (funding +, expense −); self-guards on
                    // balance_updated and clears it — fixing the old bug where a reversed row kept
                    // flag=1. REQUIRES the expense flag backfill for legacy rows applied with flag=0.
                    (new \App\Services\FIN\BalancePostingService())->reverse($ledger);

                    // Mark ledger entry as reversed (using valid status)
                    $ledger->approval_status = \App\Models\FIN\LedgerModel::STATUS_REVERSED;
                    $ledger->comments = ($ledger->comments ? $ledger->comments . "\n" : '') . 
                        "DELETED by {$user->fullname} on " . now()->format('Y-m-d H:i:s') . 
                        ($notes ? " - Reason: {$notes}" : '');
                    $ledger->save();
                }
            }
            
            // ⭐ If expense has settlement transaction, reverse it too
            if ($expenseRequest->settlement_transaction_id) {
                $settlementLedger = \App\Models\FIN\LedgerModel::find($expenseRequest->settlement_transaction_id);
                
                if ($settlementLedger && $settlementLedger->approval_status === \App\Models\FIN\LedgerModel::STATUS_APPROVED) {
                    // Reverse settlement balances via the canonical engine (EXP_FUND +, till −);
                    // self-guards on balance_updated and clears it.
                    (new \App\Services\FIN\BalancePostingService())->reverse($settlementLedger);

                    $settlementLedger->approval_status = \App\Models\FIN\LedgerModel::STATUS_REVERSED;
                    $settlementLedger->comments = ($settlementLedger->comments ? $settlementLedger->comments . "\n" : '') . 
                        "DELETED (settlement reversal) by {$user->fullname} on " . now()->format('Y-m-d H:i:s');
                    $settlementLedger->save();
                    
                    \Log::info("Reversed settlement transaction", [
                        'settlement_ledger_id' => $settlementLedger->id,
                        'amount' => $settlementLedger->amount
                    ]);
                }
            }
            
            // Mark request as deleted/cancelled
            $expenseRequest->status = 'cancelled';
            $expenseRequest->rejection_reason = "DELETED by {$user->fullname} on " . now()->format('Y-m-d H:i:s') . 
                ($notes ? " - Reason: {$notes}" : '');
            $expenseRequest->updated_by = $user->id;
            $expenseRequest->save();
            
            \DB::commit();

            // ⭐ Storage (Supplies): deleting a take-out's expense puts the packet back
            // in Storage, so the stock and the money stay in step. After the commit and
            // non-fatal — the delete itself has already succeeded.
            if ($expenseRequest->supply_takeout_id) {
                try {
                    app(\App\Services\FIN\SupplyStockService::class)->syncWithRequest($expenseRequest);
                } catch (\Throwable $e) {
                    \Log::error('Storage take-out restore failed after expense delete (mobile)', [
                        'request_id' => $expenseRequest->id,
                        'error' => $e->getMessage(),
                    ]);
                }
            }

            \Log::info('Expense deleted successfully', [
                'expense_id' => $id,
                'request_number' => $expenseRequest->request_number,
                'amount' => $expenseRequest->amount,
                'deleted_by' => $user->id,
                'ledger_reversed' => $expenseRequest->ledger_transaction_id ? true : false,
                'settlement_reversed' => $expenseRequest->settlement_transaction_id ? true : false
            ]);
            
            return response()->json([
                'success' => true,
                'message' => "Expense #{$expenseRequest->request_number} deleted successfully. Ledger entries reversed."
            ]);
            
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Failed to delete expense', [
                'expense_id' => $id,
                'user_id' => Auth::id(),
                'error' => $e->getMessage()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to delete expense: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * Get priority map for attribute categories
     * Reads rules from attribute_auto_rules.json and creates a map of category name => priority
     * If multiple rules have the same category, uses the HIGHEST priority
     */
    private function getAttributePriorityMap(int $attributeKey): array
    {
        try {
            $filePath = storage_path('app/private/attribute_auto_rules.json');
            
            if (!file_exists($filePath)) {
                return [];
            }
            
            $json = file_get_contents($filePath);
            $allRules = json_decode($json, true) ?: [];
            $rules = $allRules[(string)$attributeKey] ?? [];
            
            $priorityMap = [];
            foreach ($rules as $rule) {
                $group = trim((string)($rule['group'] ?? ''));
                $priority = (int)($rule['priority'] ?? 0);
                
                if ($group !== '') {
                    // Keep the HIGHEST priority for each category
                    if (!isset($priorityMap[$group]) || $priority > $priorityMap[$group]) {
                        $priorityMap[$group] = $priority;
                    }
                }
            }
            
            return $priorityMap;
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to read attribute priority map: ' . $e->getMessage());
            return [];
        }
    }

    /**
     * NF LEDGER - Get all accounts with balances (for mobile)
     * Shows both company accounts and employee accounts
     */
    /**
     * GET /rider/nf-ledger/tips — what the tip pool holds and who may spend it.
     *
     * Tips ride inside the invoice, so the invoice books them as revenue; the
     * pool holds them until they are handed over. This powers the payout sheet
     * on the NF Ledger screen. Reading is open to anyone who can see the NF
     * Ledger; SPENDING is gated below, server-side, because hiding a button is
     * not a permission check.
     */
    public function getTipsFund(Request $request, \App\Services\FIN\TipsFundService $tips)
    {
        $user = Auth::user();

        if (!$user->hasMobilePermission('view_nf_ledger')) {
            return response()->json([
                'success' => false,
                'message' => 'You do not have permission to view NF Ledger',
            ], 403);
        }

        if (!$tips->ready()) {
            return response()->json([
                'success' => true,
                'ready'   => false,
                'message' => 'The Tips Fund is not set up yet.',
            ]);
        }

        $canPay = app(\App\Services\CustomerCreditService::class)->userCanAutoApproveGrant($user);

        // Only real money can pay a tip out — the pool itself, vendor payables
        // and expense accounts are never options.
        $accounts = \App\Models\FIN\AccountModel::where('is_active', 1)
            ->whereIn('account_category', [
                \App\Models\FIN\AccountModel::CATEGORY_CASH,
                \App\Models\FIN\AccountModel::CATEGORY_BANK,
                \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH,
            ])
            ->visibleTo($user)
            ->orderBy('account_category')->orderBy('account_name')
            ->get(['id', 'account_name', 'account_code', 'account_category']);

        return response()->json([
            'success'  => true,
            'ready'    => true,
            'summary'  => $tips->summary(),
            'can_pay'  => $canPay,
            'accounts' => $accounts,
            'banks'    => \DB::table('t_fin_online_receiving_accounts')
                ->where('is_active', 1)->orderBy('name')->get(['id', 'name']),
        ]);
    }

    /**
     * POST /rider/nf-ledger/tips/payout — hand tip money over.
     *
     * Same service, same validation and the same refusals as the web Ledger Hub,
     * so the two clients can never disagree about what a payout is.
     */
    public function payTipsOut(Request $request, \App\Services\FIN\TipsFundService $tips)
    {
        $user = Auth::user();

        if (!app(\App\Services\CustomerCreditService::class)->userCanAutoApproveGrant($user)) {
            return response()->json([
                'success' => false,
                'message' => 'Paying tips out needs Shabib or Taimur.',
            ], 403);
        }

        $data = $request->validate([
            'amount'               => 'required|numeric|min:1',
            'from_account_id'      => 'required|integer',
            'receiving_account_id' => 'nullable|integer',
            'reason'               => 'required|string|max:255',
            'given_to'             => 'nullable|string|max:120',
            'date'                 => 'nullable|date',
        ]);

        try {
            $row = $tips->payout($data, (int) $user->id);
        } catch (\Throwable $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 422);
        }

        return response()->json([
            'success' => true,
            'message' => 'Rs ' . number_format((float) $row->amount, 2) . ' paid out of the tip pool.',
            'balance' => $tips->balance(),
        ]);
    }

    public function getNFLedgerAccounts(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_nf_ledger')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view NF Ledger'
                ], 403);
            }
            
            $businessUnitId = $request->input('business_unit_id');
            $isNonNfBU = $businessUnitId && (int) $businessUnitId !== 1;
            
            // For non-NF BU (Khaas), check if user is admin or limited
            $isKhaasAdmin = false;
            if ($isNonNfBU) {
                $isKhaasAdmin = $user->hasMobilePermission('expense_all_payment_sources')
                    || $user->hasMobilePermission('approve_khaas_transfer');
            }
            
            // Build query for active accounts — filter private accounts for non-Taimur
            $query = \App\Models\FIN\AccountModel::where('is_active', 1)
                ->visibleTo($user);
            
            if ($isNonNfBU) {
                // Khaas mode: only company accounts (cash/bank) for this BU
                $query->where('business_unit_id', (int) $businessUnitId);
                $query->whereIn('account_category', [
                    \App\Models\FIN\AccountModel::CATEGORY_CASH,
                    \App\Models\FIN\AccountModel::CATEGORY_BANK,
                ]);
                
                // Limited users: only the configured default account
                if (!$isKhaasAdmin) {
                    $defaultBuAccount = \App\Models\FIN\ConfigModel::getBuDefaultExpenseAccount((int) $businessUnitId);
                    if ($defaultBuAccount) {
                        $query->where('id', $defaultBuAccount->id);
                    }
                }
            } else {
                // Standard NF mode: show company + employee accounts, plus the
                // Tips Fund (Sep-2026).
                //
                // ⚠⚠ The Tips Fund is NOT cash or bank on purpose — that is what
                // keeps it out of every pool, the payment-source picker and the
                // employee-cash formulas. It is named EXPLICITLY here because
                // this screen is one of the two places it SHOULD be readable.
                $query->where(function($q) {
                    $q->where('account_category', \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH)
                      ->orWhereIn('account_category', [
                          \App\Models\FIN\AccountModel::CATEGORY_CASH,
                          \App\Models\FIN\AccountModel::CATEGORY_BANK,
                          \App\Models\FIN\AccountModel::CATEGORY_TIPS_FUND,
                      ]);
                });
            }
            
            // Load user relationship for employee accounts
            $query->with('user');
            
            // Search filter
            if ($request->has('search') && $request->search) {
                $search = $request->search;
                $query->where('account_name', 'LIKE', "%{$search}%");
            }
            
            // Order: Company accounts first, then employee accounts (alphabetically)
            $accounts = $query
                ->orderByRaw("CASE
                    WHEN account_category IN ('cash', 'bank') THEN 1
                    WHEN account_category = 'employee_cash' THEN 2
                    WHEN account_category = 'tips_fund' THEN 3
                    ELSE 4
                END")
                ->orderBy('account_name', 'asc')
                ->get();
            
            // Calculate pending actions for each account
            foreach ($accounts as $account) {
                $pendingActions = 0;
                
                // For employee accounts: count pending expense requests
                if ($account->user_id) {
                    $pendingActions = \App\Models\Request\RequestModel::where('requester_user_id', $account->user_id)
                        ->where('status', 'pending')
                        ->whereHas('category', function($q) {
                            $q->where('category_code', 'expense');
                        })
                        ->sum('amount');
                }
                // For company accounts: count pending requests to be paid from this account
                else {
                    $query = \App\Models\Request\RequestModel::where('status', 'pending')
                        ->whereHas('category', function($q) {
                            $q->where('category_code', 'expense');
                        });
                    
                    // If this is the Expense Fund, include requests with NULL payment source
                    if ($account->account_code === 'EXP_FUND') {
                        $query->where(function($q) use ($account) {
                            $q->where('payment_source_account_id', $account->id)
                              ->orWhereNull('payment_source_account_id');
                        });
                    } else {
                        $query->where('payment_source_account_id', $account->id);
                    }
                    
                    $pendingActions = $query->sum('amount');
                }
                
                $account->pending_actions = $pendingActions ?? 0;
            }
            
            // Separate into company and employee accounts
            $companyAccounts = [];
            $employeeAccounts = [];
            $fundAccounts = [];   // held for staff (tips) — not spendable company cash
            
            foreach ($accounts as $account) {
                // Use effective balance: calculated for employee_cash, stored for others
                $effectiveBalance = $account->getEffectiveBalance();
                
                $accountData = [
                    'id' => $account->id,
                    'account_code' => $account->account_code,
                    'account_name' => $account->account_name,
                    'account_category' => $account->account_category,
                    'current_balance' => $effectiveBalance,
                    'pending_actions' => $account->pending_actions,
                    'user_id' => $account->user_id,
                    'user_name' => $account->user ? ($account->user->fullname ?? $account->user->name) : null,
                ];
                
                if ($account->account_category === \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH) {
                    $employeeAccounts[] = $accountData;
                } elseif ($account->account_category === \App\Models\FIN\AccountModel::CATEGORY_TIPS_FUND) {
                    // ⚠ Its OWN group, never inside company accounts. The tip pool
                    // is money we are HOLDING, not money we can spend, and the
                    // cash behind it is already counted in the tills and banks.
                    // Listing it beside them would invite double-counting.
                    $fundAccounts[] = $accountData;
                } else {
                    $companyAccounts[] = $accountData;
                }
            }

            return response()->json([
                'success' => true,
                'company_accounts' => $companyAccounts,
                'employee_accounts' => $employeeAccounts,
                // New in Sep-2026. An APK that predates it simply does not render
                // the section — no crash, and nothing misfiled into company cash.
                'fund_accounts' => $fundAccounts,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to get NF Ledger accounts: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to load accounts: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE ATTENDANCE - Get daily attendance for all employees
     * Reuses web app attendance logic
     */
    public function getStoreAttendanceDaily(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_store_attendance')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view store attendance'
                ], 403);
            }
            
            $selectedDate = $request->input('date', now()->toDateString());
            
            // Build subquery for leave requests
            $leaveSub = DB::table('t_req_master as r')
                ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                ->where('c.category_code', '=', 'leave')
                ->select(
                    'r.id',
                    'r.requester_user_id',
                    'r.status',
                    'r.leave_type',
                    'r.leave_start_date',
                    'r.leave_end_date'
                );
            
            // Get attendance data for all visible users
            $query = DB::table('t_sys_user as u')
                ->leftJoin('t_ops_attendance as a', function($join) use ($selectedDate) {
                    $join->on('u.id', '=', 'a.user_id')
                         ->whereDate('a.attendance_date', '=', $selectedDate);
                })
                ->leftJoin('t_ops_rider_profile as rp', 'rp.user_id', '=', 'u.id')
                ->leftJoin('t_sys_user_role as ur', 'ur.user_id', '=', 'u.id')
                ->leftJoin('t_sys_role as r', 'r.id', '=', 'ur.role_id')
                ->leftJoin('t_ops_attendance_visibility as av', 'av.user_id', '=', 'u.id')
                ->leftJoinSub($leaveSub, 'lr', function($join) use ($selectedDate) {
                    $join->on('lr.requester_user_id', '=', 'u.id')
                        ->whereIn('lr.status', ['approved', 'pending'])
                        ->whereRaw('? BETWEEN lr.leave_start_date AND lr.leave_end_date', [$selectedDate]);
                })
                ->select(
                    'u.id as user_id',
                    'u.fullname',
                    'u.is_active',
                    'r.urole_name as role_name',
                    'a.id as attendance_id',
                    'a.attendance_date',
                    'a.login_time',
                    'a.logout_time',
                    'a.notes',
                    'a.picture_start',
                    'a.picture_end',
                    'a.meter_start',
                    'a.meter_end',
                    'a.checkin_latitude',
                    'a.checkin_longitude',
                    'a.checkin_distance_from_base',
                    'a.is_remote_checkin',
                    'a.checkout_latitude',
                    'a.checkout_longitude',
                    // The FROZEN shift snapshot. Needed so this board judges lateness with the
                    // same inputs as every other screen (ShiftResolutionService::lateForDay);
                    // without them it silently fell back to today's roster shift.
                    'a.late_minutes',
                    'a.expected_shift_start',
                    // Blocked-checkout capture (latest attempt) — feeds the bypass sheet context
                    'a.checkout_attempt_at',
                    'a.checkout_attempt_lat',
                    'a.checkout_attempt_lng',
                    'a.checkout_attempt_reason',
                    'a.checkout_attempt_distance_m',
                    'a.checkout_attempt_limit_m',
                    'a.checkout_attempt_age_min',
                    'a.checkout_attempt_drop_lat',
                    'a.checkout_attempt_drop_lng',
                    'a.checkout_attempt_drop_label',
                    'a.checkout_attempt_count',
                    // ⭐ Road distance columns (auto-calculated on checkout)
                    'a.road_distance_km',
                    'a.road_distance_source',
                    'a.gps_straight_distance_km',
                    'a.gps_readings_used',
                    // U5 timeline anchors — feed the shared DayChecksService GPS phase analyzer
                    'a.meter_start_recorded_at',
                    'a.home_meter_recorded_at',
                    'a.meter_start_source',
                    DB::raw('COALESCE(rp.shift_start, "09:00") as legacy_shift_start'),
                    DB::raw('COALESCE(rp.shift_end, "17:00") as legacy_shift_end'),
                    'lr.id as leave_request_id',
                    'lr.status as leave_status',
                    'lr.leave_type as leave_type_from_req',
                    DB::raw('COALESCE(av.is_visible, 1) as is_attendance_visible')
                )
                ->where(function($q) {
                    $q->whereNull('av.is_visible')
                      ->orWhere('av.is_visible', 1);
                })
                ->where('u.is_active', 1)
                ->orderBy('u.fullname')
                ->limit(100);

            // ⭐ GPS-accuracy hardening columns — same guarded set the web page selects, so the
            // phone and the web keep showing identical day checks. Only once the SQL is applied.
            if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'meter_start_gps')) {
                $query->addSelect([
                    'a.meter_start_gps',
                    'a.meter_start_lat',
                    'a.meter_start_lng',
                    'a.meter_start_accuracy_m',
                    'a.meter_start_distance_m',
                    'a.meter_start_office_m',
                    'a.checkout_attempt_accuracy_m',
                ]);
            }
            // ⭐ The reading stamps — so a two-machine day on the manager's PHONE reads the same
            //   as on the web (no 67,874 km, no "meter vs GPS off by 67,804"). Schema-guarded.
            if (\App\Services\Riders\VehicleService::stampsAvailable()) {
                $query->addSelect(['a.meter_start_vehicle_id', 'a.meter_end_vehicle_id']);
            }
            $query = $query->get();

            // ⭐ Machine labels for every stamped row, in ONE query (the per-row helper would
            //   otherwise look them up once per rider). Empty map = labels resolve to null and
            //   the phone falls back to its own wording — never an error.
            $storeMpLabels = [];
            try {
                $storeMpVids = [];
                foreach ($query as $r) {
                    foreach ([$r->meter_start_vehicle_id ?? null, $r->meter_end_vehicle_id ?? null] as $v) {
                        if ($v) { $storeMpVids[(int) $v] = true; }
                    }
                }
                if ($storeMpVids) {
                    $storeMpLabels = \App\Services\Riders\MeterPairHelper::labels(array_keys($storeMpVids));
                }
            } catch (\Throwable $e) { $storeMpLabels = []; }

            // Resolve shifts using ShiftResolutionService
            $shiftService = new \App\Services\ShiftResolutionService();
            $formattedData = [];

            // Main-office id: the app shows a rider's 📍 location pin only when it's
            // NOT the main office — the common case stays quiet, a pin means "elsewhere".
            $primaryLocationId = (int) (DB::table('t_ops_company_locations')
                ->where('is_primary', 1)->where('is_active', 1)->value('id') ?? 0);
            $checkoutClassifier = new \App\Services\Riders\CheckoutClassifierService();
            // Freshness window for the blocked-checkout attempt (read once, not per row).
            $stuckMins = (int) (DB::table('t_fin_config')->where('config_key', 'CHECKOUT_STUCK_ALERT_MINS')->value('config_value') ?? 25);

            // Rider-bypass state per user (home-meter valve + checkout unlock) — the same maps the
            // web attendance page shows; drives the mobile 🔓 bypass sheet. Guarded + additive.
            $hjByUser = []; $cuByUser = [];
            try {
                $uids = $query->pluck('user_id')->filter()->values()->all();
                if (!empty($uids) && \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_expected_by')) {
                    $hjSvc = new \App\Services\Riders\HomeJourneyService();
                    $hasBreach = \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_bypass_breach');
                    $hasRecAt  = \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_meter_recorded_at');
                    $hjCols = ['id', 'user_id', 'logout_time', 'home_expected_by', 'home_eta_min', 'home_arrived_at', 'home_arrival_source',
                               'home_distance_km', 'meter_home', 'home_meter_unlock_until', 'home_meter_unlock_by', 'home_late_reason'];
                    if ($hasBreach) { $hjCols[] = 'home_bypass_breach'; }
                    if ($hasRecAt)  { $hjCols[] = 'home_meter_recorded_at'; }
                    foreach (DB::table('t_ops_attendance')->whereIn('user_id', $uids)
                        ->whereDate('attendance_date', $selectedDate)->whereNotNull('home_expected_by')->get($hjCols) as $hr) {
                        $hjByUser[$hr->user_id] = [
                            'attendance_id' => (int) $hr->id,
                            'state'         => $hjSvc->deriveState($hr),
                            // Full expected_by kept alongside the HH:MM label so the page can show
                            // the ETA line ("due 19:03") and still compute against it.
                            'expected_by'   => $hr->home_expected_by ? substr((string) $hr->home_expected_by, 11, 5) : null,
                            'eta_min'       => $hr->home_eta_min !== null ? (int) $hr->home_eta_min : null,
                            'distance_km'   => $hr->home_distance_km !== null ? (float) $hr->home_distance_km : null,
                            'arrived_at'    => $hr->home_arrived_at ? substr((string) $hr->home_arrived_at, 11, 5) : null,
                            'arrival_source'=> $hr->home_arrival_source,
                            'recorded_at'   => ($hasRecAt && $hr->home_meter_recorded_at) ? substr((string) $hr->home_meter_recorded_at, 11, 5) : null,
                            'minutes_late'  => $hjSvc->minutesLate($hr),
                            'has_meter'     => $hr->meter_home !== null && $hr->meter_home !== '',
                            'meter_home'    => $hr->meter_home !== null ? (int) $hr->meter_home : null,
                            'breach'        => $hasBreach ? ($hr->home_bypass_breach ?? null) : null,
                            'reason'        => $hr->home_late_reason,
                        ];
                    }
                }
                if (!empty($uids) && \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'checkout_unlock_until')) {
                    $uRows = DB::table('t_ops_attendance')->whereIn('user_id', $uids)
                        ->whereDate('attendance_date', $selectedDate)->whereNotNull('checkout_unlock_until')
                        ->get(['user_id', 'logout_time', 'checkout_unlock_until', 'checkout_unlock_by', 'checkout_unlock_reason']);
                    if ($uRows->isNotEmpty()) {
                        $unames = DB::table('t_sys_user')->whereIn('id', array_filter($uRows->pluck('checkout_unlock_by')->all()))
                            ->pluck('fullname', 'id');
                        foreach ($uRows as $u2) {
                            $cuByUser[$u2->user_id] = [
                                'active'  => strtotime((string) $u2->checkout_unlock_until) >= time(),
                                'until'   => substr((string) $u2->checkout_unlock_until, 11, 5),
                                // Raw timestamp — the tight "did the checkout actually RIDE the
                                // unlock" test needs it (feeds the counted-checkout chip below).
                                'until_raw' => (string) $u2->checkout_unlock_until,
                                'used'    => !empty($u2->logout_time),
                                'reason'  => $u2->checkout_unlock_reason,
                                'by_name' => $u2->checkout_unlock_by ? ($unames[$u2->checkout_unlock_by] ?? 'manager') : null,
                            ];
                        }
                    }
                }
            } catch (\Throwable $e) { /* bypass info is additive — the screen must still load */ }

            // ── U5 morning-start journey per rider (store-mode mirror of the web payload):
            //    START-line data + check-in-unlock state for the mobile bypass sheet. Guarded.
            //    $bikeUidSet ALSO feeds is_company_bike on every row — the bypass sheet must
            //    offer "Unlock check-in" for a bike rider with NO attendance row at all (the
            //    skipped-home-start lock case has nothing else to hang the section on).
            $wjByUser = [];
            $bikeUidSet = [];
            // Riders exempted from the meter in Rider Management ("Meter reading is compulsory"
            // unticked) — the ⛽ tick must skip them on the phone exactly as it does on the web.
            $meterExemptSet = [];
            try {
                $exUids = $uids ?? $query->pluck('user_id')->filter()->values()->all();
                if (!empty($exUids) && \Illuminate\Support\Facades\Schema::hasColumn('t_ops_rider_profile', 'meter_required')) {
                    $meterExemptSet = array_flip(DB::table('t_ops_rider_profile')->whereIn('user_id', $exUids)
                        ->where('meter_required', 0)->pluck('user_id')->all());
                }
                // ⭐ PHASE D: the registry exempts too — a rider with no machine on the
                //   sheet's date was not asked, so the phone must not flag him either.
                //   Mirrors the web sheet exactly; silent while rules are off.
                $vresEx = new \App\Services\Riders\VehicleResolver();
                if (!empty($exUids) && $vresEx->rulesEnabled() && $vresEx->available()) {
                    $heldOnDate = $vresEx->machineHoldersOn($selectedDate);
                    foreach (DB::table('t_ops_rider_profile')->whereIn('user_id', $exUids)
                        ->pluck('user_id') as $xu) {
                        if (!isset($heldOnDate[(int) $xu])) { $meterExemptSet[(int) $xu] = true; }
                    }
                }
            } catch (\Throwable $e) { /* no column → nobody exempt */ }
            try {
                $uids = $uids ?? $query->pluck('user_id')->filter()->values()->all();
                if (!empty($uids) && \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'work_expected_by')) {
                    $wjSvc = new \App\Services\Riders\WorkJourneyService();
                    // ⭐ Phase C: company-machine cohort for the day being listed.
                    $wjCompanySet = array_flip(
                        (new \App\Services\Riders\VehicleResolver())->companyRiderIdsFor($selectedDate)
                    );
                    $bikeUids = DB::table('t_ops_rider_profile')->whereIn('user_id', $uids)
                        ->whereNotNull('home_latitude')->pluck('user_id')
                        ->filter(fn ($uid) => isset($wjCompanySet[(int) $uid]))
                        ->values()->all();
                    $bikeUidSet = array_flip($bikeUids);
                    if (!empty($bikeUids)) {
                        $wCols = ['id', 'user_id', 'attendance_date', 'login_time', 'meter_start', 'meter_start_source',
                                  'meter_start_recorded_at', 'work_expected_by', 'work_eta_min', 'work_distance_km',
                                  'checkin_unlock_until', 'checkin_unlock_by', 'checkin_unlock_reason'];
                        // Measured start-meter location — same guarded set the web page reads, so
                        // the phone and the web describe the morning identically.
                        if (\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'meter_start_gps')) {
                            array_push($wCols, 'meter_start_gps', 'meter_start_distance_m', 'meter_start_office_m', 'meter_start_accuracy_m');
                        }
                        $wRows = DB::table('t_ops_attendance')->whereIn('user_id', $bikeUids)
                            ->whereDate('attendance_date', $selectedDate)
                            ->get($wCols);
                        $wNames = DB::table('t_sys_user')->whereIn('id', array_filter($wRows->pluck('checkin_unlock_by')->all()))
                            ->pluck('fullname', 'id');
                        foreach ($wRows as $wr) {
                            $wState = $wjSvc->deriveState($wr);
                            if ($wState === 'none' && empty($wr->meter_start_recorded_at) && empty($wr->checkin_unlock_until)) {
                                continue;
                            }
                            $wjByUser[$wr->user_id] = [
                                'attendance_id' => (int) $wr->id,
                                'state'         => $wState,
                                'expected_by'   => $wr->work_expected_by ? substr((string) $wr->work_expected_by, 11, 5) : null,
                                'eta_min'       => $wr->work_eta_min !== null ? (int) $wr->work_eta_min : null,
                                'distance_km'   => $wr->work_distance_km !== null ? (float) $wr->work_distance_km : null,
                                'recorded_at'   => $wr->meter_start_recorded_at ? substr((string) $wr->meter_start_recorded_at, 11, 5) : null,
                                'source'        => $wr->meter_start_source,
                                // WHERE it was recorded, as a measurement (null on pre-hardening rows).
                                'place'         => \App\Services\Riders\WorkJourneyService::startPlace($wr),
                                'minutes_late'  => $wjSvc->minutesLate($wr),
                                'continuity'    => $wjSvc->continuity($wr),
                                'checkin_unlock'=> [
                                    'active'  => $wjSvc->checkinUnlockActive($wr),
                                    'until'   => $wr->checkin_unlock_until ? substr((string) $wr->checkin_unlock_until, 11, 5) : null,
                                    'by_name' => $wr->checkin_unlock_by ? ($wNames[$wr->checkin_unlock_by] ?? 'manager') : null,
                                    'reason'  => $wr->checkin_unlock_reason,
                                ],
                            ];
                        }
                    }
                }
            } catch (\Throwable $e) { /* morning info is additive — the screen must still load */ }

            foreach ($query as $row) {
                // Resolve the shift FOR THE SELECTED DATE (not today) so past dates use
                // the shift that was actually in effect then.
                $shiftData = $shiftService->getUserShift($row->user_id, $selectedDate);

                // Distance from base against the SHIFT location for the date (same base
                // the web attendance view + mobile check-in use) — NOT the rider's default
                // office. Recompute so a rider working at LaCarne today reads
                // distance-from-LaCarne, even if their check-in predates this feature.
                $checkinDistance = $row->checkin_distance_from_base;
                $isRemoteCheckin = $row->is_remote_checkin ?? 0;
                if ($row->checkin_latitude && $row->checkin_longitude) {
                    $distInfo = \App\Services\LocationService::calculateDistanceFromBase(
                        $row->checkin_latitude, $row->checkin_longitude,
                        $row->user_id, $shiftData['location_id'] ?? null
                    );
                    if ($distInfo['distance_meters'] !== null) {
                        $checkinDistance = $distInfo['distance_meters'];
                        $isRemoteCheckin = $distInfo['is_remote'] ? 1 : 0;
                    }
                }

                // Calculate hours and late/OT status
                $hours = 0;
                $isLate = false;
                $lateMinutes = 0;
                $isOvertime = false;
                $overtimeMinutes = 0;
                
                // ⭐⭐ Sep-6 2026 — lateness through the ONE engine (lateForDay), not a local
                // Carbon subtraction. This block used to be a FIFTH implementation of the
                // rule and it disagreed with every other screen in two ways: it ignored the
                // FROZEN `expected_shift_start` snapshot (so a later shift change rewrote a
                // past day here but nowhere else), and it only computed lateness once the
                // rider had checked OUT — a rider still on duty read as 0 minutes late all
                // day. It now also honours a manager's waive, like the rest of the app.
                // ⚠ Deliberately OUTSIDE the login+logout guard below: he is late the moment
                // he checks in, whether or not he has finished.
                $lateDay = $shiftService->lateForDay(
                    (int) $row->user_id,
                    $selectedDate,
                    $row->login_time,
                    $row->late_minutes ?? null,
                    $row->expected_shift_start ?? null,
                    false
                );
                $lateMinutes = $lateDay['minutes'];
                // The BADGE follows the raw figure — he really was late; a waive forgives the
                // minutes, not the fact — while the minutes shown are what still counts.
                $isLate = $lateDay['raw'] > 0;

                if ($row->login_time && $row->logout_time) {
                    $login = \Carbon\Carbon::parse($row->login_time);
                    $logout = \Carbon\Carbon::parse($row->logout_time);
                    // ⭐ Calculate hours worked (round to 2 decimal places)
                    $hours = round(abs($logout->diffInMinutes($login)) / 60, 2);

                    // Check if overtime — only when the shift HAS an end (start-only shifts
                    // have no overtime).
                    if (!empty($shiftData['shift_end'])) {
                        $shiftEnd = \Carbon\Carbon::parse($shiftData['shift_end']);
                        if ($logout->gt($shiftEnd)) {
                            $isOvertime = true;
                            // ⭐ Use abs() to ensure positive, round to whole number
                            $overtimeMinutes = (int) abs($logout->diffInMinutes($shiftEnd));
                        }
                    }
                }
                
                // ⭐ Calculate meter distance — NULL when the pair spans TWO machines, because
                //   there is no honest single number then (MeterPairHelper). `meter_machines`
                //   names them so the phone can say so instead of printing nothing.
                $meterDistance = \App\Services\Riders\MeterPairHelper::distance($row);
                $meterMachines = \App\Services\Riders\MeterPairHelper::machines($row, $storeMpLabels);

                // HALF-DAY (leave_type='half_day' covering this date, approved/pending): present
                // with no lateness/overtime, shown as "½ day". The leave join is already
                // approved/pending + date-scoped, so the row's own type is authoritative.
                $isHalfDay = $row->leave_request_id
                    && strtolower((string) ($row->leave_type_from_req ?? '')) === 'half_day';
                if ($isHalfDay) {
                    $isLate = false; $lateMinutes = 0;
                    $isOvertime = false; $overtimeMinutes = 0;
                }

                $formattedData[] = [
                    'user_id' => $row->user_id,
                    'fullname' => $row->fullname,
                    'role_name' => $row->role_name,
                    'attendance_id' => $row->attendance_id,
                    'attendance_date' => $row->attendance_date,
                    'login_time' => $row->login_time,
                    'logout_time' => $row->logout_time,
                    'hours' => round($hours, 2),
                    'shift_start' => $shiftData['shift_start'],
                    'shift_end' => $shiftData['shift_end'],
                    'shift_name' => $shiftData['shift_name'],
                    // Where the rider is expected today (assignment → default → primary).
                    'shift_location_name' => $shiftData['location_name'] ?? null,
                    'shift_location_is_primary' => !empty($shiftData['location_id'])
                        ? ((int) $shiftData['location_id'] === $primaryLocationId)
                        : true,
                    'is_late' => $isLate,
                    'late_minutes' => $lateMinutes,
                    'is_overtime' => $isOvertime,
                    'overtime_minutes' => $overtimeMinutes,
                    'is_half_day' => $isHalfDay,
                    'leave_request_id' => $row->leave_request_id,
                    'leave_status' => $row->leave_status,
                    'leave_type' => $row->leave_type_from_req,
                    'notes' => $row->notes,
                    // Meter pictures
                    'picture_start' => $row->picture_start ? $this->getMeterPictureUrl($row->picture_start) : null,
                    'picture_end' => $row->picture_end ? $this->getMeterPictureUrl($row->picture_end) : null,
                    // Meter values
                    'meter_start' => $row->meter_start,
                    'meter_end' => $row->meter_end,
                    'meter_distance' => $meterDistance, // ⭐ Pre-calculated meter distance
                    // ⭐ Which machine each end is of; `split` = two odometers, no single distance.
                    //   Additive — older APKs ignore it and simply show no number, as they do for
                    //   any day without a meter.
                    'meter_machines' => $meterMachines,
                    // Location data
                    'checkin_latitude' => $row->checkin_latitude ?? null,
                    'checkin_longitude' => $row->checkin_longitude ?? null,
                    'checkin_distance_from_base' => $checkinDistance,
                    'is_remote_checkin' => $isRemoteCheckin,
                    'checkout_latitude' => $row->checkout_latitude ?? null,
                    'checkout_longitude' => $row->checkout_longitude ?? null,
                    // Where he checked out (manager view): office / at a customer / elsewhere
                    // (+ a flag if the delivery point was away from the saved address pin).
                    'checkout_info' => ($row->logout_time && ($row->checkout_latitude ?? null) !== null)
                        ? $checkoutClassifier->classify((int) $row->user_id, $selectedDate, $row->checkout_latitude, $row->checkout_longitude)
                        : null,
                    // ⭐ Road distance (auto-calculated on checkout) - PRIMARY indicator
                    'road_distance_km' => $row->road_distance_km ?? null,
                    'road_distance_source' => $row->road_distance_source ?? null,
                    // ⭐ GPS distance will be calculated in batch after the loop
                    'gps_distance' => null,
                    'gps_readings_count' => 0,
                    'gps_straight_distance_km' => $row->gps_straight_distance_km ?? null,
                    // Rider bypasses (the mobile 🔓 sheet): home-meter valve + checkout unlock.
                    'home_journey' => $hjByUser[$row->user_id] ?? null,
                    'work_journey' => $wjByUser[$row->user_id] ?? null, // U5 morning-start (store bypass sheet)
                    'is_company_bike' => isset($bikeUidSet[$row->user_id]), // U5: bypass sheet valve visibility
                    'checkout_unlock' => $cuByUser[$row->user_id] ?? null,
                    // U5 phase anchors + day_checks (filled after the GPS batch below) — SAME
                    // DayChecksService the web uses, so the phone can never drift from the web.
                    'meter_start_recorded_at' => $row->meter_start_recorded_at ?? null,
                    'home_meter_recorded_at' => $row->home_meter_recorded_at ?? null,
                    'meter_start_source' => $row->meter_start_source ?? null,
                    'day_checks' => null,
                    // Blocked-checkout context for the mobile bypass sheet — SAME shared formatter
                    // the web bypass modal uses (one brain), so the phone can't drift. null if none.
                    'checkout_attempt' => \App\Services\Riders\DayChecksService::checkoutAttempt($row, $stuckMins),
                ];
            }
            
            // ⭐ Batch calculate GPS distance for all users who have attendance
            $userIdsWithAttendance = array_filter(
                array_column($formattedData, 'user_id'),
                fn($uid) => collect($formattedData)->firstWhere('user_id', $uid)['login_time'] ?? false
            );
            
            if (!empty($userIdsWithAttendance)) {
                // Get all GPS readings for the date in one query
                $allGpsReadings = \DB::table('t_ops_rider_location')
                    ->whereIn('user_id', $userIdsWithAttendance)
                    ->whereDate('captured_at', $selectedDate)
                    ->where('accuracy', '<=', 100) // Skip inaccurate readings
                    ->orderBy('user_id')
                    ->orderBy('captured_at')
                    ->select('user_id', 'latitude', 'longitude', 'accuracy', 'captured_at')
                    ->get()
                    ->groupBy('user_id');
                
                // Calculate GPS distance for each user
                foreach ($formattedData as &$employee) {
                    if (isset($allGpsReadings[$employee['user_id']])) {
                        $readings = $allGpsReadings[$employee['user_id']]->values()->all();
                        $gpsResult = $this->calculateGpsDistanceFromReadings($readings);
                        $employee['gps_distance'] = $gpsResult['distance'];
                        $employee['gps_readings_count'] = $gpsResult['readings_count'];
                    }
                }
                unset($employee); // Clear reference
            }

            // ── DAY CHECKS — the ⛽/📡 verdicts + issue chips + clean flag, built by the SHARED
            //    DayChecksService (the SAME brain the web page uses), so the phone can NEVER drift
            //    from the web. Additive field → old APKs ignore it. Non-fatal.
            try {
                $dcSvc = new \App\Services\Riders\DayChecksService();
                $otSvc = new \App\Services\HR\OvertimeService(); // counted-checkout payload (one instance → memoized)
                $warnKm = (float) (DB::table('t_fin_config')->where('config_key', 'ATTENDANCE_METER_GPS_WARN_KM')->value('config_value') ?? 10);
                $gpsGrouped = $allGpsReadings ?? collect();
                foreach ($formattedData as &$employee) {
                    if (empty($employee['login_time'])) { continue; }
                    $rd = isset($gpsGrouped[$employee['user_id']]) ? $gpsGrouped[$employee['user_id']]->values()->all() : [];
                    // Same counted-checkout payload the web attendance page shows (owner ruling
                    // Aug-8): a bypassed checkout is counted to the last delivered order.
                    $cuRow = $employee['checkout_unlock'];
                    $counted = (is_array($cuRow) && !empty($cuRow['used']))
                        ? $otSvc->countedCheckout((int) $employee['user_id'], $selectedDate,
                            $employee['login_time'], $employee['logout_time'], $cuRow['until_raw'] ?? null)
                        : null;
                    // ⚠⚠ `user_id` is load-bearing — see the twin comment on the web page's
                    //   build() call. Without it the registry's date-scoped meter excusal
                    //   (`meterExcusedOn`) evaluates user 0 and can never fire. `transfer_day`
                    //   is derived inside the service from this id, so the phone and the web
                    //   reach the same verdict without the mobile payload having to compute it.
                    $employee['day_checks'] = $dcSvc->build([
                        'user_id' => (int) $employee['user_id'],
                        'login_time' => $employee['login_time'], 'logout_time' => $employee['logout_time'],
                        'role_name' => $employee['role_name'] ?? null, 'company_bike' => !empty($employee['is_company_bike']),
                        'meter_required' => isset($meterExemptSet[$employee['user_id']]) ? 0 : 1,
                        'meter_start' => $employee['meter_start'], 'meter_end' => $employee['meter_end'], 'meter_distance' => $employee['meter_distance'],
                        // ⚠ Same split flag the web page passes, so the phone's ⛽ tick and the
                        //   web's can never disagree about a two-machine day.
                        'meter_split' => !empty($employee['meter_machines']['split']),
                        'road_distance_km' => $employee['road_distance_km'], 'gps_distance' => $employee['gps_distance'],
                        'checkout_info' => $employee['checkout_info'], 'home_journey' => $employee['home_journey'],
                        'work_journey' => $employee['work_journey'], 'checkout_unlock' => $employee['checkout_unlock'],
                        'checkout_counted' => $counted,
                        'meter_start_recorded_at' => $employee['meter_start_recorded_at'],
                        'home_meter_recorded_at' => $employee['home_meter_recorded_at'],
                        'meter_start_source' => $employee['meter_start_source'],
                    ], $rd, $selectedDate, $warnKm);
                }
                unset($employee);
            } catch (\Throwable $e) { \Log::warning('day_checks (mobile) failed (non-fatal)', ['error' => $e->getMessage()]); }

            // ⭐ Batch fetch previous day's meter_end for all employees
            // This helps identify gaps between yesterday's end and today's start
            $allUserIds = array_column($formattedData, 'user_id');
            $previousMeterEnds = [];
            
            if (!empty($allUserIds)) {
                // Get the most recent meter_end for each user before the selected date
                $prevReadings = \DB::select("
                    SELECT a.user_id, a.meter_end, a.attendance_date
                    FROM t_ops_attendance a
                    INNER JOIN (
                        SELECT user_id, MAX(attendance_date) as max_date
                        FROM t_ops_attendance
                        WHERE user_id IN (" . implode(',', array_fill(0, count($allUserIds), '?')) . ")
                          AND attendance_date < ?
                          AND meter_end IS NOT NULL
                        GROUP BY user_id
                    ) latest ON a.user_id = latest.user_id AND a.attendance_date = latest.max_date
                ", array_merge($allUserIds, [$selectedDate]));
                
                foreach ($prevReadings as $prev) {
                    $previousMeterEnds[$prev->user_id] = [
                        'meter_end' => $prev->meter_end,
                        'date' => $prev->attendance_date,
                    ];
                }
            }
            
            // Batch fetch leaves_taken_year for users who are on leave today
            $currentYear = date('Y');
            $leaveUserIds = array_column(
                array_filter($formattedData, fn($e) => $e['leave_request_id']),
                'user_id'
            );
            $yearLeavesByUser = [];
            if (!empty($leaveUserIds)) {
                $yearLeaves = DB::table('t_req_master as r')
                    ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                    ->where('c.category_code', 'leave')
                    ->where('r.status', 'approved')
                    ->whereIn('r.requester_user_id', $leaveUserIds)
                    ->where('r.leave_start_date', '>=', "{$currentYear}-01-01")
                    ->where('r.leave_end_date', '<=', "{$currentYear}-12-31")
                    ->select('r.requester_user_id', 'r.leave_start_date', 'r.leave_end_date')
                    ->get();
                foreach ($yearLeaves as $yl) {
                    $days = \Carbon\Carbon::parse($yl->leave_start_date)
                        ->diffInDays(\Carbon\Carbon::parse($yl->leave_end_date)) + 1;
                    $yearLeavesByUser[$yl->requester_user_id] = 
                        ($yearLeavesByUser[$yl->requester_user_id] ?? 0) + $days;
                }
            }

            // Add previous meter info and leaves_taken_year to each employee
            // ⭐⭐ "Last night's meter" is a fact about the MACHINE, so it comes from the same
            //    `closingBaseline()` the web sheet and the red meter-gap verdict use. This screen
            //    was the third rider-keyed copy of the lookup (flagged in the Aug-21 note §7.2):
            //    on a machine-switch day it printed the difference between two odometers as
            //    "+N km overnight". Field names are unchanged, so no APK is needed.
            //    ⚠ Only for a company-machine rider who actually has a start reading — that is
            //      exactly when the phone shows the line, and it keeps the resolver walk off
            //      every other employee in the list.
            $wjBase = new \App\Services\Riders\WorkJourneyService();
            foreach ($formattedData as &$employee) {
                $prev = $previousMeterEnds[$employee['user_id']] ?? null;
                $employee['prev_meter_end'] = $prev ? $prev['meter_end'] : null;
                $employee['prev_meter_date'] = $prev ? $prev['date'] : null;
                $employee['prev_meter_label'] = null;
                $employee['prev_meter_source'] = 'rider';

                if (!empty($employee['is_company_bike']) && !empty($employee['meter_start'])) {
                    try {
                        $mb = $wjBase->closingBaseline((int) $employee['user_id'], $selectedDate);
                        // holds_nothing = on no machine today ⇒ nothing to measure against.
                        $employee['prev_meter_end']    = $mb['holds_nothing'] ? null : $mb['value'];
                        $employee['prev_meter_date']   = $mb['holds_nothing'] ? null : $mb['date'];
                        $employee['prev_meter_label']  = $mb['holds_nothing'] ? null : $mb['label'];
                        $employee['prev_meter_source'] = $mb['holds_nothing'] ? 'none' : $mb['source'];
                        // A handover day is not judged — the baseline may be the other man's.
                        if (!empty($mb['transfer_day'])) {
                            $employee['prev_meter_end'] = null;
                            $employee['prev_meter_source'] = 'handover';
                        }
                    } catch (\Throwable $e) { /* keep the rider-keyed answer above */ }
                }

                $employee['meter_gap'] = null;
                if ($employee['prev_meter_end'] !== null && $employee['meter_start']) {
                    $gap = (int)$employee['meter_start'] - (int)$employee['prev_meter_end'];
                    $employee['meter_gap'] = $gap;
                }

                $employee['leaves_taken_year'] = $yearLeavesByUser[$employee['user_id']] ?? 0;
                $employee['leaves_year'] = (int) $currentYear;
            }
            unset($employee);
            
            // Calculate summary stats. A half-day (checked in) counts PRESENT, not on-leave —
            // its late/overtime flags are already suppressed above (owner's rule).
            $summary = [
                'total_employees' => count($formattedData),
                'present' => count(array_filter($formattedData, fn($e) => $e['login_time'])),
                'absent' => count(array_filter($formattedData, fn($e) => !$e['login_time'] && !$e['leave_request_id'])),
                'on_leave' => count(array_filter($formattedData, fn($e) => $e['leave_request_id'] && !($e['is_half_day'] ?? false))),
                'late' => count(array_filter($formattedData, fn($e) => $e['is_late'])),
                'overtime' => count(array_filter($formattedData, fn($e) => $e['is_overtime'])),
            ];
            
            return response()->json([
                'success' => true,
                'date' => $selectedDate,
                'summary' => $summary,
                'attendance' => $formattedData,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to get store attendance: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to load attendance: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE ATTENDANCE - Get individual employee attendance details
     * Reuses web app logic from AttendanceController@employeeDetails
     */
    public function getStoreAttendanceEmployeeDetails(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_store_attendance')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view store attendance'
                ], 403);
            }
            
            $userId = $request->input('user_id');
            $month = $request->input('month', now()->format('Y-m'));
            
            if (!$userId) {
                return response()->json([
                    'success' => false,
                    'message' => 'user_id is required'
                ], 400);
            }
            
            // Calculate date range for the month
            $startDate = $month . '-01';
            $endDate = \Carbon\Carbon::parse($startDate)->endOfMonth()->toDateString();
            
            // Get user info
            $userInfo = DB::table('t_sys_user as u')
                ->leftJoin('t_sys_user_role as ur', 'ur.user_id', '=', 'u.id')
                ->leftJoin('t_sys_role as r', 'r.id', '=', 'ur.role_id')
                ->select('u.id', 'u.fullname', 'r.urole_name as role_name')
                ->where('u.id', $userId)
                ->first();
            
            if (!$userInfo) {
                return response()->json([
                    'success' => false,
                    'message' => 'User not found'
                ], 404);
            }
            
            // Get shift info using ShiftResolutionService
            $shiftService = new \App\Services\ShiftResolutionService();
            $shiftInfo = $shiftService->getUserShift($userId, date('Y-m-d'));
            
            // Build per-day delivered orders via subquery
            $deliveredPerDay = DB::table('t_ops_order_rider_history as orh')
                ->join('t_crm_order_status_history as osh', function($join) {
                    $join->on('osh.order_id', '=', 'orh.order_id')
                         ->where('osh.status_code', 'delivered')
                         ->where('osh.is_current', 1);
                })
                ->select(
                    'orh.rider_user_id as rider_id',
                    DB::raw('DATE(osh.changed_at) as delivered_date'),
                    DB::raw('COUNT(DISTINCT osh.order_id) as orders_delivered'),
                    DB::raw('MIN(TIME(osh.changed_at)) as first_delivery_time'),
                    DB::raw('MAX(TIME(osh.changed_at)) as last_delivery_time')
                )
                ->where('orh.rider_user_id', '=', $userId)
                ->where('orh.is_current', '=', 1)
                ->whereBetween(DB::raw('DATE(osh.changed_at)'), [$startDate, $endDate])
                ->groupBy('orh.rider_user_id', DB::raw('DATE(osh.changed_at)'));
            
            // Leave requests subquery
            $leaveSub = DB::table('t_req_master')
                ->select(
                    'requester_user_id',
                    'id as leave_request_id',
                    'status as leave_status',
                    'leave_type',
                    'leave_start_date',
                    'leave_end_date'
                )
                ->where('category_id', function($q) {
                    $q->select('id')
                      ->from('t_req_category')
                      ->where('category_code', 'leave')
                      ->limit(1);
                });
            
            // Attendance rows joined with per-day delivered orders and leave requests
            $query = DB::table('t_ops_attendance as a')
                ->leftJoinSub($deliveredPerDay, 'd', function($join) {
                    $join->on('d.rider_id', '=', 'a.user_id')
                         ->on('d.delivered_date', '=', 'a.attendance_date');
                })
                ->leftJoinSub($leaveSub, 'lr', function($join) {
                    $join->on('lr.requester_user_id', '=', 'a.user_id')
                         ->whereColumn('a.attendance_date', '>=', 'lr.leave_start_date')
                         ->whereColumn('a.attendance_date', '<=', 'lr.leave_end_date');
                })
                ->where('a.user_id', '=', $userId)
                ->whereBetween('a.attendance_date', [$startDate, $endDate])
                ->select(
                    'a.id as attendance_id',
                    'a.attendance_date',
                    'a.login_time',
                    'a.logout_time',
                    'a.picture_start',
                    'a.picture_end',
                    'a.meter_start',
                    'a.meter_end',
                    'a.checkin_latitude',
                    'a.checkin_longitude',
                    'a.checkin_distance_from_base',
                    'a.is_remote_checkin',
                    'a.checkout_latitude',
                    'a.checkout_longitude',
                    // ⭐ Include stored road distance columns
                    'a.road_distance_km',
                    'a.road_distance_source',
                    'a.gps_straight_distance_km',
                    'a.gps_readings_used',
                    // Frozen snapshot (preferred over recomputation)
                    'a.late_minutes as snap_late_minutes',
                    'a.overtime_minutes as snap_overtime_minutes',
                    // The shift start this day was judged against — so a late row can SHOW
                    // what the check-in was measured against, like the web drill does.
                    'a.expected_shift_start',
                    'lr.leave_request_id',
                    'lr.leave_status',
                    'lr.leave_type',
                    DB::raw('COALESCE(d.orders_delivered, 0) as total_orders_delivered'),
                    DB::raw("COALESCE(d.first_delivery_time, '-') as first_delivery_time"),
                    DB::raw("COALESCE(d.last_delivery_time, '-') as last_delivery_time")
                )
                // ⭐ The reading stamps — the manager's phone must not compute a distance across
                //   two odometers either (MeterPairHelper). Schema-guarded.
                ->when(\App\Services\Riders\VehicleService::stampsAvailable(),
                    fn ($q) => $q->addSelect(['a.meter_start_vehicle_id', 'a.meter_end_vehicle_id']))
                ->orderByDesc('a.attendance_date')
                ->get();

            // Clean up null values
            foreach ($query as $record) {
                if ($record->first_delivery_time === null) {
                    $record->first_delivery_time = '-';
                }
                if ($record->last_delivery_time === null) {
                    $record->last_delivery_time = '-';
                }
            }
            
            // Calculate working days
            $workingDays = $shiftService->calculateWorkingDays($userId, $startDate, $endDate);
            
            // ⭐ Calculate meter/distance statistics
            $totalDistance = 0;
            $daysWithMeterReadings = 0;
            $daysMissingMeterReadings = 0;
            
            /**
             * ⚠⚠ THE MONTH TOTAL MUST OBEY THE SAME RULE AS THE ROW (13-Sep-2026, found on the
             *    real handset). This loop did its own `abs(end - start)` and knew nothing about
             *    the machine stamps, so on Rajab's 11-Sep the card said
             *    "🏍🚚 own bike → CAD-2958 — no day distance" while the header above it added
             *    **67,874 km** for that very day: 68,578 for the month against a true 704. It
             *    also poisoned "Avg Cost", which divides fuel by this number — Rs 0.2/km instead
             *    of Rs 21/km.
             *
             * `MeterPairHelper::distance()` is the ONE answer to "how far on this row": null when
             * the two ends are stamped to different machines. A split day is therefore not a day
             * with a reading — it is a day whose distance we do not have — so it counts as
             * missing, exactly as the ⛽ tick and every web surface already treat it.
             */
            foreach ($query as $record) {
                $distance = \App\Services\Riders\MeterPairHelper::distance($record);
                if ($distance !== null) {
                    $totalDistance += $distance;
                    $daysWithMeterReadings++;
                } elseif ($record->login_time) {
                    // Has attendance but no usable pair — no readings, or two machines.
                    $daysMissingMeterReadings++;
                }
            }
            
            // ⭐ Get fuel/petrol expenses for this user in this month
            $fuelExpense = DB::table('t_req_master as r')
                ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                ->where('c.category_code', 'expense')
                ->where('r.requester_user_id', $userId)
                ->whereIn('r.status', ['approved', 'pending']) // Include pending for visibility
                ->where(function($q) {
                    $q->where('r.expense_category', 'LIKE', '%petrol%')
                      ->orWhere('r.expense_category', 'LIKE', '%fuel%')
                      ->orWhere('r.expense_category', 'LIKE', '%Petrol%')
                      ->orWhere('r.expense_category', 'LIKE', '%Fuel%');
                })
                ->where(function($q) use ($startDate, $endDate) {
                    // Use expense_date if available, otherwise created_at
                    $q->whereBetween('r.expense_date', [$startDate, $endDate])
                      ->orWhere(function($q2) use ($startDate, $endDate) {
                          $q2->whereNull('r.expense_date')
                             ->whereBetween(DB::raw('DATE(r.created_at)'), [$startDate, $endDate]);
                      });
                })
                ->sum('r.amount');
            
            // Calculate statistics
            $totalDays = $query->count();
            $presentDays = $query->where('login_time', '!=', null)->count();

            // Half-day dates → present, no late/OT, "½ day" badge (same rule as every surface).
            $halfDaySet = (new \App\Services\HR\LeavePolicyService())->halfDayDates((int) $userId, $startDate, $endDate);

            // Count leave days — a half-day is NOT a full on-leave day (he was present).
            $onLeaveDays = 0;
            foreach ($query as $record) {
                if (isset($halfDaySet[substr((string) $record->attendance_date, 0, 10)])) { continue; }
                if ($record->leave_request_id &&
                    in_array(strtolower($record->leave_status ?? ''), ['approved', 'pending'])) {
                    $onLeaveDays++;
                }
            }
            
            $absentDays = $workingDays - $presentDays - $onLeaveDays;
            if ($absentDays < 0) $absentDays = 0;
            
            $lateDays = 0;
            $overtimeDays = 0;
            $totalHours = 0;
            $totalOrdersDelivered = 0;

            // ⭐ Overtime = TARGET-based here too (owner ruling Jul-28) — the work beyond the
            // daily target that earns BONUS LEAVE, matching the web popup, the Month tab and
            // the payslip. Computed once; the per-day map feeds the day rows below.
            $otSvcDet    = new \App\Services\HR\OvertimeService();
            $otRangeDet  = $otSvcDet->overtimeForRange($userId, $startDate, $endDate);
            $otByDateDet = $otRangeDet['dates'] ?? [];
            // The EVIDENCE behind each day's figure — check-in, checkout as recorded, and the
            // counted end when that checkout rode a manager bypass. Built in the same service
            // loop as the minutes, so the times can never contradict the number beside them.
            $otDetailsDet = $otRangeDet['details'] ?? [];
            $otMinutesDet = (int) ($otRangeDet['total'] ?? 0);

            foreach ($query as $record) {
                $record->is_half_day = isset($halfDaySet[substr((string) $record->attendance_date, 0, 10)]);
                // Calculate hours worked
                if ($record->login_time && $record->logout_time) {
                    $login = strtotime($record->login_time);
                    $logout = strtotime($record->logout_time);
                    $hours = ($logout - $login) / 3600;
                    $totalHours += $hours;
                    $record->hours_worked = round($hours, 1);
                } else {
                    $record->hours_worked = 0;
                }

                // Per-day late/overtime — prefer the FROZEN snapshot; else resolve the
                // shift in effect ON THIS DATE and compute (truncate seconds). Keeps
                // per-day rows consistent with the snapshot-preferring monthly totals.
                // A HALF-DAY counts no lateness (owner's rule) — short-circuit to 0.
                // Late through the ONE rule (Sep-6 2026 — this was the fourth inline copy).
                // ⚠ default_shift is null HERE and only here: this screen has never guessed
                // 09:00 for a user whose shift cannot be resolved, it has always reported 0.
                // Keeping that difference explicit is what makes the consolidation a no-op.
                $lateDayRec = $shiftService->lateForDay(
                    $userId, (string) $record->attendance_date, $record->login_time,
                    $record->snap_late_minutes, $record->expected_shift_start,
                    (bool) $record->is_half_day, ['default_shift' => null]
                );
                $record->late_minutes = $lateDayRec['minutes'];
                $record->late_waived_minutes = $lateDayRec['waived'];
                $record->late_raw_minutes = $lateDayRec['raw'];
                if ($lateDayRec['raw'] > 0) { $lateDays++; }

                // Target-based overtime for THIS day, from the map above. The service already
                // drops half-days and days with no checkout, so a missing key means none earned.
                $recDateOtDet = substr((string) $record->attendance_date, 0, 10);
                $record->overtime_minutes = (int) ($otByDateDet[$recDateOtDet] ?? 0);
                if ($record->overtime_minutes > 0) { $overtimeDays++; }

                // ── Web-parity evidence for the day row (additive; older app builds ignore it).
                // Overtime: the day AS WORKED + the re-based end when the checkout used a
                // manager unlock. Late: the shift start the check-in was measured against —
                // resolved only when it's actually late, so no extra lookups on normal days.
                $record->overtime_meta = $otDetailsDet[$recDateOtDet] ?? null;
                $record->shift_start_time = null;
                // ⚠ Keyed on the RAW figure, not the effective one: a day whose lateness was
                // fully waived still has to show what it was measured against, or the waive
                // reads as "there was never anything here".
                if ($lateDayRec['raw'] > 0) {
                    // lateForDay resolved the start already whenever it had to compute; only
                    // pay for a lookup when the frozen snapshot short-circuited that.
                    $record->shift_start_time = $lateDayRec['shift_start'];
                    if ($record->shift_start_time === null) {
                        $ss = $record->expected_shift_start
                            ?: ($shiftService->getUserShift($userId, $record->attendance_date)['shift_start'] ?? null);
                        if ($ss && preg_match('/(\d{1,2}):(\d{2})/', (string) $ss, $mm)) {
                            $record->shift_start_time = str_pad($mm[1], 2, '0', STR_PAD_LEFT) . ':' . $mm[2];
                        }
                    }
                }

                // Add order count to total
                $totalOrdersDelivered += $record->total_orders_delivered;

                // Format delivery times
                if ($record->first_delivery_time && $record->first_delivery_time !== '-') {
                    try {
                        $record->first_delivery_time = date('H:i', strtotime($record->first_delivery_time));
                    } catch (\Exception $e) {
                        $record->first_delivery_time = '-';
                    }
                } else {
                    $record->first_delivery_time = '-';
                }
                
                if ($record->last_delivery_time && $record->last_delivery_time !== '-') {
                    try {
                        $record->last_delivery_time = date('H:i', strtotime($record->last_delivery_time));
                    } catch (\Exception $e) {
                        $record->last_delivery_time = '-';
                    }
                } else {
                    $record->last_delivery_time = '-';
                }
                
                // Convert picture paths to URLs
                $record->picture_start = $record->picture_start ? $this->getMeterPictureUrl($record->picture_start) : null;
                $record->picture_end = $record->picture_end ? $this->getMeterPictureUrl($record->picture_end) : null;
                
                // ⭐ Meter distance — NULL on a two-machine day, with the machines named so the
                //   screen can say so instead of printing an odometer difference.
                $record->meter_distance = \App\Services\Riders\MeterPairHelper::distance($record);
                $record->meter_machines = \App\Services\Riders\MeterPairHelper::machines($record);
            }
            
            // ⭐ Batch calculate GPS distance for all days with attendance
            $datesWithAttendance = $query
                ->filter(fn($r) => $r->login_time !== null)
                ->pluck('attendance_date')
                ->toArray();
            
            $totalGpsDistance = 0;
            $totalRoadDistance = 0;
            $daysWithGpsReadings = 0;
            $daysWithRoadDistance = 0;
            
            // Determine which day to auto-calculate road distance for (most recent with attendance)
            $autoCalcRoadDate = !empty($datesWithAttendance) ? max($datesWithAttendance) : null;
            
            if (!empty($datesWithAttendance)) {
                // Get all GPS readings for this user in the date range
                $allGpsReadings = \DB::table('t_ops_rider_location')
                    ->where('user_id', $userId)
                    ->whereBetween(\DB::raw('DATE(captured_at)'), [$startDate, $endDate])
                    ->where('accuracy', '<=', 100)
                    ->orderBy('captured_at')
                    ->select('latitude', 'longitude', 'accuracy', 'captured_at', \DB::raw('DATE(captured_at) as reading_date'))
                    ->get()
                    ->groupBy('reading_date');
                
                // Get attendance records for gap analysis
                $attendanceByDate = [];
                foreach ($query as $record) {
                    $attendanceByDate[$record->attendance_date] = $record;
                }
                
                // Assign GPS distance to each record
                foreach ($query as $record) {
                    $recordDate = $record->attendance_date;
                    if (isset($allGpsReadings[$recordDate])) {
                        $readings = $allGpsReadings[$recordDate]->values()->all();
                        $gpsResult = $this->calculateGpsDistanceFromReadings($readings);
                        $record->gps_distance = $gpsResult['distance'];
                        $record->gps_readings_count = $gpsResult['readings_count'];
                        
                        if ($gpsResult['distance'] !== null) {
                            $totalGpsDistance += $gpsResult['distance'];
                            $daysWithGpsReadings++;
                        }
                        
                        // ⭐ Check for stored road distance first, otherwise calculate for most recent day
                        $record->gap_info = null;
                        
                        // ⭐ USE STORED VALUE if available (from checkout or manual calculation)
                        if ($record->road_distance_km !== null) {
                            $record->road_distance = (float)$record->road_distance_km;
                            $record->road_source = $record->road_distance_source ?? 'stored';
                            $totalRoadDistance += $record->road_distance;
                            $daysWithRoadDistance++;
                        } elseif ($recordDate === $autoCalcRoadDate && $record->gps_distance !== null && $record->gps_distance >= 0.5) {
                            // Auto-calculate road distance for most recent day only (if not stored)
                            $sampledReadings = $this->sampleGpsReadings($readings, 25); // ⭐ Use 25 samples
                            if (count($sampledReadings) >= 2) {
                                $roadDist = $this->callOpenRouteService($sampledReadings);
                                if ($roadDist !== null) {
                                    $record->road_distance = round($roadDist, 1);
                                    $record->road_source = 'openrouteservice';
                                    $totalRoadDistance += $roadDist;
                                    $daysWithRoadDistance++;
                                } else {
                                    $record->road_distance = null;
                                    $record->road_source = null;
                                }
                            } else {
                                $record->road_distance = null;
                                $record->road_source = null;
                            }
                        } elseif ($record->gps_distance !== null && $record->gps_distance < 0.5) {
                            $record->road_distance = null;
                            $record->road_source = 'skipped_stationary';
                        } else {
                            $record->road_distance = null;
                            $record->road_source = null;
                        }
                        
                        // ⭐ Calculate gap info for this day
                        // IMPORTANT: Combine date + time to get full timestamp for accurate gap calculation
                        if ($record->login_time && count($readings) >= 2) {
                            $fullLoginTime = $recordDate . ' ' . $record->login_time;
                            $fullLogoutTime = $record->logout_time ? ($recordDate . ' ' . $record->logout_time) : null;
                            $gapInfo = $this->calculateGapInfo($readings, $fullLoginTime, $fullLogoutTime);
                            $record->gap_info = $gapInfo;
                        }
                    } else {
                        // No GPS readings for this day, but check for stored road distance
                        $record->gps_distance = null;
                        $record->gps_readings_count = 0;
                        $record->gap_info = null;
                        
                        // ⭐ Still use stored road_distance_km if available
                        if ($record->road_distance_km !== null) {
                            $record->road_distance = (float)$record->road_distance_km;
                            $record->road_source = $record->road_distance_source ?? 'stored';
                            $totalRoadDistance += $record->road_distance;
                            $daysWithRoadDistance++;
                        } else {
                            $record->road_distance = null;
                            $record->road_source = null;
                        }
                    }
                }
            } else {
                // No attendance dates, but still check for stored road distance
                foreach ($query as $record) {
                    $record->gps_distance = null;
                    $record->gps_readings_count = 0;
                    $record->gap_info = null;
                    
                    // ⭐ Still use stored road_distance_km if available
                    if ($record->road_distance_km !== null) {
                        $record->road_distance = (float)$record->road_distance_km;
                        $record->road_source = $record->road_distance_source ?? 'stored';
                        $totalRoadDistance += $record->road_distance;
                        $daysWithRoadDistance++;
                    } else {
                        $record->road_distance = null;
                        $record->road_source = null;
                    }
                }
            }
            
            // Leave picture for the tappable Leave breakdown: balance (remaining of total),
            // taken split planned vs emergency, and the dated overtime/late/manual adjustments.
            // NOTE: overtime bonus (+) / late penalty (−) rows are written at PAYROLL time, so they
            // appear here only AFTER the manager pays that month (by design — the pay step is the
            // approval). Until then they're a preview on the Payroll screen only.
            $leavePolicy = new \App\Services\HR\LeavePolicyService();
            $leaveBalance = $leavePolicy->balance((int) $userId);
            $leaveAdjustments = $leavePolicy->adjustments((int) $userId);
            $leaveTakenSplit = $leavePolicy->takenByType((int) $userId);

            return response()->json([
                'success' => true,
                'employee' => [
                    'user_id' => $userInfo->id,
                    'fullname' => $userInfo->fullname,
                    'role_name' => $userInfo->role_name,
                    'shift_start' => $shiftInfo['shift_start'],
                    'shift_end' => $shiftInfo['shift_end'],
                    'shift_name' => $shiftInfo['shift_name'],
                    'working_days' => $workingDays,
                    'present_days' => $presentDays,
                    'on_leave_days' => $onLeaveDays,
                    'leave_balance' => $leaveBalance,
                    'leave_adjustments' => $leaveAdjustments,
                    'leave_taken_split' => $leaveTakenSplit,
                    'absent_days' => $absentDays,
                    'late_days' => $lateDays,
                    'overtime_days' => $overtimeDays,
                    // Same shape the web popup returns — hours earned and the bonus days they
                    // buy, from the one service payroll grants on.
                    'overtime_minutes' => $otMinutesDet,
                    // Carry-aware (Sep-2026): identical to the web grid and the payslip.
                    'overtime_bonus_leaves' => $otSvcDet->bonusLeavesFor($userId, $startDate, $endDate, $otMinutesDet),
                    'overtime_minutes_per_bonus' => $otSvcDet->minutesPerBonusDay(),
                    'total_hours' => round($totalHours, 1),
                    'total_orders_delivered' => $totalOrdersDelivered,
                    // ⭐ NEW: Meter/Distance statistics
                    'total_distance' => $totalDistance,
                    'days_with_meter_readings' => $daysWithMeterReadings,
                    'days_missing_meter_readings' => $daysMissingMeterReadings,
                    // ⭐ NEW: GPS Distance statistics
                    'total_gps_distance' => round($totalGpsDistance, 1),
                    'days_with_gps_readings' => $daysWithGpsReadings,
                    // ⭐ NEW: Road Distance statistics (most accurate)
                    'total_road_distance' => round($totalRoadDistance, 1),
                    'days_with_road_distance' => $daysWithRoadDistance,
                    // ⭐ NEW: Fuel expense for efficiency calculation
                    'fuel_expense' => round($fuelExpense, 0),
                ],
                'daily_records' => $query,
                'month' => $month,
                'start_date' => $startDate,
                'end_date' => $endDate,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to get employee attendance details: ' . $e->getMessage(), [
                'trace' => $e->getTraceAsString()
            ]);
            return response()->json([
                'success' => false,
                'message' => 'Failed to load employee details: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * STORE ATTENDANCE - Update meter values for an attendance record
     */
    /**
     * Store-mode RIDER BYPASSES (mobile manager) — thin permission-gated wrappers around the
     * SAME web logic (CRM\AttendanceController), so a manager on the phone can unlock a stuck
     * rider without opening the web. Gated on view_store_attendance so ordinary riders can
     * never call these (no self-unlock).
     */
    private function storeAttendanceGate()
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('view_store_attendance')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to manage attendance'], 403);
        }
        return null;
    }

    public function storeAttendanceCheckoutUnlock(Request $request)
    {
        if ($deny = $this->storeAttendanceGate()) { return $deny; }
        return (new \App\Http\Controllers\CRM\AttendanceController())->checkoutUnlock($request);
    }

