    /**
     * STORE ATTENDANCE - Get monthly attendance summary for all employees
     */
    public function getStoreAttendanceMonthly(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_store_attendance')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view store attendance'
                ], 403);
            }
            
            $month = $request->input('month', now()->format('Y-m'));
            $startDate = $month . '-01';
            $endDate = \Carbon\Carbon::parse($startDate)->endOfMonth()->toDateString();
            // For the CURRENT month, only count up to today (don't treat future days as
            // absent) — matches the web monthly report.
            $today = date('Y-m-d');
            $effectiveEndDate = ($endDate > $today) ? $today : $endDate;

            // Get all active visible users
            $users = DB::table('t_sys_user as u')
                ->leftJoin('t_sys_user_role as ur', 'ur.user_id', '=', 'u.id')
                ->leftJoin('t_sys_role as r', 'r.id', '=', 'ur.role_id')
                ->leftJoin('t_ops_attendance_visibility as av', 'av.user_id', '=', 'u.id')
                ->leftJoin('t_ops_rider_profile as rp', 'rp.user_id', '=', 'u.id')
                ->select(
                    'u.id as user_id',
                    'u.fullname',
                    'r.urole_name as role_name',
                    DB::raw('COALESCE(rp.shift_start, "09:00") as shift_start'),
                    DB::raw('COALESCE(rp.shift_end, "17:00") as shift_end')
                )
                ->where('u.is_active', 1)
                ->where(function($q) {
                    $q->whereNull('av.is_visible')
                      ->orWhere('av.is_visible', 1);
                })
                ->orderBy('u.fullname')
                ->get();
            
            $monthlyData = [];
            $shiftService = new \App\Services\ShiftResolutionService();
            $lookupDate = date('Y-m-d');

            // Office-checkout counts for the month, batched ONCE for all employees (R9.1 mobile
            // mirror). Same rule as the web Month column. Guarded / non-fatal.
            $officeCheckoutCounts = [];
            try {
                $ocMap = (new \App\Services\Riders\CheckoutClassifierService())
                    ->officeCheckoutDays($users->pluck('user_id')->all(), $startDate, $effectiveEndDate);
                foreach ($ocMap as $uid => $days) { $officeCheckoutCounts[$uid] = count($days); }
            } catch (\Throwable $e) { $officeCheckoutCounts = []; }

            // Same three flag families + missed meters the WEB Month tab shows, from the SAME
            // batched services — so the phone's monthly card can't disagree with the web table.
            // All guarded / non-fatal and additive (old APKs ignore the new keys).
            $allUserIds = $users->pluck('user_id')->all();
            $inFlagMap = [];
            $outFlagMap = [];
            $meterMissMap = [];
            try {
                $inFlagMap = (new \App\Services\Riders\WorkJourneyService())
                    ->workIssueDays($allUserIds, $startDate, $effectiveEndDate);
            } catch (\Throwable $e) { $inFlagMap = []; }
            try {
                $outFlagMap = (new \App\Services\Riders\HomeJourneyService())
                    ->homeIssueDays($allUserIds, $startDate, $effectiveEndDate);
            } catch (\Throwable $e) { $outFlagMap = []; }
            try {
                $meterMissMap = (new \App\Services\Riders\DayChecksService())
                    ->meterMissDays($allUserIds, $startDate, $effectiveEndDate);
            } catch (\Throwable $e) { $meterMissMap = []; }
            // Off-duty km per company-machine rider, from the ONE engine (web Month tab parity).
            $offDutyByUser = [];
            try {
                $odEng = new \App\Services\Riders\MachineAttribution();
                foreach (array_keys($odEng->month(substr($startDate, 0, 7))['riders'] ?? []) as $odUid) {
                    $cm = $odEng->companyMonth((int) $odUid, substr($startDate, 0, 7));
                    if ($cm && $cm['had_company']) $offDutyByUser[(int) $odUid] = $cm;
                }
            } catch (\Throwable $e) { $offDutyByUser = []; }

            foreach ($users as $user) {
                // Resolve shift using ShiftResolutionService (same as web) for accurate shift times
                try {
                    $shiftData = $shiftService->getUserShift($user->user_id, $lookupDate);
                    $resolvedShiftStart = $shiftData['shift_start'];
                    $resolvedShiftEnd = $shiftData['shift_end'];
                    $resolvedShiftName = $shiftData['shift_name'];
                } catch (\Exception $e) {
                    $resolvedShiftStart = $user->shift_start;
                    $resolvedShiftEnd = $user->shift_end;
                    $resolvedShiftName = $user->shift_start . ' - ' . $user->shift_end;
                }

                // Get attendance records for this user in the month
                $attendance = DB::table('t_ops_attendance')
                    ->where('user_id', $user->user_id)
                    ->whereBetween('attendance_date', [$startDate, $endDate])
                    ->get();
                
                // Get leave requests and calculate leave days manually
                $leaveRequests = DB::table('t_req_master as r')
                    ->join('t_req_category as c', 'c.id', '=', 'r.category_id')
                    ->where('c.category_code', '=', 'leave')
                    ->where('r.requester_user_id', $user->user_id)
                    ->whereIn('r.status', ['approved', 'pending'])
                    ->where(function($q) use ($startDate, $endDate) {
                        $q->whereBetween('r.leave_start_date', [$startDate, $endDate])
                          ->orWhereBetween('r.leave_end_date', [$startDate, $endDate])
                          ->orWhere(function($q2) use ($startDate, $endDate) {
                              $q2->where('r.leave_start_date', '<=', $startDate)
                                 ->where('r.leave_end_date', '>=', $endDate);
                          });
                    })
                    ->select('r.leave_start_date', 'r.leave_end_date', 'r.leave_type')
                    ->get();

                // Calculate total leave days within the month range (clipped to today
                // for the current month, matching working-days). A half-day counts 0.5.
                $leaveDays = 0;
                foreach ($leaveRequests as $leave) {
                    $leaveStart = max($leave->leave_start_date, $startDate);
                    $leaveEnd = min($leave->leave_end_date, $effectiveEndDate);
                    if ($leaveStart > $leaveEnd) { continue; } // entirely in the future
                    if (strtolower((string) ($leave->leave_type ?? '')) === 'half_day') {
                        $leaveDays += 0.5; // half-day is a single date at 0.5
                        continue;
                    }
                    $days = \Carbon\Carbon::parse($leaveStart)->diffInDays(\Carbon\Carbon::parse($leaveEnd)) + 1;
                    $leaveDays += $days;
                }
                
                // Calculate stats
                $presentDays = $attendance->filter(fn($a) => $a->login_time)->count();

                // Total hours worked.
                $totalHours = 0;
                foreach ($attendance as $record) {
                    if ($record->login_time && $record->logout_time) {
                        $loginTs = strtotime($record->attendance_date . ' ' . $record->login_time);
                        $logoutTs = strtotime($record->attendance_date . ' ' . $record->logout_time);
                        $totalHours += ($logoutTs - $loginTs) / 3600;
                    }
                }

                // Late + overtime — per-date + snapshot aware (SAME helper as the salary
                // calc and the web reports, so this store report agrees with all of them).
                $lateOt = $shiftService->sumLateOvertimeMinutes($user->user_id, $startDate, $effectiveEndDate);
                $lateDays = $lateOt['late_days'];
                $lateMinutes = $lateOt['late_minutes'];
                $overtimeDays = $lateOt['overtime_days'];
                $overtimeMinutes = $lateOt['overtime_minutes'];
                // TARGET-based overtime (worked beyond the shift length) — this IS "overtime"
                // on every manager screen (owner ruling Jul-28), because it is the work that
                // earns BONUS LEAVE. Bonus days come from the same service payroll grants
                // from, so mobile, web and the payslip always state the same thing.
                $otSvcMob = new \App\Services\HR\OvertimeService();
                $overtimeTargetMinutes = $otSvcMob
                    ->overtimeMinutes($user->user_id, $startDate, $effectiveEndDate);
                // Carry-aware (Sep-2026): identical to the web grid and the payslip.
                $overtimeBonusLeaves = $otSvcMob->bonusLeavesFor($user->user_id, $startDate, $effectiveEndDate, $overtimeTargetMinutes);

                // Calculate working days using ShiftResolutionService (same as web app),
                // only up to today for the current month.
                try {
                    $workingDays = $shiftService->calculateWorkingDays($user->user_id, $startDate, $effectiveEndDate);
                } catch (\Exception $e) {
                    $workingDays = \Carbon\Carbon::parse($startDate)->diffInDaysFiltered(function(\Carbon\Carbon $date) use ($effectiveEndDate) {
                        return $date->isWeekday() && $date->lte(\Carbon\Carbon::parse($effectiveEndDate));
                    }, \Carbon\Carbon::parse($effectiveEndDate));
                }
                
                // Absent uses the SAME canonical definition as payroll / the web Month tab / the
                // rider app (working-kind day, no login, no APPROVED leave — excludes not_needed via
                // dayKind), so this manager report can't disagree with the payroll deduction. Replaces
                // the old `working − present − leave` formula that ignored not_needed + off-day leaves.
                $absentDays = count((new \App\Services\HR\AttendanceYearService())
                    ->absentWorkingDates($user->user_id, $shiftService, $startDate, $effectiveEndDate));

                // Leave BALANCE for the configured cycle (single source of truth shared with web +
                // rider app) + the dated who/when/why adjustment history — so the manager sees
                // "consumed of total, left" and can tap for the breakdown. Replaces the old
                // calendar-year taken count that mismatched the balance everywhere else.
                $leavePolicy = new \App\Services\HR\LeavePolicyService();
                $leaveBal = $leavePolicy->balance((int) $user->user_id);
                $leaveAdjustments = $leavePolicy->adjustments((int) $user->user_id);
                $leaveTakenSplit = $leavePolicy->takenByType((int) $user->user_id);

                $monthlyData[] = [
                    'user_id' => $user->user_id,
                    'fullname' => $user->fullname,
                    'role_name' => $user->role_name,
                    'shift_name' => $resolvedShiftName,
                    'present_days' => $presentDays,
                    'absent_days' => max(0, $absentDays),
                    'leave_days' => $leaveDays,
                    'late_days' => $lateDays,
                    'late_minutes' => $lateMinutes,
                    // ⭐ Sep-2026 — `late_minutes` is NET of minutes a manager forgave. These two
                    // carry the split so this store report can explain a reduced figure, the
                    // same way the web Month tab and Payroll do. Additive: older APKs ignore them.
                    'late_waived_minutes' => (int) ($lateOt['late_waived_minutes'] ?? 0),
                    'late_raw_minutes' => (int) ($lateOt['late_raw_minutes'] ?? $lateMinutes),
                    'overtime_days' => $overtimeDays,
                    'overtime_minutes' => $overtimeMinutes,
                    'overtime_target_minutes' => $overtimeTargetMinutes,
                    'overtime_bonus_leaves' => $overtimeBonusLeaves,
                    'overtime_minutes_per_bonus' => $otSvcMob->minutesPerBonusDay(),
                    'office_checkouts_count' => (int) ($officeCheckoutCounts[$user->user_id] ?? 0), // R9.1 mobile
                    // Web-parity flag counts (one "Flags" group on the card) + missed meters.
                    'checkin_flag_days'  => (int) ($inFlagMap[$user->user_id]['days'] ?? 0),
                    'checkout_flag_days' => (int) ($outFlagMap[$user->user_id]['days'] ?? 0),
                    'meter_missed_days'  => (int) ($meterMissMap[$user->user_id]['days'] ?? 0),
                    // ⭐ Sep-30 — the web Month tab's "Off-duty km" (same engine). Additive: the
                    //   installed APK ignores both keys; the next APK renders them.
                    'offduty_km'     => $offDutyByUser[$user->user_id]['offduty_km'] ?? null,
                    'offduty_nights' => $offDutyByUser[$user->user_id]['nights'] ?? [],
                    'total_hours' => round($totalHours, 1),
                    'working_days' => $workingDays,
                    'attendance_percentage' => $workingDays > 0 ? round(($presentDays / $workingDays) * 100, 1) : 0,
                    // Back-compat scalars (old APKs) now reflect the configured cycle, not calendar year.
                    'leaves_taken_year' => $leaveBal['taken_total'],
                    'leaves_year' => (int) substr($leaveBal['cycle_start'], 0, 4),
                    // New (additive): full balance + dated adjustment history for the leave card.
                    'leave_balance' => $leaveBal,
                    'leave_adjustments' => $leaveAdjustments,
                    'leave_taken_split' => $leaveTakenSplit,
                ];
            }
            
            return response()->json([
                'success' => true,
                'month' => $month,
                'start_date' => $startDate,
                'end_date' => $endDate,
                'employees' => $monthlyData,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to get monthly attendance: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to load monthly attendance: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * NF LEDGER - Get list of accounts for transfer (source or destination)
     */
    public function getTransferAccounts(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_nf_ledger')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view NF Ledger'
                ], 403);
            }
            
            // Get all active accounts (company accounts only - cash and bank)
            $accounts = \App\Models\FIN\AccountModel::where('is_active', 1)
                ->whereIn('account_category', ['cash', 'bank'])
                ->orderBy('account_name', 'asc')
                ->get()
                ->map(function($account) {
                    return [
                        'id' => $account->id,
                        'account_code' => $account->account_code,
                        'account_name' => $account->account_name,
                        'account_category' => $account->account_category,
                        'account_type' => $account->account_type,
                        'current_balance' => $account->current_balance,
                    ];
                });
            
            return response()->json([
                'success' => true,
                'accounts' => $accounts,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to get transfer accounts: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to load accounts: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * NF LEDGER - Process account transfer
     * Reuses the same logic as web app
     */
    public function processTransfer(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_nf_ledger')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to process transfers'
                ], 403);
            }
            
            // Validate input
            $validator = \Validator::make($request->all(), [
                'from_account_id' => 'required|exists:t_fin_accounts,id',
                'to_account_id' => 'required|exists:t_fin_accounts,id|different:from_account_id',
                'amount' => 'required|numeric|min:0.01',
                'transaction_date' => 'required|date',
                'description' => 'required|string|max:500',
                'mode' => 'required|in:cash,online',
                // Which of OUR banks the transfer touches — required below when
                // either side is an ONLINE bank-category account.
                'receiving_account_id' => 'nullable|integer|exists:t_fin_online_receiving_accounts,id'
            ]);

            if ($validator->fails()) {
                return response()->json([
                    'success' => false,
                    'message' => 'Validation failed',
                    'errors' => $validator->errors()
                ], 422);
            }

            DB::beginTransaction();

            $fromAccount = \App\Models\FIN\AccountModel::findOrFail($request->from_account_id);
            $toAccount = \App\Models\FIN\AccountModel::findOrFail($request->to_account_id);

            // A transfer touching an ONLINE bank account must say WHICH bank so
            // per-bank balances reconcile (mirrors the web transfer form).
            $touchesBank = $fromAccount->account_category === \App\Models\FIN\AccountModel::CATEGORY_BANK
                || $toAccount->account_category === \App\Models\FIN\AccountModel::CATEGORY_BANK;
            $transferBankId = $touchesBank ? $request->input('receiving_account_id') : null;
            if ($touchesBank && !$transferBankId) {
                DB::rollBack();
                return response()->json([
                    'success' => false,
                    'message' => 'Select which bank this transfer goes through.'
                ], 422);
            }

            // Determine approval status.
            // Mirrors LedgerController::storeTransfer EXACTLY — an online transfer skips the queue
            // when its creator already holds every approval level `account_transfer` requires.
            // Both paths must agree: the same person entering the same transfer on the phone and
            // on the web has to get the same answer, or the mobile app becomes the way to create
            // rows that only the web can clear. (See SelfApprovalPolicy for the rule.)
            $selfApproved = $request->mode === 'online'
                && app(\App\Services\FIN\SelfApprovalPolicy::class)
                    ->canSelfApprove(\App\Models\FIN\LedgerModel::TYPE_TRANSFER, $user->id);

            $approvalStatus = ($request->mode === 'online' && !$selfApproved)
                ? \App\Models\FIN\LedgerModel::STATUS_PENDING
                : \App\Models\FIN\LedgerModel::STATUS_APPROVED;

            // Name the bank in the description for the ledger listing.
            $transferDescription = $request->description;
            if ($transferBankId) {
                $transferBankShort = \App\Models\FIN\OnlineReceivingAccountModel::find($transferBankId)?->short_code;
                if ($transferBankShort) {
                    $transferDescription .= " · via {$transferBankShort}";
                }
            }

            // Create ledger entry (self-approved rows are stamped — see the web path).
            $ledger = \App\Models\FIN\LedgerModel::create([
                'transaction_date' => $request->transaction_date,
                'transaction_type' => \App\Models\FIN\LedgerModel::TYPE_TRANSFER,
                'description' => $transferDescription,
                'from_account_id' => $fromAccount->id,
                'to_account_id' => $toAccount->id,
                'amount' => $request->amount,
                'mode' => $request->mode,
                'receiving_account_id' => $transferBankId,
                'approval_status' => $approvalStatus,
                'approval_date' => $selfApproved ? now()->toDateString() : null,
                'approved_by' => $selfApproved ? $user->id : null,
                'comments' => $selfApproved
                    ? app(\App\Services\FIN\SelfApprovalPolicy::class)
                        ->auditNote(\App\Models\FIN\LedgerModel::TYPE_TRANSFER, $user->id)
                    : null,
                'created_by' => $user->id
            ]);
            
            // Update balances (only if approved or cash).
            // Ledger L3: routed through the canonical gate (see LedgerController::store for
            // the full note). Sets balance_updated so a later reject/edit can reverse it,
            // and locks both account rows. Verified arithmetically identical to the old
            // inline code for every account pair this path produces (asset↔asset).
            if ($approvalStatus === \App\Models\FIN\LedgerModel::STATUS_APPROVED) {
                (new \App\Services\FIN\BalancePostingService())->apply($ledger);
            }
            
            DB::commit();
            
            $message = $approvalStatus === \App\Models\FIN\LedgerModel::STATUS_PENDING
                ? 'Transfer created and pending approval!'
                : ($selfApproved
                    ? 'Transfer completed and posted — no approval needed, you hold the rights for it.'
                    : 'Transfer completed successfully!');

            return response()->json([
                'success' => true,
                'message' => $message,
                'transfer' => [
                    'id' => $ledger->id,
                    'from_account' => $fromAccount->account_name,
                    'to_account' => $toAccount->account_name,
                    'amount' => $ledger->amount,
                    'mode' => $ledger->mode,
                    'approval_status' => $ledger->approval_status,
                ]
            ]);
            
        } catch (\Exception $e) {
            DB::rollBack();
            \Log::error('Mobile API - Failed to process transfer: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to process transfer: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * NF LEDGER - Get ledger details for a specific account
     * Shows transaction history with filtering options
     */
    public function getNFLedgerDetails(Request $request, $accountId)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_nf_ledger')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view NF Ledger'
                ], 403);
            }
            
            // Get the account
            $account = \App\Models\FIN\AccountModel::with('user')->find($accountId);
            
            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Account not found'
                ], 404);
            }
            
            // Block access to private accounts for non-Taimur users
            if ($account->is_private) {
                $isTaimurRole = $user->roles()->whereRaw('LOWER(urole_name) = ?', ['taimur'])->exists();
                if (!$isTaimurRole) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Account not found'
                    ], 404);
                }
            }
            
            // Get filter parameters
            $period = $request->input('period', 'all_time'); // today, this_week, this_month, all_time
            $daysPerPage = 30;
            
            // Build base query - INCLUDE APPROVED AND ALL PENDING LEVELS
            $baseQuery = \App\Models\FIN\LedgerModel::where(function($q) use ($accountId) {
                $q->where('from_account_id', $accountId)
                  ->orWhere('to_account_id', $accountId);
            })
            ->whereIn('approval_status', [
                \App\Models\FIN\LedgerModel::STATUS_APPROVED,
                \App\Models\FIN\LedgerModel::STATUS_PENDING,
                \App\Models\FIN\LedgerModel::STATUS_PENDING_L1,
                \App\Models\FIN\LedgerModel::STATUS_PENDING_L2,
            ]);
            
            // Determine date window based on period or date_end
            $useDateWindow = ($period === 'all_time');
            
            if ($useDateWindow) {
                $dateEndStr = $request->input('date_end');
                $dateEnd = $dateEndStr ? \Carbon\Carbon::parse($dateEndStr) : \Carbon\Carbon::today();
                $dateStart = $dateEnd->copy()->subDays($daysPerPage - 1);
                $windowStart = $dateStart->format('Y-m-d');
                $windowEnd = $dateEnd->format('Y-m-d');
                
                $ledgerQuery = (clone $baseQuery)
                    ->whereBetween('transaction_date', [$windowStart, $windowEnd]);
            } else {
                $ledgerQuery = clone $baseQuery;
                if ($period === 'today') {
                    $ledgerQuery->whereDate('transaction_date', today());
                } elseif ($period === 'this_week') {
                    $ledgerQuery->whereBetween('transaction_date', [now()->startOfWeek(), now()->endOfWeek()]);
                } elseif ($period === 'this_month') {
                    $ledgerQuery->whereBetween('transaction_date', [now()->startOfMonth(), now()->endOfMonth()]);
                }
            }
            
            // Transactions for the window, OLDEST FIRST so the running balance can be walked
            // forward from a known anchor (below). Flipped to newest-first for display after.
            $transactions = $ledgerQuery
                ->with(['fromAccount', 'toAccount', 'createdBy:id,fullname'])
                ->orderBy('transaction_date', 'asc')
                ->orderBy('id', 'asc')
                ->get();

            // Check if older records exist (for "Load Earlier" button)
            $hasMore = false;
            $nextDateEnd = null;
            if ($useDateWindow) {
                $hasMore = (clone $baseQuery)
                    ->where('transaction_date', '<', $windowStart)
                    ->exists();
                if ($hasMore) {
                    $nextDateEnd = \Carbon\Carbon::parse($windowStart)->subDay()->format('Y-m-d');
                }
            }

            // ⭐ Running balance per row — mirrors the web Ledger Hub
            // (HubController::buildAccountLedger) on purpose, so the same row can never print a
            // different balance on phone and on web. This endpoint previously computed NOTHING:
            // it assigned $currentBalance = $account->current_balance and then never used it,
            // so the mobile screen had no balance column at all.
            //
            // Walked FORWARD from opening_balance + everything that posted before this window —
            // NOT backward from current_balance. The stored balance is known to have drifted on
            // employee-cash accounts, and seeding a walk from a drifted anchor bends every row
            // above it. Only rows with balance_updated = 1 move it: that flag is the
            // posting/reversal guard, so a reversed or not-yet-posted row correctly carries the
            // balance forward unchanged.
            //
            // Employee-cash accounts get NO running balance, exactly as on the web, because
            // their true balance is a computed figure rather than this walk.
            $isEmployeeAcct = $account->account_category === \App\Models\FIN\AccountModel::CATEGORY_EMPLOYEE_CASH;
            $showRunning = !$isEmployeeAcct
                && $account->account_type === \App\Models\FIN\AccountModel::TYPE_ASSET;

            $seedBefore = null;
            if ($useDateWindow) {
                $seedBefore = $windowStart;
            } elseif ($period === 'today') {
                $seedBefore = today()->format('Y-m-d');
            } elseif ($period === 'this_week') {
                $seedBefore = now()->startOfWeek()->format('Y-m-d');
            } elseif ($period === 'this_month') {
                $seedBefore = now()->startOfMonth()->format('Y-m-d');
            }

            $running = null;
            if ($showRunning) {
                $preIn = 0.0;
                $preOut = 0.0;
                if ($seedBefore !== null) {
                    $preIn = (float) \App\Models\FIN\LedgerModel::where('to_account_id', $accountId)
                        ->where('balance_updated', 1)
                        ->where('transaction_date', '<', $seedBefore)->sum('amount');
                    $preOut = (float) \App\Models\FIN\LedgerModel::where('from_account_id', $accountId)
                        ->where('balance_updated', 1)
                        ->where('transaction_date', '<', $seedBefore)->sum('amount');
                }
                $running = (float) $account->opening_balance + $preIn - $preOut;
            }

            $ordered = [];
            foreach ($transactions as $txn) {
                $isDebit = $txn->from_account_id == $accountId;
                if ($running !== null && $txn->balance_updated) {
                    $running += $isDebit ? -(float) $txn->amount : (float) $txn->amount;
                }
                $ordered[] = ['txn' => $txn, 'is_debit' => $isDebit, 'balance_after' => $running];
            }

            // "Awaiting" = approval is still the thing standing between this money and the
            // balance. pending_l2 is NOT awaiting in that sense (L1 already posted the balance,
            // L2 only verifies), and balance_updated is consulted as a second opinion so a row
            // posted by some other route is never mis-filed. Same rule as the web.
            //
            // ⚠ This endpoint used to count ONLY 'approved' into the day totals, which meant
            // pending_l2 money that HAD moved the balance was missing from In/Out while sitting
            // inside the balance printed above it.
            $awaitingStatuses = [
                \App\Models\FIN\LedgerModel::STATUS_PENDING,
                \App\Models\FIN\LedgerModel::STATUS_PENDING_L1,
            ];

            $byDate = [];
            foreach (array_reverse($ordered) as $entry) {
                $txn = $entry['txn'];
                $isDebit = $entry['is_debit'];
                $amount = (float) $txn->amount;
                $txnDate = \Carbon\Carbon::parse($txn->transaction_date)->format('Y-m-d');

                if (!isset($byDate[$txnDate])) {
                    $byDate[$txnDate] = [
                        'date' => $txnDate,
                        'transactions' => [],
                        'total_in' => 0,
                        'total_out' => 0,
                        'total_pending' => 0,
                        'net_change' => 0,
                    ];
                }

                $isAwaiting = in_array($txn->approval_status, $awaitingStatuses, true)
                    && !$txn->balance_updated;

                $byDate[$txnDate]['transactions'][] = [
                    'id' => $txn->id,
                    'date' => $txn->transaction_date,
                    'created_at' => $txn->created_at ? $txn->created_at->toIso8601String() : null,
                    'type' => $txn->transaction_type,
                    // Was rendered client-side from an 8-entry map that lacked vendor_payment —
                    // so nearly every Frozen row read "📝 Transaction". Server-side now, from the
                    // one map, so phone and web say the same word.
                    'type_label' => \App\Models\FIN\LedgerModel::typeLabel($txn->transaction_type),
                    'description' => $txn->description,
                    'amount' => $amount,
                    'is_debit' => $isDebit,
                    'approval_status' => $txn->approval_status,
                    'is_pending' => $isAwaiting,
                    'balance_after' => $entry['balance_after'] !== null
                        ? round($entry['balance_after'], 2) : null,
                    'moved_by' => $txn->createdBy->fullname ?? 'System',
                    'other_account' => $isDebit ?
                        ($txn->toAccount ? $txn->toAccount->account_name : 'Unknown') :
                        ($txn->fromAccount ? $txn->fromAccount->account_name : 'Unknown'),
                    'reference_type' => $txn->reference_type,
                    'reference_id' => $txn->reference_id,
                ];

                if ($isAwaiting) {
                    $byDate[$txnDate]['total_pending'] += $amount;
                } elseif ($isDebit) {
                    $byDate[$txnDate]['total_out'] += $amount;
                } else {
                    $byDate[$txnDate]['total_in'] += $amount;
                }
            }

            foreach ($byDate as &$dayGroup) {
                // ⭐ EVERY group. This line used to sit after the loop and therefore ran only for
                // the LAST group — every other day rendered a green "+Rs. 0" next to a non-zero
                // In/Out row (the reported symptom).
                $dayGroup['net_change'] = $dayGroup['total_in'] - $dayGroup['total_out'];
            }
            unset($dayGroup);

            $groupedTransactions = array_values($byDate);
            
            // Calculate summary (only approved transactions)
            $totalIn = \App\Models\FIN\LedgerModel::where('to_account_id', $accountId)
                ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
                ->sum('amount');
            
            $totalOut = \App\Models\FIN\LedgerModel::where('from_account_id', $accountId)
                ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
                ->sum('amount');
            
            // Use effective balance: calculated for employee_cash, stored for others
            $effectiveBalance = $account->getEffectiveBalance();
            
            // Get loan and advance balances for employee accounts
            $loanBalance = 0;
            $advanceBalance = 0;
            if ($account->account_category === 'employee_cash' && $account->user_id) {
                // Get total outstanding loan balance
                $loanBalance = \App\Models\HR\EmployeeLoanModel::where('user_id', $account->user_id)
                    ->where('loan_status', 'active')
                    ->sum('outstanding_balance');
                
                // Get total pending salary advances (from approved but not settled requests)
                $advanceBalance = \App\Models\Request\RequestModel::where('requester_user_id', $account->user_id)
                    ->whereHas('category', function($q) {
                        $q->where('category_code', 'salary_advance');
                    })
                    ->where('status', 'approved')
                    ->where(function($q) {
                        $q->whereNull('settlement_status')
                          ->orWhere('settlement_status', '!=', 'settled');
                    })
                    ->get()->sum(fn ($a) => (float) $a->amount - (float) ($a->settled_amount ?? 0)); // still open (Sep-7)
            }
            
            // Get company accounts for petty cash source selection
            $companyAccounts = \App\Models\FIN\AccountModel::where('is_active', 1)
                ->where('account_category', '!=', 'employee_cash')
                ->whereIn('account_code', ['NF_CASH', 'ONLINE', 'EXP_FUND'])
                ->get(['id', 'account_code', 'account_name']);

            // ⏳ Same source as the web account page's "Waiting for approval" strip, so the two
            // can never disagree about how much is being held out of this balance. Non-fatal:
            // this is an informational banner, and it must never take the statement down with it.
            $pendingSummary = ['count' => 0, 'missing_in' => 0, 'missing_out' => 0, 'missing_net' => 0];
            try {
                $pa = app(\App\Services\FIN\PendingLedgerActionsService::class)
                    ->forAccount($account, $user->id);
                $pendingSummary = [
                    'count' => $pa['count'] ?? 0,
                    'missing_in' => $pa['missing_in'] ?? 0,
                    'missing_out' => $pa['missing_out'] ?? 0,
                    'missing_net' => $pa['missing_net'] ?? 0,
                ];
            } catch (\Exception $e) {
                \Log::warning('Mobile NF Ledger: pending actions unavailable: ' . $e->getMessage());
            }
            
            return response()->json([
                'success' => true,
                'account' => [
                    'id' => $account->id,
                    'account_code' => $account->account_code,
                    'account_name' => $account->account_name,
                    'account_category' => $account->account_category,
                    'current_balance' => $effectiveBalance,
                    'user_id' => $account->user_id,
                    'user_name' => $account->user ? ($account->user->fullname ?? $account->user->name) : null,
                    'petty_cash' => $account->petty_cash ?? 0,
                ],
                'summary' => [
                    'total_in' => $totalIn,
                    'total_out' => $totalOut,
                    'current_balance' => $effectiveBalance,
                    'loan_balance' => $loanBalance,
                    'advance_balance' => $advanceBalance,
                ],
                'grouped_transactions' => $groupedTransactions,
                // Lets the client hide the balance column rather than print a blank one on the
                // accounts where a forward walk is not the right answer (employee cash).
                'has_running_balance' => $showRunning,
                // ⏳ Money held OUT of the balance above by a pending approval. Deliberately
                // computed outside the date window — money stuck for months is exactly what the
                // window hides. Scalars only: approving from the phone is not offered here, so
                // the row list (and its web-only URLs) is not shipped.
                'pending_actions' => $pendingSummary,
                'company_accounts' => $companyAccounts,
                'pagination' => [
                    'has_more' => $hasMore,
                    'next_date_end' => $nextDateEnd,
                    'window_start' => $useDateWindow ? $windowStart : null,
                    'window_end' => $useDateWindow ? $windowEnd : null,
                ],
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Mobile API - Failed to get NF Ledger details: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to load ledger details: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * Update petty cash for an employee account
     * Only Taimur can modify, all can view
     */
    public function updatePettyCash(Request $request, $accountId)
    {
        try {
            $user = Auth::user();
            
            // Only Taimur can modify petty cash
            $isTaimur = strtolower($user->name ?? '') === 'taimur' || 
                        strtolower($user->fullname ?? '') === 'taimur' ||
                        strtolower($user->urole_name ?? '') === 'taimur';
            
            if (!$isTaimur) {
                return response()->json([
                    'success' => false,
                    'message' => 'Only Taimur can modify petty cash'
                ], 403);
            }
            
            $account = \App\Models\FIN\AccountModel::find($accountId);
            
            if (!$account) {
                return response()->json([
                    'success' => false,
                    'message' => 'Account not found'
                ], 404);
            }
            
            $amount = $request->input('amount', 0);
            $sourceType = $request->input('source_type', 'outside_cash');
            $sourceAccountId = $request->input('source_account_id');
            
            // Update petty cash
            $account->petty_cash = $amount;
            $account->save();
            
            // Log the change
            \Log::info('Petty cash updated', [
                'account_id' => $accountId,
                'amount' => $amount,
                'source_type' => $sourceType,
                'source_account_id' => $sourceAccountId,
                'updated_by' => $user->id,
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Petty cash updated successfully',
                'petty_cash' => $amount,
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to update petty cash: ' . $e->getMessage());
            return response()->json([
                'success' => false,
                'message' => 'Failed to update petty cash: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Get Overall Ledger Summary (for mobile app)
     * Reuses same logic as LedgerController for consistency
     */
    public function getOverallLedger(Request $request)
    {
        try {
            $user = Auth::user();
            
            // Check permission (reuse view_nf_ledger for now)
            if (!$user->hasMobilePermission('view_nf_ledger')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view Overall Ledger'
                ], 403);
            }
            
            // Get date range for filters (default to current month)
            $startDate = $request->input('start_date', now()->startOfMonth()->format('Y-m-d'));
            $endDate = $request->input('end_date', now()->endOfMonth()->format('Y-m-d'));
            
            // Check if user is Taimur (for private account filtering)
            $isTaimurRole = $user->roles()->whereRaw('LOWER(urole_name) = ?', ['taimur'])->exists();
            
            // Calculate KPIs (same logic as web app)
            $kpis = $this->calculateOverallLedgerKPIs($startDate, $endDate);
            
            // Get recent transactions (limited to 50 for mobile)
            $query = \App\Models\FIN\LedgerModel::with(['fromAccount', 'toAccount', 'order']);
            
            // Exclude transactions involving private accounts for non-Taimur
            if (!$isTaimurRole) {
                $privateAccountIds = \App\Models\FIN\AccountModel::where('is_private', 1)->pluck('id')->toArray();
                if (!empty($privateAccountIds)) {
                    $query->whereNotIn('from_account_id', $privateAccountIds)
                          ->whereNotIn('to_account_id', $privateAccountIds);
                }
            }
            
            // Filter by date range
            if ($startDate && $endDate) {
                $query->whereBetween('transaction_date', [$startDate, $endDate]);
            }
            
            // Apply filters if provided
            if ($request->has('type') && $request->input('type')) {
                $query->where('transaction_type', $request->input('type'));
            }
            
            if ($request->has('mode') && $request->input('mode')) {
                $query->where('mode', $request->input('mode'));
            }
            
            if ($request->has('status') && $request->input('status')) {
                $query->where('approval_status', $request->input('status'));
            }
            
            // Special vendor filter
            if ($request->has('vendor_filter') && $request->input('vendor_filter')) {
                $query->whereIn('transaction_type', [
                    \App\Models\FIN\LedgerModel::TYPE_VENDOR_PURCHASE,
                    \App\Models\FIN\LedgerModel::TYPE_VENDOR_PAYMENT
                ]);
            }
            
            $transactions = $query->orderBy('transaction_date', 'desc')
                                  ->orderBy('created_at', 'desc')
                                  ->limit(50)
                                  ->get()
                                  ->map(function($txn) {
                                      return [
                                          'id' => $txn->id,
                                          'date' => $txn->transaction_date->format('Y-m-d'),
                                          'type' => $txn->transaction_type,
                                          'type_label' => ucfirst(str_replace('_', ' ', $txn->transaction_type)),
                                          'from_account' => $txn->fromAccount ? $txn->fromAccount->account_name : 'N/A',
                                          'to_account' => $txn->toAccount ? $txn->toAccount->account_name : 'N/A',
                                          'description' => $txn->description,
                                          'amount' => $txn->amount,
                                          'amount_formatted' => 'Rs. ' . number_format($txn->amount, 2),
                                          'mode' => $txn->mode,
                                          'approval_status' => $txn->approval_status,
                                      ];
                                  });
            
            return response()->json([
                'success' => true,
                'kpis' => $kpis,
                'transactions' => $transactions,
                'date_range' => [
                    'start_date' => $startDate,
                    'end_date' => $endDate
                ]
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get overall ledger', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load overall ledger: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * Calculate Overall Ledger KPIs (reuses LedgerController logic).
     *
     * This is the store-mode operational settlement view on mobile.
     * Phase 6 — Qurbani is excluded across the board because the
     * Qurbani delivery flow deliberately skips posting an INVOICE
     * ledger row (see OrderModel:1465 — `hasPreReceivedPayments()`
     * guard). Qurbani payments are collected via the rider/manager
     * add-payment flow and post their own ledger rows against the
     * dedicated Qurbani Cash / Qurbani Online accounts. Including
     * Qurbani delivered orders here would create phantom
     * "Cash Pending With Rider" because there's no ledger
     * settlement row to offset them.
     */
    private function calculateOverallLedgerKPIs($startDate, $endDate)
    {
        $invoicesQuery = \DB::table('t_crm_order_status_history as h')
            ->leftJoin('t_crm_prod_order as o', 'o.id', '=', 'h.order_id')
            ->where('h.status_code', 'delivered')
            ->where('h.is_current', 1)
            ->tap(function ($q) {
                \App\Services\QurbaniFinanceFilter::applyToOrderQuery(
                    $q, 'o', \App\Services\QurbaniFinanceFilter::MODE_EXCLUDE
                );
            });

        if ($startDate && $endDate) {
            $invoicesQuery->whereBetween('h.changed_at', [$startDate, $endDate]);
        }

        $deliveredOrderIds = $invoicesQuery->pluck('h.order_id');
        
        // === KPI 1: INVOICES ===
        $totalInvoices = \DB::table('t_crm_prod_order')
            ->whereIn('id', $deliveredOrderIds)
            ->sum('total_price') ?? 0;
        
        $invoicesCash = \DB::table('t_crm_prod_order')
            ->whereIn('id', $deliveredOrderIds)
            ->whereIn('payment_method', ['cash', 'cash_on_delivery', 'Cash', 'COD'])
            ->sum('total_price') ?? 0;
        
        $nfCashAccount = \App\Models\FIN\AccountModel::where('account_code', 'NF_CASH')->first();
        $cashDeposits = 0;
        $shortCashTotal = 0;
        
        if ($nfCashAccount) {
            $cashDeposits = \App\Models\FIN\LedgerModel::where('to_account_id', $nfCashAccount->id)
                ->where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_EMPLOYEE_DEPOSIT)
                ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
                ->whereBetween('transaction_date', [$startDate, $endDate])
                ->sum('amount') ?? 0;
            
            $shortCashTotal = \App\Models\Request\RequestModel::where('status', 'approved')
                ->whereHas('category', function($q) {
                    $q->where('category_code', 'expense');
                })
                ->whereHas('paymentSourceAccount', function($q) {
                    $q->where('account_category', 'employee_cash');
                })
                ->whereBetween('created_at', [$startDate, $endDate])
                ->sum('amount') ?? 0;
        }
        
        $invoicesOnline = \DB::table('t_crm_prod_order')
            ->whereIn('id', $deliveredOrderIds)
            ->whereIn('payment_method', ['online', 'Online', 'bank_transfer', 'card', 'online_payment'])
            ->sum('total_price') ?? 0;
        
        // === ONLINE INVOICES: Enhanced with L1/L2 split (matching web LedgerController) ===
        $onlineAccount = \App\Models\FIN\AccountModel::where('account_code', 'ONLINE')->first();
        $onlineInvoiceLedgersQuery = \App\Models\FIN\LedgerModel::where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_INVOICE)
            ->where('approval_status', '!=', \App\Models\FIN\LedgerModel::STATUS_REVERSED)
            ->whereBetween('transaction_date', [$startDate, $endDate]);
        
        if ($onlineAccount) {
            $onlineInvoiceLedgersQuery->where('to_account_id', $onlineAccount->id);
        }
        
        $onlineInvoiceLedgers = $onlineInvoiceLedgersQuery->get();
        
        $onlineApproved = $onlineInvoiceLedgers
            ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
            ->sum('amount');
        
        // Split pending by approval level (L1 vs L2)
        // Legacy 'pending' status is treated as pending_l1
        $onlinePendingL1 = $onlineInvoiceLedgers
            ->filter(function ($invoice) {
                return in_array($invoice->approval_status, [
                    \App\Models\FIN\LedgerModel::STATUS_PENDING,      // Legacy: treat as L1
                    \App\Models\FIN\LedgerModel::STATUS_PENDING_L1,
                ], true);
            })
            ->sum('amount');
        
        $onlinePendingL2 = $onlineInvoiceLedgers
            ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_PENDING_L2)
            ->sum('amount');
        
        // Total pending (for backward compatibility)
        $onlinePending = $onlinePendingL1 + $onlinePendingL2;
        
        // === KPI 2: EXPENSES ===
        // Phase 6 — Qurbani-tagged ledger rows excluded.
        $ledgerExpenses = \App\Models\FIN\LedgerModel::where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_EXPENSE)
            ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
            ->whereBetween('transaction_date', [$startDate, $endDate])
            ->tap(function ($q) {
                \App\Services\QurbaniFinanceFilter::applyToLedgerQuery(
                    $q, 't_fin_ledger', \App\Services\QurbaniFinanceFilter::MODE_EXCLUDE
                );
            })
            ->sum('amount') ?? 0;
        
        $salaryExpenses = \App\Models\HR\SalarySlipModel::whereIn('slip_status', ['approved', 'paid'])
            ->whereNotNull('ledger_transaction_id')
            ->whereBetween('created_at', [$startDate, $endDate])
            ->sum('net_salary') ?? 0;
        
        $totalExpenses = $ledgerExpenses + $salaryExpenses;
        
        $expensesNeedingSettlement = \App\Models\Request\RequestModel::where('status', 'approved')
            ->where('settlement_status', 'pending')
            ->whereHas('category', function($q) {
                $q->where('category_code', 'expense');
            })
            ->whereBetween('created_at', [$startDate, $endDate])
            ->sum('amount') ?? 0;
        
        // === KPI 3: VENDOR BALANCE ===
        // Phase 6 — Qurbani vendor activity excluded.
        $vendorPurchases = \App\Models\FIN\LedgerModel::where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_VENDOR_PURCHASE)
            ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
            ->whereBetween('transaction_date', [$startDate, $endDate])
            ->tap(function ($q) {
                \App\Services\QurbaniFinanceFilter::applyToLedgerQuery(
                    $q, 't_fin_ledger', \App\Services\QurbaniFinanceFilter::MODE_EXCLUDE
                );
            })
            ->sum('amount') ?? 0;

        $vendorPayments = \App\Models\FIN\LedgerModel::where('transaction_type', \App\Models\FIN\LedgerModel::TYPE_VENDOR_PAYMENT)
            ->where('approval_status', \App\Models\FIN\LedgerModel::STATUS_APPROVED)
            ->whereBetween('transaction_date', [$startDate, $endDate])
            ->tap(function ($q) {
                \App\Services\QurbaniFinanceFilter::applyToLedgerQuery(
                    $q, 't_fin_ledger', \App\Services\QurbaniFinanceFilter::MODE_EXCLUDE
                );
            })
            ->sum('amount') ?? 0;
        
        $vendorBalance = $vendorPurchases - $vendorPayments;
        
        // === KPI 4: NF PROFIT ===
        $profit = $totalInvoices - $totalExpenses - $vendorPurchases;
        
        return [
            'total_invoices' => round($totalInvoices, 2),
            'invoices_cash' => round($invoicesCash, 2),
            'cash_deposits' => round($cashDeposits, 2),
            'short_cash_total' => round($shortCashTotal, 2),
            'invoices_online' => round($invoicesOnline, 2),
            'online_approved' => round($onlineApproved, 2),
            'online_pending' => round($onlinePending, 2),
            'online_pending_l1' => round($onlinePendingL1, 2), // NEW: Pending L1 split
            'online_pending_l2' => round($onlinePendingL2, 2), // NEW: Pending L2 split
            'total_expenses' => round($totalExpenses, 2),
            'regular_expenses' => round($ledgerExpenses, 2),
            'salary_expenses' => round($salaryExpenses, 2),
            'expenses_needing_settlement' => round($expensesNeedingSettlement, 2),
            'vendor_balance' => round($vendorBalance, 2),
            'vendor_purchases' => round($vendorPurchases, 2),
            'vendor_payments' => round($vendorPayments, 2),
            'profit' => round($profit, 2),
        ];
    }

    /**
     * Get Daily Closing Summary (Invoice Tracker for mobile app)
     * Replicates web app's EmployeeCashController::allOutstandingInvoices logic
     */
    /**
     * [1B — Delivered-but-unposted reconciliation] Read-only list of orders that were delivered
     * but never got their invoice posted to the ledger. Surfaced in Daily Closing so a silent
     * posting failure can't hide until a month-end mismatch. Self-healing: an order drops off the
     * moment its invoice exists, because this reads live `ledger_transaction_id`, not a stored flag.
     *
     * Scope MIRRORS LedgerPostingService's own skip rules so it never false-flags:
     *   • delivered, with no ledger_transaction_id (the authoritative "invoice posted" marker);
     *   • excludes qurbani orders and shop-customer online orders (both settle via order_payment,
     *     never a full invoice — posting is intentionally skipped for them);
     *   • windowed to recent deliveries (default 7 days) with a grace period (default 10 min) so an
     *     order posted moments ago isn't flagged mid-post, and the thousands of legacy pre-auto-post
     *     orders (which never had a ledger entry) are never surfaced.
     * If global auto-posting is OFF, reports that state instead of flagging every delivery.
     */
    public function getUnpostedInvoices(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('view_daily_closing')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view Daily Closing'
                ], 403);
            }

            // If automatic posting is globally disabled, posting is skipped for everyone by design —
            // don't flag every delivery, just report the state.
            $autoPost = \App\Models\FIN\ConfigModel::where('config_key', 'LEDGER_AUTO_POST_ENABLED')->value('config_value');
            if ($autoPost !== '1') {
                return response()->json([
                    'success' => true,
                    'auto_post_enabled' => false,
                    'count' => 0,
                    'orders' => [],
                    'message' => 'Automatic ledger posting is currently OFF — unposted deliveries are expected.',
                ]);
            }

            $windowDays = max(1, min(30, (int) $request->get('window_days', 7)));
            $graceMinutes = max(0, (int) $request->get('grace_minutes', 10));
            $onlineMethods = ['online', 'Online', 'bank_transfer', 'card', 'online_payment'];
            $windowStart = now()->subDays($windowDays)->toDateTimeString();
            $graceEnd = now()->subMinutes($graceMinutes)->toDateTimeString();

            $orders = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_order_status_history as h', function ($j) {
                    $j->on('h.order_id', '=', 'o.id')->where('h.status_code', 'delivered');
                })
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->where('o.order_status', 'delivered')
                ->whereNull('o.ledger_transaction_id')
                ->whereNull('o.qurbani_day')->whereNull('o.qurbani_slot')
                ->whereNull('o.qurbani_region')->whereNull('o.qurbani_delivery_type')
                ->where(function ($q) use ($onlineMethods) {
                    // Keep everything EXCEPT shop customers paying online (settled incrementally).
                    $q->where('c.customer_type', '!=', 'shop')
                      ->orWhereNull('c.customer_type')
                      ->orWhereNotIn('o.payment_method', $onlineMethods);
                })
                // Mirror OrderModel::hasPreReceivedPayments(): orders paid in advance via
                // incremental payments intentionally get NO invoice entry (their money is already
                // in the ledger as order_payment rows) — never flag them as "missing".
                ->whereNotExists(function ($q) {
                    $q->select(\DB::raw(1))
                      ->from('t_crm_order_payments as op')
                      ->whereColumn('op.order_id', 'o.id')
                      ->where('op.status', 'active');
                })
                ->groupBy('o.id', 'o.order_number', 'o.name', 'o.payment_method', 'o.total_price', 'o.assigned_rider_user_id')
                ->havingRaw('MAX(h.changed_at) >= ? AND MAX(h.changed_at) <= ?', [$windowStart, $graceEnd])
                ->select('o.id', 'o.order_number', 'o.name', 'o.payment_method', 'o.total_price', 'o.assigned_rider_user_id')
                ->selectRaw('MAX(h.changed_at) as delivered_at')
                ->orderByDesc('delivered_at')
                ->get();

            return response()->json([
                'success' => true,
                'auto_post_enabled' => true,
                'window_days' => $windowDays,
                'count' => $orders->count(),
                'orders' => $orders,
            ]);
        } catch (\Exception $e) {
            \Log::error('getUnpostedInvoices failed: ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Failed to load unposted invoices'], 500);
        }
    }

    /**
     * [1B — repost] Retry posting a single delivered order's invoice to the ledger. Thin wrapper
     * over the SAME LedgerPostingService the delivery flow uses, so it can't diverge from the
     * delivery-time rules and is idempotent (early ledger_transaction_id check + row lock + unique
     * index → a second post is a no-op, never a duplicate). Returns the service's own reason on
     * failure so the user sees WHY (e.g. sales account misconfigured, no NF Cash account).
     */
    public function repostOrderInvoice(Request $request, $orderId)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('view_daily_closing')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to repost invoices'
                ], 403);
            }

            $order = \App\Models\CRM\OrderModel::with('customer')->find($orderId);
            if (!$order) {
                return response()->json(['success' => false, 'message' => 'Order not found'], 404);
            }
            if ($order->ledger_transaction_id) {
                return response()->json([
                    'success' => true,
                    'already_posted' => true,
                    'message' => 'Invoice is already posted to the ledger.',
                    'order_number' => $order->order_number,
                ]);
            }

            // GUARD (mirrors OrderModel's delivery-time check): an order with active pre-received
            // payments is settled via order_payment ledger entries — posting a full invoice on top
            // would DOUBLE-BOOK the money (the QUR26-607 bug class). The delivery flow skips these
            // before calling the service; the repost path must skip them too.
            if ($order->hasPreReceivedPayments()) {
                return response()->json([
                    'success' => true,
                    'already_posted' => true,
                    'message' => 'This order is settled via incremental payments — no invoice entry is needed.',
                    'order_number' => $order->order_number,
                ]);
            }

            $result = (new \App\Services\FIN\LedgerPostingService())->postInvoiceFromOrder($order);

            return response()->json([
                'success' => (bool) ($result['success'] ?? false),
                'message' => $result['message'] ?? 'Unknown result',
                'order_number' => $order->order_number,
                'ledger_id' => $result['ledger_id'] ?? null,
            ]);
        } catch (\Exception $e) {
            \Log::error('repostOrderInvoice failed for order ' . $orderId . ': ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Failed to repost invoice: ' . $e->getMessage()], 500);
        }
    }

    public function getDailyClosing(Request $request)
    {
        try {
            $user = Auth::user();

            // Check permission
            if (!$user->hasMobilePermission('view_daily_closing')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to view Daily Closing'
                ], 403);
            }
            
            // Get filter parameters (same as web app)
            $statusFilter = $request->get('status', 'all'); // all, open, partial, settled
            $riderFilter = $request->get('rider', 'all');
            $dateFrom = $request->get('date_from');
            $dateTo = $request->get('date_to');
            // ⭐ New parameters: group_by (default 'date') and include_online (default true)
            $groupBy = $request->get('group_by', 'date'); // 'date' (default) or 'rider'
            $includeOnline = !$request->has('include_online') || $request->get('include_online') === '1';
            
            // Base query for ALL invoices (not just open)
            // IMPORTANT: Exclude reversed transactions (e.g., from payment method changes)
            // Includes both regular invoices AND qurbani order_payment entries that go to rider accounts
            $invoicesQuery = LedgerModel::whereIn('transaction_type', [LedgerModel::TYPE_INVOICE, LedgerModel::TYPE_ORDER_PAYMENT])
                ->where('approval_status', '!=', LedgerModel::STATUS_REVERSED)
                ->with(['toAccount', 'order'])
                ->whereHas('toAccount', function($q) {
                    $q->where('account_category', AccountModel::CATEGORY_EMPLOYEE_CASH);
                });
            
            // Apply date filters
            if ($dateFrom) {
                $invoicesQuery->where('transaction_date', '>=', $dateFrom);
            }
            if ($dateTo) {
                $invoicesQuery->where('transaction_date', '<=', $dateTo);
            }
            
            // Apply rider filter
            if ($riderFilter !== 'all') {
                $invoicesQuery->where('to_account_id', $riderFilter);
            }
            
            // Get all invoices
            $allInvoices = $invoicesQuery->orderBy('transaction_date', 'desc')->get();

            // Sep-2026 (same as web Daily Closing): an unsettled row with nothing left to
            // collect (Rs 0 free / replacement order) is not owed — keep it out of open/partial.
            $allInvoices = $allInvoices->reject(function($invoice) {
                return $invoice->settlement_status !== 'settled'
                    && round((float) $invoice->amount - (float) ($invoice->settled_amount ?? 0), 2) < 0.01;
            });

            // Separate into categories (EXACT web app logic)
            $openInvoices = $allInvoices->filter(function($invoice) {
                return $invoice->settlement_status === 'open' && ($invoice->settled_amount ?? 0) == 0;
            });
            
            $partialInvoices = $allInvoices->filter(function($invoice) {
                return $invoice->settlement_status === 'partial' || 
                       ($invoice->settlement_status === 'open' && ($invoice->settled_amount ?? 0) > 0);
            });
            
            $settledInvoices = $allInvoices->filter(function($invoice) {
                return $invoice->settlement_status === 'settled';
            });
            
            // Get pending settlement deposits (settlements awaiting approval)
            // Include both "Settlement" and "Partial Payment" descriptions
            $pendingSettlements = LedgerModel::where('transaction_type', LedgerModel::TYPE_EMPLOYEE_DEPOSIT)
                ->where('approval_status', LedgerModel::STATUS_PENDING)
                ->where(function($q) {
                    $q->where('description', 'LIKE', '%Settlement%')
                      ->orWhere('description', 'LIKE', '%Partial Payment%');
                })
                ->with(['fromAccount'])
                ->orderBy('created_at', 'desc')
                ->get();
            
            // Enhance pending settlements with invoice details from metadata
            $pendingSettlements = $pendingSettlements->map(function($settlement) {
                // Try ledger metadata first (NEW), fallback to session (OLD)
                $settlementData = $settlement->settlement_metadata;
                
                if ($settlementData && isset($settlementData['invoice_ids'])) {
                    $settlement->invoice_ids = $settlementData['invoice_ids'];
                    $settlement->total_outstanding = $settlementData['total_outstanding'];
                    
                    // Get the actual invoice records for display
                    $settlement->invoices = LedgerModel::whereIn('id', $settlementData['invoice_ids'])
                        ->with('order')
                        ->orderBy('transaction_date', 'asc')
                        ->get()
                        ->map(function($invoice) {
                            return [
                                'id' => $invoice->id,
                                'order_number' => $invoice->order ? $invoice->order->order_number : 'N/A',
                                'transaction_date' => $invoice->transaction_date->format('Y-m-d'),
                                'description' => $invoice->description,
                                'amount' => $invoice->amount,
                                'settled_amount' => $invoice->settled_amount ?? 0,
                                'outstanding_amount' => $invoice->amount - ($invoice->settled_amount ?? 0)
                            ];
                        });
                } else {
                    $settlement->invoice_ids = [];
                    $settlement->invoices = collect();
                    $settlement->total_outstanding = 0;
                }
                
                return $settlement;
            });
            
            // Apply status filter for display
            $displayInvoices = collect();
            switch ($statusFilter) {
                case 'open':
                    $displayInvoices = $openInvoices;
                    break;
                case 'partial':
                    $displayInvoices = $partialInvoices;
                    break;
                case 'settled':
                    $displayInvoices = $settledInvoices;
                    break;
                default:
                    $displayInvoices = $openInvoices->concat($partialInvoices);
            }
            
            // Create a map of invoice IDs to their pending settlement IDs
            $invoiceToPendingSettlement = [];
            foreach ($pendingSettlements as $settlement) {
                foreach ($settlement->invoice_ids as $invoiceId) {
                    $invoiceToPendingSettlement[$invoiceId] = $settlement->id;
                }
            }
            
            // Group pending settlements by rider (from_account_id)
            $settlementsByRider = $pendingSettlements->groupBy('from_account_id');
            
            // Jun-2026 — Payment-proof badges keyed by order_id (bulk, no N+1).
            $paymentProofMap = [];
            if (config('payment_signals.enabled')) {
                $proofOrderIds = $displayInvoices->map(fn($inv) => $inv->order?->id)
                    ->filter()->unique()->values()->all();
                if (!empty($proofOrderIds)) {
                    // Daily Closing is a RECORD surface — keep proof/verified
                    // badges after approval (suppressSettled: false).
                    $paymentProofMap = app(\App\Services\Payments\Signals\PaymentProofStatusService::class)
                        ->forOrders($proofOrderIds, suppressSettled: false);
                }
            }
            
            // Group by rider for display
            // Latest cash-held confirmation per rider (he confirmed / flagged the
            // cash at check-out), keyed by user_id. Non-fatal.
            $cashConfirmMap = collect();
            try {
                $riderUserIds = $displayInvoices->map(fn($inv) => $inv->toAccount?->user_id)->filter()->unique()->values()->all();
                if (!empty($riderUserIds) && \Schema::hasColumn('t_ops_attendance', 'cash_confirm_status')) {
                    $cashConfirmMap = \DB::table('t_ops_attendance')
                        ->whereIn('user_id', $riderUserIds)
                        ->whereNotNull('cash_confirmed_at')
                        ->orderBy('cash_confirmed_at', 'desc')
                        ->get(['user_id', 'cash_confirmed_amount', 'cash_confirmed_at', 'cash_confirm_status'])
                        ->groupBy('user_id')
                        ->map(fn($rows) => $rows->first());
                }
            } catch (\Throwable $e) {
                $cashConfirmMap = collect();
            }

            $invoicesByRider = $displayInvoices->groupBy('to_account_id')->map(function($riderInvoices) use ($invoiceToPendingSettlement, $settlementsByRider, $paymentProofMap, $cashConfirmMap) {
                $account = $riderInvoices->first()->toAccount;
                $totalOutstanding = $riderInvoices->sum(function($invoice) {
                    return $invoice->amount - ($invoice->settled_amount ?? 0);
                });
                
                // Get pending settlements for this rider
                $riderSettlements = $settlementsByRider->get($account->id, collect());
                
                return [
                    'account' => [
                        'id' => $account->id,
                        'account_name' => $account->account_name,
                        'account_code' => $account->account_code
                    ],
                    'pending_settlements' => $riderSettlements->map(function($settlement) {
                        return [
                            'id' => $settlement->id,
                            'amount' => $settlement->amount,
                            'created_at' => $settlement->created_at->format('Y-m-d H:i:s'),
                            'description' => $settlement->description,
                            'invoice_ids' => $settlement->invoice_ids,
                            'invoices' => $settlement->invoices,
                            'total_outstanding' => $settlement->total_outstanding
                        ];
                    })->values(),
                    'invoices' => $riderInvoices->map(function($invoice) use ($invoiceToPendingSettlement, $paymentProofMap) {
                        $isPendingApproval = isset($invoiceToPendingSettlement[$invoice->id]);
                        $pendingSettlementId = $isPendingApproval ? $invoiceToPendingSettlement[$invoice->id] : null;
                        $invoiceOrderId = $invoice->order?->id;
                        
                        return [
                            'id' => $invoice->id,
                            'order_id' => $invoiceOrderId,
                            'order_number' => $invoice->order ? $invoice->order->order_number : 'N/A',
                            'customer_name' => $invoice->order ? $invoice->order->customer_name : null,
                            'transaction_date' => $invoice->transaction_date->format('Y-m-d'),
                            'is_pending_approval' => $isPendingApproval,
                            'pending_settlement_id' => $pendingSettlementId,
                            'description' => $invoice->description,
                            'amount' => $invoice->amount,
                            'settled_amount' => $invoice->settled_amount ?? 0,
                            'outstanding_amount' => $invoice->amount - ($invoice->settled_amount ?? 0),
                            'settlement_status' => $invoice->settlement_status,
                            'settled_at' => $invoice->settled_at ? $invoice->settled_at->format('Y-m-d H:i:s') : null,
                            'payment_proof' => ($invoiceOrderId && isset($paymentProofMap[$invoiceOrderId]))
                                ? $paymentProofMap[$invoiceOrderId]
                                : null,
                        ];
                    })->values(),
                    'total_outstanding' => $totalOutstanding,
                    'invoice_count' => $riderInvoices->count(),
                    'cash_confirmation' => $cashConfirmMap->get($account->user_id) ?? null,
                ];
            })->values();
            
            // === Calculate Pending Approvals for Expense Requests ===
            // Use same logic as NF Cash: pending expenses that will affect NF Cash
            $nfCashAccount = AccountModel::where('account_code', 'NF_CASH')->first();
            
            $pendingApprovalsQuery = RequestModel::where('status', 'pending')
                ->whereHas('category', function($q) {
                    $q->where('category_code', 'expense');
                });
            
            // NF Cash logic: explicit NF Cash assignments OR paid from any rider balance
            if ($nfCashAccount) {
                $pendingApprovalsQuery->where(function($q) use ($nfCashAccount) {
                    $q->where('payment_source_account_id', $nfCashAccount->id)
                      ->orWhereHas('paymentSourceAccount', function($subQ) {
                          $subQ->where('account_category', 'employee_cash');
                      });
                });
            }
            
            // Apply date filters if provided
            if ($dateFrom) {
                $pendingApprovalsQuery->where('created_at', '>=', $dateFrom);
            }
            if ($dateTo) {
                $pendingApprovalsQuery->where('created_at', '<=', $dateTo);
            }
            
            $pendingApprovalsAmount = $pendingApprovalsQuery->sum('amount') ?? 0;
            $pendingApprovalsCount = $pendingApprovalsQuery->count();
            
            // === Calculate Short Cash ===
            // Approved expenses paid from rider balance but not yet settled
            $shortCashQuery = RequestModel::where('status', 'approved')
                ->where('settlement_status', 'pending')
                ->whereHas('category', function($q) {
                    $q->where('category_code', 'expense');
                })
                ->whereHas('paymentSourceAccount', function($q) {
                    $q->where('account_category', 'employee_cash');
                });
            
            // Apply date filters if provided
            if ($dateFrom) {
                $shortCashQuery->where('created_at', '>=', $dateFrom);
            }
            if ($dateTo) {
                $shortCashQuery->where('created_at', '<=', $dateTo);
            }
            
            $shortCashAmount = $shortCashQuery->sum('amount') ?? 0;
            $shortCashCount = $shortCashQuery->count();
            
            // Calculate summary stats (EXACT web app logic)
            $stats = [
                'open_count' => $openInvoices->count(),
                'open_total' => $openInvoices->sum(function($inv) {
                    return $inv->amount - ($inv->settled_amount ?? 0);
                }),
                'partial_count' => $partialInvoices->count(),
                'partial_total' => $partialInvoices->sum(function($inv) {
                    return $inv->amount - ($inv->settled_amount ?? 0);
                }),
                'pending_settlement_count' => $pendingSettlements->count(),
                'pending_settlement_total' => $pendingSettlements->sum('amount'),
                'settled_count' => $settledInvoices->count(),
                'settled_total' => $settledInvoices->sum('amount'),
                'total_outstanding' => $openInvoices->sum(function($inv) {
                    return $inv->amount - ($inv->settled_amount ?? 0);
                }) + $partialInvoices->sum(function($inv) {
                    return $inv->amount - ($inv->settled_amount ?? 0);
                }),
                'pending_approvals_count' => $pendingApprovalsCount,
                'pending_approvals_amount' => $pendingApprovalsAmount,
                'short_cash_count' => $shortCashCount,
                'short_cash_amount' => $shortCashAmount
            ];
            
            // === Pending Petrol Requests for Daily Closing (auto + manual) ===
            $pendingPetrolQuery = RequestModel::where('status', 'pending')
                ->whereHas('category', function($q) {
                    $q->where('category_code', 'expense');
                })
                ->where('expense_category', 'Petrol')
                ->with(['requester']);

            if ($dateFrom) {
                $pendingPetrolQuery->where('expense_date', '>=', $dateFrom);
            }
            if ($dateTo) {
                $pendingPetrolQuery->where('expense_date', '<=', $dateTo);
            }

            $pendingPetrolRequests = $pendingPetrolQuery->orderBy('expense_date', 'desc')->get();

            $base = request()->getSchemeAndHttpHost();

            // ⭐ WHICH MACHINE THIS MONEY IS FOR — personal bike / company bike / van, plus
            //   the plate. Same keys and the SAME composed words the web Daily Closing pane
            //   and the Month view popup use (VehicleResolver::machineChip), so the phone
            //   and the browser can never describe one claim two different ways.
            // ⚠ Additive keys only — an installed APK that does not know them renders as
            //   before. ⚠ SCHEMA-GUARDED: `vehicle_id` was hand-applied to t_req_master.
            $hasVehicleCol = \Illuminate\Support\Facades\Schema::hasColumn('t_req_master', 'vehicle_id');
            $vehResolver   = new \App\Services\Riders\VehicleResolver();
            $machineFields = function ($req) use ($hasVehicleCol, $vehResolver) {
                return $vehResolver->machineChipFields(
                    $hasVehicleCol && $req->vehicle_id !== null ? (int) $req->vehicle_id : null
                );
            };

            $petrolRequestsData = $pendingPetrolRequests->map(function($req) use ($base, $machineFields) {
                $attachmentUrl = null;
                if ($req->attachments && is_array($req->attachments) && count($req->attachments) > 0) {
                    $attachmentUrl = rtrim($base, '/') . '/public-storage/' . ltrim($req->attachments[0], '/');
                }
                return $machineFields($req) + [
                    'id' => $req->id,
                    'request_number' => $req->request_number,
                    'rider_name' => $req->requester ? $req->requester->fullname : 'Unknown',
                    'requester_user_id' => $req->requester_user_id,
                    'expense_date' => $req->expense_date ? $req->expense_date->format('Y-m-d') : null,
                    'expense_date_formatted' => $req->expense_date ? $req->expense_date->format('D, M d') : null,
                    'meter_distance' => (float) $req->meter_distance,
                    'petrol_rate' => (float) $req->petrol_rate,
                    'amount' => (float) $req->amount,
                    'status' => $req->status,
                    'description' => $req->description,
                    'source' => $req->attendance_id ? 'meter' : 'manual',
                    // What it was FILED against, so the approve row can pre-select it
                    // instead of defaulting to NF Cash and silently rebooking it.
                    'filed_source_id' => $req->payment_source_account_id,
                    'filed_bank_id' => $req->receiving_account_id,
                    'attachment_url' => $attachmentUrl,
                    'created_at' => $req->created_at ? $req->created_at->format('Y-m-d H:i:s') : null,
                ];
            })->values();

            $stats['petrol_requests_count'] = $petrolRequestsData->count();
            $stats['petrol_requests_amount'] = $petrolRequestsData->sum('amount');

            // 🔧 Pending MAINTENANCE requests — shown alongside petrol on the closing screen (R10).
            // Same shape + approval path; source is always 'manual' (no attendance link).
            $maintQuery = RequestModel::where('status', 'pending')
                ->whereHas('category', function ($q) { $q->where('category_code', 'expense'); })
                ->where('expense_category', 'Maintenance')
                ->with(['requester']);
            if ($dateFrom) { $maintQuery->where('expense_date', '>=', $dateFrom); }
            if ($dateTo)   { $maintQuery->where('expense_date', '<=', $dateTo); }
            $maintenanceRequestsData = $maintQuery->orderBy('expense_date', 'desc')->get()->map(function ($req) use ($base, $machineFields) {
                $attachmentUrl = null;
                if ($req->attachments && is_array($req->attachments) && count($req->attachments) > 0) {
                    $attachmentUrl = rtrim($base, '/') . '/public-storage/' . ltrim($req->attachments[0], '/');
                }
                return $machineFields($req) + [
                    'id' => $req->id,
                    'request_number' => $req->request_number,
                    'rider_name' => $req->requester ? $req->requester->fullname : 'Unknown',
                    'requester_user_id' => $req->requester_user_id,
                    'expense_date' => $req->expense_date ? $req->expense_date->format('Y-m-d') : null,
                    'expense_date_formatted' => $req->expense_date ? $req->expense_date->format('D, M d') : null,
                    'amount' => (float) $req->amount,
                    'status' => $req->status,
                    'description' => $req->description,
                    'source' => 'maintenance',
                    // The manager's own category name, so the approver sees WHAT the
                    // job was rather than just "maintenance".
                    'maintenance_type' => app(\App\Services\Riders\MaintenanceTypeService::class)
                        // ⭐ + the claim id: a bill paying for several jobs of one visit is
                        //   labelled with all of them (29-Sep-2026). An older engine ignores it.
                        ->labelFor($req->maintenance_type_id ?? null, $req->service_type, $req->id ?? null),
                    'filed_source_id' => $req->payment_source_account_id,
                    'filed_bank_id' => $req->receiving_account_id,
                    'attachment_url' => $attachmentUrl,
                    'created_at' => $req->created_at ? $req->created_at->format('Y-m-d H:i:s') : null,
                ];
            })->values();
            $stats['maintenance_requests_count'] = $maintenanceRequestsData->count();
            $stats['maintenance_requests_amount'] = $maintenanceRequestsData->sum('amount');

            // Payment source accounts for petrol approval dropdown
            // ⭐ Aug-2026: was four hardcoded account codes with NF Cash first — a
            // copy of "which accounts may this person pay from" that disagreed with
            // both the create side and the Fleet strip. Now the one service, so the
            // approver is offered exactly what he is tagged for. Shape is unchanged
            // (id/code/name are all still present), so an existing APK keeps working.
            // Daily Closing is Nizami Farms operations → business unit 1.
            $petrolPaymentAccounts = [];
            $petrolPaymentBanks    = [];
            if ($petrolRequestsData->count() > 0 || $maintenanceRequestsData->count() > 0) {
                $paySvc = app(\App\Services\FIN\PaymentSourceService::class);
                $petrolPaymentAccounts = $paySvc
                    ->sourcesFor($user, 1, \App\Services\FIN\PaymentSourceService::PURPOSE_EXPENSE);

                // ⭐ Aug-27-2026: the banks an ONLINE approval can be attributed to.
                // "Online Bank" is ONE chart account — WHICH bank the money left
                // (HBL / Meezan / …) lives in receiving_account_id. This screen never
                // received that list, so it could not offer the second pick, and every
                // online approval taken here booked an UNTAGGED bank outflow: the
                // per-bank balances drifted by the amount approved. Same list the
                // Fleet strip (pay_banks) and the web approve page already use.
                // Additive key — an APK that does not know it simply ignores it.
                // Only fetched when the approver actually has a bank source in his
                // list, because banks() computes per-bank balances.
                $hasBankSource = (bool) array_filter(
                    $petrolPaymentAccounts,
                    fn ($s) => !empty($s['is_online'])
                );
                if ($hasBankSource) {
                    $petrolPaymentBanks = $paySvc->banks();
                }
            }

            // Get all riders for filter dropdown
            $allRiders = AccountModel::where('account_category', AccountModel::CATEGORY_EMPLOYEE_CASH)
                ->where('is_active', 1)
                ->orderBy('account_name')
                ->get()
                ->map(function($rider) {
                    return [
                        'id' => $rider->id,
                        'account_name' => $rider->account_name
                    ];
                });
            
            // ⭐ Prepare date-grouped data for settled view
            $invoicesByDate = null;
            $onlineData = null;
            
            if ($statusFilter === 'settled' && $groupBy === 'date') {
                // Group settled invoices by date (cash)
                $invoicesByDate = $settledInvoices
                    ->groupBy(function($invoice) {
                        return $invoice->settled_at ? $invoice->settled_at->format('Y-m-d') : $invoice->transaction_date->format('Y-m-d');
                    })
                    ->map(function($dateInvoices, $date) {
                        // Group by rider within each date
                        $riderGroups = $dateInvoices->groupBy('to_account_id')->map(function($riderInvoices) {
                            $account = $riderInvoices->first()->toAccount;
                            return [
                                'rider_name' => $account ? $account->account_name : 'Unknown',
                                'count' => $riderInvoices->count(),
                                'total_amount' => $riderInvoices->sum('amount'),
                                'invoices' => $riderInvoices->map(function($inv) {
                                    return [
                                        'id' => $inv->id,
                                        'order_number' => $inv->order ? $inv->order->order_number : 'N/A',
                                        'customer_name' => $inv->order ? $inv->order->customer_name : null,
                                        'amount' => $inv->amount,
                                        'settled_at' => $inv->settled_at ? $inv->settled_at->format('Y-m-d H:i:s') : null
                                    ];
                                })->values()
                            ];
                        })->values();
                        
                        return [
                            'date' => $date,
                            'riders' => $riderGroups,
                            'cash_count' => $dateInvoices->count(),
                            'cash_amount' => $dateInvoices->sum('amount'),
                            'online_count' => 0,
                            'online_amount' => 0,
                            'online_approved_count' => 0,
                            'online_approved_amount' => 0,
                            'online_pending_count' => 0,
                            'online_pending_amount' => 0,
                            'total_count' => $dateInvoices->count(),
                            'total_amount' => $dateInvoices->sum('amount')
                        ];
                    })
                    ->sortKeysDesc()
                    ->values()
                    ->toArray();
                
                // ⭐ Fetch online data if include_online is true
                if ($includeOnline) {
                    $onlineAccount = AccountModel::where('account_code', 'ONLINE')->first();
                    
                    if ($onlineAccount) {
                        $onlineQuery = LedgerModel::where('transaction_type', LedgerModel::TYPE_INVOICE)
                            ->where('to_account_id', $onlineAccount->id)
                            ->where('approval_status', '!=', LedgerModel::STATUS_REVERSED);
                        
                        if ($dateFrom) {
                            $onlineQuery->where('transaction_date', '>=', $dateFrom);
                        }
                        if ($dateTo) {
                            $onlineQuery->where('transaction_date', '<=', $dateTo . ' 23:59:59');
                        }
                        
                        $onlineInvoices = $onlineQuery->with('order')->get();
                        
                        // Separate approved and pending
                        $onlineApproved = $onlineInvoices->where('approval_status', LedgerModel::STATUS_APPROVED);
                        $onlinePending = $onlineInvoices->where('approval_status', LedgerModel::STATUS_PENDING);
                        
                        // Group by transaction_date
                        $onlineByDate = [];
                        foreach ($onlineInvoices as $invoice) {
                            $date = $invoice->transaction_date->format('Y-m-d');
                            if (!isset($onlineByDate[$date])) {
                                $onlineByDate[$date] = [
                                    'approved' => [],
                                    'pending' => [],
                                    'approved_count' => 0,
                                    'approved_amount' => 0,
                                    'pending_count' => 0,
                                    'pending_amount' => 0
                                ];
                            }
                            
                            $invoiceData = [
                                'id' => $invoice->id,
                                'order_number' => $invoice->order ? $invoice->order->order_number : 'N/A',
                                'customer_name' => $invoice->order ? $invoice->order->customer_name : null,
                                'amount' => $invoice->amount,
                                'transaction_date' => $invoice->transaction_date->format('Y-m-d H:i:s')
                            ];
                            
                            if ($invoice->approval_status === LedgerModel::STATUS_APPROVED) {
                                $onlineByDate[$date]['approved'][] = $invoiceData;
                                $onlineByDate[$date]['approved_count']++;
                                $onlineByDate[$date]['approved_amount'] += $invoice->amount;
                            } else {
                                $onlineByDate[$date]['pending'][] = $invoiceData;
                                $onlineByDate[$date]['pending_count']++;
                                $onlineByDate[$date]['pending_amount'] += $invoice->amount;
                            }
                        }
                        
                        // Merge online data into invoicesByDate
                        foreach ($onlineByDate as $date => $onlineDayData) {
                            $found = false;
                            foreach ($invoicesByDate as &$dayData) {
                                if ($dayData['date'] === $date) {
                                    $dayData['online_count'] = $onlineDayData['approved_count'] + $onlineDayData['pending_count'];
                                    $dayData['online_amount'] = $onlineDayData['approved_amount'] + $onlineDayData['pending_amount'];
                                    $dayData['online_approved_count'] = $onlineDayData['approved_count'];
                                    $dayData['online_approved_amount'] = $onlineDayData['approved_amount'];
                                    $dayData['online_pending_count'] = $onlineDayData['pending_count'];
                                    $dayData['online_pending_amount'] = $onlineDayData['pending_amount'];
                                    $dayData['online_approved'] = $onlineDayData['approved'];
                                    $dayData['online_pending'] = $onlineDayData['pending'];
                                    $dayData['total_count'] += $onlineDayData['approved_count'] + $onlineDayData['pending_count'];
                                    $dayData['total_amount'] += $onlineDayData['approved_amount'] + $onlineDayData['pending_amount'];
                                    $found = true;
                                    break;
                                }
                            }
                            unset($dayData);
                            
                            // Add new date entry if not found in cash data
                            if (!$found) {
                                $invoicesByDate[] = [
                                    'date' => $date,
                                    'riders' => [],
                                    'cash_count' => 0,
                                    'cash_amount' => 0,
                                    'online_count' => $onlineDayData['approved_count'] + $onlineDayData['pending_count'],
                                    'online_amount' => $onlineDayData['approved_amount'] + $onlineDayData['pending_amount'],
                                    'online_approved_count' => $onlineDayData['approved_count'],
                                    'online_approved_amount' => $onlineDayData['approved_amount'],
                                    'online_pending_count' => $onlineDayData['pending_count'],
                                    'online_pending_amount' => $onlineDayData['pending_amount'],
                                    'online_approved' => $onlineDayData['approved'],
                                    'online_pending' => $onlineDayData['pending'],
                                    'total_count' => $onlineDayData['approved_count'] + $onlineDayData['pending_count'],
                                    'total_amount' => $onlineDayData['approved_amount'] + $onlineDayData['pending_amount']
                                ];
                            }
                        }
                        
                        // Re-sort by date descending
                        usort($invoicesByDate, function($a, $b) {
                            return strcmp($b['date'], $a['date']);
                        });
                        
                        $onlineData = [
                            'total_count' => $onlineInvoices->count(),
                            'total_amount' => $onlineInvoices->sum('amount'),
                            'approved_count' => $onlineApproved->count(),
                            'approved_amount' => $onlineApproved->sum('amount'),
                            'pending_count' => $onlinePending->count(),
                            'pending_amount' => $onlinePending->sum('amount')
                        ];
                    }
                }
            }
            
            // ============================================================
            // 💰 Payment Follow-ups (Aug-2026) — same source of truth as the web
            // Daily Closing panel. This block used to be a copy-paste of the web
            // implementation; both now go through OnlineFollowUpService so the
            // two screens can never drift apart again.
            //
            // `online_message_tracking` keeps the EXACT shape the installed APK
            // reads, so this deploys web-only with no rebuild. `payment_follow_up`
            // carries the new chase/proof-in/settled tiers for the next mobile
            // build. Purely informational: no ledger, settlement or invoice impact.
            // Wrapped in its own try-catch so it NEVER crashes daily closing.
            // ============================================================
            $onlineMessageTracking = null;
            $paymentFollowUp = null;
            try {
                $followUpService = app(\App\Services\Payments\OnlineFollowUpService::class);
                $paymentFollowUp = $followUpService->build($riderFilter);
                if ($paymentFollowUp) {
                    $onlineMessageTracking = $followUpService->legacyMobilePayload($paymentFollowUp);
                }
            } catch (\Exception $msgEx) {
                \Log::warning('Payment follow-ups failed in daily closing (non-critical)', [
                    'error' => $msgEx->getMessage()
                ]);
                $onlineMessageTracking = null;
                $paymentFollowUp = null;
            }

            return response()->json([
                'success' => true,
                'stats' => $stats,
                'invoices_by_rider' => $invoicesByRider,
                'invoices_by_date' => $invoicesByDate, // ⭐ New: date-grouped data for settled view
                'online_summary' => $onlineData, // ⭐ New: online summary
                'online_message_tracking' => $onlineMessageTracking, // legacy shape — the installed APK reads this
                'payment_follow_up' => $paymentFollowUp, // Aug-2026 tiers — read by the rebuilt Daily Closing screen
                // Sep-2026: the accounts the app should show if a template send
                // fails and it has to fall back to native WhatsApp. Served from
                // BankDetailsProvider so the phone can never print a stale set —
                // DailyClosingScreen used to hardcode the retired HBL pair.
                'bank_details_text' => \App\Services\WhatsApp\BankDetailsProvider::accountsBlock(),
                'petrol_requests' => $petrolRequestsData,
                'maintenance_requests' => $maintenanceRequestsData,
                'petrol_payment_accounts' => $petrolPaymentAccounts,
                'petrol_payment_banks' => $petrolPaymentBanks, // ⭐ which bank an ONLINE approval left from
                'pending_settlements' => $pendingSettlements->map(function($settlement) {
                    return [
                        'id' => $settlement->id,
                        'from_account' => $settlement->fromAccount ? $settlement->fromAccount->account_name : 'N/A',
                        'from_account_id' => $settlement->from_account_id,
                        'amount' => $settlement->amount,
                        'created_at' => $settlement->created_at->format('Y-m-d H:i:s'),
                        'description' => $settlement->description,
                        'approval_status' => $settlement->approval_status,
                        'invoice_ids' => $settlement->invoice_ids,
                        'invoices' => $settlement->invoices,
                        'total_outstanding' => $settlement->total_outstanding
                    ];
                })->values(),
                'all_riders' => $allRiders,
                'filters' => [
                    'status' => $statusFilter,
                    'rider' => $riderFilter,
                    'date_from' => $dateFrom,
                    'date_to' => $dateTo,
                    'group_by' => $groupBy, // ⭐ New
                    'include_online' => $includeOnline // ⭐ New
                ]
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Failed to get daily closing', [
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to load daily closing: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Approve settlement deposit (Daily Closing)
     * Reuses LedgerController::approveTransaction logic
     */
    public function approveDailyClosingSettlement(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_daily_closing')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to approve settlements'
                ], 403);
            }
            
            // Find the transaction
            $transaction = LedgerModel::findOrFail($id);
            
            // Verify it's a pending settlement
            if ($transaction->transaction_type !== LedgerModel::TYPE_EMPLOYEE_DEPOSIT) {
                return response()->json([
                    'success' => false,
                    'message' => 'This is not a settlement deposit transaction'
                ], 400);
            }
            
            if ($transaction->approval_status !== LedgerModel::STATUS_PENDING) {
                return response()->json([
                    'success' => false,
                    'message' => 'This transaction has already been ' . $transaction->approval_status
                ], 400);
            }
            
            DB::beginTransaction();
            
            // Load accounts
            $transaction->load(['fromAccount', 'toAccount']);
            $fromAccount = $transaction->fromAccount;
            $toAccount = $transaction->toAccount;
            
            // Update transaction status (EXACT web app logic)
            $transaction->approval_status = LedgerModel::STATUS_APPROVED;
            $transaction->approved_by = $user->id;
            $transaction->approval_date = now()->toDateString(); // ← FIXED: Use approval_date (DATE) not approved_at (DATETIME)
            $transaction->save();
            
            // Update account balances via the canonical gate (Ledger L3).
            // This is the mobile Daily Closing approve. It previously hand-rolled the same
            // "asset-aware" arithmetic as the web approve path but never set balance_updated,
            // which is why settlement deposits approved from the phone since Mar-2026 were
            // left unstamped: the money moved correctly, but a later reject could not reverse
            // it (reverse() no-ops on an unstamped row) and the Finance Hub — which counts
            // only stamped rows — did not see them.
            // Verified arithmetically identical to the old code for this path's account pair
            // (employee_cash asset → cash asset), so no balance changes.
            (new \App\Services\FIN\BalancePostingService())->apply($transaction);


            // Process settlement metadata if exists (EXACT web app logic)
            if ($transaction->settlement_metadata && isset($transaction->settlement_metadata['invoice_ids'])) {
                \Log::info('Processing invoice settlement via mobile', [
                    'deposit_id' => $transaction->id,
                    'metadata' => $transaction->settlement_metadata
                ]);
                
                $this->processInvoiceSettlementMobile($transaction, $transaction->settlement_metadata);
                
                // If this is a short cash settlement with linked expense request, auto-approve it
                if (isset($transaction->settlement_metadata['is_short_cash_settlement']) && 
                    $transaction->settlement_metadata['is_short_cash_settlement'] && 
                    isset($transaction->settlement_metadata['expense_request_id'])) {
                    
                    $expenseRequestId = $transaction->settlement_metadata['expense_request_id'];
                    
                    \Log::info('Auto-approving linked short cash expense via mobile', [
                        'deposit_id' => $transaction->id,
                        'expense_request_id' => $expenseRequestId
                    ]);
                    
                    // Auto-approve the linked expense request (EXACT web app logic)
                    $expenseRequest = RequestModel::find($expenseRequestId);
                    
                    if ($expenseRequest && $expenseRequest->status === 'pending') {
                        // Process the approval (level, approverId, action, comments)
                        $expenseRequest->processApproval(1, $user->id, 'approved', 'Auto-approved with deposit settlement (mobile)');
                        
                        \Log::info('Short cash expense auto-approved via mobile', [
                            'expense_request_id' => $expenseRequestId,
                            'amount' => $expenseRequest->amount
                        ]);
                    }
                }
            } else {
                \Log::warning('No settlement data found for deposit - invoices will not be auto-settled', [
                    'deposit_id' => $transaction->id,
                    'description' => $transaction->description
                ]);
            }
            
            DB::commit();
            
            \Log::info('Daily closing settlement approved via mobile', [
                'settlement_id' => $id,
                'approved_by' => $user->fullname,
                'amount' => $transaction->amount
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Settlement approved successfully'
            ]);
            
        } catch (\Exception $e) {
            DB::rollBack();
            
            \Log::error('Failed to approve daily closing settlement', [
                'settlement_id' => $id,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to approve settlement: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Reject settlement deposit (Daily Closing)
     * Reuses LedgerController::rejectTransaction logic
     */
    public function rejectDailyClosingSettlement(Request $request, $id)
    {
        try {
            $user = Auth::user();
            
            // Check permission
            if (!$user->hasMobilePermission('view_daily_closing')) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to reject settlements'
                ], 403);
            }
            
            // Find the transaction
            $transaction = LedgerModel::findOrFail($id);
            
            // Verify it's a pending settlement
            if ($transaction->transaction_type !== LedgerModel::TYPE_EMPLOYEE_DEPOSIT) {
                return response()->json([
                    'success' => false,
                    'message' => 'This is not a settlement deposit transaction'
                ], 400);
            }
            
            if ($transaction->approval_status !== LedgerModel::STATUS_PENDING) {
                return response()->json([
                    'success' => false,
                    'message' => 'This transaction has already been ' . $transaction->approval_status
                ], 400);
            }
            
            DB::beginTransaction();
            
            // Mark as rejected (EXACT web app logic)
            $transaction->approval_status = LedgerModel::STATUS_REJECTED;
            $transaction->approved_by = $user->id;
            $transaction->approval_date = now()->toDateString(); // ← FIXED: Use approval_date not approved_at
            $transaction->save();
            
            // Note: Account balances are NOT updated when rejecting (per web app logic)
            
            DB::commit();
            
            \Log::info('Daily closing settlement rejected via mobile', [
                'settlement_id' => $id,
                'rejected_by' => $user->fullname,
                'amount' => $transaction->amount
            ]);
            
            return response()->json([
                'success' => true,
                'message' => 'Settlement rejected successfully'
            ]);
            
        } catch (\Exception $e) {
            DB::rollBack();
            
            \Log::error('Failed to reject daily closing settlement', [
                'settlement_id' => $id,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString()
            ]);
            
            return response()->json([
                'success' => false,
                'message' => 'Failed to reject settlement: ' . $e->getMessage()
            ], 500);
        }
    }

    /**
     * Process invoice settlement when deposit is approved (Mobile version)
     * Replicates LedgerController::processInvoiceSettlement logic EXACTLY
     * 
     * @param LedgerModel $depositLedger The approved deposit transaction
     * @param array $settlementData Contains invoice_ids, deposit_amount, total_outstanding
     */
    private function processInvoiceSettlementMobile(LedgerModel $depositLedger, array $settlementData)
    {
        try {
            $invoiceIds = $settlementData['invoice_ids'];
            $depositAmount = $settlementData['deposit_amount'];
            $totalOutstanding = $settlementData['total_outstanding'];
            
            // Check if this is a short cash settlement or partial payment
            $isShortCash = $settlementData['is_short_cash_settlement'] ?? false;
            $isPartialPayment = $settlementData['is_partial_payment'] ?? false;
            $shortCashAmount = $settlementData['short_cash_amount'] ?? 0;
            
            // For short cash, the total amount settling invoices = deposit + expense
            // For partial payment, only the deposit amount is used (remaining stays open)
            // 2dp — old metadata may carry raw floats (pre-Jul-2026 deposits)
            if ($isShortCash) {
                $totalSettlementAmount = round($depositAmount + $shortCashAmount, 2);
            } else {
                $totalSettlementAmount = round($depositAmount, 2);
            }

            \Log::info('Processing invoice settlement (mobile)', [
                'deposit_id' => $depositLedger->id,
                'is_short_cash' => $isShortCash,
                'is_partial_payment' => $isPartialPayment,
                'deposit_amount' => $depositAmount,
                'short_cash_amount' => $shortCashAmount,
                'total_settlement_amount' => $totalSettlementAmount
            ]);
            
            // Get the invoices that need to be settled (in order) - include both open and partial
            $invoices = LedgerModel::whereIn('id', $invoiceIds)
                ->whereIn('settlement_status', ['open', 'partial'])
                ->orderBy('transaction_date', 'asc')
                ->get();
            
            $remainingAmount = $totalSettlementAmount;

            foreach ($invoices as $invoice) {
                $outstandingForThisInvoice = round($invoice->amount - ($invoice->settled_amount ?? 0), 2);

                if ($remainingAmount < 0.01) {
                    break; // No more money to allocate
                }

                // Calculate how much to settle on this invoice (2dp)
                $amountToSettle = round(min($remainingAmount, $outstandingForThisInvoice), 2);
                if ($amountToSettle <= 0) {
                    continue; // nothing outstanding on this invoice — skip, no zero audit rows
                }

                // Update invoice
                $invoice->settled_amount = round(($invoice->settled_amount ?? 0) + $amountToSettle, 2);

                if ($invoice->settled_amount >= $invoice->amount) {
                    // Fully settled
                    $invoice->settlement_status = 'settled';
                    $invoice->settled_at = now();
                    $invoice->settled_via_ledger_id = $depositLedger->id;
                } else {
                    // Partially settled: keep status 'open' (legacy behavior)
                    // We infer partial by settled_amount > 0
                    // Do NOT write 'partial' to settlement_status - it stays 'open'
                }
                $invoice->save();

                // Create audit record (if InvoiceSettlementModel exists)
                if (class_exists('\App\Models\FIN\InvoiceSettlementModel')) {
                    \App\Models\FIN\InvoiceSettlementModel::create([
                        'settlement_deposit_id' => $depositLedger->id,
                        'invoice_ledger_id' => $invoice->id,
                        'settled_amount' => $amountToSettle
                    ]);
                }

                $remainingAmount = round($remainingAmount - $amountToSettle, 2);
            }

            // An un-allocatable remainder means an invoice in this deposit was settled by
            // ANOTHER deposit between create and approval. Never drop it silently (Jul-2026:
            // Rs 4,956.10 vanished this way) — flag it on the deposit so finance sees it.
            if ($remainingAmount >= 0.01) {
                \Log::warning('Settlement deposit approved with UNALLOCATED remainder (mobile)', [
                    'deposit_id' => $depositLedger->id,
                    'amount_remaining' => $remainingAmount,
                ]);
                $note = "⚠ Rs. " . number_format($remainingAmount, 2) . " of this deposit could not be applied to any invoice (already settled elsewhere at approval time). Needs manual review.";
                $depositLedger->comments = trim(($depositLedger->comments ? $depositLedger->comments . " | " : "") . $note);
                $depositLedger->save();
            }

            \Log::info('Invoice settlement completed (mobile)', [
                'deposit_id' => $depositLedger->id,
                'invoices_count' => $invoices->count(),
                'total_settlement_amount' => $totalSettlementAmount,
                'amount_allocated' => $totalSettlementAmount - $remainingAmount,
                'amount_remaining' => $remainingAmount,
                'is_short_cash' => $isShortCash,
                'is_partial_payment' => $isPartialPayment
            ]);
            
        } catch (\Exception $e) {
            \Log::error('Error processing invoice settlement (mobile): ' . $e->getMessage(), [
                'deposit_id' => $depositLedger->id,
                'settlement_data' => $settlementData
            ]);
            throw $e;
        }
    }
    
    /**
     * ⭐ Update delivery priorities for orders (Store Mode + Rider Mode)
     * Sets the delivery sequence for a rider's route. Accepts BOTH
     * `out_for_delivery` (the live "van" block) and `processing` (the
     * "up next" block the rider/manager pre-plans before dispatch).
     *
     * The caller sends ONE globally-numbered list, van block first
     * (1..k) then the processing block (k+1..n). Keeping processing
     * numbers above the van's is what makes the plan carry forward
     * cleanly: when a processing order is later moved to
     * out_for_delivery its number is already higher than every current
     * van stop, so it lands at the bottom of the van — no collision,
     * no re-plan needed. Reads sort by COALESCE(delivery_priority,999)
     * and the clients derive contiguous "Stop N"/"Next N" labels from
     * position, so gaps from partial moves never show.
     */
    public function updateDeliveryPriorities(Request $request)
    {
        try {
            $user = Auth::user();
            
            $validated = $request->validate([
                'rider_id' => 'required|integer|exists:t_sys_user,id',
                'priorities' => 'required|array',
                'priorities.*.order_id' => 'required|integer|exists:t_crm_prod_order,id',
                'priorities.*.priority' => 'required|integer|min:1',
            ]);
            
            $riderId = $validated['rider_id'];
            $priorities = $validated['priorities'];

            // Check permission - store managers (view_open_orders) OR the rider acting on own route
            if (!$this->canManageRiderRoute($user, $riderId)) {
                return response()->json([
                    'success' => false,
                    'message' => 'You do not have permission to update delivery priorities'
                ], 403);
            }

            // Route lock: a manager cannot change a route locked by someone else.
            // The rider ALWAYS wins on their own route (rider-mode dispatch), so we
            // skip the lock when the caller is the rider themselves.
            $isRiderSelf = ((int) $user->id === (int) $riderId);
            if (!$isRiderSelf) {
                $lock = \DB::table('t_crm_route_lock as rl')
                    ->leftJoin('t_sys_user as u', 'u.id', '=', 'rl.locked_by')
                    ->where('rl.rider_id', $riderId)
                    ->select('rl.locked_by', 'u.fullname as locked_by_name', 'rl.locked_at')
                    ->first();

                if ($lock && $lock->locked_by != $user->id) {
                    return response()->json([
                        'success' => false,
                        'message' => "Route is locked by {$lock->locked_by_name}. Unlock it first before making changes.",
                        'route_locked' => true,
                        'locked_by_name' => $lock->locked_by_name,
                    ], 423);
                }
            }
            $updatedCount = 0;
            
            \DB::beginTransaction();
            
            foreach ($priorities as $item) {
                $order = OrderModel::where('id', $item['order_id'])
                    ->where('assigned_rider_user_id', $riderId)
                    // Van block (out_for_delivery) + up-next block (processing)
                    // + on_van (Aug-2026): the store sequences orders WHILE they
                    // are on the van, and that sequence must survive the handover
                    // — which it does, because 'on_van' is deliberately NOT in the
                    // priority-clear list above. The rider lands with the store's
                    // plan already loaded and only has to press Dispatch.
                    // Any other status in the payload (e.g. an order cancelled
                    // since the client loaded) simply doesn't match and is skipped.
                    ->whereIn('order_status', ['out_for_delivery', 'processing', 'on_van'])
                    ->first();
                
                if ($order) {
                    $order->delivery_priority = $item['priority'];
                    $order->delivery_priority_updated_by = $user->id; // attribution: who set the sequence
                    $order->delivery_priority_updated_at = now();
                    $order->save();
                    $updatedCount++;
                }
            }
            
            \DB::commit();
            
            \Log::info('Delivery priorities updated (Store Mode)', [
                'user_id' => $user->id,
                'rider_id' => $riderId,
                'orders_updated' => $updatedCount,
                'total_priorities' => count($priorities)
            ]);
            
            return response()->json([
                'success' => true,
                'message' => "Updated priorities for {$updatedCount} orders",
                'updated_count' => $updatedCount
            ]);
            
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json([
                'success' => false,
                'message' => 'Validation failed',
                'errors' => $e->errors()
            ], 422);
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Error updating delivery priorities: ' . $e->getMessage(), [
                'trace' => $e->getTraceAsString()
            ]);
            return response()->json([
                'success' => false,
                'message' => 'Failed to update delivery priorities: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * ⭐ Read-only route-lock state for a rider.
     *
     * Exists so the RIDER can be told, on his own screen, that the route he is
     * about to re-order was deliberately set by a manager. The lock stays
     * non-blocking for him (rider always wins on his own route — see
     * updateDeliveryPriorities) and never blocks dispatch; this is purely the
     * "who set this" information he had no way of seeing.
     *
     * Permission is canManageRiderRoute, NOT view_open_orders like lockRoute /
     * unlockRoute: a rider has no store permissions, and this is his own route.
     * Returns route_lock = null when the route is not locked.
     */
    public function getRouteLock(Request $request, $riderId)
    {
        try {
            $user = Auth::user();

            if (!$this->canManageRiderRoute($user, $riderId)) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            return response()->json([
                'success'    => true,
                'route_lock' => $this->getRouteLockInfo($riderId),
            ]);
        } catch (\Exception $e) {
            \Log::error('Error reading route lock: ' . $e->getMessage(), ['rider_id' => $riderId]);
            return response()->json(['success' => false, 'message' => 'Failed to read route lock'], 500);
        }
    }

    /**
     * Lock route for a rider — prevents other users from changing delivery order
     */
    public function lockRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();

            if (!$user->hasMobilePermission('view_open_orders')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $existing = \DB::table('t_crm_route_lock')->where('rider_id', $riderId)->first();
            if ($existing) {
                if ($existing->locked_by == $user->id) {
                    return response()->json(['success' => true, 'message' => 'Route already locked by you']);
                }
                $lockerName = \DB::table('t_sys_user')->where('id', $existing->locked_by)->value('fullname');
                return response()->json([
                    'success' => false,
                    'message' => "Route is already locked by {$lockerName}",
                    'locked_by_name' => $lockerName,
                ], 409);
            }

            \DB::table('t_crm_route_lock')->insert([
                'rider_id' => $riderId,
                'locked_by' => $user->id,
                'locked_at' => now(),
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Route locked',
                'route_lock' => [
                    'locked_by' => $user->id,
                    'locked_by_name' => $user->fullname,
                    'locked_at' => now()->toIso8601String(),
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Route lock error: ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Failed to lock route'], 500);
        }
    }

    /**
     * Unlock route for a rider
     */
    public function unlockRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();

            if (!$user->hasMobilePermission('view_open_orders')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            \DB::table('t_crm_route_lock')->where('rider_id', $riderId)->delete();

            return response()->json(['success' => true, 'message' => 'Route unlocked']);
        } catch (\Exception $e) {
            \Log::error('Route unlock error: ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Failed to unlock route'], 500);
        }
    }

    /**
     * ⭐ Clear delivery priority when order status changes or rider is reassigned
     * This should be called from OrderModel when status/rider changes
     */
    public static function clearDeliveryPriority($orderId)
    {
        try {
            OrderModel::where('id', $orderId)->update(['delivery_priority' => null]);
        } catch (\Exception $e) {
            \Log::warning('Failed to clear delivery priority for order ' . $orderId . ': ' . $e->getMessage());
        }
    }

    /**
     * ⭐ Get WhatsApp message templates (stored in t_fin_config)
     */
    public function getWhatsappTemplates(Request $request)
    {
        try {
            $templates = \App\Models\FIN\ConfigModel::where('config_key', 'LIKE', 'WHATSAPP_TEMPLATE_%')
                ->get()
                ->mapWithKeys(function ($item) {
                    $key = str_replace('WHATSAPP_TEMPLATE_', '', $item->config_key);
                    return [strtolower($key) => $item->config_value];
                });

            $defaults = [
                'location_request' => 'Dear Customer, Can you please share your google location pin',
            ];

            foreach ($defaults as $key => $defaultValue) {
                if (!$templates->has($key)) {
                    $templates[$key] = $defaultValue;
                }
            }

            return response()->json(['success' => true, 'templates' => $templates]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * ⭐ Save/update a WhatsApp message template
     */
    public function saveWhatsappTemplate(Request $request)
    {
        try {
            $request->validate([
                'template_key' => 'required|string|max:100',
                'template_value' => 'required|string|max:2000',
            ]);

            $configKey = 'WHATSAPP_TEMPLATE_' . strtoupper($request->input('template_key'));

            \App\Models\FIN\ConfigModel::updateOrCreate(
                ['config_key' => $configKey],
                [
                    'config_value' => $request->input('template_value'),
                    'description' => 'WhatsApp message template: ' . $request->input('template_key'),
                ]
            );

            \Illuminate\Support\Facades\Cache::forget("fin_config_{$configKey}");

            return response()->json(['success' => true, 'message' => 'Template saved successfully']);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

