        } catch (\Exception $e) {
            return response()->json([
                'success' => false,
                'message' => 'Failed to load salary slip: ' . $e->getMessage()
            ], 500);
        }
    }
    
    /**
     * Helper: Process loan payments for a salary slip
     */
    private function processSlipLoanPayments($slip)
    {
        if (!$slip->loan_ids || $slip->loan_installment_skipped) {
            \Log::info('No loan_ids to process or loan installment skipped');
            return;
        }
        
        $loanIds = array_filter(explode(',', $slip->loan_ids));
        
        \Log::info('Processing loan payments', [
            'loan_ids' => $loanIds,
            'slip_id' => $slip->id,
        ]);
        
        foreach ($loanIds as $loanId) {
            $loan = \App\Models\HR\EmployeeLoanModel::find($loanId);
            
            if (!$loan) {
                \Log::warning('Loan not found', ['loan_id' => $loanId]);
                continue;
            }
            
            if ($loan->loan_status !== 'active') {
                \Log::warning('Loan not active', ['loan_id' => $loanId, 'status' => $loan->loan_status]);
                continue;
            }
            
            // Calculate payment amount (use full installment or remaining balance, whichever is less)
            $paymentAmount = min($loan->monthly_installment, $loan->outstanding_balance);
            
            \Log::info('Processing loan payment', [
                'loan_id' => $loanId,
                'payment_amount' => $paymentAmount,
                'outstanding_before' => $loan->outstanding_balance,
            ]);
            
            // Create loan payment record
            // ⭐ FIX: Use correct field names matching LoanPaymentModel fillable
            $payment = \App\Models\HR\LoanPaymentModel::create([
                'loan_id' => $loan->id,
                'salary_slip_id' => $slip->id,
                'payment_date' => now(),
                'payment_amount' => $paymentAmount,
                'balance_before' => $loan->outstanding_balance,
                'balance_after' => $loan->outstanding_balance - $paymentAmount,
                'payment_type' => 'salary_deduction',
                'payment_notes' => 'Salary deduction via slip: ' . $slip->slip_number,
                'created_by' => auth()->id(),
            ]);
            
            // Update loan balance
            // ⭐ FIX: Only update fields that exist in the model
            $loan->outstanding_balance -= $paymentAmount;
            
            // Check if loan is fully paid
            if ($loan->outstanding_balance <= 0) {
                $loan->outstanding_balance = 0; // Ensure it's not negative
                $loan->loan_status = 'completed';
                $loan->completed_at = now();
            }
            
            $loan->save();
            
            \Log::info('Loan payment processed', [
                'loan_id' => $loanId,
                'payment_id' => $payment->id,
                'outstanding_after' => $loan->outstanding_balance,
                'loan_status' => $loan->loan_status,
            ]);
        }
    }
    
    /**
     * Helper: Settle salary advances for a salary slip
     */
    private function settleSlipAdvances($slip)
    {
        if (!$slip->advance_request_ids) {
            \Log::info('No advance_request_ids to settle');
            return;
        }
        
        $advanceIds = array_filter(explode(',', $slip->advance_request_ids));
        
        \Log::info('Settling advances', [
            'advance_ids' => $advanceIds,
            'slip_id' => $slip->id,
        ]);
        
        // Update settlement status for each advance
        // Note: settled_via_slip_id column may not exist, so we only update fields that exist
        $updated = \App\Models\Request\RequestModel::whereIn('id', $advanceIds)
            ->update([
                'settlement_status' => 'settled',
                'settled_at' => now(),
            ]);
        
        \Log::info('Advances settled', [
            'count' => $updated,
            'advance_ids' => $advanceIds,
        ]);
    }

    // =========================================================================
    // QURBANI MODE ENDPOINTS
    // =========================================================================

    /**
     * Qurbani open orders - orders containing products with attribute_1 = 'qurbani'
     * Supports filters: qurbani_day, qurbani_slot, qurbani_region, qurbani_delivery_type, status
     */
    public function getQurbaniOpenOrders(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'No permission'], 403);
            }

            // Find open qurbani orders efficiently:
            // First check orders with qurbani fields set (fast indexed check),
            // then fall back to line-item join only for orders in last 60 days without fields set
            $qurbaniOrderIds = \DB::table('t_crm_prod_order')
                ->whereNotIn('order_status', ['delivered', 'completed', 'cancelled', 'refunded'])
                ->where(function($q) {
                    $q->where('external_source', '!=', 'shopify')->orWhereNull('external_source');
                })
                ->where(function($q) {
                    // Orders with qurbani fields explicitly set (fast)
                    $q->whereNotNull('qurbani_day')
                      ->orWhereNotNull('qurbani_slot')
                      ->orWhereNotNull('qurbani_region')
                      ->orWhereNotNull('qurbani_delivery_type');
                })
                ->pluck('id');

            // Also find orders identified by line item products (for orders created before fields were added)
            $lineItemQurbaniIds = \DB::table('t_crm_prod_order_line_item as li')
                ->join('t_crm_prod_product as p', 'li.product_id', '=', 'p.id')
                ->join('t_crm_prod_order as o', 'li.order_id', '=', 'o.id')
                ->whereRaw("LOWER(p.attribute_1) = 'qurbani'")
                ->whereNotIn('o.order_status', ['delivered', 'completed', 'cancelled', 'refunded'])
                ->where(function($q) {
                    $q->where('o.external_source', '!=', 'shopify')->orWhereNull('o.external_source');
                })
                ->where('o.order_date', '>=', \Carbon\Carbon::now()->subDays(60))
                ->distinct()
                ->pluck('li.order_id');

            $allQurbaniIds = $qurbaniOrderIds->merge($lineItemQurbaniIds)->unique();

            if ($allQurbaniIds->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'orders' => [],
                    'summary' => ['total' => 0, 'unpaid' => 0, 'partial' => 0, 'paid' => 0],
                ]);
            }

            $query = OrderModel::with(['customer' => function($q) {
                    $q->select('id', 'first_name', 'last_name', 'phone_original', 'latitude', 'longitude',
                               'geocoded_latitude', 'geocoded_longitude', 'geocode_precision',
                               'verified_location_url', 'notes',
                               'verified_location_saved_by', 'verified_location_saved_at', 'delivery_region_id');
                }])
                ->with(['assignedRider' => function($q) {
                    $q->select('id', 'fullname');
                }])
                ->with(['lineItems' => function($q) {
                    $q->select(
                        'id', 'order_id', 'product_id', 'name', 'sku', 'quantity', 'unit_price', 'line_total',
                        'preparation_status', 'is_free',
                        'qurbani_day', 'qurbani_slot', 'qurbani_region', 'qurbani_sub_region', 'qurbani_delivery_type',
                        'qurbani_type', 'qurbani_paya',
                        // May-2026: per-line-item Qurbani lifecycle status + rider assignment.
                        // These are intentionally separate from preparation_status (regular
                        // orders' "Mark as Prepared" flow) and from t_crm_prod_order.assigned_rider_user_id
                        // (order-level rider) so the two systems don't bleed into each other.
                        'qurbani_item_status', 'qurbani_assigned_rider_user_id',
                        'qurbani_status_updated_at', 'qurbani_status_updated_by',
                        // May-17-2026: per-state transition timestamps for the
                        // mobile region-view's status timeline mini section.
                        'qurbani_slaughtered_at', 'qurbani_out_for_delivery_at', 'qurbani_delivered_at',
                        'instructions'
                    );
                }])
                ->with(['lineItems.product' => function($q) {
                    $q->select('id', 'attribute_2');
                }])
                ->with(['discounts'])
                ->whereIn('id', $allQurbaniIds);

            // Apply status filter
            if ($request->get('status')) {
                $query->where('order_status', $request->get('status'));
            }

            // Apply qurbani field filters (check both order-level and line-item-level)
            // qurbani_type and qurbani_paya live ONLY on line items (no order-level
            // column). Everything else exists on both — keep the legacy behaviour
            // of matching against either the order row or any line-item row.
            //
            // May-2026: Each filter accepts EITHER a scalar (legacy single-select)
            // OR an array (multi-select chips on the mobile sidebar). Internally
            // we always coerce to an array of trimmed non-empty strings and use
            // whereIn — single-element arrays still hit the same index path.
            $lineOnlyFields = ['qurbani_type', 'qurbani_paya'];
            foreach (['qurbani_day', 'qurbani_slot', 'qurbani_region', 'qurbani_sub_region', 'qurbani_delivery_type', 'qurbani_type', 'qurbani_paya'] as $field) {
                $raw = $request->input($field);
                if ($raw === null || $raw === '') continue;

                $values = is_array($raw) ? $raw : [$raw];
                $values = array_values(array_filter(array_map(function ($v) {
                    return is_string($v) ? trim($v) : $v;
                }, $values), function ($v) {
                    return $v !== null && $v !== '';
                }));
                if (empty($values)) continue;

                $isLineOnly = in_array($field, $lineOnlyFields, true);
                $query->where(function($q) use ($field, $values, $isLineOnly) {
                    if ($isLineOnly) {
                        $q->whereHas('lineItems', function($sub) use ($field, $values) {
                            $sub->whereIn($field, $values);
                        });
                    } else {
                        $q->whereIn($field, $values)
                          ->orWhereHas('lineItems', function($sub) use ($field, $values) {
                              $sub->whereIn($field, $values);
                          });
                    }
                });
            }

            $orders = $query->orderBy('order_date', 'desc')->get();

            // Preparation summaries
            $prepSummaries = \DB::table('t_crm_prod_order_line_item')
                ->whereIn('order_id', $orders->pluck('id'))
                ->groupBy('order_id')
                ->selectRaw('order_id, COUNT(*) as total, SUM(CASE WHEN preparation_status = "preparing" THEN 1 ELSE 0 END) as preparing')
                ->get()
                ->keyBy('order_id');

            // May-2026: Resolve per-line-item rider names in a single query so the
            // mobile app can render the assigned-rider chip without an N+1 lookup.
            // We collect every distinct qurbani_assigned_rider_user_id across the
            // page's line items, fetch their fullnames once, and inject the name
            // into each line-item payload below.
            $perItemRiderIds = collect();
            foreach ($orders as $o) {
                foreach ($o->lineItems as $li) {
                    if ($li->qurbani_assigned_rider_user_id) {
                        $perItemRiderIds->push($li->qurbani_assigned_rider_user_id);
                    }
                }
            }
            $perItemRiderMap = [];
            if ($perItemRiderIds->isNotEmpty()) {
                $perItemRiderMap = \DB::table('t_sys_user')
                    ->whereIn('id', $perItemRiderIds->unique()->values())
                    ->pluck('fullname', 'id')
                    ->toArray();
            }

            $regionMap = [];
            try {
                $regionMap = \DB::table('t_ops_delivery_region')
                    ->where('is_active', 1)
                    ->pluck('name', 'id')
                    ->toArray();
            } catch (\Exception $e) {}

            // May-2026: smart-box bundle calculation. We compute bundle_key,
            // bundle_size, and (start, end) packet positions for every line
            // item so the mobile row card can show "3/5" and the bulk-action
            // soft-warn can detect cross-bundle / partial-bundle selections.
            // No DB writes — pure derivation. See QurbaniBundleService.
            $bundleInputs = [];
            foreach ($orders as $o) {
                foreach ($o->lineItems as $li) {
                    $bundleInputs[] = [
                        'id'                    => $li->id,
                        'order_id'              => $li->order_id,
                        'quantity'              => $li->quantity,
                        'qurbani_day'           => $li->qurbani_day,
                        'qurbani_slot'          => $li->qurbani_slot,
                        'qurbani_delivery_type' => $li->qurbani_delivery_type,
                        'category_level_2'      => $li->product->attribute_2 ?? null,
                        'product_id'            => $li->product_id,
                    ];
                }
            }
            $bundleMap = (new \App\Services\QurbaniBundleService())->computeBundles($bundleInputs);

            $formattedOrders = $orders->map(function($order) use ($prepSummaries, $regionMap, $perItemRiderMap, $bundleMap) {
                $customerName = $order->name ?? 'N/A';
                if (!$order->name && ($order->address_first_name || $order->address_last_name)) {
                    $customerName = trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? ''));
                }
                if ($customerName === 'N/A' && $order->customer) {
                    $customerName = trim(($order->customer->first_name ?? '') . ' ' . ($order->customer->last_name ?? '')) ?: 'Unknown';
                }

                $prepSummary = $prepSummaries[$order->id] ?? null;

                $effectiveCustomerNotes = null;
                if ($order->customer) {
                    if ($order->customer->merged_into_customer_id ?? false) {
                        $primaryCustomer = \App\Models\CRM\CustomerModel::find($order->customer->merged_into_customer_id);
                        $effectiveCustomerNotes = $primaryCustomer ? ($primaryCustomer->notes ?? null) : null;
                    } else {
                        $effectiveCustomerNotes = $order->customer->notes ?? null;
                    }
                }

                return [
                    'id' => $order->id,
                    'order_number' => $order->order_number ?? 'NF-' . str_pad($order->id, 4, '0', STR_PAD_LEFT),
                    'order_date' => $order->order_date,
                    'order_status' => $order->order_status,
                    'total_price' => $order->total_price,
                    'payment_method' => $order->payment_method,
                    'payment_status' => $order->payment_status ?? 'unpaid',
                    'total_paid' => (float) ($order->total_paid ?? 0),
                    'balance_remaining' => max(0, (float)$order->total_price - (float)($order->total_paid ?? 0)),
                    // Mirrors server-side PAID stamp (bank / date / ref).
                    // The mobile InvoiceTemplate reads this as-is; without it
                    // older clients fall back to hardcoded "CASH" which is
                    // wrong for online-paid orders.
                    'paid_stamp' => $order->getPaidStampData(),
                    'qurbani_day' => $order->qurbani_day,
                    'qurbani_slot' => $order->qurbani_slot,
                    'qurbani_region' => $order->qurbani_region,
                    'qurbani_delivery_type' => $order->qurbani_delivery_type,
                    'delivery_priority' => $order->delivery_priority,
                    'expected_packets' => $order->expected_packets,
                    'actual_packets' => $order->actual_packets,
                    'customer_id' => $order->customer_id,
                    'customer_name' => $customerName,
                    'customer_address' => trim(implode(', ', array_filter([
                        $order->address_line1, $order->address_line2, $order->address_city, $order->address_province
                    ]))),
                    'customer_phone' => $order->address_phone ?? ($order->customer->phone_original ?? null),
                    'customer_notes' => $effectiveCustomerNotes,
                    'has_customer_notes' => !empty($effectiveCustomerNotes),
                    'order_note' => $order->note ?? null,
                    'has_order_note' => !empty($order->note),
                    'assigned_rider_id' => $order->assigned_rider_user_id,
                    'assigned_rider' => $order->assignedRider ? [
                        'id' => $order->assignedRider->id,
                        'name' => $order->assignedRider->fullname,
                    ] : null,
                    'preparation_summary' => [
                        'preparing_count' => $prepSummary->preparing ?? 0,
                        'total_items' => $prepSummary->total ?? 0,
                    ],
                    'delivery_region_id' => $order->customer->delivery_region_id ?? null,
                    'delivery_region_name' => ($order->customer->delivery_region_id ?? null) ? ($regionMap[$order->customer->delivery_region_id] ?? null) : null,
                    'updated_at' => $order->updated_at ? $order->updated_at->toIso8601String() : null,
                    'subtotal_price' => $order->subtotal_price ?? 0,
                    'discount_total' => $order->discount_total ?? 0,
                    'shipping_total' => $order->shipping_total ?? 0,
                    'tip_amount' => $order->tip_amount ?? 0,
                    'discounts' => $order->discounts ? $order->discounts->map(function($d) {
                        // coupon_code/title let the mobile receipt tell the customer's
                        // own ACCOUNT_BALANCE line apart from a real discount.
                        return ['discount_amount' => $d->discount_amount, 'discount_type' => $d->discount_type,
                                'coupon_code' => $d->coupon_code, 'discount_title' => $d->discount_title];
                    })->toArray() : [],
                    'has_verified_location' => ($order->customer && (
                        (!empty($order->customer->latitude) && !empty($order->customer->longitude))
                        || !empty($order->customer->verified_location_url)
                    )),
                    'line_items' => $order->lineItems->map(function($item) use ($order, $perItemRiderMap, $bundleMap) {
                        $riderId = $item->qurbani_assigned_rider_user_id;
                        $bundle = $bundleMap[$item->id] ?? null;
                        return [
                            'id' => $item->id,
                            'name' => $item->name ?? 'N/A',
                            'product_name' => $item->name ?? 'N/A',
                            'variant_name' => $item->sku ?? '',
                            'quantity' => (float) $item->quantity,
                            'unit_price' => (float) $item->unit_price,
                            'unit_price_formatted' => $item->unit_price ? 'Rs. ' . number_format($item->unit_price, 0) : null,
                            'line_total' => (float) $item->line_total,
                            'preparation_status' => $item->preparation_status,
                            'is_free' => (bool) $item->is_free,
                            'qurbani_day' => $item->qurbani_day,
                            'qurbani_slot' => $item->qurbani_slot,
                            'qurbani_region' => $item->qurbani_region,
                            'qurbani_sub_region' => $item->qurbani_sub_region,
                            'qurbani_delivery_type' => $item->qurbani_delivery_type,
                            'qurbani_type' => $item->qurbani_type,
                            'qurbani_paya' => $item->qurbani_paya,
                            // May-2026: per-line-item Qurbani lifecycle status + rider.
                            // qurbani_item_status defaults to NULL which the mobile
                            // client treats as "open"/unassigned (sorts to the top).
                            'qurbani_item_status' => $item->qurbani_item_status,
                            'qurbani_assigned_rider_user_id' => $riderId,
                            'qurbani_assigned_rider_name' => $riderId ? ($perItemRiderMap[$riderId] ?? null) : null,
                            'qurbani_status_updated_at' => $item->qurbani_status_updated_at
                                ? (string) $item->qurbani_status_updated_at
                                : null,
                            'qurbani_slaughtered_at' => $item->qurbani_slaughtered_at ? (string) $item->qurbani_slaughtered_at : null,
                            'qurbani_out_for_delivery_at' => $item->qurbani_out_for_delivery_at ? (string) $item->qurbani_out_for_delivery_at : null,
                            'qurbani_delivered_at' => $item->qurbani_delivered_at ? (string) $item->qurbani_delivered_at : null,
                            'category_level_2' => $item->product->attribute_2 ?? null,
                            'instructions' => $item->instructions,
                            'has_verified_location' => ($order->customer && (
                                (!empty($order->customer->latitude) && !empty($order->customer->longitude))
                                || !empty($order->customer->verified_location_url)
                            )),
                            'verified_location_url' => $order->customer->verified_location_url ?? null,
                            'cust_lat' => $order->customer->latitude ?? null,
                            'cust_lng' => $order->customer->longitude ?? null,
                            // Smart-box bundle metadata (May-2026). Mobile uses
                            // bundle_position_end / bundle_size to render the
                            // "3/5" chip on each row, and bundle_key for the
                            // partial / cross-bundle soft-warn dialogs.
                            'bundle_key'             => $bundle['bundle_key'] ?? null,
                            'bundle_size'            => $bundle['bundle_size'] ?? null,
                            'bundle_position_start'  => $bundle['bundle_position_start'] ?? null,
                            'bundle_position_end'    => $bundle['bundle_position_end'] ?? null,
                            'bundle_item_count'      => $bundle['bundle_item_count'] ?? null,
                        ];
                    })->values()->toArray(),
                    'external_source' => $order->external_source,
                ];
            });

            // Payment status summary
            $summary = [
                'total' => $formattedOrders->count(),
                'unpaid' => $formattedOrders->where('payment_status', 'unpaid')->count(),
                'partial' => $formattedOrders->where('payment_status', 'partial')->count(),
                'paid' => $formattedOrders->where('payment_status', 'paid')->count(),
            ];

            // May-2026 — Qurbani auto-WhatsApp piggyback. The Qurbani
            // Open Orders screen polls this endpoint every 30 seconds
            // while any manager has it open (web or mobile). That's a
            // far higher cadence than the 5-min rider GPS heartbeat
            // and is the most common operational scenario — a manager
            // monitoring orders is virtually guaranteed during event
            // hours. Self-throttled by the 55s Cache lock so the
            // high-frequency poll just keeps the worker warm without
            // any duplicate sends.
            $this->fireQurbaniWaAutoSender();

            return response()->json([
                'success' => true,
                'orders' => $formattedOrders->values(),
                'summary' => $summary,
            ]);

        } catch (\Exception $e) {
            \Log::error('Failed to get qurbani open orders', ['error' => $e->getMessage(), 'trace' => $e->getTraceAsString()]);
            return response()->json(['success' => false, 'message' => 'Failed to load qurbani orders: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Update qurbani details (day, slot, region, delivery_type) on an existing order
     */
    public function updateQurbaniDetails(Request $request, $orderId)
    {
        try {
            $validated = $request->validate([
                'qurbani_day' => 'nullable|string|max:50',
                'qurbani_slot' => 'nullable|string|max:50',
                'qurbani_region' => 'nullable|string|max:100',
                'qurbani_sub_region' => 'nullable|string|max:100',
                'qurbani_delivery_type' => 'nullable|string|max:50',
                // New Apr-2026 attributes — accepted so the mobile
                // edit-order / details screens can update them too.
                'qurbani_type' => 'nullable|string|max:50',
                'qurbani_paya' => 'nullable|string|max:50',
                'instructions' => 'nullable|string|max:500',
                'line_item_id' => 'nullable|integer|exists:t_crm_prod_order_line_item,id',
            ]);

            $order = OrderModel::findOrFail($orderId);
            $fields = [
                'qurbani_day' => $validated['qurbani_day'] ?? null,
                'qurbani_slot' => $validated['qurbani_slot'] ?? null,
                'qurbani_region' => $validated['qurbani_region'] ?? null,
                'qurbani_sub_region' => $validated['qurbani_sub_region'] ?? null,
                'qurbani_delivery_type' => $validated['qurbani_delivery_type'] ?? null,
            ];
            // Only patch qurbani_type / qurbani_paya when the caller actually
            // sent them — otherwise blank payloads would wipe existing values.
            if (array_key_exists('qurbani_type', $validated)) {
                $fields['qurbani_type'] = $validated['qurbani_type'];
            }
            if (array_key_exists('qurbani_paya', $validated)) {
                $fields['qurbani_paya'] = $validated['qurbani_paya'];
            }
            if (array_key_exists('instructions', $validated)) {
                $fields['instructions'] = $validated['instructions'];
            }

            if (!empty($validated['line_item_id'])) {
                $order->lineItems()->where('id', $validated['line_item_id'])->update($fields);
            } else {
                $order->lineItems()->update($fields);
            }

            // Sync first line item's values to order level for filtering
            $firstItem = $order->lineItems()->first();
            if ($firstItem) {
                $order->update([
                    'qurbani_day' => $firstItem->qurbani_day,
                    'qurbani_slot' => $firstItem->qurbani_slot,
                    'qurbani_region' => $firstItem->qurbani_region,
                    'qurbani_sub_region' => $firstItem->qurbani_sub_region,
                    'qurbani_delivery_type' => $firstItem->qurbani_delivery_type,
                ]);
            }

            return response()->json(['success' => true, 'message' => 'Qurbani details updated']);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    public function updateLineItemInstructions(Request $request, $orderId, $lineItemId)
    {
        try {
            $validated = $request->validate([
                'instructions' => 'nullable|string|max:500',
            ]);

            $lineItem = \App\Models\CRM\OrderLineItemModel::where('id', $lineItemId)
                ->where('order_id', $orderId)
                ->firstOrFail();

            $lineItem->instructions = $validated['instructions'] ?? null;
            $lineItem->save();

            return response()->json(['success' => true, 'message' => 'Instructions updated']);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Barcode-qty feature: set an open order's line-item quantity (in place,
     * stable id) from a scanned weight barcode. Mirrors a manual qty edit's
     * side effects via LineItemQuantityService (line total, order totals,
     * inventory delta) and stamps the source as 'barcode' so web + mobile can
     * show a badge. Open orders only; refuses invoiced/delivered orders.
     */
    public function updateLineItemQuantity(Request $request, $orderId, $lineItemId)
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('scan_line_item_qty')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to update quantities by scan'], 403);
        }

        $validated = $request->validate([
            'quantity' => 'required|numeric|min:0.001|max:100000',
            'source' => 'nullable|string|in:barcode,manual',
            'scanned_barcode' => 'nullable|string|max:20',
        ]);

        $order = \App\Models\CRM\OrderModel::find($orderId);
        if (!$order) {
            return response()->json(['success' => false, 'message' => 'Order not found'], 404);
        }

        $lineItem = \App\Models\CRM\OrderLineItemModel::where('id', $lineItemId)
            ->where('order_id', $orderId)
            ->first();
        if (!$lineItem) {
            return response()->json(['success' => false, 'message' => 'Line item not found in this order'], 404);
        }

        // Sep-2026: capture what the line carried BEFORE this write. A manual
        // correction clears quantity_scanned_barcode, which is exactly how the
        // 5-Sep 6.044 kg misread lost its evidence (corrected at 19:08, code gone).
        // The log line below is now the only place the old code survives.
        $previousScannedBarcode = $lineItem->quantity_scanned_barcode;
        $previousSource = $lineItem->quantity_source;

        $service = new \App\Services\CRM\LineItemQuantityService();
        $result = $service->setQuantity(
            $order,
            $lineItem,
            (float) $validated['quantity'],
            $validated['source'] ?? 'barcode',
            $user->id,
            $validated['scanned_barcode'] ?? null
        );

        // Aug-2026: log every APPLIED quantity change. A weighing that lands wrong
        // used to leave no trace of its own — the 0.505-read-as-9.205 incident had
        // to be reconstructed from inventory restore/deduct pairs. The raw barcode
        // plus previous->new is what makes the next one a lookup, not a forensic job.
        if (!empty($result['success'])) {
            $rawBarcode = $validated['scanned_barcode'] ?? null;
            $scannedKg = ($rawBarcode && preg_match('/^2\d{12}$/', $rawBarcode))
                ? ((int) substr($rawBarcode, 7, 5)) / 1000
                : null;
            \Log::info('Line item quantity set', [
                'order_id' => (int) $order->id,
                'order_number' => $order->order_number,
                'line_item_id' => (int) $lineItem->id,
                'sku' => $lineItem->sku,
                'source' => $validated['source'] ?? 'barcode',
                'scanned_barcode' => $rawBarcode,
                'scanned_kg' => $scannedKg,
                'previous_quantity' => $result['previous_quantity'] ?? null,
                'previous_source' => $previousSource,
                'previous_scanned_barcode' => $previousScannedBarcode,
                'new_quantity' => $result['new_quantity'] ?? null,
                'by_user_id' => (int) $user->id,
                'by' => $user->fullname ?? null,
            ]);
        }

        return response()->json($result, $result['success'] ? 200 : 422);
    }

    /**
     * 📦 Confirm ONE counted product (a frozen box / pack) by scanning its label.
     *
     * The quantity is NOT touched — it stays as ordered (owner ruling, 13-Sep-2026).
     * A boxed product's label carries no usable amount and every box of a product
     * prints the IDENTICAL code, so the only thing a scan can honestly establish is
     * "this is the right product, and it is on this order". That is what gets
     * stamped, as quantity_source = 'box_scan'.
     *
     * ⭐⭐ Everything the phone claims is re-checked here against the database, so a
     * client bug cannot silently mark the wrong line:
     *   - the barcode is re-decoded server-side (the phone's PLU is never trusted);
     *   - the line's product must be sell_unit = 'pcs' — a WEIGHED product sent here
     *     is refused, so this endpoint can never become a way to skip weighing;
     *   - the decoded PLU must equal that product's own Czerlop PLU.
     *
     * POST /api/rider/orders/{orderId}/line-items/{lineItemId}/box-scan
     * Body: { scanned_barcode: string }
     */
    public function confirmLineItemBoxScan(Request $request, $orderId, $lineItemId)
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('scan_line_item_qty')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to scan items'], 403);
        }

        $validated = $request->validate([
            'scanned_barcode' => 'required|string|max:20',
        ]);

        // The feature is invisible until the column exists, so an APK that lands
        // before the SQL says something true instead of stamping a row nobody can
        // read back as a box scan.
        if (!\App\Models\CRM\ProductModel::supportsSellUnit()) {
            return response()->json([
                'success' => false,
                'code' => 'not_supported',
                'message' => 'Box scanning is not switched on yet — please enter this quantity by hand.',
            ], 422);
        }

        $order = \App\Models\CRM\OrderModel::find($orderId);
        if (!$order) {
            return response()->json(['success' => false, 'message' => 'Order not found'], 404);
        }

        $lineItem = \App\Models\CRM\OrderLineItemModel::where('id', $lineItemId)
            ->where('order_id', $orderId)
            ->first();
        if (!$lineItem) {
            return response()->json(['success' => false, 'message' => 'Line item not found in this order'], 404);
        }

        $decoded = app(\App\Services\CRM\WeightBarcodeDecoder::class)->decode($validated['scanned_barcode']);
        if (!$decoded) {
            return response()->json([
                'success' => false,
                'code' => 'bad_barcode',
                'message' => 'That is not a valid scale label.',
            ], 422);
        }

        // Resolve the product the SAME way the open-orders payload does: SKU first
        // (the reliable key — a line item's own product_id is an EXTERNAL id),
        // variant_id as the fallback for the rare empty-sku line.
        $product = $this->resolveProductForLineItem($lineItem);
        if (!$product) {
            return response()->json([
                'success' => false,
                'code' => 'no_product',
                'message' => 'This line is not linked to a product — please enter the quantity by hand.',
            ], 422);
        }

        if (!$product->isSoldByPiece()) {
            return response()->json([
                'success' => false,
                'code' => 'not_a_box',
                'message' => $product->title . ' is sold by weight — scan it to record its weight instead.',
            ], 422);
        }

        if ((int) $product->czerlop_product_id !== (int) $decoded['plu']) {
            return response()->json([
                'success' => false,
                'code' => 'plu_mismatch',
                'message' => 'That label is PLU ' . $decoded['plu'] . ', not ' . $product->title . '.',
            ], 422);
        }

        $previousSource = $lineItem->quantity_source;
        $service = new \App\Services\CRM\LineItemQuantityService();
        $result = $service->markBoxScanned($order, $lineItem, $decoded['raw'], $user->id);

        // Same forensic value as the weighed path: the raw code, the line, and who.
        // ⭐ `scanned_units` is the label's five digits read as a count. Nothing uses
        //    it — it is logged so that if the scale's template changes again, the
        //    evidence is in the log instead of on a sticker.
        if (!empty($result['success'])) {
            \Log::info('Line item box scan confirmed', [
                'order_id' => (int) $order->id,
                'order_number' => $order->order_number,
                'line_item_id' => (int) $lineItem->id,
                'sku' => $lineItem->sku,
                'product_id' => (int) $product->id,
                'plu' => (int) $decoded['plu'],
                'scanned_barcode' => $decoded['raw'],
                'scanned_units' => $decoded['units'],
                'quantity_unchanged' => (float) $lineItem->quantity,
                'previous_source' => $previousSource,
                'already_confirmed' => !empty($result['unchanged']),
                'by_user_id' => (int) $user->id,
                'by' => $user->fullname ?? null,
            ]);
        }

        return response()->json($result, $result['success'] ? 200 : 422);
    }

    /**
     * The product behind an order line: SKU -> variant -> product, with variant_id
     * as a fallback. Mirrors the resolution used to build the open-orders payload,
     * so the phone and this endpoint can never disagree about which product a line
     * is. Returns null when the line matches nothing (hand-typed lines).
     */
    private function resolveProductForLineItem(\App\Models\CRM\OrderLineItemModel $lineItem)
    {
        $sku = trim((string) ($lineItem->sku ?? ''));
        if ($sku !== '') {
            $productId = \DB::table('t_crm_prod_product_variant')
                ->where('sku', $sku)->value('product_id');
            if ($productId) {
                return \App\Models\CRM\ProductModel::find($productId);
            }
        }
        if ($lineItem->variant_id) {
            $productId = \DB::table('t_crm_prod_product_variant')
                ->where('id', (int) $lineItem->variant_id)->value('product_id');
            if ($productId) {
                return \App\Models\CRM\ProductModel::find($productId);
            }
        }
        return null;
    }

    /**
     * Mark ONE open-order line item free / charged from the mobile app, so a
     * complimentary item no longer forces a trip to the web Edit Invoice screen.
     *
     * Permission: whoever may CREATE an order may mark an item free (owner
     * ruling, Aug-2026) — deliberately NOT scan_line_item_qty, which is the
     * weighing permission. The mobile-OR-web check mirrors OrderController::store()
     * so a role granted only the web permission does not silently lose access.
     *
     * All the money handling (line totals, order totals, and the refusals on
     * closed / already-invoiced orders) lives in LineItemQuantityService::setFree.
     *
     * PUT /api/rider/orders/{orderId}/line-items/{lineItemId}/free
     * Body: { is_free: bool }
     */
    public function updateLineItemFree(Request $request, $orderId, $lineItemId)
    {
        $user = Auth::user();
        if (!$user || !($user->hasMobilePermission('create_orders') || $user->hasPermission('create_orders'))) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to mark items free'], 403);
        }

        $validated = $request->validate([
            'is_free' => 'required|boolean',
        ]);

        $order = \App\Models\CRM\OrderModel::find($orderId);
        if (!$order) {
            return response()->json(['success' => false, 'message' => 'Order not found'], 404);
        }

        $lineItem = \App\Models\CRM\OrderLineItemModel::where('id', $lineItemId)
            ->where('order_id', $orderId)
            ->first();
        if (!$lineItem) {
            return response()->json(['success' => false, 'message' => 'Line item not found in this order'], 404);
        }

        $service = new \App\Services\CRM\LineItemQuantityService();
        $result = $service->setFree($order, $lineItem, (bool) $validated['is_free'], $user->id);

        return response()->json($result, $result['success'] ? 200 : 422);
    }

    /**
     * Barcode-qty feature: set MULTIPLE open-order line-item quantities in ONE
     * request (the mobile multi-row manual "Save all"). Atomic — all rows are
     * validated and applied in a single transaction, totals recomputed once
     * (see LineItemQuantityService::setQuantitiesBatch). Open orders only.
     *
     * PUT /api/rider/orders/{orderId}/line-items/quantities
     * Body: { items: [ { line_item_id, quantity, source?, scanned_barcode? }, ... ] }
     * The quantity is already weight-factor-adjusted by the client (same as web).
     */
    public function updateLineItemQuantitiesBatch(Request $request, $orderId)
    {
        $user = Auth::user();
        if (!$user || !$user->hasMobilePermission('scan_line_item_qty')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to update quantities by scan'], 403);
        }

        $validated = $request->validate([
            'items' => 'required|array|min:1|max:200',
            'items.*.line_item_id' => 'required|integer',
            'items.*.quantity' => 'required|numeric|min:0.001|max:100000',
            'items.*.source' => 'nullable|string|in:barcode,manual',
            'items.*.scanned_barcode' => 'nullable|string|max:20',
        ]);

        $order = \App\Models\CRM\OrderModel::find($orderId);
        if (!$order) {
            return response()->json(['success' => false, 'message' => 'Order not found'], 404);
        }

        $service = new \App\Services\CRM\LineItemQuantityService();
        $result = $service->setQuantitiesBatch($order, $validated['items'], $user->id);

        return response()->json($result, $result['success'] ? 200 : 422);
    }

    // =========================================================================
    // QURBANI: Per-line-item status & rider assignment (May-2026)
    //
    // These four endpoints are deliberately scoped at the LINE ITEM level
    // (not the order level) so bulk operations cannot accidentally cascade
    // to every product in an order — that was the long-standing bug
    // operations reported with the regular-orders Mark-as-Prepared flow.
    //
    // Auth: every endpoint requires `access_qurbani_mode` mobile permission,
    // matching the rest of the Qurbani API surface.
    //
    // Status updates ONLY touch:
    //   - qurbani_item_status
    //   - qurbani_status_updated_at / by
    // Critically NOT preparation_status, so the regular Mark-as-Prepared
    // inventory deduction flow stays untouched even if the same line items
    // exist on a non-Qurbani path.
    // =========================================================================

    /**
     * Bulk update Qurbani per-line-item status.
     *
     * POST /api/rider/qurbani/line-items/bulk-update-status
     * Body:
     *   line_item_ids: int[]            (the SPECIFIC line items to update)
     *   qurbani_item_status: string|null  (one of the option_value slugs in
     *                                      t_crm_qurbani_field_options where
     *                                      field_name='qurbani_item_status',
     *                                      or null/empty for "open"/unassigned)
     *
     * Note: there is NO order_id in the URL — callers pass exact line item
     * IDs and only those rows are touched.
     */
    public function bulkUpdateQurbaniItemStatus(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'No permission'], 403);
            }

            $validated = $request->validate([
                'line_item_ids' => 'required|array|min:1',
                'line_item_ids.*' => 'required|integer',
                'qurbani_item_status' => 'nullable|string|max:50',
            ]);

            $newStatus = $validated['qurbani_item_status'] ?? null;
            if ($newStatus === '') $newStatus = null;

            // Validate against t_crm_qurbani_field_options when a non-null
            // status was supplied. NULL is always valid (means "open"/unassigned).
            if ($newStatus !== null) {
                $exists = \DB::table('t_crm_qurbani_field_options')
                    ->where('field_name', 'qurbani_item_status')
                    ->where('option_value', $newStatus)
                    ->where('is_active', 1)
                    ->exists();
                if (!$exists) {
                    return response()->json([
                        'success' => false,
                        'message' => "Unknown qurbani item status: {$newStatus}",
                    ], 422);
                }
            }

            $now = now();
            // May-2026 — pre-formatted Carbon timestamp string. Used
            // INSIDE the COALESCE() raw expressions below so the stamp
            // matches Laravel's config('app.timezone') (Asia/Karachi
            // in prod) instead of MySQL's server timezone (UTC on
            // most cloud hosts). Earlier code used `NOW()` which is
            // server-MySQL-timezone — that's why slaughtered_at
            // showed up ~5h behind the rest of the app, and why the
            // 1-minute slaughter trigger comparison drifted. Safe to
            // splice straight into SQL: toDateTimeString() always
            // returns a fixed 'Y-m-d H:i:s' format with no quote chars.
            $nowStr = $now->toDateTimeString();
            $update = [
                'qurbani_item_status' => $newStatus,
                'qurbani_status_updated_at' => $now,
                'qurbani_status_updated_by' => $user->id,
                'updated_by' => $user->id,
            ];
            // May-17-2026: stamp the per-state transition column when a line
            // item enters that state. We don't overwrite if the column is
            // already set (transitions in/out of a state shouldn't lose the
            // FIRST-entered timestamp), so the update is conditional via raw
            // expressions. NULL stays NULL until the state is first entered.
            if ($newStatus === 'slaughtered') {
                $update['qurbani_slaughtered_at'] = \DB::raw("COALESCE(qurbani_slaughtered_at, '{$nowStr}')");
            } elseif ($newStatus === 'out_for_delivery') {
                $update['qurbani_out_for_delivery_at'] = \DB::raw("COALESCE(qurbani_out_for_delivery_at, '{$nowStr}')");
            } elseif ($newStatus === 'delivered') {
                $update['qurbani_delivered_at'] = \DB::raw("COALESCE(qurbani_delivered_at, '{$nowStr}')");
            }
            $updated = \App\Models\CRM\OrderLineItemModel::whereIn('id', $validated['line_item_ids'])
                ->update($update);

            return response()->json([
                'success' => true,
                'message' => "Updated {$updated} item(s)",
                'updated_count' => $updated,
                'qurbani_item_status' => $newStatus,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \Log::error('Failed bulk qurbani item status update', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed to update items: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Bulk assign a rider to specific Qurbani line items.
     *
     * POST /api/rider/qurbani/line-items/bulk-assign-rider
     * Body:
     *   line_item_ids: int[]
     *   assigned_rider_user_id: int|null   (null clears the assignment)
     *
     * Order-level t_crm_prod_order.assigned_rider_user_id is intentionally
     * NOT modified — Qurbani is the only flow with per-item riders today.
     */
    public function bulkAssignQurbaniRider(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'No permission'], 403);
            }

            $validated = $request->validate([
                'line_item_ids' => 'required|array|min:1',
                'line_item_ids.*' => 'required|integer',
                'assigned_rider_user_id' => 'nullable|integer|exists:t_sys_user,id',
            ]);

            $riderId = $validated['assigned_rider_user_id'] ?? null;

            $updated = \App\Models\CRM\OrderLineItemModel::whereIn('id', $validated['line_item_ids'])
                ->update([
                    'qurbani_assigned_rider_user_id' => $riderId,
                    'updated_by' => $user->id,
                ]);

            $riderName = null;
            if ($riderId) {
                $riderName = \DB::table('t_sys_user')->where('id', $riderId)->value('fullname');
            }

            return response()->json([
                'success' => true,
                'message' => $riderId
                    ? "Assigned {$riderName} to {$updated} item(s)"
                    : "Cleared rider on {$updated} item(s)",
                'updated_count' => $updated,
                'assigned_rider_user_id' => $riderId,
                'assigned_rider_name' => $riderName,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \Log::error('Failed bulk qurbani rider assignment', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed to assign rider: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Single-item Qurbani status update (thin wrapper around the bulk endpoint
     * so mobile can call it without building a one-element array client-side).
     *
     * PUT /api/rider/qurbani/line-items/{lineItemId}/status
     */
    public function updateQurbaniItemStatus(Request $request, $lineItemId)
    {
        $request->merge(['line_item_ids' => [(int) $lineItemId]]);
        return $this->bulkUpdateQurbaniItemStatus($request);
    }

    /**
     * Single-item Qurbani rider assignment.
     *
     * PUT /api/rider/qurbani/line-items/{lineItemId}/rider
     */
    public function assignQurbaniRider(Request $request, $lineItemId)
    {
        $request->merge(['line_item_ids' => [(int) $lineItemId]]);
        return $this->bulkAssignQurbaniRider($request);
    }

    /**
     * Rider Qurbani delivery feed (May-2026).
     *
     * GET /api/rider/qurbani/my-deliveries
     *
     * Returns ONLY orders where the current user is assigned to one or more
     * line items via t_crm_prod_order_line_item.qurbani_assigned_rider_user_id.
     * Each order payload includes ONLY the items assigned to this rider —
     * other line items in the same order belong to other riders / other
     * slots and are filtered out (they would confuse the rider screen).
     *
     * Bundle metadata (bundle_size, bundle_position_end, bundle_key) is
     * computed across the FULL order so the rider sees the correct
     * "3 of 5 packets" position even when their assignment covers a
     * subset of the bundle.
     *
     * Filtering: ?show=ofd_only|open|delivered|all (default ofd_only)
     *   - ofd_only   → only items with qurbani_item_status='out_for_delivery'
     *                  (default mode for the rider screen — May-2026: hides
     *                  items still 'open' / 'slaughtered' so the rider's
     *                  Qurbani view only contains items that have been
     *                  explicitly handed off to delivery by the manager).
     *   - open       → legacy: any item not yet 'delivered'.
     *   - delivered  → delivered items only.
     *   - all        → everything assigned, no status filter.
     */
    public function getQurbaniRiderDeliveries(Request $request)
    {
        try {
            $user = Auth::user();
            // Authorisation here is per-item (we filter to line items where
            // qurbani_assigned_rider_user_id = user->id), so we do NOT gate
            // on access_qurbani_mode — that permission is for the Qurbani
            // dispatch / management screens, not the rider's own feed of
            // assignments. Rider users without that permission still need
            // to be able to see what's been pushed to them.

            // May-2026 — default is now 'ofd_only' (was 'open'). The
            // rider's screen should only surface items the manager has
            // explicitly moved into the out-for-delivery lane; items
            // still being processed at the slaughterhouse ('open' or
            // 'slaughtered' status) are noise that confused riders
            // about what was actually theirs to deliver. Old mobile
            // builds that still send show=open continue to get the
            // legacy behaviour, so this is backwards-compatible.
            $show = strtolower((string) $request->get('show', 'ofd_only'));
            if (!in_array($show, ['ofd_only', 'open', 'delivered', 'all'], true)) {
                $show = 'ofd_only';
            }

            // Phase A3 (May-2026) — passive late detection on the
            // RIDER's own feed too. If their earliest pending dispatched
            // bundle's stored ETA has slipped past the threshold, fire
            // ONE recompute before we read the rows below so the rider
            // gets fresh ETAs in the same response. No-op when rate-
            // limited / disabled / no GPS / no Google base.
            $passiveResult = null;
            try {
                $masterEnabled = \App\Models\FIN\ConfigModel::get('qurbani_eta_refresh_enabled', '1') === '1';
                if ($masterEnabled) {
                    $thresholdMin = (int) \App\Models\FIN\ConfigModel::get('qurbani_eta_delay_threshold_minutes', '10');
                    if ($thresholdMin < 1) $thresholdMin = 10;
                    $cutoff = now()->subMinutes($thresholdMin);
                    $latestSlip = \DB::table('t_crm_prod_order_line_item')
                        ->where('qurbani_assigned_rider_user_id', $user->id)
                        ->whereNotNull('qurbani_dispatched_at')
                        ->whereNotNull('qurbani_estimated_delivery_at')
                        ->whereNull('qurbani_delivered_at')
                        ->where('qurbani_estimated_delivery_at', '<', $cutoff)
                        ->where(function ($q) {
                            $q->whereNull('qurbani_item_status')
                              ->orWhere('qurbani_item_status', '!=', 'delivered');
                        })
                        ->exists();
                    if ($latestSlip) {
                        $passiveResult = $this->recomputeQurbaniEtasInternal((int) $user->id, (int) $user->id, 'rider_passive_late_detect');
                    }
                }
            } catch (\Exception $e) {
                \Log::warning('Qurbani rider passive late-detect failed', [
                    'user_id' => $user->id, 'error' => $e->getMessage(),
                ]);
            }

            // Step 1: discover orders where this rider has at least one
            // assigned line item. We start from the line-item table because
            // assignment lives there now (not on the order).
            $assignedQuery = \DB::table('t_crm_prod_order_line_item')
                ->where('qurbani_assigned_rider_user_id', $user->id);
            if ($show === 'ofd_only') {
                // May-2026 — only items explicitly marked OFD by the
                // manager. Hides everything still 'open' / 'slaughtered'
                // so the rider sees a focused list of what's ready to
                // actually deliver.
                $assignedQuery->where('qurbani_item_status', 'out_for_delivery');
            } elseif ($show === 'open') {
                $assignedQuery->where(function($q) {
                    $q->whereNull('qurbani_item_status')
                      ->orWhere('qurbani_item_status', '!=', 'delivered');
                });
            } elseif ($show === 'delivered') {
                $assignedQuery->where('qurbani_item_status', 'delivered');
            }
            $orderIds = $assignedQuery->pluck('order_id')->unique()->values();
            if ($orderIds->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'orders' => [],
                    'summary' => ['total' => 0, 'open_items' => 0, 'delivered_items' => 0],
                ]);
            }

            $orders = \App\Models\CRM\OrderModel::with(['customer', 'lineItems' => function($q) {
                    $q->select(
                        'id', 'order_id', 'product_id', 'name', 'sku', 'quantity', 'unit_price', 'line_total',
                        'qurbani_day', 'qurbani_slot', 'qurbani_region', 'qurbani_sub_region',
                        'qurbani_delivery_type', 'qurbani_type', 'qurbani_paya',
                        'qurbani_item_status', 'qurbani_assigned_rider_user_id',
                        'qurbani_status_updated_at',
                        'qurbani_slaughtered_at', 'qurbani_out_for_delivery_at', 'qurbani_delivered_at',
                        'qurbani_delivery_priority', 'qurbani_estimated_delivery_at',
                        'qurbani_eta_calculated_at', 'qurbani_dispatched_at', 'qurbani_dispatched_by',
                        'qurbani_started_delivery_at',
                        'qurbani_live_tracking_enabled',
                        'instructions'
                    );
                }, 'lineItems.product' => function($q) {
                    $q->select('id', 'attribute_2');
                }])
                ->whereIn('id', $orderIds)
                ->orderBy('order_date', 'desc')
                ->get();

            // Compute bundles across the FULL order line items so the
            // rider sees the same "3/5" position the dispatch screen shows.
            $bundleInputs = [];
            foreach ($orders as $o) {
                foreach ($o->lineItems as $li) {
                    $bundleInputs[] = [
                        'id'                    => $li->id,
                        'order_id'              => $li->order_id,
                        'quantity'              => $li->quantity,
                        'qurbani_day'           => $li->qurbani_day,
                        'qurbani_slot'          => $li->qurbani_slot,
                        'qurbani_delivery_type' => $li->qurbani_delivery_type,
                        'category_level_2'      => $li->product->attribute_2 ?? null,
                        'product_id'            => $li->product_id,
                    ];
                }
            }
            $bundleMap = (new \App\Services\QurbaniBundleService())->computeBundles($bundleInputs);

            $payload = [];
            $totalOpen = 0; $totalDelivered = 0;
            foreach ($orders as $order) {
                // Filter line items down to ones assigned to this rider, and
                // apply the show filter (ofd_only|open|delivered|all).
                $myItems = $order->lineItems->filter(function($li) use ($user, $show) {
                    if ((int) $li->qurbani_assigned_rider_user_id !== (int) $user->id) return false;
                    $isDelivered = $li->qurbani_item_status === 'delivered';
                    $isOfd       = $li->qurbani_item_status === 'out_for_delivery';
                    if ($show === 'ofd_only') return $isOfd;
                    if ($show === 'open')     return !$isDelivered;
                    if ($show === 'delivered') return $isDelivered;
                    return true;
                })->values();

                if ($myItems->isEmpty()) continue;

                // Group my items by bundle_key so the mobile UI can render
                // one card per bundle (the way the rider thinks about
                // delivery: one trip, one customer, one bundle).
                $bundles = [];
                foreach ($myItems as $li) {
                    $b = $bundleMap[$li->id] ?? null;
                    $bk = $b['bundle_key'] ?? "no-bundle:{$li->id}";
                    if (!isset($bundles[$bk])) {
                        $bundles[$bk] = [
                            'bundle_key' => $bk,
                            'bundle_size' => $b['bundle_size'] ?? null,
                            'qurbani_day' => $li->qurbani_day,
                            'qurbani_slot' => $li->qurbani_slot,
                            'qurbani_delivery_type' => $li->qurbani_delivery_type,
                            'items' => [],
                            'my_qty_in_bundle' => 0,
                            'all_delivered' => true,
                            // Route metadata — every line item in the
                            // bundle stores the same priority/ETA so we
                            // can read them off the first item.
                            'qurbani_delivery_priority'      => $li->qurbani_delivery_priority,
                            'qurbani_estimated_delivery_at'  => $li->qurbani_estimated_delivery_at
                                ? (string) $li->qurbani_estimated_delivery_at : null,
                            'qurbani_eta_calculated_at'      => $li->qurbani_eta_calculated_at
                                ? (string) $li->qurbani_eta_calculated_at : null,
                            'qurbani_dispatched_at'          => $li->qurbani_dispatched_at
                                ? (string) $li->qurbani_dispatched_at : null,
                            'qurbani_dispatched_by'          => $li->qurbani_dispatched_by,
                            'qurbani_started_delivery_at'    => $li->qurbani_started_delivery_at
                                ? (string) $li->qurbani_started_delivery_at : null,
                            'qurbani_live_tracking_enabled'  => (int) ($li->qurbani_live_tracking_enabled ?? 0) === 1,
                            'qurbani_delivered_at'           => null,
                            // Dispatch lifecycle: drives the rider /
                            // manager UI grouping (Pending vs Dispatched
                            // batch). 'delivered' takes precedence and
                            // is set after the items loop below.
                            'bundle_dispatch_status'         => $li->qurbani_dispatched_at
                                ? 'dispatched' : 'pending',
                        ];
                    }
                    $isDelivered = $li->qurbani_item_status === 'delivered';
                    if (!$isDelivered) $bundles[$bk]['all_delivered'] = false;
                    if ($li->qurbani_delivered_at) {
                        $existing = $bundles[$bk]['qurbani_delivered_at'];
                        if (!$existing || strtotime((string) $li->qurbani_delivered_at) > strtotime($existing)) {
                            $bundles[$bk]['qurbani_delivered_at'] = (string) $li->qurbani_delivered_at;
                        }
                    }
                    $bundles[$bk]['my_qty_in_bundle'] += max(1, (int) $li->quantity);
                    $bundles[$bk]['items'][] = [
                        'id' => $li->id,
                        'name' => $li->name,
                        'quantity' => (float) $li->quantity,
                        'category_level_2' => $li->product->attribute_2 ?? null,
                        'qurbani_type' => $li->qurbani_type,
                        'qurbani_paya' => $li->qurbani_paya,
                        // May-2026 — Region is needed by the Hand Over
                        // modal so it can pre-group target riders by
                        // matching region (same UX as the manager
                        // bulk-assign picker in QurbaniOpenOrdersScreen).
                        // Already loaded on $li from the lineItems
                        // select above — just surfacing it.
                        'qurbani_region'     => $li->qurbani_region,
                        'qurbani_sub_region' => $li->qurbani_sub_region,
                        'qurbani_item_status' => $li->qurbani_item_status,
                        'qurbani_status_updated_at' => $li->qurbani_status_updated_at
                            ? (string) $li->qurbani_status_updated_at : null,
                        'instructions' => $li->instructions,
                        'bundle_position_start' => $b['bundle_position_start'] ?? null,
                        'bundle_position_end'   => $b['bundle_position_end'] ?? null,
                        'bundle_size'           => $b['bundle_size'] ?? null,
                        // Total distinct line items in the FULL bundle (not
                        // just the ones assigned to this rider). The
                        // mobile chip uses this to decide whether the
                        // i/N label is meaningful — a single-line-item
                        // bundle shouldn't surface "3/3".
                        'bundle_item_count'     => $b['bundle_item_count'] ?? null,
                    ];

                    if ($isDelivered) $totalDelivered++; else $totalOpen++;
                }

                // Sort items inside each bundle by their packet position so
                // rider sees 1/5, 2/5, 3/5… in order — not jumbled by
                // line-item id. NULL position falls last (defensive).
                foreach ($bundles as &$bRef) {
                    usort($bRef['items'], function($a, $b) {
                        $ap = $a['bundle_position_start'] ?? PHP_INT_MAX;
                        $bp = $b['bundle_position_start'] ?? PHP_INT_MAX;
                        return $ap <=> $bp;
                    });
                    // bundle_dispatch_status finalization: 'delivered'
                    // only when EVERY rider-owned item is delivered.
                    if ($bRef['all_delivered']) {
                        $bRef['bundle_dispatch_status'] = 'delivered';
                    }
                }
                unset($bRef);

                $customerName = $order->name ?? null;
                if (!$customerName && ($order->address_first_name || $order->address_last_name)) {
                    $customerName = trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? ''));
                }
                if (!$customerName && $order->customer) {
                    $customerName = trim(($order->customer->first_name ?? '') . ' ' . ($order->customer->last_name ?? '')) ?: null;
                }

                // Verified-location info — surfaced so the rider can see
                // who saved the pin BEFORE tapping the address.
                // Phase E (May-2026) — resolve through the URL-parse
                // fallback so customers with verified_location_url but
                // no pin row aren't silently dropped from ETA calcs.
                $cust = $order->customer;
                $resolved = $this->resolveCustomerDispatchCoords($cust);
                $hasCoords = $resolved['lat'] !== null && $resolved['lng'] !== null;
                $custLat = $resolved['lat'];
                $custLng = $resolved['lng'];

                // The order's "route position" = the min priority across
                // its bundles (a customer with priority-1 stop comes
                // first in the rider's screen even if their second
                // bundle is at priority 7).
                $minPriority = null;
                foreach ($bundles as $b) {
                    if ($b['qurbani_delivery_priority'] !== null) {
                        $p = (int) $b['qurbani_delivery_priority'];
                        if ($minPriority === null || $p < $minPriority) $minPriority = $p;
                    }
                }

                $payload[] = [
                    'id' => $order->id,
                    'order_number' => $order->order_number,
                    'customer_id' => $order->customer_id,
                    'customer_name' => $customerName ?: 'Unknown',
                    'customer_phone' => $order->address_phone ?? ($order->customer->phone_original ?? null),
                    'customer_address' => trim(implode(', ', array_filter([
                        $order->address_line1, $order->address_line2, $order->address_city,
                    ]))),
                    'order_status' => $order->order_status,
                    'qurbani_region' => $order->qurbani_region,
                    'bundles' => array_values($bundles),
                    'my_item_count' => $myItems->count(),
                    'my_total_qty'  => $myItems->sum(fn($li) => max(1, (int) $li->quantity)),
                    'route_priority' => $minPriority,
                    // Verified-location fields. cust_lat/lng take
                    // precedence over verified_location_url when the
                    // rider taps the address — they're a deterministic
                    // pin, not a free-text URL.
                    'has_verified_location' => $hasCoords || ($cust && !empty($cust->verified_location_url)),
                    'cust_lat' => $custLat,
                    'cust_lng' => $custLng,
                    'verified_location_url' => $cust->verified_location_url ?? null,
                    'verified_location_saved_by' => $cust->verified_location_saved_by ?? null,
                    'verified_location_saved_at' => $cust && $cust->verified_location_saved_at
                        ? (string) $cust->verified_location_saved_at : null,
                    // May-2026 diagnostic — when this is non-null the
                    // mobile warning banner can tell the rider WHY the
                    // pin couldn't be turned into coords (short link not
                    // expanded, plus code, etc.) instead of the generic
                    // "missing coords".
                    'coords_source' => $resolved['source'] ?? null,
                    'coords_reason' => $resolved['reason'] ?? null,
                ];
            }

            // Sort: orders with a priority come first (in priority asc),
            // then the rest by order_date desc (existing behaviour).
            usort($payload, function ($a, $b) {
                $pa = $a['route_priority'];
                $pb = $b['route_priority'];
                if ($pa !== null && $pb !== null) return $pa <=> $pb;
                if ($pa !== null) return -1;
                if ($pb !== null) return 1;
                return 0;
            });

            // Compute fleet-level dispatch + lock summary so the rider
            // can show "Route set by X at HH:MM" banner without an extra
            // round-trip.
            $latestDispatchedAt = null;
            $latestDispatchedBy = null;
            $latestStartedAt = null;
            // Phase 1 — bundle-shared aggregate: any non-delivered
            // dispatched bundle has live tracking ON?
            $liveTrackingEnabled = false;
            foreach ($payload as $p) {
                foreach ($p['bundles'] as $b) {
                    if (!empty($b['qurbani_dispatched_at'])) {
                        if (!$latestDispatchedAt || strtotime($b['qurbani_dispatched_at']) > strtotime($latestDispatchedAt)) {
                            $latestDispatchedAt = $b['qurbani_dispatched_at'];
                            $latestDispatchedBy = $b['qurbani_dispatched_by'] ?? null;
                        }
                    }
                    if (!empty($b['qurbani_started_delivery_at'])) {
                        if (!$latestStartedAt || strtotime($b['qurbani_started_delivery_at']) > strtotime($latestStartedAt)) {
                            $latestStartedAt = $b['qurbani_started_delivery_at'];
                        }
                    }
                    if (!empty($b['qurbani_live_tracking_enabled'])
                        && empty($b['qurbani_delivered_at'])
                        && !($b['all_delivered'] ?? false)) {
                        $liveTrackingEnabled = true;
                    }
                }
            }
            $dispatchedByName = null;
            if ($latestDispatchedBy) {
                $dispatchedByName = \DB::table('t_sys_user')->where('id', $latestDispatchedBy)->value('fullname');
            }

            // Resolve verifier user IDs to names in a single query.
            $verifierIds = [];
            foreach ($payload as $p) {
                if (!empty($p['verified_location_saved_by'])) $verifierIds[] = $p['verified_location_saved_by'];
            }
            if (!empty($verifierIds)) {
                $names = \DB::table('t_sys_user')
                    ->whereIn('id', array_unique($verifierIds))
                    ->pluck('fullname', 'id')
                    ->toArray();
                // Customer-app pins are stamped with the sentinel id -> "Customer".
                $names[\App\Models\CRM\CustomerModel::VERIFIED_PIN_CUSTOMER_ID] = 'Customer';
                foreach ($payload as &$p) {
                    $vid = $p['verified_location_saved_by'] ?? null;
                    $p['verified_location_saved_by_name'] = ($vid && isset($names[$vid])) ? $names[$vid] : null;
                }
                unset($p);
            } else {
                foreach ($payload as &$p) { $p['verified_location_saved_by_name'] = null; }
                unset($p);
            }

            // May-2026 — Qurbani auto-WhatsApp piggyback for the
            // rider-side delivery feed. Rider's My Deliveries screen
            // polls this every 30s while open, so an active rider
            // also keeps the worker alive without depending on the
            // GPS heartbeat being functional (Android background
            // service can flake). 55s Cache lock prevents spam.
            $this->fireQurbaniWaAutoSender();

            // May-2026 — Re-hydrate the rider's return-to-base ETA from
            // the dispatch cache so it survives screen reloads (the
            // dispatch endpoint only returns it once; without this the
            // chip vanishes the moment the user backgrounds the app).
            $cachedRtb = $latestDispatchedAt ? $this->getCachedQurbaniReturnToBase((int) $user->id) : null;

            return response()->json([
                'success' => true,
                'orders' => $payload,
                'summary' => [
                    'total' => count($payload),
                    'open_items' => $totalOpen,
                    'delivered_items' => $totalDelivered,
                ],
                'route_lock' => $this->getQurbaniRouteLockInfo($user->id),
                'dispatch' => [
                    'dispatched_at' => $latestDispatchedAt,
                    'dispatched_by' => $latestDispatchedBy ? (int) $latestDispatchedBy : null,
                    'dispatched_by_name' => $dispatchedByName,
                    'started_delivery_at' => $latestStartedAt,
                    // Phase 1 — server-stored Live ETA tracking flag.
                    // Replaces the old AsyncStorage per-dispatch toggle:
                    // rider screen reads this to gate the 3-min refresh
                    // loop; manager planner mutates it via the new
                    // POST .../live-tracking endpoint.
                    'live_tracking_enabled' => $liveTrackingEnabled,
                ],
                // May-2026 — same shape returned by the dispatch endpoint
                // (null when not cached / no active dispatch).
                'return_to_base' => $cachedRtb,
                // Phase A3 — server tells the rider's screen when it
                // auto-recomputed because something slipped past
                // threshold. Mobile shows a one-off toast.
                'passive_recompute' => $passiveResult,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to load qurbani rider deliveries', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Bulk mark Qurbani line items as 'delivered' from the rider's app.
     *
     * POST /api/rider/qurbani/line-items/bulk-mark-delivered
     * Body: { line_item_ids: int[] }
     *
     * Distinct from bulkUpdateQurbaniItemStatus because this endpoint:
     *   - Only ever sets qurbani_item_status='delivered' (no slug freedom)
     *   - Validates that the caller is the assigned rider on every item
     *     (anti-tamper — a rider can't mark someone else's items)
     *   - Auto-promotes parent order_status to 'delivered' once ALL line
     *     items in the order are qurbani_item_status='delivered'. The
     *     ledger guard (OrderModel::hasPreReceivedPayments) keeps Qurbani
     *     orders out of the rider ledger pending list.
     *   - Records a delivery snapshot into t_crm_order_status_history if
     *     the order is auto-promoted.
     */
    public function bulkMarkQurbaniItemsDelivered(Request $request)
    {
        try {
            $user = Auth::user();
            // Authorisation here is per-item — every line item must have
            // qurbani_assigned_rider_user_id == $user->id (verified below).
            // We deliberately do NOT require access_qurbani_mode because
            // that permission is for the Qurbani dispatch screens, not for
            // riders confirming their own deliveries. Pattern matches
            // markOrderDelivered() for regular orders, which also relies
            // solely on rider-of-record auth.
            //
            // The qurbani_rider_delivered_enabled config used to gate this
            // endpoint, but we've decoupled it: the toggle now strictly
            // controls whether regular orders are HIDDEN in rider mode
            // (see RiderTabs in mobile nav). Mark-delivered must work
            // regardless of toggle state so admins can test the flow off
            // season — the per-item assigned-rider check is the real gate.

            $validated = $request->validate([
                'line_item_ids' => 'required|array|min:1',
                'line_item_ids.*' => 'required|integer',
                'latitude' => 'nullable|numeric',
                'longitude' => 'nullable|numeric',
            ]);

            // Authorisation: every line item must be assigned to the caller.
            $items = \App\Models\CRM\OrderLineItemModel::whereIn('id', $validated['line_item_ids'])->get();
            if ($items->isEmpty()) {
                return response()->json(['success' => false, 'message' => 'No items found'], 404);
            }
            foreach ($items as $li) {
                if ((int) $li->qurbani_assigned_rider_user_id !== (int) $user->id) {
                    return response()->json([
                        'success' => false,
                        'message' => "Line item #{$li->id} is not assigned to you",
                    ], 403);
                }
            }

            $now = now();
            // See timezone note in the sibling bulkUpdateQurbaniItemStatus
            // — COALESCE NOW() returns MySQL-server TZ; we splice a
            // Carbon-stamped string instead so the value matches
            // config('app.timezone').
            $nowStr = $now->toDateTimeString();
            $updated = \App\Models\CRM\OrderLineItemModel::whereIn('id', $validated['line_item_ids'])
                ->update([
                    'qurbani_item_status' => 'delivered',
                    'qurbani_status_updated_at' => $now,
                    'qurbani_status_updated_by' => $user->id,
                    'updated_by' => $user->id,
                    // Stamp first-time-delivered timestamp (preserve original
                    // if somehow re-delivered after being undone).
                    'qurbani_delivered_at' => \DB::raw("COALESCE(qurbani_delivered_at, '{$nowStr}')"),
                ]);

            // Auto-promote: if ALL line items in any of the affected orders
            // are now qurbani_item_status='delivered', bump the parent
            // order_status to 'delivered' too. The order's own ledger
            // posting flow already skips Qurbani orders via
            // hasPreReceivedPayments() so this won't pollute the rider
            // ledger pending list.
            $autoPromoted = [];
            $affectedOrderIds = $items->pluck('order_id')->unique();
            foreach ($affectedOrderIds as $oid) {
                $order = \App\Models\CRM\OrderModel::with('customer')->find($oid);
                if (!$order) continue;
                if (in_array($order->order_status, ['delivered', 'completed', 'cancelled'])) continue;

                $totalCount = \App\Models\CRM\OrderLineItemModel::where('order_id', $oid)->count();
                if ($totalCount === 0) continue;
                $deliveredCount = \App\Models\CRM\OrderLineItemModel::where('order_id', $oid)
                    ->where('qurbani_item_status', 'delivered')
                    ->count();
                if ($deliveredCount < $totalCount) continue;

                try {
                    $note = "Auto-promoted: all {$totalCount} qurbani items delivered by rider {$user->fullname}";
                    if (!empty($validated['latitude']) && !empty($validated['longitude'])) {
                        $note .= " (GPS: {$validated['latitude']}, {$validated['longitude']})";
                    }
                    if ($order->changeStatus('delivered', $note, $user->id)) {
                        $autoPromoted[] = $order->order_number;
                        if (!empty($validated['latitude']) && !empty($validated['longitude'])) {
                            \DB::table('t_crm_order_status_history')
                                ->where('order_id', $order->id)
                                ->where('status_code', 'delivered')
                                ->where('is_current', 1)
                                ->update([
                                    'delivery_latitude'  => $validated['latitude'],
                                    'delivery_longitude' => $validated['longitude'],
                                ]);
                        }
                    }
                } catch (\Exception $e) {
                    // Don't fail the line-item delivery if promotion fails;
                    // the items are already marked delivered and the next
                    // mark-delivered call will retry promotion.
                    \Log::warning('Qurbani auto-promote failed', [
                        'order_id' => $oid, 'error' => $e->getMessage(),
                    ]);
                }
            }

            // Phase A2 (May-2026) — delay detection. Compare the
            // delivered_at (NOW) of each just-marked item against its
            // PRE-UPDATE qurbani_estimated_delivery_at (still in the
            // $items collection because we loaded it before the
            // update). If any rider's items slipped past the threshold,
            // recompute that rider's remaining undelivered ETAs once.
            // Failures are best-effort and never break the delivery
            // confirmation flow.
            $delayResults = [];
            try {
                $delayResults = $this->maybeRecomputeOnDeliveryDelay($items, $user->id);
            } catch (\Exception $e) {
                \Log::warning('Qurbani delay-recompute hook failed', [
                    'error' => $e->getMessage(),
                ]);
            }

            return response()->json([
                'success' => true,
                'message' => "Marked {$updated} item(s) as delivered",
                'updated_count' => $updated,
                'auto_promoted_orders' => $autoPromoted,
                'eta_delay_recomputes' => $delayResults,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \Log::error('Failed to bulk mark qurbani items delivered', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Single-item rider mark-delivered (thin wrapper).
     *
     * POST /api/rider/qurbani/line-items/{lineItemId}/mark-delivered
     */
    public function markQurbaniItemDelivered(Request $request, $lineItemId)
    {
        $request->merge(['line_item_ids' => [(int) $lineItemId]]);
        return $this->bulkMarkQurbaniItemsDelivered($request);
    }

    /**
     * Lightweight line-items endpoint for the region-view / all-orders view.
     * Returns a flat array of qurbani line items with minimal embedded order
     * context. Skips the heavy per-order processing (discounts, paid stamps,
     * merged-customer lookups, payment history) that the invoice view needs.
     *
     * GET /api/rider/qurbani/line-items
     *   ?qurbani_region=...
     *   &qurbani_day[]=Day 1&qurbani_day[]=Day 2
     *   &qurbani_delivery_type[]=Delivery
     *   &status=open
     */
    public function getQurbaniLineItems(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'No permission'], 403);
            }

            // Step 1: pre-resolve qurbani order IDs using two cheap, well-indexed
            // queries. This mirrors getQurbaniOpenOrders so we get the same
            // qurbani-order detection behaviour AND avoid the slow full-scan
            // pattern (whereNotNull(qurbani_day) OR ... OR LOWER(attribute_1))
            // which the optimizer can't use any index for.
            $qurbaniOrderIds = \DB::table('t_crm_prod_order')
                ->whereNotIn('order_status', ['cancelled', 'refunded'])
                ->where(function ($q) {
                    $q->where('external_source', '!=', 'shopify')->orWhereNull('external_source');
                })
                ->where(function ($q) {
                    $q->whereNotNull('qurbani_day')
                      ->orWhereNotNull('qurbani_slot')
                      ->orWhereNotNull('qurbani_region')
                      ->orWhereNotNull('qurbani_delivery_type');
                })
                ->pluck('id');

            $lineItemQurbaniIds = \DB::table('t_crm_prod_order_line_item as li')
                ->join('t_crm_prod_product as p', 'li.product_id', '=', 'p.id')
                ->join('t_crm_prod_order as o', 'li.order_id', '=', 'o.id')
                ->whereRaw("LOWER(p.attribute_1) = 'qurbani'")
                ->whereNotIn('o.order_status', ['cancelled', 'refunded'])
                ->where(function ($q) {
                    $q->where('o.external_source', '!=', 'shopify')->orWhereNull('o.external_source');
                })
                ->where('o.order_date', '>=', \Carbon\Carbon::now()->subDays(60))
                ->distinct()
                ->pluck('li.order_id');

            $allQurbaniIds = $qurbaniOrderIds->merge($lineItemQurbaniIds)->unique()->values();

            if ($allQurbaniIds->isEmpty()) {
                return response()->json([
                    'success' => true,
                    'items' => [],
                    'summary' => ['total' => 0, 'open' => 0, 'delivered' => 0, 'in_progress' => 0],
                ]);
            }

            // Step 2: load line items only for those orders. Now we have a
            // bounded, indexed lookup (whereIn('li.order_id', ...)) instead
            // of a full-scan OR.
            $query = \DB::table('t_crm_prod_order_line_item as li')
                ->join('t_crm_prod_order as o', 'li.order_id', '=', 'o.id')
                ->join('t_crm_prod_product as p', 'li.product_id', '=', 'p.id')
                ->leftJoin('t_crm_prod_customer as c', 'o.customer_id', '=', 'c.id')
                ->whereIn('li.order_id', $allQurbaniIds)
                ->select([
                    'li.id',
                    'li.order_id',
                    'li.name',
                    'li.quantity',
                    'li.product_id',
                    'li.qurbani_day',
                    'li.qurbani_slot',
                    'li.qurbani_region',
                    'li.qurbani_sub_region',
                    'li.qurbani_delivery_type',
                    'li.qurbani_type',
                    'li.qurbani_paya',
                    'li.qurbani_item_status',
                    'li.qurbani_assigned_rider_user_id',
                    'li.qurbani_status_updated_at',
                    'li.qurbani_slaughtered_at',
                    'li.qurbani_out_for_delivery_at',
                    'li.qurbani_delivered_at',
                    'li.instructions',
                    'p.attribute_2 as category_level_2',
                    'p.attribute_1 as attribute_1',
                    'o.order_number',
                    'o.order_status',
                    'o.order_date',
                    'o.total_price',
                    'o.name as order_name',
                    'o.address_first_name',
                    'o.address_last_name',
                    'o.address_phone',
                    'o.address_line1',
                    'o.address_line2',
                    'o.address_city',
                    'c.first_name as cust_first_name',
                    'c.last_name as cust_last_name',
                    'c.phone_original as cust_phone',
                    'c.latitude as cust_lat',
                    'c.longitude as cust_lng',
                    'c.verified_location_url',
                ]);

            // Filter line items to only qurbani-flagged rows. An order can
            // contain non-qurbani line items (rare but possible) and we don't
            // want them to clutter the All Orders / region views. A line item
            // is qurbani if EITHER its qurbani_* fields are set OR its
            // product is tagged as qurbani.
            $query->where(function ($q) {
                $q->whereNotNull('li.qurbani_day')
                  ->orWhereNotNull('li.qurbani_slot')
                  ->orWhereNotNull('li.qurbani_region')
                  ->orWhereNotNull('li.qurbani_delivery_type')
                  ->orWhereRaw("LOWER(p.attribute_1) = 'qurbani'");
            });

            // Apply Qurbani-specific filters (multi-select arrays + scalars).
            foreach (['qurbani_day', 'qurbani_slot', 'qurbani_region', 'qurbani_sub_region', 'qurbani_delivery_type', 'qurbani_type', 'qurbani_paya'] as $field) {
                $raw = $request->input($field);
                if ($raw === null || $raw === '') continue;
                $values = is_array($raw) ? $raw : [$raw];
                $values = array_values(array_filter(array_map('trim', $values), fn($v) => $v !== ''));
                if (empty($values)) continue;
                $query->whereIn("li.{$field}", $values);
            }

            // Status filter on qurbani_item_status (not order_status)
            if ($request->input('status')) {
                $statusVal = $request->input('status');
                if ($statusVal === 'open') {
                    $query->where(function ($q) {
                        $q->whereNull('li.qurbani_item_status')
                          ->orWhere('li.qurbani_item_status', '')
                          ->orWhere('li.qurbani_item_status', 'open');
                    });
                } else {
                    $query->where('li.qurbani_item_status', $statusVal);
                }
            }

            $rows = $query->orderBy('o.order_date', 'desc')
                          ->orderBy('li.id', 'asc')
                          ->get();

            // Resolve per-item rider names in one query
            $riderIds = $rows->pluck('qurbani_assigned_rider_user_id')->filter()->unique();
            $riderMap = [];
            if ($riderIds->isNotEmpty()) {
                $riderMap = \DB::table('t_sys_user')
                    ->whereIn('id', $riderIds->values())
                    ->pluck('fullname', 'id')
                    ->toArray();
            }

            // Compute bundles via QurbaniBundleService
            $bundleInputs = $rows->map(fn($r) => [
                'id' => $r->id,
                'order_id' => $r->order_id,
                'quantity' => $r->quantity,
                'qurbani_day' => $r->qurbani_day,
                'qurbani_slot' => $r->qurbani_slot,
                'qurbani_delivery_type' => $r->qurbani_delivery_type,
                'category_level_2' => $r->category_level_2,
                'product_id' => $r->product_id,
            ])->toArray();
            $bundleMap = (new \App\Services\QurbaniBundleService())->computeBundles($bundleInputs);

            // Format response
            $items = $rows->map(function ($r) use ($riderMap, $bundleMap) {
                $customerName = $r->order_name ?? 'N/A';
                if ($customerName === 'N/A' || $customerName === null) {
                    $customerName = trim(($r->address_first_name ?? '') . ' ' . ($r->address_last_name ?? ''));
                }
                if ((!$customerName || $customerName === 'N/A') && ($r->cust_first_name || $r->cust_last_name)) {
                    $customerName = trim(($r->cust_first_name ?? '') . ' ' . ($r->cust_last_name ?? ''));
                }

                $b = $bundleMap[$r->id] ?? [];

                return [
                    'id' => $r->id,
                    'order_id' => $r->order_id,
                    'order_number' => $r->order_number ?? 'NF-' . str_pad($r->order_id, 4, '0', STR_PAD_LEFT),
                    'order_status' => $r->order_status,
                    'customer_name' => $customerName ?: 'Unknown',
                    'customer_phone' => $r->address_phone ?? $r->cust_phone ?? null,
                    'customer_address' => trim(implode(', ', array_filter([$r->address_line1, $r->address_line2, $r->address_city]))),
                    'name' => $r->name,
                    'quantity' => (float) $r->quantity,
                    'category_level_2' => $r->category_level_2,
                    'qurbani_day' => $r->qurbani_day,
                    'qurbani_slot' => $r->qurbani_slot,
                    'qurbani_region' => $r->qurbani_region,
                    'qurbani_sub_region' => $r->qurbani_sub_region,
                    'qurbani_delivery_type' => $r->qurbani_delivery_type,
                    'qurbani_type' => $r->qurbani_type,
                    'qurbani_paya' => $r->qurbani_paya,
                    'qurbani_item_status' => $r->qurbani_item_status,
                    'qurbani_assigned_rider_user_id' => $r->qurbani_assigned_rider_user_id,
                    'qurbani_assigned_rider_name' => $riderMap[$r->qurbani_assigned_rider_user_id] ?? null,
                    'qurbani_status_updated_at' => $r->qurbani_status_updated_at,
                    'qurbani_slaughtered_at' => $r->qurbani_slaughtered_at,
                    'qurbani_out_for_delivery_at' => $r->qurbani_out_for_delivery_at,
                    'qurbani_delivered_at' => $r->qurbani_delivered_at,
                    'instructions' => $r->instructions,
                    'has_verified_location' => !empty($r->cust_lat) && !empty($r->cust_lng) || !empty($r->verified_location_url),
                    // Forward the verified-location coords/url for the
                    // mobile detail modal's "View Location" button.
                    'verified_location_url' => $r->verified_location_url ?? null,
                    'cust_lat' => $r->cust_lat ?? null,
                    'cust_lng' => $r->cust_lng ?? null,
                    'bundle_key' => $b['bundle_key'] ?? null,
                    'bundle_size' => $b['bundle_size'] ?? null,
                    'bundle_position_start' => $b['bundle_position_start'] ?? null,
                    'bundle_position_end' => $b['bundle_position_end'] ?? null,
                    'bundle_item_count' => $b['bundle_item_count'] ?? null,
                ];
            })->values();

            // Summary counts — 'slaughtered' is treated as part of 'open' group
            $total = $items->count();
            $open = $items->filter(fn($i) => !$i['qurbani_item_status'] || in_array($i['qurbani_item_status'], ['open', 'slaughtered']))->count();
            $delivered = $items->filter(fn($i) => $i['qurbani_item_status'] === 'delivered')->count();

            // May-2026 — same Qurbani auto-WhatsApp piggyback as the
            // open-orders endpoint above. The region-view of the
            // Qurbani Orders screen polls THIS endpoint every 30s
            // (whichever of /open-orders or /line-items is active
            // depending on isRegionView in QurbaniOpenOrdersScreen).
            // Hooking both ensures the worker fires regardless of
            // which view mode the manager is using.
            $this->fireQurbaniWaAutoSender();

            return response()->json([
                'success' => true,
                'items' => $items,
                'summary' => [
                    'total' => $total,
                    'open' => $open,
                    'delivered' => $delivered,
                    'in_progress' => $total - $open - $delivered,
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get qurbani line items', [
                'user_id' => Auth::id(),
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Qurbani field options - dropdown values for qurbani order fields
     */
    public function getQurbaniFieldOptions(Request $request)
    {
        try {
            $options = \DB::table('t_crm_qurbani_field_options')
                ->where('is_active', 1)
                ->orderBy('field_name')
                ->orderBy('display_order')
                ->get()
                ->groupBy('field_name')
                ->map(function ($group) {
                    return $group->map(function ($item) {
                        $opt = ['id' => $item->id, 'value' => $item->option_value];
                        if ($item->parent_id) $opt['parent_id'] = $item->parent_id;
                        if (isset($item->delivery_type_parent_id) && $item->delivery_type_parent_id) $opt['delivery_type_parent_id'] = $item->delivery_type_parent_id;
                        if ($item->is_default) $opt['is_default'] = true;
                        if (!empty($item->category_override)) $opt['category_override'] = $item->category_override;
                        return $opt;
                    })->values();
                });

            $categories = \DB::table('t_crm_prod_product')
                ->whereRaw("LOWER(attribute_1) = 'qurbani'")
                ->whereNotNull('attribute_2')
                ->where('attribute_2', '!=', '')
                ->distinct()
                ->orderBy('attribute_2')
                ->pluck('attribute_2')
                ->values();

            $shippingPrice = \App\Models\FIN\ConfigModel::get('qurbani_shipping_price', '1000');
            // Default payment method (cash/online) for new qurbani orders.
            // Mobile reads this to pre-select the method chip so the setting
            // configured on the web Qurbani Settings page flows through
            // without extra plumbing. Only 'cash' / 'online' are valid.
            $defaultPaymentMethod = \App\Models\FIN\ConfigModel::get('qurbani_default_payment_method', 'cash');
            if (!in_array($defaultPaymentMethod, ['cash', 'online'], true)) {
                $defaultPaymentMethod = 'cash';
            }

            $rawInvoiceFields = \DB::table('t_crm_qurbani_field_options')
                ->where('show_in_invoice', 1)
                ->groupBy('field_name')
                ->pluck('field_name')
                ->toArray();
            $desiredOrder = ['qurbani_day', 'qurbani_delivery_type', 'qurbani_slot', 'qurbani_region', 'qurbani_sub_region'];
            $invoiceFields = [];
            foreach ($desiredOrder as $f) { if (in_array($f, $rawInvoiceFields)) $invoiceFields[] = $f; }
            foreach ($rawInvoiceFields as $f) { if (!in_array($f, $invoiceFields)) $invoiceFields[] = $f; }

            $cancellationCode = \App\Models\FIN\ConfigModel::get('qurbani_cancellation_code', '');

            return response()->json([
                'success' => true,
                'options' => $options,
                'categories' => $categories,
                'qurbani_shipping_price' => $shippingPrice,
                'qurbani_default_payment_method' => $defaultPaymentMethod,
                'invoice_fields' => $invoiceFields,
                'qurbani_cancellation_code' => $cancellationCode,
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Booked summary + targets for the mobile Qurbani create/edit form.
     *
     * Mirrors the web controller's QurbaniWebController::getOrderStats shape
     * ({ success, summary, detail, targets }) so the mobile "target remaining"
     * hint on the new-order form can compute booked/target/remaining locally
     * without duplicating logic. Kept intentionally read-only — writing
     * targets stays a web-only Taimur-role flow.
     *
     * @param  \Illuminate\Http\Request  $request
     * @return \Illuminate\Http\JsonResponse
     */
    public function getQurbaniBookedStats(Request $request)
    {
        try {
            $rows = \DB::table('t_crm_prod_order as o')
                ->join('t_crm_prod_order_line_item as li', 'li.order_id', '=', 'o.id')
                ->leftJoin('t_crm_prod_product as p', 'p.id', '=', 'li.product_id')
                ->where(function ($q) {
                    $q->whereRaw("LOWER(COALESCE(p.attribute_1, '')) = 'qurbani'")
                      ->orWhereNotNull('li.qurbani_day')
                      ->orWhereNotNull('li.qurbani_slot')
                      ->orWhereNotNull('li.qurbani_region')
                      ->orWhereNotNull('li.qurbani_delivery_type');
                })
                ->where(function ($q) {
                    $q->whereNull('o.order_status')
                      ->orWhereRaw("LOWER(o.order_status) <> 'cancelled'");
                })
                // Strictly line-item based grouping — see QurbaniWebController::getOrderStats
                // for the rationale. Previously this mirrored the web query's
                // COALESCE(li.*, o.*, 'Unassigned') which leaked the order's
                // first-line snapshot onto sibling lines and mis-bucketed them
                // in the mobile target-remaining hint. Lines with nothing set
                // now land in 'Unassigned'.
                ->select(
                    \DB::raw("COALESCE(NULLIF(li.qurbani_delivery_type, ''), 'Unassigned') as delivery_type"),
                    \DB::raw("COALESCE(NULLIF(li.qurbani_day, ''), 'Unassigned') as day"),
                    \DB::raw("COALESCE(NULLIF(p.attribute_2, ''), 'Uncategorized') as category"),
                    \DB::raw("COALESCE(NULLIF(li.qurbani_slot, ''), 'Unassigned') as slot"),
                    \DB::raw("COALESCE(NULLIF(li.qurbani_region, ''), 'Unassigned') as region"),
                    \DB::raw('COALESCE(SUM(li.quantity), 0) as qty')
                )
                ->groupBy('delivery_type', 'day', 'category', 'slot', 'region')
                ->get();

            $summary = [];
            $detail = [];
            foreach ($rows as $r) {
                $dt = (string) $r->delivery_type;
                $day = (string) $r->day;
                $cat = (string) $r->category;
                $slot = (string) $r->slot;
                $region = (string) $r->region;
                $qty = (int) $r->qty;
                $summary[$dt][$day][$cat] = ($summary[$dt][$day][$cat] ?? 0) + $qty;
                $detail[$dt][$day][$cat]['cell'][$slot][$region] = ($detail[$dt][$day][$cat]['cell'][$slot][$region] ?? 0) + $qty;
            }

            $hiddenCatsJson = \App\Models\FIN\ConfigModel::get('qurbani_hidden_stats_categories', '[]');
            $hiddenCats = json_decode($hiddenCatsJson, true) ?: [];
            if (!empty($hiddenCats)) {
                foreach ($summary as $dt => $dayMap) {
                    foreach ($dayMap as $day => $catMap) {
                        foreach ($hiddenCats as $hc) { unset($summary[$dt][$day][$hc]); }
                    }
                }
                foreach ($detail as $dt => $dayMap) {
                    foreach ($dayMap as $day => $catMap) {
                        foreach ($hiddenCats as $hc) { unset($detail[$dt][$day][$hc]); }
                    }
                }
            }

            $targetSummary = [];
            $targetBreakdown = [];
            if (\DB::getSchemaBuilder()->hasTable('t_crm_qurbani_targets')) {
                $targetRows = \DB::table('t_crm_qurbani_targets')->get();
                foreach ($targetRows as $tr) {
                    $dt  = (string) $tr->delivery_type;
                    $day = (string) $tr->day;
                    $cat = (string) $tr->category;
                    $slot   = (string) ($tr->slot ?? '');
                    $region = (string) ($tr->region ?? '');
                    $qty = (int) $tr->target_qty;
                    if ($slot === '' && $region === '') {
                        $targetSummary[$dt][$day][$cat] = $qty;
                    } else {
                        $targetBreakdown[$dt][$day][$cat][$slot][$region] = $qty;
                    }
                }
            }

            return response()->json([
                'success' => true,
                'summary' => $summary,
                'detail' => $detail,
                'targets' => [
                    'summary' => $targetSummary,
                    'breakdown' => $targetBreakdown,
                ],
            ]);
        } catch (\Exception $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * List payments for an order
     */
    public function getOrderPayments(Request $request, $orderId)
    {
        try {
            $user = Auth::user();

            $order = OrderModel::findOrFail($orderId);

            $payments = \DB::table('t_crm_order_payments as p')
                ->leftJoin('t_sys_user as u', 'p.created_by', '=', 'u.id')
                ->leftJoin('t_fin_ledger as l', 'p.ledger_transaction_id', '=', 'l.id')
                ->leftJoin('t_fin_online_receiving_accounts as b', 'p.receiving_account_id', '=', 'b.id')
                ->where('p.order_id', $orderId)
                ->where('p.status', 'active')
                ->orderBy('p.payment_date', 'desc')
                ->orderBy('p.created_at', 'desc')
                ->select([
                    'p.id', 'p.amount', 'p.payment_method', 'p.payment_date',
                    'p.reference', 'p.notes', 'p.status', 'p.ledger_transaction_id',
                    'p.created_by', 'p.created_at',
                    'p.receiving_account_id',
                    'u.fullname as created_by_name',
                    'b.name as receiving_account_name',
                    'b.short_code as receiving_account_code',
                    'b.color_hex as receiving_account_color',
                    'l.approval_status as ledger_approval_status',
                    'l.settlement_status as ledger_settlement_status',
                ])
                ->get();

            return response()->json([
                'success' => true,
                'order_id' => (int) $orderId,
                'order_number' => $order->order_number,
                'total_price' => (float) $order->total_price,
                'total_paid' => (float) ($order->total_paid ?? 0),
                'payment_status' => $order->payment_status ?? 'unpaid',
                'balance_remaining' => max(0, (float)$order->total_price - (float)($order->total_paid ?? 0)),
                'payments' => $payments,
                // Ship PAID-stamp overrides + list of receiving banks so the
                // mobile Add Payment sheet has everything it needs in one
                // round-trip (no need to call /online-receiving-accounts
                // separately).
                'paid_stamp' => [
                    'sending_bank' => $order->paid_stamp_sending_bank,
                    'date'         => $order->paid_stamp_date
                        ? \Carbon\Carbon::parse($order->paid_stamp_date)->format('Y-m-d')
                        : null,
                    'ref_mode'     => $order->paid_stamp_ref_mode ?: 'reference',
                ],
                'receiving_accounts' => \App\Models\FIN\OnlineReceivingAccountModel::active()
                    ->ordered()
                    ->get(['id', 'name', 'short_code', 'color_hex']),
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to get order payments', ['order_id' => $orderId, 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Add a payment to an order.
     * Ledger routing:
     *   Rider adds cash → rider's employee_cash (shows in daily closing, needs settlement)
     *   Manager/Taimur adds cash → NF_CASH (auto-settled)
     *   Online (any) → online bank account
     */
    public function addOrderPayment(Request $request, $orderId)
    {
        try {
            $user = Auth::user();
            $order = OrderModel::findOrFail($orderId);
            // Needed to decide shop vs regular billing behaviour below.
            $order->loadMissing('customer');

            $validated = $request->validate([
                'amount' => 'required|numeric|min:0.01',
                'payment_method' => 'required|string|in:cash,cash_on_delivery,online,bank_transfer',
                // Allow backdating but never future-date — matches web modal.
                'payment_date' => 'nullable|date|before_or_equal:today',
                'reference' => 'nullable|string|max:255',
                'notes' => 'nullable|string|max:1000',
                // Which of our banks received the online payment. Old APKs
                // that don't know about this field will leave it null which
                // is exactly the legacy behaviour.
                'receiving_account_id' => 'nullable|integer|exists:t_fin_online_receiving_accounts,id',
                // Invoice PAID-stamp display overrides — all optional.
                'sending_bank'    => 'nullable|string|max:100',
                'stamp_date'      => 'nullable|date',
                'stamp_ref_mode'  => 'nullable|string|in:reference,customer_name,blank',
            ]);

            $amount = (float) $validated['amount'];
            $currentPaid = (float) ($order->total_paid ?? 0);
            $orderTotal = (float) $order->total_price;
            $remaining = $orderTotal - $currentPaid;

            if ($amount > $remaining + 0.01) {
                return response()->json([
                    'success' => false,
                    'message' => 'Payment amount (Rs. ' . number_format($amount) . ') exceeds remaining balance (Rs. ' . number_format($remaining) . ')'
                ], 422);
            }

            $paymentMethod = $validated['payment_method'];
            $paymentDate = $validated['payment_date'] ?? now()->toDateString();

            // Normalize cash_on_delivery to cash for ledger
            $normalizedMethod = in_array($paymentMethod, ['cash', 'cash_on_delivery']) ? 'cash' : $paymentMethod;
            $isOnline = in_array($normalizedMethod, ['online', 'bank_transfer', 'card']);

            // Determine if user is a manager (Taimur/Management) for auto-approval
            $user->load('roles');
            $roleNames = $user->roles->pluck('urole_name')->map(fn($n) => strtolower($n))->toArray();
            $isManager = in_array('taimur', $roleNames)
                || collect($roleNames)->contains(fn($n) => str_contains($n, 'management'))
                || $user->user_type === 'admin';

            \DB::beginTransaction();

            // Receiving bank only applies to online/bank_transfer — cash has
            // no bank. If the caller sent a receiving_account_id with a cash
            // payment, quietly ignore it rather than erroring out (old +
            // new APKs can both send the same payload shape).
            $receivingAccountId = $isOnline ? ($validated['receiving_account_id'] ?? null) : null;

            // Bank is MANDATORY for online payments — without it the per-bank
            // balances can never reconcile with the ONLINE account.
            if ($isOnline && !$receivingAccountId) {
                return response()->json([
                    'success' => false,
                    'message' => 'Select which bank received this online payment.',
                ], 422);
            }

            // Create payment record
            $payment = \App\Models\CRM\OrderPaymentModel::create([
                'order_id' => $order->id,
                'amount' => $amount,
                'payment_method' => $paymentMethod,
                'receiving_account_id' => $receivingAccountId,
                'payment_date' => $paymentDate,
                'reference' => $validated['reference'] ?? null,
                'notes' => $validated['notes'] ?? null,
                'status' => 'active',
                'created_by' => $user->id,
            ]);

            // Merge PAID-stamp metadata onto the order. Skip any key the
            // client didn't send so old APKs don't wipe stamp overrides a
            // user set previously on web.
            $stampUpdates = [];
            if (array_key_exists('sending_bank', $validated)) {
                $stampUpdates['paid_stamp_sending_bank'] = $validated['sending_bank'];
            }
            if (array_key_exists('stamp_date', $validated)) {
                $stampUpdates['paid_stamp_date'] = $validated['stamp_date'];
            } else {
                // Auto-advance stamp date with the newest payment when no
                // explicit override was supplied.
                $stampUpdates['paid_stamp_date'] = $paymentDate;
            }
            if (array_key_exists('stamp_ref_mode', $validated)) {
                $stampUpdates['paid_stamp_ref_mode'] = $validated['stamp_ref_mode'];
            }
            if (!empty($stampUpdates)) {
                $order->fill($stampUpdates)->save();
            }

            // --- Ledger entry ---
            $salesAccount = \App\Models\FIN\ConfigModel::getSalesRevenueAccount();
            if (!$salesAccount) {
                throw new \Exception("Sales revenue account not configured");
            }

            $customerName = $order->name ?? trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? '')) ?: 'Customer';
            $isQurbaniOrder = str_starts_with($order->order_number ?? '', 'QUR') || !empty($order->qurbani_day);
            // Shop customers settle online orders via incremental payments (no
            // full invoice was posted), exactly like the web addShopPayment.
            $isShopOrder = $order->customer && $order->customer->isShop();
            $label = $isQurbaniOrder ? 'Qurbani' : ($isShopOrder ? 'Shop' : 'Order');
            $description = "{$label} Payment #{$order->order_number} - Rs. " . number_format($amount) . " ({$customerName})";

            // Name the bank in the description for the ledger listing.
            if ($receivingAccountId) {
                $payBankShort = \App\Models\FIN\OnlineReceivingAccountModel::find($receivingAccountId)?->short_code;
                if ($payBankShort) {
                    $description .= " · via {$payBankShort}";
                }
            }

            if ($isOnline) {
                $toAccount = $isQurbaniOrder
                    ? \App\Models\FIN\ConfigModel::getQurbaniOnlineAccount()
                    : \App\Models\FIN\ConfigModel::getOnlineBankAccount();
                if (!$toAccount) throw new \Exception("Online account not configured");
                $mode = LedgerModel::MODE_ONLINE;

                // Apr-2026: Qurbani online payments entered by Taimur /
                // Management / Admin skip the L1+L2 approval queue entirely.
                // The web equivalent (OrderController::addQurbaniPayment)
                // already auto-approves for everyone who can use that screen,
                // and we want the mobile path to behave the same way for
                // trusted roles. Regular riders still flow through the
                // invoice_approval rules below — i.e. Qurbani online payments
                // they enter will land in the L1 queue as before.
                //
                // Jun-2026: Shop online payments behave like Qurbani — they are
                // a settlement against an order that never got a full invoice
                // posting, so they auto-approve instead of creating a pending
                // invoice row. We auto-approve shop payments regardless of role
                // because the Regular approval queue deliberately excludes shop
                // customers, so a pending shop row would otherwise be orphaned.
                if (($isQurbaniOrder && $isManager) || $isShopOrder) {
                    $approvalStatus = LedgerModel::STATUS_APPROVED;
                } else {
                    $invoiceCategory = \App\Models\Request\RequestCategoryModel::getByCode('invoice_approval');
                    $approvalStatus = LedgerModel::STATUS_APPROVED;
                    if ($invoiceCategory) {
                        $config = $invoiceCategory->approvalConfig;
                        if ($config && $config->canAutoApprove($amount)) {
                            $approvalStatus = LedgerModel::STATUS_APPROVED;
                        } elseif ($invoiceCategory->requiresLevel1()) {
                            $approvalStatus = LedgerModel::STATUS_PENDING_L1;
                        }
                    }
                }
                $settlementStatus = $approvalStatus === LedgerModel::STATUS_APPROVED ? 'settled' : 'open';
            } elseif ($isManager) {
                $toAccount = $isQurbaniOrder
                    ? \App\Models\FIN\ConfigModel::getQurbaniCashAccount()
                    : \App\Models\FIN\ConfigModel::getNFCashAccount();
                if (!$toAccount) throw new \Exception("Cash account not configured");
                $mode = LedgerModel::MODE_CASH;
                $approvalStatus = LedgerModel::STATUS_APPROVED;
                $settlementStatus = 'settled';
            } else {
                // Rider cash → rider's employee cash (needs settlement via daily closing)
                $toAccount = AccountModel::createEmployeeCashAccount($user->id, $user->fullname ?? $user->name);
                $mode = LedgerModel::MODE_CASH;
                $approvalStatus = LedgerModel::STATUS_APPROVED;
                $settlementStatus = 'open';
            }

            $applyBalanceNow = in_array($approvalStatus, [
                LedgerModel::STATUS_APPROVED,
                LedgerModel::STATUS_PENDING_L2,
            ]);

            $ledger = LedgerModel::create([
                'transaction_date' => $paymentDate,
                'transaction_type' => LedgerModel::TYPE_ORDER_PAYMENT,
                'description' => $description,
                'from_account_id' => $salesAccount->id,
                'to_account_id' => $toAccount->id,
                'amount' => $amount,
                'mode' => $mode,
                // Tag which of OUR banks received this online payment (null for
                // cash) so per-bank balances reconcile against the ONLINE account.
                'receiving_account_id' => $receivingAccountId,
                'approval_status' => $approvalStatus,
                'balance_updated' => 0, // engine applies below (when it should) and sets this
                'settlement_status' => $settlementStatus,
                'settled_amount' => $settlementStatus === 'settled' ? $amount : 0,
                'settled_at' => $settlementStatus === 'settled' ? now() : null,
                'approval_date' => $approvalStatus === LedgerModel::STATUS_APPROVED ? now() : null,
                'approved_by' => $approvalStatus === LedgerModel::STATUS_APPROVED ? $user->id : null,
                'order_id' => $order->id,
                'created_by' => $user->id,
            ]);

            // Apply via the canonical engine — same net move as the old inline code (income is
            // debit-arithmetic in this system: sales −, receiving account +), now row-locked and
            // stamped. When $applyBalanceNow is false the row stays flag=0 and the approval flow
            // applies it later, exactly as before.
            if ($applyBalanceNow) {
                (new \App\Services\FIN\BalancePostingService())->apply($ledger);
            }

            // Link ledger to payment
            $payment->ledger_transaction_id = $ledger->id;
            $payment->save();

            // Recalculate order payment status
            $order->recalculatePaymentStatus();

            \DB::commit();

            \Log::info('Qurbani payment added', [
                'order_id' => $order->id,
                'payment_id' => $payment->id,
                'ledger_id' => $ledger->id,
                'amount' => $amount,
                'method' => $paymentMethod,
                'by_role' => $isManager ? 'manager' : 'rider',
                'approval' => $approvalStatus,
                'settlement' => $settlementStatus,
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Payment of Rs. ' . number_format($amount) . ' recorded successfully',
                'payment' => [
                    'id' => $payment->id,
                    'amount' => (float) $payment->amount,
                    'payment_method' => $payment->payment_method,
                    'payment_date' => $payment->payment_date,
                    'ledger_transaction_id' => $ledger->id,
                ],
                'order_payment_status' => $order->payment_status,
                'order_total_paid' => (float) $order->total_paid,
                'order_balance_remaining' => max(0, (float)$order->total_price - (float)$order->total_paid),
            ]);

        } catch (\Illuminate\Validation\ValidationException $e) {
            \DB::rollBack();
            return response()->json(['success' => false, 'message' => $e->getMessage(), 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Failed to add order payment', ['order_id' => $orderId, 'error' => $e->getMessage(), 'trace' => $e->getTraceAsString()]);
            return response()->json(['success' => false, 'message' => 'Failed to record payment: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Mobile counterpart of OrderController@updateQurbaniPayment — lets the
     * app patch non-financial metadata (receiving bank, reference, notes,
     * stamp display fields) on an existing active payment. The ledger is
     * NEVER touched here; amount / method / date remain immutable (use the
     * void-and-readd flow for those).
     */
    public function updateOrderPayment(Request $request, $orderId, $paymentId)
    {
        try {
            $user = Auth::user();
            if (!$user) {
                return response()->json(['success' => false, 'message' => 'Unauthorized'], 401);
            }

            $order = OrderModel::findOrFail($orderId);
            $payment = \App\Models\CRM\OrderPaymentModel::where('order_id', $order->id)
                ->where('id', $paymentId)
                ->first();

            if (!$payment) {
                return response()->json(['success' => false, 'message' => 'Payment not found'], 404);
            }
            if ($payment->status !== 'active') {
                return response()->json(['success' => false, 'message' => 'Voided payments cannot be edited'], 422);
            }

            $validated = $request->validate([
                'reference' => 'nullable|string|max:255',
                'notes' => 'nullable|string|max:1000',
                'receiving_account_id' => 'nullable|integer|exists:t_fin_online_receiving_accounts,id',
                'sending_bank'    => 'nullable|string|max:100',
                'stamp_date'      => 'nullable|date',
                'stamp_ref_mode'  => 'nullable|string|in:reference,customer_name,blank',
            ]);

            $isOnline = in_array($payment->payment_method, ['online', 'bank_transfer', 'card']);

            $updates = [];
            if (array_key_exists('reference', $validated)) {
                $updates['reference'] = $validated['reference'];
            }
            if (array_key_exists('notes', $validated)) {
                $updates['notes'] = $validated['notes'];
            }
            if ($isOnline && array_key_exists('receiving_account_id', $validated)) {
                $updates['receiving_account_id'] = $validated['receiving_account_id'];
            }

            if (!empty($updates)) {
                $payment->fill($updates)->save();
            }

            $stampUpdates = [];
            if (array_key_exists('sending_bank', $validated)) {
                $stampUpdates['paid_stamp_sending_bank'] = $validated['sending_bank'];
            }
            if (array_key_exists('stamp_date', $validated)) {
                $stampUpdates['paid_stamp_date'] = $validated['stamp_date'];
            }
            if (array_key_exists('stamp_ref_mode', $validated)) {
                $stampUpdates['paid_stamp_ref_mode'] = $validated['stamp_ref_mode'];
            }
            if (!empty($stampUpdates)) {
                $order->fill($stampUpdates)->save();
            }

            \Log::info('Order payment metadata updated', [
                'order_id' => $order->id,
                'payment_id' => $payment->id,
                'user_id' => $user->id,
                'updated_keys' => array_keys($updates),
                'stamp_keys' => array_keys($stampUpdates),
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Payment updated',
                'payment' => [
                    'id' => $payment->id,
                    'reference' => $payment->reference,
                    'notes' => $payment->notes,
                    'receiving_account_id' => $payment->receiving_account_id,
                ],
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => $e->getMessage(), 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \Log::error('Failed to update order payment', [
                'order_id' => $orderId, 'payment_id' => $paymentId, 'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => 'Failed to update payment: ' . $e->getMessage()], 500);
        }
    }

    /**
     * Mobile counterpart of OrderController@deleteQurbaniPayment — voids a
     * single payment on an order and reverses its ledger + account-balance
     * impact. Keeps the row (status='voided') for audit but hides it from
     * every "active" query the rest of the app uses.
     */
    public function deleteOrderPayment(Request $request, $orderId, $paymentId)
    {
        try {
            $user = Auth::user();
            if (!$user) {
                return response()->json(['success' => false, 'message' => 'Unauthorized'], 401);
            }

            $order = OrderModel::findOrFail($orderId);
            $payment = \App\Models\CRM\OrderPaymentModel::where('order_id', $order->id)
                ->where('id', $paymentId)
                ->first();

            if (!$payment) {
                return response()->json(['success' => false, 'message' => 'Payment not found'], 404);
            }
            if ($payment->status !== 'active') {
                return response()->json(['success' => false, 'message' => 'Payment is not active'], 422);
            }

            \DB::beginTransaction();
            try {
                $amount = (float) $payment->amount;

                $ledger = $payment->ledger_transaction_id
                    ? \App\Models\FIN\LedgerModel::find($payment->ledger_transaction_id)
                    : null;

                if ($ledger) {
                    $toAccount = \App\Models\FIN\AccountModel::find($ledger->to_account_id);
                    if ($toAccount) {
                        $toAccount->current_balance = (float) $toAccount->current_balance - $amount;
                        $toAccount->save();
                    }
                    $fromAccount = \App\Models\FIN\AccountModel::find($ledger->from_account_id);
                    if ($fromAccount) {
                        $fromAccount->current_balance = (float) $fromAccount->current_balance + $amount;
                        $fromAccount->save();
                    }
                    $ledger->delete();
                }

                $payment->status = 'voided';
                $payment->updated_by = $user->id;
                $payment->save();

                $order->recalculatePaymentStatus();

                \DB::commit();
            } catch (\Exception $inner) {
                \DB::rollBack();
                throw $inner;
            }

            return response()->json([
                'success' => true,
                'message' => 'Payment voided',
                'order'   => [
                    'total_paid'        => (float) $order->total_paid,
                    'payment_status'    => $order->payment_status,
                    'balance_remaining' => max(0, (float) $order->total_price - (float) $order->total_paid),
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to void order payment (mobile)', [
                'order_id' => $orderId,
                'payment_id' => $paymentId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Display-only edit of the invoice PAID stamp. Mirrors
     * OrderController@updatePaidStamp so mobile can let the team tweak
     * the sending bank / stamp date / third-line reference mode AFTER
     * a payment has already been recorded — without creating, editing
     * or voiding any payment row. Financial state is untouched.
     */
    public function updatePaidStamp(Request $request, $id)
    {
        try {
            $user = Auth::user();
            if (!$user) {
                return response()->json(['success' => false, 'message' => 'Unauthorized'], 401);
            }
            $order = OrderModel::findOrFail($id);

            $validated = $request->validate([
                'sending_bank'   => 'nullable|string|max:100',
                'stamp_date'     => 'nullable|date',
                'stamp_ref_mode' => 'nullable|string|in:reference,customer_name,blank',
            ]);

            $updates = [];
            if (array_key_exists('sending_bank', $validated)) {
                $updates['paid_stamp_sending_bank'] = $validated['sending_bank'] !== '' ? $validated['sending_bank'] : null;
            }
            if (array_key_exists('stamp_date', $validated)) {
                $updates['paid_stamp_date'] = $validated['stamp_date'] !== '' ? $validated['stamp_date'] : null;
            }
            if (array_key_exists('stamp_ref_mode', $validated)) {
                $updates['paid_stamp_ref_mode'] = $validated['stamp_ref_mode'] ?: 'reference';
            }

            if (!empty($updates)) {
                $updates['updated_by'] = $user->id;
                $order->fill($updates)->save();
            }

            return response()->json([
                'success'    => true,
                'message'    => 'Invoice stamp updated',
                'paid_stamp' => [
                    'sending_bank' => $order->paid_stamp_sending_bank,
                    'date'         => $order->paid_stamp_date
                        ? \Carbon\Carbon::parse($order->paid_stamp_date)->format('Y-m-d')
                        : null,
                    'ref_mode'     => $order->paid_stamp_ref_mode ?: 'reference',
                ],
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => $e->errors()], 422);
        } catch (\Exception $e) {
            \Log::error('Failed to update paid stamp (mobile)', ['order_id' => $id, 'error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    // ============================================================
    // QURBANI ROUTE / DISPATCH / ETA  (May 2026)
    // ============================================================
    //
    // Mirrors the regular-orders flow (lockRoute / updateDeliveryPriorities /
    // calculateDeliveryEtas / optimizeRoute) but operates at the BUNDLE
    // level inside Qurbani Mode:
    //   - One stop per smart-box bundle (same customer + day + slot +
    //     delivery_type), NOT per individual line item, because a rider
    //     dropping a bundle off makes a single delivery stop even if the
    //     bundle contains 3 hissas + 1 bakra.
    //   - Lock state lives in t_crm_route_lock with mode='qurbani' so it
    //     coexists with the regular-orders lock for the same rider.
    //   - Priorities + ETAs are stored on every line item in the bundle
    //     (qurbani_delivery_priority / qurbani_estimated_delivery_at) so
    //     queries against line_item don't have to join a bundle table.
    //
    // The rider's "Set Route" button calls saveQurbaniRoute(); the rider's
    // "Dispatch" button (and the manager's) calls dispatchQurbaniRoute(),
    // which is the only place that touches Google Directions and writes
    // qurbani_dispatched_at.

    /**
     * Helper: load and shape the rider's qurbani delivery list as bundles
     * with route metadata (priority, ETA, status, dispatched_at, etc.) so
     * the manager planner and the rider's app render from the same shape.
     *
     * @param int    $riderId  rider whose route we want
     * @param string $show     open|delivered|all  (open also includes
     *                         out_for_delivery / slaughtered etc.)
     */
    private function buildQurbaniRiderRoute($riderId, string $show = 'open'): array
    {
        $assignedQuery = \DB::table('t_crm_prod_order_line_item')
            ->where('qurbani_assigned_rider_user_id', $riderId);
        if ($show === 'open') {
            $assignedQuery->where(function ($q) {
                $q->whereNull('qurbani_item_status')
                  ->orWhere('qurbani_item_status', '!=', 'delivered');
            });
        } elseif ($show === 'delivered') {
            $assignedQuery->where('qurbani_item_status', 'delivered');
        }
        $orderIds = $assignedQuery->pluck('order_id')->unique()->values();
        if ($orderIds->isEmpty()) {
            return ['bundles' => [], 'orders' => []];
        }

        $orders = \App\Models\CRM\OrderModel::with(['customer', 'lineItems' => function ($q) {
                $q->select(
                    'id', 'order_id', 'product_id', 'name', 'sku', 'quantity', 'unit_price', 'line_total',
                    'qurbani_day', 'qurbani_slot',
                    'qurbani_slot_start_minute', 'qurbani_slot_end_minute',
                    'qurbani_region', 'qurbani_sub_region',
                    'qurbani_delivery_type', 'qurbani_type', 'qurbani_paya',
                    'qurbani_item_status', 'qurbani_assigned_rider_user_id',
                    'qurbani_status_updated_at',
                    'qurbani_slaughtered_at', 'qurbani_out_for_delivery_at', 'qurbani_delivered_at',
                    'qurbani_delivery_priority', 'qurbani_estimated_delivery_at',
                    'qurbani_eta_calculated_at', 'qurbani_dispatched_at', 'qurbani_dispatched_by',
                    'qurbani_started_delivery_at',
                    'qurbani_live_tracking_enabled',
                    'instructions'
                );
            }, 'lineItems.product' => function ($q) {
                $q->select('id', 'attribute_2');
            }])
            ->whereIn('id', $orderIds)
            ->get();

        // Compute bundles across ALL line items in each order so the
        // bundle position chips match what the dispatch screen shows.
        $bundleInputs = [];
        foreach ($orders as $o) {
            foreach ($o->lineItems as $li) {
                $bundleInputs[] = [
                    'id'                    => $li->id,
                    'order_id'              => $li->order_id,
                    'quantity'              => $li->quantity,
                    'qurbani_day'           => $li->qurbani_day,
                    'qurbani_slot'          => $li->qurbani_slot,
                    'qurbani_delivery_type' => $li->qurbani_delivery_type,
                    'category_level_2'      => $li->product->attribute_2 ?? null,
                    'product_id'            => $li->product_id,
                ];
            }
        }
        $bundleMap = (new \App\Services\QurbaniBundleService())->computeBundles($bundleInputs);

        $bundles = [];
        $orderShells = [];
        foreach ($orders as $order) {
            $myItems = $order->lineItems->filter(function ($li) use ($riderId, $show) {
                if ((int) $li->qurbani_assigned_rider_user_id !== (int) $riderId) return false;
                $isDelivered = $li->qurbani_item_status === 'delivered';
                if ($show === 'open') return !$isDelivered;
                if ($show === 'delivered') return $isDelivered;
                return true;
            })->values();
            if ($myItems->isEmpty()) continue;

            $customerName = $order->name ?: trim(($order->address_first_name ?? '') . ' ' . ($order->address_last_name ?? ''));
            if (!$customerName && $order->customer) {
                $customerName = trim(($order->customer->first_name ?? '') . ' ' . ($order->customer->last_name ?? '')) ?: null;
            }

            $cust = $order->customer;
            // Phase E (May-2026) — resolve cust_lat/lng through the
            // URL-parse fallback. Otherwise customers with only
            // verified_location_url (no pin row) drop out of the
            // Google Directions waypoint list and skip ETA calc.
            $resolved = $this->resolveCustomerDispatchCoords($cust);
            $hasCoords = $resolved['lat'] !== null && $resolved['lng'] !== null;
            $custLat = $resolved['lat'];
            $custLng = $resolved['lng'];
            // Verified-location metadata: who saved/last-updated the
            // pin and when. Surfaced so the rider knows whose pin
            // they're trusting before they tap an address.
            $verifiedBy = $cust ? ($cust->verified_location_saved_by ?? null) : null;
            $verifiedAt = $cust ? ($cust->verified_location_saved_at ?? null) : null;

            $orderShells[$order->id] = [
                'id' => $order->id,
                'order_number' => $order->order_number,
                'customer_id' => $order->customer_id,
                'customer_name' => $customerName ?: 'Unknown',
                'customer_phone' => $order->address_phone ?? ($cust->phone_original ?? ($cust->phone ?? null)),
                'customer_address' => trim(implode(', ', array_filter([
                    $order->address_line1, $order->address_line2, $order->address_city,
                ]))),
                'qurbani_region' => $order->qurbani_region,
                'has_verified_location' => $hasCoords || ($cust && !empty($cust->verified_location_url)),
                'cust_lat' => $custLat,
                'cust_lng' => $custLng,
                'verified_location_url' => $cust->verified_location_url ?? null,
                'verified_location_saved_by' => $verifiedBy,
                'verified_location_saved_at' => $verifiedAt ? (string) $verifiedAt : null,
                // May-2026 diagnostic for the rider's missing-coords
                // banner; see RiderController::resolveCustomerDispatchCoords.
                'coords_source' => $resolved['source'] ?? null,
                'coords_reason' => $resolved['reason'] ?? null,
            ];

            foreach ($myItems as $li) {
                $b = $bundleMap[$li->id] ?? null;
                $bk = $b['bundle_key'] ?? "no-bundle:{$li->id}";
                if (!isset($bundles[$bk])) {
                    $bundles[$bk] = [
                        'bundle_key'              => $bk,
                        'order_id'                => $order->id,
                        'order_number'            => $order->order_number,
                        'customer_id'             => $order->customer_id,
                        'customer_name'           => $orderShells[$order->id]['customer_name'],
                        'customer_phone'          => $orderShells[$order->id]['customer_phone'],
                        'customer_address'        => $orderShells[$order->id]['customer_address'],
                        'has_verified_location'   => $orderShells[$order->id]['has_verified_location'],
                        'cust_lat'                => $custLat,
                        'cust_lng'                => $custLng,
                        'verified_location_url'   => $orderShells[$order->id]['verified_location_url'],
                        'verified_location_saved_by' => $orderShells[$order->id]['verified_location_saved_by'],
                        'verified_location_saved_at' => $orderShells[$order->id]['verified_location_saved_at'],
                        'coords_source'           => $orderShells[$order->id]['coords_source'] ?? null,
                        'coords_reason'           => $orderShells[$order->id]['coords_reason'] ?? null,
                        'qurbani_day'             => $li->qurbani_day,
                        'qurbani_slot'            => $li->qurbani_slot,
                        'qurbani_slot_start_minute' => $li->qurbani_slot_start_minute !== null ? (int) $li->qurbani_slot_start_minute : null,
                        'qurbani_slot_end_minute'   => $li->qurbani_slot_end_minute   !== null ? (int) $li->qurbani_slot_end_minute   : null,
                        'qurbani_delivery_type'   => $li->qurbani_delivery_type,
                        'qurbani_region'          => $li->qurbani_region,
                        'qurbani_sub_region'      => $li->qurbani_sub_region,
                        'bundle_size'             => $b['bundle_size'] ?? null,
                        'items'                   => [],
                        'all_delivered'           => true,
                        'any_ofd'                 => false,
                        // Route metadata — pulled off the line item but
                        // shared across the bundle (every line item in a
                        // bundle stores the same priority / ETA).
                        'qurbani_delivery_priority'      => $li->qurbani_delivery_priority,
                        'qurbani_estimated_delivery_at'  => $li->qurbani_estimated_delivery_at
                            ? (string) $li->qurbani_estimated_delivery_at : null,
                        'qurbani_eta_calculated_at'      => $li->qurbani_eta_calculated_at
                            ? (string) $li->qurbani_eta_calculated_at : null,
                        'qurbani_dispatched_at'          => $li->qurbani_dispatched_at
                            ? (string) $li->qurbani_dispatched_at : null,
                        'qurbani_dispatched_by'          => $li->qurbani_dispatched_by,
                        'qurbani_started_delivery_at'    => $li->qurbani_started_delivery_at
                            ? (string) $li->qurbani_started_delivery_at : null,
                        // Live ETA tracking flag — bundle-shared (every
                        // line item in a dispatched bundle stores the
                        // same value). Manager + rider can flip via
                        // POST .../live-tracking; reset on every fresh
                        // dispatch (see dispatchQurbaniRoute).
                        'qurbani_live_tracking_enabled'  => (int) ($li->qurbani_live_tracking_enabled ?? 0) === 1,
                        'qurbani_delivered_at'           => null,
                    ];
                }
                $isDelivered = $li->qurbani_item_status === 'delivered';
                if (!$isDelivered) $bundles[$bk]['all_delivered'] = false;
                if (in_array($li->qurbani_item_status, ['out_for_delivery'], true)) $bundles[$bk]['any_ofd'] = true;
                // Track the latest delivered_at for the bundle so we can
                // surface "Actual Delivery Time" in the manager's review
                // tab. Use latest because multiple items may have
                // staggered delivery_at timestamps if the rider delivered
                // them in pieces somehow.
                if ($li->qurbani_delivered_at) {
                    $existing = $bundles[$bk]['qurbani_delivered_at'];
                    if (!$existing || strtotime((string) $li->qurbani_delivered_at) > strtotime($existing)) {
                        $bundles[$bk]['qurbani_delivered_at'] = (string) $li->qurbani_delivered_at;
                    }
                }
                $bundles[$bk]['items'][] = [
                    'id' => $li->id,
                    'name' => $li->name,
                    'quantity' => (float) $li->quantity,
                    'category_level_2' => $li->product->attribute_2 ?? null,
                    'qurbani_type' => $li->qurbani_type,
                    'qurbani_paya' => $li->qurbani_paya,
                    'qurbani_item_status' => $li->qurbani_item_status,
                    'qurbani_status_updated_at' => $li->qurbani_status_updated_at
                        ? (string) $li->qurbani_status_updated_at : null,
                    'instructions' => $li->instructions,
                    'bundle_position_start' => $b['bundle_position_start'] ?? null,
                    'bundle_position_end'   => $b['bundle_position_end'] ?? null,
                    'bundle_size'           => $b['bundle_size'] ?? null,
                    'bundle_item_count'     => $b['bundle_item_count'] ?? null,
                ];
            }
        }

        // Resolve verified_location_saved_by user IDs to names in one
        // batch query — avoids N+1 when many bundles share the same
        // verified-by user.
        $verifierIds = [];
        foreach ($bundles as $b) {
            if (!empty($b['verified_location_saved_by'])) $verifierIds[] = $b['verified_location_saved_by'];
        }
        $verifierNames = [];
        if (!empty($verifierIds)) {
            $verifierNames = \DB::table('t_sys_user')
                ->whereIn('id', array_unique($verifierIds))
                ->pluck('fullname', 'id')
                ->toArray();
        }
        // Customer-app pins are stamped with the sentinel id -> "Customer".
        $verifierNames[\App\Models\CRM\CustomerModel::VERIFIED_PIN_CUSTOMER_ID] = 'Customer';

        // Sort items inside each bundle by packet position + finalize
        // status fields used by the manager planner.
        foreach ($bundles as &$bRef) {
            usort($bRef['items'], function ($a, $b) {
                $ap = $a['bundle_position_start'] ?? PHP_INT_MAX;
                $bp = $b['bundle_position_start'] ?? PHP_INT_MAX;
                return $ap <=> $bp;
            });
            // bundle_status surface: drives the rider/manager card chip.
            if ($bRef['all_delivered']) {
                $bRef['bundle_status'] = 'delivered';
            } elseif ($bRef['any_ofd']) {
                $bRef['bundle_status'] = 'out_for_delivery';
            } else {
                $bRef['bundle_status'] = 'pending';
            }
            // bundle_dispatch_status: orthogonal to delivery status —
            // tells the manager planner whether this bundle is part of
            // a frozen Dispatched batch (sequence locked, ETA set) or
            // still Pending (can be optimised / re-sequenced).
            //   delivered     all items delivered (terminal)
            //   dispatched    has dispatched_at AND not all delivered
            //   pending       no dispatched_at yet
            if ($bRef['all_delivered']) {
                $bRef['bundle_dispatch_status'] = 'delivered';
            } elseif (!empty($bRef['qurbani_dispatched_at'])) {
                $bRef['bundle_dispatch_status'] = 'dispatched';
            } else {
                $bRef['bundle_dispatch_status'] = 'pending';
            }
            // Resolve verifier name.
            $vid = $bRef['verified_location_saved_by'] ?? null;
            $bRef['verified_location_saved_by_name'] = ($vid && isset($verifierNames[$vid]))
                ? $verifierNames[$vid] : null;
        }
        unset($bRef);

        // Sort bundles globally by priority asc, NULL last; stable on
        // (priority, customer_name, bundle_key).
        $bundleList = array_values($bundles);
        usort($bundleList, function ($a, $b) {
            $pa = $a['qurbani_delivery_priority'] ?? null;
            $pb = $b['qurbani_delivery_priority'] ?? null;
            if ($pa === null && $pb === null) {
                return strcmp($a['customer_name'] ?? '', $b['customer_name'] ?? '');
            }
            if ($pa === null) return 1;
            if ($pb === null) return -1;
            if ($pa === $pb) return strcmp($a['bundle_key'], $b['bundle_key']);
            return $pa <=> $pb;
        });

        return ['bundles' => $bundleList, 'orders' => array_values($orderShells)];
    }

    /**
     * Helper: route lock info for (rider_id, mode='qurbani').
     */
    private function getQurbaniRouteLockInfo($riderId): ?array
    {
        $lock = \DB::table('t_crm_route_lock as rl')
            ->leftJoin('t_sys_user as u', 'u.id', '=', 'rl.locked_by')
            ->where('rl.rider_id', $riderId)
            ->where('rl.mode', 'qurbani')
            ->select('rl.locked_by', 'u.fullname as locked_by_name', 'rl.locked_at')
            ->first();

        if (!$lock) return null;
        return [
            'locked_by' => (int) $lock->locked_by,
            'locked_by_name' => $lock->locked_by_name,
            'locked_at' => $lock->locked_at,
        ];
    }

    /**
     * May-2026 — Return-to-base ETA cache (Phase B extension).
     *
     * Background: dispatchQurbaniRoute and editDispatchedRoute already
     * compute a "back at base by HH:MM" estimate using the same
     * Google Directions call that builds per-stop ETAs (the trick is
     * appending the configured Qurbani base as a synthetic final
     * waypoint — no extra API spend). Today that value is only
     * returned in the immediate response and shown on the active
     * rider's own delivery screen.
     *
     * The manager dashboard (mobile QurbaniRidersScreen + web
     * /qurbani/riders) doesn't get to see it because it polls
     * /qurbani/riders separately — that endpoint has no access to
     * the Google call without burning API credits per refresh.
     *
     * Fix: cache the RTB payload PER RIDER for the lifetime of the
     * current dispatch. Auto-expire shortly after the ETA passes so a
     * stale value never lingers; explicitly forget on cancel-dispatch
     * so the chip disappears the moment work is released. Reads are
     * gated by the caller (only show if the rider still has dispatched
     * undelivered items — pruning dispatch-completed states naturally).
     *
     * Keys: `qurbani:rtb:{riderId}`. Cache backend is whatever the app
     * uses (Redis in prod, file/array in dev) — same one
     * fireQurbaniWaAutoSender already relies on, so no new ops surface.
     */
    private const QURBANI_RTB_CACHE_PREFIX = 'qurbani:rtb:';

    private function cacheQurbaniReturnToBase(int $riderId, ?array $rtb): void
    {
        if (!$rtb || empty($rtb['estimated_at'])) {
            return;
        }
        try {
            $eta = \Carbon\Carbon::parse($rtb['estimated_at']);
            // Keep until 30 min after the projected ETA to absorb
            // slight drift, capped at 8h to defend against a clock-
            // skewed write that would otherwise live forever.
            $secondsUntilEta = max(60, $eta->diffInSeconds(now(), false) * -1);
            $ttl = (int) min(8 * 3600, $secondsUntilEta + 30 * 60);
            \Cache::put(
                self::QURBANI_RTB_CACHE_PREFIX . (int) $riderId,
                $rtb,
                $ttl
            );
        } catch (\Throwable $e) {
            // Cache failure must never break the dispatch response.
            \Log::debug('cacheQurbaniReturnToBase failed', ['rider' => $riderId, 'error' => $e->getMessage()]);
        }
    }

    private function getCachedQurbaniReturnToBase(int $riderId): ?array
    {
        try {
            $v = \Cache::get(self::QURBANI_RTB_CACHE_PREFIX . (int) $riderId);
            if (!is_array($v)) return null;
            // Defensive freshness check: if the projected ETA is more
            // than 30 min in the past, treat as stale and drop. The
            // TTL above is the primary guard; this catches edge cases
            // where the cache TTL hadn't ticked yet (or a redis flush
            // resurrected an old write).
            if (!empty($v['estimated_at'])) {
                $eta = \Carbon\Carbon::parse($v['estimated_at']);
                if ($eta->lt(now()->subMinutes(30))) {
                    \Cache::forget(self::QURBANI_RTB_CACHE_PREFIX . (int) $riderId);
                    return null;
                }
            }
            return $v;
        } catch (\Throwable $e) {
            return null;
        }
    }

    private function forgetCachedQurbaniReturnToBase(int $riderId): void
    {
        try {
            \Cache::forget(self::QURBANI_RTB_CACHE_PREFIX . (int) $riderId);
        } catch (\Throwable $e) {
            // Same swallow-rule as the writer.
        }
    }

    /**
     * Helper: enrich each bundle with ETA comparison (early/late/on time)
     * once it has BOTH an estimated_delivery_at and a delivered_at.
     */
    private function enrichBundleEtaComparison(array &$bundles): void
    {
        foreach ($bundles as &$bundle) {
            $bundle['eta_comparison'] = null;
            $est = $bundle['qurbani_estimated_delivery_at'] ?? null;
            $act = $bundle['qurbani_delivered_at'] ?? null;
            if (!$est) continue;
            $estTime = \Carbon\Carbon::parse($est);
            if ($act) {
                $actTime = \Carbon\Carbon::parse($act);
                $diff = (int) round($actTime->diffInMinutes($estTime, false));
                $bundle['eta_comparison'] = [
                    'estimated_at_display' => $estTime->format('h:i A'),
                    'actual_at_display' => $actTime->format('h:i A'),
                    'diff_minutes' => $diff,
                    'status' => $diff >= 0 ? 'early' : 'late',
                    'on_time' => abs($diff) <= 5,
                    'status_text' => $diff >= 0
                        ? ($diff == 0 ? 'On time' : "{$diff} min early")
                        : (abs($diff) . ' min late'),
                ];
            } else {
                $bundle['eta_comparison'] = [
                    'estimated_at_display' => $estTime->format('h:i A'),
                    'actual_at_display' => null,
                    'diff_minutes' => null,
                    'status' => 'pending',
                    'on_time' => null,
                    'status_text' => 'ETA ' . $estTime->format('h:i A'),
                ];
            }
        }
        unset($bundle);
    }

    /**
     * Helper: enrich each bundle with slot_compare — telling us
     * whether the ETA (for OFD bundles) or the actual delivered_at
     * (for delivered bundles) lands inside the promised slot end.
     *
     * Phase 4 (May-2026) — driven by qurbani_slot_end_minute on the
     * line item (settings override > parser auto-detect).
     */
    private function enrichBundleSlotCompare(array &$bundles): void
    {
        $grace = (int) \App\Models\FIN\ConfigModel::get('qurbani_late_grace_minutes', '10');
        if ($grace < 0) $grace = 0;
        foreach ($bundles as &$bundle) {
            $bundle['slot_compare'] = null;
            $slotEnd = $bundle['qurbani_slot_end_minute'] ?? null;
            if ($slotEnd === null) continue;
            // Delivered bundle: compare actual delivery time to slot end.
            if (!empty($bundle['qurbani_delivered_at'])) {
                $bundle['slot_compare'] = \App\Services\QurbaniSlotParser::compareEventToSlot(
                    $bundle['qurbani_delivered_at'],
                    (int) $slotEnd,
                    $grace,
                    'delivered'
                );
                continue;
            }
            // OFD bundle with stored ETA: compare ETA to slot end.
            $eta = $bundle['qurbani_estimated_delivery_at'] ?? null;
            if ($eta) {
                $bundle['slot_compare'] = \App\Services\QurbaniSlotParser::compareEventToSlot(
                    $eta,
                    (int) $slotEnd,
                    $grace,
                    'eta'
                );
            }
        }
        unset($bundle);
    }

    /**
     * May-2026 — Delivered promise-drift enrichment.
     *
     * Each delivered bundle is annotated with how its actual delivery
     * time compares to the "promise" given to the customer. Promise
     * source priority (mirrors the manager Q&A on May-28 2026):
     *
     *   1. WhatsApp OFD message — the EARLIEST row in
     *      t_ops_qurbani_wa_log with trigger IN (ofd, ofd_delay_update)
     *      and status='sent' for any line item in the bundle. This is
     *      the moment the customer was first told a time. Tagged
     *      promise_source = 'whatsapp'.
     *
     *   2. System ETA fallback — qurbani_estimated_delivery_at when
     *      no WA promise was ever sent (test mode, no phone, template
     *      off, etc.). Tagged promise_source = 'system_eta' so the UI
     *      can show "(no WA — fell back to system ETA)".
     *
     *   3. None — no promise on record; drift left null.
     *
     * Drift buckets use qurbani_late_grace_minutes (config, default 10)
     * for the on-promise cutoff and a hard-coded 30 min for the very-
     * late threshold to mirror qurbani_wa_ofd_delay_threshold_minutes
     * (a 30-min slip is what the auto-WA "needs delay update" worker
     * already flags as a real problem).
     *
     * One batched query for all line item ids in $bundles to keep this
     * O(1) regardless of how many delivered stops the rider has.
     */
    private function enrichDeliveredPromiseDrift(array &$bundles): void
    {
        // Collect line_item ids for delivered bundles only — there's
        // nothing to compare on pending/OFD rows yet.
        $deliveredLineItemIds = [];
        foreach ($bundles as $b) {
            if (empty($b['qurbani_delivered_at'])) continue;
            foreach (($b['items'] ?? []) as $it) {
                if (!empty($it['id'])) $deliveredLineItemIds[] = (int) $it['id'];
            }
        }
        $deliveredLineItemIds = array_values(array_unique($deliveredLineItemIds));

        // Per-line-item WA log lookup. We keep the earliest sent OFD
        // row (the original promise) AND the latest one (so we can
        // surface revision count + "latest revised promise"). Done in
        // PHP because a single grouped SQL would lose either end of
        // the time-ordered list — and the dataset is small (one query,
        // bounded by the rider's delivered stops for the day).
        $logByLi = [];
        if (!empty($deliveredLineItemIds)) {
            $logRows = \DB::table('t_ops_qurbani_wa_log')
                ->whereIn('line_item_id', $deliveredLineItemIds)
                ->whereIn('trigger_event', ['ofd', 'ofd_delay_update'])
                ->where('status', 'sent')
                ->whereNotNull('delivery_time_used')
                ->orderBy('created_at', 'asc')
                ->select('line_item_id', 'trigger_event', 'delivery_time_used', 'created_at')
                ->get();
            foreach ($logRows as $row) {
                $li = (int) $row->line_item_id;
                if (!isset($logByLi[$li])) {
                    $logByLi[$li] = [
                        'earliest_eta_at'  => (string) $row->delivery_time_used,
                        'earliest_sent_at' => (string) $row->created_at,
                        'latest_eta_at'    => (string) $row->delivery_time_used,
                        'latest_sent_at'   => (string) $row->created_at,
                        'revisions'        => 0,
                    ];
                } else {
                    $logByLi[$li]['latest_eta_at']  = (string) $row->delivery_time_used;
                    $logByLi[$li]['latest_sent_at'] = (string) $row->created_at;
                    if ($row->trigger_event === 'ofd_delay_update') {
                        $logByLi[$li]['revisions']++;
                    }
                }
            }
        }

        $grace = (int) \App\Models\FIN\ConfigModel::get('qurbani_late_grace_minutes', '10');
        if ($grace < 0) $grace = 0;
        $veryLate = (int) \App\Models\FIN\ConfigModel::get('qurbani_wa_ofd_delay_threshold_minutes', '30');
        if ($veryLate < 1) $veryLate = 30;

        foreach ($bundles as &$bundle) {
            $bundle['promise_drift'] = null;
            $delivered = $bundle['qurbani_delivered_at'] ?? null;
            if (!$delivered) continue;

            // Bundle-level promise = earliest WA-promise across any of
            // its items (a bundle delivered together should share one
            // customer-facing promise; if items somehow got staggered
            // sends we take the FIRST as the canonical original).
            $earliestEta = null;
            $earliestSentAt = null;
            $latestEta = null;
            $latestSentAt = null;
            $revisions = 0;
            foreach (($bundle['items'] ?? []) as $it) {
                $li = (int) ($it['id'] ?? 0);
                if (!$li || !isset($logByLi[$li])) continue;
                $rec = $logByLi[$li];
                if ($earliestEta === null
                    || strtotime($rec['earliest_sent_at']) < strtotime($earliestSentAt)) {
                    $earliestEta = $rec['earliest_eta_at'];
                    $earliestSentAt = $rec['earliest_sent_at'];
                }
                if ($latestEta === null
                    || strtotime($rec['latest_sent_at']) > strtotime($latestSentAt)) {
                    $latestEta = $rec['latest_eta_at'];
                    $latestSentAt = $rec['latest_sent_at'];
                }
                $revisions += (int) $rec['revisions'];
            }

            // Pick promise source — WA wins, system ETA falls back.
            $promiseSource = null;
            $promiseEta = null;
            if ($earliestEta) {
                $promiseSource = 'whatsapp';
                $promiseEta = $earliestEta;
            } elseif (!empty($bundle['qurbani_estimated_delivery_at'])) {
                $promiseSource = 'system_eta';
                $promiseEta = $bundle['qurbani_estimated_delivery_at'];
            }
            if (!$promiseEta) continue;

            try {
                $promiseCarbon = \Carbon\Carbon::parse($promiseEta);
                $actualCarbon = \Carbon\Carbon::parse($delivered);
                // Signed minutes — positive = delivered AFTER promise (late);
                // negative = delivered before promise (early).
                $driftMin = (int) round($promiseCarbon->diffInMinutes($actualCarbon, false));
            } catch (\Throwable $e) {
                continue;
            }

            // Bucket: on_promise within ±grace; late > grace; very_late
            // beyond the WA "needs delay update" threshold; early when
            // negative beyond the grace window.
            $bucket = 'on_promise';
            $abs = abs($driftMin);
            if ($driftMin > $grace) {
                $bucket = $driftMin > $veryLate ? 'very_late' : 'late';
            } elseif ($driftMin < -$grace) {
                $bucket = 'early';
            }

            // Human-readable status text for the chip.
            if ($bucket === 'on_promise') {
                $statusText = $abs <= 1 ? 'On promise' : ($abs . 'm vs promise');
            } elseif ($bucket === 'early') {
                $statusText = $abs . 'm before promise';
            } else {
                $statusText = $driftMin . 'm late';
            }

            $bundle['promise_drift'] = [
                'promise_source'        => $promiseSource,           // whatsapp | system_eta
                'promised_eta_at'       => (string) $promiseEta,
                'promised_eta_display'  => $promiseCarbon->format('h:i A'),
                'promised_sent_at'      => $earliestSentAt,         // when WA went out (null for system_eta fallback)
                'delivered_at_display'  => $actualCarbon->format('h:i A'),
                'drift_minutes'         => $driftMin,
                'drift_bucket'          => $bucket,                  // on_promise | late | very_late | early
                'status_text'           => $statusText,
                'grace_minutes'         => $grace,
                'very_late_threshold'   => $veryLate,
                // Revision context — populated only when WA delay-
                // updates were actually sent. Lets the UI render
                // "(1 revision sent at 2:18 PM → revised 2:45 PM)".
                'revisions_sent'        => $revisions,
                'latest_promised_eta_at'      => $revisions > 0 ? $latestEta : null,
                'latest_promised_eta_display' => ($revisions > 0 && $latestEta)
                    ? \Carbon\Carbon::parse($latestEta)->format('h:i A') : null,
                'latest_promised_sent_at'     => $revisions > 0 ? $latestSentAt : null,
            ];
        }
        unset($bundle);
    }

    /**
     * GET /rider/qurbani/riders
     *
     * Manager view: list every rider that currently has at least one
     * Qurbani line item assigned to them. For each rider returns a small
     * summary so the sidebar list can show counts without us round-
     * tripping for each rider.
     */
    public function getQurbaniRidersSummary(Request $request)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $rows = \DB::table('t_crm_prod_order_line_item as li')
                ->join('t_sys_user as u', 'u.id', '=', 'li.qurbani_assigned_rider_user_id')
                ->whereNotNull('li.qurbani_assigned_rider_user_id')
                ->select([
                    'u.id as rider_id',
                    'u.fullname as rider_name',
                    \DB::raw("SUM(CASE WHEN li.qurbani_item_status='out_for_delivery' THEN 1 ELSE 0 END) as ofd_items"),
                    \DB::raw("SUM(CASE WHEN li.qurbani_item_status='delivered' THEN 1 ELSE 0 END) as delivered_items"),
                    \DB::raw("SUM(CASE WHEN li.qurbani_item_status IS NULL OR li.qurbani_item_status NOT IN ('delivered','out_for_delivery') THEN 1 ELSE 0 END) as pending_items"),
                    \DB::raw("MAX(li.qurbani_dispatched_at) as last_dispatched_at"),
                    // May-2026 — Haider-bug fix. Surface the most recent
                    // delivery timestamp too so the mobile riders summary
                    // can show "Finished delivery Xm ago" (vs "Dispatched
                    // Xm ago") once every assigned item is delivered.
                    // Without this, a rider who completed his run hours
                    // ago kept showing "Last dispatched 5m ago" purely
                    // because the dispatch time stuck around.
                    \DB::raw("MAX(li.qurbani_delivered_at) as last_delivered_at"),
                ])
                ->groupBy('u.id', 'u.fullname')
                ->orderBy('u.fullname', 'asc')
                ->get();

            // Pull qurbani route locks in one shot.
            $locks = \DB::table('t_crm_route_lock as rl')
                ->leftJoin('t_sys_user as u', 'u.id', '=', 'rl.locked_by')
                ->where('rl.mode', 'qurbani')
                ->select('rl.rider_id', 'rl.locked_by', 'u.fullname as locked_by_name', 'rl.locked_at')
                ->get()
                ->keyBy('rider_id');

            // Phase C (May-2026) — pull GPS health for every rider in
            // one query so the manager screen + planner can show a
            // pill (live / recent / stale / none) without N+1 hits.
            //
            // We grab the most recent reading per rider via a
            // correlated subquery on captured_at MAX. Index on
            // (user_id, captured_at) keeps this cheap.
            $riderIds = $rows->pluck('rider_id')->all();
            $gpsByRider = [];
            if (!empty($riderIds)) {
                $gpsRows = \DB::table('t_ops_rider_location as rl')
                    ->whereIn('rl.user_id', $riderIds)
                    ->whereRaw('rl.captured_at = (SELECT MAX(rl2.captured_at) FROM t_ops_rider_location rl2 WHERE rl2.user_id = rl.user_id)')
                    ->select('rl.user_id', 'rl.latitude', 'rl.longitude', 'rl.captured_at')
                    ->get();
                foreach ($gpsRows as $g) {
                    $gpsByRider[(int) $g->user_id] = $g;
                }
            }

            $now = now();
            $payload = [];
            foreach ($rows as $r) {
                $lock = $locks[$r->rider_id] ?? null;

                // Compute GPS health bucket. The thresholds below match
                // the dispatch-tracker conventions used for regular
                // orders (5 min = "live", 30 min = "recent",
                // anything older or absent = "stale" / "none").
                $g = $gpsByRider[(int) $r->rider_id] ?? null;
                $gpsStatus = 'none';
                $gpsAgeMinutes = null;
                $gpsCapturedAt = null;
                if ($g && $g->captured_at) {
                    $gpsCapturedAt = (string) $g->captured_at;
                    try {
                        $captured = \Carbon\Carbon::parse($g->captured_at);
                        $gpsAgeMinutes = (int) abs($now->diffInMinutes($captured));
                        if ($gpsAgeMinutes <= 5) {
                            $gpsStatus = 'live';
                        } elseif ($gpsAgeMinutes <= 30) {
                            $gpsStatus = 'recent';
                        } else {
                            $gpsStatus = 'stale';
                        }
                    } catch (\Exception $e) {
                        $gpsStatus = 'none';
                    }
                }

                // May-2026 — Return-to-base ETA piggy-back. Only show
                // when the rider STILL has dispatched-undelivered work
                // (the OFD bucket here): when the run is over the
                // estimate is irrelevant and would just confuse the
                // operator. Cache writer guarantees freshness; we don't
                // call Google here.
                $rtb = null;
                if ((int) $r->ofd_items > 0) {
                    $rtb = $this->getCachedQurbaniReturnToBase((int) $r->rider_id);
                }

                $payload[] = [
                    'rider_id' => (int) $r->rider_id,
                    'rider_name' => $r->rider_name,
                    'pending_items' => (int) $r->pending_items,
                    'ofd_items' => (int) $r->ofd_items,
                    'delivered_items' => (int) $r->delivered_items,
                    'last_dispatched_at' => $r->last_dispatched_at ? (string) $r->last_dispatched_at : null,
                    'last_delivered_at'  => $r->last_delivered_at  ? (string) $r->last_delivered_at  : null,
                    'route_locked' => (bool) $lock,
                    'route_lock' => $lock ? [
                        'locked_by' => (int) $lock->locked_by,
                        'locked_by_name' => $lock->locked_by_name,
                        'locked_at' => $lock->locked_at,
                    ] : null,
                    // Phase C — GPS health.
                    'gps' => [
                        'status'         => $gpsStatus,           // live | recent | stale | none
                        'age_minutes'    => $gpsAgeMinutes,
                        'captured_at'    => $gpsCapturedAt,
                        'latitude'       => $g && $g->latitude ? (float) $g->latitude : null,
                        'longitude'      => $g && $g->longitude ? (float) $g->longitude : null,
                    ],
                    // Phase B (May-2026 ext) — back-to-base chip. Null
                    // when the rider has no dispatched OFD items OR no
                    // dispatch has run yet today.
                    'return_to_base' => $rtb,
                ];
            }

            // Phase 3 (May-2026) — auto-WhatsApp piggyback. Cheap
            // when nothing's eligible (master-off / no candidates) and
            // self-throttled by a 55s cache lock so the high-frequency
            // poll from the manager planner doesn't matter.
            $this->fireQurbaniWaAutoSender();

            return response()->json(['success' => true, 'riders' => $payload]);
        } catch (\Exception $e) {
            \Log::error('Failed to load qurbani riders summary', ['error' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Phase 3 (May-2026) — fire the Qurbani auto-WhatsApp sender on
     * an `app()->terminating()` callback so the response is already
     * flushed by the time we hit Meta's API.
     *
     * Safe to call from anywhere; the service short-circuits if the
     * master switch is off, and a Cache lock prevents two parallel
     * callers from both running the worker (the second one no-ops).
     */
    private function fireQurbaniWaAutoSender(): void
    {
        try {
            app()->terminating(function () {
                try {
                    /** @var \App\Services\QurbaniWaAutoSender $svc */
                    $svc = app(\App\Services\QurbaniWaAutoSender::class);
                    $svc->processNow();
                } catch (\Throwable $e) {
                    // Worker errors must NEVER affect the request.
                    \Log::warning('QurbaniWaAutoSender (terminating) failed', ['error' => $e->getMessage()]);
                }
            });
        } catch (\Throwable $e) {
            // Some exotic environments (testing) can't register
            // terminating callbacks — silently no-op there too.
            \Log::debug('QurbaniWaAutoSender hook skipped', ['error' => $e->getMessage()]);
        }
    }

    /**
     * Fire the rider-GPS "defibrillator" sweep on an app()->terminating()
     * callback (the heartbeat response is already flushed by then). The sweep is
     * itself lock-throttled to ~once/min, so calling it on every heartbeat is
     * cheap — with N active riders heartbeating, it runs about once a minute
     * total, enough to catch a rider who has just gone silent. Never affects the
     * request.
     */
    private function fireRiderGpsWatchdog(): void
    {
        try {
            app()->terminating(function () {
                try {
                    app(\App\Services\Location\RiderGpsWatchdog::class)->runThrottled();
                } catch (\Throwable $e) {
                    \Log::warning('RiderGpsWatchdog (terminating) failed', ['error' => $e->getMessage()]);
                }
            });
        } catch (\Throwable $e) {
            \Log::debug('RiderGpsWatchdog hook skipped', ['error' => $e->getMessage()]);
        }
    }

    /**
     * U4 — escalate to management when a company-bike rider is home 10+ min without recording his
     * meter, or came home late (never arrived, window passed). Piggybacks on the rider heartbeat
     * (so a dead-phone rider is still caught by OTHER riders' heartbeats), self-throttled to once a
     * minute, and fires in terminating() so the rider's response isn't slowed. Stamps
     * home_mgmt_alerted_at so each rider is pushed at most once per journey.
     */
    private function fireHomeMeterEscalation(): void
    {
        try {
            app()->terminating(function () {
                try {
                    if (!\Cache::add('home_meter_escalation_lock', 1, 55)) { return; } // ~once/min
                    if (!\Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_expected_by')) { return; }
                    $hj = new \App\Services\Riders\HomeJourneyService();
                    $hasAlerted = \Illuminate\Support\Facades\Schema::hasColumn('t_ops_attendance', 'home_mgmt_alerted_at');
                    foreach ($hj->openEscalations() as $e) {
                        if (!empty($e['already_pushed'])) { continue; }
                        try {
                            (new \App\Services\FirebaseService())->notifyHomeMeterMissed(
                                $e['attendance_id'], $e['rider_name'], $e['state'], $e['minutes_late']
                            );
                        } catch (\Throwable $ex) { /* push best-effort */ }
                        if ($hasAlerted) {
                            \DB::table('t_ops_attendance')->where('id', $e['attendance_id'])
                                ->update(['home_mgmt_alerted_at' => now()]);
                        }
                    }
                } catch (\Throwable $e) {
                    \Log::warning('HomeMeterEscalation (terminating) failed', ['error' => $e->getMessage()]);
                }
            });
        } catch (\Throwable $e) {
            \Log::debug('HomeMeterEscalation hook skipped', ['error' => $e->getMessage()]);
        }
    }

    /**
     * Auto location-request drain — same "fire off the manager poll" pattern as
     * fireQurbaniWaAutoSender(). Registers an app()->terminating() drain of the
     * t_crm_location_auto_queue so queued requests (written on order accept /
     * create) go out on the mobile/web open-orders sync rather than depending on
     * the cron. No-op when the location automation is off; lock-protected so it
     * never double-fires with the cron.
     */
    private function fireLocationAutoDrain(): void
    {
        try {
            app(\App\Services\Location\OpenOrderLocationService::class)->fireFromRequest();
        } catch (\Throwable $e) {
            \Log::debug('LocationAutoDrain hook skipped', ['error' => $e->getMessage()]);
        }
    }

    /**
     * GET /rider/qurbani/riders/{riderId}/route?show=ofd|delivered|all
     *
     * Returns the rider's bundle-grouped route with route metadata and
     * lock state. Caller can be the manager (any auth'd user with
     * access_qurbani_mode) or the rider themselves (so they see what was
     * dispatched to them in the Qurbani delivery view).
     */
    public function getQurbaniRiderRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            // Riders can always see their own route (no qurbani-mode
            // permission gate). Managers viewing someone else's route
            // need the qurbani-mode permission.
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $show = strtolower((string) $request->get('show', 'ofd'));
            // Accept 'ofd' as alias for 'open' but restrict to OFD-only
            // when the manager wants to see the active dispatch list.
            $filter = $show;
            if ($show === 'ofd') {
                $filter = 'open';
            }
            if (!in_array($filter, ['open', 'delivered', 'all'], true)) {
                $filter = 'open';
            }
            $route = $this->buildQurbaniRiderRoute($riderId, $filter);
            $bundles = $route['bundles'];

            // If the caller asked specifically for "ofd" we further trim
            // to bundles whose status is out_for_delivery (skips bundles
            // still in pending / slaughtered for the manager planner).
            if ($show === 'ofd') {
                $bundles = array_values(array_filter($bundles, function ($b) {
                    return ($b['bundle_status'] ?? '') === 'out_for_delivery';
                }));
            }

            // Phase A3 (May-2026) — passive late detection. If the
            // earliest pending dispatched bundle's stored ETA is more
            // than threshold minutes in the past, the rider is running
            // late even before any delivery has completed. Fire one
            // recompute (no-op if rate-limited or no GPS available).
            // Re-fetch bundles afterwards so the caller sees the new
            // ETAs in the same response.
            $passiveResult = null;
            try {
                $masterEnabled = \App\Models\FIN\ConfigModel::get('qurbani_eta_refresh_enabled', '1') === '1';
                if ($masterEnabled) {
                    $thresholdMin = (int) \App\Models\FIN\ConfigModel::get('qurbani_eta_delay_threshold_minutes', '10');
                    if ($thresholdMin < 1) $thresholdMin = 10;
                    $now = now();
                    $earliestSlip = 0;
                    foreach ($bundles as $b) {
                        if (($b['bundle_status'] ?? '') !== 'out_for_delivery') continue;
                        if (($b['bundle_dispatch_status'] ?? '') !== 'dispatched') continue;
                        // Skip bundles already delivered.
                        if (!empty($b['qurbani_delivered_at'])) continue;
                        $eta = $b['qurbani_estimated_delivery_at'] ?? null;
                        if (!$eta) continue;
                        try {
                            $etaCarbon = \Carbon\Carbon::parse($eta);
                            $slip = (int) $etaCarbon->diffInMinutes($now, false); // signed
                            if ($slip > $earliestSlip) $earliestSlip = $slip;
                        } catch (\Exception $e) { /* ignore */ }
                    }
                    if ($earliestSlip > $thresholdMin) {
                        $passiveResult = $this->recomputeQurbaniEtasInternal((int) $riderId, (int) $user->id, 'passive_late_detect');
                        // Re-fetch bundles only when the recompute
                        // actually mutated rows — avoids a redundant
                        // query when we got rate-limited.
                        if (($passiveResult['action'] ?? '') === 'updated' && ($passiveResult['updated'] ?? 0) > 0) {
                            $route = $this->buildQurbaniRiderRoute($riderId, $filter);
                            $bundles = $route['bundles'];
                            if ($show === 'ofd') {
                                $bundles = array_values(array_filter($bundles, function ($b) {
                                    return ($b['bundle_status'] ?? '') === 'out_for_delivery';
                                }));
                            }
                        }
                    }
                }
            } catch (\Exception $e) {
                \Log::warning('Qurbani passive late-detect failed', [
                    'rider_id' => $riderId, 'error' => $e->getMessage(),
                ]);
            }

            $this->enrichBundleEtaComparison($bundles);
            $this->enrichBundleSlotCompare($bundles);
            // May-2026 — promise-vs-actual drift on delivered bundles.
            // Reads t_ops_qurbani_wa_log to pull the original ETA the
            // customer was told via WhatsApp (or falls back to system
            // ETA). Used by the rider-route Delivered redesign.
            $this->enrichDeliveredPromiseDrift($bundles);

            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->select('id', 'fullname')
                ->first();

            // Aggregate dispatch metadata from the bundles (use latest
            // dispatched_at across all bundles since the route is
            // dispatched as one unit).
            $latestDispatchedAt = null;
            $latestDispatchedBy = null;
            $latestStartedAt = null;
            // Live tracking is bundle-shared but stored per row, so we
            // surface ONE aggregate boolean: true if any DISPATCHED &
            // undelivered bundle has the flag on. Bundles already
            // delivered shouldn't keep live tracking "on" in the UI.
            $liveTrackingEnabled = false;
            foreach ($bundles as $b) {
                if (!empty($b['qurbani_dispatched_at'])) {
                    if (!$latestDispatchedAt || strtotime($b['qurbani_dispatched_at']) > strtotime($latestDispatchedAt)) {
                        $latestDispatchedAt = $b['qurbani_dispatched_at'];
                        $latestDispatchedBy = $b['qurbani_dispatched_by'] ?? null;
                    }
                }
                if (!empty($b['qurbani_started_delivery_at'])) {
                    if (!$latestStartedAt || strtotime($b['qurbani_started_delivery_at']) > strtotime($latestStartedAt)) {
                        $latestStartedAt = $b['qurbani_started_delivery_at'];
                    }
                }
                if (!empty($b['qurbani_live_tracking_enabled'])
                    && empty($b['qurbani_delivered_at'])
                    && ($b['bundle_status'] ?? '') === 'out_for_delivery') {
                    $liveTrackingEnabled = true;
                }
            }
            $dispatchedByName = null;
            if ($latestDispatchedBy) {
                $dispatchedByName = \DB::table('t_sys_user')->where('id', $latestDispatchedBy)->value('fullname');
            }

            // Phase C — GPS health for THIS rider so the planner card
            // can show a pill at the top. Re-uses the same thresholds
            // as getQurbaniRidersSummary (live ≤5min, recent ≤30min,
            // stale beyond, none = no reading).
            $gpsRow = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->orderBy('captured_at', 'desc')
                ->select('latitude', 'longitude', 'captured_at')
                ->first();
            $gpsStatus = 'none';
            $gpsAgeMinutes = null;
            $gpsCapturedAt = null;
            if ($gpsRow && $gpsRow->captured_at) {
                $gpsCapturedAt = (string) $gpsRow->captured_at;
                try {
                    $captured = \Carbon\Carbon::parse($gpsRow->captured_at);
                    $gpsAgeMinutes = (int) abs(now()->diffInMinutes($captured));
                    if ($gpsAgeMinutes <= 5)        $gpsStatus = 'live';
                    elseif ($gpsAgeMinutes <= 30)   $gpsStatus = 'recent';
                    else                            $gpsStatus = 'stale';
                } catch (\Exception $e) { /* leave as none */ }
            }

            // Phase 3 (May-2026) — Qurbani auto-WhatsApp piggyback.
            // Run the auto-sender AFTER the response is flushed so the
            // manager UI never waits on Meta latency. The service
            // self-throttles via Cache::add (55s lock) so calling it
            // from every poll is safe.
            $this->fireQurbaniWaAutoSender();

            return response()->json([
                'success' => true,
                'rider' => $rider ? ['id' => (int) $rider->id, 'name' => $rider->fullname] : null,
                'bundles' => $bundles,
                'route_lock' => $this->getQurbaniRouteLockInfo($riderId),
                'dispatch' => [
                    'dispatched_at' => $latestDispatchedAt,
                    'dispatched_by' => $latestDispatchedBy ? (int) $latestDispatchedBy : null,
                    'dispatched_by_name' => $dispatchedByName,
                    'started_delivery_at' => $latestStartedAt,
                    // Phase 1 (May-2026) — bundle-shared aggregate flag.
                    // Manager planner renders the toggle pill from this;
                    // rider app gates the auto-refresh loop on it.
                    'live_tracking_enabled' => $liveTrackingEnabled,
                ],
                'gps' => [
                    'status'      => $gpsStatus,
                    'age_minutes' => $gpsAgeMinutes,
                    'captured_at' => $gpsCapturedAt,
                    'latitude'    => $gpsRow && $gpsRow->latitude  ? (float) $gpsRow->latitude  : null,
                    'longitude'   => $gpsRow && $gpsRow->longitude ? (float) $gpsRow->longitude : null,
                ],
                // Phase A3 — present only when a passive late-detect
                // recompute was attempted on this request. Clients can
                // surface a one-off toast (e.g. "Running late — ETAs
                // refreshed") without polling extra endpoints.
                'passive_recompute' => $passiveResult,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to load qurbani rider route', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * GET /api/rider/qurbani/riders/{riderId}/dispatch-map
     * GET /qurbani/api/riders/{riderId}/dispatch-map  (web alias)
     *
     * Phase C (May-2026) — payload for the Qurbani dispatch map (mobile +
     * web). Scoped to ONE rider's CURRENT dispatch event (the latest
     * qurbani_dispatched_at across their assignments) so the modal
     * shows pins for just this trip:
     *
     *   - rider's last GPS reading (with status: live | recent | stale | none)
     *   - Qurbani Operations Base (when configured)
     *   - one pin per OFD bundle (orange, with sequence + ETA + customer)
     *   - one pin per delivered-this-dispatch bundle (green, greyed-out
     *     style on client; we just expose the data)
     *
     * Authorisation mirrors getQurbaniRiderRoute — manager with
     * access_qurbani_mode OR the rider themselves.
     */
    public function getQurbaniDispatchMap(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->select('id', 'fullname')
                ->first();
            if (!$rider) {
                return response()->json(['success' => false, 'message' => 'Rider not found'], 404);
            }

            // Pull the rider's latest dispatched_at — this becomes the
            // batch discriminator for the map. We allow a small tolerance
            // (5 min) on either side to capture bundles that were
            // dispatched in the same press but stamped a few seconds
            // apart due to per-bundle UPDATE order.
            $latestDispatch = \DB::table('t_crm_prod_order_line_item')
                ->where('qurbani_assigned_rider_user_id', $riderId)
                ->whereNotNull('qurbani_dispatched_at')
                ->max('qurbani_dispatched_at');

            // Build the rider's full route with location info, then
            // bucket bundles into "this dispatch · OFD" and "this
            // dispatch · delivered". Bundles never dispatched are
            // ignored — the map is about the in-flight trip.
            $route = $this->buildQurbaniRiderRoute($riderId, 'all');
            $ofd = [];
            $delivered = [];
            if ($latestDispatch) {
                $cutoffMin = \Carbon\Carbon::parse($latestDispatch)->subMinutes(5);
                $cutoffMax = \Carbon\Carbon::parse($latestDispatch)->addMinutes(5);
                foreach ($route['bundles'] as $b) {
                    $disp = $b['qurbani_dispatched_at'] ?? null;
                    if (!$disp) continue;
                    try {
                        $d = \Carbon\Carbon::parse($disp);
                        if ($d->lt($cutoffMin) || $d->gt($cutoffMax)) continue;
                    } catch (\Exception $e) { continue; }
                    $entry = [
                        'bundle_key'                    => $b['bundle_key'],
                        'order_id'                      => $b['order_id'] ?? null,
                        'order_number'                  => $b['order_number'] ?? null,
                        'customer_name'                 => $b['customer_name'] ?? null,
                        'customer_phone'                => $b['customer_phone'] ?? null,
                        'customer_address'              => $b['customer_address'] ?? null,
                        'qurbani_region'                => $b['qurbani_region'] ?? null,
                        'qurbani_sub_region'            => $b['qurbani_sub_region'] ?? null,
                        'lat'                           => $b['cust_lat'] ? (float) $b['cust_lat'] : null,
                        'lng'                           => $b['cust_lng'] ? (float) $b['cust_lng'] : null,
                        'priority'                      => $b['qurbani_delivery_priority'] ?? null,
                        'estimated_delivery_at'         => $b['qurbani_estimated_delivery_at'] ?? null,
                        'delivered_at'                  => $b['qurbani_delivered_at'] ?? null,
                        'bundle_size'                   => $b['bundle_size'] ?? null,
                        'item_count'                    => count($b['items'] ?? []),
                    ];
                    $isDelivered = !empty($b['qurbani_delivered_at']) || ($b['bundle_status'] ?? '') === 'delivered';
                    if ($isDelivered) {
                        $delivered[] = $entry;
                    } elseif (($b['bundle_status'] ?? '') === 'out_for_delivery') {
                        $ofd[] = $entry;
                    }
                }
                // Order OFD by route priority for nicer numbering on map.
                usort($ofd, function ($a, $b) {
                    $pa = $a['priority'] ?? 9999;
                    $pb = $b['priority'] ?? 9999;
                    return $pa <=> $pb;
                });
                // Delivered ordered by actual delivery time.
                usort($delivered, function ($a, $b) {
                    return strcmp((string) ($a['delivered_at'] ?? ''), (string) ($b['delivered_at'] ?? ''));
                });
            }

            // Rider GPS — same shape as getQurbaniRiderRoute.
            $gpsRow = \DB::table('t_ops_rider_location')
                ->where('user_id', $riderId)
                ->orderBy('captured_at', 'desc')
                ->select('latitude', 'longitude', 'captured_at')
                ->first();
            $gpsStatus = 'none';
            $gpsAgeMinutes = null;
            $gpsCapturedAt = null;
            if ($gpsRow && $gpsRow->captured_at) {
                $gpsCapturedAt = (string) $gpsRow->captured_at;
                try {
                    $captured = \Carbon\Carbon::parse($gpsRow->captured_at);
                    $gpsAgeMinutes = (int) abs(now()->diffInMinutes($captured));
                    if ($gpsAgeMinutes <= 5)        $gpsStatus = 'live';
                    elseif ($gpsAgeMinutes <= 30)   $gpsStatus = 'recent';
                    else                            $gpsStatus = 'stale';
                } catch (\Exception $e) { /* leave none */ }
            }

            $qBase = \App\Services\LocationService::getQurbaniBaseLocation();

            // May-2026 — compute the EFFECTIVE ORIGIN the map should
            // visually anchor the route to. Mirrors the freshness gate
            // used by Auto Route + Dispatch (Start) — see
            // QURBANI_FRESH_GPS_MINUTES. The mobile dispatch map and
            // the "Open in Google Maps" link both read this field so
            // the map shows the SAME starting point the server uses
            // when planning ETAs:
            //
            //   - GPS within last 10 min  → rider GPS (live route)
            //   - GPS older / missing     → Qurbani warehouse base
            //                               (if configured)
            //   - No base + no fresh GPS  → null (mobile shows a
            //                               warning instead of a
            //                               misleading start point)
            //
            // Surfacing this server-side keeps map / route / Google
            // Maps deep-link aligned — no more "the map shows my
            // GPS as start but the ETAs were planned from the
            // warehouse" mismatch.
            $effectiveOrigin = null;
            $freshGpsMin = self::QURBANI_FRESH_GPS_MINUTES;
            if ($gpsRow && $gpsRow->latitude && $gpsRow->longitude
                && $gpsAgeMinutes !== null && $gpsAgeMinutes <= $freshGpsMin) {
                $effectiveOrigin = [
                    'lat'          => (float) $gpsRow->latitude,
                    'lng'          => (float) $gpsRow->longitude,
                    'source'       => 'rider_gps',
                    'source_label' => 'Rider GPS · ' . $gpsAgeMinutes . ' min ago',
                ];
            } elseif ($qBase) {
                $effectiveOrigin = [
                    'lat'          => (float) $qBase->latitude,
                    'lng'          => (float) $qBase->longitude,
                    'source'       => 'qurbani_base',
                    'source_label' => 'Warehouse (' . $qBase->location_name . ')',
                ];
            }

            return response()->json([
                'success' => true,
                'rider' => ['id' => (int) $rider->id, 'name' => $rider->fullname],
                'dispatched_at' => $latestDispatch,
                'rider_gps' => [
                    'status'      => $gpsStatus,
                    'age_minutes' => $gpsAgeMinutes,
                    'captured_at' => $gpsCapturedAt,
                    'lat'         => $gpsRow && $gpsRow->latitude  ? (float) $gpsRow->latitude  : null,
                    'lng'         => $gpsRow && $gpsRow->longitude ? (float) $gpsRow->longitude : null,
                    // May-2026 — explicit "fresh enough to be used as
                    // origin?" flag so the mobile map can stop
                    // duplicating the freshness rule client-side.
                    'is_fresh'    => $gpsAgeMinutes !== null && $gpsAgeMinutes <= $freshGpsMin,
                    'fresh_threshold_min' => $freshGpsMin,
                ],
                'base' => $qBase ? [
                    'name' => (string) $qBase->location_name,
                    'lat'  => (float) $qBase->latitude,
                    'lng'  => (float) $qBase->longitude,
                ] : null,
                // The single source of truth for the route start —
                // the mobile map uses this for the polyline anchor
                // and the Open-in-Google-Maps origin parameter.
                'effective_origin' => $effectiveOrigin,
                'ofd_bundles'       => $ofd,
                'delivered_bundles' => $delivered,
                'counts' => [
                    'ofd'       => count($ofd),
                    'delivered' => count($delivered),
                    'total'     => count($ofd) + count($delivered),
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to load Qurbani dispatch map', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * POST /rider/qurbani/riders/{riderId}/optimize-route
     *
     * Dry-run: returns a suggested bundle ordering based on Google
     * nearest-neighbour. Does NOT persist anything — the caller
     * confirms by pressing Set Route which calls saveQurbaniRoute()
     * (which itself enforces the lock + permission).
     *
     * Note: works on BUNDLES (one stop per bundle) — multiple items
     * inside the same bundle collapse to a single waypoint because the
     * rider drops them all off in one stop.
     *
     * Permissions: caller can be the manager (any user with
     * access_qurbani_mode, viewing/optimising someone else's route)
     * OR the rider themselves on their own route. May-2026 fix —
     * previously this endpoint was manager-only, which broke the
     * "Auto Route" button in the rider's own delivery view. Now
     * matches the pattern used by saveQurbaniRoute, dispatchQurbani-
     * Route, refreshQurbaniRoute, cancelQurbaniDispatch, etc.
     */
    public function optimizeQurbaniRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->where('is_active', 1)
                ->select('id', 'fullname')
                ->first();
            if (!$rider) {
                return response()->json(['success' => false, 'message' => 'Rider not found'], 404);
            }

            // Origin lookup: rider GPS → Qurbani Operations Base →
            // assigned office → primary office. The Qurbani-specific
            // base (configurable from /qurbani-settings) is the new
            // preferred fallback so ETAs reflect the actual depot
            // when the rider's app hasn't pinged GPS recently.
            //
            // May-2026 — freshness tightened 30 → 10 min (see
            // QURBANI_FRESH_GPS_MINUTES). 30 was too lenient: a
            // rider whose GPS pinged 25 min ago could have moved
            // far enough that planning the route from their stale
            // pin would produce wrong ETAs — using the configured
            // warehouse is the safer fallback in that case.
            $origin = \App\Services\LocationService::getQurbaniOriginForRider($riderId, self::QURBANI_FRESH_GPS_MINUTES);
            if (!$origin) {
                return response()->json([
                    'success' => false,
                    'message' => 'No origin available — rider GPS is stale, no Qurbani base set, and no office location configured.',
                ], 400);
            }
            $usedShopLocation = ($origin['source'] !== 'rider_gps');
            $riderLocation = (object) [
                'latitude'  => $origin['latitude'],
                'longitude' => $origin['longitude'],
            ];

            // Optimise PENDING out-for-delivery bundles only — the
            // already-dispatched batch is frozen by design (the manager
            // wants to plan around it without disrupting a running
            // delivery run). Already-dispatched bundles keep their
            // priority and ETA untouched here.
            $route = $this->buildQurbaniRiderRoute($riderId, 'open');
            $bundles = array_values(array_filter($route['bundles'], function ($b) {
                return ($b['bundle_status'] ?? '') === 'out_for_delivery'
                    && ($b['bundle_dispatch_status'] ?? '') === 'pending';
            }));

            if (empty($bundles)) {
                return response()->json([
                    'success' => false,
                    'message' => 'No pending out-for-delivery bundles to optimize. Already-dispatched bundles are frozen.',
                ], 400);
            }

            // Continue priority numbering AFTER the existing dispatched
            // batch so saved priorities don't collide.
            $maxDispatchedPriority = 0;
            foreach ($route['bundles'] as $b) {
                if (($b['bundle_dispatch_status'] ?? '') === 'dispatched'
                    && $b['qurbani_delivery_priority'] !== null
                    && (int) $b['qurbani_delivery_priority'] > $maxDispatchedPriority) {
                    $maxDispatchedPriority = (int) $b['qurbani_delivery_priority'];
                }
            }

            $waypoints = [['lat' => (float) $riderLocation->latitude, 'lng' => (float) $riderLocation->longitude]];
            $bundlesWithLoc = [];
            $unverified = [];
            $noLocation = [];
            foreach ($bundles as $b) {
                if ($b['cust_lat'] && $b['cust_lng']) {
                    $waypoints[] = ['lat' => (float) $b['cust_lat'], 'lng' => (float) $b['cust_lng']];
                    $bundlesWithLoc[] = $b;
                } else {
                    $noLocation[] = $b['order_number'] . ' (' . $b['customer_name'] . ')';
                }
            }
            if (count($bundlesWithLoc) === 0) {
                return response()->json([
                    'success' => false,
                    'message' => 'No bundles have GPS coordinates — verify customer locations first.',
                ], 400);
            }

            $result = $this->getOptimizedRouteFromGoogle($waypoints);
            if (!$result) {
                return response()->json([
                    'success' => false,
                    'message' => 'Failed to optimize route (Google API error or limit reached).',
                ], 500);
            }

            // Build optimised sequence with cumulative travel + 5 min
            // buffer between stops (per user spec — different from
            // regular orders' 10 min). ETA is clock time of arrival.
            $stopBufferMinutes = 5;
            $now = now();
            $cumulative = 0;
            $optimised = [];
            foreach ($result['waypoint_order'] as $idx => $originalIndex) {
                $b = $bundlesWithLoc[$originalIndex];
                $legDuration = $result['legs'][$idx] ?? 0;
                $cumulative += $legDuration;
                $estAt = $now->copy()->addMinutes(round($cumulative));
                $optimised[] = [
                    'bundle_key' => $b['bundle_key'],
                    'order_id' => $b['order_id'],
                    'order_number' => $b['order_number'],
                    'customer_name' => $b['customer_name'],
                    // Priorities continue AFTER the dispatched batch's
                    // max so saving doesn't reshuffle dispatched stops.
                    'priority' => $maxDispatchedPriority + $idx + 1,
                    'travel_minutes' => round($legDuration),
                    'cumulative_minutes' => round($cumulative),
                    'estimated_at' => $estAt->format('h:i A'),
                ];
                $cumulative += $stopBufferMinutes;
            }

            $response = [
                'success' => true,
                'optimized_sequence' => $optimised,
                'total_time_minutes' => round($cumulative - $stopBufferMinutes),
                'total_distance_km' => $result['total_distance_km'] ?? null,
                'bundles_count' => count($optimised),
                'no_location_bundles' => $noLocation,
            ];
            // Tell the caller which origin we used so the UI can warn
            // the manager when the route was planned from a fallback
            // (rider's GPS off / Qurbani base / regular office).
            $response['origin_source']       = $origin['source'];
            $response['origin_source_label'] = $origin['source_label'];
            if ($usedShopLocation) {
                $response['gps_warning'] = "Rider GPS not active — route optimized from " . $origin['source_label'] . '.';
            }
            return response()->json($response);
        } catch (\Exception $e) {
            \Log::error('Qurbani optimize route failed', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * POST /rider/qurbani/riders/{riderId}/save-route
     * Body: { sequence: [{ bundle_key, priority }, ...] }
     *
     * Persists qurbani_delivery_priority to every line item in each
     * named bundle. Rejects if the route is locked by someone else.
     *
     * Caller can be the manager (any user with access_qurbani_mode) or
     * the rider themselves — if locked by the manager, the rider can't
     * resequence, but can still call dispatch.
     */
    public function saveQurbaniRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $validated = $request->validate([
                'sequence' => 'required|array|min:1',
                'sequence.*.bundle_key' => 'required|string',
                'sequence.*.priority' => 'required|integer|min:1',
            ]);

            // Lock check (mode='qurbani').
            $lock = $this->getQurbaniRouteLockInfo($riderId);
            if ($lock && (int) $lock['locked_by'] !== (int) $user->id) {
                return response()->json([
                    'success' => false,
                    'message' => "Route is locked by {$lock['locked_by_name']}. Unlock it first to change the sequence.",
                    'route_locked' => true,
                    'locked_by_name' => $lock['locked_by_name'],
                ], 423);
            }

            // Re-compute bundles for THIS rider so we can resolve
            // bundle_key -> set of line_item ids server-side. Don't
            // trust client-provided line_item ids — bundle_key is
            // deterministic but the client should never enumerate item
            // ids for an assignment update.
            $route = $this->buildQurbaniRiderRoute($riderId, 'all');
            $bundles = $route['bundles'];
            $byKey = [];
            foreach ($bundles as $b) {
                $byKey[$b['bundle_key']] = $b;
            }

            \DB::beginTransaction();
            $updatedBundles = 0;
            $updatedItems = 0;
            $skippedDispatched = 0;
            foreach ($validated['sequence'] as $entry) {
                $b = $byKey[$entry['bundle_key']] ?? null;
                if (!$b) continue; // bundle no longer exists — skip silently
                // Dispatched bundles are frozen — skip silently. The
                // client SHOULD only send pending bundles, but we
                // enforce here defensively so a stale UI can't kick
                // the dispatched batch out of sequence.
                if (($b['bundle_dispatch_status'] ?? '') === 'dispatched') {
                    $skippedDispatched++;
                    continue;
                }
                $itemIds = array_map(fn($it) => $it['id'], $b['items']);
                if (empty($itemIds)) continue;
                $rows = \DB::table('t_crm_prod_order_line_item')
                    ->whereIn('id', $itemIds)
                    ->where('qurbani_assigned_rider_user_id', $riderId)
                    ->whereNull('qurbani_dispatched_at') // belt + suspenders
                    ->update([
                        'qurbani_delivery_priority' => $entry['priority'],
                        'updated_at' => now(),
                    ]);
                if ($rows > 0) {
                    $updatedBundles++;
                    $updatedItems += $rows;
                }
            }
            \DB::commit();

            $msg = "Route saved ({$updatedBundles} bundles, {$updatedItems} items).";
            if ($skippedDispatched > 0) {
                $msg .= " {$skippedDispatched} already-dispatched bundle(s) kept frozen.";
            }
            return response()->json([
                'success' => true,
                'message' => $msg,
                'updated_bundles' => $updatedBundles,
                'updated_items' => $updatedItems,
                'skipped_dispatched' => $skippedDispatched,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Qurbani save route failed', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * POST /api/rider/qurbani/riders/{riderId}/edit-dispatched-route
     *
     * Phase G (May-2026) — post-dispatch reorder.
     *
     * Lets the manager (or rider on their own route) reshuffle the
     * sequence of bundles that have ALREADY been dispatched, without
     * having to un-dispatch and re-dispatch the route. Useful when
     * field conditions change mid-run: a customer says "come in an
     * hour", a road is blocked, weather rerouting, etc.
     *
     * Differences from `saveQurbaniRoute`:
     *   - Accepts priority updates on dispatched bundles (the older
     *     endpoint silently skips them by design).
     *   - Recomputes ETAs against the rider's CURRENT origin (GPS if
     *     fresh, else base / office — same chain as dispatch + refresh).
     *   - 30-minute delta gate: a recomputed ETA is only persisted
     *     when it differs from the saved ETA by MORE than
     *     `eta_threshold_min` (default 30). Below the threshold the
     *     old ETA is kept so customer-facing surfaces (rider screen,
     *     auto-WA "Out for delivery" timing, future ETA pushes) don't
     *     flicker on every small reorder. The manager still sees the
     *     `eta_changes` array in the response so they know what the
     *     fresh Google ETA would have been.
     *
     * Caller pattern:
     *   - Mobile sends the full new sequence (dispatched + pending)
     *     on the 5-second debounce after the manager finishes
     *     reordering, AND again when they press "Save & Exit".
     *   - Server does the heavy lifting (Google call + delta gate +
     *     persistence). Mobile just shows the summary toast.
     *
     * Request body:
     *   {
     *     sequence: [{ bundle_key: string, priority: int }, ...],
     *     recompute: bool          // default true; false = priorities only
     *     eta_threshold_min: int   // default 30; clamp 0..240
     *   }
     */
    public function editDispatchedRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $validated = $request->validate([
                'sequence' => 'required|array|min:1',
                'sequence.*.bundle_key' => 'required|string',
                'sequence.*.priority' => 'required|integer|min:1',
                'recompute' => 'sometimes|boolean',
                'eta_threshold_min' => 'sometimes|integer|min:0|max:240',
            ]);
            $recompute = $request->boolean('recompute', true);
            $threshold = (int) ($validated['eta_threshold_min'] ?? 30);

            // Lock check — block anyone else from editing while a
            // different user has the route locked.
            $lock = $this->getQurbaniRouteLockInfo($riderId);
            if ($lock && (int) $lock['locked_by'] !== (int) $user->id) {
                return response()->json([
                    'success' => false,
                    'message' => "Route is locked by {$lock['locked_by_name']}. Unlock it first to change the dispatched sequence.",
                    'route_locked' => true,
                    'locked_by_name' => $lock['locked_by_name'],
                ], 423);
            }

            $route = $this->buildQurbaniRiderRoute($riderId, 'all');
            $bundles = $route['bundles'];
            $byKey = [];
            foreach ($bundles as $b) {
                $byKey[$b['bundle_key']] = $b;
            }

            // 1) Persist priorities for every non-delivered bundle in
            //    the supplied sequence (dispatched OR pending). The
            //    delivered guard is enforced both at the PHP level
            //    AND the DB query so a stale client can't accidentally
            //    rewrite a delivered item's priority.
            \DB::beginTransaction();
            $updatedItems = 0;
            $updatedBundles = 0;
            $touchedDispatchedKeys = [];
            foreach ($validated['sequence'] as $entry) {
                $b = $byKey[$entry['bundle_key']] ?? null;
                if (!$b) continue;
                $ds = $b['bundle_dispatch_status'] ?? 'pending';
                if ($ds === 'delivered') continue;
                $itemIds = array_map(fn($it) => $it['id'], $b['items']);
                if (empty($itemIds)) continue;
                $rows = \DB::table('t_crm_prod_order_line_item')
                    ->whereIn('id', $itemIds)
                    ->where('qurbani_assigned_rider_user_id', $riderId)
                    ->whereNull('qurbani_delivered_at')
                    ->update([
                        'qurbani_delivery_priority' => $entry['priority'],
                        'updated_at' => now(),
                    ]);
                if ($rows > 0) {
                    $updatedBundles++;
                    $updatedItems += $rows;
                    if ($ds === 'dispatched') {
                        $touchedDispatchedKeys[] = $b['bundle_key'];
                    }
                }
            }
            \DB::commit();

            // 2) Optionally recompute ETAs for the (now-reordered)
            //    dispatched batch and apply the delta gate.
            $etaChanges = [];
            $etaWritten = 0;
            $etaSkipped = 0;
            $totalDurationMin = null;
            $returnToBase = null;
            $originSource = null;
            $bundlesNoLoc = [];
            $googleFailed = false;

            if ($recompute) {
                $route2 = $this->buildQurbaniRiderRoute($riderId, 'open');
                $ofdBundles = array_values(array_filter($route2['bundles'], function ($b) {
                    $ds = $b['bundle_dispatch_status'] ?? 'pending';
                    return ($b['bundle_status'] ?? '') === 'out_for_delivery' && $ds === 'dispatched';
                }));
                // Sort by the freshly-saved priority so the Google
                // call uses the new order.
                usort($ofdBundles, function ($a, $b) {
                    $pa = $a['qurbani_delivery_priority'] ?? 9999;
                    $pb = $b['qurbani_delivery_priority'] ?? 9999;
                    return $pa <=> $pb;
                });

                if (!empty($ofdBundles)) {
                    // Origin chain — same freshness window as Auto
                    // Route and Dispatch. May-2026: tightened 30 →
                    // 10 min via QURBANI_FRESH_GPS_MINUTES so stale
                    // rider GPS falls back to the configured
                    // warehouse instead of producing wrong ETAs.
                    // We're not in the rider's auto-loop so we
                    // don't need the 5-min refresh-self window here.
                    $origin = \App\Services\LocationService::getQurbaniOriginForRider($riderId, self::QURBANI_FRESH_GPS_MINUTES);
                    if ($origin) {
                        $originSource = $origin['source'];
                        $waypoints = [['lat' => (float) $origin['latitude'], 'lng' => (float) $origin['longitude']]];
                        $bundlesWithLoc = [];
                        foreach ($ofdBundles as $b) {
                            if ($b['cust_lat'] && $b['cust_lng']) {
                                $waypoints[] = ['lat' => (float) $b['cust_lat'], 'lng' => (float) $b['cust_lng']];
                                $bundlesWithLoc[] = $b;
                            } else {
                                $bundlesNoLoc[] = $b;
                            }
                        }
                        $qBase = \App\Services\LocationService::getQurbaniBaseLocation();
                        $appendBase = ($qBase !== null && count($bundlesWithLoc) > 0);
                        if ($appendBase) {
                            $waypoints[] = ['lat' => (float) $qBase->latitude, 'lng' => (float) $qBase->longitude];
                        }

                        if (count($bundlesWithLoc) > 0) {
                            $etaResult = $this->getMultiStopEtaFromGoogle($waypoints);
                            if ($etaResult) {
                                $stopBufferMinutes = 5;
                                $cumulative = 0;
                                $now = now();
                                $newEtaByBundle = [];
                                foreach ($bundlesWithLoc as $idx => $b) {
                                    $legDuration = $etaResult['legs'][$idx] ?? 0;
                                    $cumulative += $legDuration;
                                    $estAt = $now->copy()->addMinutes(round($cumulative));
                                    $newEtaByBundle[$b['bundle_key']] = $estAt;
                                    $cumulative += $stopBufferMinutes;
                                }
                                $totalDurationMin = (int) round($cumulative);
                                if ($appendBase) {
                                    $returnLegIdx = count($bundlesWithLoc);
                                    $returnLegMin = $etaResult['legs'][$returnLegIdx] ?? 0;
                                    if ($returnLegMin > 0) {
                                        $cumulativeAtLast = $cumulative - $stopBufferMinutes;
                                        $eta = $now->copy()->addMinutes(round($cumulativeAtLast + $returnLegMin));
                                        $returnToBase = [
                                            'base_name'        => (string) $qBase->location_name,
                                            'base_lat'         => (float) $qBase->latitude,
                                            'base_lng'         => (float) $qBase->longitude,
                                            'return_minutes'   => (int) round($returnLegMin),
                                            'estimated_at'     => $eta->toIso8601String(),
                                            'estimated_at_iso' => $eta->toIso8601String(),
                                        ];
                                        // May-2026 — Persist for manager
                                        // dashboards. See dispatchQurbaniRoute
                                        // for the rationale + cache helper.
                                        $this->cacheQurbaniReturnToBase((int) $riderId, $returnToBase);
                                    }
                                }

                                // 30-minute delta gate. We compare the
                                // freshly-computed ETA against whatever
                                // is currently saved on the bundle. The
                                // gate fires per bundle so a single big
                                // shift can update one customer's ETA
                                // without touching the others.
                                \DB::beginTransaction();
                                foreach ($bundlesWithLoc as $b) {
                                    $newEta = $newEtaByBundle[$b['bundle_key']] ?? null;
                                    if (!$newEta) continue;
                                    $oldEtaRaw = $b['qurbani_estimated_delivery_at'] ?? null;
                                    $oldEta = null;
                                    if ($oldEtaRaw) {
                                        try { $oldEta = \Carbon\Carbon::parse($oldEtaRaw); }
                                        catch (\Exception $e) { $oldEta = null; }
                                    }
                                    $deltaMin = $oldEta ? (int) abs($newEta->diffInMinutes($oldEta)) : null;
                                    // Write if no old ETA, OR delta strictly exceeds threshold.
                                    $shouldWrite = ($oldEta === null) || ($deltaMin !== null && $deltaMin > $threshold);

                                    if ($shouldWrite) {
                                        $itemIds = array_map(fn($it) => $it['id'], $b['items']);
                                        \DB::table('t_crm_prod_order_line_item')
                                            ->whereIn('id', $itemIds)
                                            ->where('qurbani_assigned_rider_user_id', $riderId)
                                            ->whereNull('qurbani_delivered_at')
                                            ->update([
                                                'qurbani_estimated_delivery_at' => $newEta,
                                                'qurbani_eta_calculated_at' => $now,
                                                'updated_at' => $now,
                                            ]);
                                        $etaWritten++;
                                    } else {
                                        $etaSkipped++;
                                    }

                                    $etaChanges[] = [
                                        'bundle_key' => $b['bundle_key'],
                                        'customer_name' => $b['customer_name'],
                                        'old_eta'  => $oldEtaRaw ? (string) $oldEtaRaw : null,
                                        'new_eta'  => $newEta->toIso8601String(),
                                        'delta_min' => $deltaMin,
                                        'written'  => $shouldWrite,
                                    ];
                                }
                                \DB::commit();
                            } else {
                                $googleFailed = true;
                            }
                        }
                    }
                }
            }

            \Log::info('Qurbani dispatched route edited', [
                'rider_id'             => $riderId,
                'edited_by'            => $user->id,
                'is_own_route'         => $isOwnRoute,
                'updated_bundles'      => $updatedBundles,
                'touched_dispatched'   => count($touchedDispatchedKeys),
                'eta_threshold_min'    => $threshold,
                'eta_written_count'    => $etaWritten,
                'eta_skipped_count'    => $etaSkipped,
                'recompute_requested'  => $recompute,
                'google_failed'        => $googleFailed,
                'origin_source'        => $originSource,
            ]);

            $msg = "Route updated ({$updatedBundles} bundle" . ($updatedBundles === 1 ? '' : 's') . ").";
            if ($recompute) {
                if ($googleFailed) {
                    $msg .= " ETA recompute failed (Google API).";
                } elseif ($etaWritten + $etaSkipped === 0) {
                    $msg .= " No ETAs to recompute.";
                } else {
                    $msg .= " ETAs: {$etaWritten} updated (>{$threshold}m delta), {$etaSkipped} unchanged.";
                }
            }

            return response()->json([
                'success' => true,
                'message' => $msg,
                'updated_bundles' => $updatedBundles,
                'updated_items' => $updatedItems,
                'eta_threshold_min' => $threshold,
                'eta_recomputed' => $recompute,
                'eta_written_count' => $etaWritten,
                'eta_skipped_count' => $etaSkipped,
                'eta_changes' => $etaChanges,
                'total_duration_minutes' => $totalDurationMin,
                'return_to_base' => $returnToBase,
                'origin_source' => $originSource,
                'google_failed' => $googleFailed,
                'no_location_bundles' => array_map(function ($b) {
                    return $b['order_number'] . ' (' . $b['customer_name'] . ')';
                }, $bundlesNoLoc),
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            try { \DB::rollBack(); } catch (\Exception $e2) {}
            \Log::error('Qurbani edit dispatched route failed', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
                'trace' => $e->getTraceAsString(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * POST /rider/qurbani/riders/{riderId}/dispatch
     * Body (optional):
     *   target:   'pending' (default)  | 'refresh'
     *   sequence: [{ bundle_key, priority }, ...]   — only honoured for
     *             target='pending' on unlocked / self-locked routes.
     *
     * target='pending' — manager Dispatch button + rider Start Delivery:
     *   - Operates ONLY on bundles with qurbani_dispatched_at IS NULL
     *     (the "Pending" batch — what the user wants to commit).
     *   - Stamps qurbani_dispatched_at/by + ETAs + (rider only) the
     *     first qurbani_started_delivery_at.
     *   - Already-dispatched bundles are NOT touched. Their ETA stays
     *     fixed and their priority stays where it was. This is the
     *     "freeze the dispatched batch" behaviour — managers can keep
     *     planning new bundles without disrupting an in-flight run.
     *
     * target='refresh' — manager-only Refresh ETA button:
     *   - Operates ONLY on bundles with qurbani_dispatched_at IS NOT NULL
     *     AND not delivered (the "Dispatched" batch).
     *   - Recomputes and updates qurbani_estimated_delivery_at +
     *     qurbani_eta_calculated_at. Sequence is preserved (we walk
     *     bundles in current priority order). Does NOT change
     *     qurbani_dispatched_at/by — the original dispatch is still
     *     the same dispatch event.
     *   - Riders cannot call this directly. See 'refresh-self' below.
     *
     * target='refresh-self' (Phase D, May-2026) — rider-only auto/manual
     * ETA refresh while OFD:
     *   - Same effect as 'refresh' but allowed only on the rider's OWN
     *     route. Origin = rider's current GPS (since this is exactly
     *     the situation we want live ETA for).
     *   - Server-side rate limit: max 1 call per minute per rider via
     *     a Cache lock. Avoids hammering Google Directions when the
     *     mobile app misbehaves.
     *   - Skipped (returns success=true with skipped=true) if the
     *     rider has no fresh GPS reading — caller can decide whether
     *     to retry later.
     */
    public function dispatchQurbaniRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            // 'pending' (default) | 'refresh' | 'refresh-self'
            $target = strtolower((string) $request->input('target', 'pending'));
            if (!in_array($target, ['pending', 'refresh', 'refresh-self'], true)) $target = 'pending';
            // refresh-self is rider-only on their own route. It's the
            // sanctioned way for the rider's app to recompute ETAs
            // mid-run without giving them the manager-only 'refresh'.
            if ($target === 'refresh-self' && !$isOwnRoute) {
                return response()->json([
                    'success' => false,
                    'message' => 'refresh-self is only valid on your own route.',
                ], 403);
            }
            // Server-side rate limit on rider-driven auto-refresh —
            // max 1 call/minute/rider. Stops misbehaving mobiles from
            // hammering Google Directions during a delivery run.
            if ($target === 'refresh-self') {
                $rlKey = 'qurbani_eta_refresh_self_' . $riderId;
                if (\Cache::has($rlKey)) {
                    return response()->json([
                        'success'      => true,
                        'skipped'      => true,
                        'skip_reason'  => 'rate_limited',
                        'message'      => 'ETA refresh skipped (rate-limited — try again in a moment).',
                    ]);
                }
                \Cache::put($rlKey, 1, 60);
            }
            // Only managers can hit the manager refresh path.
            if ($target === 'refresh' && $isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json([
                    'success' => false,
                    'message' => 'ETA refresh is manager-only.',
                ], 403);
            }

            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->where('is_active', 1)
                ->select('id', 'fullname')
                ->first();
            if (!$rider) {
                return response()->json(['success' => false, 'message' => 'Rider not found'], 404);
            }

            // Origin lookup: rider GPS → Qurbani Operations Base →
            // assigned office → primary office. Phase A (May-2026)
            // moved this into a shared helper so optimize + dispatch
            // agree on the chain.
            //
            // refresh-self uses a tighter freshness window (5 min) —
            // the whole point of an auto-refresh during a live run is
            // to react to the rider's current position; if their GPS
            // is older than 5 min, we silently skip rather than
            // recompute against stale data.
            //
            // May-2026 — initial-dispatch path tightened 30 → 10 min
            // via QURBANI_FRESH_GPS_MINUTES. See the constant for
            // the rationale. Effect: when the rider presses Start
            // with a GPS reading older than 10 minutes, we use the
            // configured warehouse as the route origin instead of
            // their stale GPS — exactly what the user asked for.
            $freshness = ($target === 'refresh-self') ? 5 : self::QURBANI_FRESH_GPS_MINUTES;
            $origin = \App\Services\LocationService::getQurbaniOriginForRider($riderId, $freshness);
            if ($target === 'refresh-self' && (!$origin || $origin['source'] !== 'rider_gps')) {
                return response()->json([
                    'success'     => true,
                    'skipped'     => true,
                    'skip_reason' => 'gps_stale',
                    'message'     => 'ETA refresh skipped (rider GPS is stale).',
                ]);
            }
            if (!$origin) {
                return response()->json([
                    'success' => false,
                    'message' => 'No origin available — rider GPS is stale, no Qurbani base set, and no office location configured.',
                ], 400);
            }
            $usedShopLocation = ($origin['source'] !== 'rider_gps');
            $riderLocation = (object) [
                'latitude'  => $origin['latitude'],
                'longitude' => $origin['longitude'],
            ];

            $sequence = $request->input('sequence', []);

            \DB::beginTransaction();

            // Optionally persist priorities if caller supplied a sequence
            // AND the route is not locked by someone else AND we're in
            // 'pending' mode (refreshing dispatched ETAs never touches
            // the sequence).
            if ($target === 'pending' && !empty($sequence)) {
                $lock = $this->getQurbaniRouteLockInfo($riderId);
                if (!$lock || (int) $lock['locked_by'] === (int) $user->id) {
                    $route = $this->buildQurbaniRiderRoute($riderId, 'all');
                    $byKey = [];
                    foreach ($route['bundles'] as $b) {
                        $byKey[$b['bundle_key']] = $b;
                    }
                    foreach ($sequence as $entry) {
                        $b = $byKey[$entry['bundle_key']] ?? null;
                        if (!$b) continue;
                        // Don't reshuffle the dispatched batch even if a
                        // stale client sends those keys.
                        if (($b['bundle_dispatch_status'] ?? '') === 'dispatched') continue;
                        $itemIds = array_map(fn($it) => $it['id'], $b['items']);
                        if (empty($itemIds)) continue;
                        \DB::table('t_crm_prod_order_line_item')
                            ->whereIn('id', $itemIds)
                            ->where('qurbani_assigned_rider_user_id', $riderId)
                            ->whereNull('qurbani_dispatched_at')
                            ->update([
                                'qurbani_delivery_priority' => $entry['priority'],
                                'updated_at' => now(),
                            ]);
                    }
                }
                // If route IS locked by someone else, ignore the
                // sequence silently — rider can still get a fresh ETA on
                // the existing locked route.
            }

            // Choose the bundle set to dispatch based on target.
            //   pending       → only never-dispatched OFD bundles
            //   refresh       → only already-dispatched (not delivered) bundles
            //   refresh-self  → same as refresh (rider's own route)
            $route = $this->buildQurbaniRiderRoute($riderId, 'open');
            $isRefresh = ($target === 'refresh' || $target === 'refresh-self');
            $ofdBundles = array_values(array_filter($route['bundles'], function ($b) use ($isRefresh) {
                if (($b['bundle_status'] ?? '') !== 'out_for_delivery') return false;
                $ds = $b['bundle_dispatch_status'] ?? 'pending';
                return $isRefresh ? ($ds === 'dispatched') : ($ds === 'pending');
            }));

            if (empty($ofdBundles)) {
                \DB::rollBack();
                // For rider auto-refresh, treat "nothing to refresh" as
                // a soft skip rather than an error — the screen polls
                // periodically and we don't want a noisy alert.
                if ($target === 'refresh-self') {
                    return response()->json([
                        'success'     => true,
                        'skipped'     => true,
                        'skip_reason' => 'no_dispatched_bundles',
                        'message'     => 'No dispatched bundles to refresh.',
                    ]);
                }
                return response()->json([
                    'success' => false,
                    'message' => $isRefresh
                        ? 'No dispatched bundles to refresh.'
                        : 'No pending out-for-delivery bundles to dispatch.',
                ], 400);
            }

            // Build waypoints in order. Skip bundles without coords; we
            // still dispatch them but their ETA stays NULL.
            $waypoints = [['lat' => (float) $riderLocation->latitude, 'lng' => (float) $riderLocation->longitude]];
            $bundlesWithLoc = [];
            $bundlesNoLoc = [];
            foreach ($ofdBundles as $b) {
                if ($b['cust_lat'] && $b['cust_lng']) {
                    $waypoints[] = ['lat' => (float) $b['cust_lat'], 'lng' => (float) $b['cust_lng']];
                    $bundlesWithLoc[] = $b;
                } else {
                    $bundlesNoLoc[] = $b;
                }
            }

            // Phase B (May-2026) — append the Qurbani Operations Base
            // as a synthetic FINAL waypoint when configured. The extra
            // leg gives us a "Return to base" ETA after the last
            // delivery without any extra Google API calls. If no base
            // is configured we just don't append, and return-to-base
            // stays null in the response.
            $qBase = \App\Services\LocationService::getQurbaniBaseLocation();
            $appendBase = ($qBase !== null && count($bundlesWithLoc) > 0);
            if ($appendBase) {
                $waypoints[] = ['lat' => (float) $qBase->latitude, 'lng' => (float) $qBase->longitude];
            }

            $estimatedAtByBundle = [];
            $totalDuration = 0;
            $returnToBase = null;
            if (count($bundlesWithLoc) > 0) {
                $etaResult = $this->getMultiStopEtaFromGoogle($waypoints);
                if (!$etaResult) {
                    \DB::rollBack();
                    return response()->json([
                        'success' => false,
                        'message' => 'Failed to compute ETAs (Google API error or limit reached).',
                    ], 500);
                }
                $stopBufferMinutes = 5;
                $cumulative = 0;
                $now = now();
                foreach ($bundlesWithLoc as $idx => $b) {
                    $legDuration = $etaResult['legs'][$idx] ?? 0;
                    $cumulative += $legDuration;
                    $estAt = $now->copy()->addMinutes(round($cumulative));
                    $estimatedAtByBundle[$b['bundle_key']] = $estAt;
                    $cumulative += $stopBufferMinutes;
                }
                // Total duration BEFORE the synthetic return leg —
                // existing callers expect this to mean "time to last
                // customer", not "time to back at base".
                $totalDuration = round($cumulative);
                // Return-to-base leg = the leg AFTER the last customer.
                // legs array length is (waypoints - 1); the last leg
                // is from last_customer → qBase. We don't add the 5min
                // stop buffer here because the rider isn't "stopping"
                // at base in the same sense.
                if ($appendBase) {
                    $returnLegIdx = count($bundlesWithLoc); // = legs index for last_customer→base
                    $returnLegMin = $etaResult['legs'][$returnLegIdx] ?? 0;
                    if ($returnLegMin > 0) {
                        // ETA at base = ETA at last customer + return-leg minutes.
                        // We can't reuse $cumulative directly because it
                        // already added the stop buffer for the last
                        // customer; subtract that buffer back out.
                        $cumulativeAtLast = $cumulative - $stopBufferMinutes;
                        $eta = $now->copy()->addMinutes(round($cumulativeAtLast + $returnLegMin));
                        $returnToBase = [
                            'base_name'        => (string) $qBase->location_name,
                            'base_lat'         => (float) $qBase->latitude,
                            'base_lng'         => (float) $qBase->longitude,
                            'return_minutes'   => (int) round($returnLegMin),
                            'estimated_at'     => $eta->toIso8601String(),
                            'estimated_at_iso' => $eta->toIso8601String(),
                        ];
                        // May-2026 — Persist for the manager dashboards
                        // (mobile QurbaniRidersScreen + web /qurbani/riders)
                        // and for /my-deliveries reloads. See helper docs.
                        $this->cacheQurbaniReturnToBase((int) $riderId, $returnToBase);
                    }
                }
            }

            // Persist ETAs (and on 'pending' also dispatched_at) on every
            // line item in each OFD bundle. Already-delivered items are
            // filtered out above.
            $dispatchedAt = now();
            // Rider's Start Delivery is always 'pending' target — that
            // first press is what stamps started_delivery_at.
            $startedAt = ($target === 'pending' && $isOwnRoute) ? $dispatchedAt : null;
            $itemsTouched = 0;
            foreach ($ofdBundles as $b) {
                $itemIds = array_map(fn($it) => $it['id'], $b['items']);
                if (empty($itemIds)) continue;
                $estAt = $estimatedAtByBundle[$b['bundle_key']] ?? null;

                $update = [
                    'updated_at' => now(),
                ];
                // Only stamp dispatched_at on a fresh dispatch — refresh
                // preserves the original dispatch event.
                if ($target === 'pending') {
                    $update['qurbani_dispatched_at'] = $dispatchedAt;
                    $update['qurbani_dispatched_by'] = $user->id;
                    // Reset Live ETA tracking on every fresh dispatch so a
                    // toggle from a previous trip doesn't silently bleed
                    // into the next one. Manager / rider opts in again.
                    $update['qurbani_live_tracking_enabled'] = 0;
                }
                if ($estAt) {
                    $update['qurbani_estimated_delivery_at'] = $estAt;
                    $update['qurbani_eta_calculated_at'] = $dispatchedAt;
                }
                if ($startedAt) {
                    // COALESCE so we record only the FIRST time the
                    // rider started — repeat-presses don't reset it.
                    $update['qurbani_started_delivery_at'] = \DB::raw(
                        "COALESCE(qurbani_started_delivery_at, '" . $startedAt->toDateTimeString() . "')"
                    );
                }

                $itemsTouched += \DB::table('t_crm_prod_order_line_item')
                    ->whereIn('id', $itemIds)
                    ->where('qurbani_assigned_rider_user_id', $riderId)
                    ->update($update);
            }

            \DB::commit();

            \Log::info('Qurbani route ' . ($isRefresh ? 'ETAs refreshed' : 'dispatched'), [
                'rider_id' => $riderId,
                'target' => $target,
                'dispatched_by' => $user->id,
                'is_own_route' => $isOwnRoute,
                'bundles' => count($ofdBundles),
                'items_touched' => $itemsTouched,
                'total_duration_minutes' => $totalDuration,
                'origin_source' => $origin['source'],
                'return_to_base' => $returnToBase ? $returnToBase['return_minutes'] : null,
            ]);

            if ($target === 'refresh') {
                $msg = "ETAs refreshed for " . count($ofdBundles) . ' dispatched bundle(s).';
            } elseif ($target === 'refresh-self') {
                $msg = "ETAs auto-refreshed for " . count($ofdBundles) . ' bundle(s).';
            } elseif ($isOwnRoute) {
                $msg = 'Delivery started — ETAs computed.';
            } else {
                $msg = "Dispatched {$itemsTouched} items across " . count($ofdBundles) . ' bundles.';
            }

            $response = [
                'success' => true,
                'target' => $target,
                'message' => $msg,
                'bundles_count' => count($ofdBundles),
                'items_touched' => $itemsTouched,
                'total_duration_minutes' => $totalDuration,
                'dispatched_at' => $target === 'pending' ? $dispatchedAt->toIso8601String() : null,
                'dispatched_by' => $target === 'pending' ? $user->id : null,
                'dispatched_by_name' => $target === 'pending' ? $user->fullname : null,
                'is_own_route' => $isOwnRoute,
                'started_delivery_at' => $startedAt ? $startedAt->toIso8601String() : null,
                'no_location_bundles' => array_map(function ($b) {
                    return $b['order_number'] . ' (' . $b['customer_name'] . ')';
                }, $bundlesNoLoc),
                // Phase A — origin metadata (always returned).
                'origin_source'       => $origin['source'],
                'origin_source_label' => $origin['source_label'],
                // Phase B — return-to-base ETA (null if no Qurbani base configured).
                'return_to_base' => $returnToBase,
                // For rider auto-refresh — caller can show "ETA refreshed N min ago".
                'eta_calculated_at' => $isRefresh ? $dispatchedAt->toIso8601String() : null,
            ];
            if ($usedShopLocation) {
                $response['gps_warning'] = 'Rider GPS not active — ETAs computed from ' . $origin['source_label'] . '.';
            }
            return response()->json($response);
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Qurbani dispatch failed', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * POST /rider/qurbani/riders/{riderId}/cancel-dispatch
     * Body: { batch_dispatched_at?: 'YYYY-MM-DD HH:MM:SS' }
     *
     * May-2026 — handover support. Releases UNDELIVERED line items
     * from an active dispatch back to "pending" so they can be
     * re-dispatched (either by the same rider after a vehicle fix,
     * or by a different rider after the manager reassigns).
     *
     * What gets cleared on each affected line item:
     *   qurbani_dispatched_at, qurbani_dispatched_by,
     *   qurbani_estimated_delivery_at, qurbani_eta_calculated_at,
     *   qurbani_live_tracking_enabled, qurbani_started_delivery_at
     *
     * What is intentionally NOT changed:
     *   - qurbani_item_status (e.g. 'slaughtered' / 'out_for_delivery')
     *     — orthogonal to dispatch state, set by separate flows.
     *   - qurbani_assigned_rider_user_id — the manager reassigns
     *     separately via the bulk-rider flow if a different rider
     *     should take over. By default the same rider keeps the
     *     items so cancel + immediate re-dispatch "just works".
     *   - qurbani_delivered_at / qurbani_delivered_by — already-
     *     delivered items are filtered out and stay intact.
     *   - t_ops_qurbani_wa_log rows — customers who already received
     *     an OFD WhatsApp keep that record. If the re-dispatch's
     *     fresh ETA differs by more than the configured threshold,
     *     the existing delay-update banner picks them up so the
     *     customer is updated without spamming.
     *
     * batch_dispatched_at (optional): when supplied, only items in
     * that specific wave are cancelled. Matched with a 1-second
     * window in case the client rounded the timestamp. When
     * omitted, ALL active waves for the rider are cancelled.
     *
     * Permissions: manager (access_qurbani_mode) OR rider on own
     * route. Refuses if the route is locked by someone else (same
     * gate as saveQurbaniRoute) so a phone with a stale screen
     * can't kill a run the manager is actively rearranging.
     */
    public function cancelQurbaniDispatch(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwnRoute = ((int) $user->id === (int) $riderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $rider = \DB::table('t_sys_user')
                ->where('id', $riderId)
                ->where('is_active', 1)
                ->select('id', 'fullname')
                ->first();
            if (!$rider) {
                return response()->json(['success' => false, 'message' => 'Rider not found'], 404);
            }

            // Lock gate — mirrors saveQurbaniRoute / dispatchQurbaniRoute.
            $lock = $this->getQurbaniRouteLockInfo($riderId);
            if ($lock && (int) $lock['locked_by'] !== (int) $user->id) {
                return response()->json([
                    'success' => false,
                    'message' => 'Route is locked by ' . ($lock['locked_by_name'] ?? 'another user') . '. Ask them to unlock first.',
                ], 423);
            }

            $batchAtRaw = $request->input('batch_dispatched_at');
            $batchStart = null;
            $batchEnd = null;
            if ($batchAtRaw) {
                try {
                    $parsed = \Carbon\Carbon::parse($batchAtRaw);
                    // ±1s window so a client that truncated millis still
                    // matches the canonical server-side dispatched_at.
                    $batchStart = $parsed->copy()->subSecond();
                    $batchEnd = $parsed->copy()->addSecond();
                } catch (\Throwable $e) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Invalid batch_dispatched_at — expected ISO 8601 or YYYY-MM-DD HH:MM:SS.',
                    ], 422);
                }
            }

            \DB::beginTransaction();

            $base = \DB::table('t_crm_prod_order_line_item as li')
                ->where('li.qurbani_assigned_rider_user_id', $riderId)
                ->whereNotNull('li.qurbani_dispatched_at')
                ->whereNull('li.qurbani_delivered_at');
            if ($batchStart && $batchEnd) {
                $base->whereBetween('li.qurbani_dispatched_at', [$batchStart, $batchEnd]);
            }

            // Snapshot affected rows for audit + UI feedback.
            // May-2026 fix — customer link goes through the ORDER,
            // not the line item (t_crm_prod_order_line_item has no
            // customer_id column). And t_crm_prod_customer has
            // first_name + last_name, not fullname — fullname only
            // lives on t_sys_user (rider). Both bugs caused the
            // "c.fullname unknown column" SQL error users hit when
            // pressing Cancel Dispatch.
            $rows = (clone $base)
                ->leftJoin('t_crm_prod_order as o', 'o.id', '=', 'li.order_id')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->select(
                    'li.id',
                    'li.order_id',
                    'o.order_number',
                    \DB::raw("TRIM(CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,''))) as customer_name"),
                    'li.qurbani_dispatched_at',
                    'li.qurbani_estimated_delivery_at',
                    'li.qurbani_started_delivery_at'
                )
                ->get();

            if ($rows->isEmpty()) {
                \DB::rollBack();
                return response()->json([
                    'success' => false,
                    'message' => $batchAtRaw
                        ? 'No undelivered items found in that dispatch — it may have already been cancelled or fully delivered.'
                        : 'No active dispatch to cancel for ' . $rider->fullname . '.',
                ], 400);
            }

            $itemsTouched = (clone $base)->update([
                'qurbani_dispatched_at'         => null,
                'qurbani_dispatched_by'         => null,
                'qurbani_estimated_delivery_at' => null,
                'qurbani_eta_calculated_at'     => null,
                'qurbani_live_tracking_enabled' => 0,
                'qurbani_started_delivery_at'   => null,
                'updated_at'                    => now(),
            ]);

            \DB::commit();

            // May-2026 — RTB cache invalidation. If the rider has NO
            // remaining dispatched-undelivered items after this cancel,
            // forget the back-to-base estimate so the dashboard chip
            // disappears immediately. When a single batch is cancelled
            // but other batches remain dispatched we deliberately
            // leave the cache alone — those other ETAs are still valid
            // and the RTB chip represents the most recent dispatch.
            $stillDispatched = \DB::table('t_crm_prod_order_line_item')
                ->where('qurbani_assigned_rider_user_id', $riderId)
                ->whereNotNull('qurbani_dispatched_at')
                ->whereNull('qurbani_delivered_at')
                ->count();
            if ($stillDispatched === 0) {
                $this->forgetCachedQurbaniReturnToBase((int) $riderId);
            }

            // Group by order for a friendlier response payload that
            // the mobile UI can render in a confirmation toast.
            $byOrder = [];
            foreach ($rows as $r) {
                $key = $r->order_id;
                if (!isset($byOrder[$key])) {
                    $byOrder[$key] = [
                        'order_id'      => (int) $r->order_id,
                        'order_number'  => $r->order_number,
                        'customer_name' => $r->customer_name,
                        'items'         => 0,
                    ];
                }
                $byOrder[$key]['items']++;
            }
            $ordersReleased = array_values($byOrder);

            \Log::info('Qurbani dispatch cancelled', [
                'rider_id'            => $riderId,
                'rider_name'          => $rider->fullname,
                'cancelled_by'        => $user->id,
                'cancelled_by_name'   => $user->fullname,
                'is_own_route'        => $isOwnRoute,
                'batch_dispatched_at' => $batchAtRaw,
                'items_touched'       => $itemsTouched,
                'orders_affected'     => array_column($ordersReleased, 'order_number'),
            ]);

            return response()->json([
                'success'             => true,
                'message'             => 'Released ' . $itemsTouched . ' undelivered item(s) across '
                    . count($ordersReleased) . ' order(s). They are now pending and can be re-dispatched.',
                'items_touched'       => $itemsTouched,
                'orders_released'     => $ordersReleased,
                'batch_dispatched_at' => $batchAtRaw,
                'rider_id'            => (int) $riderId,
                'rider_name'          => $rider->fullname,
            ]);
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Qurbani dispatch cancel failed', [
                'rider_id' => $riderId,
                'error'    => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Qurbani rider hand-over picker source (May-2026).
     *
     * GET /api/rider/qurbani/handover-riders
     *
     * Returns the Qurbani-whitelisted active riders (same list the
     * manager uses in QurbaniOpenOrdersScreen's bulk-rider picker via
     * /store/riders?mode=qurbani) but WITHOUT the `assign_riders`
     * permission gate so a regular rider can use it to hand work off
     * to another rider mid-route.
     *
     * The whitelist source is the same config key (`qurbani_rider_ids`)
     * the manager maintains in Qurbani Settings — keeping ONE source
     * of truth so adding/removing a rider in settings instantly
     * flows through to every picker in the app.
     *
     * Response also annotates each rider with their current dispatch
     * state (`has_active_dispatch` + `last_dispatched_at`) so the
     * client can show "🟢 Currently delivering" vs "⚪ Idle" hints
     * — helps the caller pick a target with capacity.
     */
    public function getQurbaniHandoverRiders(Request $request)
    {
        try {
            $user = Auth::user();
            // Auth-only gate. The endpoint hands BACK a name list,
            // never mutates anything — and the actual reassignment
            // endpoint enforces its own own-or-manager check, so a
            // leaked rider list is no worse than today's /qurbani/riders
            // summary (which has the same names visible to all
            // managers). Riders need this without `assign_riders`.

            // Same shape as getActiveRiders(mode=qurbani) so the mobile
            // picker can render rows without a second adapter.
            $riders = \DB::table('t_sys_user as u')
                ->leftJoin('t_ops_rider_profile as p', 'p.user_id', '=', 'u.id')
                ->where(function ($q) {
                    $q->whereNull('p.user_id')->orWhere('p.active', 1);
                })
                ->where('u.is_active', 1)
                ->orderBy('u.fullname')
                ->get(['u.id', 'u.fullname']);

            $whitelistApplied = false;
            $raw = (string) \App\Models\FIN\ConfigModel::get('qurbani_rider_ids', '[]');
            $ids = json_decode($raw, true);
            if (is_array($ids)) {
                $ids = array_values(array_filter(array_map('intval', $ids), fn($v) => $v > 0));
                if (!empty($ids)) {
                    $filtered = $riders->filter(fn($r) => in_array((int) $r->id, $ids, true))->values();
                    // Defensive empty-whitelist fallback (matches
                    // getActiveRiders behaviour) so a misconfigured
                    // setting doesn't silently kill the picker.
                    if ($filtered->count() > 0) {
                        $riders = $filtered;
                        $whitelistApplied = true;
                    }
                }
            }

            // Annotate each rider with dispatch state so the caller can
            // hint the operator about target capacity. One round-trip
            // groupBy — no N+1.
            $riderIds = $riders->pluck('id')->all();
            $dispatchByRider = [];
            if (!empty($riderIds)) {
                $rows = \DB::table('t_crm_prod_order_line_item')
                    ->whereIn('qurbani_assigned_rider_user_id', $riderIds)
                    ->select(
                        'qurbani_assigned_rider_user_id as rider_id',
                        \DB::raw('MAX(qurbani_dispatched_at) as last_dispatched_at'),
                        \DB::raw("SUM(CASE WHEN qurbani_dispatched_at IS NOT NULL AND qurbani_delivered_at IS NULL THEN 1 ELSE 0 END) as in_flight_items"),
                        \DB::raw("SUM(CASE WHEN qurbani_item_status='out_for_delivery' AND qurbani_dispatched_at IS NULL AND qurbani_delivered_at IS NULL THEN 1 ELSE 0 END) as pending_items")
                    )
                    ->groupBy('qurbani_assigned_rider_user_id')
                    ->get();
                foreach ($rows as $row) {
                    $dispatchByRider[(int) $row->rider_id] = $row;
                }
            }

            // May-2026 — Same per-rider meta enrichment as the manager
            // /store/riders?mode=qurbani endpoint so the handover
            // picker can show region/contact next to each name in the
            // same visual style.
            $metaRaw = (string) \App\Models\FIN\ConfigModel::get('qurbani_rider_meta', '{}');
            $metaMap = json_decode($metaRaw, true);
            if (!is_array($metaMap)) { $metaMap = []; }

            $payload = $riders->map(function ($r) use ($dispatchByRider, $metaMap) {
                $d = $dispatchByRider[(int) $r->id] ?? null;
                $inFlight = $d ? (int) $d->in_flight_items : 0;
                $pending  = $d ? (int) $d->pending_items   : 0;
                $key = (string) $r->id;
                $m = isset($metaMap[$key]) && is_array($metaMap[$key]) ? $metaMap[$key] : null;
                return [
                    'id'                  => (int) $r->id,
                    'fullname'            => $r->fullname,
                    'qurbani_region'      => $m ? (string) ($m['region']  ?? '') : '',
                    'qurbani_contact'     => $m ? (string) ($m['contact'] ?? '') : '',
                    'has_active_dispatch' => $inFlight > 0,
                    'in_flight_items'     => $inFlight,
                    'pending_items'       => $pending,
                    'last_dispatched_at'  => $d->last_dispatched_at ?? null,
                ];
            })->values();

            return response()->json([
                'success'   => true,
                'riders'    => $payload,
                'whitelist' => $whitelistApplied,
            ]);
        } catch (\Exception $e) {
            \Log::error('getQurbaniHandoverRiders failed', [
                'user_id' => Auth::id(),
                'error'   => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Qurbani hand-over (May-2026) — reassign a SUBSET of a rider's
     * pending OFD items to a different rider.
     *
     * POST /api/rider/qurbani/riders/{fromRiderId}/handover
     *
     * Body:
     *   line_item_ids: int[]              (REQUIRED, ≥1)
     *   to_rider_user_id: int             (REQUIRED, must be active + different from fromRiderId)
     *
     * Permission: own route OR access_qurbani_mode (manager).
     *
     * Guards (every item MUST pass — partial-success rejects with the
     * exact reasons so the client can show a useful error):
     *   - item belongs to fromRiderId (qurbani_assigned_rider_user_id matches)
     *   - qurbani_item_status = 'out_for_delivery'  (assigned for delivery)
     *   - qurbani_dispatched_at IS NULL             (NOT yet dispatched — frozen waves are off-limits)
     *   - qurbani_delivered_at  IS NULL             (defensive)
     *
     * Side effects per item:
     *   - qurbani_assigned_rider_user_id → toRiderId
     *   - qurbani_delivery_priority      → NULL   (old rider's sequence
     *                                              doesn't apply; new rider
     *                                              will resequence with Auto
     *                                              Route or manual move)
     *   - updated_by, updated_at         → caller, now
     *
     * Things we DELIBERATELY do NOT touch:
     *   - qurbani_dispatched_at / qurbani_dispatched_by   (already NULL by guard)
     *   - qurbani_estimated_delivery_at / *_eta_*         (already NULL since not dispatched)
     *   - qurbani_started_delivery_at                     (already NULL)
     *   - qurbani_item_status                             (stays 'out_for_delivery'
     *                                                      so the new rider sees them
     *                                                      in his pending OFD pool)
     *
     * Lock interaction: same gate as cancel-dispatch / save-route — if
     * fromRider's route is locked by someone OTHER than the caller, we
     * refuse. The TARGET rider's lock is irrelevant: we're not editing
     * his frozen sequence, just adding to his pending pool.
     *
     * Response includes a per-order breakdown plus the target rider's
     * current dispatch state, so the mobile client can phrase the
     * confirmation correctly ("Queued for next dispatch" vs "Added to
     * pending pool").
     */
    public function handoverQurbaniItems(Request $request, $fromRiderId)
    {
        try {
            $user = Auth::user();
            $fromRiderId = (int) $fromRiderId;
            $isOwnRoute = ((int) $user->id === $fromRiderId);
            if (!$isOwnRoute && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $validated = $request->validate([
                'line_item_ids'    => 'required|array|min:1',
                'line_item_ids.*'  => 'required|integer',
                'to_rider_user_id' => 'required|integer|exists:t_sys_user,id',
            ]);

            $toRiderId = (int) $validated['to_rider_user_id'];
            $itemIds   = array_values(array_unique(array_map('intval', $validated['line_item_ids'])));

            if ($toRiderId === $fromRiderId) {
                return response()->json([
                    'success' => false,
                    'message' => 'Source and target riders are the same — nothing to hand over.',
                ], 422);
            }

            // Validate both riders.
            $fromRider = \DB::table('t_sys_user')
                ->where('id', $fromRiderId)->where('is_active', 1)
                ->select('id', 'fullname')->first();
            if (!$fromRider) {
                return response()->json(['success' => false, 'message' => 'Source rider not found or inactive'], 404);
            }
            $toRider = \DB::table('t_sys_user')
                ->where('id', $toRiderId)->where('is_active', 1)
                ->select('id', 'fullname')->first();
            if (!$toRider) {
                return response()->json(['success' => false, 'message' => 'Target rider not found or inactive'], 404);
            }

            // Lock gate — mirror save/dispatch/cancel. Only fromRider's
            // route lock matters; we're not mutating toRider's frozen
            // sequence (we only touch his pending pool, which has no
            // saved order yet).
            $lock = $this->getQurbaniRouteLockInfo($fromRiderId);
            if ($lock && (int) $lock['locked_by'] !== (int) $user->id) {
                return response()->json([
                    'success' => false,
                    'message' => 'Source rider\'s route is locked by ' . ($lock['locked_by_name'] ?? 'another user') . '. Ask them to unlock first.',
                ], 423);
            }

            \DB::beginTransaction();

            // Snapshot every requested item with the columns needed to
            // both check guards AND build a friendly per-order audit
            // payload. Single query, no N+1.
            $snapshot = \DB::table('t_crm_prod_order_line_item as li')
                ->leftJoin('t_crm_prod_order as o', 'o.id', '=', 'li.order_id')
                ->leftJoin('t_crm_prod_customer as c', 'c.id', '=', 'o.customer_id')
                ->whereIn('li.id', $itemIds)
                ->select(
                    'li.id',
                    'li.order_id',
                    'o.order_number',
                    'li.qurbani_assigned_rider_user_id',
                    'li.qurbani_item_status',
                    'li.qurbani_dispatched_at',
                    'li.qurbani_delivered_at',
                    \DB::raw("TRIM(CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,''))) as customer_name")
                )
                ->get();

            // Per-item guard pass — collect blockers in one go so we
            // can return a structured rejection rather than silently
            // skipping bad items. Partial-success would let bad UX
            // creep in (rider thinks all 5 were handed over when only
            // 3 actually moved).
            $blockers = [];
            $okIds    = [];
            $foundIds = $snapshot->pluck('id')->map(fn($v) => (int) $v)->all();
            foreach ($itemIds as $iid) {
                if (!in_array($iid, $foundIds, true)) {
                    $blockers[] = "Item #{$iid}: not found";
                }
            }
            foreach ($snapshot as $r) {
                $reasons = [];
                if ((int) $r->qurbani_assigned_rider_user_id !== $fromRiderId) {
                    $reasons[] = 'belongs to a different rider';
                }
                if (($r->qurbani_item_status ?? null) !== 'out_for_delivery') {
                    $reasons[] = 'not Out for Delivery';
                }
                if (!empty($r->qurbani_dispatched_at)) {
                    $reasons[] = 'already dispatched (must be cancelled first)';
                }
                if (!empty($r->qurbani_delivered_at)) {
                    $reasons[] = 'already delivered';
                }
                if (!empty($reasons)) {
                    $label = $r->order_number ?: ('item #' . $r->id);
                    $blockers[] = "{$label}: " . implode(', ', $reasons);
                } else {
                    $okIds[] = (int) $r->id;
                }
            }
            if (!empty($blockers)) {
                \DB::rollBack();
                return response()->json([
                    'success'  => false,
                    'message'  => 'Cannot hand over — ' . count($blockers) . ' item(s) failed checks. ' . implode(' · ', array_slice($blockers, 0, 5)) . (count($blockers) > 5 ? ' …' : ''),
                    'blockers' => $blockers,
                ], 422);
            }

            // All clear — apply the reassignment.
            //   - rider: pointed at the target
            //   - delivery_priority: cleared (target will re-sequence)
            //   - updated_*: caller stamp
            // We DO NOT touch dispatched_at / eta / item_status — guards
            // already proved they're null / OFD, and the new rider's
            // route screen will surface these as pending items ready
            // for his next Auto Route press.
            $updated = \App\Models\CRM\OrderLineItemModel::whereIn('id', $okIds)
                ->update([
                    'qurbani_assigned_rider_user_id' => $toRiderId,
                    'qurbani_delivery_priority'      => null,
                    'updated_by'                     => $user->id,
                    'updated_at'                     => now(),
                ]);

            \DB::commit();

            // Build per-order grouping for the response toast.
            $byOrder = [];
            foreach ($snapshot->whereIn('id', $okIds) as $r) {
                $key = (int) $r->order_id;
                if (!isset($byOrder[$key])) {
                    $byOrder[$key] = [
                        'order_id'      => $key,
                        'order_number'  => $r->order_number,
                        'customer_name' => $r->customer_name,
                        'items'         => 0,
                    ];
                }
                $byOrder[$key]['items']++;
            }
            $ordersAffected = array_values($byOrder);

            // Compute target's current dispatch state so the client can
            // phrase the confirmation right.
            $toRiderInFlight = (int) \DB::table('t_crm_prod_order_line_item')
                ->where('qurbani_assigned_rider_user_id', $toRiderId)
                ->whereNotNull('qurbani_dispatched_at')
                ->whereNull('qurbani_delivered_at')
                ->count();

            \Log::info('Qurbani items handed over', [
                'from_rider_id'    => $fromRiderId,
                'from_rider_name'  => $fromRider->fullname,
                'to_rider_id'      => $toRiderId,
                'to_rider_name'    => $toRider->fullname,
                'caller_user_id'   => $user->id,
                'caller_user_name' => $user->fullname,
                'is_own_route'     => $isOwnRoute,
                'items_count'      => $updated,
                'item_ids'         => $okIds,
                'orders_affected'  => array_column($ordersAffected, 'order_number'),
                'target_in_flight' => $toRiderInFlight,
            ]);

            $queuedHint = $toRiderInFlight > 0
                ? "Queued for {$toRider->fullname}'s next dispatch (they have {$toRiderInFlight} item(s) currently in-flight)."
                : "Added to {$toRider->fullname}'s pending pool — ready for Auto Route + Dispatch.";

            return response()->json([
                'success'            => true,
                'message'            => 'Handed over ' . $updated . ' item(s) across ' . count($ordersAffected) . ' order(s) from ' . $fromRider->fullname . ' to ' . $toRider->fullname . '. ' . $queuedHint,
                'items_count'        => $updated,
                'item_ids'           => $okIds,
                'orders_affected'    => $ordersAffected,
                'from_rider_id'      => $fromRiderId,
                'from_rider_name'    => $fromRider->fullname,
                'to_rider_id'        => $toRiderId,
                'to_rider_name'      => $toRider->fullname,
                'target_in_flight'   => $toRiderInFlight,
                'target_has_active_dispatch' => $toRiderInFlight > 0,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Exception $e) {
            \DB::rollBack();
            \Log::error('Qurbani handover failed', [
                'from_rider_id' => $fromRiderId,
                'error'         => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * Internal Qurbani ETA recompute (May-2026 revision).
     *
     * Server-initiated cousin of dispatchQurbaniRoute(target='refresh').
     * Used when delay detection fires after a delivery completion, or
     * when planner / summary endpoints notice the earliest pending ETA
     * has slipped past the configured threshold. Distinct from the
     * rider-driven 'refresh-self' so we can:
     *   - run even when rider GPS is stale (we WANT to react when the
     *     rider's phone is dead but the dispatcher knows things are late)
     *   - charge against the same 1/min/rider rate-limit cache so the
     *     three triggers (delay-on-delivery, passive late-detect, rider
     *     auto-refresh) can never combined-overload Google
     *   - ignore master-switch=disabled (delay detection is admin-driven
     *     ground truth, not a rider convenience). Callers gate this
     *     themselves when needed.
     *
     * Returns an array with shape:
     *   ['action' => 'updated' | 'skipped' | 'failed',
     *    'reason' => string|null, 'updated' => int]
     *
     * Never throws — failures are logged and reported via 'failed'.
     */
    private function recomputeQurbaniEtasInternal(int $riderId, int $userId, string $reason): array
    {
        try {
            // Same rate-limit cache key as the rider-driven path so all
            // three triggers share the 1/min/rider budget.
            $rlKey = 'qurbani_eta_refresh_self_' . $riderId;
            if (\Cache::has($rlKey)) {
                return ['action' => 'skipped', 'reason' => 'rate_limited', 'updated' => 0];
            }

            // Origin lookup with the GENEROUS 30-min freshness window —
            // the manager-side trigger needs to work when rider GPS is
            // briefly stale (battery dip, app backgrounded). If even
            // the office is unavailable we bail.
            $origin = \App\Services\LocationService::getQurbaniOriginForRider($riderId, 30);
            if (!$origin) {
                return ['action' => 'skipped', 'reason' => 'no_origin', 'updated' => 0];
            }

            // Pull the rider's currently-dispatched, undelivered bundles.
            $route = $this->buildQurbaniRiderRoute($riderId, 'open');
            $ofdBundles = array_values(array_filter($route['bundles'], function ($b) {
                if (($b['bundle_status'] ?? '') !== 'out_for_delivery') return false;
                return ($b['bundle_dispatch_status'] ?? '') === 'dispatched';
            }));
            if (empty($ofdBundles)) {
                return ['action' => 'skipped', 'reason' => 'no_dispatched_bundles', 'updated' => 0];
            }

            // Build waypoints (origin + each bundle with location). Skip
            // bundles without coords as elsewhere — their ETAs stay null.
            $waypoints = [['lat' => (float) $origin['latitude'], 'lng' => (float) $origin['longitude']]];
            $bundlesWithLoc = [];
            foreach ($ofdBundles as $b) {
                if ($b['cust_lat'] && $b['cust_lng']) {
                    $waypoints[] = ['lat' => (float) $b['cust_lat'], 'lng' => (float) $b['cust_lng']];
                    $bundlesWithLoc[] = $b;
                }
            }
            if (count($bundlesWithLoc) === 0) {
                return ['action' => 'skipped', 'reason' => 'no_geo_bundles', 'updated' => 0];
            }

            $etaResult = $this->getMultiStopEtaFromGoogle($waypoints);
            if (!$etaResult) {
                return ['action' => 'failed', 'reason' => 'google_directions_error', 'updated' => 0];
            }

            // Burn the rate-limit AFTER we know we'll actually mutate
            // data — failed Google calls shouldn't lock the next try.
            \Cache::put($rlKey, 1, 60);

            $stopBufferMinutes = 5;
            $cumulative = 0;
            $now = now();
            $estimatedAtByBundle = [];
            foreach ($bundlesWithLoc as $idx => $b) {
                $legDuration = $etaResult['legs'][$idx] ?? 0;
                $cumulative += $legDuration;
                $estimatedAtByBundle[$b['bundle_key']] = $now->copy()->addMinutes(round($cumulative));
                $cumulative += $stopBufferMinutes;
            }

            $itemsTouched = 0;
            foreach ($bundlesWithLoc as $b) {
                $itemIds = array_map(fn($it) => $it['id'], $b['items']);
                if (empty($itemIds)) continue;
                $itemsTouched += \DB::table('t_crm_prod_order_line_item')
                    ->whereIn('id', $itemIds)
                    ->where('qurbani_assigned_rider_user_id', $riderId)
                    ->update([
                        'qurbani_estimated_delivery_at' => $estimatedAtByBundle[$b['bundle_key']],
                        'qurbani_eta_calculated_at'     => $now,
                        'updated_at'                    => $now,
                    ]);
            }

            \Log::info('Qurbani ETA auto-recompute', [
                'rider_id'      => $riderId,
                'reason'        => $reason,
                'origin_source' => $origin['source'],
                'bundles'       => count($bundlesWithLoc),
                'items_touched' => $itemsTouched,
                'triggered_by'  => $userId,
            ]);

            return ['action' => 'updated', 'reason' => $reason, 'updated' => $itemsTouched];
        } catch (\Exception $e) {
            \Log::error('Qurbani ETA auto-recompute failed', [
                'rider_id' => $riderId,
                'reason'   => $reason,
                'error'    => $e->getMessage(),
            ]);
            return ['action' => 'failed', 'reason' => 'exception', 'updated' => 0];
        }
    }

    /**
     * Detect ETA-vs-delivered slip on a freshly-delivered batch and,
     * if any rider's items slipped past the threshold, kick off a
     * single ETA recompute for the rest of that rider's dispatch.
     *
     * Pre-condition: the items have ALREADY been updated to
     * qurbani_item_status='delivered' with qurbani_delivered_at=NOW().
     * We pass the original $items collection (read BEFORE the update)
     * so we still have the OLD qurbani_estimated_delivery_at to compare
     * against — that's the "ETA stored at the time of dispatch" the
     * user described.
     *
     * Returns the per-rider trigger results so callers can surface
     * "ETAs auto-refreshed" toasts to the rider's screen.
     */
    private function maybeRecomputeOnDeliveryDelay($items, int $userId): array
    {
        $thresholdMin = (int) \App\Models\FIN\ConfigModel::get('qurbani_eta_delay_threshold_minutes', '10');
        if ($thresholdMin < 1) $thresholdMin = 10;
        $masterEnabled = \App\Models\FIN\ConfigModel::get('qurbani_eta_refresh_enabled', '1') === '1';
        if (!$masterEnabled) {
            // Admin disabled the whole feature — don't auto-recompute.
            return [];
        }

        $now = now();
        $delayedRiders = [];
        $delayDetails = [];
        foreach ($items as $li) {
            $eta = $li->qurbani_estimated_delivery_at ?? null;
            $rider = (int) ($li->qurbani_assigned_rider_user_id ?? 0);
            if (!$eta || !$rider) continue;
            try {
                $etaCarbon = \Carbon\Carbon::parse($eta);
                $slipMinutes = $etaCarbon->diffInMinutes($now, false); // signed: positive when now > eta
                if ($slipMinutes > $thresholdMin) {
                    $delayedRiders[$rider] = true;
                    $delayDetails[] = [
                        'line_item_id' => $li->id,
                        'rider_id'     => $rider,
                        'slip_minutes' => (int) $slipMinutes,
                    ];
                }
            } catch (\Exception $e) {
                // Ignore malformed timestamps.
            }
        }

        if (empty($delayedRiders)) {
            return [];
        }

        // One recompute per rider — even if 5 of their bundles slipped
        // we only recompute the route once.
        $results = [];
        foreach (array_keys($delayedRiders) as $riderId) {
            $r = $this->recomputeQurbaniEtasInternal((int) $riderId, $userId, 'delivery_delay');
            $r['rider_id'] = (int) $riderId;
            $results[] = $r;
        }

        \Log::info('Qurbani delay-trigger recompute', [
            'threshold_min' => $thresholdMin,
            'delayed_items' => $delayDetails,
            'results'       => $results,
        ]);
        return $results;
    }

    /**
     * POST /rider/qurbani/riders/{riderId}/live-tracking
     * Body: { enabled: bool }
     *
     * Phase 1 (May-2026) — toggle the per-dispatch Live ETA tracking
     * flag. Either the manager (with access_qurbani_mode) or the rider
     * themselves can flip it. The flag is stored on every dispatched
     * line item assigned to this rider and is reset to 0 every time
     * a fresh dispatch is pressed (see dispatchQurbaniRoute,
     * target='pending').
     *
     * When ON, the rider app's auto-refresh loop wakes up every
     * qurbani_eta_refresh_minutes (default 3) and calls dispatchQurbaniRoute
     * with target='refresh-self', recomputing ETAs from current GPS.
     * The shared 1-min/rider rate limit in recomputeQurbaniEtasInternal
     * still applies — if delay-detect or passive late-detect fires in
     * the same minute, the auto refresh will no-op silently.
     *
     * Hard requirements:
     *   - Master switch (qurbani_eta_refresh_enabled) must be ON,
     *     otherwise we refuse the toggle entirely (the rider app's
     *     timer also gates on this so it would never fire anyway,
     *     but UX-wise we want a clean error message instead of a
     *     silently-accepted toggle that does nothing).
     *   - The rider must have at least one DISPATCHED, undelivered
     *     bundle; turning it on for a rider with nothing dispatched
     *     is meaningless (and confusing — the next dispatch resets
     *     the flag anyway).
     */
    public function setQurbaniLiveTracking(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            $isOwn = ((int) $user->id === (int) $riderId);
            if (!$isOwn && !$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $enabled = filter_var($request->input('enabled'), FILTER_VALIDATE_BOOLEAN);

            if ($enabled) {
                $masterOn = \App\Models\FIN\ConfigModel::get('qurbani_eta_refresh_enabled', '1') === '1';
                if (!$masterOn) {
                    return response()->json([
                        'success' => false,
                        'message' => 'Live ETA tracking is disabled in Qurbani Settings — ask an admin to enable it.',
                    ], 422);
                }
            }

            // Scope: every line item this rider has that is currently
            // dispatched and not delivered. Same scope as the
            // refresh-self / delay-detect recomputes so the rider's
            // app sees a consistent flag across all dispatched bundles.
            $rowsAffected = \DB::table('t_crm_prod_order_line_item')
                ->where('qurbani_assigned_rider_user_id', $riderId)
                ->whereNotNull('qurbani_dispatched_at')
                ->whereNull('qurbani_delivered_at')
                ->where(function ($q) {
                    $q->whereNull('qurbani_item_status')
                      ->orWhere('qurbani_item_status', '!=', 'delivered');
                })
                ->update([
                    'qurbani_live_tracking_enabled' => $enabled ? 1 : 0,
                    'updated_at' => now(),
                ]);

            if ($rowsAffected === 0) {
                return response()->json([
                    'success' => false,
                    'message' => 'No dispatched undelivered bundles for this rider — toggle is reset on every new dispatch.',
                ], 422);
            }

            \Log::info('Qurbani live tracking toggled', [
                'rider_id'   => (int) $riderId,
                'enabled'    => $enabled,
                'changed_by' => $user->id,
                'is_own'     => $isOwn,
                'rows'       => $rowsAffected,
            ]);

            return response()->json([
                'success' => true,
                'enabled' => $enabled,
                'rider_id' => (int) $riderId,
                'rows_updated' => $rowsAffected,
                'message' => $enabled
                    ? 'Live ETA tracking enabled — rider app will refresh ETAs every few minutes.'
                    : 'Live ETA tracking disabled.',
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to toggle qurbani live tracking', [
                'rider_id' => $riderId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * GET /rider/qurbani/line-items/{lineItemId}/timeline    (mobile)
     * GET /qurbani/api/line-items/{lineItemId}/timeline      (web alias)
     *
     * Phase 2 (May-2026) — Qurbani order timeline. Returns a single
     * snapshot of everything customer-service / dispatch-watchers want
     * to know about a Qurbani line item at a glance:
     *
     *   - Status events reached so far (placed → slaughtered → OFD →
     *     delivered) with timestamps. Only the LATEST status change
     *     has a "by" attribute because qurbani_status_updated_by is
     *     overwritten on each transition.
     *   - Rider name + dispatch event (who dispatched, when, when
     *     the rider actually started the trip).
     *   - Current ETA — single line, not a history. Includes a small
     *     note when qurbani_eta_calculated_at > qurbani_dispatched_at
     *     (i.e. the ETA was refreshed after dispatch).
     *   - Delay alert — fires when ANY prior bundle in the same rider's
     *     dispatch sequence was delivered more than the configured
     *     threshold past its own ETA. Names the slipping prior stop
     *     so the manager knows which delivery threw the schedule off.
     *   - WhatsApp today — just the latest inbound + latest outbound
     *     template message for this customer's conversation since
     *     midnight. No per-order linking; this is for "did we hear
     *     from them today / did we send them anything?" context.
     *
     * Authorisation: any logged-in user with access_qurbani_mode (the
     * timeline shows operational details for managers / customer
     * service, not for riders' own delivery feed).
     */
    public function getQurbaniOrderTimeline(Request $request, $lineItemId)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            // Step 1: fetch the line item + its parent order with
            // customer info. Single row, no joins — keeps this fast.
            $li = \DB::table('t_crm_prod_order_line_item as li')
                ->leftJoin('t_crm_prod_order as o', 'o.id', '=', 'li.order_id')
                ->leftJoin('t_crm_customer as c', 'c.id', '=', 'o.customer_id')
                ->where('li.id', $lineItemId)
                ->select(
                    'li.id', 'li.order_id', 'li.name as item_name', 'li.quantity',
                    'li.qurbani_day', 'li.qurbani_slot',
                    'li.qurbani_slot_start_minute', 'li.qurbani_slot_end_minute',
                    'li.qurbani_region',
                    'li.qurbani_sub_region', 'li.qurbani_delivery_type',
                    'li.qurbani_type', 'li.qurbani_paya', 'li.qurbani_item_status',
                    'li.qurbani_status_updated_at', 'li.qurbani_status_updated_by',
                    'li.qurbani_assigned_rider_user_id',
                    'li.qurbani_dispatched_at', 'li.qurbani_dispatched_by',
                    'li.qurbani_started_delivery_at',
                    'li.qurbani_estimated_delivery_at', 'li.qurbani_eta_calculated_at',
                    'li.qurbani_slaughtered_at', 'li.qurbani_out_for_delivery_at', 'li.qurbani_delivered_at',
                    'li.qurbani_delivery_priority', 'li.created_at as line_created_at',
                    'o.id as order_id_dup', 'o.order_number', 'o.customer_id',
                    'o.created_at as order_created_at',
                    'o.address_first_name', 'o.address_last_name',
                    'o.address_line1', 'o.address_line2', 'o.address_city',
                    'o.name as order_name'
                )
                ->first();

            if (!$li) {
                return response()->json(['success' => false, 'message' => 'Line item not found'], 404);
            }

            // Step 2: resolve all "by" user IDs in one query so we can
            // attach names without N+1 lookups.
            $userIds = array_filter([
                $li->qurbani_status_updated_by,
                $li->qurbani_dispatched_by,
                $li->qurbani_assigned_rider_user_id,
            ]);
            $userMap = [];
            if (!empty($userIds)) {
                $userMap = \DB::table('t_sys_user')
                    ->whereIn('id', array_unique($userIds))
                    ->pluck('fullname', 'id')
                    ->toArray();
            }

            // Step 3: build status events. Include only events that
            // have a timestamp (i.e. that have actually happened).
            // The latest status carries the "by" attribute since
            // qurbani_status_updated_by only stores the most recent
            // transition's actor.
            $currentStatus = strtolower((string) ($li->qurbani_item_status ?? ''));
            $latestActorId = $li->qurbani_status_updated_by;
            $events = [];
            $events[] = [
                'key'   => 'placed',
                'label' => 'Order placed',
                'at'    => $li->order_created_at ? (string) $li->order_created_at : (string) $li->line_created_at,
                'by'    => null,
                'icon'  => '📝',
                'color' => '#6B7280',
            ];
            if ($li->qurbani_slaughtered_at) {
                $events[] = [
                    'key'   => 'slaughtered',
                    'label' => 'Slaughtered',
                    'at'    => (string) $li->qurbani_slaughtered_at,
                    'by'    => $currentStatus === 'slaughtered' && $latestActorId
                        ? ($userMap[$latestActorId] ?? null) : null,
                    'icon'  => '🔪',
                    'color' => '#92400E',
                ];
            }
            if ($li->qurbani_out_for_delivery_at) {
                $events[] = [
                    'key'   => 'ofd',
                    'label' => 'Out for Delivery',
                    'at'    => (string) $li->qurbani_out_for_delivery_at,
                    'by'    => $currentStatus === 'out_for_delivery' && $latestActorId
                        ? ($userMap[$latestActorId] ?? null) : null,
                    'icon'  => '🛵',
                    'color' => '#1E40AF',
                ];
            }
            if ($li->qurbani_delivered_at) {
                $events[] = [
                    'key'   => 'delivered',
                    'label' => 'Delivered',
                    'at'    => (string) $li->qurbani_delivered_at,
                    'by'    => $currentStatus === 'delivered' && $latestActorId
                        ? ($userMap[$latestActorId] ?? null) : null,
                    'icon'  => '✅',
                    'color' => '#065F46',
                ];
            }

            // Step 4: dispatch + rider info. Bundle-shared fields so a
            // single line item is enough.
            $rider = null;
            if ($li->qurbani_assigned_rider_user_id) {
                $rider = [
                    'id'   => (int) $li->qurbani_assigned_rider_user_id,
                    'name' => $userMap[$li->qurbani_assigned_rider_user_id] ?? 'Rider',
                ];
            }
            $dispatch = null;
            if ($li->qurbani_dispatched_at) {
                $dispatch = [
                    'at'         => (string) $li->qurbani_dispatched_at,
                    'by_id'      => $li->qurbani_dispatched_by ? (int) $li->qurbani_dispatched_by : null,
                    'by_name'    => $li->qurbani_dispatched_by
                        ? ($userMap[$li->qurbani_dispatched_by] ?? null) : null,
                    'started_at' => $li->qurbani_started_delivery_at
                        ? (string) $li->qurbani_started_delivery_at : null,
                ];
            }

            // Step 5: current ETA — show ONE line. Note when the ETA
            // was recomputed after dispatch (eta_calculated_at strictly
            // after dispatched_at by more than 1 minute, to ignore
            // the same-second stamp written during the initial
            // dispatch flow).
            $currentEta = null;
            if ($li->qurbani_estimated_delivery_at) {
                $isInitial = true;
                $note = null;
                if ($li->qurbani_dispatched_at && $li->qurbani_eta_calculated_at) {
                    try {
                        $dispAt = \Carbon\Carbon::parse($li->qurbani_dispatched_at);
                        $calcAt = \Carbon\Carbon::parse($li->qurbani_eta_calculated_at);
                        if ($calcAt->gt($dispAt->copy()->addMinute())) {
                            $isInitial = false;
                            $note = 'ETA refreshed after dispatch · last calculated at '
                                . $calcAt->format('H:i');
                        }
                    } catch (\Exception $e) { /* fallthrough */ }
                }
                $currentEta = [
                    'at'             => (string) $li->qurbani_estimated_delivery_at,
                    'calculated_at'  => $li->qurbani_eta_calculated_at
                        ? (string) $li->qurbani_eta_calculated_at : null,
                    'is_initial'     => $isInitial,
                    'note'           => $note,
                ];
            }

            // Step 6: delay alert. Find any prior bundle (lower
            // qurbani_delivery_priority, same rider) that was
            // delivered more than threshold past its own ETA.
            // Only meaningful while the current item is still
            // dispatched & undelivered — once delivered, the alert
            // becomes historical noise.
            $delayAlert = null;
            $thresholdMin = (int) \App\Models\FIN\ConfigModel::get('qurbani_eta_delay_threshold_minutes', '10');
            if ($thresholdMin < 1) $thresholdMin = 10;
            if ($currentStatus !== 'delivered'
                && $li->qurbani_assigned_rider_user_id
                && $li->qurbani_delivery_priority !== null
                && $li->qurbani_dispatched_at) {
                $priorSlips = \DB::table('t_crm_prod_order_line_item as li2')
                    ->leftJoin('t_crm_prod_order as o2', 'o2.id', '=', 'li2.order_id')
                    ->leftJoin('t_crm_customer as c2', 'c2.id', '=', 'o2.customer_id')
                    ->where('li2.qurbani_assigned_rider_user_id', $li->qurbani_assigned_rider_user_id)
                    ->where('li2.qurbani_delivery_priority', '<', $li->qurbani_delivery_priority)
                    ->whereNotNull('li2.qurbani_dispatched_at')
                    ->whereNotNull('li2.qurbani_estimated_delivery_at')
                    ->whereNotNull('li2.qurbani_delivered_at')
                    ->where('li2.qurbani_dispatched_at', '>=', \Carbon\Carbon::parse($li->qurbani_dispatched_at)->subMinutes(5))
                    ->select(
                        'li2.qurbani_estimated_delivery_at',
                        'li2.qurbani_delivered_at',
                        'li2.qurbani_delivery_priority',
                        'o2.name as order_name',
                        'o2.address_first_name', 'o2.address_last_name',
                        'c2.first_name as cust_first_name', 'c2.last_name as cust_last_name'
                    )
                    ->get();

                $worstSlipMin = 0;
                $worstStop = null;
                foreach ($priorSlips as $s) {
                    try {
                        $eta = \Carbon\Carbon::parse($s->qurbani_estimated_delivery_at);
                        $del = \Carbon\Carbon::parse($s->qurbani_delivered_at);
                        $slip = (int) $eta->diffInMinutes($del, false); // positive when delivered AFTER eta
                        if ($slip > $thresholdMin && $slip > $worstSlipMin) {
                            $worstSlipMin = $slip;
                            $worstStop = trim((string) (
                                $s->order_name
                                ?: trim(($s->address_first_name ?? '') . ' ' . ($s->address_last_name ?? ''))
                                ?: trim(($s->cust_first_name ?? '') . ' ' . ($s->cust_last_name ?? ''))
                            )) ?: 'a previous stop';
                        }
                    } catch (\Exception $e) { /* skip malformed */ }
                }

                if ($worstSlipMin > 0) {
                    $delayAlert = [
                        'active'       => true,
                        'slip_minutes' => $worstSlipMin,
                        'prior_stop'   => $worstStop,
                        'reason'       => "Earlier stop ({$worstStop}) delivered {$worstSlipMin} min past its ETA — this delivery may slip too.",
                    ];
                }
            }

            // Step 7: WhatsApp today. Single conversation per customer,
            // we just need the latest inbound + latest outbound from
            // since-midnight (server timezone). No per-order linking.
            $whatsappToday = ['last_inbound' => null, 'last_outbound' => null];
            if ($li->customer_id) {
                $convo = \DB::table('t_wa_conversations')
                    ->where('customer_id', $li->customer_id)
                    ->select('id')
                    ->first();
                if ($convo) {
                    $startOfDay = now()->startOfDay();
                    $msgs = \DB::table('t_wa_messages')
                        ->where('conversation_id', $convo->id)
                        ->where('created_at', '>=', $startOfDay)
                        ->select('id', 'direction', 'type', 'content', 'template_name', 'sent_by', 'created_at')
                        ->orderBy('created_at', 'desc')
                        ->get();

                    $sentByIds = [];
                    foreach ($msgs as $m) {
                        if ($m->direction === 'outbound' && $m->sent_by) $sentByIds[] = $m->sent_by;
                    }
                    $sentByMap = [];
                    if (!empty($sentByIds)) {
                        $sentByMap = \DB::table('t_sys_user')
                            ->whereIn('id', array_unique($sentByIds))
                            ->pluck('fullname', 'id')
                            ->toArray();
                    }

                    foreach ($msgs as $m) {
                        if ($m->direction === 'inbound' && !$whatsappToday['last_inbound']) {
                            $preview = (string) ($m->content ?? '');
                            if (mb_strlen($preview) > 80) $preview = mb_substr($preview, 0, 80) . '…';
                            if ($preview === '' && $m->type) $preview = '[' . strtoupper($m->type) . ']';
                            $whatsappToday['last_inbound'] = [
                                'at'      => (string) $m->created_at,
                                'preview' => $preview,
                                'type'    => $m->type,
                            ];
                        }
                        if ($m->direction === 'outbound' && !$whatsappToday['last_outbound']) {
                            $preview = (string) ($m->content ?? '');
                            if (mb_strlen($preview) > 80) $preview = mb_substr($preview, 0, 80) . '…';
                            if ($preview === '' && $m->template_name) $preview = 'Template: ' . $m->template_name;
                            $whatsappToday['last_outbound'] = [
                                'at'            => (string) $m->created_at,
                                'preview'       => $preview,
                                'type'          => $m->type,
                                'is_template'   => $m->type === 'template',
                                'template_name' => $m->template_name,
                                'by'            => $m->sent_by ? ($sentByMap[$m->sent_by] ?? null) : null,
                            ];
                        }
                        if ($whatsappToday['last_inbound'] && $whatsappToday['last_outbound']) break;
                    }
                }
            }

            // Step 7b (May-2026): route position — how many stops are
            // ahead of THIS line item in the rider's currently-running
            // dispatch. Auto-derived from the live row data (no extra
            // table needed): an "ahead" stop is any line item with the
            // same rider, dispatched, undelivered, and a strictly
            // smaller qurbani_delivery_priority. As the rider delivers
            // each prior stop the row gets stamped with
            // qurbani_delivered_at and drops out of this count, so the
            // number stays self-correcting on every refresh — no extra
            // background job needed (matches the user's "use existing
            // sync" requirement).
            $routePosition = null;
            if ($li->qurbani_assigned_rider_user_id
                && $li->qurbani_dispatched_at
                && $li->qurbani_delivery_priority !== null
                && $currentStatus !== 'delivered'
                && $currentStatus !== 'cancelled') {
                $aheadCount = (int) \DB::table('t_crm_prod_order_line_item')
                    ->where('qurbani_assigned_rider_user_id', $li->qurbani_assigned_rider_user_id)
                    ->whereNotNull('qurbani_dispatched_at')
                    ->whereNull('qurbani_delivered_at')
                    ->where('qurbani_delivery_priority', '<', $li->qurbani_delivery_priority)
                    ->where('id', '!=', $li->id)
                    ->count();
                $totalRemaining = (int) \DB::table('t_crm_prod_order_line_item')
                    ->where('qurbani_assigned_rider_user_id', $li->qurbani_assigned_rider_user_id)
                    ->whereNotNull('qurbani_dispatched_at')
                    ->whereNull('qurbani_delivered_at')
                    ->count();
                if ($aheadCount === 0) {
                    $label = 'Next stop on the route';
                } else {
                    $label = $aheadCount . ' stop' . ($aheadCount === 1 ? '' : 's')
                        . ' ahead in the route';
                }
                $routePosition = [
                    'is_in_dispatch'  => true,
                    'ahead_count'     => $aheadCount,
                    'total_remaining' => $totalRemaining,
                    'priority'        => (int) $li->qurbani_delivery_priority,
                    'label'           => $label,
                ];
            }

            // Step 7c (May-2026) — slot vs ETA / delivered-at compare.
            // Same shape as the cards on /qurbani/orders so the
            // timeline modal can render the same chip without
            // repeating the math client-side.
            $slotCompare = null;
            if ($li->qurbani_slot_end_minute !== null) {
                $grace = (int) \App\Models\FIN\ConfigModel::get('qurbani_late_grace_minutes', '10');
                if ($grace < 0) $grace = 0;
                if ($li->qurbani_delivered_at) {
                    $slotCompare = \App\Services\QurbaniSlotParser::compareEventToSlot(
                        (string) $li->qurbani_delivered_at,
                        (int) $li->qurbani_slot_end_minute,
                        $grace,
                        'delivered'
                    );
                } elseif ($li->qurbani_estimated_delivery_at) {
                    $slotCompare = \App\Services\QurbaniSlotParser::compareEventToSlot(
                        (string) $li->qurbani_estimated_delivery_at,
                        (int) $li->qurbani_slot_end_minute,
                        $grace,
                        'eta'
                    );
                }
            }

            // Step 8: payload. Customer name uses the same fallback
            // chain as the rest of the Qurbani views.
            $customerName = $li->order_name
                ?: trim(($li->address_first_name ?? '') . ' ' . ($li->address_last_name ?? ''));
            if (!$customerName) $customerName = 'Unknown';

            return response()->json([
                'success' => true,
                'order' => [
                    'id'             => (int) $li->order_id,
                    'order_number'   => $li->order_number,
                    'customer_id'    => $li->customer_id ? (int) $li->customer_id : null,
                    'customer_name'  => $customerName,
                    'address'        => trim(implode(', ', array_filter([
                        $li->address_line1, $li->address_line2, $li->address_city,
                    ]))) ?: null,
                ],
                'line_item' => [
                    'id'                       => (int) $li->id,
                    'name'                     => $li->item_name,
                    'quantity'                 => (float) $li->quantity,
                    'qurbani_day'              => $li->qurbani_day,
                    'qurbani_slot'             => $li->qurbani_slot,
                    'qurbani_slot_start_minute'=> $li->qurbani_slot_start_minute !== null ? (int) $li->qurbani_slot_start_minute : null,
                    'qurbani_slot_end_minute'  => $li->qurbani_slot_end_minute   !== null ? (int) $li->qurbani_slot_end_minute   : null,
                    'qurbani_region'           => $li->qurbani_region,
                    'qurbani_sub_region'       => $li->qurbani_sub_region,
                    'qurbani_delivery_type'    => $li->qurbani_delivery_type,
                    'qurbani_type'             => $li->qurbani_type,
                    'qurbani_paya'             => $li->qurbani_paya,
                    'qurbani_item_status'      => $li->qurbani_item_status,
                    'qurbani_delivery_priority'=> $li->qurbani_delivery_priority !== null
                        ? (int) $li->qurbani_delivery_priority : null,
                ],
                'events'         => $events,
                'rider'          => $rider,
                'dispatch'       => $dispatch,
                'current_eta'    => $currentEta,
                'slot_compare'   => $slotCompare,
                'route_position' => $routePosition,
                'delay_alert'    => $delayAlert,
                'whatsapp_today' => $whatsappToday,
            ]);
        } catch (\Exception $e) {
            \Log::error('Failed to load qurbani order timeline', [
                'line_item_id' => $lineItemId,
                'error' => $e->getMessage(),
            ]);
            return response()->json(['success' => false, 'message' => $e->getMessage()], 500);
        }
    }

    /**
     * POST /rider/qurbani/riders/{riderId}/lock-route
     * Locks the qurbani-mode route for this rider so other users can't
     * resequence. Coexists with regular-orders lock via mode='qurbani'.
     */
    public function lockQurbaniRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }

            $existing = \DB::table('t_crm_route_lock')
                ->where('rider_id', $riderId)
                ->where('mode', 'qurbani')
                ->first();
            if ($existing) {
                if ($existing->locked_by == $user->id) {
                    return response()->json(['success' => true, 'message' => 'Route already locked by you']);
                }
                $lockerName = \DB::table('t_sys_user')->where('id', $existing->locked_by)->value('fullname');
                return response()->json([
                    'success' => false,
                    'message' => "Route is already locked by {$lockerName}",
                    'locked_by_name' => $lockerName,
                ], 409);
            }

            \DB::table('t_crm_route_lock')->insert([
                'rider_id' => $riderId,
                'locked_by' => $user->id,
                'locked_at' => now(),
                'mode' => 'qurbani',
            ]);

            return response()->json([
                'success' => true,
                'message' => 'Route locked',
                'route_lock' => [
                    'locked_by' => $user->id,
                    'locked_by_name' => $user->fullname,
                    'locked_at' => now()->toIso8601String(),
                ],
            ]);
        } catch (\Exception $e) {
            \Log::error('Qurbani lock route error: ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Failed to lock route'], 500);
        }
    }

    /**
     * DELETE /rider/qurbani/riders/{riderId}/lock-route
     * Unlocks the qurbani-mode route. Anyone with qurbani-mode
     * permission can unlock — matches the regular-orders behaviour.
     */
    public function unlockQurbaniRoute(Request $request, $riderId)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }
            \DB::table('t_crm_route_lock')
                ->where('rider_id', $riderId)
                ->where('mode', 'qurbani')
                ->delete();
            return response()->json(['success' => true, 'message' => 'Route unlocked']);
        } catch (\Exception $e) {
            \Log::error('Qurbani unlock route error: ' . $e->getMessage());
            return response()->json(['success' => false, 'message' => 'Failed to unlock route'], 500);
        }
    }

    /**
     * GET /api/qurbani/riders/{riderId}/delay-impacted (May-2026)
     *
     * Returns the list of stops on this rider's route where the
     * current Google ETA has drifted from the last ETA we messaged
     * the customer about by more than `qurbani_wa_ofd_delay_threshold_minutes`
     * (default 30). Used by the mobile manager view to render the
     * "Send updated times" banner above the action bar.
     *
     * Manager-only (qurbani mode permission). The actual rider's own
     * mobile screen does NOT call this endpoint — the user wanted
     * the delay-update decision to stay with the manager.
     *
     * Returns:
     *   {
     *     success: true,
     *     impacted: [ { line_item_id, customer_name, order_number,
     *                   messaged_eta_at, current_eta_at, delta_minutes,
     *                   in_cooldown }, ... ],
     *     threshold_minutes: 30,
     *     cooldown_minutes:  15,
     *     total_impacted: int   // count NOT in cooldown
     *   }
     */
    public function getQurbaniDelayImpacted(Request $request, $riderId, \App\Services\QurbaniWaAutoSender $waSender)
    {
        try {
            $user = Auth::user();
            // Manager-only — the decision to nudge customers with a new
            // ETA is operational, not the rider's call to make.
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }
            $impacted = $waSender->findDelayImpactedStops((int) $riderId);
            $threshold = (int) \App\Models\FIN\ConfigModel::get('qurbani_wa_ofd_delay_threshold_minutes', '30');
            $cooldown  = (int) \App\Models\FIN\ConfigModel::get('qurbani_wa_ofd_delay_resend_cooldown_minutes', '15');
            // Total = count of stops eligible to send right now (not in
            // cooldown). The mobile UI uses this to decide whether the
            // banner should be enabled or muted.
            $eligible = array_filter($impacted, fn($r) => !$r->in_cooldown);

            return response()->json([
                'success'           => true,
                'impacted'          => array_map(function ($r) {
                    return [
                        'line_item_id'    => $r->line_item_id,
                        'order_id'        => $r->order_id,
                        'order_number'    => $r->order_number,
                        'customer_name'   => $r->customer_name,
                        'messaged_eta_at' => $r->messaged_eta_at,
                        'current_eta_at'  => $r->current_eta_at,
                        'delta_minutes'   => $r->delta_minutes,
                        'in_cooldown'     => $r->in_cooldown,
                        'last_trigger_event' => $r->last_trigger_event,
                    ];
                }, $impacted),
                'threshold_minutes' => $threshold,
                'cooldown_minutes'  => $cooldown,
                'total_impacted'    => count($impacted),
                'total_eligible'    => count($eligible),
            ]);
        } catch (\Throwable $e) {
            \Log::error('getQurbaniDelayImpacted failed', ['rider_id' => $riderId, 'err' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to compute delay-impacted stops'], 500);
        }
    }

    /**
     * POST /api/qurbani/riders/{riderId}/send-delay-update (May-2026)
     *
     * Manager-triggered re-send of the OFD delivery template (with the
     * new rounded-range ETA) for stops impacted by route delays.
     *
     * Body (optional):
     *   { line_item_ids: [int, ...] }    // limit to specific stops
     * Omit `line_item_ids` to send to every currently-impacted stop.
     *
     * Cooldown (default 15 min/stop) is enforced server-side regardless
     * of whether the client passes a whitelist — a misbehaving UI can
     * never trigger duplicate sends.
     *
     * Returns: { success, sent, skipped, failed, reasons[] }
     */
    public function sendQurbaniDelayUpdate(Request $request, $riderId, \App\Services\QurbaniWaAutoSender $waSender)
    {
        try {
            $user = Auth::user();
            if (!$user->hasMobilePermission('access_qurbani_mode')) {
                return response()->json(['success' => false, 'message' => 'Permission denied'], 403);
            }
            $validated = $request->validate([
                'line_item_ids'   => 'nullable|array',
                'line_item_ids.*' => 'integer',
            ]);
            $whitelist = $validated['line_item_ids'] ?? null;

            $result = $waSender->sendDelayUpdate((int) $riderId, $whitelist);

            \Log::info('Qurbani delay-update sent', [
                'rider_id'   => $riderId,
                'manager_id' => $user->id,
                'whitelist'  => $whitelist,
                'result'     => $result,
            ]);

            $msg = $result['sent'] . ' sent';
            if (($result['skipped'] ?? 0) > 0) $msg .= ', ' . $result['skipped'] . ' skipped';
            if (($result['failed'] ?? 0) > 0)  $msg .= ', ' . $result['failed'] . ' failed';

            return response()->json([
                'success' => true,
                'message' => $msg,
                'result'  => $result,
            ]);
        } catch (\Illuminate\Validation\ValidationException $e) {
            return response()->json(['success' => false, 'message' => 'Validation failed', 'errors' => $e->errors()], 422);
        } catch (\Throwable $e) {
            \Log::error('sendQurbaniDelayUpdate failed', ['rider_id' => $riderId, 'err' => $e->getMessage()]);
            return response()->json(['success' => false, 'message' => 'Failed to send delay updates: ' . $e->getMessage()], 500);
        }
    }

    // ===================== Shift management (mobile Store → Shifts) =====================

    /** Shift types for the mobile picker (gated by manage_shifts). Reuses the web endpoint. */
    public function getShiftTemplatesMobile(Request $request)
    {
        if (!Auth::user()->hasMobilePermission('manage_shifts')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to manage shifts'], 403);
        }
        // ⚠ Stamp the source BEFORE delegating: `list()` asks the authority service which
        //   permission half to read, and it reads that from this very attribute.
        $request->attributes->set('shift_log_source', 'mobile');
        return app(\App\Http\Controllers\Ops\ShiftController::class)->list($request);
    }

    /**
     * ⏳ SHIFT CHANGE APPROVALS on the phone (Sep-2026). Three thin wrappers over the same
     * controller the desk uses, so "who may answer this" cannot differ between them.
     *
     * ⚠ NOT gated by `manage_shifts` here: the queue is answered by LADDER POSITION, and the
     *   service returns an empty list to anyone with nothing to answer. Gating on the
     *   permission would be both redundant and wrong — the ladder is the finer rule.
     */
    public function shiftApprovalsMobile(Request $request)
    {
        $request->attributes->set('shift_mobile', true);
        return app(\App\Http\Controllers\Ops\ShiftRulesController::class)->approvals($request);
    }

    public function approveShiftRequestMobile(Request $request, $id)
    {
        $request->attributes->set('shift_mobile', true);
        return app(\App\Http\Controllers\Ops\ShiftRulesController::class)->approve($request, $id);
    }

    public function declineShiftRequestMobile(Request $request, $id)
    {
        $request->attributes->set('shift_mobile', true);
        return app(\App\Http\Controllers\Ops\ShiftRulesController::class)->decline($request, $id);
    }

    /** Delivery riders + current shift + active/upcoming changes (StoreShiftsScreen data). */
    /**
     * 👥 USERS LIST (mobile) — every active account with whether it is on the one roster
     * that the Shift Planner and Attendance share. The phone half of the web planner's
     * "Users list" button.
     *
     * 🔒 Owner ruling 9-Sep-2026: *"this list is only for shabib abd taimur to modify"*.
     *    Gate is `manage_user_roster`, NOT `manage_shifts` — a planner who may move shifts
     *    still may not change who exists on the list.
     */
    public function shiftUsersListMobile(Request $request)
    {
        $me = $request->user() ?: Auth::user();
        if (!app(\App\Services\Ops\ShiftAuthorityService::class)->canManageRoster($me, true)) {
            return response()->json([
                'success' => false,
                'message' => 'Only Shabib and Taimur can open the users list.',
            ], 403);
        }

        return response()->json([
            'success' => true,
            'users' => app(\App\Services\Ops\UserRosterService::class)->list(),
