    /**
     * 👥 Put someone on the users list, or take them off — the phone half.
     *
     * ⚠ Goes through the SAME writer as the web (`UserRosterService::set`), so one toggle
     *   moves the person on both the Shift Planner and Attendance, exactly as on the desk.
     */
    public function toggleShiftUserMobile(Request $request)
    {
        $me = $request->user() ?: Auth::user();
        if (!app(\App\Services\Ops\ShiftAuthorityService::class)->canManageRoster($me, true)) {
            return response()->json([
                'success' => false,
                'message' => 'Only Shabib and Taimur can change who is on the users list.',
            ], 403);
        }

        $data = $request->validate([
            'user_id' => 'required|integer|exists:t_sys_user,id',
            'on_list' => 'required|boolean',
        ]);

        $roster = app(\App\Services\Ops\UserRosterService::class);
        $onList = (bool) $data['on_list'];
        $warning = $onList ? null : $roster->removalWarning((int) $data['user_id']);
        $roster->set((int) $data['user_id'], $onList, $me ? (int) $me->id : null);

        return response()->json([
            'success' => true,
            'message' => $onList ? 'Added to the users list' : 'Removed from the users list',
            'warning' => $warning,
        ]);
    }

    public function getStoreShiftRiders(Request $request)
    {
        if (!Auth::user()->hasMobilePermission('manage_shifts')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to manage shifts'], 403);
        }
        $svc = new \App\Services\ShiftResolutionService();
        /**
         * 🔒 SHIFT AUTHORITY (Sep-2026) — resolved ONCE for the whole list, then asked per
         * rider below. ⚠ `true` = the mobile permission half, so the phone and the desk read
         * the same key from the right side.
         */
        $shiftActor = $request->user() ?: Auth::user();
        $shiftAuthority = app(\App\Services\Ops\ShiftAuthorityService::class);
        $shiftOpenRequests = app(\App\Services\Ops\ShiftChangeRequestService::class)->openByUser();
        $today = now()->format('Y-m-d');
        /**
         * 👥 ONE COMMON LIST (owner ruling Sep-2026) — *"we should have one common list
         * which is the attendance"*. This used to INNER JOIN the rider profile on
         * `p.active = 1`, so the phone showed ONLY ticked delivery riders while the web
         * grid could show all staff: Shabib had 12 real shift rows and no row on mobile,
         * and Taimur (exempt, hidden from attendance) was listed on both.
         *
         * The roster is now shared with the web planner through ONE helper so the two
         * cannot drift apart again. The rider join stays a LEFT join purely to carry the
         * phone + the `is_rider` flag for the app's Riders/All chip.
         *
         * ⚠ Additive for an older APK: it simply renders the longer list (and its writes
         *   are still judged by the same ladder gate). Nothing is removed from the payload.
         */
        $roster = \App\Models\User::shiftPlannerRoster();
        $rosterOffList = array_flip($roster['off_roster']);
        $riders = \DB::table('t_sys_user as u')
            ->leftJoin('t_ops_rider_profile as p', 'p.user_id', '=', 'u.id')
            ->where('u.is_active', 1)
            ->whereIn('u.id', $roster['ids'] ?: [0])
            ->orderBy('u.fullname')
            ->get(['u.id', 'u.fullname', 'p.phone', \DB::raw('COALESCE(p.active, 0) as is_rider')]);

        // 🔧 Next workshop errand per rider — ONE query for the whole list, never per row.
        // Guarded: before workshop_visits_sep2026.sql this is simply empty.
        $workshopByUser = [];
        try {
            $wv = app(\App\Services\Riders\WorkshopVisitService::class);
            foreach ($wv->listVisits(['from' => $today, 'limit' => 200]) as $v) {
                // listVisits is ordered by date, so the FIRST one per rider is his next.
                if (!isset($workshopByUser[$v['user_id']])) {
                    $workshopByUser[$v['user_id']] = [
                        'id' => $v['id'], 'visit_date' => $v['visit_date'], 'visit_time' => $v['visit_time'],
                        'vehicle_name' => $v['vehicle_name'], 'workshop' => $v['workshop'],
                        'accepted' => $v['accepted'], 'accepted_on_behalf' => $v['accepted_on_behalf'],
                    ];
                }
            }
        } catch (\Throwable $e) { /* not deployed → no visits */ }

        $out = [];
        foreach ($riders as $r) {
            $primary = $svc->getUserShift($r->id, $today);
            $rows = \App\Models\Ops\UserShiftAssignmentModel::with('shiftTemplate')->where('user_id', $r->id)->get();
            $changes = [];
            foreach ($rows as $row) {
                $f = $row->effective_from ? $row->effective_from->format('Y-m-d') : null;
                $t = $row->effective_to ? $row->effective_to->format('Y-m-d') : null;
                if ($t !== null && $t >= $today) {
                    $changes[] = ['assignment_id' => $row->id, 'kind' => 'temporary', 'shift_name' => optional($row->shiftTemplate)->shift_name, 'from' => $f, 'to' => $t, 'acknowledged' => $row->acknowledged_at !== null];
                } elseif ($t === null && $f !== null && $f > $today) {
                    $changes[] = ['assignment_id' => $row->id, 'kind' => 'upcoming_primary', 'shift_name' => optional($row->shiftTemplate)->shift_name, 'from' => $f, 'to' => null, 'acknowledged' => $row->acknowledged_at !== null];
                }
            }
            $def = $svc->userDefaultLocation($r->id); // rider's default office (pre-selected on assign)
            $shiftAuth = $shiftAuthority->rowStateFor($shiftActor, (int) $r->id, true);
            $out[] = ['user_id' => $r->id, 'name' => $r->fullname,
                // 👥 Roster flags (Sep-2026): drives the app's Riders/All chip, and the
                //    "not in attendance" tag on a row only the safety net is keeping.
                'is_rider' => (int) ($r->is_rider ?? 0) === 1,
                'off_roster' => isset($rosterOffList[(int) $r->id]),
                'has_phone' => !empty(trim((string) $r->phone)),
                'default_location_id' => $def['location_id'],
                'default_location_name' => $def['location_name'],
                'primary' => ['shift_name' => $primary['shift_name'], 'start' => $primary['shift_start'], 'end' => $primary['shift_end'], 'location_name' => $primary['location_name'] ?? null],
                /**
                 * 🔧 His next workshop errand (owner ask, Sep-2026): "whoever is planning
                 * the shift should know that on this date the rider has to go".
                 *
                 * ⚠ The web planner is a 7-day GRID and paints this on the day cell; this
                 *   screen is a rider LIST, so the honest equivalent is his next one. It
                 *   changes nothing about the shift — a workshop day is a normal paid
                 *   working day (owner ruling) — it is here so the planner can set that
                 *   day's times around the appointment.
                 * ⚠ Additive: an older app ignores the key.
                 */
                'workshop' => $workshopByUser[(int) $r->id] ?? null,
                /**
                 * 🔒 SHIFT AUTHORITY (Sep-2026) — the same three answers the web grid gets,
                 * so the phone offers exactly what the server will accept.
                 * ⚠ Additive: an older APK ignores these keys and simply shows the old UI;
                 *   its writes are still refused by the gate, with a message it can display.
                 */
                'can_change' => $shiftAuth['can'],
                'lock_reason' => $shiftAuth['reason'],
                'needs_approval' => $shiftAuth['needs_approval'],
                'allowed_template_ids' => $shiftAuthority->allowedTemplateIdsFor($shiftActor, (int) $r->id),
                'pending_requests' => $shiftOpenRequests[(int) $r->id] ?? [],
                'changes' => $changes];
        }
        // 👥 Does this phone get the "Users list" button? (Shabib + Taimur only.)
        $canManageRoster = $shiftAuthority->canManageRoster($shiftActor, true);

        // Active office locations (for the assign screen's location bubbles).
        // ⚠ Van meet-up points live in this table too and are NOT offices — a
        //   rendezvous must never be assignable as somebody's work location.
        $locations = \DB::table('t_ops_company_locations')->where('is_active', 1)
            ->when(\App\Services\LocationService::hasHandoverPointColumn(), fn ($q) => $q->where(function ($w) {
                $w->where('is_handover_point', 0)->orWhereNull('is_handover_point');
            }))
            ->orderByDesc('is_primary')->orderBy('location_name')
            ->get(['id', 'location_name', 'is_primary'])
            ->map(fn($l) => ['id' => (int) $l->id, 'name' => $l->location_name, 'is_primary' => (int) $l->is_primary === 1]);
        // ⚠ `can_manage_roster` is additive — an older APK ignores it and shows no button.
        return response()->json(['success' => true, 'riders' => $out, 'locations' => $locations,
            'can_manage_roster' => $canManageRoster]);
    }

    /** Per-rider MONTH shift breakdown for the manager (StoreShifts → tap rider → month view),
     *  so they can SEE what shift each day was set to before correcting history. Each day carries
     *  the resolved shift + off/holiday/override flags + the frozen snapshot lateness (the signal
     *  for "this day's shift may be wrong"). Read-only, gated by manage_shifts. Mirrors the web
     *  Shift Planner's per-day cell logic, for a full month. */
    public function getRiderShiftMonth(Request $request)
    {
        if (!Auth::user()->hasMobilePermission('manage_shifts')) {
            return response()->json(['success' => false, 'message' => 'You do not have permission to manage shifts'], 403);
        }
        $v = \Validator::make($request->all(), [
            'user_id' => 'required|integer|exists:t_sys_user,id',
            'month' => 'nullable|date_format:Y-m',
        ]);
        if ($v->fails()) {
            return response()->json(['success' => false, 'message' => $v->errors()->first()], 422);
        }

        $uid = (int) $request->user_id;
        $month = $request->input('month') ?: now()->format('Y-m');
        $start = \Carbon\Carbon::parse($month . '-01')->startOfMonth();
        $end = $start->copy()->endOfMonth();
        $startStr = $start->format('Y-m-d');
        $endStr = $end->format('Y-m-d');
        $today = now()->format('Y-m-d');
        $svc = new \App\Services\ShiftResolutionService();

        // Preload once: assignment rows, holidays, attendance (for late) across the month.
        $rows = \App\Models\Ops\UserShiftAssignmentModel::with('shiftTemplate')->where('user_id', $uid)->get();
        $holidays = \DB::table('t_ops_public_holidays')->where('is_active', 1)
            ->whereBetween('holiday_date', [$startStr, $endStr])->get()
            ->mapWithKeys(fn($h) => [\Carbon\Carbon::parse($h->holiday_date)->format('Y-m-d') => $h->holiday_name])
            ->all();
        $att = \DB::table('t_ops_attendance')->where('user_id', $uid)
            ->whereBetween('attendance_date', [$startStr, $endStr])
            ->get(['attendance_date', 'login_time', 'logout_time', 'late_minutes'])
            ->keyBy(fn($a) => substr((string) $a->attendance_date, 0, 10));

        // "Not needed" day tags for the month (guarded — table may not be deployed yet).
        $dayTags = [];
        try {
            if (\Illuminate\Support\Facades\Schema::hasTable('t_ops_day_tag')) {
                foreach (\DB::table('t_ops_day_tag')->where('user_id', $uid)
                    ->whereBetween('tag_date', [$startStr, $endStr])->get(['tag_date']) as $t) {
                    $dayTags[\Carbon\Carbon::parse($t->tag_date)->format('Y-m-d')] = true;
                }
            }
        } catch (\Throwable $e) { /* no tags */ }

        $days = [];
        for ($d = $start->copy(); $d->lte($end); $d->addDay()) {
            $ds = $d->format('Y-m-d');
            $shift = $svc->getUserShift($uid, $ds);
            $dow = (int) $d->format('N'); // 1=Mon..7=Sun
            $isHoliday = isset($holidays[$ds]);
            $isOff = !in_array($dow, $shift['working_days'] ?? []);
            // A bounded row (effective_to set) covering this date = temporary override.
            $isOverride = $rows->first(function ($row) use ($ds) {
                if (is_null($row->effective_to)) {
                    return false;
                }
                $f = $row->effective_from ? $row->effective_from->format('Y-m-d') : null;
                $t = $row->effective_to->format('Y-m-d');
                return ($f === null || $f <= $ds) && ($t >= $ds);
            }) !== null;

            $a = $att[$ds] ?? null;
            $loggedIn = $a && !empty($a->login_time);
            $late = ($loggedIn && !is_null($a->late_minutes)) ? (int) $a->late_minutes : null;

            $days[] = [
                'date' => $ds,
                'dow' => $d->format('D'),
                'day' => (int) $d->format('j'),
                'shift_name' => $shift['shift_name'],
                'start' => $shift['shift_start'],
                'end' => $shift['shift_end'],
                'is_off' => $isOff,
                'is_holiday' => $isHoliday,
                'holiday_name' => $isHoliday ? $holidays[$ds] : null,
                'is_override' => $isOverride,
                // "Not needed" only matters on a would-be WORKING day (off/holiday win).
                'is_not_needed' => (isset($dayTags[$ds]) && !$isOff && !$isHoliday),
                'is_today' => $ds === $today,
                'is_future' => $ds > $today,
                'logged_in' => $loggedIn,
                'late_minutes' => $late,
            ];
        }

        return response()->json([
            'success' => true,
            'user_id' => $uid,
            'name' => \DB::table('t_sys_user')->where('id', $uid)->value('fullname'),
            'month' => $month,
            'days' => $days,
        ]);
    }

